import scala.collection.mutable

object Main {

  case class Edge(v: Int, w: Long)

  def main(args: Array[String]): Unit = {
    val sc = new java.util.Scanner(System.in)
    val INF = Long.MaxValue
    val V = sc.nextInt()
    val G = Array.fill(V + 1)(List[Edge]())
    (0 until V - 1) foreach { _ =>
      val u, v, w = sc.nextInt()
      G(u) ::= Edge(v, w)
      G(v) ::= Edge(u, w)
    }
    val Q, K = sc.nextInt()
    val X, Y = new Array[Int](Q)
    (0 until Q) foreach { i =>
      val x, y = sc.nextInt()
      X(i) = x
      Y(i) = y
    }

    // j番目の質問クエリ、頂点xjから頂点Kを経由しつつ、頂点yjまで
    // 移動する場合の最短経路の距離を求めてください
    // ...つまり, xjからKへの最短距離, Kからyjへの最短距離の和を答えればそれが最短経路となる
    // 木に対する全点対最短路問題を事前に解いておき, クエリへ回答する
    // 木かつ ci >= 1 なので, ダイクストラ法によって全点対最短路を求めることができる.

    def dijkstra(s: Int, V: Int, E: Int, G: Array[List[Edge]]): Array[Long] = {
      val d = Array.fill[Long](V+1)(INF)
      val queue = mutable.PriorityQueue[(Long, Int)]()(Ordering.by(_._1))
      d(s) = 0L
      queue.enqueue((0L, s))

      def loop(): Unit =
        if (queue.nonEmpty) {
          val (ud, u) = queue.dequeue()
          if (d(u) < ud) loop()
          else {
            d(u) = ud
            G(u) foreach { edge =>
              if (d(edge.v) > d(u) + edge.w) {
                d(edge.v) = d(u) + edge.w
                queue.enqueue((d(edge.v), edge.v))
              }
            }
            loop()
          }
        }
      loop()
      d
    }

    val d: Array[Array[Long]] =
      Array.tabulate(V)(s => dijkstra(s + 1, V, V - 1, G))

    val r = (0 until Q).map { i =>
      d(X(i)-1)(K) + d(K-1)(Y(i))
    }. mkString("\n")

    println(r)
  }

}

import java.io._
import java.util.StringTokenizer

object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val N = in.next().toInt
  // (node, cost)
  val graph: Array[List[(Int, Int)]] = Array.fill(N+1)(Nil)
  for(_ <- 1 to N-1) {
    val a, b, cost = in.next().toInt
    graph(a) = (b, cost) :: graph(a)
    graph(b) = (a, cost) :: graph(b)
  }

  val Q, K = in.next().toInt

  // dfs
  val stack = new scala.collection.mutable.Stack[(Int, Long)] // (nowNode, cost)
  stack.push((K, 0))

  val dp = new Array[Long](N+1)
  dp(K) = 2

  while (!stack.isEmpty) {
    val (now, accCost) = stack.pop
    for((node, cost) <- graph(now)) {
      if(dp(node) == 0) {
        dp(node) = accCost + cost
        stack.push((node, accCost + cost))
      }
    }
  }

  for (_ <- 1 to Q) {
    val x, y = in.next().toInt
    val ans: Long = dp(x) + dp(y)
    pw.println(ans)
  }
  pw.flush()

}


