const int N=4e5+20;
typedef long long ll; 
typedef pair<ll,ll> ii;

int n,q,vis[N],num;
ll dis[N];//¸ùµ½½áµãµÄ¾àÀë 
ll dep[N];//µÚi´Î·ÃÎÊµÄ½áµãÉî¶È
ll vs[N];//vs[i] dfsµÚi´Î·ÃÎÊµ½µÄ½áµã
ll pos[N];//pos[v] ½áµãvµÚÒ»´Î±»·ÃÎÊµ½µÄÎ»ÖÃ 
vector<ii> e[N];
ll d[N][30];//d[i][j] ÐòºÅi~2^jµÄ×îÐ¡depÐòºÅ 
void init()
{
	for(int i=0;i<=n;i++)
	e[i].clear();

	num=0;
	memset(dis,0,sizeof(dis));
	memset(vis,0,sizeof(vis));
	memset(pos,-1,sizeof(pos));
}
void dfs(int u,int depth)
{
	vs[++num]=u;
	dep[num]=depth;
	if(pos[u]==-1)
	pos[u]=num;

	vis[u]=1;
	for(int i=0;i<e[u].size();i++)
	{
		int v=e[u][i].first;
		int w=e[u][i].second;
		if(vis[v])
		continue;

		dis[v]=dis[u]+w;
		dfs(v,depth+1);

		//¼ÇÂ¼Â·¾¶
		vs[++num]=u;
		dep[num]=depth;

	}
}
void RMQ(ll len)//Çó(u,v)Â·¾¶ÖÐÉî¶È×îÐ¡µÄ½áµãµÄ·ÃÎÊÐòºÅ¼´LCA(u,v) 
{
	for(int i=0;i<=len;i++)
	d[i][0]=i;

	for(int j=1;(1<<j)<=len;j++)
	{
		for(int i=1;i+(1<<j)<=len;i++)
		{
			int x=d[i][j-1],y=d[i+(1<<(j-1))][j-1];
			if(dep[x]<=dep[y])
			d[i][j]=x;
			else
			d[i][j]=y;	
		} 
	}
}
ll LCA(ll x,ll y)
{
	int a=pos[x],b=pos[y];
	if(a>b)
	swap(a,b);

	//·ÃÎÊÐòºÅ(a,b)ÖÐÉî¶È×îÐ¡µÄµã¼´ÎªLCA(x,y)
	int k=0;
	while((1<<k+1)<=b-a+1) k++;

	int l=d[a][k],r=d[b-(1<<k)+1][k];
	if(dep[l]<dep[r])
	return vs[l];
	else
	return vs[r]; 
}
ll query(int u,int v)
{
	return dis[u]+dis[v]-2*dis[LCA(u,v)];
}
