arr<T> modpowmat(arr<T> &a, ll n){
    int s = a.size();
    arr<T> b(s, vector<T>(s, 0));
    rep(i, s) b[i][i] = 1;

    while(n>0){
        if(n&1) {
            arr<T> c(s, vector<T>(s, 0));
            rep(i, s) rep(j, s) rep(k, s) c[i][j] += a[i][k] * b[k][j];
            b = c;
        }
        arr<T> c(s, vector<T>(s, 0));
        rep(i, s) rep(j, s) rep(k, s) c[i][j] += a[i][k] * a[k][j];
        a = c;
        n >>= 1;
    }
    return b;
}

