    int N,Q,K;
    cin >> N;
    for(int i = 0;i < N-1;i++){
        int a,b,c;
        cin >> a >> b >> c;
        addEdge(a-1,b-1,c,node);
    }
    cin >> Q >> K;
    dijkstra(N,K-1,N-1,node);
    for(int i = 0;i < Q;i++){
        int a,b;
        cin >> a >> b;
        cout << node[a-1].minCost + node[b-1].minCost << endl;
    }
}

