void Init()
{
    memset(pre,-1,sizeof(pre));
    LL Index = 1;
    LL i,j,flag;
    LL x,y,w;
    for(i=0;i<m;i++)
    {
        x=Scan();y=Scan();w=Scan();
        for(flag=0,j=pre[x];j!=-1;j=edge[j].next)
        {//重边的情况
            if(y == edge[j].v)
            {
                if(w < edge[j].w)
                    edge[j].w = w;
                flag = 1;
                break;
            }
        }
        if(flag == 1)
            continue;
        edge[Index].v = y;
        edge[Index].w = w;
        edge[Index].next = pre[x];  //保存x起点的上一条边在edge数组中的位置
        pre[x] = Index++;  //位置更新
        swap(x,y);
        edge[Index].v = y;
        edge[Index].w = w;
        edge[Index].next = pre[x];
        pre[x] = Index++;
    }
}

void SPFA()
{
    LL q,k;
