//----UnionFind-----

class UnionFind{
    public:
    vll par;
    vll rank;//rankが高いほど上の親である
    UnionFind(LL N):par(N),rank(N){
        REP(i,N)par[i] = i;
        REP(i,N)rank[i] = 0;
    }
    ~UnionFind(){}
    LL root(LL x){
        if(par[x] ==x)return x;
        else {
            par[x] = root(par[x]);
            return par[x];
        }
    }
    void unite(LL x, LL y){
        LL rx = root(x);
        LL ry = root(y);
        if(rx == ry)return;
        if(rank[rx] < rank[ry]){
            par[rx] = ry;//rankの高い方を親にする
        }else{
            par[ry] = rx;
            if(rank[rx] == rank[ry]){
                //rankがどちらも同じ時、どちらか好きな方を親にしてそのrankを1上げる
                rank[rx]++;
            }
        }

    }
    bool same(LL x, LL y){
        LL rx = root(x);
        LL ry = root(y);
        return rx == ry;
    }
};


//--------BFS---------


class BFS_shortestDistance{
    public:
    BFS_shortestDistance(vector<vector <char> > p_ , ll h_ , ll w_){
        p = p_;
        h=h_;
        w=w_;
        initial_number = h*w*2;
        REP(i,h){
            vector <LL> k(w);
            REP(t,w)k[t] =  initial_number;
            field.push_back(k);
        }
    }
    vector<vector <char> > p;

    ll h;
    ll w;
    ll initial_number;//初期化用数値

    vector< vector<LL> >field;  //この変数に書き込む


    pair<LL , LL > plus(pair<LL , LL> &a, pair<LL , LL > &b){
        pair<LL , LL> p;
        p.first = a.first + b.first;
        p.second = a.second + b.second;
        return p;
    }
    bool equal(pair<LL , LL> &a, pair<LL , LL > &b){
        return (a.first == b.first && a.second == b.second);
    }
    bool is_in_field(int h, int w, const pair<LL , LL> &point)
    {
        const int c = point.second;
        const int r = point.first;
        return (0 <= c && c < w) && (0 <= r && r < h); 
    }

    // fieldの中身を初期化
    //最短距離がh*w*2になることはないのでこれで初期化する
    void init(){
        REP(i,field.size()){
            REP(t,field[i].size()){
                field[i][t] = initial_number;
            }
        }
    }

    // sy , sx はスタート位置の 『INDEX』!! 
    // syが縦　sx が横
    void shortest(ll sy,ll sx){
        //初期化
        init();

        pair <LL , LL> c[4];
        c[0].first = 0;
        c[0].second = 1;
        c[1].first = 0;
        c[1].second = -1;
        c[2].first = 1;
        c[2].second = 0;
        c[3].first = -1;
        c[3].second = 0;
        queue <pair<LL ,LL> >Q;
        pair<LL , LL> s;
        s.first = sy;
        s.second = sx;
        field[sy][sx] = 0;//スタート位置のみ0で初期化

        Q.push(s);
        while(Q.empty() == false){
            pair <LL , LL> now = Q.front();
            Q.pop();        

            for(int u = 0; u < 4 ; u++){
                pair<LL , LL > x = c[u];
                pair<LL , LL> next = plus(now , x);
                if(is_in_field(h,w,next)){
                    if(p[next.first][next.second] == '.'){
                        //まだ到達してない　＝＝　field の値が initial_number　
                        if(field[next.first][next.second] == initial_number){
                            field[next.first][next.second] = field[now.first][now.second] + 1;
                            Q.push(next);
                        }else{
                            //すでに到達済みである＝＝これ以前にQueueから出てきたpairがすでに
                            //到達している＝＝すでにfieldの値が最小値であることは明らか;
                        }
                    }
                }
            }
        }
    }


};






//-----------MAIN------------//

ll solve(vector<vll> &dp , vector<vll> node , ll start , ll goal , ll before){
    if (dp[start][goal]!=-1)return dp[start][goal];
    vll ans(node[start].size() , 0);
    REP(i,node[start].size()){
        ll next = node[start][i];
        if(next!=before && start != before){
            ans[0] += dp[start][next];
            //cout << "Here : " << ans[0] << endl;
            ans[0] += solve(dp , node , next , goal , start);
            ans[1] = 1000000000000;
            break;
        }
        else if(start == before){    
            ans[i] += dp[start][next];
            //cout << "Here : " << ans[i] << endl;
            ans[i] += solve(dp , node , next , goal , start);
        }
        else if(i==node[start].size()-1 && start != before )return 1000000000000;

    }
    dp[start][goal] = MIN(ans).first;
    return dp[start][goal];
}



