      vi(p.second);
   }
   time_out[u] = ++time_cnt;
}
inline bool is_parent(int p, int c)
{
   auto ret = time_in[p] <= time_in[c] && time_out[c] <= time_out[p];
   return ret;
}

//cost, node
pair<int64_t, int> lca(int u, int v) {
   if (depth[v] < depth[u])
      swap(u, v);
   //if (is_parent(u, v)) return u;

   int64_t mc = 0;// depth[u] <= depth[v]
   for (int j = si_log - 1; 0 <= j; --j) {
      const auto &z = lca_par[j][v];
      if (depth[u] <= depth[z]) {
         //mc = max(mc, lca_max_cost[j][v]);
         mc = max(mc, lca_cost[j][v]);
         v = z;
      }
   }
   if (u == v)
      return make_pair(mc, u);
   for (int j = si_log - 1; 0 <= j; --j) {
      const auto &q = lca_par[j][u];
      const auto &w = lca_par[j][v];
      if (q != w) {
         //mc = max({ mc, lca_max_cost[j][u], lca_max_cost[j][v] });
         mc = max({ mc, lca_cost[j][u], lca_cost[j][v] });
         u = q;
         v = w;
      }
   }
   //mc = max({ mc, lca_max_cost[0][u], lca_max_cost[0][v] });
   mc = max({ mc, lca_cost[0][u], lca_cost[0][v] });
   return make_pair(mc, lca_par[0][u]);
}
int lca_dist(int a, int b) {
   auto r = lca(a, b);
   int c = r.second;
   auto ret = depth[a] + depth[b] - 2 * depth[c];
   return ret;
}
int64_t cost_dist(int a, int b) {
   auto r = lca(a, b);
   int c = r.second;//a-c-b
   auto ret = lca_cost[0][a] + lca_cost[0][b] - 2 * lca_cost[0][c];
   return ret;
}
//a .. b .. c
bool is_path(int a, int b, int c) {
   const auto ac = lca_dist(a, c),
      ab = lca_dist(a, b),
      bc = lca_dist(b, c);
   auto ret = ac == (ab + bc);
   return ret;
}
