};

int dp[20][200001];
ll cost[200001];
ll depth[200001];

void dfs(int v, int p, vector<vector<Edge>> &G, ll c, int d) {
  cost[v] = c;
  depth[v] = d;
  for(int i = 0; i < G[v].size(); i++) {
    if (G[v][i].t == p) continue;
    dp[0][G[v][i].t] = v;
    dfs(G[v][i].t, v, G, c + G[v][i].cost, d + 1);
  }
}

int lca(int a, int b) {
  if (depth[a] < depth[b]) {
    int diff = depth[b] - depth[a];
    for(int i = 0; i < 20; i++) {
      if (diff >> i & 1) {
        b = dp[i][b];
      }
    }
  }
  if (depth[b] < depth[a]) {
    int diff = depth[a] - depth[b];
    for(int i = 0; i < 20; i++) {
      if (diff >> i & 1) {
        a = dp[i][a];
      }
    }
  }
  if (a == b) return a;

  for(int i = 19; i >= 0; i--) {
    if (dp[i][a] != dp[i][b]) {
      a = dp[i][a];
      b = dp[i][b];
    }
  }
  return dp[0][a];
}

