  dp[0][K] = K;
  dfs(K, -1, G, 0, 0);

  for(int i = 0; i < 19; i++) {
    for(int j = 0; j < N; j++) {
      dp[i + 1][j] = dp[i][dp[i][j]];
    }
  }

  for (int i = 0; i < Q; i++) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    // int c = lca(x, y);
    // cout << c << endl;
