void PrePar( ) {
    for(int i=1; i<=n; i++)P[0][i]=T[i];
    for(int i=1; 1<<i<=n ; i++) { ///Length
        for(int j=1; j<=n; j++) { /// Node ID
            if( P[i-1][j]==-1 )continue;
            Dis[i][j]= Dis[i-1][j]+ Dis[i-1][ P[i-1][j] ];
            P[i][j]= P[i-1][ P[i-1][j] ];
        }
    }
}

ll dis;
int Kth(int x,int k) {
    for(int i=18; i>=0; i--) {
        if( (1<<i) <=k ) {
            dis+=Dis[i][x];
            x=P[i][x];
            k-=(1<<i);
        }
    }
    return x;
}

int LCA(int x,int y) {
    if( L[x]<L[y] ) swap(x,y);
    int k=(L[x]-L[y]);
    x=Kth(x,k);
    if(x==y) return x;
    for(int i=18; i>=0; i--) {
        if( P[i][x]!=P[i][y] ) {
            dis+=Dis[i][x];
            dis+=Dis[i][y];
            x=P[i][x];
            y=P[i][y];
        }
    }
    dis+=Dis[0][x];
    dis+=Dis[0][y];
    return T[x];
}

