using PII = pair<int, int>;
using VPII = vector<PII>;
using VI = vector<int>;
using VVI = vector<VI>;
using Vll = vector<ll>;
using VVll = vector<Vll>;
using VC = vector<char>;
using VS = vector<string>;
using VB = vector<bool>;
const int INF = 1e9;
const ll MOD = 1e9 + 7;

void calc(auto &tree, auto &par, auto u, auto &dis, auto &visited)
{
  if (visited[u] == true) return;
  visited[u] = true;
  REPx(x, tree[u])
  {
    int v = x.first;
    if (visited[v] == true) continue;
    ll weight = x.second;
    par[v] = u;
    dis[v] = dis[u] + weight;
  }
  REPx(x, tree[u]) calc(tree, par, x.first, dis, visited);
}

void search(auto &reached, auto &u, auto &par)
{
  reached[u] = true;
  if (u == 0) return;
  search(reached, par[u], par);
}

int findpar(auto &N, auto &tree, auto &par, auto &a, auto b)
{
  VB reached(N, false);
  search(reached, a, par);
  while (true)
  {
    if (reached[b] == true) return b;
    b = par[b];
  }
}

int main()
{
  ll N;
  scanf("%lld", &N);
  vector<vector<pair<int, ll>>> tree(N, vector<pair<int, ll>>());
  REP(i, N-1)
  {
    int a, b;
