    scanf("%d%d%lld", &a, &b, &c);
    a--; b--;
    tree[a].push_back(pair<int, ll>(b, c));
    tree[b].push_back(pair<int, ll>(a, c));
  }
  VI par(N, 0);
  Vll dis(N, 0);
  VB visited(N, false);
  calc(tree, par, 0, dis, visited);
  int Q, K;
  scanf("%d%d", &Q, &K); K--;
  ll dis_K = dis[K];
  REP(i, Q)
  {
    int x, y;
    scanf("%d%d", &x, &y);
    x--; y--;
    int par1, par2;
    par1 = findpar(N, tree, par, x, K);
    par2 = findpar(N, tree, par, K, y);
    printf("%lld\n", dis[x] + dis_K - 2*dis[par1] + dis_K + dis[y] - 2*dis[par2]);
  }

  return 0;
}

