class Dijkstra {
  private:
    struct Graph {
        int to, cost;
    };
    int V;
    vector<vector<Graph>> G;
    const long long INF = 4'000'000'000'000'000'000;
    using P             = pair<long long, int>;
    vector<long long> dist;

  public:
    Dijkstra(int v) {
        V = v;
        G.resize(v);
        dist.resize(v, INF);
    }
    // 無向グラフの構築
    void undirected_update(int x, int y, int cost) {
        G[x].push_back({y, cost});
        G[y].push_back({x, cost});
    }
    // 有向グラフの構築
    void directed_update(int from, int to, int cost) {
        G[from].push_back({to, cost});
    }

    // ダイクストラの計算
    void calc(int start) {
        priority_queue<P, vector<P>, greater<P>> que;
        dist[start] = 0;
        que.push({0, start});

        while (!que.empty()) {
            auto p = que.top();
            que.pop();
            int v = p.second;
            if (dist[v] < p.first)
                continue;
            for (int i = 0; i < G[v].size(); i++) {
                auto e = G[v][i];
                if (dist[v] + e.cost < dist[e.to]) {
                    dist[e.to] = dist[v] + e.cost;
                    que.push({dist[e.to], e.to});
                }
            }
        }
    }

    // calc で渡した start からの最短経路を返す
    // 最短経路が存在しないとき -1 を返す
    long long path(int to) { return dist[to] != INF ? dist[to] : -1; }
};

