        dj.undirected_update(a, b, c);
    }
    int Q, K;
    cin >> Q >> K;
    dj.calc(K - 1);
    REP(i, Q) {
        int x, y;
        cin >> x >> y;
        ll ans = dj.path(x - 1) + dj.path(y - 1);
        std::cout << ans << '\n';
    }

    return 0;
}

