  init();
  ll q,K;
  cin>>q>>K;
  K--;
  while(q--){
    ll a,b;
    cin>>a>>b;
    a--,b--;
    cout<< Cal(a,K) + Cal(K,b) <<endl;
  }
  return 0;
}

