ll N;
vector<vector<pair<ll, ll>>> E;

vector<pair<ll, ll>> dfs(ll top)
{
  vector<pair<ll, ll>> par_dis(N, {INF, 0});//dis, par
  par_dis.at(top) = {0, 0};
  queue<ll> q;
  q.push({top});
  while (!q.empty())
  {
    ll check = q.front();
    q.pop();
    for (ll i = 0; i < E.at(check).size(); ++i)
    {
      pair<ll, ll> next = E.at(check).at(i);
      if (par_dis.at(next.first).first > par_dis.at(check).first + next.second)
      {
        q.push(next.first);
        ll par = par_dis.at(check).second;
        if (E.at(check).size() > 2 | (check == 0 && E.at(check).size() > 1))
        {
          par = check;
        }
        par_dis.at(next.first) = {par_dis.at(check).first + next.second, par};
      }
    }
  }
  return par_dis;
}

ll calc_dist(ll a, ll b, vector<pair<ll, ll>> par_dis)
{
  ll same_par;
  pair<ll, ll> a_par = par_dis.at(a), b_par = par_dis.at(b);
  while (true)
  {
    if (a_par.second == b_par.second)
    {
      break;
    }
    if (a_par.first > b_par.first)
    {
      a_par = par_dis.at(a_par.second);
    }
    else
    {
      b_par = par_dis.at(b_par.second);
    }
  }
  return par_dis.at(a).first + par_dis.at(b).first - 2 * par_dis.at(a_par.second).first;
}

