const ll INF = 1e18;

typedef pair<int, int> C;
typedef pair<ll, int> P;
map<P, ll> G;
vector<int> V[100001];
ll d[100001];

ll dijkstra(int s, int g) {
    priority_queue<P, vector<P>, greater<>> que;
    for (int i = 0; i < 100001; i++) d[i] = INF;
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (v == g) break;
        if (d[v] < p.first) continue;

        for (int i = 0; i < V[v].size(); i++) {
            int to = V[v][i];
            ll cost = G[C(v, to)];

            if (d[to] > d[v] + cost) {
                d[to] = d[v] + cost;
                que.push(P(d[to], to));
            }
        }
    }

    return d[g];
}

