        cin >> a >> b >> c;
        a--; b--;
        G[C(a, b)] = c;
        G[C(b, a)] = c;
        V[a].push_back(b);
        V[b].push_back(a);
    }

    int Q, K;
    cin >> Q >> K;
    K--;
    for (int i = 0; i < Q; i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        ll a = dijkstra(x, K);
        ll b = dijkstra(y, K);
