void lca(int a,int b){
    printf("%d %d\n",a,b);
    if(depth[a]<depth[b])swap(a,b);
    int dif=depth[a]-depth[b];
    for(int i=0;dif;i++){
        if(dif%2){
            ans+=dist[a][i];
            a=parent[a][i];
        }
        dif/=2;
    }
    if(a!=b){
        for(int i=49;i>=0;i--)
