#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long ll;
struct Node
{
    int v;
    ll cost;
};
static const int MAXN = 1e5 + 10;
static const ll OO = 1e15;
vector<Node> s[MAXN];
ll dis[MAXN];
void Init()
{
    for(int i = 0 ; i < MAXN ; ++i)
    {
        dis[i] = OO;
    }
}
struct cmp
{
    bool operator () (Node a , Node b)
    {
        return a.cost > b.cost; ///small top
    }
};

void Dijkstra(int st , int ed)
{
    priority_queue <Node , vector <Node> , cmp> qu;
    dis[st] = 0;
    Node ac;
    ac.v = st;
    ac.cost = 0;
    qu.push(ac);
    while(!qu.empty())
    {
        ac = qu.top();
        qu.pop();
        int u = ac.v;
        ll uc = ac.cost;
        if(dis[u] < uc)
        {
            continue;
        }
        int si = s[u].size();
        for(int i = 0 ; i < si ; ++i)
        {
            int v = s[u][i].v;
            ll co = s[u][i].cost;
            if(dis[v] > dis[u] + co)
            {
                Node temp;
                dis[v] = dis[u] + co;
                temp.v = v;
                temp.cost = dis[v];
                qu.push(temp);
            }
        }
    }
}
int main()
{
