int N, Q, K;
vector<vector<P>> root(100001);  //pair<辺の距離, 行先の頂点>
vector<ll> dist(100001, LLONG_MAX); //distance[i]はstartから頂点iへの最短距離が入る
bitset<100001> used;

void Dijkstra(ll start){ //start = 始点
    priority_queue<P, vector<P>, greater<P>> que;
    que.push(make_pair(0, start));
    while(!que.empty()){
        ll d, t; //d:startからの距離, t:行先
        tie(d, t) = que.top(); que.pop();
        if(used[t]) continue;   //探索済み
        used[t] = true, dist[t] = d;
        for(auto e : root[t]){
            if(dist[e.second] <= d + e.first) continue;
            que.push(make_pair(d + e.first, e.second));
        }
    }
    return;
}

