void calc(auto &tree, auto &par, auto u, auto &dis, auto &visited)
{
  if (visited[u] == true) return;
  visited[u] = true;
  REPx(x, tree[u])
  {
    int v = x.first;
    if (visited[v] == true) continue;
    ll weight = x.second;
    par[v] = u;
    dis[v] = dis[u] + weight;
  }
  REPx(x, tree[u]) calc(tree, par, x.first, dis, visited);
}

int findpar(auto &N, auto &tree, auto &par, auto a, auto b)
{
  VB reached(N, false);
  reached[a] = true;
  reached[b] = true;
  bool flg_a = true, flg_b = true;
  while (true)
  {
    if (a != par[a])
    {
      a = par[a];
      if (reached[a] == true) return a;
      else reached[a] = true;
    }
    else if (flg_a)
    {
      if (reached[a] == true) return a;
      else {reached[a] = true; flg_a = false;}
    }
    if (b != par[b])
    {
      b = par[b];
      if (reached[b] == true) return b;
      else reached[b] = true;
    }
    else if (flg_b)
    {
      if (reached[b] == true) return b;
      else {reached[b] = true; flg_b = false;}
    }
  }
}

