void build(int n, int *s1, int *s2, int *s)  
{  
    if(n <= 0)  
        return;  
    int p;  
    for(int i=0; i < n; i++)  
        if(s1[0] == s2[i])  
        {  
            p = i;  
            break;  
        }  
    build(p, s1 + 1, s2, s);  
    build(n - p - 1, s1 + p + 1, s2 + p + 1, s + p);  
    s[n - 1] = s1[0];  
}  

