#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using vll = vector<long long>;
using pll = pair<long long, long long>;

void bfs(vector<vector<pll> > &G, vll &distW, vector<bool> &checked, ll s){
    queue<ll> que;
    que.push(s);
    distW[s] = 0;
    checked[s] = true;
    while(!que.empty()){
        ll cur;
        cur = que.front(); que.pop();
        for(ll i=0; i< G[cur].size(); i++){
            ll u = G[cur][i].first, val = G[cur][i].second;
            if(!checked[u]){
                checked[u] = true;
                distW[u] = distW[cur] + val;
                que.push(u);
            }
        }
    }
}

void solve(long long N, std::vector<long long> a, std::vector<long long> b, std::vector<long long> c, long long Q, long long K, std::vector<long long> x, std::vector<long long> y){
    vector<vector<pll> > G(N);
    for(ll i=0; i< N-1; i++){
        G[a[i]-1].push_back(pll(b[i]-1, c[i]));
        G[b[i]-1].push_back(pll(a[i]-1, c[i]));
    }
    vll distW(N, 0);
    vector<bool> checked(N, false);
    bfs(G, distW, checked, K-1);
    for(ll i=0; i< Q; i++){
        cout << distW[x[i]-1] + distW[y[i]-1] << endl;
    }
    return;
}

int main(){
    long long N;
    scanf("%lld",&N);
    std::vector<long long> a(N-1);
    std::vector<long long> b(N-1);
    std::vector<long long> c(N-1);
    for(int i = 0 ; i < N-1 ; i++){
        scanf("%lld",&a[i]);
        scanf("%lld",&b[i]);
        scanf("%lld",&c[i]);
    }
    long long Q;
    scanf("%lld",&Q);
    long long K;
    scanf("%lld",&K);
    std::vector<long long> x(Q);
    std::vector<long long> y(Q);
    for(int i = 0 ; i < Q ; i++){
        scanf("%lld",&x[i]);
        scanf("%lld",&y[i]);
    }
    solve(N, std::move(a), std::move(b), std::move(c), Q, K, std::move(x), std::move(y));
    return 0;
}

