using namespace std;

class DTransitTreePath {

    vector<vpii> graph;
    vl dist;

    void dfs(int u, int p, ll d) {
        dist[u] = d;
        for (auto [v, w]: graph[u]) {
            if (v != p) {
                dfs(v, u, d + w);
            }
        }
    }

public:
	void solve(std::istream& in, std::ostream& out) {
        int n;
        in >> n;
        graph.resize(n);
        FOR(i, 1, n) {
            int a, b, c;
            in >> a >> b >> c;
            a--, b--;
            graph[a].pb({b, c});
            graph[b].pb({a, c});
        }
        int q, k;
        in >> q >> k;
        k--;
        dist.resize(n);
        dfs(k, -1, 0);
        FOR(i, 0, q) {
            int x, y;
            in >> x >> y;
            x--, y--;
            ll res = dist[x] + dist[y];
            out << res << '\n';
        }
	}

	void setup() {}
};


int main() {
    std::ios_base::sync_with_stdio(false);
	DTransitTreePath solver;
    solver.setup();
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
    out << std::fixed;
    out.precision(20);
	solver.solve(in, out);
	return 0;
}

