class LCA {
public:
    ll V, logV;
    vector<ll> depth, len;
    vector<vector<ll> > parent;

    LCA(ll V) {
        this->V = V;
        logV = 0;
        while (V > (1LL<<logV)) logV++;
        this->depth = vector<ll>(V);
        this->len = vector<ll>(V);
        this->parent = vector<vector<ll> >(logV, vector<ll>(V));
    }

    void init(ll v, ll par, ll d, ll l) {
        depth[v] = d;
        parent[0][v] = par;
        len[v] = l;
        for (ll i = 0; i < (ll)G[v].size(); i++) {
            ll w = G[v][i].first;
            ll lc = G[v][i].second;
            if (w == par) continue;
            init(w, v, d+1, lc + l);
        }
    }

    void build() {
        for (ll k = 0; k + 1 < logV; k++) {
            for (ll v = 0; v < V; v++) {
                if (parent[k][v] < 0) parent[k+1][v] = -1;
                else parent[k+1][v] = parent[k][parent[k][v]];
            }
        }
    }

    ll query(ll u, ll v) {
        if (depth[u] > depth[v]) swap(u, v);
        for (ll k = 0; k < logV; k++) {
            if ((depth[v] - depth[u]) >> k & 1)
                v = parent[k][v];
        }
        if (u == v) return u;

        for (ll k = logV-1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }
};

