using P = pair<ll,ll>;

int main(){
        ll n;
        scanf("%lld", &n);
        vector<vector<P>> links(n, vector<P>(0));

        for(ll i=0; i<n-1; i++){
                ll a, b, c;
                scanf("%lld %lld %lld", &a, &b, &c);
                links[a-1].push_back(P(c,b-1));
                links[b-1].push_back(P(c,a-1));
        }

        ll q, k;
        scanf("%lld %lld", &q, &k);
        k--;

        vector<ll> dis(n, 1e11);
        dis[k] = 0;
        priority_queue<P, vector<P>, greater<P>> que;
        que.push(P(0,k));
        while(!que.empty()){
                ll from, dist;
                tie(dist, from) = que.top();
                que.pop();
                if(dis[from]<dist) continue;

                for(P edge: links[from]){
                        ll to, cost;
                        tie(cost, to) = edge;
                        if(dis[to]<=dist+cost) continue;
                        dis[to] = dist+cost;
                        que.push(P(dis[to], to));
                }
        }

        //for(ll i=0; i<n; i++)printf("%lld ", dis[i]);puts("");

        for(ll i=0; i<q; i++){
                ll x, y;
                scanf("%lld %lld", &x, &y);
                printf("%lld\n", dis[x-1]+dis[y-1]);
        }

        return 0;
}

