void bfs(ll node, vector<vector<ll>> &dist){
    vector<ll> color(n, 0);
    color[node] = 1;
    dist[node][node] = 0;
    queue<ll> que;
    que.push(node);

    while(!que.empty()){
        auto p = que.front();
        que.pop();

        if(tree[p].parent.first != -1 && color[tree[p].parent.first] == 0){
            que.push(tree[p].parent.first);
            dist[node][tree[p].parent.first] = dist[node][p]+tree[p].parent.second;
            color[tree[p].parent.first] = 1;
        }
        for(auto c: tree[p].child){
            if(color[c.first] == 0){
                que.push(c.first);
                dist[node][c.first] = dist[node][p]+c.second;
                color[c.first] = 1;
            }
        }
    }
}

