typedef pair<int,int> Pair; 
struct node
{
	vector<LL> city;
	vector<LL> distance; 
}N[MaxN]; 
int symbol[MaxN]={0};
map <Pair,LL>mmp; 
void swap(LL &a,LL &b)
{
	LL c=a;
	a=b;
	b=c; 
} 
void work(int &a,int &b)
{
	if(a>b)
		swap(a,b); 
} 
int flag=0;
void dfs(int star,int now,int purpose,LL distance)
{
	symbol[now]=1; 
	if(now==purpose)
		flag=1 ;
	if(flag==1)
		return ; 
	for(int i=0;i<N[now].city.size();i++)
	{
		if(symbol[N[now].city[i]]==0)
		{
			Pair P;
			P.first=star;
			P.second=N[now].city[i];
			work(P.first,P.second); 
			mmp[P]=distance+N[now].distance[i]; 
			dfs(star,N[now].city[i],purpose,distance+N[now].distance[i]);
		} 
	} 
	symbol[now]=0; 
} 
int main()
{
	int M;
	scanf("%d",&M);
	for(int i=1;i<M;i++)
	{

		int c1,c2;
		LL distance;
		scanf("%d %d %lld",&c1,&c2,&distance);
		N[c1].city.push_back(c2);
		N[c1].distance.push_back(distance);
		N[c2].city.push_back(c1);
		N[c2].distance.push_back(distance); 
		work(c1,c2);
		Pair P;
		P.first=c1;
		P.second=c2;
		mmp[P]=distance; 
	} 

	int Q,K;
	scanf("%d %d",&Q,&K); 
	while(Q--)
	{
		LL sum=0;
		int c1,c2;
		scanf("%d %d",&c1,&c2); 
		Pair P;
		P.first=c1;
		P.second=K;
		work(P.first,P.second);

		if(mmp[P]!=0)
			sum+=mmp[P];
		else
		{
			memset(symbol,0,sizeof(symbol));
			flag=0;
			dfs(K,K,c1,0);
			sum+=mmp[P];
		}
		P.first=c2;
		P.second=K;
		work(P.first,P.second);

		if(mmp[P]!=0)
			sum+=mmp[P];
		else
		{
			memset(symbol,0,sizeof(symbol));
			flag=0;
			dfs(K,K,c2,0);
			sum+=mmp[P];
		}
		printf("%lld\n",sum);
	} 
	return 0;
}

