vector<ll> dijkstra(const vector<vector<P>>& G, const ll s) {
  const ll n = G.size();
  vector<ll> dist(n, linf);
  dist[s] = 0;
  priority_queue<P, vector<P>, greater<P>> Q;
  Q.push(P(0, s));
  while ( !Q.empty() ) {
    P p = Q.top(); Q.pop();
    ll cost, v; tie(cost, v) = p;
    if (cost > dist[v]) continue;
    each(e, G[v]) {
      if (dist[v] + e.second < dist[e.first]) {
        dist[e.first] = dist[v] + e.second;
        Q.push(P(dist[e.first], e.first));
      }
    }
  }
  return dist;
}

