        ll a = in()-1,b=in()-1,c = in();
        node[a][b] = c;
        node[b][a] = c;
        graph[a].pb(b);
        graph[b].pb(a);
    }
    ll Q = in(),K = in()-1;
    seen.assign(N, false);
    dist.assign(N,INT64_MAX-INT32_MAX);
    dist[K] = 0;
    dfs(graph,K);
    REP(i,Q)cout << dist[in()-1] + dist[in()-1] << "\n";
}

