ll dis[nmax]; // store the shortest distance from K to i



void sub_solve(int k){
	for(int i=0;i<N;i++){
		dis[i] = inf;
	}

	stack<int> s;
	vector<bool> visit(N,false);
	int cur;

	s.push(k);dis[k] = 0;
	visit[k]=true;

	while(!s.empty()){
		cur = s.top(); s.pop();
		for(auto e:edge[cur]){
			int node = e.first;
			ll distance = e.second;
			dis[node] =  min(dis[node],dis[cur]+distance);
			if(!visit[node]){
				s.push(node);
				visit[node]=true;
			}
		}
	}
}


int solve(){
	//for all i, decide the shortest distance from K to i.
	sub_solve(K);

	for(int i=0;i<N;i++){
