int n,q,k;
int dep[100010];
long long dis[100010];
vector<pair<int,long long> >v[100010];
bool vis[100010];
int par[100010][22];
void dfs(int x)
{
	vis[x]=true;
	for(int i=0;i<v[x].size();i++)
	{
		int y=v[x][i].first;
		long long w=v[x][i].second;
		if(vis[y])continue;
		dep[y]=dep[x]+1;
		par[y][0]=x;
		dis[y]=dis[x]+w;
		dfs(y);
	}
}
int lca(int x,int y)
{
	if(dep[x]<dep[y])swap(x,y);
	for(int i=20;i>=0;i--)
	{
		if(dep[par[x][i]]>=dep[y])x=par[x][i];
	}
	if(x==y)return x;
	for(int i=20;i>0;i--)
	{
		if(par[x][i]!=par[y][i])
		{
			x=par[x][i];
			y=par[y][i];
		}
	}
	return par[x][0];
}
long long gtdis(int x,int y)
{
	return dis[x]+dis[y]-2LL*dis[lca(x,y)];
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int a,b;
		long long c;
