		v[a].push_back(make_pair(b,c));
		v[b].push_back(make_pair(a,c));
	}
	dfs(1);
	dep[0]=-1;
	for(int i=1;i<=20;i++)
	{
		for(int j=2;j<=n;j++)par[j][i]=par[par[j][i-1]][i-1];
	}
	scanf("%d%d",&q,&k);
	for(int i=1;i<q;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		printf("%lld\n",gtdis(x,k)+gtdis(y,k)); 
	}
	int x,y;
	scanf("%d%d",&x,&y);
	printf("%lld",gtdis(x,k)+gtdis(y,k)); 
	return 0;
}

