const int N = 1e5+4, LOGN = 20;
vector <pair<int,int> > g[N];
int dp[N][LOGN], D[N];
long long dis[N];

void dfs(int v,int p){
	D[v] = D[p] + 1;
	dp[v][0] = p;
	for (auto it:g[v]){
		if (it.first!=p) {
			dis[it.first] = dis[v] + it.second;
			dfs(it.first, v);
		}
	}
}
int lca(int v, int u){
	if (D[v] < D[u]) swap(u,v);
	int d = D[v] - D[u];
	for (int i = 0; i < LOGN; i++) if (d & (1<<i)) v = dp[v][i];
	if (u == v) return v;
	for (int i = LOGN - 1; i >= 0; i--){
		if (dp[v][i] != dp[u][i]) v = dp[v][i], u = dp[u][i];
	}
	return dp[v][0];
}


long long dist(int u, int v){
	int LCA = lca(u, v);
	return dis[v] + dis[u];
}


