class DTransitTreePath {
public:
	void solve(std::istream& in, std::ostream& out)
	{
        int n, a, b;
        ll c;
        in >> n;
        Dijkstra<ll> dk(n);
        for(int i=0; i<n-1; i++){
            in >> a >> b >> c;
            a--; b--;
            dk.add(a, b, c);
            dk.add(b, a, c);
        }
        int q, k, x, y;
        in >> q >> k;
        dk.build(--k);
        for(int i=0; i<q; i++){
            in >> x >> y;
            out << dk.result(--x) + dk.result(--y) << endl;
        }
	}
};


int main() {
	DTransitTreePath solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

