struct edge{
  int to; ll cost;
};

int N;
vector<edge> G[100100];
int Q, K;

ll d[100100] = {INF};

void dfs(int i, ll co) {
  d[i] = co;
  for(int j = 0; j < G[i].size(); j++) {
    if(d[G[i][j].to] == INF) dfs(G[i][j].to , d[i] + G[i][j].cost);
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  rep(i, N) {
    int a, b; cin >> a >> b; a --; b --;
    ll c; cin >> c;
    edge es; es.to = b; es.cost = c;
    G[a].push_back(es);
    es.to = a;
    G[b].push_back(es);
  }

  cin >> Q >> K; K --;
  dfs(K, 0);
  rep(i, Q) {
    int x, y; cin >> x >> y; x --; y --;
    cout << d[x] + d[y] << "\n";
  }
  return 0;
}

