using namespace std;
typedef pair<int,int> pii;
vector<pii> g[N];
LL dis[N];
int cnt;
int lg[N],f[N],p[N],d[N][25],rmq[N];
int rmq_init(int n){
	lg[0] = -1;
	FOR(i,1,n) lg[i] = lg[i >> 1] + 1;
	for (int i = 1; i <= n; i ++) d[i][0] = i;
	for (int j = 1; (1 << j) <= n; j ++)
	for (int i = 1; i + (1 << j) - 1 <= n; i ++)
		d[i][j] = rmq[d[i][j - 1]] < rmq[d[i + (1 << (j - 1))][j - 1]] ? d[i][j - 1] : d[i + (1 << (j - 1))][j - 1];
	return 0;
}
int query(int a,int b){
	if (a > b) swap(a,b);
	int k = lg[b - a + 1];
	return rmq[d[a][k]] <= rmq[d[b - (1 << k) + 1][k]] ? d[a][k] : d[b - (1 << k) + 1][k];
}
int query_lca(int u,int v){
	return f[query(p[u],p[v])];
}
int dfs(int u,int fa,int depth){
	f[++ cnt] = u;
	rmq[cnt] = depth;
	p[u] = cnt;
	for (int i = 0; i < g[u].size(); i ++){
		int v = g[u][i].X,len = g[u][i].Y;
		if (v == fa) continue;
		dis[v] = dis[u] + (LL)len;
		dfs(v,u,depth + 1);
		f[++ cnt] = u;
		rmq[cnt] = depth;
	}
	return 0;
}
LL Distance(int x,int y){
	int lca = query_lca(x,y);
	return dis[x] + dis[y] - 2 * dis[lca];
}
int main(){
	int n;
	cin >> n;
	FOR(i,1,n - 1){
		int x,y,z;
		scanf("%d%d%d",&x,&y,&z);
		g[x].pb(pii(y,z));
		g[y].pb(pii(x,z));
	}
	int q,k;
	cnt = 0;
	dis[1] = 0;
	dfs(1,-1,0);
	rmq_init(cnt);
	cin >> q >> k;
	while (q --){
		int x,y;
		scanf("%d%d",&x,&y);
		printf("%I64d\n",Distance(x,k) + Distance(y,k));
	}
}

#include <cstdio>
