#define MAXN 100002

char vis[MAXN] = {0};
int n, q, k;
long long int D[MAXN];
vector<pair<int, long long int> > a[MAXN];
queue<int> Q;

void bfs(int st) {
	D[st] = 0;
	vis[st] = 1;
	Q.push(st);

	while(Q.size()) {
		int u = Q.front(); Q.pop();
		for(auto p : a[u]) {
			if(!vis[p.first]) {
				vis[p.first] = 1;
				D[p.first] = D[u] + p.second;
				Q.push(p.first);
			}
		}
	}
}

