using namespace std;

template<typename T = int>
vector<T> dijkstra(const vector<vector<pair<int, T>>> &G, int st, const T inf) {
    priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> pq;
    pq.push({0, st});
    vector<T> dist(G.size(), inf);
    dist[st] = 0;
    while (!pq.empty()) {
        const auto now = pq.top();
        pq.pop();
        for (auto nxt : G[now.second]) {
            const T nextCost = now.first + nxt.second;
            if (dist[nxt.first] <= nextCost) {
                continue;
            }
            dist[nxt.first] = nextCost;
            pq.push(make_pair(nextCost, nxt.first));
        }
    }
    return dist;
}

