void path(int v, int prev, int start, int goal, long long dist)
{
  if(v == goal){
    d[start] = dist;
  }
  for(auto itr=graph[v].begin(); itr != graph[v].end(); ++itr){
    pair<int, int> p;
    p = *itr;
    if(prev != p.first){
      path(p.first, v, start, goal, dist + p.second);
    }
  }
  return;
}

