struct Edge{
  int to;
  ll weight;
  Edge(int t, ll w) : to(t), weight(w) {}
};

vector<vector<Edge>> g;
int n;

vector<ll> dist;
void dijkstra(int s){
  priority_queue<P, vector<P>, greater<P>> que;
  dist[s] = 0;
  que.push({dist[s], s});

  while(!que.empty()){
    auto v = que.top();
    que.pop();
    int from = v.second;
    ll d = v.first;
    if(d > dist[from])continue;

    for(auto nv : g[from]){
      ll cost = nv.weight;
      int to = nv.to;
      if(dist[from] + cost < dist[to]){
        dist[to] = dist[from] + cost;
        que.push({dist[to], to});
      }
    }
  }
}


