struct Graph{
  long long V;
  long long E;
  //u,v,weight,cap
  vector<tuple<long long,long long,long long,long long>> edges;
  void add(long long u,long long v){edges.push_back(make_tuple(u,v,1,1));}
  void add(long long u,long long v,long long weight){edges.push_back(make_tuple(u,v,weight,1));}
  void add(long long u,long long v,long long weight,long long capacity){edges.push_back(make_tuple(u,v,weight,capacity));}
  Graph(long long V) : V(V){}
  Graph(long long V,long long E) : V(V),E(E){}
};

struct HLD{
    Graph G;
    ll root;
    vector<ll> DFS;
    vector<ll> subtree;
    vector<ll> pre;

    ll dfs(ll n,const vector<vector<pair<ll,ll>>> &adj){
        DFS[n] = 0;
        ll ans = 1;
        for(auto p:adj[n]){
            if(DFS[p.first] == -1){
                ans += dfs(p.first,adj);
                pre[p.first] = n;
            }
        }
        return DFS[n] = ans;
    }

    void HLdfs(ll n,ll r,const vector<vector<pair<ll,ll>>> &adj){
        subtree[n] = r;
        ll MAX = 0;
        bool flag = true;
        for(auto p:adj[n]){
            if(DFS[p.first] < DFS[n]){
                MAX = max(DFS[p.first],MAX);
            }
        }
        for(auto p:adj[n]){
            if(MAX == DFS[p.first] && flag){
                HLdfs(p.first,r,adj);
                flag = false;
            }
            else if(DFS[p.first] < DFS[n]){
                HLdfs(p.first,p.first,adj);
            }
        }
    }

    void depthdfs(ll n,ll pre,ll depth,const vector<vector<pair<ll,ll>>> &adj){
        DFS[n] = depth;
        for(auto p:adj[n]){
            if(p.first != pre){
                depthdfs(p.first,n,depth+p.second,adj);
            }
        }
    }

    ll lca(ll u,ll v){
        while(subtree[u] != subtree[v]){
            if(DFS[subtree[u]] < DFS[subtree[v]]){
                v = pre[subtree[v]];
            }
            else{
                u = pre[subtree[u]];
            }
        }
        return (DFS[u] < DFS[v] ? u : v);
    }

    ll dist(ll u,ll v){
        ll LCA = lca(u,v);
        return DFS[u]+DFS[v]-2*DFS[LCA];
    }

    HLD(Graph G,ll root = 0) : G(G),root(root) {
        vector<vector<pair<ll,ll>>> adj;
        adj.resize(G.V);
        DFS.resize(G.V);
        pre.resize(G.V);
        subtree.resize(G.V);
        fill(ALL(DFS),-1);
        for(auto t:G.edges)adj[get<0>(t)].push_back(make_pair(get<1>(t),get<2>(t)));
        dfs(root,adj);
        HLdfs(root,root,adj);
        depthdfs(root,root,1,adj);
    }
};

