struct node{int p,c,l,r;};
node t[100001];
long long cost[100001];
bool alr[100001]={true};
void dfs(int now,long long nowc){
	cost[now]=nowc;
	alr[now]=true;
	if(t[now].p&&alr[t[now].p]==false) dfs(t[now].p,nowc+t[now].c);
	if(t[now].l&&alr[t[now].l]==false) dfs(t[now].l,nowc+t[t[now].l].c);
	int tmp=t[now].l;
	while(t[tmp].r){
		tmp=t[tmp].r;
		if(alr[tmp]==false) dfs(tmp,nowc+t[tmp].c);
	}
}

