}

#include<bits/stdc++.h>
using namespace std;
typedef pair<int,int>P;
struct E{
  long long t,c;
  bool operator<(const E&a)const{return c>a.c;}
};
vector<E>G[1<<17];
long long z[1<<17];
int n,a,b,c,q,k,x,y,i,j;
void dijkstra(){
  priority_queue<E>Q;
  for(int i=0;i<1<<17;)z[i++]=1ll<<60;
  z[k]=0;
  Q.push(E{k,0});
  while(Q.size()){
    E p=Q.top();Q.pop();
    if(z[p.t]<p.c)continue;
    for(i=0;i<G[p.t].size();++i){
      E e=G[p.t][i];
      if(z[e.t]>p.c+e.c)z[e.t]=p.c+e.c,Q.push(E{e.t,z[e.t]});
    }
  }
}
main(){
  for(cin>>n;++i<n;G[a].push_back(E{b,c}),G[b].push_back(E{a,c}))scanf("%d%d%d",&a,&b,&c);
  for(cin>>q>>k,dijkstra();j++<q;printf("%lld\n",z[x]+z[y]))scanf("%d%d",&x,&y);
}

