using namespace std;  
const int MAXN=1e5+50;  
const long long INF=1e18;  
int n;  
int k,p;  
long long dis[MAXN];  
int vis[MAXN];  
struct Edge  
{  
    int from;  
    int to;  
    int cost;  
    Edge(int a,int b,int c)  
    {  
        from=a;  
        to=b;  
        cost=c;  
    }  
};  
vector<Edge> edges;  
vector<int> G[MAXN];  

void Init()  
{  
    for(int i=0; i<=n; i++)  
        G[i].clear();  
    edges.clear();  
}  
struct Heap  
{  
    int d,u;  
    Heap(int a,int b)  
    {  
        d=a,u=b;  
    }  
    bool operator<(Heap h)const  
    {  
        return d>h.d;  
    }  
};  
void Dijkstra(int s)  
{  
    priority_queue<Heap> p;  
    p.push(Heap(0,s));  
    for(int i=0; i<=n; i++) dis[i]=INF;  
    dis[s]=0;  
    memset(vis,0,sizeof(vis));  
    while(!p.empty())  
    {  
        Heap h=p.top();  
        p.pop();  
        int  u=h.u;  
        if(vis[u]) continue;  
        for(int i=0; i<G[u].size(); i++)  
        {  
            Edge &e=edges[G[u][i]];  
            if(vis[e.to]) continue;  
            if(dis[e.to]>dis[u]+e.cost)  
            {  
                dis[e.to]=dis[u]+e.cost;  
                p.push(Heap(dis[e.to],e.to));  
            }  
        }  
    }  
}  
int main()  
{  
    scanf("%d",&n);  
    Init();  
    for(int i=0; i<n-1; i++)  
    {  
        int x,y,z;  
        scanf("%d%d%d",&x,&y,&z);  
        edges.push_back(Edge(x,y,z));  
        G[x].push_back(2*i);//无向边，两个方向加  
        edges.push_back(Edge(y,x,z));  
        G[y].push_back(2*i+1);  
    }  
    scanf("%d%d",&p,&k);  
    Dijkstra(k);  
    //for(int i=0;i<=n;i++)  
    //    cout<<dis[i]<<" ";  
    //  cout<<endl;  
    for(int i=0; i<p; i++)  
    {  
        int x,y;  
        scanf("%d%d",&x,&y);  
        cout<<dis[x]+dis[y]<<endl;  
    }  
    return 0;  
}

