ll mul(ll a, ll b, ll m = mod) { return (ll)(a * b) % m;}
ll add(ll a, ll b, ll m = mod) { a += b; if(a >= m) a -= m; if(a < 0) a += m; return a;}
ll power(ll a, ll b, ll m = mod) { if(b == 0) return 1; if(b == 1) return (a % m); ll x = power(a, b / 2, m); x = mul(x, x, m); if(b % 2) x = mul(x, a, m); return x;}
ll n, p[N][20], h[N], subtree[N], d[N];
vector < pl > g[N];
void dfs(ll u, ll pre)
{
    p[u][0] = pre;
    for(ll i = 1; i <= LOGN; i++)
    {
        if(p[u][i - 1])
        {
            p[u][i] = p[p[u][i - 1]][i - 1];
        }
    }
    h[u] = h[pre] + 1;
    subtree[u]++;
    f(i, g[u].size())
    {
        ll v = g[u][i].F;
        if(v == pre)
        {
            continue;
        }
        d[v] = d[u] + g[u][i].S;
        dfs(v, u);
        subtree[u] += subtree[v];
    }
}
ll lca(ll u, ll v)
{
    if(u == v) return u;
    if(h[u] < h[v])
    {
        swap(u, v);
    }
    for(ll i = LOGN; i >= 0 ; i--)
    {
        if((p[u][i]) && h[p[u][i]] >= h[v])
        {
            u = p[u][i];
        }
    }
    if(u == v)
    {
        return v;
    }
    for(ll i = LOGN; i >= 0; i--)
    {
        if(p[u][i] != p[v][i])
        {
            u = p[u][i];
            v = p[v][i];
        }
    }
    return p[v][0];
}
ll dist(ll x, ll y)
{
    ll l = lca(x, y);
    return d[x] + d[y] - 2 * d[l];
}
