using namespace std;

typedef long long ll;
typedef pair<ll,int> P;//firstは最短距離,secondは頂点の番号

struct edge{
    int to;
    ll cost;
};

const int MAX_V=1e5;//問題の制約用
const ll INF=1e18;
int V;//使う頂点数
vector<edge> G[MAX_V];//グラフ
ll d[MAX_V];//距離を詰める

void dijkstra(int s){//始点sからの最短距離を求める。
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d,d+V,INF);
    d[s]=0;
    que.push(P(0,s));
    while(!que.empty()){
        P p=que.top(); que.pop();
        int v = p.second;
        if(d[v]<p.first) continue;//それが最短距離でなければ無視
        for(int i=0;i<G[v].size();i++){
            edge e=G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to],e.to));
            }
        }
    }
}


