        e.to=b; e.cost=c;
        G[a].push_back(e);
        e.to=a; e.cost=c;
        G[b].push_back(e);
    }
    int Q,K;
    cin>>Q>>K;
    K--;
    dijkstra(K);
    for(int i=0;i<Q;i++){
        int x,y;
        cin>>x>>y;
        x--; y--;
        cout<<d[x]+d[y]<<endl;
    }
    return 0;
}

