using ll = long long;

struct Edge {
  int to;
  ll cost;
  Edge(int to, ll cost) : to(to), cost(cost) {}
};
bool operator < (const Edge &e, const Edge &f) {
  return ( e.cost != f.cost ) ? e.cost > f.cost : e.to < f.to;
}
using graph = vector<vector<Edge>>;

const ll INF = 1e18;

graph G;
vector<ll> d;

void dijkstra(int s) {
  int N = G.size();
  priority_queue<Edge> que;
  d.assign(N, INF);
  d[s] = 0;
  que.push(Edge(s, 0));
  while (!que.empty()) {
    Edge e = que.top(); que.pop();
    int u = e.to;
    if (d[u] < e.cost) continue;
    for (auto&& v : G[u]) {
      if (d[v.to] > d[u] + v.cost) {
        d[v.to] = d[u] + v.cost;
        que.push(Edge(v.to, d[v.to]));
      }
    }
  }
}

