map<pair<pll,ll>,ll>maps;
ll dfs1(ll i)
{
    if(i==k){
        return 0;
    }
    if(maps[{{i,k},colour}])return maps[{{i,k},colour}];
    if(vis[i]==colour)return INF;
    vis[i]=colour;
    ll ans=INF;
    for(auto p:vec[i]){
        maps[{{i,p.ff},colour}]=ans=min(ans,p.ss+dfs1(p.ff));
    }
    return maps[{{i,k},colour}]=ans;
}
ll dfs2(ll i)
{
    if(i==b){
        return 0;
    }
    if(maps[{{i,b},colour}])return maps[{{i,b},colour}];
    if(vis2[i]==colour)return INF;
    vis2[i]=colour;
    ll ans=INF;
    for(auto p:vec[i]){
        maps[{{i,p.ff},colour}]=ans=min(ans,p.ss+dfs2(p.ff));
    }
    return maps[{{i,b},colour}]=ans;
}

