void dijkstra(int s)
{
	ll minv;
	int color[MAX];

	for(int i = 0; i < n; i++)
	{
		d[i] = INFTY;
		color[i] = WHITE;
	}

	d[s] = 0;
	color[s] = GRAY;
	while (1)
	{
		minv = INFTY;
		int u = -1;
		for(int i = 0; i < n; i++)
		{
			if (minv > d[i] && color[i] != BLACK)
			{
				u = i;
				minv = d[i];
			}
		}
		if (u == -1) break;
		color[u] = BLACK;
		for(int v = 0; v < n; v++)
		{
			if (color[v] != BLACK && M[u][v] != INFTY)
