    long length;
};

// 現在位置 i から dest までの最短経路を深さ優先探索
// これだと O(N^2) の実装なので全然間に合わない
long dfs( int i, int dest, int parent, long d, vector<edge>* V )
{
    if( i == dest ) return d;
    long ans = LONG_MAX;
    for( auto &e: V[i] ){
        if( e.to == parent ) continue;
        ans = min( ans, dfs( e.to, dest, i, d+e.length, V ) );
    }
    return ans;
}

// O(N) の実装
// 探索しながら最短距離を minLength に代入していく
void dfs2( int i, int parent, long d, vector<edge>* V, vector<long>& minLength )
{
    minLength[i] = d;
    for( auto &e: V[i] ){
        if( e.to == parent ) continue;
        dfs2( e.to, i, d+e.length, V , minLength);
    }
}


