ll solve()
{
    const ll inf = 1LL << 60;
    ll N;
    cin >> N;
    ll a,b,c;
    //ll ans = 0;
    vector<vector<pair<ll,ll>>> node(N);
    for1(i,N-1) {
        cin >> a >> b >> c;
        a -= 1;
        b -= 1;
        node[a].push_back(make_pair(b,c));
        node[b].push_back(make_pair(a,c));
    }

    ll Q,K;
    cin >> Q >> K;
    K -= 1;

    vector<ll> sc(N, inf);
    sc[K] = 0;
    priority_queue<pair<ll,ll>> q;
    q.push(make_pair(0,K));
    while (!q.empty()) {
        pair<ll,ll> item = q.top();
        q.pop();
        ll cost = -item.first;
        ll src = item.second;
        for (auto road : node[src]) {
            ll dest = road.first;
            ll cost1 = road.second;
            if (sc[dest] > cost + cost1) {
                sc[dest] = cost + cost1;
                q.push(make_pair(-sc[dest],dest));
            }
        }
    }

    vector<ll> ans(Q);
    for1(i,Q) {
        ll x,y;
        cin >> x >> y;
        x -= 1;
        y -= 1;
        ans[i] = sc[x] + sc[y];
    }
    for1(i,Q) {
        cout << ans[i] << endl;
    }

    return 0;//ans;
}

