vector<ll> dijkstra(int N, vector<vector<edge> >& G, int s) {
  vector<ll> d(N, (ll)1e+15);
    d[s] = 0;
    priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>> > pq;
    pq.push(pair<ll, ll>(0, s));
    while (pq.size()) {
        pair<ll, ll> p = pq.top(); pq.pop();
        ll u = p.second;
        if (p.first > d[u]) continue;
        for (edge e: G[u])
            if (d[e.v] > d[u] + e.w) {
                d[e.v] = d[u] + e.w;
                pq.push(pair<ll, ll>(d[e.v], e.v));
            }
    }
    return d;
}

