using namespace std;

typedef long long ll;

int n, timer = 0, l = 1;
vector<vector<int>> v, up;
vector<int> tin, tout;
vector<ll> d;
map<pair<int, int>, int> data;

void dfs(int u, int p = 1) {
    tin[u] = ++timer;
    up[u][0] = p;
    for (int i = 1; i <= l; i++) {
        up[u][i] = up[up[u][i - 1]][i - 1];
    }
    for (int i = 0; i < v[u].size(); i++) {
        if (v[u][i] != p) {
            d[v[u][i]] = (ll) d[u] + data[{u, v[u][i]}];
            dfs(v[u][i], u);
        }
    }
    tout[u] = ++timer;
}

bool check(int v1, int v2) {
    return tin[v1] <= tin[v2] && tout[v2] <= tout[v1];
}

int lca(int v1, int v2) {
    if (check(v1, v2)) {
        return v1;
    }
    if (check(v2, v1)) {
        return v2;
    }
    for (int i = l; i >= 0; i--) {
        if (!check(up[v1][i], v2)) {
            v1 = up[v1][i];
        }
    }
    return up[v1][0];
}

ll dist(int x, int y) {
    return (ll) d[x] + d[y] - 2 * d[lca(x, y)];
}

