typedef pair<long long, long long> P;

void dijkstra(int s){
    for(int i = 0; i < n; i++){
        D[i] = INF;
    }
    D[s] = 0;
    priority_queue<P, vector<P>, greater<P>> q;
    q.push({s, 0});
    while(!q.empty()){
        P p = q.top();
        q.pop();
        long long now = p.second;
        if(D[now] < p.first) continue;
        for(int i = 0; i < G[now].size(); i++){
            edge e = G[now][i];
            if(D[e.to] > D[now] + e.cost){
                D[e.to] = D[now] + e.cost;
                q.push({e.to, D[e.to]});
            }
        }
    }
}


