void init( ) {
  for( int i = 0; i < n; ++i ) {
    graph[ i ].clear( );
  }
}

void dfs( int u, int p = -1 ) {
  d[ u ] = ( p == -1 ? 0 : d[ p ] )+1;
  dp[ u ][ 0 ] = p;
  for( auto& e : graph[ u ] ) {
    if( e.FI != p ) {
      dfs( e.FI, u );
      val[ e.FI ][ 0 ] = e.SE;
    }
  }
}

int query( int u, int v ) {
  int r = 0;
  if( d[ u ] > d[ v ] ) {
    swap( u, v );
  }
  for( int j = LOG2-1; j >= 0; --j ) {
    if( d[ u ] <= d[ dp[ v ][ j ] ] ) {
      r += val[ v ][ j ];
      v = dp[ v ][ j ];
    }
  }
  if( u == v ) {
    return r;
  }
  for( int j = LOG2-1; j >= 0; --j ) {
    if( dp[ u ][ j ] != dp[ v ][ j ] ) {
      r += val[ u ][ j ];
      u = dp[ u ][ j ];
      r += val[ v ][ j ];
      v = dp[ v ][ j ];
    }
  }
  r += val[ u ][ 0 ];
  r += val[ v ][ 0 ];
  return r;
}

