  for (int i = 1; i < n; i++) {
    int from, to, weight;
    cin >> from >> to >> weight;
    edges[from].emplace_back(make_pair(to, weight));
    edges[to].emplace_back(make_pair(from, weight));
  }
  int q, k;
  cin >> q >> k;

  vector<uint64_t> dist(n + 1);
  deque<pair<int, uint64_t>> queue;  // vertex, dist
  queue.push_back(make_pair(k, 0));  // starting point
  while (!queue.empty()) {
    auto start = queue.front();
    queue.pop_front();
    uint64_t current_dist = start.second;
