const ll INF = LLONG_MAX;
const int MAX_V = 100100;

struct edge{
  int to;
  ll cost;
};
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(int V,int s){
  priority_queue<P,vector<P>,greater<P>> que;
  fill(d,d+V,INF);
  d[s] = 0;
  que.push(P(0,s));
  while(!que.empty()){
    P p = que.top();
    que.pop();
    int v = p.se;
    if(d[v] < p.first)continue;
    rep(i,sz(G[v])){
      edge e = G[v][i];
      if(d[e.to] > d[v]+e.cost){
        d[e.to] =  d[v]+e.cost;
        que.push(P(d[e.to],e.to));
      }
    }
  }
}

