vector<ii> g[100010];

ll dist[100010];
void dfs(int u, int p)
{
	for(auto next : g[u]) {
		int v = next.first;
		int w = next.second;

		if(v == p)
			continue;
		dist[v] = dist[u] + w;
		dfs(v, u);
	}
}

