typedef long long int LL;
#define INF 0x3f3f3f3f  //无穷大
#define MAXN 100000+24
struct ArcNode{
	int to;
	int weight;
	ArcNode *next;
};
queue<int> Q;  //队列中的结点为顶点序号
int n;    //顶点个数
ArcNode* List[MAXN];  //每个顶点的边链表表头指针
int inq[MAXN];  //每个顶点是否在队列中的标志
LL dist[MAXN],path[MAXN];
void SPFA(int src)
{
	int i,u;   //u为队列头顶点序号
	ArcNode* temp;
	for(i=1;i<=n;i++)  //初始化
	{
		dist[i]=INF;
		path[i]=src;
		inq[i]=0;
	}
	dist[src]=0;
	path[src]=src;
	inq[src]++;
	Q.push(src);  
	while(!Q.empty()) {
		u=Q.front();
		Q.pop();
		inq[u]--;
		temp=List[u];
		while(temp!=NULL){
			int v=temp->to;
			if(dist[v]>dist[u]+temp->weight){
				dist[v]=dist[u]+temp->weight;
				path[v]=u;
				if(!inq[v]){
					Q.push(v);
					inq[v]++;
				}
			}
			temp=temp->next;
		}
	}
}
int main(){
	while(~scanf("%d",&n)){
		memset(List,0,sizeof(List));
		ArcNode* temp;
		for(int i=1;i<n;i++){
			int u,v,w;  
			scanf("%d%d%d",&u,&v,&w);  
			temp=new ArcNode;
			temp->to=v;
			temp->weight=w;
			temp->next=NULL;
			if(List[u]==NULL) List[u]=temp;
			else{
				temp->next=List[u];
				List[u]=temp;
			}
		}
		int q,st;
		scanf("%d%d",&q,&st);
		SPFA(st); 
		for(int i=1;i<=q;i++){
			int u,v;
			scanf("%d%d",&u,&v);
			printf("%d\n",dist[u]+dist[v]);
		}
	}
	return 0;
}

