#include <bits/stdc++.h>
#define MOD 1000000007
using namespace std;
typedef long long ll;
typedef pair<ll, int> P;

int N, Q, K;
vector<vector<P>> root(100001);  //pair<辺の距離, 行先の頂点>

ll Dijkstra(ll start, ll goal){ //start = 始点
    priority_queue<P, vector<P>, greater<P>> que;
    vector<ll> dist(100001, LLONG_MAX); //distance[i]はstartから頂点iへの最短距離が入る
    bitset<100001> used;
    que.push(make_pair(0, start));
    while(!que.empty()){
        ll d, t; //d:startからの距離, t:行先
        tie(d, t) = que.top(); que.pop();
        if(used[t]) continue;   //探索済み
        used[t] = true, dist[t] = d;
        if(t == goal) break;
        for(auto e : root[t]){
            if(dist[e.second] <= d + e.first) continue;
            que.push(make_pair(d + e.first, e.second));
        }
    }
    return dist[goal];
}

int main(void){

    cin >> N;
    for(int i = 0; i < N - 1; ++i){
        int a, b, c; cin >> a >> b >> c;
        root[a].push_back(make_pair(c, b)), root[b].push_back(make_pair(c, a));
    }

    cin >> Q >> K;
    for(int i = 0; i < Q; ++i){
        ll x, y; cin >> x >> y;
        ll a = Dijkstra(x, K);
        ll b = Dijkstra(K, y);
        cout << a + b << endl;
    }

    return 0;
}

