        a--;b--;
        dik.add_edge(a, b, c);
        dik.add_edge(b, a, c);
    }

    int q, k;
    cin >> q >> k;
    k--;
    dik.run(k);
    REP(i, q){
        ll x, y;
        cin >> x >> y;
        x--;y--;
        cout << dik.get_distance(x) + dik.get_distance(y) << endl;
    }
}

