#include <cstdio>

struct Line{
	int a;
	int b;
	int c;
};

int n;

int search(Line lines[], int s){//lines[i].b == sとなるiを返す
	for(int i = 0; i < n - 1; i++){
		if(lines[i].b == s){
			return i;
		}
	}
}

void direction(Line lines[], int k, bool ok[]){//kが上になるようにする
	for(int i = 0; i < n - 1; i++){
		if(lines[i].b == k && ok[i] == false){
			int tmp = lines[i].a;
			lines[i].a = lines[i].b;
			lines[i].b = tmp;
			ok[i] = true;
			direction(lines, lines[i].b, ok);
		}
	}
	for(int i = 0; i < n - 1; i++){
		if(lines[i].a == k && ok[i] == false){
			ok[i] = true;
			direction(lines, lines[i].a, ok);
		}
	}
	return;
}

int main(){
	scanf("%d", &n);
	Line lines[n-1];
	for(int i = 0; i < n-1; i++){
		scanf("%d%d%d", &lines[i].a, &lines[i].b, &lines[i].c);
	}
	int q, k;
	scanf("%d%d", &q, &k);
	bool ok[n-1];
	for(int i = 0; i < n - 1; i++){
		ok[i] = false;
	}
	direction(lines, k, ok);
	for(int i = 0; i < q; i++){
		int ans = 0;
		int x, y;
		scanf("%d%d", &x, &y);
		int st = search(lines, x);
		while(lines[st].a != k){
			ans += lines[st].c;
			st = search(lines, lines[st].a);
		}
		ans += lines[st].c;
		int end = search(lines, y);
		while(lines[end].a != k){
			ans += lines[end].c;
			end = search(lines, lines[end].a);
		}
		ans += lines[end].c;
		printf("%d\n", ans);
	}

	return 0;
}

