vector<long long> dijkstra(int start){
    vector<long long> distance(MAX_N, INF);
    distance[start] = 0;//start->i
    priority_queue<pair<long long,int>,vector<pair<long long,int>>,greater<pair<long long,int>>> que; //min heap <cost,to> costでソートするためGの逆
    que.push(make_pair(0, start));
    while(!que.empty()){
        auto p = que.top(); //<cost,to>
        que.pop();
        //目的地1を更新できないならとばす
        if(distance[p.second] < p.first) continue;
        //目的地１(p.second)から伸びるedgeの先の目的地２(edge.first)をそれぞれ更新する
        for (auto edge: Glaph[p.second]){ //edge<to,cost> 
            //目的地２の元のcost > 更新された目的地１のコスト + edgeのコスト なら更新してキューに追加
            if(distance[edge.first] > distance[p.second] + edge.second){
                 distance[edge.first] = distance[p.second] + edge.second;
                 que.push(make_pair(distance[edge.first],edge.first));
            }
        }
    }
    return distance;
}

