using namespace std;

#define MAX_V 200000

long long int INF = 100000000000000000LL;

struct edge{
	int to;
	long long int cost;
};

typedef pair<long long int, int> P; // firstは最短距離、secondは頂点の番号

vector<edge> G[MAX_V];
long long int d[MAX_V];

// 速さはO(|E|log|V|)

void shortest_path(int s, int V){ // Vは頂点数

	priority_queue<P, vector<P>, greater<P> > que;

	for(int i = 0; i < V; i++){
		d[i] = INF;
	}
	d[s] = 0;

	que.push(P(0, s));

	while(!que.empty()){

		P p = que.top();
		que.pop();

		int v = p.second;

		if(d[v] < p.first){
			continue;
		}

		for(int i = 0; i < G[v].size(); i++){
			edge e = G[v][i];
			if(d[e.to] > e.cost + d[v]){
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		} // 頂点への最小コストを更新
	}
}

int main(){

	int N;
	cin >> N;
	for(int i = 0; i < N - 1; i++){
		int index1, index2;
		long long int cost;
		cin >> index1 >> index2 >> cost;
		edge e1, e2;
		e1.to = index2;
		e2.to = index1;
		e1.cost = cost;
		e2.cost = cost;
		G[index1].push_back(e1);
		G[index2].push_back(e2);
	}

	int Q, K;
	cin >> Q >> K;

	shortest_path(K, N + 1);

	for(int i = 0; i < Q; i++){
		int x, y;
		cin >> x >> y;
		cout << d[x] + d[y] << endl;
	}

	return 0;
}

