int N, a, b, c, Q, K, x, y;

struct node {
    int id;
    long long dist;
    node(int i, long long d) : id(i), dist(d) {}
};

vector<vector<node> > sons(MAXN);
int first[MAXN] = {0};
int path[MAXN << 1];
long long deep[MAXN << 1];
int dp[MAXN << 1][19];
int pos = 0;

void dfs(int cur, int fa, long long d) {
    for (auto son : sons[cur]) {
        if (son.id == fa) continue;
        path[pos] = cur;
        deep[pos++]= d;
        dfs(son.id, cur, d + son.dist);
    }
    path[pos] = cur;
    deep[pos++] = d;
}

void make_st() {
    for (int i = 0; i != pos; ++i) {
        if (first[path[i]] == 0)
            first[path[i]] = i;
        dp[i][0] = i;
    }
    for (int j = 1; j != 19; ++j) {
        for (int i = 0; i + (1 << j) - 1 < pos; ++i) {
            int a = dp[i][j - 1];
            int b = dp[i + (1 << j >> 1)][j - 1];
            dp[i][j] = deep[a] < deep[b] ? a : b;
        }
    }
}

int LCA(int a, int b) {
    a = first[a]; b = first[b];
    if (a > b) swap(a, b);
    int j = -1, len = b - a + 1;
    while (len) {
        ++j;
        len /= 2;
    }
    int c = dp[a][j];
    int d = dp[b - (1 << j) + 1][j];
    return deep[c] < deep[d] ? path[c] : path[d];
}

long long dis(int a, int b) {
    int t = LCA(a, b);
    return deep[first[a]] + deep[first[b]] - 2 * deep[first[t]];
}

int main() {
    cin >> N;
    for (int i = 1; i != N; ++i) {
        cin >> a >> b >> c;
        sons[a].push_back(node(b, c));
        sons[b].push_back(node(a, c));
    }
    dfs(1, 0, 0);
    make_st();
    cin >> Q >> K;
    while (Q--) {
        cin >> x >> y;
        int t = LCA(x, y);
        cout << dis(x, y) + 2 * dis(t, K) << endl;
    }
    return 0;
}

