using Edge = pair<int, ll>;
using Graph = vector<vector<Edge>>;

void dfs(const Graph &G, int v, int p, ll sum, vector<ll> &dist) {
    dist[v] = sum;
    for (auto e : G[v]) {
        if (e.first == p) continue;
        dfs(G, e.first, v, sum + e.second, dist);
    }
}

