        G[a].pb({b, c});
        G[b].pb({a, c});
    }
    int Q, K; cin >> Q >> K;
    K--;
    dfs(G, K, -1, 0, dist);
    rep(i, Q) {
        int x, y; cin >> x >> y;
        x--; y--;
        cout << dist[x] + dist[y] << endl;
    }

    return 0;
}

