#include <bits/stdc++.h>

using namespace std;

const int N = 100005;
const int P = 20;

int n, d[N], fa[N][P];
long long dis[N][P];
vector<pair<int, int>> g[N];

void dfs(int u, int f, int w) {
  d[u] = d[f] + 1;
  dis[u][0] = w;
  fa[u][0] = f;
  for (int i = 1; i < P; ++i) {
    fa[u][i] = fa[fa[u][i - 1]][i - 1];
    dis[u][i] = dis[u][i - 1] + dis[fa[u][i - 1]][i - 1];
  }
  for (auto &go : g[u]) {
    if (go.first != f) {
      dfs(go.first, u, go.second);
    }
  }
}

long long query(int u, int v) {
  long long res = 0;
  if (d[u] < d[v]) {
    swap(u, v);
  }
  int del = d[u] - d[v];
  for (int i = P - 1; i >= 0 && del; --i) {
    if (del & (1 << i)) {
      res += dis[u][i];
      u = fa[u][i];
    }
  }
  for (int i = P - 1; i >= 0; --i) {
    if (fa[u][i] != fa[v][i]) {
      res += dis[u][i] + dis[v][i];
      u = fa[u][i];
      v = fa[v][i];
    }
  }
  if (u != v) {
    res += dis[u][0] + dis[v][0];
  }
  return res;
}

int main() {
  scanf("%d", &n);
  for (int i = 1; i < n; ++i) {
    int u, v, w;
    scanf("%d %d %d", &u, &v, &w);
    g[u].push_back({v, w});
    g[v].push_back({u, w});
  }
  dfs(1, 1, 0);
  int q, k;
  scanf("%d %d", &q, &k);
  while (q--) {
    int x, y;
    scanf("%d %d", &x, &y);
    cout << query(x, k) + query(y, k) << endl;
  }
  return 0;
}

