void addEdge(long long u, long long v, long long w)
{
    edge[tot].v = v;
    edge[tot].w = w;
    edge[tot].next = head[u];       //接替已有边
    head[u] = tot++;                //自己前插成为u派生的第一条边
}
void SPFA(long long u)
{
    long long v, w, i;
    for(i = 1; i <= n; i++)  //对于从1到n的编号
        dis[i] = inf, vis[i] = false;
    dis[u] = 0;
    queue<long long > q;
    q.push (u);
    vis[u] = true;
    while(!q.empty())
    {
        u = q.front();
        q.pop();
        vis[u] = false;
        for(i = head[u]; i != -1; i = edge[i].next)
        {
            w = edge[i].w;
            v = edge[i].v;
            if (dis[u] + w < dis[v])
            {
                dis[v] = dis[u] + w;
                if (!vis[v])
                {
                    q.push (v);
                    vis[v] = true;
                }
            }
        }
    }
}
