int lca(int u, int v) {
	if (d[u] > d[v])swap(u, v);
	rep(i, 18) {
		if ((d[v] - d[u]) >> i & 1)v = par[i][v];
	}
	if (u == v)return u;
	for (int i = 17; i >= 0; i--) {
		if (par[i][u] != par[i][v]) {
			u = par[i][u]; v = par[i][v];
		}
	}
	return par[0][u];
}
