struct NODE{
	ll dist;
	ll number;
	bool done;
	vl edges_to;
	vl edges_cost;
	bool operator<= (const NODE &temp) const { return this->dist >= temp.dist; }
	bool operator>= (const NODE &temp) const { return this->dist <= temp.dist; }
	bool operator< (const NODE &temp) const { return this->dist > temp.dist; }
	bool operator> (const NODE& temp) const { return this->dist < temp.dist; }
};

void dijkstra(vector<NODE> &nodes, ll start){
	priority_queue<NODE> q;
	vb contains_flag(nodes.size(),false);
	nodes[start].dist = 0;
	q.push(nodes[start]);
	contains_flag[start] = true;
	while (!q.empty()){
		NODE temp_v = q.top();
		q.pop();
		contains_flag[temp_v.number] = false;
		//cout << "temp_v.number="<<temp_v.number << endl;
		temp_v.done = true;
		rep(i, temp_v.edges_to.size()){
			ll to = temp_v.edges_to[i];
			ll cost = temp_v.edges_cost[i] + temp_v.dist;
			if (nodes[to].dist < 0 || cost < nodes[to].dist){
				nodes[to].dist = cost;
				if (!contains_flag[to]){
					q.push(nodes[to]);
					//cout << "push_" << to << endl;
					contains_flag[to] = true;
				}
			}
		}
	}
}

