vector<vector<pair<int, int>>> E;  ///< Adjacency list with distance.

void dfs(int v, int64_t d) {  // vertex, distance
  V[v] = d;
  for (const auto& x : E[v]) {
    int v_next = x.first;
    int d_next = x.second;
    if (V[v_next] != -1) continue;  // already visited.
    dfs(v_next, d + d_next);
  }
}

