void bellmanFord(vector<edge>& es, vector<ll>& ds, int start)
{
    for (auto& d : ds) d = INT64_MAX;
    ds[start] = 0;
    while (true) {
        bool update = false;
        for (int i = 0; i < es.size(); ++i) {
            edge e = es[i];
            if (ds[e.from] != INT64_MAX && ds[e.to] > ds[e.from] + e.cost) {
                ds[e.to] = ds[e.from] + e.cost;
                update = true;
            }
        }
        if (!update) break;
    }
}

