const int maxn = 10e5;
unordered_map<int, int> graph[maxn];

ll solve(int x, int y, int k){
	int start = x;

	queue<int> q;
	bool vis[maxn];
	memset(vis, 0, sizeof vis);

	int parent[maxn];

	q.push(start);
	vis[start] = true;

	bool foundK = false, foundY = false;

	while(!q.empty()){
		int u = q.front();
		q.pop();

		if (u == k) foundK = true;
		if (u == y) foundY = true;

		if (foundK && foundY) break;
		for(auto it : graph[u]){
			int v = it.first;
			if (!vis[v]){
				parent[v] = u;
				q.push(v);
				vis[v] = true;
			}
		}
	}

	ll total = 0;
	int temp = y;
	unordered_map<int,bool> ancestors;
	ancestors[temp] = true;
	while(temp!=x){
		total += graph[temp][parent[temp]];
		//cout << "parent y: " << parent[temp]+1 << endl;
		temp = parent[temp];
		ancestors[temp] = true;
	}
	//cout << "Total: " <<  total << endl;

	if(!ancestors[k]){
		ll totalK = 0;
		while(k!=x){
			totalK += graph[k][parent[k]];
			//cout << "parent k: " << parent[k]+1 << endl;
			k = parent[k];
			if (ancestors[k]) break;
		}

		total += 2*totalK;
		//cout << "TotalK: " << totalK << endl;
	}

	return total;
} 
