		graph[a-1][b-1] = c;
		graph[b-1][a-1] = c;
	}

	int Q, K;
	cin >> Q >> K;
	while(Q--){
		int x, y;
		cin >> x >> y;
		cout << solve(x-1,y-1,K-1) << endl;
	}
}

