    int to;
    long long cost;
    edge(const int to_, const long long cost_):to(to_), cost(cost_){}
};

using Graph = vector<vector<edge>>;

vector<long long> bfs(const Graph& G, const int s){
    vector<long long> d(G.size(), LONG_MAX);
    queue<int> q;
    q.push(s);
    d[s] = 0;
    vector<bool> visited(G.size(), false);

    while(!q.empty()){
        const int current_v = q.front();
        q.pop();
        visited[current_v] = true;

        for(const auto& e : G[current_v]){
            if(visited[e.to]) continue;
            q.push(e.to);
            d[e.to] = d[current_v] + e.cost;
        }
    }

    return d;
}

int main(){
    int n; cin >> n;

    Graph G(n);
    for(int i = 0; i < n-1; ++i){
        int a, b; 
        long long c;
        cin >> a >> b >> c;
        a--; b--;

        G[a].emplace_back(edge(b, c));
        G[b].emplace_back(edge(a, c));
    }

    int q, k; cin >> q >> k;
    k--;

    vector<long long> d = bfs(G, k);

    for(int i = 0; i < q; ++i){
        int x, y; cin >> x >> y;
        x--; y--;

        cout << d[x] + d[y] << endl;
    }

    return EXIT_SUCCESS;
}

