typedef vector<pii> vpii;

/* global variables */

vpii nbrs[MAX_N];
ll ds[MAX_N];

/* subroutines */

/* main */

int main() {
  int n;
  scanf("%d", &n);

  for (int i = 1; i < n; i++) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    a--, b--;
    nbrs[a].push_back(pii(b, c));
    nbrs[b].push_back(pii(a, c));
  }

  int m, k;
  scanf("%d%d", &m, &k);

  k--;
  ds[k] = 0;
  queue<pii> q;
  q.push(pii(k, -1));

  while (! q.empty()) {
    pii u = q.front(); q.pop();
    int &ui = u.first, &up = u.second;

    vpii &nbru = nbrs[ui];
    for (vpii::iterator vit = nbru.begin(); vit != nbru.end(); vit++) {
      int &vi = vit->first;
      if (vi != up) {
	ds[vi] = ds[ui] + vit->second;
	q.push(pii(vi, ui));
      }
    }
  }

  while (m--) {
    int x, y;
    scanf("%d%d", &x, &y);
    x--, y--;
    printf("%lld\n", ds[x] + ds[y]);
  }

  return 0;
}

