int main()
{
	int32_t N;
	scanf("%d", &N);

	vector<pair<int64_t, int32_t>> graph[1000];
	for (int32_t i = 0; i < N - 1; i++) {
		int32_t a, b;
		int64_t c;
		scanf("%d%d%" PRId64, &a, &b, &c);
		a--;
		b--;
		graph[a].push_back(make_pair(c, b));
		graph[b].push_back(make_pair(c, a));
	}

	int32_t Q, K;
	scanf("%d%d", &Q, &K);
	K--;

	int64_t d[1000];
	for (int32_t i = 0; i < N; i++) {
		d[i] = numeric_limits<int64_t>::max();
	}
	priority_queue<pair<int64_t, int32_t>, vector<pair<int64_t, int32_t>>, greater<pair<int64_t, int32_t>>> q;
	q.push(make_pair(0, K));
	d[K] = 0;
	while (!q.empty()) {
		pair<int64_t, int32_t> temp = q.top(); q.pop();
		int32_t node = temp.second;

		if (d[node] < temp.first)
			continue;

		for (int32_t i = 0; i < (int32_t)graph[node].size(); i++) {
			int32_t next_cost = graph[node][i].first;
			int32_t next_node = graph[node][i].second;
			if (d[next_node] > d[node] + next_cost) {
				d[next_node] = d[node] + next_cost;
				q.push(make_pair(d[next_node], next_node));
			}
		}
	}

	for (int32_t i = 0; i < Q; i++) {
		int32_t x, y;
		scanf("%d%d", &x, &y);
		x--;
		y--;
		printf("%" PRId64 "\n", d[x] + d[y]);
	}

	return 0;
}

