int par[25][200000];

void dfs(int b, int pr = -1, int D = 0){
	for (auto &i : E[b]){
		if (i.second == pr)continue;
		dfs(i.second, b, D + i.first);
	}
	d[b] = D;
	par[0][b] = pr;
}
#define MAX_LOG 22
int lca(int a, int b){
	if (d[a] < d[b]){
		swap(a, b);
	}
	for (int i = 0; i < MAX_LOG; i++){
		if (((d[a] - d[b]) >> i) & 1){
			a = par[i][a];
		}
	}
	if (a == b){
		return a;
	}
	for (int i = MAX_LOG - 1; i >= 0; i--){
		if (par[i][a] != par[i][b]){
			a = par[i][a];
			b = par[i][b];
		}
	}
	return par[0][a];
}
ll dist(int x,int y){
	return d[x]+d[y]-d[lca(x,y)]*2;
}
int main(){
	int n;scanf("%d",&n);
	rep(i,n-1){
		int a,b,c;scanf("%d%d%d",&a,&b,&c);a--;b--;
		E[a].push_back(P(c,b));E[b].push_back(P(c,a));
	}
	dfs(0,-1,0);
	for (int i = 0; i + 1 < MAX_LOG; i++){
		for (int j = 0; j < n; j++){
			if (par[i][j] == -1){
				par[i + 1][j] = -1;
				continue;
			}
			par[i + 1][j] = par[i][par[i][j]];
		}
	}
