int main() {
    ll n;
    cin >> n;
    vector<queue<ll>> g(n);
    map<P, ll> graph;

    rep(i, n-1) {
        ll a, b, c; cin >> a >> b >> c;
        a--; b--;
        graph[P(a,b)] = c;
        graph[P(b,a)] = c;
        g[a].push(b);
        g[b].push(a);
    }

    vector<ll> d(n, INF);
    ll q, k; cin >> q >> k;
    k--;
    d[k] = 0;
    queue<ll> que;
    que.push(k);
    while(!que.empty()) {
        ll t = que.front();
        que.pop();
        while(!g[t].empty()) {
            ll nx = g[t].front();
            g[t].pop();
            if(d[nx] == INF) {
                que.push(nx);
                d[nx] = d[t]+graph[P(t,nx)];
            }
        }
    }
