vector<ll> dist(vector<vector<P>> G, ll N, ll K){
    vector<ll> dist(N);
    vector<ll> visit(N, 0);
    dist[K] = 0;

    stack<P> sk;
    sk.push({K, 0});
    while(!sk.empty()){
        P n = sk.top();
        ll now = n.first;
        sk.pop();
        if(visit[now]) continue;
        visit[now] = 1;
        dist[now] = n.second;

        for(auto e : G[now]) if(!visit[e.first]) sk.push({e.first, n.second + e.second});
    }

    return dist;
}

