};
//
int N;
//経路
vector<vector<Edge>> edgeMap(100001);
//Kからの距離
ll minD[100001];

//全都市のKからの距離を計算
//K,およびその先から伸びるすべての辺を探索。最大でも10000回ですむはず
void calcFromK(int k) {
    list<Data> queue;
    queue.push_back({-1, k, 0});

    while (queue.size() > 0) {
        Data d = queue.front();
        queue.pop_front();
        //都市 d.curr から伸びている辺を全部あさる。ただし来た道は除外
        auto arr = edgeMap[d.index];
        minD[d.index] = d.distanceFromK;
        for (auto e: arr) {
            if (e.to != d.from) {
                queue.push_back({d.index, e.to, e.distance + d.distanceFromK});
            }
        }
    }
}
//x -> k -> yな距離を計算
ll solve(int x, int y, int k) {
    return minD[x] + minD[y];
}

