	last[u] = all;
	other[all] = v;
	cost[all] = w;
}

queue<int> sq;

void spfa(int x, int n){
	for(int i = 1; i <= n; i++) dis[i] = 1 << 30;
	dis[x] = 0;
	memset(vis, 0, sizeof(vis));
	sq.push(x);
	int now = x, dr, ed;
	while(sq.size()){
		now = sq.front();
		ed = last[now];
		vis[now] = 1;
		while(ed != -1){
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr]){
				dis[dr] = dis[now] + cost[ed];
				if(!vis[dr]){
					sq.push(dr);
				}
			}
			ed = pre[ed];
		}
		vis[now] = 0;
		sq.pop();
	}
}

