lli dist(int x, int y, vector<int>& origs) {
    if (mat[x][y] == -1) {
        lli d_min = -1;
        for(int i = 0; i < n; i++) {
            if (find(origs.begin(), origs.end(), i) != origs.end() || i == x) continue;
            if (mat[x][i] != -1) {
                origs.push_back(x);
                lli d_tmp = dist(i, y, origs);
                if (d_tmp == -1) {
                    continue;
                }
                d_tmp += mat[x][i];
                if (d_min == -1) d_min = d_tmp;
                else d_min = min(d_min, d_tmp);
            }
        }
        mat[x][y] = mat[y][x] = d_min;
    }
    return mat[x][y];
}

