using ll = long long;
using namespace std;
ll djikstra(int s, int g, int n, vector<vector<pair<int,ll>>> &root){
  priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> que;
  // <最短距離, 頂点>
  que.push(make_pair(0, s)); //0 をスタート地点として距離を0とする
  vector<ll> distance(n, -1);
  distance[s] = 0;
  while(!que.empty()){
    pair<ll,int> info = que.top();
    que.pop();
    int pos = info.second;
    if(distance[pos] < info.first) continue;
    for(pair<int,ll> x : root[pos]){
      int next = x.first;
      ll kyori = x.second + distance[pos];
      if(distance[next] == -1 || distance[next] > kyori){
        que.push(make_pair(kyori, next));
        distance[next] = kyori;
      }
    }
  }
  return distance[g];
}
int main(){
  int n;
  cin >> n;
  vector<vector<pair<int, ll>>> root(n);
  rep(i, n - 1){
    int a,b,c; // 0 ~
