void dijkstra(int x) {
    priority_queue<P, vector<P>, greater<P>> q;
    q.push(P(0, x));
    dist[x] = 0; 
    while (!q.empty()) {
        auto p = q.top();
        q.pop();
        int v = p.second;
        if (dist[v] < p.first) continue;
        for (int i = 0; i < tree[v].size(); ++i) {
