            if (contains(origs.begin(), origs.end(), i) || i == x || i == y) continue;
            if (mat[x][i] != -1) {
                //cerr << "FIND " << x << " -> " << i << " -> " << y << endl;
                lli d_tmp = dist(i, y, origs);
                if (d_tmp == -1) {
                    continue;
                }
                d_tmp += mat[x][i];
                if (d_min == -1) d_min = d_tmp;
                else d_min = min(d_min, d_tmp);
            }
        }
        mat[x][y] = mat[y][x] = d_min;
    }
    //cerr << "RESULT(" << mat[x][y] << ") " << s << endl;
    return mat[x][y];
}

