vector <pair<int, long long>> graph[100001];
vector <pair<int, int>> query;

long long dfs(int start, int end)
{
	long long res = 0;
	stack <pair<int,long long>> s;
	bool visited[100001] = { false, };
	s.push(make_pair(start,0));
	while (!s.empty())
	{
		int edge = s.top().first;
		long long dist = s.top().second;
		bool flag = false;
		if (visited[edge] == false)
		{
			visited[edge] = true;
			res += dist;
		}
		if (edge == end)
		{
			break;
		}

		for (auto v : graph[edge])
		{
			if (visited[v.first] == false)
			{
				flag = true;
				s.push(make_pair(v.first,v.second));
			}
		}

		if (flag == false)
		{
			res -= s.top().second;
			s.pop();
		}
	}
	return res;
}
int main(void)
{
	ifstream ifs;
	int n, q, k;
	int a, b;
	long long c;

	ifs.open("test.txt");
	ifs >> n;

	for (int i = 0; i < n-1; i++)
	{
		ifs >> a >> b >> c;
		graph[a].push_back(make_pair(b, c));
		graph[b].push_back(make_pair(a, c));
	}

	ifs >> q >> k;
	for (int i = 0; i < q; i++)
	{
		ifs >> a >> b;
		query.push_back(make_pair(a, b));
	}

	for (auto q : query)
	{
		long long num = 0;
		num += dfs(q.first, k);
		num += dfs(k, q.second);

		cout << num << endl;
	}

	return 0;
}

