		dep[to]=new_cost;
		dfs(to,v);
	}
	++timer;
	tout[v]=timer;
}

bool upper(int a,int b)
{
	return tin[a]<=tin[b]&&tout[a]>=tout[b];
}

long long lca(long long a,long long b)
{
	if (upper(a,b))
		return a;
	if (upper(b,a))
		return b;
	for (int i=19;i>=0;--i)
	{
		if (!upper(up[a][i],b))
			a=up[a][i];
	}
	return up[a][0];
}

long long solve(int a,int b)
{
	long long Q=lca(a,b);
	return dep[a]+dep[b]-2*dep[Q];
}

