void calcFromK(int from, int curr, ll distance) {
    minD[curr] = distance;

    //都市 d.curr から伸びている辺を全部あさる。ただし来た道は除外
    auto arr = edgeMap[curr];
    for (auto &e: arr) {
        if (e.to != from) {
            calcFromK(curr, e.to, distance + e.distance);
        }
    }
}
