void dfs(int u,int f){
    dep[u]=(f==-1?1:dep[f]+1);
    for (int i=0;i<(int)G[u].size();i++){
        Edge&e=edges[G[u][i]];
        int v=e.To(u);
        if (v==f) continue;
        dis[v]=dis[u]+1LL*e.w;
        parent[v][0]=u;
        dfs(v,u);
    }
}
void initLCA(){
    for (int k=0;k<19;k++){
        for (int v=1;v<=n;v++){
            if (parent[v][k]<0) continue;
            parent[v][k+1]=parent[parent[v][k]][k];
        }
    }
}
int lca(int u,int v){
    if (dep[u]>dep[v]) swap(u,v);
    for (int k=0;k<20;k++){
        if (((dep[v]-dep[u])>>k)&1) v=parent[v][k];
    }
    if (u==v) return u;
    for (int k=19;k>=0;k--){
        if (parent[u][k]!=parent[v][k]){
            u=parent[u][k];
            v=parent[v][k];
        }
    }
    return parent[u][0];
}
