        a--;b--;
        dk.add(a,b,c);
        dk.add(b,a,c);
    }

    ll q,k;
    cin>>q>>k;
    k--;
    dk.dijkstra(k);
    rep(i,q){
        ll x,y;
        cin>>x>>y;
        x--;y--;
        cout<<dk.d[x]+dk.d[y]<<endl;
    }


}

