using namespace std;
#define GRAPH_SIZE (100000 + 1)
static vector<pair<uint32_t, uint32_t>> graph[GRAPH_SIZE];
static uint64_t distances[GRAPH_SIZE];
static bool status[GRAPH_SIZE];

void init_graph()
{
  for (uint32_t i = 0; i < GRAPH_SIZE; i++) {
    distances[i] = UINT64_MAX;
    status[i] = false;
  }
}

void calc_distances(uint32_t N)
{
  while (true) {
    uint32_t min_index;
    uint64_t min_distance = UINT64_MAX;

    for (uint32_t i = 0; i < N; i++) {
      if ((distances[i] < min_distance) && (!status[i])) {
        min_index = i;
        min_distance = distances[i];
      }
    }

    if (min_distance == UINT64_MAX) break;
    status[min_index] = true;
    for (uint32_t i = 0; i < graph[min_index].size(); i++) {
      pair<uint32_t, uint32_t> vertex = graph[min_index][i];
      uint32_t to = vertex.first;
      uint32_t weight = vertex.second;
      distances[to] = min(distances[to], min_distance + weight);
    }
  }
}

int32_t main()
{
  init_graph();

  uint32_t N;
  cin >> N;

  for (uint32_t i = 0; i < (N - 1); i++) {
    uint32_t a, b, c;
    cin >> a >> b >> c;
    graph[a].push_back(make_pair(b, c));
    graph[b].push_back(make_pair(a, c));
  }

  uint32_t Q, K;
  cin >> Q >> K;

  distances[K] = 0;
  calc_distances(N);

  for (uint32_t i = 0; i < Q; i++) {
    uint32_t x, y;
    cin >> x >> y;
    cout << distances[x] + distances[y] << endl;
  }

  return 0;
}

