struct edge
{
  int to, cost;
  edge(int t,int c){
		to=t;
		cost=c;
	}
	edge(){}
};

LL add(LL a,LL b){
  return (a+b)%mod;
}

typedef vector< vector < edge > > Graph;//隣接リスト

int min_path[100010]={};//sからの最短経路数
template< typename T = LL >
vector< T > Dijkstra(Graph &g, int s)//始点sから各点までの最短距離を保持したvectorを返す&
                                     //min_pathに始点sから各点までの最短経路数
{
  typedef pair< T, int > Pi;//cost,from
  vector< T > min_cost(g.size(), numeric_limits< T >::max());
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;//Pi:cost,from
  que.emplace(0, s);
  min_cost[s] = 0;
  min_path[s]=1;
  while(!que.empty()) {
    Pi p = que.top();
    que.pop();
    if(p.first > min_cost[p.second]) continue;
    for(auto &e : g[p.second]) {
      if(p.first + e.cost > min_cost[e.to]) continue;
			if(p.first + e.cost == min_cost[e.to]){
        min_path[e.to]=add(min_path[p.second],min_path[e.to]);//最短距離が同じだったら経路数は和
				//min_path[e.to]=min_path[p.second]+min_path[e.to];//modなし
			}else {
				min_path[e.to]=min_path[p.second];//最短距離更新->最短経路更新
        min_cost[e.to] = p.first + e.cost;
        que.emplace(min_cost[e.to], e.to);
			}
    }
  }
  return (min_cost);
}

