using namespace std;
typedef long long ll;
typedef pair<ll, int> P;
const int MAXN = (int)1e5 + 5;
const ll INF = (ll)1e18;

vector<P> G[MAXN];
ll dist[MAXN];

void dijkstra(int s) {
  for (int i = 0; i < MAXN; ++i) dist[i] = INF;
  priority_queue<P, vector<P>, greater<P> > q;
  dist[s] = 0;
  q.push(P(0, s));
  while (!q.empty()) {
    P cur = q.top(); q.pop();
    ll d = cur.first;
    int v = cur.second;
    if (d > dist[v]) continue;
    for (P next: G[v]) {
      ll d2 = next.first + d;
      int u = next.second;
      if (d2 < dist[u]) {
	dist[u] = d2;
	q.push(P(d2, u));
      }
    }
  }
}

