    G[a].push_back(P(c, b));
    G[b].push_back(P(c, a));
  }

  int q, k;
  scanf("%d %d", &q, &k);
  k--;
  dijkstra(k);
  ll ans[q];
  for (int i = 0; i < q; ++i) {
    int x, y;
