const int N=200050;
struct node
{
	long long int to,next,c;
}e[N];
long long int first[N],dep[N],visit[N];
long long int fa[N][30],dis[N];
int cnt=0;
void insert(int u,int v,int c)
{
	e[++cnt].to=v;e[cnt].next=first[u];first[u]=cnt;e[cnt].c=c;
	e[++cnt].to=u;e[cnt].next=first[v];first[v]=cnt;e[cnt].c=c;
}
void dfs(int x)
{
	visit[x]=1;
	for(int i=1;(1<<i)<=dep[x];i++)
		fa[x][i]=fa[fa[x][i-1]][i-1];
	for(int k=first[x];k;k=e[k].next)	
	if(!visit[e[k].to])
	{
		fa[e[k].to][0]=x;
		dep[e[k].to]=dep[x]+1;
		dis[e[k].to]=dis[x]+e[k].c;
		dfs(e[k].to);
	}
}
int lca(int x,int y)
{
	if(dep[x]<dep[y])	std::swap(x,y);
	int t=dep[x]-dep[y];
	for(int i=0;(1<<i)<=t;i++)
	if((1<<i)&t)	x=fa[x][i];

	for(int i=25;i>=0;i--)
	if((1<<i)<=dep[x]&&fa[x][i]!=fa[y][i])
	x=fa[x][i],y=fa[y][i];
	if(x==y)	return x;
	return fa[x][0];
}
int main()
{
	long long int n;	
	scanf("%lld",&n);
	int v,u,c;
	for(int i=2;i<=n;i++)		scanf("%d %d %d",&v,&u,&c),insert(v,u,c);
	dfs(1);
	int m,k;
	scanf("%d %d",&m,&k);
	for(int i=1;i<=m;i++)
	{
		long long int x,y;
		scanf("%lld %lld",&x,&y);
		long long  lc=lca(x,k);
		long long ans=dis[x]+dis[k]-2*dis[lc];
		lc=lca(y,k);
		ans+=dis[y]+dis[k]-2*dis[lc];
		printf("%lld\n",ans);
	}
	return 0;	
}

