const int MAX = 100010;
const int WHITE = 1;
const int BLACK = 2;
const int GRAY = 3;
const ll INFTY = 1e11;

vector<pair<int, ll> > list[MAX];
ll dist[MAX];
int N;

void dijkstra(int K){
    priority_queue<pair<ll,int>, vector<pair<ll,int> >, greater<pair<ll,int> > > Q;
    for(int i=0;i<N;i++){
        dist[i] = INFTY;
    }

    dist[K] = 0;
    Q.push(make_pair(dist[K],K));

    while(!Q.empty()){
        auto f = Q.top(); Q.pop();
        int u = f.second;
        if(dist[u] < f.first) continue;

        for(int j=0;j<list[u].size();j++){
            auto e = list[u][j];
            if(dist[e.first] > dist[u] + e.second){
                dist[e.first] = dist[u] + e.second;
                Q.push(make_pair(dist[e.first],e.first));
            }
        }
    }
}

int main(){
    int K,Q;
    cin >> N;
    for(int i=0;i<N-1;i++){
        int a,b;
        ll c;
        cin >> a >> b >> c;
        a--;b--;
        list[a].push_back(make_pair(b,c));
        list[b].push_back(make_pair(a,c));
    }
    cin >> Q >> K;
    K--;
    dijkstra(K);
    for(int i=0;i<Q;i++){
        int x,y;
        cin >> x >> y;
        x--; y--;
        cout << dist[x] + dist[y] << endl;
    }
    return 0;
}

