void dijkstra(int64_t s){
  // first:最短距離 second:頂点番号
  priority_queue<pii, vector<pii>, greater<pii>> q; 
  dist[s] = 0; q.push(pii(0,s));

  while(!q.empty()){
    int64_t cur_d = q.top().first;
    int64_t cur_v = q.top().second;
    q.pop();

    if(cur_d > dist[cur_v]) continue;

    for(int64_t i=0; i<tree[cur_v].size(); i++){
      edge e = tree[cur_v][i];
      if(dist[cur_v] + e.cost < dist[e.to]){
        dist[e.to] = dist[cur_v] + e.cost;
        q.push(pii(dist[e.to], e.to));
      }
    }
  }
}


