int main()
{
    unsigned long long N;
    cin >> N;
    /*vector<unsigned long long> tmpVec(N, 0);
    vector<vector<unsigned long long>> pathVec(N, tmpVec);*/
    unordered_map<unsigned long long, vector<unsigned long long>> pathMap;
    unordered_map<unsigned long long, vector<unsigned long long>> CheckMap;

    unsigned long long a, b, c;
    for (unsigned long long i = 0; i < N - 1; i++)
    {
        cin >> a >> b >> c;
        a--;
        b--;
        pathMap[a].push_back(c);
        pathMap[b].push_back(c);
        CheckMap[a].push_back(b);
        CheckMap[b].push_back(a);
    }

    unsigned long long Q, K;
    cin >> Q >> K;
    K--;
    unsigned long long x, y;

    stack<PathData> PDStack;
    unordered_set<unsigned long long> CheckSet;
    unordered_map<unsigned long long, unsigned long long> CostMap;

    for (int i = 0; i < CheckMap[K].size(); i++)
    {
        PathData pd;
        pd.from = K;
        pd.to = CheckMap[K][i];
        pd.cost = pathMap[K][i];
        PDStack.push(pd);
    }
    CheckSet.emplace(K);

    while (!PDStack.empty())
    {
        PathData pd = PDStack.top();
        PDStack.pop();
        CostMap[pd.to] = pd.cost;

        for (int i = 0; i < CheckMap[pd.to].size(); i++)
        {
            if (CheckSet.find(CheckMap[pd.to][i]) == CheckSet.end())
            {
                PathData pd_new;
                pd_new.from = pd.to;
                pd_new.to = CheckMap[pd.to][i];
                pd_new.cost = pd.cost + pathMap[pd.to][i];
                PDStack.push(pd_new);
            }
        }
        CheckSet.emplace(pd.to);
    }

    for (unsigned long long i = 0; i < Q; i++)
    {
        cin >> x >> y;
        x--;
        y--;

        cout << CostMap[x] + CostMap[y] << endl;
    }
    return 0;
}

