    int left=0,right=min(ap.size(),bp.size())-1;

    while(right - left > 1){
        int mid=(right+left)/2;
        if(bp[mid] == ap[mid])left=mid;
        else right = mid;
    }
    int lcav=ap[left];
    int dlca = dist[lcav];

    return dlca;
}



