{
    int n;
    cin >> n;

    SparseGraph<> graph;
    for (int i = 0; i < n; i++)
    {
        graph.push_node(i);
    }

    for (int i = 0; i < n - 1; i++)
    {
        size_t a, b, c;
        cin >> a >> b >> c;
        graph.connect(a - 1, b - 1, c);
    }

    int q, k;
    cin >> q >> k;
    k--;

    std::vector<std::size_t> distance_from_k(n, 0);
    bfs(graph, distance_from_k, k);

    for (int i = 0; i < q; i++)
    {
        int x, y;
        cin >> x >> y;
        cout << (distance_from_k[x - 1] + distance_from_k[y - 1]) << endl;
    }
}

