                if (cost[u.first] != -1) continue;
                cost[u.first] = cost[v] + u.second;
                if (u.first == K) {
                    memo[i] = cost[K];
                    break;
                }
                q.push(u.first);
            }
        }
    }

    vector<ll> ans(Q);
    REP(i, Q) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        ans[i] = memo[a] + memo[b];
    }

    REP(i, Q) {
        cout << ans[i] << endl;
    }
    return 0;
}

