const int MaxN = 2e5, MaxM = 4e5;
int n, all, Q, K;
int pre[MaxM + 5], last[MaxN + 5], other[MaxM + 5];
int seq[MaxN * 20 + 5];
bool Inseq[MaxN + 5];
LL cost[MaxM + 5], dis[MaxN + 5];

void Build(int x, int y, int w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Init()
{
	all = -1; memset(last, -1, sizeof(last));
	for (int i = 1; i <= n - 1; i++) {
		int u, v, w;
		scanf("%d%d%d", &u, &v, &w);
		Build(u, v, w); Build(v, u, w);
	}
}

void Spfa(int s) 
{
	int head = 1, tail = 0;
	memset(Inseq, 0, sizeof(Inseq));
	for (int i = 1; i <= n; i++) dis[i] = 1LL << 60;
	dis[s] = 0; seq[++tail] = s; Inseq[s] = true;
	while (head <= tail) {
		int now = seq[head];
		int ed = last[now], dr;
		while (ed != -1) {
			dr = other[ed];
			if (dis[now] + cost[ed] < dis[dr]) {
				dis[dr] = dis[now] + cost[ed];
				if (!Inseq[dr]) {
					Inseq[dr] = true;
					seq[++tail] = dr;
				}
			}
			ed = pre[ed];
		}	
		head++;
		Inseq[now] = 0;
	}
}


void Solve()
{
	scanf("%d%d", &Q, &K);
	Spfa(K);
	for (int i = 1; i <= Q; i++) {
		int u, v; scanf("%d%d", &u, &v);
		printf("%lld\n", dis[u] + dis[v]);
	}
}

int main()
{
	while (~scanf("%d", &n)) {
		Init();
		Solve();
	}
	return 0;	
}

