		dis[sum[i].to][0]=sum[i].wi;
		dfs(sum[i].to);
	}
}
LL lca(int x,int y)
{
	LL vv=0;
	if(deep[x]>deep[y])swap(x,y);
	int d=deep[y]-deep[x];
	for(int i=0;(1<<i)<=d;i++)
		if((1<<i)&d){
			vv+=dis[y][i];
			y=gr[y][i];

		}
	if(x==y)return vv;
	for(int i=20;i>=0;i--){
		if(gr[x][i]!=gr[y][i]){
			vv+=dis[x][i]+dis[y][i];
			x=gr[x][i];y=gr[y][i];
		}
	}
	vv+=dis[x][0]+dis[y][0];
	return vv;
}
