using namespace std;
struct Edge {
    ll to;     // 辺の行き先
    ll weight; // 辺の重み
    Edge(int t, int w) : to(t), weight(w) { }
};
using Graph = vector<vector<Edge>>;

int main() {
    // 頂点数と辺数
    ll N, M;
    cin >> N;
    M=N-1;

    // グラフ入力受取 (ここでは無向グラフを想定)
    Graph G(N);
    for (ll i = 0; i < M; ++i) {
        ll a, b,c;
        cin >> a >> b>>c;
        a--;
        b--;
        G[a].push_back(Edge(b, c));
        G[b].push_back(Edge(a, c));
    }

    ll Q,K;
    cin>>Q>>K;
    K--;

    // BFS のためのデータ構造
    vector<ll> dist(N, -1); // 全頂点を「未訪問」に初期化
    queue<ll> que;

    // 初期条件 (頂点 K を初期ノードとする)
    dist[K] = 0;
    que.push(K); // K を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop();

        // v から辿れる頂点をすべて調べる
        for (auto nv : G[v]) {
            if (dist[nv.to] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv.to] = dist[v] + nv.weight;
            que.push(nv.to);
        }
    }

    // 結果出力 (各頂点の頂点 0 からの距離を見る)
    //for (int v = 0; v < N; ++v) cout << v << ": " << dist[v] << endl;

    FOR(i,0,Q-1){
      ll x,y;
      cin>>x>>y;
      x--;y--;
      cout<<dist[x]+dist[y]<<endl;
    }

}

