map<P,int> mp;
vector<int> to[100100];
vector<int> ord;
int depth[100100];
int first[100100];
int pa[100100];

void dfs(int i, int pa, int d) {
    first[i] = ord.size();
    depth[i] = d;
    ord.push_back(i);
    for (auto p : to[i]) {
        if (p == pa) continue;
        dfs(p,i,d+1);
        ord.push_back(i);
    }
}
int dist(int a, int rt) {
    int ret = 0;
    while (a != rt) {
        ret += mp[P(min(a,pa[a]),max(a,pa[a]))];
        a = pa[a];
    }
    return ret;
};

signed main() {
    int n; cin >> n;
    rep(i,n-1) {
        int a, b, c; cin >> a >> b >> c;
        a--; b--;
        mp[P(min(a,b),max(a,b))] = c;
        to[a].push_back(b);
        to[b].push_back(a);
    }

    dfs(0,-1,0);

    for (auto q : mp) {
        auto p = q.first;
        int f = p.first, s = p.second;
        if (depth[f] < depth[s]) swap(f,s);
        pa[f] = s;
    }

    // if lca(a, b) == lca(b, k)
    // swap(a, b)
    // if lca(a, b) == lca(a, k) 
    // a -> lca(a, b) -> lca(b, k) -> k -> lca(b, k) -> b
    // else 
    // a -> lca(a, b) -> lca(lca(a, b), k) -> k -> lca(lca(a, b), k) -> lca(a, b) -> b

    using X = P;
    auto fx = [](X x1, X x2) -> X {return min(x1,x2);};
    SegTree<X> seg(ord.size(), fx, P(INF,0));
    rep(i,ord.size()) seg.set(i,P(depth[ord[i]], ord[i]));
    seg.build();

    int q, k; cin >> q >> k;
    k--;
    rep(i,q) {
        int a, b; cin >> a >> b;
        a--; b--;
        auto lca = [&](int a, int b) {
            int l = min(first[a],first[b]);
            int r = max(first[a],first[b]);
            P qu = seg.query(l,r+1);
            return qu.second;
        };
        if (lca(a,b) == lca(b,k)) swap(a,b);

        if (lca(a,b) == lca(a,k)) {
            int rt = lca(a,b);
            int subrt = lca(b,k);
            int ans = dist(a,rt) + dist(subrt,rt) + dist(b,subrt) + dist(k,subrt) * 2;
            cout << ans << endl;
        }
        else {
            int rt = lca(a,k);
            int subrt = lca(a,b);
            int ans = dist(a,subrt) + dist(b,subrt) + dist(subrt,rt) * 2 + dist(k,subrt) * 2;
            cout << ans << endl;
        }
    }
    return 0;
}

