#define MAX 200005
typedef long long ll;

struct edge{
  ll to,cost;
};

ll n,a,b,c;
vector< edge > G[MAX];
ll size[MAX];
ll par[MAX];
ll dep[MAX];
ll dist[MAX];
ll depth[MAX];
ll parent[MAX];

void idfs(ll pos,ll prev=-1){
  ll m=-1;
  for(int i=0;i<(int)G[pos].size();i++){
    edge e=G[pos][i];
    if(e.to==prev)continue;
    dist[e.to]=dist[pos]+e.cost;
    depth[e.to]=depth[pos]+1;
    parent[e.to]=pos;

    idfs(e.to,pos);
    size[pos]+=size[e.to];
    if(m==-1||size[m]<size[e.to])m=e.to;
  }
  if(m>=0)par[m]=pos;
}

int dp[26][MAX];
void lca_init(){
  for(int i=0;i<n;i++)dp[0][i]=parent[i];
  for(int i=1;i<26;i++){
    for(int v=0;v<n;v++){
      int u=dp[i-1][v];
      if(u!=-1)u=dp[i-1][u];
      dp[i][v]=u;
    }
  }
}

int lca(int u,int v){
  if(depth[u]>depth[v])swap(u,v);

  int dist= depth[v]-depth[u];
  for(int i=0;i<30;i++)
    if( dist>>i & 1)
      v=dp[i][v];

  for(int I=25;I>=0;I--){
    if( dp[I][u] == dp[I][v] )continue;
    u=dp[I][u];
    v=dp[I][v];
  }
  return parent[u];
}


void init(){
  for(int i=0;i<n-1;i++){
    ll a,b,c;
    cin>>a>>b>>c;
    a--,b--;
    G[a].push_back( (edge){b,c} );
    G[b].push_back( (edge){a,c} );
  }
  parent[0]=-1;  
  idfs(0);

  lca_init();
}

ll Cal(ll a,ll b){
  ll ans=depth[a]+depth[b];
  ll target=lca(a,b);
  return ans-depth[target]*2;
}

int main(){
  cin>>n;
  init();
  ll q;
  cin>>q;
  ll K;
  cin>>K;
  K--;
  while(q--){
    cin>>a>>b;
    a--,b--;
    ll ans=Cal(a,K) + Cal(K,b);
    cout<<ans<<endl;
  }
  return 0;
}

