        root[a].push_back(make_pair(c, b)), root[b].push_back(make_pair(c, a));
    }

    scanf("%d %d", &Q, &K);
    Dijkstra(K);
    for(int i = 0; i < Q; ++i){
        ll x, y; cin >> x >> y;
        printf("%d\n", dist[x] + dist[y]);
    }

    return 0;
}

