class Dijk {
public:
  vector<edge> G[100005];
  ll dist[100005];
  int used[100005];

  void dijk(int s, int V) {
    priority_queue<P,vector<P>,greater<P>> Q;
    rep(i, 0, V) dist[i] = INF;
    rep(i, 0, V) used[i] = 0;
    dist[s] = 0;
    Q.push({0, s});

    while(!Q.empty()) {
      P p = Q.top(); Q.pop();
      int v = p.second;
      if(used[v]) continue;
      used[v] = 1;
      for(auto &e : G[v]) {
        if(dist[e.to] > dist[v] + e.cost) {
          dist[e.to] = dist[v] + e.cost;
          Q.push({dist[e.to], e.to});
        }
      }
    }
  }
};


