vector<edge> ev[100010];
ll k;
ll kc[100010];
ll recur(ll start,ll from, ll next,ll cost) {

	if (kc[start] > 0) {
		return kc[start];
	}
	if (next == k) {
		kc[start] = cost;
		return cost;
	}

	ll sum = 0;
	for (size_t i = 0; i < ev[next].size(); i++)
	{
		if (ev[next][i].to == from) continue;
		sum += recur(start,next,ev[next][i].to, cost + ev[next][i].cost);
	}
	return sum;
}
void TransitTreePath() {
	int n;
	cin >> n;
	for (size_t i = 0; i < n - 1; i++)
	{
		ll a, b, c;
		cin >> a >> b >> c;
