		e.cost = c;
		ev[a].push_back(e);
		edge e2;
		e2.to = a;
		e2.cost = c;

		ev[b].push_back(e2);
	}

	ll q;
	cin >> q >> k;
	for (int i = 1; i <= n; i++)
	{
		if (i == k) continue;
		recur(i,i, i, 0);
	}

	for (size_t i = 0; i < q; i++)
	{
		ll x, y;
		cin >> x >> y;
		cout << (kc[x] + kc[y]) << endl;
	}
}
