int solve() {
  ll n,q,k;
  cin >> n;
  vector<vector<edge> > tree(n);
  for(ll i = 0;i < n - 1; i++){
    ll a,b,c;
    cin >> a >> b >> c;
    a--;
    b--;
    edge tmp;
    tmp.to = b;
    tmp.cost = c;
    tree[a].push_back(tmp);
    tmp.to = a;
    tmp.cost = c;
    tree[b].push_back(tmp);
  }
  cin >> q >> k;
  k--;
  // dfs
  vector<ll> d(n);
  vector<ll> res(q);
  vector<bool> visit(n, false);
  stack<ll> stk;
  stk.push(k);
  ll cost = 0;
  while(!stk.empty()){
    ll now = stk.top();
    for(ll i = 0;i < tree[now].size(); i++){
      if(visit[tree[now][i].to]){
        if(!stk.empty())
          stk.pop();
        continue;
      }
      if(d[tree[now][i].to] == 0){
        d[tree[now][i].to] += tree[now][i].cost + d[now];
        stk.push(tree[now][i].to);
        visit[now] = true;
      }
    }
  }
  vector<ll> x(q),y(q);
  for(ll i = 0; i < q; i++){
    ll x,y;
    cin >> x >> y;
    x--; y--;
    cout << d[x] + d[y] << endl;
  }
  return 0;
}


int main(void){
  solve();
  return 0;
}

