const ll MAX_N = 100005;
ll n, q, k, a, b, c, x, y;
ll depth[MAX_N];
gr tree[MAX_N];

void dfs(ll now, ll prev, ll all_cost){
    depth[now] = all_cost;
    items(e, tree[now]){
        if (e.to == prev) continue;
        dfs(e.to, now, all_cost + e.cost);
    }
}

