void spfa(long long v0)
{
	long long i;
	bool visited[maxnum];
	for(i = 1; i <= n; i++)
	{
		dist[i] = INF;
		visited[i] = false;
		/*cout << dist[i] << endl;*/
	}
	queue<long long>Q;
	Q.push(v0);
	visited[v0] = true;
	dist[v0] = 0;
	while(!Q.empty())
	{
		long long u = Q.front();
		Q.pop();
		visited[u] = false;
		long long k = first[u];
		while(k != -1)
		{
			long long v = e[k].w;
			long long val = e[k].h;
			if(dist[v] >= dist[u] + val)
			{
				if(dist[v] > dist[u] + val)
				{
					dist[v] = dist[u] + val;
					if(!visited[v])
					{
						Q.push(v);
						visited[v] = true;
					}
				}
			}
			k = Next[k];
		}
	}
}
