struct Edge {
    int to;
    ll weight;
    Edge(int t, ll w) : to(t), weight(w) { }
};
using Graph = vector<vector<Edge>>;

vector<bool> seen;
vector<ll> depth;
void dfs(const Graph &G, int v) {
    seen[v] = true;

    for (auto next_v : G[v]) { 
        if (seen[next_v.to]) continue;
		depth[next_v.to] = depth[v] + next_v.weight;
        dfs(G, next_v.to);
    }
}

void Main() {
	int N; cin >> N;
	Graph G(N);
	REP(i, N - 1) {
