        G[from].push_back(Edge(to, weight));
		G[to].push_back(Edge(from, weight));
	}
	int Q, K; cin >> Q >> K;
	--K;
	seen.assign(N, false);
	depth.assign(N, -1);
	depth[K] = 0;
    dfs(G, K);

	REP(i, Q) {
		int x, y; cin >> x >> y;
		--x; --y;
		cout << depth[x] + depth[y] << endl;
	}
}

