void dijkstra (int x) {
    priority_queue <PII, vector <PII>, greater<PII> > pq;
    PII p;
    int to, from;
    long long dist, dist1;
    dis[x] = 0;
    pq.push({0, x});
    while (!pq.empty()) {
        p = pq.top();
        pq.pop();
        from = p.second;
        dist = p.first;
        for (PII p1 : adj[from]) {
            to = p1.first;
            dist1 = p1.second;
            if (dis[to] > dist + dist1) {
                dis[to] = dist + dist1;
                pq.push({dis[to], to});
            }
        }
    }
}

