void dijkstra(int v0)
{
    int i,j,k;
    bool visited[MAX]={0};
    for(i=1;i<=n;i++)
    {
        if(matrix[v0][i]>0&&i!=v0)
        {
            dist[i]=matrix[v0][i];
            path[i]=v0;
        }
        else
        {
            dist[i]=INF;
            path[i]=-1;
        }
        visited[i]=false;
        path[v0]=v0;
        dist[v0]=0;
    }
    visited[v0]=true;
    for(i=2;i<=n;i++)
    {
        ll min=INF;
        int u;
        for(j=1;j<=n;j++)
        {
            if(visited[j]==false&&dist[j]<min)
            {
                min=dist[j];
                u=j;        
            }
        } 
        visited[u]=true;
        for(k=1;k<=n;k++)
        {
            if(visited[k]==false&&matrix[u][k]>0&&min+matrix[u][k]<dist[k])
            {
                dist[k]=min+matrix[u][k];
                path[k]=u; 
            }
        }        
    }    
}
