void init()
{
    memset(c, 0, sizeof(c));
    for(int i = 0; i < n; i++)
        G[i].clear();
    memset(d, MAX, sizeof(d));
    int i;
    long long x,y,v;
    for(i = 0; i < n-1; i++)
    {
        scanf("%lld%lld%lld", &x, &y, &v);
        node n1, n2;
