        G[x].push_back(n2);
        G[y].push_back(n1);
    }
}

void SPFA(long long x)
{
    queue<long long> q;
    q.push(x);
    c[x] = 1;
    while(!q.empty())
    {
        long long tmp = q.front();
        q.pop();
        c[tmp] = 0;
        for(int i = 0; i < G[tmp].size(); i++)
        {
            if(G[tmp][i].v + d[tmp] < d[G[tmp][i].n])
            {
                d[G[tmp][i].n] = G[tmp][i].v + d[tmp];
                if(!c[G[tmp][i].n])
                {
                    q.push(G[tmp][i].n);
                    c[G[tmp][i].n] = 1;
                }
            }
        }
    }
}

int main()
{
