// 木の根を適当に固定して、最近共通祖先を求める
// 二点間距離もいける
// 前処理 O( N log N )
// クエリ O( log N )
class LowestCommonAncestor
{
private:
	const int N;
	std::vector< VPII > G;

	bool constructed = false;
	std::vector<LL> depth_, distances_;
	std::vector< std::vector<int> > parent_;

public:
	LowestCommonAncestor( const int n ) : N( n ), G( N ), depth_( N ), distances_( N ), parent_( N, std::vector<int>( 31, -1 ) )
	{
		return;
	}

	void connect( const int u, const int v, const int d = 1 )
	{
		G[u].EB( v, d );
		G[v].EB( u, d );
		constructed = false;

		return;
	}

	int depth( const int u ) const
	{
		return depth_[u];
	}

	int solve( int u, int v )
	{
		if ( !constructed )
		{
			dfs( 0, -1, 0, 0 );
			doubling();
			constructed = true;
		}

		if ( depth_[u] < depth_[v] )
		{
			swap( u, v );
		}

		{ // align depths
			int diff = depth_[u] - depth_[v];
			for ( int i = 30; 0 <= i; --i )
			{
				if ( diff & 1 << i )
				{
					u = parent_[u][i];
				}
			}
		}

		if ( u == v )
		{
			return u;
		}

		for ( int i = 30; 0 <= i; --i )
		{
			if ( parent_[u][i] != parent_[v][i] )
			{
				u = parent_[u][i];
				v = parent_[v][i];
			}
		}

		return parent_[u][0];
	}

	LL distance( const int u, const int v )
	{
		const int w = solve( u, v );
		return distances_[u] + distances_[v] - 2 * distances_[w];
	}

private:
	void dfs( const int u, const int prev, const int d, const LL dist )
	{
		depth_[u] = d;
		parent_[u][0] = prev;
		distances_[u] = dist;

		for ( const PII &e : G[u] )
		{
			const int v = e.fst;
			if ( v == prev )
			{
				continue;
			}

			dfs( v, u, d + 1, dist + e.snd );
		}

		return;
	}

	void doubling()
	{
		for ( int i = 0; i < 30; ++i )
		{
			for ( int u = 0; u < N; ++u )
			{
				if ( parent_[u][i] != -1 )
				{
					parent_[u][ i + 1 ] = parent_[ parent_[u][i] ][i];
				}
			}
		}
		return;
	}
};
// LowestCommonAncestor( N )
// connect( u, v [, dist = 1 ] )
// solve( u, v )
// depth( u )
// distance( u, v )

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int N;
	scanf( "%d", &N );

	LowestCommonAncestor lca( N );
	REP( N - 1 )
	{
		int a, b, c;
		scanf( "%d%d%d", &a, &b, &c );
		--a, --b;

		lca.connect( a, b, c );
	}

	int Q, K;
	scanf( "%d%d", &Q, &K );
	--K;

	REP( Q )
	{
		int x, y;
		scanf( "%d%d", &x, &y );
		--x, --y;

		printf( "%lld\n", lca.distance( x, K ) + lca.distance( K, y ) );
	}

	fflush( stdout );


	return 0;
}

