void dijkstra(ll s,std::vector<std::vector<P>>& path,std::vector<ll>& ans){
    std::priority_queue<P,std::vector<P>,std::greater<P>> que;
    ans[s]=0;
    que.push(P(0,s));

    while(!que.empty()){
        P p = que.top();que.pop();
        int v = p.second;
        if(ans[v]<p.first){
            continue;
        }

        rep(i,0,path[v].size()){
            P e=path[v][i];
            if(ans[e.first] > ans[v] + e.second){
                ans[e.first]=ans[v]+e.second;
                que.push(P(ans[e.first],e.first));
            }
        }
    }
}


