#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define REP(i,n)  FOR(i,0,n)

#define LL long long
using EDGE = tuple<int, int, LL>;
using PII = pair<int, int>;

map<int, LL> cost_list;

void make_cost(vector<EDGE> &trees, int start) {
  queue<EDGE> que;
  int prev, now;
  LL cost, add;
  que.push(make_tuple(-1, start, 0));
  while(!que.empty()) {
    EDGE tmp = que.front();
    que.pop();
    prev = get<0>(tmp);
    now = get<1>(tmp);
    cost = get<2>(tmp);
    for(auto it=trees.begin(); it!=trees.end();) {
      int a = get<0>(*it);
      int b = get<1>(*it);
      if(a==now && prev!=b) {
        add = get<2>(*it);
        it = trees.erase(it);
        cost_list[b] = cost+add;
        que.push(make_tuple(a, b, cost+add));
      } else if(b==now && prev!=a) {
        add = get<2>(*it);
        it = trees.erase(it);
        cost_list[a] = cost+add;
        que.push(make_tuple(b, a, cost+add));
      } else
        it++;
    }
  }
}

int main() {
  int N;
  cin >> N;
  vector<EDGE> trees(N);
  REP(i, N-1) {
    int a, b;
    LL c;
    cin >> a >> b >> c;
    trees.at(i) = make_tuple(a, b, c);
  }

  int Q, K;
  cin >> Q >> K;
  make_cost(trees, K);
  REP(i, Q) {
    int x, y;
    cin >> x >> y;
    cout << cost_list.at(x) + cost_list.at(y) << endl;
  }
}

