    ll to, cost;
} Edge;

vector<vector<Edge>> g;
vector<bool> vi;
int k, num;

void dijkstra(vector<ll> &d, int s) {
    priority_queue<P, vector<P>, greater<P>> pq;
    d[s] = 0;
    // P<dist, v>
    pq.push({0,s});

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();
        int v = p.second;

        for(auto &&e: g[v]) {
            if (d[e.to] > d[v]+e.cost) {
                d[e.to] = d[v]+e.cost;
                pq.push({d[e.to], e.to});
            }
        }
    }
}

void dfs(vector<P> &b, int x, int dist) {
    if (vi[x]) return;
    vi[x] = true;
    for (auto &&e: g[x]) {
        b[x] = {num,dist};
        dfs(b, e.to, dist+1);
        if (k == x) ++num;
    }
}


