struct edge{
	int v; LL w;
};

vector<vector<edge>> adj;
vector<LL> dist;

void bfs(int root){
	queue<int> frontier;
	dist[root] = 0;
	frontier.push(root);
	while(not frontier.empty()){
		int here = frontier.front(); frontier.pop();
		for (edge& e : adj[here]){
			if (dist[e.v] == -1){
				dist[e.v] = dist[here] + e.w;
				frontier.push(e.v);
			}
		}
	}
}

