using namespace std;
int n,tot=1,q,k;
LL dis[N][20];
bool ok[N];
int deep[N],gr[N][20];
int first[N];
struct point{
	int to,next,wi;
}sum[N*2];
void add(int u,int v,int w)
{
	tot++;sum[tot].next=first[u];first[u]=tot;sum[tot].to=v;sum[tot].wi=w;
	tot++;sum[tot].next=first[v];first[v]=tot;sum[tot].to=u;sum[tot].wi=w;
}
void dfs(int x)
{
	ok[x]=1;
	for(int i=1;(1<<i)<=deep[x];i++){
			gr[x][i]=gr[gr[x][i-1]][i-1];
			dis[x][i]=dis[x][i-1]+dis[gr[x][i-1]][i-1];
	}
	for(int i=first[x];i;i=sum[i].next){
		if(ok[sum[i].to])continue;
		gr[sum[i].to][0]=x;
		deep[sum[i].to]=deep[x]+1;
		dis[sum[i].to][0]=sum[i].wi;
		dfs(sum[i].to);
	}
}
LL lca(int x,int y)
{
	LL vv=0;
	if(deep[x]>deep[y])swap(x,y);
	int d=deep[y]-deep[x];
	for(int i=0;(1<<i)<=d;i++)
		if((1<<i)&d){
			vv+=dis[y][i];
			y=gr[y][i];

		}
	if(x==y)return vv;
	for(int i=20;i>=0;i--){
		if((1<<i)<=deep[x]&&gr[x][i]!=gr[y][i]){
			vv+=dis[x][i]+dis[y][i];
			x=gr[x][i];y=gr[y][i];
		}
	}
	vv+=dis[x][0]+dis[y][0];
	return vv;
}
