void dij(int s,int n)
{
    for (int i = 0;i <= n;i++) d[i] = 10000000000000000;
    memset(vis,0,sizeof(vis));

    d[s] = 0;

    priority_queue<heapnode> q;

    heapnode t;
    t.d = 0;t.u = s;

    q.push(t);

    while (!q.empty())
    {
        heapnode x = q.top();q.pop();

        int u = x.u;

        if (vis[u]) continue;

        vis[u] = true;

        for (int i = 0;i < v[u].size();i++)
        {
            edge e = edges[v[u][i]];

            if (d[e.to] > d[u] + e.cost)
            {
                d[e.to] = d[u] + e.cost;

                heapnode tt;
                tt.u = e.to;t.d = d[e.to];

                q.push(tt);
            }
        }
    }
}

