/* dijkstra(G,s,dis)
    入力:グラフ G, 開始点 s,距離を格納する dis
    計算量 : O(|E|log|V|)
    副作用 : disが書き換えられる
*/
using Graph = vector<vector<Edge>>;
using P = pair<ll, int>;
void dijkstra(const Graph &G, int s, vector<ll> &dis, vector<int> &prev)
{
    int N = G.size();
    dis.resize(N, INF); // Gの大きさで初期化
    prev.resize(N, -1);
    priority_queue<P, vector<P>, greater<P>> pq; // [仮の最短経路,頂点]が小さい順で並ぶ
    dis[s] = 0;                                  //スタート地点の距離は0
    pq.emplace(dis[s], s);                       // スタート地点を代入
    while (!pq.empty())
    {
        P p = pq.top(); // 最短経路が一番小さいものを取得
        pq.pop();
        int V = p.second; // 頂点
        if (dis[V] < p.first)
        { // 最短経路で無い場合は無視
            continue;
        }
        for (auto &e : G[V])
        {
            if (dis[e.to] > dis[V] + e.cost)
            { //最短経路なら
                dis[e.to] = dis[V] + e.cost;
                prev[e.to] = V; //頂点vを通って　e.toにたどり着いた
                pq.emplace(dis[e.to], e.to);
            }
        }
    }
}

