// LCA
#define MAX_LOG_N 50
#define MAX_N 100010
struct LCA {
  vector<PII> G[MAX_N];  //グラフの隣接リスト {to, cost}

  PII parent[MAX_LOG_N][MAX_N];
  int depth[MAX_N];
  bool used[MAX_N];

  // modeが1→LCA modeが2→経路長 modeが3→最大の重み
  int mode;

  int func(int a, int b) {
    if(mode == 2) return a+b;
    if(mode == 3) return max(a, b);
    return 0;
  }

  void dfs(int v, int p, int d, int w) {
    // cout << v << " " << d << endl;
    used[v] = true;
    // 頂点pと頂点vの辺の重み
    parent[0][v] = {p, w};
    depth[v] = d;
    REP(i, G[v].size()) if(G[v][i].first != p) {
      dfs(G[v][i].first, v, d+1, G[v][i].second);
    }
  }
  // 8
  // 1 2 1
  // 1 3 1
  // 2 4 2
  // 2 5 3
  // 2 6 1
  // 3 7 4
  // 6 8 6
  // 初期化 O(nlogn)
  // modeが1→LCA modeが2→経路長 modeが3→最大の重み
  void init(int n, int m) {
    mode = m;
    REP(i, n) if(!used[i]) dfs(i, -1, 0, 0);
    REP(k, MAX_LOG_N-1) REP(v, n) {
      if(parent[k][v].first < 0) parent[k+1][v] = {-1, 0};
      else {
        PII tmp = parent[k][parent[k][v].first];
        if(tmp.first < 0) parent[k+1][v] = {-1, 0};
        else parent[k+1][v] = {tmp.first, func(parent[k][v].second, tmp.second)};
      }
    }
  }

  // uとvのlcaを求める
  int lca(int u, int v) {
    if(depth[u] > depth[v]) swap(u, v);
    // cout << depth[u] << " " << depth[v] << endl;
    int ret = 0;
    REP(k, MAX_LOG_N) {
      if((depth[v]-depth[u]) >> k & 1) {
        ret = func(ret, parent[k][v].second);
        v = parent[k][v].first;
        // cout << u << " " << v << " " << ret << endl;
      }
    }
    if(u == v) {
      if(mode == 1) return u;
      return ret;
    }
    for(int k = MAX_LOG_N-1; k>=0; k--) {
      // cout << parent[k][u].first << "," << parent[k][u].second << " " << parent[k][v].first << "," << parent[k][v].second << endl;
      if(parent[k][u] != parent[k][v]) {
        ret = func(ret, parent[k][u].second);
        ret = func(ret, parent[k][v].second);
        u = parent[k][u].first;
        v = parent[k][v].first;
        // cout << u << " " << v << " " << ret << endl;
      }
    }
    if(mode == 1) return parent[0][u].first;
    return ret + parent[0][u].second + parent[0][v].second;
  }
};
LCA lca;

