};


class Dijkstra{
public:
    ll n;//頂点数,辺数
    V<V<edge>> G;
    V<ll> d;
    V<ll> pr;

    explicit Dijkstra(ll sz_n){
        n=sz_n;
        G.resize(sz_n);
        d.resize(sz_n);
        pr.resize(sz_n);
    }

    void add_edge(ll from,ll to,ll cost){
        G[from].push_back((edge){to,cost});
        G[to].push_back((edge){from,cost});//有向辺の場合は削除
    }

    void exe(ll s){//頂点sからの最短距離
        priority_queue<PP,vector<PP>,greater<PP>> que;
        rep(i,n) d[i]=INF;
        d[s]=0;
        que.push(PP{0,s});//pair...first->最短距離、second->頂点

        while(!que.empty()){
            PP p=que.top();que.pop();
            ll v=p.vert;
            if(d[v]<p.min_d) continue;
            for(int i=0;i<(int)G[v].size();i++){
                edge e=G[v][i];
                if(d[e.to]>d[v]+e.cost){
                    d[e.to]=d[v]+e.cost;
                    que.push(PP{d[e.to],e.to});
                    pr[e.to]=v;
                }
            }
        }
    }

    ll dist_to(ll t){
        return d[t];
    }

    //頂点tへの最短路
    vector<ll> get_path(ll t){
        vector<ll> path;
        for(;t!=-1;t=pr[t]) path.push_back(t);//tがsになるまでprev[t]をたどっていく
        reverse(all(path));
        return path;
    }

};


