    vector<ll> dist(n+1, LLONG_MAX);
    dist[k] = 0;

    pque.push(make_pair(0, k));
    while(!pque.empty()){
        pair<int, int> p = pque.top();
        pque.pop();
        int v = p.second;
        if(dist[v] < p.first) continue;
        for(int i = 0; i < graph[v].size(); i++){
            edge e = graph[v][i];
            if(dist[e.to] > dist[v] + e.cost){
                dist[e.to] = dist[v] + e.cost;
                pque.push(make_pair(dist[e.to], e.to));
            }
        }
    }

    for(int i = 0; i < q; i++) cout << dist[x[i]] + dist[y[i]] << endl;

    return 0;
}

