void warshall_floyd(int n) { // nは頂点数
  for (int i = 1; i <= n; i++)      // 経由する頂点
    for (int j = 1; j <= n; j++)    // 開始頂点
      for (int k = 1; k <= n; k++){  // 終端
    	  if(i==j||j==k||i==k)continue;
        dist[j][k] = min(dist[j][k], dist[j][i] + dist[i][k]);
      }
}

