        G[b].push_back({a, c});
    }

    int q, k;
    cin >> q >> k;
    k--;
    dijkstra(k);

    REP(i, q) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        cout << d[x] + d[y] << endl;
    }


}

