pair<int, llong> lift[N][LOG];
int height[N];

void calc(int v, int p = -1, llong e = 0ll, int h = 0) {
    lift[v][0] = {(p == -1 ? v : p), (p == -1 ? 0ll : e)};
    height[v] = h;
    for (int i = 1; i < LOG; i++) {
        lift[v][i] = {lift[lift[v][i - 1].fi][i - 1].fi, lift[v][i - 1].se + lift[lift[v][i - 1].fi][i - 1].se};
    }
    for (auto u: tree[v]) {
        if (u.fi == p) {
            continue;
        }
        calc(u.fi, v, u.se, h + 1);
    }
}

llong get(int a, int b) {
    llong ans = 0;
    int iA = LOG - 1, iB = LOG - 1, iC = LOG - 1;
    while (height[a] > height[b]) {
        if (height[lift[a][iA].fi] >= height[b]) {
            ans += lift[a][iA].se;
            a = lift[a][iA].fi;
        }
        --iA;
    }
    while (height[b] > height[a]) {
        if (height[lift[b][iB].fi] >= height[a]) {
            ans += lift[b][iB].se;
            b = lift[b][iB].fi;
        }
        --iB;
    }
    while (a != b && iC >= 0) {
        if (lift[a][iC].fi != lift[b][iC].fi) {
            ans += lift[a][iC].se;
            ans += lift[b][iC].se;
            a = lift[a][iC].fi;
            b = lift[b][iC].fi;
        }
        iC--;
    }
    if (iC < 0) {
        ans += lift[a][0].se;
        ans += lift[b][0].se;
        a = lift[a][0].fi;
    }
    if (a != K) {
        ans += 2 * get(a, K);
    }
    return ans;
}

