typedef pair<ll, int> pr;

#define MAX 100000
#define WHITE 0
#define GRAY 1
#define BLACK 2
#define INF -1

int n, c[MAX];
ll d[MAX];
vector<pair<int, ll>> adj[MAX];

void dijkstra_init(){
	for(int i=0; i<n; i++){
		d[i]=INF;
		c[i]=WHITE;
	}
	return;
}

void dijkstra(int s){
	d[s]=0;
	priority_queue<pr, vector<pr>, greater<pr>> pq;
	pq.push(make_pair(0,s));
	c[s]=GRAY;

	while(!pq.empty()){
		pair<ll, int> f=pq.top();
		pq.pop();
		int u=f.second;
		c[u]=BLACK;
		if(d[u]<f.first && d[u]!=INF) continue;

		for(int j=0; j<adj[u].size(); j++){
			ll v=adj[u][j].first;
			if(c[v]==BLACK) continue;
			if(d[v]==INF || d[v]>d[u]+adj[u][j].second){
				d[v]=d[u]+adj[u][j].second;
				pq.push(make_pair(d[v], v));
				c[v]=GRAY;
			}
		}
	}
	return;
}

int main(){
	cin >> n;
	for(int i=0; i<n-1; i++){
		int a, b;
		ll c;
		cin >> a >> b >> c;
		adj[a-1].push_back(make_pair(b-1, c));
		adj[b-1].push_back(make_pair(a-1, c));
	}

	int q, k;
	cin >> q >> k;
	dijkstra_init();
	dijkstra(k-1);
	for(int i=0; i<q; i++){
		int x, y;
		cin >> x >> y;
		cout << d[x-1]+d[y-1] << endl;
	}
	return 0;
}

