void add(int x,int y,long long c)
{
    net[++tot]=head[x],head[x]=tot,to[tot]=y,val[tot]=c;
}
void dfs(int x)
{
    deep[x]=deep[fa[x][0]]+1;
    for(int i=1;fa[x][i-1];i++)
        fa[x][i]=fa[fa[x][i-1]][i-1];
    for(int i=head[x];i;i=net[i])
        if(to[i]!=fa[x][0])
            fa[to[i]][0]=x,dis[to[i]]=dis[x]+val[i],dfs(to[i]);
}
int lca(int x,int y)
{
    if(deep[x]<deep[y]) swap(x,y);
    int temp=20;
    while(temp>=0)
    {
        if(deep[fa[x][temp]]>=deep[y]) x=fa[x][temp];
        temp--;
    }
    temp=20;
    if(x==y) return x;
    while(temp>=0)
    {
        if(fa[x][temp]!=fa[y][temp]) 
            x=fa[x][temp],y=fa[y][temp];
        temp--;
    }
    return fa[x][0];
}
