int par[25][200000];

void dfs(int b, int pr = -1, int D = 0){
	for (auto &i : E[b]){
		if (i.second == pr)continue;
		dfs(i.second, b, D + i.first);
	}
	d[b] = D;
	par[0][b] = pr;
}
#define MAX_LOG 22
int lca(int a, int b){
	if (d[a] < d[b]){
		swap(a, b);
	}
	for (int i = 0; i < MAX_LOG; i++){
		if (((d[a] - d[b]) >> i) & 1){
			a = par[i][a];
		}
	}
	if (a == b){
		return a;
	}
	for (int i = MAX_LOG - 1; i >= 0; i--){
		if (par[i][a] != par[i][b]){
			a = par[i][a];
			b = par[i][b];
		}
	}
	return par[0][a];
}
ll dist(int x,int y){
	return d[x]+d[y]-d[lca(x,y)]*2;
}
signed main(){
