		E[a].push_back(P(c,b));E[b].push_back(P(c,a));
	}
	dfs(0,-1,0);
	for (int i = 0; i + 1 < MAX_LOG; i++){
		for (int j = 0; j < n; j++){
			if (par[i][j] == -1){
				par[i + 1][j] = -1;
				continue;
			}
			par[i + 1][j] = par[i][par[i][j]];
		}
	}
