    dist[k - 1] = 0;
    color[k - 1] = GRAY;

    while (1)
    {
        // S - V でコスト最小の頂点を選ぶ
        vertex = -1;
        min_d = infll;
        for (ll i = 0; i < n; i++)
        {
            if (color[i] == GRAY && dist[i] < min_d)
            {
                min_d = dist[i];
                vertex = i;
            }
        }
        // S = V の場合は終了
        if (vertex == -1)
            break;

        // vertexをSに追加
        color[vertex] = BLACK;

        // S-Vに属し、vertexに隣接する頂点のコストを更新
        for (i = 0; i < n; i++)
        {
            if (color[i] != BLACK && g[vertex][i] < infll)
            {
                color[i] = GRAY;
                if (dist[i] > dist[vertex] + g[vertex][i])
                {
                    dist[i] = dist[vertex] + g[vertex][i];
                }
            }
        }
    }
}

int main()
{

    ll n;
    cin >> n;
    vector<vector<ll>> g(n, vector<ll>(n, infll));
    ll dist[n];
    ll a, b, c;
    for (ll i = 0; i < n - 1; i++)
    {
        cin >> a >> b >> c;
        g[a - 1][b - 1] = c;
        g[b - 1][a - 1] = c;
    }
    ll q, k;
    cin >> q >> k;

    // ダイクストラ法
    dijkstra(n, dist, g, k);

    ll x, y;
    for (ll i = 0; i < q; i++)
    {
        cin >> x >> y;
        cout << dist[x - 1] + dist[y - 1] << endl;
    }

    return 0;
}

