vector<pair<long long, int> > adj[100005];
int color[100005];
long long dist[100005];
int N;

void dijkstra(int start_v) {
    priority_queue<pair<long long, int> > Q;
    for (int i = 1; i <= N; i++) {
        dist[i] = INF;
        color[i] = WHITE;
    }

    dist[start_v] = 0;
    Q.push(make_pair(0, start_v));
    color[start_v] = GRAY;

    while (!Q.empty()) {
        pair<long long, int> f = Q.top();
        Q.pop();
        int u = f.second;
        color[u] = BLACK;

        if (dist[u] < f.first * (-1)) continue;

        for (int j = 0; j < adj[u].size(); j++) {
            int v = adj[u][j].second;
            if (color[v] == BLACK) continue;
            if (adj[u][j].first + dist[u] < dist[v]) {
                dist[v] = dist[u] + adj[u][j].first;
                Q.push(make_pair(dist[v] * (-1), v));
                color[v] = GRAY;
            }
        }
    }

    return;
}

