    d.assign(N+1,LINF);
    d[--K]=0;
    priority_queue<PL, vector<PL>, greater<PL>>gq;
    gq.push({d[K],K});
    while(!gq.empty()){
        PL target=gq.top(); gq.pop();
        ll dt=target.first, t=target.second;
        if(d[t]<dt) continue;
        REP(i,G[t].size()){
            edge e=G[t][i];
            if(d[e.to]>d[t]+e.cost){
                d[e.to]=d[t]+e.cost;
                gq.push({d[e.to],e.to});
            }
        }
    }
    REP(i,Q){
        CINT(x,y);
        cout<<(d[--x]+d[--y])<<"\n";
    }
    return 0;
}

