/*
	【 DFS(深さ優先探索) 】

	< 注意 >
	最初に
	tree[頂点番号].push_back({ 辺の先の頂点番号, 距離 });
	tree[辺の先の頂点番号].push_back({ 頂点番号, 距離 });
	を実行して初期化してください。

	< 実行内容 >
	depth[A]に指定した頂点(v)から頂点Aまでの距離を格納する

	< パラメータ >
	tree[A] : 点Aと接続する辺の可変長配列
	depth[A] : 点Aに達するまでの距離(コスト)
*/

void DFS(
	int v,      // int v : 現在探索中の頂点の番号
	int p = -1, // int p : 探索元の頂点、普通は-1を指定
	ll d = 0    // ll  d : 距離(コスト)の初期値、普通は0を指定
) {
	depth[v] = d;
	for (auto &e : tree[v]) {
		if (e.to == p) continue;
		DFS(e.to, v, d + e.cost);
	}
}


