using namespace std;

class TreeDistance{
    int n;                                              // 頂点数
    int max_log_n;
    int root;                                           // 木の根
    vector<vector<pair<int, int>>> edges;

    vector<long long> distance_from_root;               // 根からの距離
    vector<int> depth;                                  // 根からの深さ
    vector<vector<int>> parent;                         // 親を2^k回辿って到達する頂点(根を通り過ぎる場合は-1とする)

public:
    void init(int n, int root, vector<vector<pair<int, int>>> &edges) {
        this->n = n;
        this->root = root;
        this->edges = edges;

        max_log_n = int(log2(n)) + 1;
        distance_from_root.assign(n, -1);
        distance_from_root[root] = 0;
        depth.assign(n, -1);
        parent.assign(max_log_n, vector<int>(n, -1));

        // 木のrootからの各頂点への距離，深さ，を求める
        dfs(root, -1, 0);

        // parentを初期化する
        for (int k = 0; k + 1 < max_log_n; ++k) {
            for (int v = 0; v < n; ++v) {
                if (parent[k][v] < 0) {
                    parent[k + 1][v] = -1;
                }
                else parent[k + 1][v] = parent[k][parent[k][v]];
            }
        }
    }

    long long distance(int u, int v) {
        return distance_from_root[u] + distance_from_root[v] - 2 * distance_from_root[lca(u, v)];
    }

    // uとvのLCAを求める
    int lca(int u, int v) {
        // uとvの深さが同じになるまで親を辿る
        if (depth[u] > depth[v]) {
            swap(u, v);
        }
        for (int k = 0; k < max_log_n; ++k) {
            if ((depth[v] - depth[u]) >> k & 1) {
                v = parent[k][v];
            }
        }
        if (u == v) {
            return u;
        }
        // 二分探索でLCAを求める
        for (int k = max_log_n - 1; k >= 0; --k) {
            if (parent[k][u] != parent[k][v]) {
                u = parent[k][u];
                v = parent[k][v];
            }
        }
        return parent[0][u];
    }


private:
    void dfs(int v, int p, int d) {
        parent[0][v] = p;
        depth[v] = d;
        for(auto node_dist : edges.at(v)) {
            if (node_dist.first != p and node_dist.first != v) {
                distance_from_root[node_dist.first] = distance_from_root[v] + node_dist.second;
                dfs(node_dist.first, v, d + 1);
            }
        }
    }
};

int main() {
    cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;

    vector<vector<pair<int, int>>> edges(N);
    FOR(i, 0, N - 1) {
        int a, b, c;
        cin >> a >> b >> c;
        edges[a - 1].emplace_back(make_pair(b - 1, c));
        edges[b - 1].emplace_back(make_pair(a - 1, c));
    }

    TreeDistance td;
    td.init(N, 0, edges);

    int Q, K;
    cin >> Q >> K;
    FOR(i, 0, Q) {
        int x, y;
        cin >> x >> y;
        print(td.distance(x - 1, K - 1) + td.distance(K - 1, y - 1));
    }

	return 0;
}

