    for (int i = h[ver]; i != -1; i = ne[i]) {
      ll j = e[i];
      if (dist[j] > distance + w[i]) {
        dist[j] = distance + w[i];
        heap.push(make_pair(dist[j], j));
      }
    }
  }
}

