    }

    //ダイクストラ
    priority_queue<pair<ll,ll> >pq;
    // weight[v]に始点sからvまでの最短コストを保存する
    ll weight[N];
    // 訪問状態を記録
    bool searched[N];
    for(ll i = 0; i < N; i ++){
        searched[i] = false;
        weight[i] = LLONG_MAX;
