            if(targetCost + u < weight[targetNode]){
                //cout << i << "/" << node << ":" << targetCost << "," << u << endl;
                weight[targetNode] = targetCost + u;
                pair<ll,ll> newPair = make_pair(weight[targetNode] * -1, targetNode);
                pq.push(newPair);
            }
        }
    }

    for(ll i = 0; i < Q; i ++){
        cout << (weight[x[i]] + weight[y[i]]) << endl;
    }


    return 0;
}

