int getLca(int x, int y) {
    if (dep[x] < dep[y]) swap(x, y);
    x = up(x, dep[x] - dep[y]);
    if (x == y) return x;
    int l = 1, r = n, mid, res = -1;
    while (l <= r) {
        mid = (l + r) >> 1;
        if (up(x, mid) == up(y, mid)) {
            r = mid - 1;
            res = mid;
        } else {
            l = mid + 1;
        }
    }
    return up(x, res);
}

ll getDis(int x, int y) {
    assert(dep[x] >= dep[y]);
    return dis[x] - dis[y];
}

