struct LCA{
public:
	vector<vector<P> > g;
	const int MAX_LOG = 22;
	vector<vector<int> > lcc;
	vector<long long> dep;
	void init2(){
		int n = g.size();
		for (int i = 0; i + 1 < MAX_LOG; i++){
			for (int j = 0; j < n; j++){
				if (lcc[i][j] == -1){
					lcc[i + 1][j] = -1;
					continue;
				}
				lcc[i + 1][j] = lcc[i][lcc[i][j]];
			}
		}
	}
	int lca(int a, int b){
		if (dep[a] < dep[b]){
			swap(a, b);
		}
		for (int i = 0; i < MAX_LOG; i++){
			if (((dep[a] - dep[b]) >> i) & 1){
				a = lcc[i][a];
			}
		}
		if (a == b){
			return a;
		}
		for (int i = MAX_LOG - 1; i >= 0; i--){
			if (lcc[i][a] != lcc[i][b]){
				a = lcc[i][a];
				b = lcc[i][b];
			}
		}
		return lcc[0][a];
	}
	inline void dfs(int b, int pr = -1, int d = 0){
		for (auto &i : g[b]){
			if (i.second == pr)continue;
			dfs(i.second, b, d + i.first);
		}
		dep[b] = d;
		lcc[0][b] = pr;
	}
	void init(vector<vector<P> > &tree, int root = 0){
		g = tree;
		lcc.resize(MAX_LOG, vector<int>(g.size(), 0));
		dep.resize(g.size());
		dfs(root);
		init2();
	}
};
