void dfs(ll p,ll q,ll r){
  depth[p]=r;
  for(auto e:tree[p]){
    if(e.first==q)continue;
    depth[e.first]=depth[p]+e.second;
    dfs(e.first,p,depth[e.first]);
  }
  return;
}

