#define MAX_N 100'000

ll dp[MAX_N+1];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    cin>>N;
    map<int, vector<pair<int, int>>> edges;
    for (int n = 1; n < N; n++) {
        int a, b, c;
        cin>>a>>b>>c;
        edges[a].push_back(make_pair(b, c));
        edges[b].push_back(make_pair(a, c));
    }
    fill(begin(dp), end(dp), inf);

    int Q, K;
    cin>>Q>>K;
    dp[K] = 0;
    queue<int> q;
    q.push(K);
    while (!q.empty()) {
        int v = q.front();
        q.pop();

        for (auto to : edges[v]) {
            if (dp[to.first] != inf) continue;
            dp[to.first] = dp[v] + to.second;
            q.push(to.first);
        }
    }

    for (int q = 0; q < Q; q++) {
        int x, y;
        cin>>x>>y;
        cout<<dp[x] + dp[y]<<endl;
    }
    return 0;
}

