bool used[100100];

void dfs(long long X){
    used[X] = 1;
    T[X] = cost;
    REP(i,V[X].size()){
        if(used[V[X][i].first]) continue;
        cost += V[X][i].second;
        dfs(V[X][i].first);
        cost -= V[X][i].second;
    }
}

