#include <bits/stdc++.h>
using namespace std;
using ll=long long;
#define MOD 1000000007

vector<vector<pair<int,ll>>> tree;
vector<ll> depth;

void solve(int v){
  for(auto nv :tree.at(v)){
    if(depth.at(nv.first)==-1){
      depth.at(nv.first)=depth.at(v)+nv.second;
      solve(nv.first);
    }
  }
}

int main(){
  int N;
  cin>>N;
  tree.resize(N);
  depth.resize(N,-1);
  for(int i=0;i<N-1;i++){
    int a,b;
    ll c;
    cin>>a>>b>>c;
    a--;
    b--;
    tree.at(a).push_back(make_pair(b,c));
    tree.at(b).push_back(make_pair(a,c));
  }
  int Q,K;
  cin>>Q>>K;
  K--;
  vector<int> x(Q),y(Q);
  for(int i=0;i<Q;i++){
    cin>>x.at(i)>>y.at(i);
    x.at(i)--;
    y.at(i)--;
  }

  depth.at(K)=0;
  solve(K);

  for(int i=0;i<Q;i++){
    cout<<depth.at(x.at(i))+depth.at(y.at(i))<<endl;
  }

}

