#include <unordered_set>
std::unordered_set<Node*> Used;
void CalcCost(Node* node, const uint64_t cost) {
	if(Used.count(node) != 0)
		return;
	Used.emplace(node);
	node->toKCost = cost;
	for(auto& nd : node->link) {
		CalcCost(nd.first, cost + nd.second);
	}
}
