        for(ll n = 0; n < N; n ++){
            connection[i][n] = LLONG_MAX;
        }
    }
    for(ll i = 0; i < N - 1; i ++){
        cin >> a[i] >> b[i] >> c[i];
        a[i] --;
        b[i] --;
        connection[a[i]][b[i]] = c[i];
        connection[b[i]][a[i]] = c[i];
    }

    //ダイクストラ
    priority_queue<pair<int,int> >pq;
    // weight[v]に始点sからvまでの最短コストを保存する
    ll weight[N];
    // 訪問状態を記録
    bool searched[N];
    for(ll i = 0; i < N; i ++){
        searched[i] = false;
        weight[i] = LLONG_MAX;
