        tree[b].push_back(edge{a, c});
    }

    cin >> Q >> K; K--;

    dijkstra(K);

    for (int i = 0; i < Q; i++) {
        cin >> x >> y;
        x--; y--;
        cout << d[x] + d[y] << endl;
    }
    return 0;
}

