#define ll long long

ll bfs(ll start, ll dest, vector<vector<pair<ll,ll>>> &adjlist) {
	//returns length
	ll length=0;
	queue<pair<ll,ll>> q;
	vector<bool> visited(adjlist.size());
	q.push({start,0});
	while (!q.empty()) {
		ll v = q.front().first, c = q.front().second;
		q.pop();
		visited[v]=true;
		if (v==dest) {
			length=c;
			break;
		}

		for (pair<ll,ll> p : adjlist[v]) {
			ll nextv = p.first, nextc = p.second;
			if (!visited[nextv])
				q.push({nextv,c+nextc});
		}
	}
	return length;
}

