void dij(int s) {
    priority_queue <pii,vector<pii>,greater<pii> > Q;
    rep(i,1,N+1) {
        d[s][i] = INF;
    }
    d[s][s] = 0;
    memset(done,0,sizeof(done));
    Q.push(mp(0,s));
    while (!Q.empty()) {
        pii t = Q.top(); Q.pop();
        int u = t.se;
        if (done[u]) continue;
        done[u] = true;
        rep(i,0,sz(G[u])) {
            Edge e = edge[G[u][i]];
            if (d[s][e.to] > d[s][u] + e.dist) {
                d[s][e.to] = d[s][u] + e.dist;
                Q.push(mp(d[s][e.to],e.to));
            }
        }

    }
}

