void link(int u,int v,int w)
{
	++ cnt; e[cnt].next = head[u];
	e[cnt].to = v; e[cnt].w = w;
	head[u] = cnt;
}
void dfs(int x,int f=0)
{
	for(int i = head[x]; i; i = e[i].next)
		if(e[i].to != f)
		{
			dep[e[i].to] = dep[x] + 1;
			fa[e[i].to][0] = x;
			dis[e[i].to][0] = e[i].w;
			dfs(e[i].to,x);
		}
}
int lca(int x,int y)
{
	if(dep[x] < dep[y]) swap(x,y);
	int c = dep[x] - dep[y];
	for(int j = 19; j >= 0; -- j) if(c&(1<<j)) x = fa[x][j];
	for(int j = 19; j >= 0; -- j) if(fa[x][j]!=fa[y][j]) x = fa[x][j], y = fa[y][j];
	return (x==y?x:fa[x][0]);
}
long long calc(int x,int y)
{
	int g = lca(x,y);
	long long ret = 0;
	int c = dep[x]-dep[g];
	for(int j = 19; j >= 0; -- j) if(c&(1<<j)) ret += dis[x][j], x = fa[x][j];
	c = dep[y]-dep[g];
	for(int j = 19; j >= 0; -- j) if(c&(1<<j)) ret += dis[y][j], y = fa[y][j];
	return ret;
}
