void Search(const int n, vector<list<pair<int, int>>> &d, vector<ll> &ans) {
	for (auto itr = d[n].begin(); itr != d[n].end(); itr++) {
		if (ans[(*itr).first] == -1) {
			ans[(*itr).first] = ans[n] + (*itr).second;
			Search((*itr).first, d, ans);
		}
	}
	return;
}

