vector<pair<ll,ll> >e[maxn];//二维数组，第一维是点的序号，第二维是该点所连接的点的数量
//first是该点连接的点的序号，second是该点到所连接点的权值

ll n,m,dis[maxn];

void init()
{
    for(ll i=0;i<maxn;i++)e[i].clear();
    for(int i=0;i<maxn;i++)dis[i]=(1ll<<60)-1;
}

void dij(ll s)
{
    priority_queue<pair<ll,ll> >q;
    dis[s]=0;
    q.push(make_pair(-dis[s],s));
    while(!q.empty())
    {
        ll now=q.top().second;//当前离起点最近的点（最短路已经确定的点）
        q.pop();
        for(int i=0;i<e[now].size();i++)
        {
            ll v=e[now][i].first;//更新该点所连接的所有点
            if(dis[v]>dis[now]+e[now][i].second)
            {
                dis[v]=dis[now]+e[now][i].second;
                q.push(make_pair(-dis[v],v));//更新成功则入队
            }
        }
    }
}

