#include <bits/stdc++.h>
using namespace std;

#define MAX_V 100001
#define INF 1000000000000001
typedef long long ll;

struct edge { ll to, cost; };
typedef pair<ll, ll> P; // firstは最短距離、secondは頂点の番号
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(ll s) {
	// greater<P>を指定することでfirstが小さい順に取り出せるようにする
	priority_queue<P, vector<P>, greater<P> > que;
	fill(d, d + MAX_V, INF);
	d[s] = 0;
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top(); que.pop();
		ll v = p.second;
		if (d[v] < p.first) continue;
		for (int i = 0; i < G[v].size(); i++) {
			edge e = G[v][i];
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

void solve(long long N, vector<long long> a, vector<long long> b, vector<long long> c, long long Q, long long K, vector<long long> x, vector<long long> y){
	for (int i=0; i<N-1; i++) {
		edge e1 = {a[i],c[i]};
		G[b[i]].push_back(e1);
		edge e2 = {b[i],c[i]};
		G[a[i]].push_back(e2);
	}
	dijkstra(K);
	for (int i=0; i<Q; i++) {
		cout << d[x[i]]+d[y[i]] << endl;
	}
}

