typedef long long ll;
struct Edge {
	int next, to; ll c;
} edge[(MAX_N<<1)+5];
int n, m, k, cnt;
int d[MAX_N+5], p[MAX_N+5][25], first[MAX_N+5];
ll tofa[MAX_N+5][25];
bool vis[MAX_N+5];
void INSERT(int a, int b, ll c) {
	edge[++cnt].next = first[a], edge[cnt].c = c;
	edge[cnt].to = b, first[a] = cnt;
}
void DFS(int u) {
	vis[u] = true;
	for (int i = 1; (1<<i) <= n; i++) {
		if ((1<<i) <= d[u]) {
			p[u][i] = p[p[u][i-1]][i-1];
			tofa[u][i] = tofa[u][i-1]+tofa[p[u][i-1]][i-1];
		}
	}
	for (int i = first[u]; i; i = edge[i].next) {
		int v = edge[i].to;
		if (!vis[v]) {
			d[v] = d[u]+1;
			p[v][0] = u;
			tofa[v][0] = edge[i].c;
			DFS(v);
		}
	}
}
ll LCA(int a, int b) {
	int i, j; ll ret = 0;
	if (d[a] < d[b])	swap(a, b);
	for (i = 0; (1<<i) <= d[a]; i++) {}
	i--;
	for (j = i; j >= 0; j--) {
		if (d[a]-(1<<j) >= d[b]) {
			ret += tofa[a][j];
			a = p[a][j];
		}
	}
	if (a == b) {
		return ret;
	}
	for (j = i; j >= 0; j--) {
		if (p[a][j] != p[b][j]) {
			ret += (tofa[a][j]+tofa[b][j]);
			a = p[a][j];
			b = p[b][j];
		}
	}
	return ret+tofa[a][0]+tofa[b][0];
}
int main() {
	scanf("%d", &n);
	for (int i = 1; i < n; i++) {
		int u, v, c; cin >> u >> v >> c;
		INSERT(u, v, c), INSERT(v, u, c);
	}
	DFS(1);
	scanf("%d%d", &m, &k);
	for (int i = 0; i < m; i++) {
		int x, y; scanf("%d%d", &x, &y);
		printf("%lld\n", LCA(x, k)+LCA(k, y));
	}
	return 0;
}

