    for(int i=0; i<N-1; i++){
        int a,b,c; cin >> a >> b >> c;
        G[a-1].push_back(edge{b-1,c});
        G[b-1].push_back(edge{a-1,c});
    }
    int Q,K; cin >> Q >> K;

    vector<ll> costs(N,-1);
    stack<stcon> st;
    st.push(stcon{K-1,0});
    while(!st.empty()){
