const int MaxN = 10000;
typedef long long LL;
int n, m, all;
int pre[MaxN + 5], last[MaxN + 5], other[MaxN + 5], cost[MaxN + 5];
LL	dis[MaxN + 5], seq[MaxN + 5];
bool Inque[MaxN + 5];

void Build(int x, int y, int w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int s)
{
	int head = 1, tail = 1, now, ed, dr;
	seq[tail] = s;
	for(int i = 1; i <= n; i++)
	{
		if(i == s) dis[i] = 0;
		else dis[i] = 1ll << 60;
	}
	Inque[s] = 1;
	while(head <= tail)
	{
		now = seq[head];
		ed = last[now];
		while(ed != -1)
		{
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr])
			{
				dis[dr] = dis[now] + cost[ed];
				if(!Inque[dr])
				{
					Inque[dr] = 1;
					seq[++tail] = dr;
				}
			}
			ed = pre[ed];
		}
		Inque[now] = 0;
		head++;
	}
}

int main()
{
	all = -1;
	memset(last, -1, sizeof(last));
	scanf("%d", &n);
	for(int i = 1; i <= n-1; i++)
	{
		int a, b, w;
		scanf("%d%d%d", &a, &b, &w);
		Build(a, b, w); Build(b, a, w);
	}
	memset(seq, 0, sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	int q,k;
	scanf("%d%d",&q,&k);
	Bfs(k);
	for (int i = 1; i <= q; i++)
	{
		int h,j;
		scanf("%d %d",&h,&j);
		printf("%I64d\n",dis[h]+dis[j]);
	}
}

