#define LL long long
using EDGE = tuple<int, int, LL>;
int g_K;

LL towards(vector<EDGE> &trees, int &goal, int prev, int now, bool reach, LL cost) {
  if(now==goal && reach) {
    return cost;
  }
  vector<LL> way;
  if(now==g_K || prev==-1) {
    if(now==g_K) reach=true;
    REP(i, trees.size()) {
      int a, b;
      a = get<0>(trees.at(i));
      b = get<1>(trees.at(i));
      if(a==now)
        way.push_back(towards(trees, goal, a, b, reach, cost+get<2>(trees.at(i))));
      if(b==now)
        way.push_back(towards(trees, goal, b, a, reach, cost+get<2>(trees.at(i))));
    }
  } else {
    REP(i, trees.size()) {
      int a, b;
      a = get<0>(trees.at(i));
      b = get<1>(trees.at(i));
      if(a==now && b!=prev)
        way.push_back(towards(trees, goal, a, b, reach, cost+get<2>(trees.at(i))));
      if(b==now && a!=prev)
        way.push_back(towards(trees, goal, b, a, reach, cost+get<2>(trees.at(i))));
    }
  }
  if(way.size() != 0) {
  	LL result=0;
    REP(i, way.size()) {
      if(way.at(i)!=0) {
        if(result==0)
          result = way.at(i);
        else
          result = min(result, way.at(i));
      }
    }
    return result;
  }
  return 0;
}

LL shotest(int &x, int &y, vector<EDGE> &trees) {
  return towards(trees, y, -1, x, false, 0);
}

