    rep(i, MAX) dist[i] = LLINF;
    dist[root] = 0;
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    pq.push(make_pair(0, root));
    while (!pq.empty()) {
        pli top = pq.top();
        pq.pop();
        int u = top.second;
        for (auto &e: g[u]) {
            int v = e.second;
            ll cost = e.first;
            if (chmin(dist[v], dist[u] + cost)) {
                pq.push(make_pair(dist[v], v));
            }
        }
    }

    cin >> q >> k;
    rep(i, q) {
        int x, y; cin >> x >> y;
        cout << dist[x] + dist[y] + 2 * dist[k] << endl;
    }
}

