    cin >> Q >> K;
    K--;

    dij.calc_shortest_path(K);

    while(Q--){
      ll x, y;
      cin >> x >> y;
      x--; y--;
      ll d = dij.distance(x) + dij.distance(y);
      p(d);
    }

    return 0;
}

