using namespace std;

struct PathData
{
    long from;
    long to;
    long cost;
};

int main()
{
    long N;
    cin >> N;
    vector<long> tmpVec(N, 0);
    vector<vector<long>> pathVec(N, tmpVec);
    unordered_map<long, vector<long>> CheckMap;

    long a, b, c;
    for (long i = 0; i < N - 1; i++)
    {
        cin >> a >> b >> c;
        a--;
        b--;
        pathVec[a][b] = pathVec[b][a] = c;
        CheckMap[a].push_back(b);
        CheckMap[b].push_back(a);
    }

    long Q, K;
    cin >> Q >> K;
    K--;
    long x, y;

    stack<PathData> PDStack;
    unordered_set<long> CheckSet;
    unordered_map<long, long> CostMap;

    for (int i = 0; i < CheckMap[K].size(); i++)
    {
        PathData pd;
        pd.from = K;
        pd.to = CheckMap[K][i];
        pd.cost = pathVec[K][CheckMap[K][i]];
        PDStack.push(pd);
    }
    CheckSet.emplace(K);

    while (!PDStack.empty())
    {
        PathData pd = PDStack.top();
        PDStack.pop();
        CostMap[pd.to] = pd.cost;

        for (int i = 0; i < CheckMap[pd.to].size(); i++)
        {
            if (CheckSet.find(CheckMap[pd.to][i]) == CheckSet.end())
            {
                PathData pd_new;
                pd_new.from = pd.to;
                pd_new.to = CheckMap[pd.to][i];
                pd_new.cost = pd.cost + pathVec[pd.to][CheckMap[pd.to][i]];
                PDStack.push(pd_new);
            }
        }
        CheckSet.emplace(pd.to);
    }

    for (long i = 0; i < Q; i++)
    {
        cin >> x >> y;
        x--;
        y--;

        cout << CostMap[x] + CostMap[y] << endl;
    }
    return 0;
}

