        scanf("%d%d%lld", &a, &b, &c);
        a--; b--;
        if (a > b) std::swap(a, b);
        tree[b].parent = a;
        tree[b].cost = c;
    }
    int q, k;
    scanf("%d%d", &q, &k);
    k--;
