    int tmp_k = k;
    while (tmp_k)
    {
        int next = tree[tmp_k].parent;
        tree[next].k_distance = tree[tmp_k].k_distance + tree[tmp_k].cost;
        tmp_k = next;
    }

    for (int i = 0; i < q; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        x--; y--;
        printf("%lld\n", calc_distance(x) + calc_distance(y));
    }

    return 0;
}

long long calc_distance(const long long a)
{
    if (tree[a].k_distance == -1)
        tree[a].k_distance = calc_distance(tree[a].parent) + tree[a].cost;
    return tree[a].k_distance;
}

