void dfs(int u,int deep)
{
    vis[u]=1;
    vex[++tot]=u;   //以tot为编号的的节点
    first[u]=tot;
    R[tot]=deep;
    for(int x=head[u];x;x=Path[x].nxt)
    {
        int v=Path[x].to,c=Path[x].cost;
        if(!vis[v])
        {
            dis[v]=dis[u]+c;
            dfs(v,deep+1);
            vex[++tot]=u;
            R[tot]=deep;
        }
    }
}
int dp[Max<<1][25];
void ST(int n) //n是2*n-1
{
    int x,y;
    for(int i=1;i<=n;i++) dp[i][0]=i;
    for(int j=1;(1<<j)<=n;j++)
    {
        for(int i=1;i+(1<<j)-1<=n;i++)
        {
          x=dp[i][j-1];y=dp[i+(1<<(j-1))][j-1];
          dp[i][j]=(R[x]<R[y]?x:y);
        }
    }
}
int RMQ(int l,int r)
{
    int k=0,x,y;
    while((1<<(k+1))<=r-l+1) k++;
    x=dp[l][k];y=dp[r-(1<<k)+1][k];
    return (R[x]<R[y])?x:y;
}
int lca(int u,int v)
{
    int x=first[u],y=first[v];
    if(x>y) swap(x,y);
    int res=RMQ(x,y);  //在u,v之间的最小深度节点即为lca
    return vex[res];
}
