struct PathData
{
    unsigned long long from;
    unsigned long long to;
    unsigned long long cost;
    unsigned long long goal;
};

int main()
{
    unsigned long long N;
    cin >> N;
    vector<unsigned long long> tmpVec(N, 0);
    vector<vector<unsigned long long>> pathVec(N, tmpVec);
    unordered_map<unsigned long long, vector<unsigned long long>> CheckMap;

    unsigned long long a, b, c;
    for (unsigned long long i = 0; i < N - 1; i++)
    {
        cin >> a >> b >> c;
        a--;
        b--;
        pathVec[a][b] = pathVec[b][a] = c;
        CheckMap[a].push_back(b);
        CheckMap[b].push_back(a);
    }

    unsigned long long Q, K;
    cin >> Q >> K;
    K--;
    unsigned long long x, y;

    queue<PathData> PDQueue;
    unsigned long long sum1, sum2;

    for (unsigned long long i = 0; i < Q; i++)
    {
        cin >> x >> y;
        x--;
        y--;

        for (unsigned long long j = 0; j < CheckMap[x].size(); j++)
        {
            PathData pd;
            pd.from = x;
            pd.to = CheckMap[x][j];
            pd.cost = pathVec[x][CheckMap[x][j]];
            pd.goal = K;
            PDQueue.push(pd);
        }

        while (!PDQueue.empty())
        {
            PathData pd = PDQueue.front();
            PDQueue.pop();
            if (pd.to == pd.goal)
            {
                sum1 = pd.cost;
                break;
            }

            for (unsigned long long j = 0; j < CheckMap[pd.to].size(); j++)
            {
                PathData pd_new;
                pd_new.from = pd.to;
                pd_new.to = CheckMap[pd.to][j];
                pd_new.cost = pd.cost + pathVec[pd.to][CheckMap[pd.to][j]];
                pd_new.goal = pd.goal;
                PDQueue.push(pd_new);
            }
        }

        while (!PDQueue.empty())
            PDQueue.pop();

        for (unsigned long long j = 0; j < CheckMap[K].size(); j++)
        {
            PathData pd;
            pd.from = K;
            pd.to = CheckMap[K][j];
            pd.cost = pathVec[K][CheckMap[K][j]];
            pd.goal = y;
            PDQueue.push(pd);
        }

        while (!PDQueue.empty())
        {
            PathData pd = PDQueue.front();
            PDQueue.pop();
            if (pd.to == pd.goal)
            {
                sum2 = pd.cost;
                break;
            }

            for (unsigned long long j = 0; j < CheckMap[pd.to].size(); j++)
            {
                PathData pd_new;
                pd_new.from = pd.to;
                pd_new.to = CheckMap[pd.to][j];
                pd_new.cost = pd.cost + pathVec[pd.to][CheckMap[pd.to][j]];
                pd_new.goal = pd.goal;
                PDQueue.push(pd_new);
            }
        }

        cout << sum1 + sum2 << endl;
    }
    return 0;
}

