int f1(int a, int b, int c, int d) {
	if (f(c, d) == a && f(c, d + 1) == b)
		return s[c][d];
	c--, d = d * 2 + 1;
	if (b <= f(c, d))
		return f1(a, b, c, d - 1);
	if (a >= f(c, d))
		return f1(a, b, c, d);
	return mi(f1(a, f(c, d), c, d - 1), f1(f(c, d), b, c, d));
}

int lca(int a, int b) {
