void Build(int x, int y, LL w){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int x){
	int head = 1, tail = 1, now, dt, dr;
	seq[tail] = x;
	for(int i = 1; i <= n; i++)
	{
		if(i == x) dis[i] = 0;
		else dis[i] = 10000000000000;
	}
	Inque[x] = 1;
	while(head <= tail){
		now = seq[head];
		dt = last[now];
		while(dt != -1){
			dr = other[dt];
			if(dis[now] + cost[dt] < dis[dr]){
				dis[dr] = dis[now] + cost[dt];
				if(!Inque[dr]){
					Inque[dr] = 1; 
					seq[++tail] = dr;
				}
			}
			dt = pre[dt];
		}
		Inque[now] = 0;
		head++;
	}
}

