    UnionFind<ll> uf(n + 1);
    rep(i, n - 1) {
        int a, b, c;
        cin >> a >> b >> c;
        uf.merge(a, b, c);
    }
    int q, k;
    cin >> q >> k;
    rep(i, q) {
        int x, y;
        cin >> x >> y;
        out(abs(uf.diff(x, k)) + abs(uf.diff(y, k)));
    }
}

