using vvvi = vector<vvi>;

int n, q, root;

vvvi g;

vi tree;
vi vid;
vi to_root;

map< pair<lli, lli>, lli > edges;

int id = 0;

void hang(vvvi& g, int k)
{
    for(auto& elt : g[k])
    {
        lli nd = elt[0];
        lli w = elt[1];

        if(vid[nd]) continue;

        tree[nd] = k;
        vid[nd] = id;
        to_root[nd] = to_root[k] + w;

        id += g[k].size() > 1;
        hang(g, nd);
    }
}

pair<lli, lli> find_anc(lli a, lli b)
{
    int same = 0;

    lli len0 = 0;

    if(vid[a] == vid[b])
    {
        same = 1;

        lli ra = to_root[a];
        lli rb = to_root[b];

        if(ra < rb) swap(ra, rb);

        len0 = ra - rb;
    }

    lli len = 0;

    while(a != b)
    {
        lli& x = to_root[a] > to_root[b] ? a : b;

        assert(x != root);

        lli p = tree[x];

        lli x_p = edges[{x, p}];

        len += edges[{x, p}];

        if(p != root && g[p].size() == 1)
        {
            lli pp = tree[p];

            lli p_pp = edges[{p, pp}];

            len += p_pp;

            edges[{x, pp}] = x_p + p_pp;

            tree[x] = pp;

            p = pp;
        }

        x = p;
    }

    if(same) len = len0;

    return {len, a};
}

