    {
        int a, b, c; cin >> a >> b >> c;

        g[a].push_back({b, c});
        g[b].push_back({a, c});

        edges[{a, b}] = c;
        edges[{b, a}] = c;
    }

    cin >> q >> root;

    tree = vi(n + 1);
    tree[root] = root;

    vid = vi(n + 1);
    to_root = vi(n + 1);

    vid[root] = ++id;

    hang(g, root);

    for(int i = 0; i < q; i++)
    {
        int a, b; cin >> a >> b;

        lli len, anc;

        auto pr = find_anc(a, b);

        len = pr.first;
        anc = pr.second;

        len += to_root[anc] * 2;

        cout << len << '\n';
    }

    return 0;
}

