lint dijkstra(int s) {
  vec<lint> d(N, LINF);
  minheap<pair<lint, lint>> q;
  d[s] = 0;
  q.emplace(0, s);

  while (q.size()) {
    auto p = q.top(); q.pop();
    auto v = p.second;
    if (d[v] < p.first) continue;
    each(e, G[v]) {
      if (d[e.to] > e.cost + d[v]) {
        d[e.to] = e.cost + d[v];
        q.emplace(d[e.to], e.to);
      }
    }
  }

  return d[K];
}

vec<lint> dk() {
  vec<lint> d(N, LINF);
  minheap<pair<lint, lint>> q;
  d[K] = 0;
