void dijkstra( int s ) {
    priority_queue<P,vector<P>,greater<P>> que;
    d[s] = 0;
    que.push(P(0,s));

    while( que.size() ){
        P p = que.top(); que.pop();
        ll dis = p.first;
        int v = p.second;
        if ( d[v] < dis ) continue;
        for ( int i = 0; i < G[v].size(); ++i){
            Edge e = G[v][i];
            int nv = e.first;
            ll ndis = e.second;
            if ( d[nv] > d[v] + ndis ){
                d[nv] = d[v] + ndis;
                que.push(P(d[nv],nv));
            }
        }
    }
}

