        to[b].push_back(std::make_pair(a, c));
    }

    int leave = getLeave();
    length.resize(N, 0);
    dig(leave, -1, 0);


    int x, y;
    std::cin >> q >> k;
    long long int K = length[k-1];
    for(int i=0; i<q; ++i){
        std::cin >> x >> y;
