}

const ll INF = 1e18;

graph G;
vector<ll> d;

void dijkstra(int s) {
  int N = G.size();
  priority_queue<edge> pq;
  d.assign(N, INF);
  d[s] = 0;
  pq.push({s, 0});
  while (!pq.empty()) {
    edge e = pq.top(); pq.pop();
    int u = e.to;
    if (d[u] < e.cost) continue;
    for (auto&& v : G[u]) {
      if (d[v.to] > d[u] + v.cost) {
        d[v.to] = d[u] + v.cost;
        pq.push({v.to, d[v.to]});
      }
    }
  }
}

