    G[a].push_back({b, c});
    G[b].push_back({a, c});
  }
  int Q, K; cin >> Q >> K;
  dijkstra(--K);
  vector<int> x(Q), y(Q);
  for (int i = 0; i < Q; i++) {
    cin >> x[i] >> y[i];
    x[i]--; y[i]--;
  }
