void dfs(int v, int p, int depth, ll d) {
    dep[v] = depth;
    lca[0][v] = p;
    dis[v] = d;
    for (auto x: g[v])
        if (x.fi != p) dfs(x.fi, v, depth + 1, d + x.se);
}

int up(int x, int height) {
    for (int i = 20; i >= 0; i--)
        if (height >> i & 1) x = lca[i][x];
    return x;
}

int getLca(int x, int y) {
    if (dep[x] < dep[y]) swap(x, y);
    if (x == y) return x;
    x = up(x, dep[x] - dep[y]);
    if (x == y) return x;
    int l = 1, r = 20, mid, res = -1;
    while (l <= r) {
        mid = (l + r) >> 1;
        if (lca[mid][x] == lca[mid][y]) {
            r = mid - 1;
            res = mid;
        } else {
            l = mid + 1;
        }
    }
    return lca[res][x];
}

ll getDis(int x, int y) {
    assert(dep[x] >= dep[y]);
    return dis[x] - dis[y];
}

