void dijkstra(int s) {
    ll dd2[100005];


    priority_queue<P, vector<P>, greater<P>> que;
//    fill(d, d + V, INF);
    for(int i = 0; i <= V; i++){
        dd2[i] = INF;
    }
    dd2[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (dd2[v] < p.first) continue;
        for (int i = 0; i < G[v].size(); i++) {
            edge e = G[v][i];
            if (dd2[e.to] > dd2[v] + e.cost) {
                dd2[e.to] = dd2[v] + e.cost;
                que.push(P(dd2[e.to], e.to));
            }
        }
    }
    for(int i = 0; i <= V; i++){
        dd[i] = dd2[i];
    }

}

