void dfs1(int v, int p){
  up[v][0] = p;
  for(int j = 1; j < 20; ++j){
    up[v][j] = up[up[v][j - 1]][j - 1];
  }
  for(pii i : g[v]){
    if(i.first == p){
      continue;
    }
    h[i.first] = h[v] + i.second;
    dfs1(i.first, v);
  }
