int lca(int x, int y){
  if(h[x] < h[y]){
    swap(x, y);
  }
  for(int j = 19; j >= 0; --j){
    if(up[x][j] && ((h[x] - h[y]) >> j) & 1){
      x = up[x][j];
    }
  }
  for(int j = 19; j >= 0; --j){
    if(up[x][j] && up[y][j] && up[x][j] != up[y][j]){
      x = up[x][j];
      y = up[y][j];
    }
  }
  if(x == y)
    return x;
  return up[x][0];
}

ll dist(int x, int y){
  return h[x] + h[y] - 2 * h[lca(x, y)];
}

