		edges[a].push_back(P(b,c));
		edges[b].push_back(P(a,c));
	}

	cin >> Q >> K;
	Dijkstra(K);
	int x,y;
	for(int i = 0; i < Q; i++){
		cin >> x >> y;
		ans.push_back(dis[x] + dis[y]);
	}

