    for (int j=0;j<edges[current.second].size();++j) {
      E e=edges[current.second][j];
      if (dp[e.to] > dp[current.second] + e.cost) {
        dp[e.to] = dp[current.second] + e.cost;
        PQ.push(P(dp[e.to], e.to));
      }
    }
  }
  for(int i=0;i<Q;++i) {
    int x,y;
    scanf("%d%d", &x, &y);
    --x;--y;
    printf("%lld\n", dp[x] + dp[y]);
  }
  return 0;
}

