		AddEdge(v, u, w);
	}

	scanf("%d%d", &q, &k);
	dfs(k);
	while(q--){
		scanf("%d%d", &a, &b);
		printf("%d\n", dis[a] + dis[b]);
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll N = 4e5+9;
ll n,k,q,tdfn,tot;
ll dp[50][N],vis[N];
ll B[N],LOG[N],used[N],F[N],pos[N];
vector<pair<ll,ll> > edge[N];
void rmq_init(ll n,ll num[])
{
    ll i,j;
    for(j=1;j<=n;j++) 
        dp[0][j]=num[j];
    for(j=1;j<=LOG[n];j++)
    {
        ll limit=n+1-(1<<j);
        for(i=1;i<=limit;i++)
        {
            ll x=i+(1<<j>>1);
            dp[j][i]=min(dp[j-1][x],dp[j-1][i]);
        }
    }
}
ll rmq(ll l,ll r,ll num[])
{
    ll m=LOG[r-l+1];
    return min(dp[m][l],dp[m][r-(1<<m)+1]);
}
ll sum[M];
void dfs(ll s)
{
    ll i,t;
    used[s]=1;
    ll tmp=++tdfn;
    B[++tot]=tmp;F[tmp]=s;
    pos[s]=tot;
    for(i=0;i<edge[s].size();i++)
    {
        t=edge[s][i].first;
        if(used[t]) continue;
        sum[t]=sum[s]+edge[s][i].second;
        dfs(t);
        B[++tot]=tmp;
    }
}
ll lca(ll a,ll b)
{
    if(pos[a]>pos[b]) swap(a,b);
    ll ans=rmq(pos[a],pos[b],B);
    return F[ans];
}
int main()
{
    ll i,a,b,w;
    LOG[0]=-1;
    for(i=1;i<N;i++)  LOG[i]=LOG[i>>1]+1;
    cin >> n;
    for(i=0;i<=n;i++) edge[i].clear();
    for(i=1;i<n;i++)
    {
        cin >> a >> b >> w;
        edge[a].push_back(make_pair(b,w));
        edge[b].push_back(make_pair(a,w));
    }
    sum[1]=0;
    tdfn=0;
    tot=0;
    memset(used,0,sizeof(used));
    dfs(1);
    rmq_init(tot,B);
    cin >> q >> k;
    while(q--)
    {
        cin >> a >> b;
        cout << sum[a]+sum[k]-2*sum[lca(a,k)] + sum[b]+sum[k]-2*sum[lca(b,k)] << endl;
    }
    return 0;
}

