vector<pair<int,int> >G[MAXX];
const int N=100010;
const int LGN=22;
#pragma comment(linker, "/STACK:1000000000")
ll parent[LGN][N],depth[MAXX],vis[MAXX],weight[MAXX];


int uplift(int u,int k){
	for(int i=0;i<LGN;i++){
		if(k&1)u=parent[i][u];
		k>>=1;
	}
	return u;
}
void dfs(int src){
	vis[src]=1;
	for(int i=0;i<G[src].size();i++){
		int v=G[src][i].first;
		int w=G[src][i].second;
		if(vis[v])continue;
		parent[0][v]=src;
		weight[v]=weight[src]+w;
		depth[v]=depth[src]+1;
		dfs(v);
	}
}
void init(int k)
{
	dfs(k);
	for(int i=1;i<LGN;i++){
		for(int j=0;j<N;j++){
			if(parent[i-1][j]!=-1){
				parent[i][j]=parent[i-1][parent[i-1][j]];
			}
		}
	}
}
int lca(int u,int v){
	int diff=abs(depth[u]-depth[v]);
	if(depth[u]>depth[v]){
		u=uplift(u,diff);
	}
	else if(depth[v]>depth[u]){
		v=uplift(v,diff);
	}
	if(u==v)return u;
	for(int i=LGN-1;i>=0;i--){
		if(parent[i][u]!=parent[i][v]){
			u=parent[i][u];
			v=parent[i][v];
		}
	}

	return parent[0][u];
}
int main()
{

	memset(parent,-1,sizeof parent);
	memset(vis,0,sizeof vis);
	memset(weight,0,sizeof weight);
	int n;
	cin>>n;
	for(int i=1;i<=n-1;i++){
		int u,v,w;
		cin>>u>>v>>w;
		u--; v--;
		G[u].pb({v,w});
		G[v].pb({u,w});
	}
	int q, k;
	cin>>q >> k;
	k--;
	init(k);
	for(int i=0;i<q;i++){
		int a,b;
		cin>>a>>b;
		a--, b--;
		int lc=lca(a,b);
		if(lc == k){
		ll ans=weight[a]+weight[b]-2*weight[lc];
		   cout << ans << endl;
		}
		else{
           ll ans1 = weight[a]+weight[k]-2*weight[k];
           ll ans2 = weight[k]+weight[b]-2*weight[k];
           ll ans = min(ans1, ans2);
           ll diff = abs(ans1-ans2);
           cout << 2*ans+diff << endl;
		}

	}
	return 0;
}

