struct lca {
    int n, root;
    undigraph<int> g;
    vector<vector<int>> par;
    vi dep;
    vi disv;
    bool costallone;
    void dfs(int v, int p, int d) {
        dep[v] = d;
        par[0][v] = p;
        fort(gi, g[v])dfs(t, v, d + 1);
    }
    lca(undigraph<> &g_, int root_ = 0) : g(g_), root(root_) {
        n = g.size();
        par.assign(30, vi(n));
        dep.resize(n);
        costallone = 1;
        fora(e, g.edges)if (e.cost != 1)costallone = 0;
        dfs(root, -1, 0);
        rep(k, par.size() - 1) {
            rep(i, n) {
                if (par[k][i] == -1)par[k + 1][i] = -1;
                else par[k + 1][i] = par[k][par[k][i]];
            }
        }
        if (costallone)disv = dep;
        else disv = dijkstra(g, root);
    }
    int getlca(int u, int v) {
        if (dep[u] > dep[v])swap(u, v);
        rep(k, par.size()) {
            if ((dep[u] - dep[v]) >> k & 1) {
                v = par[k][v];
            }
        }
        if (u == v)return u;
        rer(k, par.size() - 1) {
            if (par[k][u] != par[k][v]) {
                u = par[k][u];
                v = par[k][v];
            }
        }
        return par[0][u];
    }
    int dis(int u, int v) {
        int p = getlca(u, v);
        return disv[u] + disv[v] - disv[p] * 2;
    }
};
