typedef long long lint;
typedef pair<lint,lint> pp;
typedef vector<pp> vecP;
typedef vector<vecP> graph;

int N,Q,K;
const int MAX_N = 100010;
int par[MAX_N][20],height[MAX_N];
lint dist[MAX_N];
graph path;

void dfs(int v,int p,lint h){
	dist[v] = h;
	par[v][0] = p;
	for(int i=0;i<(int)path[v].size();i++){
		int u = path[v][i].first;
		if(u==p)continue;
		dfs(u,v,h+path[v][i].second);
	}
}

void init(){
	dfs(1,1,0);
	for(int i=1;i<20;i++){
		for(int j=1;j<=N;j++){
			par[j][i] = par[par[j][i-1]][i-1];
		}
	}
	for(int i=1,x;i<=N;i++){
		x=i;
		for(int j=19;j>=0;j--){
			if(par[x][j] != 1){
				x = par[x][j];
				height[i] += 1<<j;
			}
		}
	}
}

int LCA(int x,int y){
	if(height[x] < height[y])swap(x,y);
	int dif = height[x] - height[y];
	for(int i=19;i>=0;i--){
		if(dif>>i&1)x = par[x][i];
	}
	if(x==y)return x;
	for(int i=19;i>=0;i--){
		if(par[x][i]!=par[y][i]){
			x = par[x][i];
			y = par[y][i];
		}
	}
	return par[x][0];
}

lint getDist(int x,int y){
	int z = LCA(x,y);
	return dist[x]+dist[y]-2*dist[z];
}

int main(){
	scanf("%d",&N);
	path.assign(N+1,vecP());
	int x,y,z;
	for(int i=0;i<N-1;i++){
		scanf("%d%d%d",&x,&y,&z);
		path[x].push_back({y,z});
		path[y].push_back({x,z});
	}

	init();

	scanf("%d%d",&Q,&K);
	for(int i=0;i<Q;i++){
		scanf("%d%d",&x,&y);
		printf("%lld\n",getDist(x,K)+getDist(y,K));
	}
	return 0;
}

