using namespace std;

struct edge{
    int to;
    long long cost;
};

typedef pair<long long, int> P;
const long long INF = 10000000;
vector<long long> dist;

typedef vector<vector<edge> > AdjList;
AdjList graph;

void dijkstra(int n, int s){
    dist = vector<long long>(n,INF);
    dist[s] = 0;
    priority_queue<P, vector<P>, greater<P> > que;
    que.push(P(0,s));

    while(!que.empty()){
        P p = que.top();
        que.pop();
        int v = p.second;
        if(dist[v] < p.first){
            continue;
        }
        for(int i=0; i<graph[v].size(); i++){
            edge e = graph[v][i];
            if(dist[e.to] > dist[v] + e.cost){
                dist[e.to] = dist[v] + e.cost;
                que.push(P(dist[e.to],e.to));
            }
        }
    }
}

int main(void){
    int n;
    cin >> n;
    graph = AdjList(2*n);
    for(int i=0; i<n-1; i++){
        int a, b;
        long long c;
        cin >> a >> b >> c;
        a--;
        b--;
        graph[a].push_back((edge){b,c});
        graph[b].push_back((edge){a,c});
    }
    int q, k;
    cin >> q >> k;
    k--;
    dijkstra(n,k);
    for(int i=0; i<q; i++){
        int x, y;
        long long ans = 0;
        cin >> x >> y;
        x--;
        y--;
        ans = dist[x] + dist[y];
        cout << ans << endl;
    }
    return 0;
}

