    for (ll i = 0; i < n - 1; i++)
    {
        cin >> a >> b >> c;
        g[a - 1][b - 1] = c;
        g[b - 1][a - 1] = c;
    }
    ll q, k;
    cin >> q >> k;

    // ダイクストラ法
    dijkstra(n, dist, g, k);

    ll x, y;
    for (ll i = 0; i < q; i++)
    {
        cin >> x >> y;
        cout << dist[x - 1] + dist[y - 1] << endl;
    }

    return 0;
}

