// v: 今いる頂点, p: v の親
void dfs(int v, int p, long long d) {
    depth[v] = d;
    for (int i = 0; i < tree[v].size(); i++) {
        edge e = tree[v][i];
        // 戻らないようにする処理
        if (e.to == p) { continue; }
        dfs(e.to, v, d + e.cost);
    }
}

