using V = vector<P>;

vector<int64> bfs(const int& n, const int& k, const vector<V>& g) {
    vector<int64> res(g.size()+1,-1);
    queue<P> q;
    q.emplace(k,0);

    while(!q.empty()) {
        int64 u,c;
        tie(u,c) = q.front(); q.pop();
        if (res[u] > 0) continue;
        res[u] = c;
        for (auto p : g[u]) {
            int64 v,d;
            tie(v,d) = p;
            q.emplace(v, c+d);
        }
    }
    return res;
}


