void dfs(int node,int pa)
{
	hi[node]=hi[pa]+1;
	dp[node][0]=pa;
	for(int i=1;i<20;i++)
		dp[node][i]=dp[dp[node][i-1]][i-1];
	for(auto i:adj[node])
	{
		if(i.F==pa) continue;
		dis[i.F]=dis[node]+i.S;
		dfs(i.F,node);
	}
}

int lca(int x,int y)
{
	if(hi[x]<hi[y]) swap(x,y);
	for(int i=19;i>=0;i--)
	{
		if(hi[x]-(1<<i) >=hi[y])
			x=dp[x][i];
	}
	if(x==y) return x;
	for(int i=19;i>=0;i--)
	{
		if(dp[x][i]!=dp[y][i])
		{
			x=dp[x][i]; y=dp[y][i];
		}
	}
	return dp[x][0];
}

long long dist(int a,int b)
{
	//cout << a << " " << b << " " << lca(a,b) << endl;
	return dis[a]+dis[b]-2*dis[lca(a,b)];
}

