typedef long long ll;
typedef pair<ll,ll> P;
#define NODE 100001
#define INF 1000000000
#define LLINF 1000000000000000000LL

//v[i][j]; j番目の辺。iからfirstへの有向辺で、コストはsecond。
vector<vector<pair<ll,ll> > > v(NODE);
ll dist[NODE];
int dijkstra(int start){
  //初期化
  for(int i = 0;i < NODE;i++)dist[i] = LLINF;
  dist[start] = 0;
  //priority_queueの宣言
  //pqに入れているのは(startからtoへの最短距離, to)
  //priority_queueの都合上、vのpairの順番とは逆にしている。
  priority_queue<P,vector<P>,greater<P> > pq;
  pq.push(make_pair(0,start));
  while(!pq.empty()){
    //現在見る者の中で、最もdistが小さいものを取り出す
    P now = pq.top();pq.pop();
    ll d = now.first;
    ll node = now.second;
    //すでに更新されていたりして、現在のが最適でなかったらスルー
    if(dist[node] < d)continue;
    //その点と辺を持つものに対して
    for(int i = 0;i < v[node].size();i++){
      ll opp_n = v[node][i].first;
      ll opp_d = v[node][i].second;
      //もし、distが更新できるならば、更新してpriority_queueに突っ込む
      if(dist[opp_n] > d + opp_d){
        dist[opp_n] = d + opp_d;
        pq.push(make_pair(dist[opp_n],opp_n));
      }
    }
  }
}

