    v[b].PB(MP(a,c));
  }
  int Q, K;
  cin >> Q >> K;
  dijkstra(K - 1);

  REP(i, Q) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    cout << (dist[x] + dist[y]) << endl;
  }

  return 0;
}

