vector<int> V[100001];

ll bfs(int s, int g) {
    ll d[100001];
    queue<int> que;
    for(int i = 0; i < 100000; i++) d[i] = INF;

    que.push(s);
    d[s] = 0;

    while(que.size()) {
        int f = que.front(); que.pop();
        if (f == g) break;

        for (ll i = 0; i < V[f].size(); i++) {
            int n = V[f][i];
            if (d[n] == INF) {
                que.push(n);
                d[n] = d[f] + G[P(f, n)];
            }
        }
    }

    return d[g];
}

