vector<P> G[MAX_V];
int root;

int parent[MAX_V];
int depth[MAX_V];
ll dist[MAX_V];

void dfs(int v, int p, int d, ll len){
	parent[v] = p;
	depth[v] = d;
	for (int i = 0; i < (int)G[v].size(); ++i){
		if (G[v][i].first != p){
			dfs(G[v][i].first, v, d + 1, len + G[v][i].second);
		} // end if
	} // end for
	dist[v] = len;
}

void init(void){
	dfs(root, -1, 0, 0);
}

int lca(int u, int v){
	while(depth[u] > depth[v]) u = parent[u];
	while(depth[v] > depth[u]) v = parent[v];

	while(u != v){
		u = parent[u];
		v = parent[v];
	} // end while

	return u;
}

bool is_lca(int x, int y, int z){
	int u = lca(x, y);
	return u == z;
}

ll solve(int v, int w){
	int u = lca(v, w);
//	int res = depth[v] + depth[w] - 2 * depth[u];
	ll res = dist[v] + dist[w] - 2LL * dist[u];
}

