ll Ans[A];

void add(int u,int v,ll w){
    G[tot].v = v;
    G[tot].w = w;
    G[tot].next = head[u];
    head[u] = tot++;
}

void dfs(int u,int pre,ll dep){
    Ans[u] = min(Ans[u],dep);
    for(int i=head[u] ;i!=-1 ;i=G[i].next){
        int v = G[i].v;
        if(v == pre) continue;
        ll w = G[i].w;
        dfs(v,u,dep+w);
    }
}

