using namespace std;
using ll = long long;

struct Node {
    vector<int> to;
    vector<ll> to_cost;

    bool done;
    ll dist;
};

void calc_dist(int pos, vector<Node>& node) {
    node[pos].done = true;
    for (int i = 0; i < node[pos].to.size(); i++) {
        int next = node[pos].to[i];
        if (node[next].done == false) {
            node[next].dist = node[pos].dist + node[pos].to_cost[i];
            calc_dist(next, node);
        }
    }
}

int main() {
    int N;
    cin >> N;
    vector<Node> node(N);

    for (int i = 0; i < N - 1; i++) {
        int a, b; ll c;
        cin >> a >> b >> c;
        a--; b--;
        node[a].to.push_back(b);
        node[a].to_cost.push_back(c);
        node[b].to.push_back(a);
        node[b].to_cost.push_back(c);
    }

    int Q, K;
    cin >> Q >> K; K--;

    // 頂点 K からの最短距離
    node[K].dist = 0;
    calc_dist(K, node);

    vector<int> x(Q), y(Q);
    for (int i = 0; i < Q; i++) {
        cin >> x[i] >> y[i];
        x[i]--; y[i]--;
    }

    for (int i = 0; i < Q; i++) {
        cout << node[x[i]].dist + node[y[i]].dist << endl;
    }

    return 0;
}

