  for(int i=0;i<n-1;i++) {
    int a, b;
    long long int c;
    cin >> a >> b >> c;
    a--;
    b--;
    V[a].emplace_back(make_pair(b, c));
    V[b].emplace_back(make_pair(a, c));
  }
  vector<long long int> d(n);
  vector<int> prev(n);
  auto compare = [](pair<int, long long int> ap, pair<int, long long int> bp) {
    return (ap.second > bp.second);
  };
  priority_queue<pair<int, long long int>, vector<pair<int, long long int>>, decltype(compare)> que{compare};

  int q, k;
  cin >> q >> k;
  k--;

  for(int i=0;i<n;i++) {
    if(i == k) d[i] = 0;
    else d[i] = 1e18;
    prev[i] = -1;
