  while(!que.empty()) {
    pair<int, long long int> p = que.top();que.pop();
    for(int i=0;i<V[p.first].size();i++) {
      long long int alt = p.second + V[p.first][i].second;
      if(d[V[p.first][i].first] > alt) {
        d[V[p.first][i].first] = alt;
        prev[V[p.first][i].first] = p.first;
        que.emplace(make_pair(V[p.first][i].first, alt));
      }
    }
