#include<bits/stdc++.h>
using namespace std;
#define MAX 100005
typedef long long ll;

struct edge{
  ll to,cost;
};

ll n,a,b,c;
vector< edge > G[MAX];
ll size[MAX];
ll par[MAX];
ll dep[MAX];
ll depth[MAX];
ll parent[MAX];

void idfs(int pos,int prev=-1){
  int m=-1;
  if(G[pos].empty())return;
  for(int i=0;i<(int)G[pos].size();i++){
    edge e=G[pos][i];
    if(e.to==prev)continue;
    depth[e.to]=depth[pos]+e.cost;
    parent[e.to]=pos;

    idfs(e.to,pos);
    size[pos]+=size[e.to];
    if(m==-1||size[m]<size[e.to])m=e.to;
  }
  par[m]=pos;
}

int calc(int x){
  if(par[x]==x)return x;
  return par[x]=calc(par[x]);
}

void init(){
  for(int i=0;i<MAX;i++){
    size[i]=1;
    par[i]=i;
  }

  for(int i=0;i<n-1;i++){
    ll a,b,c;
    scanf("%lld %lld %lld",&a,&b,&c);
    a--,b--;
    G[a].push_back( (edge){b,c} );
    G[b].push_back( (edge){a,c} );
  }
  parent[0]=-1;  
  idfs(0);

  for(int i=0;i<n;i++){
    int p=calc(i);
    while(p){
      p=par[parent[p]];
      dep[i]++;
    }
  }
}

ll Cal(ll a,ll b){
  ll ans=depth[a]+depth[b];
  while(par[a]!=par[b]){
    if(dep[a]<dep[b])swap(a,b);
    a=parent[par[a]];
  }
  ll target=(depth[a]<depth[b]?a:b);
  return ans-depth[target]*2;
}

int main(){
  scanf("%lld",&n);
  init();
  ll q;
  scanf("%lld",&q);
  ll K;
  scanf("%lld",&K);
  K--;
  while(q--){
    scanf("%lld %lld",&a,&b);
    a--,b--;
    ll ans=Cal(a,K) + Cal(K,b);
    printf("%lld\n",ans);
  }
  return 0;
}

