long lcm(long x, long y){ return (x / gcd(x, y) * y); }

void dps(long now, long par, vector<vector<long>> &graph, map<pair<long, long>, long>& weight, vector<long> &dist){
	if (par == -1) dist[now] = 0;
	else dist[now] = dist[par] + weight[make_pair(par, now)];

	for (auto e : graph[now]){
		if (e == par) continue;
		dps(e, now, graph, weight, dist);
	}
}

