using namespace std;
using ll = long long;
using P = pair<int, int>;

class Tree {
	using T = pair<ll, int>;
	int n;
	vector<vector<T>> edge;
	vector<ll> d;

public:
	Tree(int N) : n(N), edge(N), d(N, INT64_MAX) {}
	void add(int a, int b, ll c) {
		edge[a].emplace_back(c, b);
		edge[b].emplace_back(c, a);
	}
	void dfs(int k, int p = -1) {
		if (p < 0) d[k] = 0;
		for (auto &t : edge[k]) {
			ll c;
			int j;
			tie(c, j) = t;
			if (j == p) continue;
			d[j] = d[k] + c;
			dfs(j, k);
		}
	}
	ll distance(int i) {
		return d[i];
	}
};

