void dijkstra(int s){
	priority_queue<P,vector<P>,greater<P>> que;
	d[s]=0;
	que.push(P(0,s));
	while(que.size()){
		P p=que.top();
		que.pop();
		if(d[p.second]<p.first)continue;
		for(int i=0;i<g[p.second].size();i++){
			edge e=g[p.second][i];
			if(d[p.second]<d[e.to]+e.cost){
				d[e.to]=d[p.second]+e.cost;
				que.push(P(d[e.to],e.to));
			}
		}
	}
}

