void search(int node, vector<vector<pair<int,long>>> &path,vector<long> &route, vector<int> &s, vector<int> v){
    static int isSearch=1;
    vector<int> next;
    for(auto n : v){
        for(auto p : path[n]){
            if(s[p.first]==0){
                s[p.first]=1;
                isSearch++;
                next.push_back(p.first);
                route[p.first]=route[n]+p.second;
            }
        }
    }
    if(isSearch!=node){
        search(node,path,route,s,next);
    }
}

