template<class T> using WeightedGraph = vector<vector<Edge<T>>>;
template<class T>
vector<T> dijkstra(WeightedGraph<T>& g, int s){
    const auto INFD = numeric_limits<T>::max();
    vector<T> dist(g.size(),INFD);
    dist[s] = 0;
    using pd = pair<T, int>;
    priority_queue<pd,vector<pd>,greater<pd>> que;
    que.emplace(dist[s],s);
    while(!que.empty()){
        T cost; int idx;
        tie(cost,idx) = que.top(); que.pop();
        if(dist[idx]<cost) continue;
        for(auto& e: g[idx]){
            if(dist[e.to] > dist[idx]+e.cost){
                dist[e.to] = dist[idx]+e.cost;
                que.emplace(dist[e.to],e.to);
            }
        }
    }
    return dist;
}
