const long point_maxn = 100005;   //点的最大上限
struct node
{/*node存储边，一个edge代表一条边*/
    LL v;     //终点位置
    LL w;     //权值
    LL next;  //同一起点的下一条边存储在edge数组中的位置（理解了这个静态邻接表就可以了）
}edge[edge_maxn];
LL pre[point_maxn];  //以该点为起点的第一条边存储在edge数组中的位置
LL n;  //点的数量
LL m;  //边的数量
queue<LL> Q;
LL dirs[point_maxn];
bool vis[point_maxn];
void Init()
{
    memset(pre,-1,sizeof(pre));
    LL Index = 1;
    LL i,j,flag;
    LL x,y,w;
    for(i=0;i<m;i++)
    {
        scanf("%lld%lld%lld",&x,&y,&w);
        for(flag=0,j=pre[x];j!=-1;j=edge[j].next)
        {//重边的情况
            if(y == edge[j].v)
            {
                if(w < edge[j].w)
                    edge[j].w = w;
                flag = 1;
                break;
            }
        }
        if(flag == 1)
            continue;
        edge[Index].v = y;
        edge[Index].w = w;
        edge[Index].next = pre[x];  //保存x起点的上一条边在edge数组中的位置
        pre[x] = Index++;  //位置更新
        swap(x,y);
        edge[Index].v = y;
        edge[Index].w = w;
        edge[Index].next = pre[x];
        pre[x] = Index++;
    }
}

void SPFA()
{
    LL q,k;
    cin>>q>>k;
    LL start = k;

    while(!Q.empty())
    {
        Q.pop();
    }
    memset(vis,0,sizeof(vis));
    fill(dirs,dirs+point_maxn,lmax);
    dirs[start] = 0;
    vis[start] = 1;
    Q.push(start);
    while(!Q.empty())
    {
        LL top = Q.front(); //边的起点
        Q.pop();
        vis[top] = 0;
        for(LL j=pre[top];j!=-1;j=edge[j].next)
        {
            LL e = edge[j].v; //边的终点
            if(dirs[e] > edge[j].w + dirs[top])
            {
                dirs[e] = edge[j].w + dirs[top];
                if(!vis[e])
                {
                    Q.push(e);
                    vis[e] = 1;
                }
            }
        }
    }
    FOR(i,1,q) {
        LL x,y;
        scanf("%lld%lld",&x,&y);
        printf("%lld",dirs[x]+dirs[y]);

    }
}

int main()
{
    scanf("%lld",&n);
    m=n-1;
    Init();
    SPFA();
    return 0;
}

