using namespace std;
typedef long long LL;
const int MAXN = 1e6 + 5;
int pre[MAXN],other[MAXN],last[MAXN];
long long dis[MAXN];
int all,n,q,k;
int cost[MAXN],seq[MAXN];
bool Inque[MAXN];
void Build(int x, int y, LL w){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int x){
	int head = 1, tail = 1, now, dt, dr;
	seq[tail] = x;
	for(int i = 1; i <= n; i++)
	{
		if(i == x) dis[i] = 0;
		else dis[i] = 10000000000000000;
	}
	Inque[x] = 1;
	while(head <= tail){
		now = seq[head];
		dt = last[now];
		while(dt != -1){
			dr = other[dt];
			if(dis[now] + cost[dt] < dis[dr]){
				dis[dr] = dis[now] + cost[dt];
				if(!Inque[dr]){
					Inque[dr] = 1; 
					seq[++tail] = dr;
				}
			}
			dt = pre[dt];
		}
		Inque[now] = 0;
		head++;
	}
}

int main()
{
	all = -1;
	memset(last, -1, sizeof(last));
	scanf("%d",&n);

	for(int i = 1; i < n; i++){
		int a,b;
		LL w;
		scanf("%d%d%d",&a,&b,&w);
		Build(a,b,w);
		Build(b,a,w);
	}
	memset(seq, 0,sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	Bfs(k);
	scanf("%d%d",&q,&k);
	while(q--){
		int x,y;
		scanf("%d%d",&x,&y);
		printf("%lld\n",dis[x]+dis[y]);
	}
}

