struct edge{
    ll to,cost;  
};

void dijkstra(vector<vector<edge> > &G,vector<ll> &d,ll s){
    PQ que;
    fill(d.begin(),d.end(), LINF);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()){
        P p = que.top(); que.pop();
        ll v = p.second;
        if(d[v] < p.first) continue;

        rep(i,0,G[v].size()){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to],e.to));
            }

        }
    }


}

