struct inout {
  static const long long ibufl = 1 << 25;
  static const long long obufl = 1 << 25;
  char in_buf[ibufl], out_buf[obufl], *inf, *ouf;
  void init() {
    fread(in_buf, 1, ibufl, stdin);
    inf = in_buf;
    ouf = out_buf;
  }
  inout &operator>>(long long &a) {
    long long fh = 1;
    while (!(isdigit(*inf) || *inf == '-')) ++inf;
    if (*inf == '-') fh = -1, ++inf;
    a = 0;
    while (isdigit(*inf)) {
      a = a * 10 + *inf - '0';
      ++inf;
    }
    a *= fh;
    return *this;
  }
  void writeint(long long x) {
    if (x / 10) writeint(x / 10);
    *ouf = x % 10 + '0';
    ++ouf;
  }
  inout &operator<<(long long a) {

    if (a < 0) {
      *ouf = '-';
      ++ouf;
      a = -a;
    }
    writeint(a);
    return *this;
  }
  static const long long sz = 7;
  inout &operator<<(char a) {
    *ouf = a;
    ++ouf;
    return *this;
  }
  inout &operator<<(char *a) {
    while (*a) {
      *ouf = *a;
      ++ouf;
      ++a;
    }
    return *this;
  }
  void out() { fwrite(out_buf, 1, ouf - out_buf, stdout); }
};
inout io;

using Weight = int;
struct Edge {
  int dst;
  Weight weight;
  Edge() : dst(0), weight(0) {}
  Edge(int d, Weight w = 1) : dst(d), weight(w) {}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

vector<Edge> G[100005];
ll dist[100005];

void dfs(int cur, int pre) {
  for (const auto &nex : G[cur]) {
    if (nex.dst != pre) {
      dist[nex.dst] = dist[cur] + nex.weight;
      dfs(nex.dst, cur);
    }
  };
}

void Main() {
  ll n;
  io.init();
  io >> n;
  rep(i, n - 1) {
    ll u, v, w;
    io >> u >> v >> w;
    G[u].emplace_back(v, w);
    G[v].emplace_back(u, w);
  }

  ll q, k;
  io >> q >> k;

  dfs(k, -1);

  while (q--) {
    ll u, v;
    io >> u >> v;
    io << dist[u] + dist[v] << '\n';
  }
  io.out();
}

