    int to;
    long long cost;
    edge(const int to_, const long long cost_):to(to_), cost(cost_){}
};

using Graph = vector<vector<edge>>;

long long bfs(const Graph& G, const int s, const int x, const int y){
    queue<pair<int, long long>> q;
    q.push(make_pair(s, 0)); // fisrt: vertex, second: current cost
    long long ret = 0;
    vector<bool> visited(G.size(), false);

    while(!q.empty()){
        const int current_v = q.front().first;
        const long long current_cost = q.front().second;
        q.pop();
        visited[current_v] = true;

        if(x == current_v || y == current_v){
   //         cout << current_cost << endl;
            ret += current_cost;
        }
        if(visited[x] && visited[y])
            break;

        for(const auto& e : G[current_v]){
            if(visited[e.to]) continue;
            q.push(make_pair(e.to, current_cost + e.cost));
        }
    }

    return ret;
}

