void dfs(int v, int p, int d){
  parent[0][v] = p;
  depth[v] = d;
  for(int i=0; i<G[v].size(); i++){
    if(G[v][i] != p) dfs(G[v][i], v, d+1);
  }
}
void init(int root){
  dfs(root, -1, 0);
  for(int k=0; k+1<64; k++){
    for(int v=0; v<N+1; v++){
      if(parent[k][v] < 0) parent[k+1][v] = -1;
      else parent[k+1][v] = parent[k][parent[k][v]];
    }
  }
}
int lca(int u, int v){
  if(depth[u] > depth[v]) swap(u, v);
  for(int k=0; k<64; k++){
    if((depth[v] - depth[u]) >> k & 1){
      v = parent[k][v];
    }
  }
  if(u==v) return u;
  for(int k=64-1; k>=0; k--){
    if(parent[k][u] != parent[k][v]){
      u = parent[k][u];
      v = parent[k][v];
    }
  }
  return parent[0][u];
}


void calc_dist(ll v, ll d){
  if(dist[v] != -1) return;
  dist[v] = d;
  rep(i,GG[v].size()){
    calc_dist(GG[v][i].first, d+GG[v][i].second);
  }
}

ll calc(int root, int x, int y){
  int z = lca(x, y);
  return abs(dist[z]-dist[x]) + abs(dist[z]-dist[y]);
}

