		int v = G[src][i].first;
		int w = G[src][i].second;
		if(vis[v])continue;
		parent[v][0]=src;
		weight[v]=weight[src]+w;
		depth[v]=depth[src]+1;
		dfs(v);
	}
}
void init(int k)
{
    parent[k][0] = k;
	dfs(k);
		for(int i = 1; i <= N; i++){
            for(int j = 1; j < LGN; j++)
                parent[i][j] = parent[parent[i][j-1]][j-1];
		}

}
int lca(int u,int v){
	int diff=abs(depth[u]-depth[v]);
	if(depth[u]>depth[v]){
		u=uplift(u,diff);
	}
	else if(depth[v]>depth[u]){
		v=uplift(v,diff);
	}
	if(u==v)return u;
	for(int i=LGN-1;i>=0;i--){
		if(parent[u][i]!=parent[v][i]){
			u=parent[u][i];
			v=parent[v][i];
		}
	}

	return parent[u][0];
}
