void finddist(int pwd, int parent, vector<vector<long>> &edge, vector<long> &kdistance) {
    kdistance[pwd] = kdistance[parent] + edge[parent][pwd];
    for (int node = 1; node < edge.size(); node++) {
        if (node == parent || node == pwd || edge[pwd][node] == MAXC) continue;
        finddist(node, pwd, edge, kdistance);
    }
}

