    edge(int to, int cost) : to(to), cost(cost) {}
};
typedef vector< vector < edge > > Graph;

void dfs(Graph &G, int st, vector<llint> &dist){
    stack<int> S;
    int N = G.size();
    static vector<vector<edge>::iterator> itr(N);
    REP(i, N){ itr[i] = G[i].begin(); }
    static vector<int> done(N, 0);
    S.push(st);
    dist[st] = 0;
    while(!S.empty()){
        int u = S.top();
        if(itr[u] == G[u].end()){
            S.pop();
            done[u] = 2;
        }else{
            edge v = *itr[u]++;
            if(!done[v.to]){
                done[v.to] = 1;
                S.push(v.to);
                if(dist[v.to] == -1) dist[v.to] = dist[u] + v.cost;
            }
        }
    }
}

