int vis[maxn];
int pre[maxn];
int head1[maxn],head2[maxn];
ll dis[maxn];

struct node
{
    int s,t,w,lca,next;
}e1[maxn*2],e2[maxn*4];

void init()
{
    mst(vis,0);
    mst(dis,0);
    mst(head1,-1);
    mst(head2,-1);
    for(int i=1;i<=n;i++)
        pre[i]=i;
}

int find(int x)
{
    int t,r=x;
    while(x!=pre[x])
    {
        x=pre[x];
    }
    while(r!=x)
    {
        t=pre[r];
        pre[r]=x;
        r=t;
    }
    return x;
}

void join(int a,int b)
{
    int A,B;
    A=find(a);
    B=find(b);
    if(A!=B)
        pre[B]=A;
}
void add1(int s,int t,int w)
{
    e1[cnt].s=s;
    e1[cnt].t=t;
    e1[cnt].w=w;
    e1[cnt].next=head1[s];
    head1[s]=cnt++;
}

void add2(int s,int t)
{
    e2[cnt].s=s;
    e2[cnt].t=t;
    e2[cnt].lca=-1;
    e2[cnt].next=head2[s];
    head2[s]=cnt++;
}

void Tarjan(int now)
{
    vis[now]=1;
    for(int i=head1[now];i!=-1;i=e1[i].next)
    {
        int t=e1[i].t;
        if(vis[t]==0)
        {
            int w=e1[i].w;
            dis[t]=dis[now]+w;
            Tarjan(t);
            join(now,t);
        }
    }
    for(int i=head2[now];i!=-1;i=e2[i].next)
    {
        int t=e2[i].t;
        if(vis[t]==1)
        {
            e2[i].lca=find(t);
            e2[i^1].lca=e2[i].lca;
        }
    }
}

