    {
        init();
        cnt=0;
        for(int i=0;i<n-1;i++)
        {
            scanf("%d%d%d",&x,&y,&w);
            add1(x,y,w);
            add1(y,x,w);
        }
        cnt=0;
        scanf("%d%d",&q,&k);
        for(int i=0;i<q;i++)
        {
            scanf("%d%d",&x,&y);
            add2(x,k);
            add2(k,x);
            add2(k,y);
            add2(y,k);
        }
        Tarjan(1);
        for(int i=0;i<q;i++)
        {
            int now=i*4;
