{
	lvl[v]=lvl[u]+1;
	p[0][v]=u;
	sum[0][v]=cost[{v,u}];
	for(ll i=1;i<19;++i)
		p[i][v]=p[i-1][p[i-1][v]],sum[i][v]=sum[i-1][v]+sum[i-1][p[i-1][v]];
	for(ll to:g[v])
		if (to!=u)
			dfs(to,v);
}
ll lca(ll a,ll b)
{
	if(lvl[a]>lvl[b])swap(a,b);
	ll res=0;
	for(ll i=18;i>=0;--i)
		if(lvl[a]<=lvl[p[i][b]])
			res+=sum[i][b],b=p[i][b];
	if(a==b)return res;
	for(ll i=18;i>=0;--i)
		if(p[i][a]!=p[i][b])
			res+=sum[i][a]+sum[i][b],a=p[i][a],b=p[i][b];
	return res+sum[0][a]+sum[0][b];
}
