const int maxn=100010;

int n,q,k;
vector<pair<int,LL> > e[maxn];
LL dist[maxn];

inline void dij()
{
	MINF(dist);
	dist[k]=0;

	priority_queue<pair<LL,int>,vector<pair<LL,int> >,greater<pair<LL,int> > > q;
	q.push({dist[k],k});

	while(!q.empty())
	{
		int x=q.top().sc;
		LL res=q.top().fs;
		q.pop();
		if(dist[x]!=res) continue;

		repV(i,e[x]) if(res+i.sc<dist[i.fs])
		{
			dist[i.fs]=res+i.sc;
			q.push({dist[i.fs],i.fs});
		}
	}
}

