		e[x].push_back({y,z});
		e[y].push_back({x,z});
	}

	SF("%d%d",&q,&k);
	dij();

	while(q--)
	{
		int x,y;SF("%d%d",&x,&y);

		PF("%lld\n",dist[x]+dist[y]);
	}

	return 0;
}
