		tree[a].push_back({b,c});
		tree[b].push_back({a,c});
	}

	int q,k;
	cin >> q >> k;
	k--;

	dfs(k,-1,0);
	for(int i=0;i<q;i++){
		int x,y;
		cin >> x >> y;
		x--,y--;
		cout << depth[x] + depth[y] << endl;
	}
	return 0;
}

