    long i, len = n - 1;

    for (i = 0; i < n; i++) nodes[i].id = i;

    for (i = 0; i < len; i++) {
        cin >> a >> b >> c;

        a--;
        b--;

        nodes[a].connects.push_back(make_pair(b, c));
        nodes[b].connects.push_back(make_pair(a, c));
    }

    cin >> q >> k;

    k--;

    map<long, ll> table;

    solve(nodes, k, table);

    for (i = 0; i < q; i++) {
        cin >> a >> b;

        a--;
        b--;

        cout << table[a] + table[b] << endl;
    }

    return 0;
}

