    G[b].push_back(edge{a, c});
  }
  int q,k;
  cin>>q>>k;
  k--;
  dijkstra(k);
  int x,y;
  long long res;
  REP(i,q){
    cin>>x>>y;
    x--;y--;
    res = (long long)(dist[x]+dist[y]);
    cout<<res<<endl;
  }
  return 0;
}

