int n;
vector<vector<pair<int,long long>>> graph;
vector<long long> dist;

void bfs(int v,long long c){
  queue<pair<int,long long>> que;
  que.emplace(v,c);
  while(!que.empty()){
    v=que.front().first;
    c=que.front().second;
    que.pop();
    dist[v]=c;
    for(auto e:graph[v]){
      if(dist[e.first]!=-1) continue;
      que.emplace(e.first,e.second+c);
    }
  }
}

