    a--;b--;
    graph[a].emplace_back(b,c);
    graph[b].emplace_back(a,c);
  }

  int q,k;
  cin >> q >> k;
  bfs(k-1,0);
  for (int i = 0; i < q; i++)
  {
    int x,y;
    cin >> x >> y;
    cout << dist[x-1]+dist[y-1] << endl;
  }
}

