	Tree() {le=2;}
	void in(int x,int y,int v)
	{
		edge[le].to=y;
		edge[le].v=v;
		edge[le].next=first[x];
		first[x]=le++;
	}
	void insert(int x,int y,int v)
	{
		in(x,y,v);
		in(y,x,v);
	}
	void dfs(int x,int f,int v,int cur)
	{
		st[x][0]=v;
		fa[x][0]=f;
		dep[x]=cur;
		for (int i=first[x];i;i=edge[i].next)
			if (edge[i].to!=f)
				dfs(edge[i].to,x,edge[i].v,cur+1);
	}
	void makest()
	{
		for (int j=1;j<=18;j++)
			for (int i=1;i<=n;i++)
			{
				fa[i][j]=fa[fa[i][j-1]][j-1];
				st[i][j]=st[i][j-1]+st[fa[i][j-1]][j-1];
			}
	}
	LL find(int x,int y)
	{
		if (dep[x]<dep[y]) swap(x,y);
		LL ans=0;
		for (int j=18;j>=0;j--)
			if (dep[fa[x][j]]>=dep[y]) ans+=st[x][j],x=fa[x][j];
		for (int j=18;j>=0;j--)
			if (fa[x][j]!=fa[y][j])
			{
				ans+=st[x][j];
				ans+=st[y][j];
				x=fa[x][j];
				y=fa[y][j];
			}
		ans+=st[x][0]+st[y][0];
		return ans;
	}
