// dijkstra (route restoration)
template <class T> vector<T> dijkstra(int s, WeightedGraph<T>& adj_list, T inf) {
  int si = sz(adj_list);
  vector<T> dist(si, inf);

  using Pi = pair<T, int>;
  priority_queue<Pi, vector<Pi>, greater<Pi>> que;
  dist[s] = 0;
  que.emplace(dist[s], s);
  while (!que.empty()) {
    T cost;
    int idx;
    tie(cost, idx) = que.top();
    que.pop();
    if (dist[idx] < cost) continue;
    for (auto& e : adj_list[idx]) {
      auto next_cost = cost + e.cost;
      if (dist[e.to] <= next_cost) continue;
      dist[e.to] = next_cost;
      que.emplace(dist[e.to], e.to);
    }
  }
  return dist;
}

int main(int argc, char* argv[]) {
  long long N;
  scanf("%lld", &N);
  std::vector<long long> a(N - 1);
  std::vector<long long> b(N - 1);
  std::vector<long long> c(N - 1);
  WeightedGraph<ll> w(N);
  for (int i = 0; i < N - 1; i++) {
    scanf("%lld", &a[i]);
    scanf("%lld", &b[i]);
    scanf("%lld", &c[i]);
    a[i]--, b[i]--;
    w[a[i]].emplace_back(Edge(b[i], c[i]));
    w[b[i]].emplace_back(Edge(a[i], c[i]));
  }
  long long Q;
  scanf("%lld", &Q);
  long long K;
  scanf("%lld", &K);
  std::vector<long long> x(Q);
  std::vector<long long> y(Q);
  for (int i = 0; i < Q; i++) {
    scanf("%lld", &x[i]);
    scanf("%lld", &y[i]);
  }

  vec<ll> dists = dijkstra(K - 1, w, LL_INF);
  string ans = "";
  rep(i, 0, Q) { ans += to_string(dists[x[i] - 1] + dists[y[i] - 1]) + "\n"; }
  cout << ans;
  return 0;
}

