vector<s64> D; // Kから各頂点への最短距離

void dfs(s64 v, s64 d)
{
    D[v] = d;

    for(const auto& p : G[v]) {
        s64 to   = p.first;
        s64 cost = p.second;

        if(D[to] != INF) continue;
        dfs(to, d+cost);
    }
}

void solve()
{
    D.assign(N, INF);
    dfs(K, 0);

    REP(i, Q) {
        int x, y; cin >> x >> y; --x; --y; // 0-based
        s64 d = D[x] + D[y];
        PRINTLN(d);
    }
}

