        int c;    cin >> c;
        G[a].push_back(make_pair(b,c));
        G[b].push_back(make_pair(a,c));
    }

    cin >> Q;
    cin >> K; --K; // 0-based

    solve();

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define MAX 200005
typedef long long ll;

struct edge{
  ll to,cost;
};

ll n,a,b,c;
vector< edge > G[MAX];
ll size[MAX];
ll par[MAX];
ll dep[MAX];
ll depth[MAX];
ll dist[MAX];
ll parent[MAX];

void idfs(ll pos,ll prev=-1){
  ll m=-1;
  for(int i=0;i<(int)G[pos].size();i++){
    edge e=G[pos][i];
    if(e.to==prev)continue;
    dist[e.to]=dist[pos]+e.cost;
    depth[e.to]=depth[pos]+1;
    parent[e.to]=pos;

    idfs(e.to,pos);
    size[pos]+=size[e.to];
    if(m==-1||size[m]<size[e.to])m=e.to;
  }
  if(m>=0)par[m]=pos;
}

ll calc(ll x){
  if(par[x]==x)return x;
  return par[x]=calc(par[x]);
}

void init(){
  for(int i=0;i<MAX;i++){
    size[i]=1;
    par[i]=i;
  }

  for(int i=0;i<n-1;i++){
    ll a,b,c;
    cin>>a>>b>>c;
    a--,b--;
    G[a].push_back( (edge){b,c} );
    G[b].push_back( (edge){a,c} );
  }

  parent[0]=-1;  
  idfs(0);

  for(int i=0;i<n;i++){
    int p=calc(i);
    while(p){
      p=par[parent[p]];
      dep[i]++;
    }
  }
}

ll Cal(ll a,ll b){
  ll ans=dist[a]+dist[b];
  while(par[a]!=par[b]){
    if(dep[a]<dep[b])swap(a,b);
    a=parent[par[a]];
  }
  ll target=(depth[a]<depth[b]?a:b);
  return ans-dist[target]*2;
}

int main(){
  cin>>n;
  init();
  ll q;
  cin>>q;
  ll K;
  cin>>K;
  K--;
  while(q--){
    cin>>a>>b;
    a--,b--;
    ll ans=Cal(a,K) + Cal(K,b);
    cout<<ans<<endl;
  }
  return 0;
}

#include <bits/stdc++.h>
#define FOR(i, begin, end) for(int i=(begin);i<(end);i++)
#define REP(i, n) FOR(i,0,n)
#define IFOR(i, begin, end) for(int i=(end)-1;i>=(begin);i--)
#define IREP(i, n) IFOR(i,0,n)
#define SORT(a) sort(a.begin(), a.end())
#define REVERSE(a) reverse(a.begin(), a.end())
#define int long long
#define INF 1000000000000000000
using namespace std;

typedef vector<int> vec;
typedef vector<vec> mat;
typedef pair<int, int> Pii;

template<typename T>
void readvec(vector<T> &a);
void readindex(vector<int> &a);

struct edge{int to, cost;};

class Graph
{
public:
    int V;
    vector<vector<edge>> G;
    vec d, root;

    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
        d = vec(V);
        root = vec(V);
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void erase_edge(int from, int to){
        vec e(0);
        REP(i, G[from].size()){
            if(G[from][i].to == to) e.push_back(i);
        }
        IREP(i, e.size()) G[from].erase(G[from].begin() + e[i]);
    }

    void erase_edge2(int v1, int v2){
        erase_edge(v1, v2);
        erase_edge(v2, v1);
    }

    void dijkstra(int s, int t){
        priority_queue<Pii, vector<Pii>, greater<Pii>> que;
        fill(d.begin(), d.end(), INF);
        d[s] = 0;
        que.push(Pii(0, s));

        while(!que.empty()){
            Pii p = que.top(); que.pop();
            int v = p.second;
            if(v == t) return;
            if(d[v] < p.first) continue;
            REP(i, G[v].size()){
                edge e = G[v][i];
                if(d[e.to] > d[v] + e.cost){
                    d[e.to] = d[v] + e.cost;
                    que.push(Pii(d[e.to], e.to));
                }
            }
        }
    }

    void dijkstra_r(int s, int t){
        priority_queue<Pii, vector<Pii>, greater<Pii>> que;
        fill(d.begin(), d.end(), INF);
        d[s] = 0; root[s] = -1;
        que.push(Pii(0, s));

        while(!que.empty()){
            Pii p = que.top(); que.pop();
            int v = p.second;
            if(v == t) return;
            if(d[v] < p.first) continue;
            REP(i, G[v].size()){
                edge e = G[v][i];
                if(d[e.to] > d[v] + e.cost){
                    d[e.to] = d[v] + e.cost;
                    root[e.to] = v;
                    que.push(Pii(d[e.to], e.to));
                }
            }
        }
    }

    void bellman_ford(int s){
        fill(d.begin(), d.end(), INF);
        d[s] = 0;
        while(true){
            bool update = false;
            REP(v, V){
                REP(i, G[v].size()){
                    edge e = G[v][i];
                    if(d[v] != INF && d[e.to] > d[v] + e.cost){
                        d[e.to] = d[v] + e.cost;
                        update = true;
                    }
                }
            }
            if(!update) break;
        }
    }

    mat waeshall_floyd(){
        mat d2(V, vec(V));
        REP(i, V){
            REP(j, V){
                if(i == j){
                    d2[i][j] = 0;
                }else{
                    d2[i][j] = INF;
                }
            }
        }
        REP(v, V){
            REP(i, G[v].size()){
                edge e = G[v][i];
                d2[v][e.to] = e.cost;
            }
        }
        REP(k, V){
            REP(i, V){
                REP(j, V){
                    d2[i][j] = min(d2[i][j], d2[i][k] + d2[k][j]);
                }
            }
        }
        return d2;
    }

};

signed main(){

    int N; cin >> N;
    Graph G(N);
    int a, b, c;
    REP(i, N - 1){
        cin >> a >> b >> c;
        G.add_edge2(a - 1, b - 1, c);
    }

    int Q, K; cin >> Q >> K;
    G.dijkstra(K - 1, -1);
    int x, y;
    REP(i, Q){
        cin >> x >> y;
        cout << G.d[x - 1] + G.d[y - 1] << endl;
    }

    return 0;
}


