int par[17][100005];
int dep[100005];

void init(int N){
  repeat(i, 16){
    repeat(j, N){
      if(par[i][j]==-1){
        par[i+1][j]=-1;
      }else{
        par[i+1][j]=par[i][par[i][j]];
      }
    }
  }
}

int lca(int s, int t){
  if(dep[s]<dep[t]) swap(s, t);
  repeat(i,17)if((dep[s]-dep[t])>>i&1) s=par[i][s];
  if(s==t) return s;
  for(int i=16; i>=0; i--){
    if(par[i][s]!=par[i][t]) s=par[i][s], t=par[i][t];
  }
  return par[0][s];
}


void f(int i, int p, int k){
   par[0][i]=p;
   if(i==k) sb[i]=1;
   for(auto e: g[i])if(e.to!=p){
      assert(d[i]>=0);
      d[e.to]=d[i]+e.c;
      sb[e.to]|=sb[i];
      dep[e.to]=dep[i]+1;
      f(e.to, i, k);
   }
}


