void dfs(int v,int pr){
    tin[v]=timer++;
    up[0][v]=pr;
    for(int i=1;i<=sz;i++){
        up[i][v]=up[i-1][up[i-1][v]];
    }
    for(auto to:g[v]){
        if(to.first!=pr){
            d[to.first]=d[v]+to.second;
            dfs(to.first,v);
        }
    }
    tout[v]=timer++;
}
inline bool upper(int a,int b){
    return tin[a]<=tin[b] && tout[a]>=tout[b];
}
inline int lca(int a,int b){
    if(upper(a,b)){
        return a;
    }
    if(upper(b,a)){
        return b;
    }
    for(int i=sz;i>=0;i--){
        if(!upper(up[i][a],b)){
            a=up[i][a];
        }
    }
    return up[0][a];
}
