void Dijkstra(int s)
{
    priority_queue<p,vector<p>,greater<p> > que;
    fill(dis+1,dis+n+1,INF);
    dis[s]=0;
    que.push(p(0,s));
    while(!que.empty())
    {
        p P=que.top();
        que.pop();
        v=P.second;
        if(dis[v]<P.first)
            continue;
        for(ll i=0;i<edge[v].size();i++)
        {
            Edge e=edge[v][i];
        if(dis[e.to]>dis[v]+e.cost)
        {
            dis[e.to]=dis[v]+e.cost;
            que.push(p(dis[e.to],e.to));
        }
        }
    }
}
