struct Node{
    Node* parent;
    //vector<int> children;
    int cost;
    //Node() : parent(-1),  children(vector<int>()), cost(0) {children.reserve(10);}
    Node() : parent(nullptr), cost(0) {}
};
void func(Node *ptr, Node *toptr, int cost){
    if(ptr==nullptr)
        return;
    Node *parent = ptr->parent;
    ptr->parent = toptr;
    int c = ptr->cost;
    ptr->cost = cost;
    func(parent, ptr, c);
}
ll calcCost(Node *ptr){
    if(ptr==nullptr)
        return 0LL;
    return ptr->cost+calcCost(ptr->parent);
}
