using namespace std;

struct Node{

  int v; //边的终点编号
  int w; //边权
};
int n, m,k,x,y,q;
const int N =2e5+10;
vector<Node>Adj[N];

bool st[N];
long long dist[N];

void dijkstra()
{
    // memset(dist , 0x3f,sizeof dist);

    for(int i = 1;i<=n;i++)
    {
        dist[i] = 1e17;
    }

    dist[k] = 0;
    for(int i = 0;i < n ;i++)
    {
        long long  u = -1, w = 1000000000000000000;
        for(int j = 0;j < n;j++)
        {
            if(!st[j]&&dist[j]<w)
            {
                w = dist[j];
                u = j;
            }
        }

        if(u==-1)continue;
        st[u] = true;

        for(int j = 0;j<Adj[u].size();j++)
        {
            int v = Adj[u][j].v;
            if(!st[v]&&dist[u]+Adj[u][j].w < dist[v]){
                dist[v] = dist[u] + Adj[u][j].w;
            }
        }

    }

}


int main()
{


    cin >>n;
    m = n-1;
    while(m--)
    {
        int a,b,c;
        cin >>a>>b>>c;
        Adj[a].push_back({b,c});
        Adj[b].push_back({a,c});

    }

    cin >>q >>k;

    dijkstra();
    while(q--)
    {
        cin >>x>>y;
        cout << dist[x] + dist[y] <<endl;
    }

    return 0;
}

