ll dfs(const int v, const int from) {
    if (distK[v] != LINF) return distK[v];

    ll dist = LINF;
    for (const auto& e : graph[v]) {
        if (e.first == from) continue;
        else if (e.first == K) {
            dist = e.second;
            break;
        }
        else {
            chmin(dist, dfs(e.first, v) + e.second);
        }
    }

    if (dist != LINF) distK[v] = dist;
    return dist;
}

