	sort(v.begin(),v.end());
	//long long pos=lower_bound(v.begin(),v.end(),to)-v.begin(); //FUCK LOWER BOUND
	bool found=binary_search(v.begin(),v.end(),to);

	//cout<<"pos"<<pos<<endl;
	if(/*pos>=0 && pos<=v.size()-1 && v[pos]==to*/found){
		//cout<<"MINUS"<<endl;
		return getDis(0,from)-getDis(0,to);
	}else{
		//cout<<"ADD"<<endl;
		return getDis(0,from)+getDis(0,to);
	}
}

