void dijkstra(){

    d[K] = 0;
    priority_queue<Pi,vector<Pi>,greater<Pi>> pque;
    pque.push(mp(0,K));
    while(!pque.empty()){
        Pi p = pque.top();
        pque.pop();
        ll pos=p.second,cost=p.first;
        if( cost > d[pos] )continue;
        rep(i,G[pos].size()){
            ll  to = G[pos][i].first;
            ll newcost = cost + G[pos][i].second;
            if(newcost < d[to]){
                d[to] = newcost;
                pque.push(mp(d[to],to));
            }
        }

    }

}

