#define LL long long
using EDGE = tuple<int, int, LL>;
int g_K;

LL towards(vector<EDGE> &trees, int &goal, int prev, int now, LL cost) {
  if(now==goal) {
    return cost;
  }
  vector<LL> way;
  REP(i, trees.size()) {
    int a, b;
    a = get<0>(trees.at(i));
    b = get<1>(trees.at(i));
    if(a==now && prev!=b)
      way.push_back(towards(trees, goal, a, b, cost+get<2>(trees.at(i))));
    if(b==now && prev!=a)
      way.push_back(towards(trees, goal, b, a, cost+get<2>(trees.at(i))));
  }
  if(way.size() != 0) {
  	LL result=0;
    REP(i, way.size()) {
      if(way.at(i)!=0) {
        if(result==0)
          result = way.at(i);
        else
          result = min(result, way.at(i));
      }
    }
    return result;
  }
  return 0;
}

LL shotest(int &x, int &y, vector<EDGE> &trees) {
  return (towards(trees, g_K, -1, x, 0) + towards(trees, y, -1, g_K, 0));
}

int main() {
  int N;
  cin >> N;
  vector<EDGE> trees(N);
  REP(i, N-1) {
    int a, b; LL c;
    cin >> a >> b >> c;
    trees.at(i) = make_tuple(a, b, c);
  }

  int Q;
  cin >> Q >> g_K;
  REP(i, Q) {
    int x, y;
    cin >> x >> y;
    cout << shotest(x, y, trees) << endl;
  }
}

