struct Tree
{
  const static int MAX_V = 200010;
  using P = pair<int, ll>;
  vector<P> E[MAX_V];
  int par[MAX_V];
  int depth[MAX_V];
  ll dist[MAX_V];

  void add_E(int a, int b, ll w = 1, bool direction = false)
  {
    E[a].push_back(MP(b, w));
    if (!direction)
      E[b].push_back(MP(a, w));
  }

  void dfs(int p, int d, ll w)
  {
    for (auto pi : E[p])
    {
      int v = pi.first;
      if (par[v] != -2)
        continue;
      par[v] = p;
      depth[v] = d + 1;
      dist[v] = w + pi.second;
      dfs(v, d + 1, w + pi.second);
    }
  }

  void make_tree(int root = 0)
  {
    fill(par, par + MAX_V, -2);
    par[root] = -1;
    depth[root] = dist[root] = 0;
    dfs(root, 0, 0);
  }

  int par_double[MAX_V][25]; //頂点iの2^k個上の頂点
  bool calculated = false;
  void calc_double()
  {
    for (int i = 0; i < MAX_V; i++)
      par_double[i][0] = (par[i] < 0 ? -1 : par[i]);

    for (int k = 0; k < 24; k++)
    {
      for (int i = 0; i < MAX_V; i++)
      {
        if (par_double[i][k] == -1)
          par_double[i][k + 1] = -1;
        else
          par_double[i][k + 1] = par_double[par_double[i][k]][k];
      }
    }
  }

  int getLCA(int a, int b)
  {
    if (!calculated)
    {
      calc_double();
      calculated = true;
    }
    if (a == b)
      return a;
    if (depth[a] < depth[b])
      swap(a, b);
    for (int k = 24; k >= 0; k--)
    {
      if (par_double[a][k] != -1 && depth[par_double[a][k]] >= depth[b])
      {
        a = par_double[a][k];
      }
    }
    if (a == b)
      return a;
    for (int k = 24; k >= 0; k--)
    {
      if (par_double[a][k] != -1 && par_double[a][k] != par_double[b][k])
      {
        a = par_double[a][k];
        b = par_double[b][k];
      }
    }
    return par_double[a][0];
  }

  inline int length(int a, int b)
  {
    return depth[a] + depth[b] - 2 * depth[getLCA(a, b)];
  }

  inline ll distance(int a, int b)
  {
    return dist[a] + dist[b] - 2 * dist[getLCA(a, b)];
  }
};

