long long GCD(long long a, long long b) {

    long long temp;

    if (a < b) temp = a, a = b, b = temp;

    while (b != 0)  temp = a % b, a = b, b = temp;

    return a;

}

long long LCM(long long a, long long b) {

    long long temp = a * (b / GCD(a, b));

    return temp;
}

