vll dijkstra(ll n, vector<vector<vll>> nx, ll start) {
  vll dist(n, inf);
  dist[start] = 0;
  for (ll i = 0; i < n - 1; i++) {
    priority_queue<vll, vector<vll>, greater<vll>> pq;
    for (ll j = 0; j < n; j++) {
      if (dist[j] == inf) continue;
      for (ll k = 0; k < nx[j].size(); k++) {
        vll v = nx[j][k];
        if (dist[v[1]] == inf) {
          pq.push({dist[j] + v[0], v[1]});
        }
      }
    }
    vll w = pq.top();
    dist[w[1]] = w[0];
  }
  return dist;
}

int main() {
  ll n;
  cin >> n;
  vector<vector<vll>> nx(n, vector<vll>(0));
  for (ll i = 0; i < n - 1; i++) {
    ll a, b, c;
    cin >> a >> b >> c;
    nx[a - 1].push_back({c, b - 1});
    nx[b - 1].push_back({c, a - 1});
  }
  ll q, k;
  cin >> q >> k;
  vll dist = dijkstra(n, nx, k - 1);
  for (ll i = 0; i < q; i++) {
    ll x, y;
    cin >> x >> y;
    cout << dist[x - 1] + dist[y - 1] << endl;
  }
}

