  vector<edge> g[n];
  rep(i,n-1) {
    int s, t, c;
    cin >> s >> t >> c;
    s--, t--;
    g[s].push_back((edge){t,c});
    g[t].push_back((edge){s,c});
  }

  // 始点sから各頂点iへの最短距離を求めてd[i]に格納　O(|m|log|n|)
  vector<int> d(n,INFLL);
  auto dijkstra = [&](int s) {
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>> > que;
    rep(i,n) d[i] = INFLL;
    d[s] = 0;
    que.push(pair<int,int>(0,s));
    while (!que.empty()) {
      pair<int,int> p = que.top(); que.pop();
      int v = p.second;
      if (d[v] < p.first) continue; // vまでにかかるコスト(=c=p.first)が最小でないならcontinue
      for (int i = 0; i < g[v].size(); i++) {
        edge e = g[v][i];
        if (d[e.to] > d[v] + e.cost) {
          d[e.to] = d[v] + e.cost;
          que.push(pair<int,int>(d[e.to],e.to));
