#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int INF = 1000000000;

void dijkstra(int s, vector<vector<pair<ll, int>>>& adj, vector<ll>& dist)
{
  dist[s] = 0;
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
  que.push(make_pair(0, s));
  while (not que.empty()) {
    pair<ll, int> p = que.top(); que.pop();
    ll d = p.first;
    int u = p.second;
    if (d > dist[u]) { continue; }
    for (pair<ll, int> q : adj[u]) {
      ll cost = q.first;
      int v = q.second;
      if (dist[u] + cost < dist[v]) {
        dist[v] = dist[u] + cost;
        que.push(make_pair(dist[v], v));
      }
    }
  }
}

int main()
{
  int N; scanf("%d", &N);
  vector<vector<pair<ll, int>>> adj(N + 5, vector<pair<ll, int>>());
  int a, b, c;
  for (int i = 0; i < N - 1; ++i) {
    scanf("%d %d %d", &a, &b, &c);
    adj[a].push_back(make_pair(c, b));
    adj[b].push_back(make_pair(c, a));
  }

  int Q, K; scanf("%d %d", &Q, &K);
  ll LLINF = 1e18;
  vector<ll> dist(N + 5, LLINF);
  dijkstra(K, adj, dist);
  int x, y;
  while (Q-- > 0) {
    scanf("%d %d", &x, &y);
    printf("%lld\n", dist[x] + dist[y]);
  }
  return 0;
}

