struct dii{//for pfs
	lint dist;	//distance
	int i;		//vertex number
	bool operator<(const dii &r) const{
		return dist>r.dist;
	}
};
lint ds[MAX_N];	//distance
void pfs(int s,lint *d=ds){//start
	priority_queue<dii> q;
	fill(d,d+n,linf);d[s]=0;q.push({0,s});
	int cur;
	edge e;
	while(!q.empty()){
		dii p=q.top();q.pop();
		cur=p.i;
		if(d[cur]<p.dist)continue;
		rep(i,siz(g[cur])){
			e=g[cur][i];
			if(d[e.to]>d[cur]+e.cost){
				d[e.to]=d[cur]+e.cost;
				q.push({ d[e.to],e.to });
			}
		}
	}
}

