/****** define constant end ********/
/****** define variable start ******/
ll n;
vl a, b, c;
ll q, k;
vl x, y;
Graph G;
/******* define variable end *******/

std::vector<ll> d;

void dijkstra(ll s){
	std::priority_queue<P, std::vector<P>, std::greater<P>> que;
	for(ll i = 0; i < n; i++) d[i] = INF;
	d[s] = 0;
	que.push(P(0, s));

	while(!que.empty()){
		P p = que.top(); que.pop();
		ll v = p.second;
		if(d[v] < p.first) continue;
		for(ll i = 0; i < G[v].size(); i++){
			Edge e = G[v][i];
			if(d[e.to] > d[v] + e.cost){
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}
int solve() {
    cin >> n;
	G.resize(n);
	d.resize(n);
    a.resize(n-1);
    b.resize(n-1);
    c.resize(n-1);
    REP(i, n-1){
        cin >> a[i] >> b[i] >> c[i];
		Edge e = {b[i]-1, c[i]};
		G[a[i]-1].push_back(e);
		Edge e2 = {a[i]-1, c[i]};
		G[b[i]-1].push_back(e2);
    }
    cin >> q >> k;
	dijkstra(k-1);
    x.resize(q);
    y.resize(q);
    REP(i, q){
        cin >> x[i] >> y[i];
		cout << d[x[i]-1] + d[y[i]-1] << endl;
	}
	return 0;
}

