#include <map>
#include <numeric>

using namespace std;
using ll = long long;
const ll INF = 1e18;

typedef pair<int, int> C;
typedef pair<ll, int> P;
map<P, ll> G;
vector<int> V[100001];
ll d[100001];

ll dijkstra(int s, int g) {
    priority_queue<P, vector<P>, greater<>> que;
    for (int i = 0; i < 100001; i++) d[i] = INF;
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (v == g) break;
        if (d[v] < p.first) continue;

        for (auto to : V[v]) {
            ll cost = G[C(v, to)];

            if (d[to] > d[v] + cost) {
                d[to] = d[v] + cost;
                que.push(P(d[to], to));
            }
        }
    }

    return d[g];
}

int main() {
    int N;
    cin >> N;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        ll c;
        cin >> a >> b >> c;
        a--; b--;
        G[C(a, b)] = c;
        G[C(b, a)] = c;
        V[a].push_back(b);
        V[b].push_back(a);
    }

    int Q, K;
    cin >> Q >> K;
    K--;
    for (int i = 0; i < Q; i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        ll a = dijkstra(x, K);
        ll b = dijkstra(y, K);
        cout << a + b << endl;
    }

    return 0;
}

