void inti(){
	memset(head, -1, sizeof(head));
	for(int i = 0; i < maxn; ++i){
		dis[i] = INF;
	}
	memset(vis, false, sizeof(vis));
	cnt = 0;
}
void build(long long s, long long e, long long w){
	r[cnt].v = w;
	r[cnt].to = e;
	r[cnt].next = head[s];
	head[s] = cnt++;
}
void spfa(long long s){
	queue<int>q;
	int end, i, top;
	q.push(s);
	vis[s] = true;
	dis[s] = 0;
	while(!q.empty()){
		top = q.front();
		q.pop();
		vis[top] = false;
		for(i = head[top]; i != -1; i = r[i].next){
			end = r[i].to;
			if(dis[end] > dis[top] + r[i].v){
				dis[end] = dis[top] + r[i].v;
				if(!vis[end]){
					q.push(end);
					vis[end] = true;
				}
			}
		}
	}
}
