void dijkstra(LL s){
    priority_queue<P, vector<P>, greater<P>>    que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0, s));
    while(!que.empty()){
        P p = que.top();
        que.pop();
        LL v = p.second;
