        else par[k+1][v] = par[k][par[k][v]];
    }
}

ll lca(ll u, ll v){
    if(depth[u] > depth[v]) swap(u, v);
    ll dd = depth[v] - depth[u];
    rep(k, MX_LOG) {
        if(dd >> k & 1) v = par[k][v];
    }
    if(u == v) return u;

    for(ll k = MX_LOG-1; k >= 0; k--){
        if(par[k][u] != par[k][v]){
            u = par[k][u];
            v = par[k][v];
        }
    }
    return par[0][u];
}


