	{
		if((depth[v]-depth[u])>>k&1)
		{
			v=parent[k][v];
		}
	}
	if(u==v)return u;
	for(long long k=MAX_LOG_V-1;k>=0;k--)
	{
		if(parent[k][u]!=parent[k][v])
		{
			u=parent[k][u];
			v=parent[k][v];
		}
	}
	return parent[0][u];
}
