    rep(i,q){
        cout<<d[x[i]-1]+d[y[i]-1]<<endl;
    }
    return 0;
}
void dijkstra(int k){
    priority_queue<P, vector<P>,greater<P> >que;
    fill(d,d+n,INF);
    d[k]=0;
    que.push(P(0,k));
    while(!que.empty()){
        P p=que.top();
        que.pop();
        int v= p.second;
        if(d[v]<p.first)continue;
        for(int i=0;i<vec[v].size();i++){
            edge temp=vec[v][i];
            if(d[temp.to]>d[v]+temp.cost){
                d[temp.to]=d[v]+temp.cost;
                que.push(P(d[temp.to],temp.to));
            }
        }
    }
}

