void root(int k, std::vector< std::vector< std::pair<int, int> > > &g, long long int distances[])
{
	std::queue<int> q;
	std::queue<long long int> qcounter;
	q.push(k);
	qcounter.push(0);

	bool visited[100010] = { 0 };

	while (q.empty() == false)
	{
		int top = q.front();
		long long int counter = qcounter.front();
		q.pop();
		qcounter.pop();

		distances[top] = counter;

		if (visited[top])
			continue;
		else
			visited[top] = true;

		for (int i = 0; i < g[top].size(); ++i)
		{
			int node = g[top][i].first;
			if (!visited[node])
			{
				q.push(node);
				qcounter.push(counter + g[top][i].second);
			}
		}
	}

}

