vector<pair<int, int> > v[200010];
int level[200010];
int dist[200010];
int table[20][200010];
int parent[200010];

void dfs(int par, int node, int d, int depth)
{
    dist[node]=d;
    level[node]=depth;
    parent[node]=par;
    for(int i=0; i<v[node].size(); i++) {
        int cur=v[node][i].first;
        if(par!=cur) {
            dfs(node, cur, d+v[node][i].second, depth+1);
        }
    }
}

void make_table(int n)
{
    for(int i=0; i<20; i++) {
        for(int j=1; j<=n; j++) {
            table[i][j]=-1;
        }
    }
    for(int i=1; i<=n; i++) {
        table[0][i]=parent[i];
    }
    for(int i=1; i<20; i++) {
        for(int j=1; j<=n; j++) {
            int mid=table[i-1][j];
            if(mid!=-1) {
                table[i][j]=table[i-1][mid];
            }
        }
    }
}

pair<int, int> walk(int a, int b)
{
    if(level[a]>level[b]) swap(a, b);
    int k=level[b]-level[a];
    for(int i=19; i>=0; i--) {
        if(k&(1<<i)) {
            b=table[i][b];
        }
    }
    return {a, b};
}

int __lca(int a, int b)
{
    pair<int, int> fnl=walk(a, b);
    a=fnl.first, b=fnl.second;
    if(a==b) return a;
    for(int i=19; i>=0; i--) {
        if(table[i][a]!=table[i][b]) {
            a=table[i][a], b=table[i][b];
        }
    }
    return parent[a];
}

int get_distance(int a, int b)
{
    return dist[a]+dist[b]-2*dist[__lca(a, b)];
}


