	REP(i, N - 1) {
		int a, b; cin >> a >> b; a--; b--;
		ll c; cin >> c;
		G[a].push_back(Edge(b, c));
		G[b].push_back(Edge(a, c));
	}
	int Q; cin >> Q;
	int K; cin >> K; K--;
	vector<int> x(Q), y(Q); REP(i, Q) cin >> x[i] >> y[i];
	REP(i, Q) {
		x[i]--;
		y[i]--;
	}

	// 最短距離を初期化
	vector<ll> d(N, (ll)1e18);
	d[K] = 0;
