template <class Abel>
struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<ll> diff_weight;

    UnionFind(int n = 1, Abel SUM_UNITY = 0) { init(n, SUM_UNITY); }

    void init(int n = 1, Abel SUM_UNITY = 0) {
        par.resize(n);
        rank.resize(n);
        diff_weight.resize(n);
        for (int i = 0; i < n; ++i)
            par[i] = i, rank[i] = 0, diff_weight[i] = SUM_UNITY;
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        } else {
            int r = root(par[x]);
            diff_weight[x] += diff_weight[par[x]];
            return par[x] = r;
        }
    }

    ll weight(int x) {
        root(x);
        return diff_weight[x];
    }

    bool issame(int x, int y) { return root(x) == root(y); }

    bool merge(int x, int y, ll w) {
        w += weight(x);
        w -= weight(y);
        x = root(x);
        y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y), w = -w;
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        diff_weight[y] = w;
        return true;
    }

    ll diff(int x, int y) { return weight(y) - weight(x); }
};

int main() {
    int N;
    cin >> N;
    vector<int> A(N - 1), B(N - 1);
    vector<ll> C(N - 1);
    rep(i, N - 1) {
        cin >> A[i] >> B[i] >> C[i];
        --A[i], --B[i];
    }
    int Q, K;
    cin >> Q >> K;
    --K;
    vector<int> X(Q), Y(Q);
    rep(i, Q) {
        cin >> X[i] >> Y[i];
        --X[i], --Y[i];
    }

    UnionFind<int> uf(N);
    rep(i, N - 1) uf.merge(A[i], B[i], C[i]);
    vector<vector<ll>> ans(Q, vector<ll>(3));
    rep(i, Q) {
        ans[i][0] = uf.diff(uf.root(X[i]), X[i]) + uf.diff(uf.root(Y[i]), Y[i]);
        ans[i][1] = ans[i][0] - 2 * uf.diff(uf.root(K), K);
        ans[i][2] = ans[i][0] + 2 * uf.diff(uf.root(K), K);
    }

    int root = uf.root(0);
    uf.init(N);
    rep(i, N - 1) {
        if (A[i] == root || B[i] == root) continue;
        uf.merge(A[i], B[i], C[i]);
    }
    rep(i, Q) {
        if (root == K ||
            (uf.issame(X[i], K) == false && uf.issame(Y[i], K) == true) ||
            (uf.issame(X[i], K) == true && uf.issame(Y[i], K) == false)) {
            cout << ans[i][0] << endl;
        } else if (uf.issame(X[i], K) == true && uf.issame(Y[i], K) == true) {
            cout << ans[i][1] << endl;
        } else {
            cout << ans[i][2] << endl;
        }
    }
}

#include <iostream>
#include <vector>

using nodes = std::vector<std::pair<int, int>>;

void make_tree(std::vector<nodes> const& rootless,
               int root,
               std::vector<int>& roots,
               std::vector<int>& dists) {
  for (auto const& p : rootless[root]) {
    auto c = p.first;
    if (dists[c] == 0) {
      roots[c] = root;
      dists[c] = p.second;
      make_tree(rootless, c, roots, dists);
    }
  }
}

int main() {
  int N;
  std::cin >> N;
  std::vector<nodes> rootless(N, nodes());

  for (int i=0; i<N-1; i++) {
    int a, b, c;
    std::cin >> a >> b >> c;
    a--; b--;
    rootless[a].emplace_back(b, c);
    rootless[b].emplace_back(a, c);
  }

  int Q, K;
  std::cin >> Q >> K;
  K--;

  std::vector<int> roots(N);
  std::vector<int> dists(N, 0);
  make_tree(rootless, K, roots, dists);

  for (int i=0; i<Q; i++) {
    int x, y;
    std::cin >> x >> y;
    x--; y--;

    long long int ans=0;
    while (x != K) {
      ans += dists[x];
      x = roots[x];
    }
    while (y != K) {
      ans += dists[y];
      y = roots[y];
    }

    std::cout << ans << '\n';
  }

  return 0;
}

