using namespace std;
long long inf=1e18*9;
int n,m;
int tot=0,pre[100012],now[100012],son[100012],h[100012],f[100012];
long long v[100012],d[100012];
void add(int a,int b,long long c){
	tot++;
	pre[tot]=now[a];
	now[a]=tot;
	son[tot]=b;
	v[tot]=c;
}

void doing(int st){
	int head=0,tail=1;
	for (int i=1;i<=n;i++)
	  d[i]=inf;
	memset(f,0,sizeof(f));
	h[1]=st;
	d[st]=0;
	f[st]=1;
	while (head<tail)
	{
	  head++;
	  int fa=h[head];
	  int p=now[fa];
	  while (p>0)
	  {
	  	int s=son[p];
	  	if (d[s]>d[fa]+v[p])
	  	{
		  d[s]=d[fa]+v[p];
		  if (!f[s])
		  {
		  	tail++;
		  	f[s]=1;
			h[tail]=s;
		  }
		}
		p=pre[p];
	  }
	  f[fa]=0;
	}
}



