	G[0].push_back(make_pair(1, 1));
	G[1].push_back(make_pair(2, 1));
	...

	vector<ll> result = dijkstra(G, 0);
	*/
	priority_queue< pair<ll, ll> > searchPQ;	// PQの要素はこれから探索するノード(firstがコスト, secondがノード番号)
	const ll node_number = G.size();
	vector<bool> isChecked(node_number, false);	// trueのときは探索済

	output_dist.resize(node_number);

	Rep(i, node_number) {
		output_dist[i] = INF64;
		isChecked[i] = false;
	}

	// 起点からスタート
	output_dist[startNode] = 0;
	searchPQ.push(make_pair(0, startNode));

	while (!searchPQ.empty())
	{
		pair<ll, ll> search_node = searchPQ.top(); searchPQ.pop();
		ll u = search_node.second;// 調べるノード
		isChecked[u] = true;

		if (output_dist[u] < search_node.first * (-1)) continue;// search_node.firstは負の値にしている

		for (ll j = 0; j < G[u].size(); j++) {
			// uにつながっているノードを探索
			ll v = G[u][j].first;
			if (isChecked[v] == true) continue;
			if (output_dist[v] > output_dist[u] + G[u][j].second) {
				output_dist[v] = output_dist[u] + G[u][j].second;
				searchPQ.push(make_pair(output_dist[v] * (-1), v));//priority_queueはデフォルトで大きい値をpopしてしまうのでマイナスをかける
			}
		}
	}
}

