void rmq_init(int n)
{
	for(int i=0;i<n;i++)
	{
		bit[i][0] = i;
	}
	for(int j=1;(1<<j)<n;j++)
	{
		for(int i=0;i+(1<<j)-1<n;i++)
		{
			if(depth[bit[i][j-1]] <= depth[bit[i+(1<<(j-1))][j-1]])
			{
				bit[i][j] = bit[i][j-1];
			}
			else
			{
				bit[i][j] = bit[i+(1<<(j-1))][j-1];
			}
		}
	}
}
int query(int l,int r)
{
	int k = 0;
	while((1<<(k+1))<r-l+1)
		k++;
	if(depth[bit[l][k]] <= depth[bit[r-(1<<k)][k]])
	{
		return bit[l][k];
	}
	else
	{
		return bit[r-(1<<k)][k];
	}
}
