M dijkstra(int n, int point, map<int, A> d){
    M cost;
    for(int i=1  ;i<n+1  ;i++) {
        cost[i]=1e18;
    }
    priority_queue<L,A,greater<L>> q;

    long long nownode,nextnode,nowcost,passcost,newcost;

    cost[point]=0;
    q.push( {cost[point],point} );

    while (!q.empty()){
        nowcost=q.top()[0];
        nownode=q.top()[1];
        q.pop();
        if (cost[nownode]<nowcost){  //今costに登録されてる値が現在のその座標のコストより小さいとき
            continue;
        }
        for(auto item_of_d:d[nownode]){
            passcost=item_of_d[1];
            nextnode=item_of_d[0];
            newcost=nowcost+passcost;
            if (cost[nextnode]>newcost){
                cost[nextnode]=newcost;
                q.push({newcost,nextnode});
            }
        }
    }
    return cost;
}


