struct Edge{
	int to,next;
	LL weight;
	Edge(int _to = 0, int _next = 0,LL _w=0) :to(_to), next(_next),weight(_w){};
}Edges[MAXN * 2];
void add(int u, int v,LL w){
	Edges[tot].to = v;
	Edges[tot].next = head[u];
	Edges[tot].weight=w;
	head[u] = tot++;
}
int id[MAXN], son[MAXN], deep[MAXN], size[MAXN], fa[MAXN], reid[MAXN], top[MAXN];
void Init(){
	tot = 0; cnt = 0;
	memset(val,0,sizeof(val));
	memset(head, -1, sizeof(head));
	memset(son, -1, sizeof(son));
}
void DFS1(int u, int p,int dep,LL _v){
	fa[u] = p; size[u] = 1; deep[u] = dep; val[u]=_v;
	for (int i = head[u]; i != -1; i = Edges[i].next){
		if (Edges[i].to != p){
			DFS1(Edges[i].to, u,dep+1,Edges[i].weight);
			size[u] += size[Edges[i].to];
			if (son[u] == -1 || size[Edges[i].to] > size[son[u]]){
				son[u] = Edges[i].to;
			}
		}
	}
}
void DFS2(int u, int tp){
	id[u] = ++cnt; reid[id[u]] = u; top[u] = tp;
	if (son[u] == -1){ return; }
	DFS2(son[u], tp);
	for (int i = head[u]; i != -1; i = Edges[i].next){
		if (son[u] != Edges[i].to&&Edges[i].to != fa[u]){
			DFS2(Edges[i].to, Edges[i].to);
		}
	}
}
struct Node{
	int st, ed;
	LL sum;
}Seg[MAXN * 4];
void Build(int l, int r, int k){
	Seg[k].st = l; Seg[k].ed = r; 
	if (l == r){
		Seg[k].sum = val[reid[l]]; 
		return;
	}
	int mid = (l + r) / 2;
	Build(l, mid, L(k)); Build(mid + 1, r, R(k));
	Seg[k].sum = Seg[L(k)].sum + Seg[R(k)].sum;
}
void pushUp(int k){
	Seg[k].sum = Seg[L(k)].sum + Seg[R(k)].sum;
}
LL QuerySum(int l, int r, int k){
	if (Seg[k].st == l&&Seg[k].ed == r){
		return Seg[k].sum;
	}
	LL sum = 0;
	if (r <= Seg[L(k)].ed){
		sum = QuerySum(l, r, L(k));
	}
	else if (l >= Seg[R(k)].st){
		sum = QuerySum(l, r, R(k));
	}
	else{
		sum = QuerySum(l, Seg[L(k)].ed, L(k)) + QuerySum(Seg[R(k)].st, r, R(k));
	}
	pushUp(k);
	return sum;
}
LL QuerySum(int u,int v){
	LL ans = 0;
	int f1 = top[u], f2 = top[v];
	while (f1!=f2){
		if (deep[f1] < deep[f2]){
			swap(f1, f2);
			swap(u, v);
		}
		ans += QuerySum(id[f1], id[u],1);
		u = fa[f1]; f1 = top[u];
	}
	if (deep[u] > deep[v]){
		swap(u, v);
	}
	ans += QuerySum(id[u],id[v], 1);
	return ans;
}
