void shortest_path(int s) {
    for (int i=0; i<=N; ++i) d[i] = INF;
    d[s] = 0;
    while (true) {
        bool update = false;
        for (long i=0; i<E; ++i) {
            edge e = es[i];
            if (d[e.from] != INF && d[e.to] > d[e.from] + e.cost) {
                d[e.to] = d[e.from] + e.cost;
                update = true;
            }
        }
        if (!update) break;
    }
}

