vector<edge> ev[100010];
ll k;
ll kc[100010];
ll recur(ll start,ll from, ll next,ll cost) {

	if (kc[from] > 0) {
		if (start == from) return kc[from];
		return kc[start] = kc[from] + cost;
	}
	if (next == k) {
		kc[start] = cost;
		return cost;
	}

	for (size_t i = 0; i < ev[next].size(); i++)
	{
		if (ev[next][i].to == from) continue;
		if (kc[next] > 0) {
			kc[start] = kc[next] + cost;
		}else
			recur(start,next,ev[next][i].to, cost + ev[next][i].cost);
	}
}
void TransitTreePath() {
	int n;
	cin >> n;
	for (size_t i = 0; i < n - 1; i++)
	{
		ll a, b, c;
		cin >> a >> b >> c;
		edge e;
		e.to = b;
		e.cost = c;
		ev[a].push_back(e);
		edge e2;
		e2.to = a;
		e2.cost = c;

		ev[b].push_back(e2);
	}

	ll q;
	cin >> q >> k;
	for (int i = 1; i <= n; i++)
	{
		if (i == k) continue;
		recur(i,i, i, 0);
	}

	for (size_t i = 0; i < q; i++)
	{
		ll x, y;
		cin >> x >> y;
		cout << (kc[x] + kc[y]) << endl;
	}
}
int main() {
	TransitTreePath();
	return 0;
}

