void BFS(vector<pair<llong,llong>> tree[],llong saitan[],int tmp,bool visited[]){
    for(auto itr = tree[tmp].begin(); itr != tree[tmp].end();itr++){
        if(not visited[(*itr).first]){
            saitan[(*itr).first] = saitan[tmp] + (*itr).second;
            visited[(*itr).first]=true;
            BFS(tree, saitan,(*itr).first, visited);
        }
    }
