#include <bits/stdc++.h>

using namespace std;

int main()
{
  uint64_t N;
  cin >> N;

  map<uint64_t, set<pair<uint64_t, uint64_t>>> edges;
  for (uint64_t n = 0; n < N - 1; ++n) {
    uint64_t a, b, c;
    cin >> a >> b >> c;

    edges[a - 1].emplace(b - 1, c);
    edges[b - 1].emplace(a - 1, c);
  }

  uint64_t Q, K;
  cin >> Q >> K;

  vector<uint64_t> depth(N, -1);
  depth[K - 1] = 0;
  queue<uint64_t> queue;
  queue.push(K - 1);
  while (!queue.empty()) {
    uint64_t src = queue.front(); queue.pop();

    for (auto pair : edges[src]) {
      if (depth[pair.first] != -1) {
        continue;
      }

      depth[pair.first] = depth[src] + pair.second;
      queue.push(pair.first);
    }
  }

  for (uint64_t q = 0; q < Q; ++q) {
    uint64_t x, y;
    cin >> x >> y;

    cout << (depth[x - 1] + depth[y - 1]) << endl;
  }

  return 0;
}

