inline int LCA(int a, int b){
    int d1 = depth[a], d2 = depth[b], pom = abs(d1 - d2);
    if(d1 > d2) swap(a, b);
    for(int i = 0; (1<<i) <= pom; ++i)
        if((pom & (1<<i)) > 0)
            b = ojciec[b][i];
    if(a == b) return a;
    for(int i = 19; i >= 0; --i)
        if(ojciec[a][i] != ojciec[b][i])
            a = ojciec[a][i], b = ojciec[b][i];
    return ojciec[a][0];
}

inline int odl(int a, int b){
    int l = LCA(a, b);
    return (depth[a] + depth[b] - 2*depth[l]);
}

