class Node {
public:
    int number;
    ll dist;
    Node(ll d, int n) {
        dist = d;
        number = n;
    }
};
bool operator < (const Node &l, const Node &r) {
    return l.dist < r.dist
    || (!(r.dist < l.dist) && l.number < r.number);
};
bool operator > (const Node &l, const Node &r) {
    return r < l;
};

class Dijkstra {
private:
    class Edge {
    public:
        int to, cost;
        Edge(int t, int c) {
            to = t;
            cost = c;
        }
    };

    vector<vector<Edge>> edges;
    int node_n;

    void edge_initializer(int n) {
        edges = vector<vector<Edge>>(n);
    }

public:
    vector<ll> d;
    int start = 0;

    Dijkstra(int n, int s) {
        start = s;
        node_n = n;
        edge_initializer(n);
    }

    void add_edge(int from, int to, int cost, bool rev=true) {
        edges[from].pb(Edge(to,cost));
        if(rev) edges[to].pb(Edge(from,cost));
    }

    vector<ll> solve() {
        d = vector<ll>(node_n, LLONG_MAX); d[start] = 0;

        priority_queue<Node,vector<Node>,greater<Node>> Q;

        for(int i=0; i<node_n; i++) {
            Q.push(Node(d[i],i));
        }

        while(!Q.empty()) {
            Node u = Q.top(); Q.pop();
            if(u.dist > d[u.number]) continue;
            for(Edge &edge:edges[u.number]) {
                ll alt = d[u.number] + edge.cost;
                int v = edge.to;
                if(d[v] > alt) {
                    d[v] = alt;
                    Q.push(Node(d[v],v));
                }
            }
        }
        return d;
    }
};

