void dijkstra()
{
    memset(dist , 0x3f,sizeof dist);
    dist[k] = 0;

    for(int i = 0;i < n ;i++)
    {
        long long  u = -1, w = 1000000000000000000;
        for(int j = 0;j < n;j++)
        {
            if(!st[j]&&dist[j]<w)
            {
                w = dist[j];
                u = j;
            }
