        if(u==-1)continue;
        st[u] = true;

        for(int j = 0;j<Adj[u].size();j++)
        {
            int v = Adj[u][j].v;
            if(!st[v]&&dist[u]+Adj[u][j].w < dist[v]){
                dist[v] = dist[u] + Adj[u][j].w;
            }
        }

    }

}

