#define WHITE 0
#define GRAY 1
#define BLACK 2

// ダイクストラ法を適用し、dを更新する関数
void dijkstra(ll n, ll dist[], vector<vector<pair<ll, ll>>> g, ll k)
{
    ll i, vertex, min_d, color[n];
    // 初期状態
    for (i = 0; i < n; i++)
    {
        dist[i] = infll;
        color[i] = WHITE;
    }
    dist[k - 1] = 0;
    color[k - 1] = GRAY;

    while (1)
    {
        // S - V でコスト最小の頂点を選ぶ
        vertex = -1;
        min_d = infll;
        for (ll i = 0; i < n; i++)
        {
            if (color[i] == GRAY)
            {
                vertex = i;
                break;
            }
        }
        // S = V の場合は終了
        if (vertex == -1)
            break;

        // vertexをSに追加
        color[vertex] = BLACK;

        // S-Vに属し、vertexに隣接する頂点のコストを更新
        for (auto f : g[vertex])
        {
            if (color[f.first] != BLACK && f.second < infll)
            {
                color[f.first] = GRAY;
                if (dist[f.first] > dist[vertex] + f.second)
                {
                    dist[f.first] = dist[vertex] + f.second;
                }
            }
        }
    }
}

