void dfs(int x , int father)
{
	dep[x] = dep[father] + 1;
	p[x][0] = father;
	if(x == K) vis[x] = true;
	for(int i = 1 ; i <= 20 ; i++)
		p[x][i] = p[p[x][i - 1]][i - 1];
	int ed = last[x];
	while(ed != -1){
		int dr = other[ed];
		if(dr != father) {
			if(vis[x] == 1) vis[dr] = true;
			dis[dr] = dis[x] + cost[ed];
			dfs(dr , x);
		}
		ed = pre[ed];
	}
}

void swap(int &x , int &y)
{
	int temp;temp = x ; x = y ; y = temp;
}

int Get_LCA(int x , int y)
{
	if(dep[x] < dep[y]) swap(x , y);
	int del = dep[x] - dep[y];
	for(int i = 0 ; i <= POW ; i++)
		if(del & (1 << i)) x = p[x][i];
	if(x != y){
		for(int i = POW ; i >= 0 ; i--){
			if(p[x][i] != p[y][i]){
				x = p[x][i];
				y = p[y][i];
			}
		}
		x = p[x][0];
		y = p[y][0];
	}
	return x;
}

