    --a; --b;
    G[a].push_back({b, c});
    G[b].push_back({a, c});
  }
  ll Q, K; cin >> Q >> K;
  --K;
  Dijkstra<ll> dijkstra(G, K, 1e18);
  while (Q--) {
    ll x, y; cin >> x >> y;
    --x; --y;
    cout << dijkstra.d[x] + dijkstra.d[y] << endl;
  }
  return 0;
}

