int get_lca(int x,int y)
{
	if(depth [x] < depth [y]) swap(x,y);
	for(int i = 19;i >= 0;i--) if(par [i] [x] != -1 && depth [par [i] [x]] >= depth [y]){
		x = par [i] [x];
	}
	if(x == y) return x;
	for(int i = 19;i >= 0;i--) if(par [i] [x] != -1 && par [i] [y] != -1 && par [i] [x] != par [i] [y]){
		x = par [i] [x];
		y = par [i] [y];
	}
	return par [0] [x];
}

ll get_dist(int x,int y)
{
	return minDist [x] + minDist [y] - minDist [get_lca(x,y)] * 2;
}

