void dijkstra(int n, int k){
  priority_queue<p, vector<p>, greater<p> > que;
  bool color[100005];
  for(int i = 0; i < n; i++){
    dist[i] = INF;
    color[i] = false;
  }
  dist[k] = 0;
  que.push(p(0, k));
  while(!que.empty()){
    p f = que.top(); que.pop();
