#define LL long long
const int maxn=100100;
int n,fa[maxn][30],deep[maxn],vis[maxn];
LL dis[maxn];
vector<pair<int,LL> >v[maxn];
void dfs(int u,int pre,LL dist){
	fa[u][0]=pre;deep[u]=deep[pre]+1;vis[u]=1;dis[u]=dist;
	for(int i=0;i<v[u].size();i++){
		int e=v[u][i].first;
		LL va=v[u][i].second;
		if(e==pre||vis[e])continue;
		dfs(e,u,dist+va);
	}
}
void init_bz(){
	for(int j=1;(1<<j)<=n;j++)
		for(int i=1;i<=n;i++)
			fa[i][j]=fa[fa[i][j-1]][j-1];
}
int LCA(int u,int v){
	if(deep[u]<deep[v])swap(u,v);
	int cal=deep[u]-deep[v];
	for(int i=0;(1<<i)<=cal;++i)if((1<<i)&cal)u=fa[u][i];
	if(u==v)return v;
	for(int i=(int)log2(n);i>=0;--i)
		if(fa[u][i]!=fa[v][i]){
			u=fa[u][i];
			v=fa[v][i];
		}
	return fa[u][0];
}
LL getdis(int a,int b){
    int ablca=LCA(a,b);
    return dis[a]-dis[ablca]+dis[b]-dis[ablca];
}
int check(int a,int b,int c){//a-c-b
    return getdis(a,c)+getdis(c,b)==getdis(a,b);
}
int main(){
	scanf("%d",&n);
	for(int i=2;i<=n;i++){
		int a,b;
		LL c;
		scanf("%d%d%lld",&a,&b,&c);
		v[a].push_back({b,c});
		v[b].push_back({a,c});
	}
	dfs(1,0,0);
	init_bz();
	int q,k;
	scanf("%d%d",&q,&k);
	while(q--){
		int a,b;
        scanf("%d%d",&a,&b);
        int lcaab=LCA(a,b);
        //int lcaak=LCA(lcaab,k);
        //cout<<lcaab<<" "<<lcaak<<endl;
        LL dis1=getdis(k,a);
        LL dis2=getdis(k,b);
        LL dis3=getdis(k,lcaab);
        int lcaak=LCA(a,k);
        int lcabk=LCA(b,k);
        if(check(a,lcaab,k)||check(b,lcaab,k))printf("%lld\n",getdis(a,b));
        else if(check(a,lcaab,lcaak))printf("%lld\n",getdis(a,b)+2*getdis(a,lcaak));
        else if(check(b,lcaab,lcabk))printf("%lld\n",getdis(a,b)+2*getdis(b,lcabk));
        else printf("%lld\n",getdis(a,b)+2*min(dis1,min(dis2,dis3)));
		//printf("%d\n",ans);
	}
}

