long solve(int x, int y, ad *ads, int n){
  priority_queue<Node, vector<Node>, Comparator> pque;
  bool visited[n + 1];
  rep(i, n + 1){
    visited[i] = false;
  }
  visited[x] = true;

  long ends[n + 1];
  rep(i, n + 1) ends[i] = 0;

  while(true){
    for(pii edge: ads[x]){
      pque.push(Node(x, edge.first, edge.second));
    }

    Node target(0, 0, 0);
    while(not pque.empty()){
      target = pque.top();
      pque.pop();
      if(not visited[target.from]){
        goto WHILE_ELSE;
      }
    }

    return -1;
WHILE_ELSE:
    ends[target.from] += ends[target.to] + target.cost;
    x = target.from;
    if(x == y) {
      return ends[y];
    }
    visited[x] = true;
  }
}

int main(){
  int n;
  cin >> n;

  ad ads[n + 1];

  int f, t, c;
  for(int i = 0; i < n - 1; i++){
    cin >> f >> t >> c;
    ads[f].push_back(make_pair(t, c));
    ads[t].push_back(make_pair(f, c));
  }

  int q, k;
  cin >> q >> k;

  long kresult[n + 1];
  FOR(i, 1, n + 2){
    kresult[i] = solve(k, i, ads, n);
  }
  rep(i, q){
    int x, y;
    cin >> x >> y;

    cout << kresult[x] + kresult[y] << endl;
  }
}

