    for (decltype(Q) i = 0; i < Q; ++i) {
        int64_t x, y;
        std::cin >> x >> y;
        x--; y--;

        std::cout << dist_to_k[x] + dist_to_k[y] << std::endl;
    }

    return 0;
}

