//	freopen("out.txt", "w", stdout);
//#endif
	int start = clock();
	int n, m,st;
	while (~scanf("%d",&n)){
		Init();
		for (int i = 1; i < n; i++){
			int u, v;
			LL w;
			scanf("%d%d%I64d", &u, &v,&w);
			add(u, v,w); add(v, u,w);
		}
		DFS1(1, 1, 0, 0); DFS2(1, 1); Build(1, n, 1);
		scanf("%d%d", &m,&st);
		while (m--){
			int u,v;
			scanf("%d%d",&u,&v);
			printf("%I64d\n", QuerySum(u,st)+QuerySum(st,v)); 
		}
	}
//#ifdef LOCAL_TIME
//	cout << "[Finished in " << clock() - start << " ms]" << endl;
//#endif
	return 0;
}

