struct edge {
	ll len;
	ll to;
};
struct graph {	// 0-indexed
	vector<vector<edge>> edges;
	bool directed, weight;
	long long ver;
	graph(long long vertex, bool direction, bool weigh) : edges(vertex) {
		ver = vertex;
		directed = direction;
		weight = weigh;
		edges.resize(vertex);
	}
	void input(long long edge_num) {
		rep(i, edge_num) {
			ll a, b;
			cin >> a >> b;
			a--;
			b--;
			ll c;
			if(weight)
				cin >> c;
			else
				c = 1;
			edge newed;
			newed.len = c;
			newed.to = b;
			edges[a].push_back(newed);
			if(!directed) {
				newed.to = a;
				edges[b].push_back(newed);
			}
		}
	}
	vector<long long> dijkstra(long long start) {
		vector<long long> ret(ver, POW(10, 16));
		pqup<pair<long long, long long>> p;	 //{dist,place}
		p.push({0, start});
		ret[start] = 0;

		while(!p.empty()) {
			ll dist = p.top().first;
			ll place = p.top().second;
			p.pop();
			if(ret[place] < dist) continue;
			for(auto &next : edges[place]) {
				ll nextplace = next.to;
				ll dis = next.len;
				if(chmin(ret[nextplace], dist + dis)) {
					p.push({ret[nextplace], nextplace});
				}
			}
		}
		return ret;
	}
};

