int N, Q, K;

void bfs(int K) {
	queue<int> que;
	REP(i, N) {
		depth[i] = INF;
	}
	que.push(K);
	depth[K] = 0;
	while (que.size()) {
		int p = que.front(); que.pop();
		for (auto &e : tree[p]) {
			if (depth[e.to] == INF) {
				que.push(e.to); depth[e.to] = depth[p] + e.cost;
			}
		}
	}
}

