#include<cstdio>
#include<vector>
using namespace std;

typedef long long lint;

const int N=100010;
vector<pair<int,int> > adj[N];
int visit[N],depth[N],dist[N],parent[N];
lint ans;

void dfs(int n){
    int size=adj[n].size();
    for(int i=0;i<size;i++){
        int x=adj[n][i].first;
        int d=adj[n][i].second;
        if(!visit[x]){
            visit[x]=1;
            depth[x]=depth[n]+1;
            parent[x]=n;
            dist[x]=d;
            dfs(x);
        }
    }
}

int lca(int a,int b){
    while(a!=b){
        if(depth[a]<depth[b])
            ans+=(2*dist[b]),b=parent[b];
        else if(depth[a]>depth[b])
            ans+=dist[a],a=parent[a];
        else{
            ans+=dist[a],a=parent[a];
            ans+=(2*dist[b]),b=parent[b];
        }
    }
    return a;
}

void Lca(int a,int b){
    while(a!=b){
        if(depth[a]<depth[b])
            ans+=(dist[b]),b=parent[b];
        else if(depth[a]>depth[b])
            ans+=dist[a],a=parent[a];
        else{
            ans+=dist[a],a=parent[a];
            ans+=(dist[b]),b=parent[b];
        }
    }
}

int main(void){
    int n,q,k;
    scanf("%d",&n);
    for(int i=1;i<n;i++){
        int a,b,c;
        scanf("%d %d %d",&a,&b,&c);
        adj[a].push_back(make_pair(b,c));
        adj[b].push_back(make_pair(a,c));
    }
    visit[1]=1;
    parent[1]=-1;
    depth[1]=1;
    dfs(1);
    scanf("%d %d",&q,&k);
    for(int i=1;i<=q;i++){
        int x,y;
        scanf("%d %d",&x,&y);
        ans=0;
        int l=lca(x,k);
        Lca(l,y);
        printf("%lld\n",ans);
    }
    return 0;
}

