const int N = 1e5+7;
const int LOGN = log(N) + 2;
const int MOD = 1e9+7;
typedef long long ll;
typedef unsigned long long ull;
typedef vector<int> vi;

int lcm(int a, int b) {return a/__gcd(a, b)*b;}

vector <pair<ll, ll> > v[N]; 
vector <ll> ans;
priority_queue <pair<ll, ll> > q;

void solve(ll x, ll target, ll cost) {
	bitset<N> vis;
	q.push({x, -cost});
	while(q.size()) {
		ll x = q.top().fi, cost = -q.top().sc; q.pop();

		if (vis[x] == 1) continue ;
		vis[x] = 1;

		if (x == target) {
			ans.pb(-cost); break ;
		}

		for(auto i : v[x]) {
			q.emplace(i.fi, -cost+i.sc);
		}
	}
	while(q.size()) q.pop();
}

int main()
{
