	FOR(i, 0, n-1) {
		ll x, y; ll c; cin >> x >> y >> c;
		v[x].eb(y, c);
		v[y].eb(x, c);
	}
	ll q, k; cin >> q >> k;
	FOR(i, 0, q) {
		// debug;
		ans.clear();
		ll x, y; cin >> x >> y;
		solve(x, k, 0);
		solve(k, y, 0);
		cout << ans[0]+ans[1] << ndl;
