        G[b].push_back({a,c});
    }
    int Q,K; cin >> Q >> K;
    K--;
    vector<ll> dist(N,1e15);
    dijkstra(G,K,dist);

    REP(i,Q){
        int x,y; cin >> x >> y;
        x--;
        y--;
        cout << dist[x]+dist[y] << endl;
    }

    return 0;
}

