void shortestPath(ll s)
{
	set<pair<ll, ll> > st;

	st.insert(mp(0,s));
	dist[s] = 0;
	while(!st.empty())
	{
		pair<ll, ll> p = *(st.begin());
		st.erase(st.begin());
		ll u = p.second;
		for(auto i = vec[u].begin(); i != vec[u].end(); ++i)
		{
			ll v = (*i).first;
			ll weight = (*i).second;
			if(dist[v] > dist[u] + weight)
			{
				if(dist[v] != LLONG_MAX)
				{
					st.erase(st.find(mp(dist[v], v)));
				}
				dist[v] = dist[u] + weight;
				st.insert(mp(dist[v],v));
			}
		}
	}
}
