typedef long long int ll;
typedef pair<int, int> P;
#define rep(i, n) for(int i = 0; i < n; i++)
#define INF 1000000007

#define MAX_N 100000
int cost[MAX_N], vis[MAX_N];
vector<P> G[MAX_N];

void dij(int st) {

	for (int i = 0; i < MAX_N; i++) vis[i] = -1;
	for (int i = 0; i < MAX_N; i++) cost[i] = INF;

	priority_queue<P, vector<P>, greater<P> > Q;

	cost[st] = 0;
	Q.push(P(0, st));

	while (!Q.empty()) {
		pair<int, int> front = Q.top(); Q.pop();
		int now = front.second;
		vis[now] = 1;

		if (cost[now] < front.first) continue;

		for (int i = 0; i < G[now].size(); i++) {
			int next = G[now][i].first;
			if (vis[next] == -1) {
				if (cost[next] > cost[now] + G[now][i].second) {
					cost[next] = cost[now] + G[now][i].second;
					Q.push(make_pair(cost[next], next));
				}
			}
		}
	}
}


int main() {
	int N;
	int a,b,c;
	cin >> N;
	rep(i, N-1) {
		cin >> a >> b >> c;
		G[a].push_back(P(b, c));
		G[b].push_back(P(a, c));
	}
	int Q, K;
	cin >> Q >> K;
	rep(i, Q) {
		int st, dt;
		cin >> st >> dt;
		dij(st);
		//rep(j, N) cout << cost[j] << " ";
		//cout << cost[K];
		int cost1 = cost[K];
		dij(K);
		int cost2 = cost[dt];
		cout << (cost1 + cost2) << endl;
	}

	return 0;
}

