using namespace std;

struct edge
{
    // 頂点 最短時間
    int a;
    int64_t cost;

    edge() {};
    edge(int a, int64_t cost)
        : a(a), cost(cost) {}

    bool operator> (const edge &edge) const
    {
        return cost > edge.cost;
    }
};

// 始点 頂点0
int start = 0;

// 道情報 行き 配列
vector< vector<edge> > goList;

// 所要時間 行き 配列
vector<int64_t> goAry;

// 行ったことある、ない
vector<bool> gone;

void bfs()
{
    queue<edge> que;

    // スタート地点をキューに入れる
    que.push(edge(start, 0));

    // 距離を0にする
    goAry[start] = 0;

    // 行ったことがある
    gone[start] = true;

    while (que.size())
    {
        edge q = que.front();
        que.pop();

        for (int i = 0; i < (signed)goList[q.a].size(); i++)
        {
            edge e = goList[q.a][i];

            // 行ったことがない
            if (gone[e.a] == false)
            {
                goAry[e.a] = goAry[q.a] + e.cost;
                // push 頂点 時間
                que.push(edge(e.a, goAry[e.a]));
                // 行ったことがある
                gone[e.a] = true;
            }
        }
    }
}

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    goList.resize(N);

    for (int i = 0; i < N - 1; i++)
    {
        int a, b;
        int64_t c;
        if (scanf("%d%d%" PRId64, &a, &b, &c) < 3) return 0;

        // 0-indexed
        a--;
        b--;

        goList[a].push_back(edge(b, c));
        goList[b].push_back(edge(a, c));
    }

    goAry.resize(N);
    gone.resize(N);

    for (int i = 0; i < N - 1; i++)
    {
        // 初期化
        goAry[i] = 0;
        // 行ったことがない
        gone[i] = false;
    }

    int Q;
    int K;
    if (scanf("%d%d", &Q, &K) < 2) return 0;

    start = --K;

    // 幅優先探索 Breadth-First Search
    bfs();

    int x;
    int y;
    for (int i = 0; i < Q; i++)
    {
        if (scanf("%d%d", &x, &y) < 2) return 0;
        x--;
        y--;
        printf("%" PRId64 "\n", goAry[x] + goAry[y]);
    }

    return 0;
}

