#define MAX 100010
using namespace std;

//木のデータ構造
vector<vector<int> > tree(10, vector<int>() );

//訪問済み検査配列
vector<bool> visit(MAX, false);

//頂点Kから頂点iへの最短距離はdist[i]である
long long dist[MAX];

//頂点間の距離（コスト）
map< set<int>, int> cost;

//頂点nowからの距離がdである
void dfs(int now, long long d){
  for(auto next : tree[now-1]){
    //訪問済みなら次の頂点へ
    if(visit[next-1] == true)
      continue;

    //nextを訪問済みにし，距離を計算
    visit[next-1] = true;
    dist[next-1] = d + cost[{now, next}];

    //再帰的にDFS
    dfs(next, dist[next-1]);
  }
}


int main(void){
  int N;
  cin >> N;

  //treeの作成
  int a, b, c;
  rep(i, N-1){
    cin >> a >> b >> c;
    tree[a-1].push_back(b);
    tree[b-1].push_back(a);
    cost[{a, b}] = c;
  }

  int Q, K;
  cin >> Q >> K;

  //頂点Kを探索済みにする
  visit[K-1] = true;

  //最短経路探索
  dfs(K, 0);

  //クエリ処理
  int x, y;
  rep(i, Q){
    cin >> x >> y;
    //頂点x -> K -> yの最短距離を考えればよい
    cout << dist[x-1] + dist[y-1] << endl;
  }

  return 0;
}

