    for (int64_t i = 0; i < Q; ++i) {
        int64_t x, y;
        std::cin >> x >> y;
        x--;
        y--;
        auto distFromX = g.find_shortest_path(x, 0);

        std::cout << (*distFromX)[K] + (*distFromK)[y] << std::endl;
    }

    return 0;
}

