const int N = 1e5+5;
struct node{
	int v,w;
};
vector<node> E[N];
long long dis[N];
bool vis[N];

void dfs(int u,long long sum){
	dis[u] = sum;
	vis[u] = 1;
	for(int i = 0;i < E[u].size();i++){
		int& v = E[u][i].v;
		if (vis[v]) continue;
		dfs(v,sum + E[u][i].w);
	}
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int n;
	cin >> n;
	for(int i = 1;i < n;i++){
		int a,b,c;
		cin >> a >> b >> c;
		node tmp = {b,c};
		E[a].push_back(tmp);
		tmp.v = a;
		E[b].push_back(tmp);
	}
	int q,k;
	cin >> q >> k;
	dfs(k,0);
	while(q--){
		int x,y;
		cin >> x >> y;
		cout << dis[x] + dis[y] << '\n';
	}
	return 0;
}

