const int mod = 1000000007;
const int inf = mod*mod;
const int d5 = 100100;

typedef pair<int, int> P;
struct edge { int v, w; };

vector<int> dijkstra(int N, vector<vector<edge>>& G, int s) {
	vector<int> d(N, inf);
    d[s] = 0;
	priority_queue<P,vector<P>,greater<P>> Q;
	Q.push(P(0, s));
	while (!Q.empty()){
		P p = Q.top();
        Q.pop();
		int u = p.second;
		if (p.first > d[u]) continue;
		for (edge e: G[u]){
			if (d[e.v] > d[u] + e.w) {
				d[e.v] = d[u] + e.w;
				Q.push(P(d[e.v], e.v));
			}
        }
	}
	return d;
}

