        cin>>u>>v>>w;
		u--, v--;
		G[u].push_back(edge{v,w});
		G[v].push_back(edge{u,w});
	}
	int Q,x;
    cin>>Q>>x;
	x--;
	vector<int> d = dijkstra(N, G, x);
	for(int i=0;i<Q;i++){
        int u,v;
        cin>>u>>v;
        u--;
        v--;
        cout<<d[u]+d[v]<<endl;
	}
}

