int const N_MAX = 100001;

std::map<std::uint64_t, std::uint64_t> length[N_MAX];
std::uint64_t cost[N_MAX];

void depthFirstSearch(std::uint64_t u, std::uint64_t old_u) {
	for (auto const & p : length[u]) {
		std::uint64_t v = p.second;

		if (v == old_u) continue;
		cost[v] = cost[u] + length[u][p.first];
		depthFirstSearch(v, u);
	}

	return;
}


int main() {
	std::uint64_t N, Q, K;
	std::uint64_t a, b, c, x, y;

	std::cin >> N;
	for (std::uint64_t i = 0; i < N; ++i) {
		std::cin >> a >> b >> c;
		length[a][b] = c;
		length[b][c] = c;
	}

	std::cin >> Q >> K;
	depthFirstSearch(K, 0);
	for (std::uint64_t i = 0; i < Q; ++i) {
		std::cin >> x >> y;
		std::cout << cost[x] + cost[y] << std::endl;
	}


	return 0;
}

