struct Tree
{
	Edge edge[maxn<<1];
	LL st[maxn][20],fa[maxn][20];
	int first[maxn],le,dep[maxn];
	LL dis[maxn];
	Tree() {le=2;}
	void in(int x,int y,int v)
	{
		edge[le].to=y;
		edge[le].v=v;
		edge[le].next=first[x];
		first[x]=le++;
	}
	void insert(int x,int y,int v)
	{
		in(x,y,v);
		in(y,x,v);
	}
	void dfs(int x,int f,int v,int cur)
	{
		st[x][0]=v;
		fa[x][0]=f;
		dep[x]=cur;
		dis[x]=dis[f]+v;
		for (int i=first[x];i;i=edge[i].next)
			if (edge[i].to!=f)
				dfs(edge[i].to,x,edge[i].v,cur+1);
	}
	void makest()
	{
		for (int j=1;j<=18;j++)
			for (int i=1;i<=n;i++)
			{
				fa[i][j]=fa[fa[i][j-1]][j-1];
				st[i][j]=st[i][j-1]+st[fa[i][j-1]][j-1];
			}
	}
	LL find(int x,int y)
	{
		int xx=x,yy=y;
		if (dep[x]<dep[y]) swap(x,y);
		for (int j=18;j>=0;j--)
			if (dep[fa[x][j]]>=dep[y]) x=fa[x][j];
		if(x==y) return dis[xx]+dis[yy]-2*dis[x];
		for (int j=18;j>=0;j--)
			if (fa[x][j]!=fa[y][j])
			{
				x=fa[x][j];
				y=fa[y][j];
			}
		int lca=fa[x][0];return dis[xx]+dis[yy]-2*dis[lca];
	}
}t;
