#include <bits/stdc++.h>
using namespace std;

#define INF (INT64_MAX/2)
#define MAX 100000

struct edge { int to; long long cost; };
typedef pair< long long, int >  P;

int N;
int Q, K;
vector< edge > G[MAX];
long long d[MAX];

void dijkstra( int s )
{
	priority_queue< P, vector<P>, greater<P> > que;
/*
	for( int i = 0; i < N; i++ ) {
		d[i] = INF;
	}
*/
	fill( d, d + N, INF );
	d[s] = 0;
	que.push( P( 0, s ) );
	while( !que.empty() ) {
		P p = que.top(); que.pop();
		int v = p.second;
		if( d[v] < p.first ) continue;
		for( int i = 0; i < G[v].size(); i++ ) {
			edge e = G[v][i];
			if( d[e.to] > d[v] + e.cost ) {
				d[e.to] = d[v] + e.cost;
				que.push( P( d[e.to], e.to ) );
			}
		}
	}
}

