void update(int par, int cur){
    auto iter = m.find(pair<int, int>(min(par, cur), max(par, cur)));
    if(iter == m.end()) exit(-1);
    ret[cur] = iter->second;

    for(auto i : v[cur]){
        if(par == i) continue;
        auto next = m.find(pair<int, int>(min(cur, i), max(cur, i)));
        if(next == m.end()) exit(-1);
        next->second += ret[cur];
        ret[i] = next->second;
        update(cur, i);
    }
}

