void dfs(vector<vector<int>> const& adj, vector<vector<int64_t>> const& costs, int k, int v, vector<int64_t>& result)
{
    for (int ichild = 0; ichild < (int) adj[v].size(); ++ichild) {
        int child = adj[v][ichild];
        int64_t cost = costs[v][ichild];
        if (!result[child] && child != k) {
            result[child] = result[v] + cost;
            dfs(adj, costs, k, child, result);
        }
    }
}

int main()
{
    cin.sync_with_stdio(false); cin.tie(0);
    cout.sync_with_stdio(false); cout.tie(0);

    int n;
    cin >> n;
    vector<vector<int>> adj(n);
    vector<vector<int64_t>> costs(n);
    for (int i = 0; i < n - 1; ++i) {
        int x, y; int64_t cost;
        cin >> x >> y >> cost; --x; --y;
        adj[x].push_back(y);
        adj[y].push_back(x);
        costs[x].push_back(cost);
        costs[y].push_back(cost);
    }
    vector<int64_t> result(n);
    int q, k;
    cin >> q >> k; --k;
    dfs(adj, costs, k, k, result);
    for (int i = 0; i < q; ++i) {
        int x, y;
        cin >> x >> y; --x; --y;
        cout << result[x] + result[y] << "\n";
    }
}

