const int maxn = 4e5+10;
struct edge{
	long long to;
	long long weight;
	edge( long long to,long long weight) : to(to),weight(weight){}
};
vector<edge>g[maxn];
long long vs[maxn*2-1];//dfs访问顺序 
long long depth[maxn*2-1];//节点深度 
long long id[maxn];//各个顶点在vs中首次出现的下标 
long long dist[maxn];//节点到根结点的距离 
long long bit[maxn*2-1][16];//RMQ的binaryindexdtree节点 
void rmq_init(long long n)
{
	for(long long i=0;i<n;i++)
	{
		bit[i][0] = i;
	}
	for(long long j=1;(1<<j)<n;j++)
	{
		for(long long i=0;i+(1<<j)-1<n;i++)
		{
			if(depth[bit[i][j-1]] <= depth[bit[i+(1<<(j-1))][j-1]])
			{
				bit[i][j] = bit[i][j-1];
			}
			else
			{
				bit[i][j] = bit[i+(1<<(j-1))][j-1];
			}
		}
	}
}
long long query(long l,long long r)
{
	long long k = 0;
	while((1<<(k+1))<r-l+1)
		k++;
	if(depth[bit[l][k]] <= depth[bit[r-(1<<k)][k]])
	{
		return bit[l][k];
	}
	else
	{
		return bit[r-(1<<k)][k];
	}
}
void dfs(long long v,long long p,long long d,long long &k)
{
	id[v] = k;
	vs[k] = v;
	depth[k++] = d;
	for(long long i=0;i<g[v].size();i++)
	{
		if(g[v][i].to != p)
		{
			dist[g[v][i].to] = dist[v] + g[v][i].weight;
			dfs(g[v][i].to,v,d+1,k);
			vs[k] = v;
			depth[k++] = d;
		}
	 } 
}
long long init(long long V)
{
	long long k = 0;
	long long root = 0;
	dfs(root,-1,0,k);
	rmq_init(V*2-1);
}
long long lca(long long u,long long v)
{
	return vs[query(min(id[u],id[v]),max(id[u],id[v])+1)];
}
void add_edge(long long from,long long to,long long weight)
{
	g[from].push_back(edge(to,weight));
}
