		v[a].push_back({b,c});
		v[b].push_back({a,c});
	}
	dfs(1,0,0);
	init_bz();
	int q,k;
	scanf("%d%d",&q,&k);
	while(q--){
		int a,b;
        scanf("%d%d",&a,&b);
        int lcaab=LCA(a,b);
        int lcaak=LCA(lcaab,k);
        //cout<<lcaab<<" "<<lcaak<<endl;
        if(lcaak==lcaab&&deep[k]<deep[lcaab])printf("%lld\n",getdis(a,b));
        else printf("%lld\n",getdis(a,b)+2*getdis(lcaab,k));
		//printf("%d\n",ans);
	}
}

