int last[N];
ll z, dis[N];
bool vis[N];
struct orz {
    int v, next;
    ll w;
} e[N * 4];

struct stu {
    int s, dis;

    bool operator<(const stu &a) const {
        return dis > a.dis;
    }
};

void add(int u, int v, ll w) {
    cnt++;
    e[cnt].v = v;
    e[cnt].next = last[u];
    last[u] = cnt;
    e[cnt].w = w;
}

void Dij(int s) {
    priority_queue<stu> q;
    while (!q.empty()) q.pop();
    for (int i = 1; i <= n; i++) dis[i] = 1e16;
    memset(vis, 0, sizeof(vis));
    dis[s] = 0;
    stu now;
    now.dis = 0;
    now.s = s;
    q.push(now);
    while (!q.empty()) {
        now = q.top();
        q.pop();
        if (vis[now.s]) continue;
        vis[now.s] = 1;
        for (int i = last[now.s]; i; i = e[i].next) {
            int to = e[i].v;
            if (dis[to] > dis[now.s] + e[i].w) {
                dis[to] = dis[now.s] + e[i].w;
                stu nex;
                nex.s = to;
                nex.dis = dis[to];
                q.push(nex);
            }
        }
    }
}

