const int MaxN = 1e5;

int n, q, k;
int all;
int pre[2 * MaxN + 5], last[2 * MaxN + 5], other[2 * MaxN + 5];
LL cost[2 * MaxN + 5];
LL dis[MaxN + 5];
bool vis[MaxN + 5];

void build(int x, int y, LL w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void spfa(int s)
{
	for(int i = 1; i <= n; i++)
		dis[i] = INF;
	dis[s] = 0;
	vis[s] = 1;
	queue <int> q;
	q.push(s);
	int now, ed, dr;
	while(!q.empty()) {
		now = q.front();
		q.pop();
		ed = last[now];
		while(ed != -1) {
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr]) {
				dis[dr] = dis[now] + cost[ed];
				if(!vis[dr]) {
					q.push(dr);
				}
			}
			ed = pre[ed];
		}
		vis[now] = 0;
	}
}

int main()
{
	cin >> n;
	all = -1; memset(last, -1, sizeof(last));
	for(int i = 1; i < n; i++) {
		int u, v;
		LL w;
		cin >> u >> v >> w;
		build(u, v, w);
		build(v, u, w);
	}
	scanf("%d %d", &q, &k);
	spfa(k);
	for(int i = 1; i <= q; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
