int dfs(int start, int end)
{
	int res = 0;
	stack <pair<int,int>> s;
	bool visited[100001] = { false, };
	s.push(make_pair(start,0));
	while (!s.empty())
	{
		int edge = s.top().first;
		int dist = s.top().second;
		bool flag = false;
		if (visited[edge] == false)
		{
			visited[edge] = true;
			res += dist;
		}
		if (edge == end)
		{
			break;
		}

		for (auto v : graph[edge])
		{
			if (visited[v.first] == false)
			{
				flag = true;
				s.push(make_pair(v.first,v.second));
			}
		}

		if (flag == false)
		{
			res -= s.top().second;
			s.pop();
		}
	}
	return res;
}
