void dfs1(int v, int p){
  up[v][0] = p;
  hh[v] = hh[p] + 1;
  for(int j = 1; j < 20; ++j){
    up[v][j] = up[up[v][j - 1]][j - 1];
  }
  for(pii i : g[v]){
    if(i.first == p){
      continue;
    }
    h[i.first] = h[v] + i.second;
    dfs1(i.first, v);
  }
}

int lca(int x, int y){
  if(hh[x] < hh[y]){
    swap(x, y);
  }
  for(int j = 19; j >= 0; --j){
    if(up[x][j] && ((hh[x] - hh[y]) >> j) & 1){
      x = up[x][j];
    }
  }
  for(int j = 19; j >= 0; --j){
    if(up[x][j] && up[y][j] && up[x][j] != up[y][j]){
      x = up[x][j];
      y = up[y][j];
    }
  }
  if(x == y){
    return x;
  }
  return up[x][0];
}

ll dist(int x, int y){
  return h[x] + h[y] - 2 * h[lca(x, y)];
}

