void short_path(ll ss)
{
	fill(d,d+n+1,INF);
	priority_queue<P,vector<P>,greater<P>>qu;
	d[ss]=0;
	qu.push(P(0,ss));
	while(!qu.empty())
	{
		P p=qu.top();qu.pop();
		ll u=p.second;ll dis=p.first;
		if(d[u]<dis)continue;
		for(ll v=0;v<G[u].size();++v)
		{
			P x=G[u][v];
			if(d[x.second]>dis+x.first)
			{
				d[x.second]=dis+x.first;
				qu.push(P(d[x.second],x.second));
			}
		}
	}
}
