void BFS(int v){
  //cout << "first v " << v << endl;
  queue<int> q;
  int i=0;
  visited[v] = 1;
  q.push(v);
  int d=0;
  int d_before=0;
  while(!q.empty()){
    int val = q.front();
    //cout << "Pop "  << val  << endl;
    for(auto &e : tree[val]){
      //cout << " Next " << e.to << " Cost " << e.cost << endl;
      if(visited[e.to] != 1){
	//cout << "Visited:" <<  e.to << endl;
	d = depth[val] + e.cost;
	depth[e.to] = d;
	visited[e.to] = 1;
	q.push(e.to);
      }else{
	d = 0;
      }
    }
    q.pop();
  }

}

