void solve() {
	int N; cin >> N;
	vector<vector<pii>> G(N); //cost, to
	REP(i, N - 1) {
		int a, b, c;  cin >> a >> b >> c;
		--a; --b;
		G[a].emplace_back(c, b);
		G[b].emplace_back(c, a);
	}
	int Q, K; cin >> Q >> K;
	--K;
	vector<int> d(N, inf);
	d[K] = 0;
	queue<int> que;
	que.push(K);
	while (not que.empty()) {
		int node = que.front(); que.pop();
		for (auto &to : G[node]) {
			if (d[to.second] != inf) continue;
			d[to.second] = d[node] + to.first;
			que.push(to.second);
		}
	}

	REP(i, Q) {
		int x, y; cin >> x >> y;
		--x; --y;
		cout << d[x] + d[y] << endl;
	}
}

