vector<ll> bfs(ll start, vector<vector<pair<ll,ll>>> &adjlist) {
	//returns all distances to start
	queue<pair<ll,ll>> q;
	vector<ll> distances(adjlist.size());
	q.push({start,0});
	while (!q.empty()) {
		ll v = q.front().first, c = q.front().second;
		distances[v] = c;
		q.pop();
		for (pair<ll,ll> p : adjlist[v]) {
			ll nextv = p.first, nextc = p.second;
			if (!distances[nextv])
				q.push({nextv,c+nextc});
		}
	}
	distances[start]=0;
	return distances;
}

