typedef pair<int, int> edge;


vector<edge> G[100005];
int N, Q, K;

llint dist[100005];
bool used[100005];

void dijkstra()
{
	priority_queue<int, vector<int>, greater<int> > Q;

	for(int i = 1; i <= N; i++){
		dist[i] = inf;
	}
	dist[K] = 0;
	Q.push(K);

	int v;
	while( (int)Q.size() ){
		v = Q.top();
		Q.pop();
		used[v] = true;

		for(int i = 0; i < (int)G[v].size(); i++){
			if(used[G[v][i].first]) continue;
			dist[G[v][i].first] = min(dist[G[v][i].first], dist[v] + G[v][i].second);
			Q.push(G[v][i].first);
		}
	}
}

