using namespace std;

struct NODE{
	ll dist;
	ll number;
	bool done;
	vl edges_to;
	vl edges_cost;
	bool operator<= (const NODE &temp) const { return this->dist >= temp.dist; }
	bool operator>= (const NODE &temp) const { return this->dist <= temp.dist; }
	bool operator< (const NODE &temp) const { return this->dist > temp.dist; }
	bool operator> (const NODE& temp) const { return this->dist < temp.dist; }
};

ll dijkstra(vector<NODE> nodes, ll start, ll x,ll y){
	priority_queue<NODE> q;
	vb contains_flag(nodes.size(),false);
	nodes[start].dist = 0;
	q.push(nodes[start]);
	contains_flag[start] = true;
	while (!q.empty()){
		NODE temp_v = q.top();
		q.pop();
		contains_flag[temp_v.number] = false;
		//cout << "temp_v.number="<<temp_v.number << endl;
		temp_v.done = true;
		rep(i, temp_v.edges_to.size()){
			ll to = temp_v.edges_to[i];
			ll cost = temp_v.edges_cost[i] + temp_v.dist;
			if (nodes[to].dist < 0 || cost < nodes[to].dist){
				nodes[to].dist = cost;
				if (!contains_flag[to]){
					q.push(nodes[to]);
					//cout << "push_" << to << endl;
					contains_flag[to] = true;
				}
			}
		}
	}return nodes[x].dist+nodes[y].dist;
}

int main(){
	ll n; cin >> n;
	vector<NODE> nodes(n);
	nodes[0].dist = -1;
	nodes[0].done = false;
