	rep(i, n-1){
		ll a, b, c;
		cin >> a >> b >> c;
		nodes[a-1].edges_to.push_back(b-1);
		nodes[a-1].edges_cost.push_back(c);
		nodes[b - 1].edges_to.push_back(a - 1);
		nodes[b - 1].edges_cost.push_back(c);
		nodes[i + 1].number = i + 1;
