using Weight = int;
struct Edge {
  int dst;
  Weight weight;
  Edge() : dst(0), weight(0) {}
  Edge(int d, Weight w = 1) : dst(d), weight(w) {}
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

vector<ll> distdist(const Graph &G, const int root = 0) {
  vector<ll> dist(G.size());
  dist[root] = 0;
  function<void(int, int)> dfs = [&](int cur, int pre) {
    for (const auto &nex : G[cur]) {
      if (nex.dst != pre) {
        dist[nex.dst] = dist[cur] + nex.weight;
        dfs(nex.dst, cur);
      }
    }
  };
  dfs(root, -1);
  return dist;
}


