	for (i=20;i>=0;i--)
		if (depth[anc[u][i]]>=depth[v])
		{
			res+=sum[u][i];
			u=anc[u][i];
		}
	if (u==v) return res;
	for (i=20;i>=0;i--)
		if (anc[u][i]!=anc[v][i])
		{
			res+=sum[u][i];
			res+=sum[v][i];
			u=anc[u][i];
			v=anc[v][i];
		}
	return res+sum[u][0]+sum[v][0];
}

