void dijkstra(int s){
	// piiのfirstは最短距離、secondは頂点の番号
	priority_queue<pll, vector<pll>, greater<pll>> que;
	fill(d, d+V, INF);
	d[s]=0;
	que.push(pii(0, s));
	while(!que.empty()){
		pll p=que.top();
		que.pop();
		ll v=p.second;
		if(d[v]<p.first){
			continue;
		}
		REP(i, g[v].size()){
			edge e=g[v][i];
			if(d[e.to]>d[v]+e.cost){
				d[e.to]=d[v]+e.cost;
				que.push(pii(d[e.to], e.to));
			}
		}
	}
}

