#include <bits/stdc++.h>
using namespace std;

template<class T> struct LowestCommonAncestor {
    using Graph = vector<vector<pair<int, T>>>;
    const T t_inf = numeric_limits<T>::max();
    pair<T, int> id = make_pair(t_inf, INT_MAX);
    int n;
    vector<pair<T, int>> data;
    vector<int> idx;

    LowestCommonAncestor(Graph G, int s = 0) : idx(G.size(), -1), n(1) {
        vector<pair<T, int>> p;
        EulerTour(G, s, s, 0, p);
        int sz = p.size();
        for (int i = sz-1; i >= 0; i--) idx[p[i].second] = i;
        while (n < sz) { n *= 2; }
        data.resize(2*n-1, id);
        for (int i = 0; i < sz; i++) data[i+n-1] = p[i];
        for (int i = n-2; i >= 0; i--) data[i] = min(data[i*2+1], data[i*2+2]);
    }
    void EulerTour(const Graph &G, int now, int par, T dep, vector<pair<T, int>> &path) {
        path.emplace_back(dep, now);
        for (auto nxt : G[now]) if (nxt.first != par) {
            EulerTour(G, nxt.first, now, dep+nxt.second, path);
            path.emplace_back(dep, now);
        }
    }

    pair<T, int> query (int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return data[k];
        pair<T, int> vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        pair<T, int> vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return min(vl, vr);
    }

    int ancestor (int a, int b) {
        int l = min(idx[a], idx[b]), r = max(idx[a], idx[b]);
        return query(l, r).second;
    }

    T distance(int a, int b) {
        int l = min(idx[a], idx[b]), r = max(idx[a], idx[b]);
        T an = query(l, r + 1).first;
        T d1 = data[idx[a]+n-1].first, d2 = data[idx[b]+n-1].first;
        return (d1 + d2 - an*2);
    }
};

int main() {
    int n, q, k;
    cin >> n;
    vector<vector<pair<int, long long>>> g(n);
    for (int i = 0; i < n-1; i++) {
        int a, b; long long c;
        cin >> a >> b >> c; a--; b--;
        g[a].emplace_back(b, c);
        g[b].emplace_back(a, c);
    }
    cin >> q >> k;
    LowestCommonAncestor<long long> lca(g, --k);

    while (q--) {
        int a, b; cin >> a >> b; a--; b--;
        long long ans = lca.distance(a, k) + lca.distance(k, b);
        cout << ans << endl;
    }
    return 0;
}

