struct Edge {
	int to, length;
};
int main() {
	int n; std::cin >> n;
	std::vector<std::vector<Edge>> nodes(n);
	for (auto i = 1; i < n; ++i) {
		int a, b, c; std::cin >> a >> b >> c; --a; --b;
		nodes[a].push_back(Edge{ b, c });
		nodes[b].push_back(Edge{ a, c });
	}
	int q, k; std::cin >> q >> k; --k;
	std::vector<long long int> min_distance(n, -1);
	std::stack<int> stack;
	min_distance[k] = 0; stack.push(k);
	while (!stack.empty()) {
		const auto top = stack.top(); stack.pop();
		for (const auto edge : nodes[top]) if (min_distance[edge.to] == -1) {
			min_distance[edge.to] = min_distance[top] + edge.length;
			stack.push(edge.to);
		}
	}
	for (auto i = 0; i < q; ++i) {
		int x, y; std::cin >> x >> y; --x; --y;
		std::cout << min_distance[x] + min_distance[y] << std::endl;
	}
}

