struct edge {int to;ll cost;};
void dijkstra(int start, const vector<vector<edge>>&edges, vector<ll>& d){
    const int n = edges.size();
    d.resize(n);
    priority_queue<P,vector<P>,greater<P>> Q;
    fill(all(d),LINF);
    d[start]=0;
    Q.push(make_pair(0,start));
    while(!Q.empty()){
        P p=Q.top();
        Q.pop();
        int v=p.second;
        if(d[v]<p.first)continue;
        REPA(i,edges[v]){
            edge e=edges[v][i];
            if(d[e.to]>d[v]+e.cost){
                d[e.to]=d[v]+e.cost;
                Q.push(make_pair(d[e.to],e.to));
            }
        }
    }
}

