};

vector<edge> edges;
vector<int> v[100005];

void adde(int from,int to,long long cost)
{
    edge tmp;

    tmp.from = from;
    tmp.to = to;
    tmp.cost = cost;

    edges.push_back(tmp);

    int m = edges.size() - 1;

    v[from].push_back(m);
}

long long d[100005];

long long bfs(int s,int en)
{
    memset(d,-1,sizeof(d));

    queue<int> q;

    d[s] = 0;
    q.push(s);

    while (!q.empty())
    {
        int t = q.front();q.pop();

        if (t == en) return d[en];

        for (int i = 0;i < v[t].size();i++)
        {
            int id = v[t][i];

            edge e = edges[id];

            if (d[e.to] == -1)
            {
                d[e.to] = d[t] + e.cost;

                q.push(e.to);
            }
        }
    }
}

