void dijk(int n,int start)
{
    memset(vis,0,sizeof(vis));
    for(int i=1;i<=n;i++) dist[i]=INF;
    priority_queue<node>q;
    while(!q.empty())
    {
        q.pop();
    }
    dist[start]=0;
    q.push(node(start,0));
    node tmp;
    while(!q.empty())
    {
