typedef pair<long long, long long> pi;

long long n, a, b, c, q, k, x, y, dist[100001], p[100001][20], depth[100001];
vector<pi> adj[100001];

void dfs(long long node){
        for(vector<pi>::iterator it = adj[node].begin(); it != adj[node].end(); it++){
                if(it->first == 1 || depth[it->first] != 0 || dist[it->first] != 0) continue;
                dist[it->first] = dist[node]+it->second;
                p[it->first][0] = node;
                depth[it->first] = depth[node]+1;
                dfs(it->first);
        }
}

long long lca(long long x, long long y){
        if(depth[x] < depth[y]) swap(x, y);
        for(int k = 19; k >= 0; k--){
                if(p[x][k] != -1 && depth[p[x][k]] >= depth[y]) x = p[x][k];
        }
        if(x == y) return x;
        for(int k = 19; k >= 0; k--){
                if(p[x][k] != p[y][k]){
                        x = p[x][k];
                        y = p[y][k];
                }
        }
        return p[x][0];
}

long long distance(long long x, long long y){
        return dist[x]+dist[y]-2*dist[lca(x, y)];
}

