using namespace std;

struct Union_find{
	vector<int> par;
	vector<int> rank;
	vector<long long> diff_weight;
	Union_find(int p){
		par = vector<int>(p + 1);
		rank = vector<int>(p + 1);
		diff_weight = vector<long long>(p + 1);
		for(int i = 1; i <= p; i++){
			par[i] = i;
		}
	}
	int find(int x){
		if(par[x] == x)
			return x;
		else{
			int pa = find(par[x]);
			diff_weight[x] += diff_weight[par[x]];
			return par[x] = pa;
		}
	}
	void unite(int x, int y, long long w){
		w = w + weight(x) - weight(y);
		x = find(x);
		y = find(y);
		if(x == y) return;
		if(rank[x] < rank[y]){
			par[x] = y;
			diff_weight[x] = -1 * w;
		} else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
			diff_weight[y] = w;
		}
	}
	bool same(int x, int y){
		return find(x) == find(y);
	}
	long long weight(int x){
		find(x);
		return diff_weight[x];
	}
	long long diff(int x, int y){
		return weight(y) - weight(x);
	}
};

int main(){
	int n, ans = 0;
	cin >> n;
	Union_find uf(n);
	for(int i = 0; i < n - 1; i++){
		int a, b, c;
		cin >> a >> b >> c;
		uf.unite(a, b, c);
	}
