ll solve(vector<vll> &dp , vector<vll> node , ll start , ll goal , ll before){
    if (dp[start][goal]!=-1)return dp[start][goal];
    vll ans(node[start].size() , 0);
    REP(i,node[start].size()){
        ll next = node[start][i];
        if(next!=before && start != before){
            ans[0] += dp[start][next];
            //cout << "Here : " << ans[0] << endl;
            ans[0] += solve(dp , node , next , goal , start);
            ans[1] = 1000000000000;
            break;
        }
        else if(start == before){    
            ans[i] += dp[start][next];
            //cout << "Here : " << ans[i] << endl;
            ans[i] += solve(dp , node , next , goal , start);
        }
        else if(i==node[start].size()-1 && start != before )return 1000000000000;

    }
    dp[start][goal] = MIN(ans).first;
    return dp[start][goal];
}



