const int N = 1e5+10;
const ll INF = 1e15;

using namespace std;

vector<pair<int,ll>> Graph[N];
vector<ll> dist;

void dijkstra (int k, int n)
{
    dist.assign(n+1,INF);
    dist[k]=0;
    set<pair<ll,int>> q;
    q.insert({0LL,k});
    while (!q.empty())
    {
        int v=q.begin()->ss;
        q.erase(q.begin());
        for (auto e: Graph[v])
        {
            int to=e.ff;
            ll len=e.ss;
            if (dist[to]>dist[v]+len)
            {
                dist[to]=dist[v]+len;
                q.insert(mp(dist[to],to));
            }
        }
    }
}

