        Graph[a].pb(mp(b,c));
        Graph[b].pb(mp(a,c));
    }
    cin>>q>>k;
    dijkstra(k,n);
    int x,y;
    while (q--)
    {
        cin>>x>>y;
        cout<<dist[x]+dist[y]<<endl;
    }
}

