  while (!pq.empty()) {
    pair<long long, int> now = pq.top(); pq.pop();
    if (minDist[now.second] != now.first) {
      continue;
    }
    for (pair<int, long long> nxt : G[now.second]) {
      const long long nextCost = minDist[now.second] + nxt.second;
      if (minDist[nxt.first] <= nextCost) {
        continue;
      }
      minDist[nxt.first] = nextCost;
      pq.push({nextCost, nxt.first});
    }
  }
  for (int i = 0; i < q; i++) {
    cerr << "problem " << i + 1 << " solved" << endl;
    int x, y;
