#include<bits/stdc++.h>
using namespace std;

#include<algorithm>
#include<functional>
#include<vector>

using Size = int;
using Vertex = int;
using Weight = long long;
struct Edge {Vertex from, to; Weight weight;};
using Graph = std::vector<std::vector<Edge>>;

class CentroidDecomposition {
 public:
  CentroidDecomposition(const Graph& G, Vertex root) : parent(G.size(), NIL), depth(G.size(), 0), subsize(G.size(), 1), head(G.size()), d(G.size(), 0) {
    std::function<Size(Vertex)> dfs = [&](Vertex cur) {
      for(const auto& e: G[cur]) if(e.to != parent[cur]) {
        d[e.to] += d[e.from] + e.weight;
        depth[e.to] = depth[cur] + 1;
        parent[e.to] = cur;
        subsize[cur] += dfs(e.to);
      }
      return subsize[cur];
    };
    std::function<void(Vertex)> build = [&](Vertex cur) {
      Vertex nex = NIL;
      Size size = 0;
      for(const auto& e: G[cur]) if(e.to != parent[cur]) if(chmax(size, subsize[e.to]) == subsize[e.to]) nex = e.to;
      for(const auto& e: G[cur]) if(e.to != parent[cur]) {
        if(e.to == nex) head[e.to] = head[cur];
        else            head[e.to] = e.to;
        build(e.to);
      }
    };
    dfs(root);
    build(head[root] = root);
  }
  Vertex lca(Vertex u, Vertex v) const {
    while(head[u] != head[v]) {
      if(depth[head[u]] > depth[head[v]]) std::swap(u, v);
      v = parent[head[v]];
    }
    return depth[u] < depth[v] ? u : v;
  }
  Weight distance(auto u, auto v) {
    return d[u] + d[v] - d[lca(u,v)];
  }
 private:
  inline Size position(Vertex v) {return depth[v] - depth[head[v]];}
  template<typename T> inline T chmax(T& l, const T& r) {return l = std::max(l, r);};
  const Size NIL = -1;
  std::vector<Vertex> head, parent;
  std::vector<Size> depth, subsize;
  vector<Weight> d;
};

int main() {
  int N;
  cin >> N;
  Graph G(N);
  for(auto i=1; i<N; ++i) {
    int a, b, c;
    cin >> a >> b >> c;
    --a; --b;
    G[a].push_back({a,b,c});
    G[b].push_back({b,a,c});
  }

  CentroidDecomposition T(G, 0);

  int Q, K;
  cin >> Q >> K;
  --K;
  for(auto i=0; i<Q; ++i) {
    int x, y;
    cin >> x >> y;
    --x; --y;
    cout << T.distance(x, K) + T.distance(K, y) << endl;
  }
}

