void dfs(
        const vector<vector<pair<int, int>>> &graph,
        vector<unsigned long long> &dist_from_K,
        int current_vertex,
        int prev_vertex,
        unsigned long long current_cost )
{
    auto &connected = graph[current_vertex];

    for( auto p : connected )
    {
        if( p.first == prev_vertex ) continue;

        dist_from_K[p.first] = current_cost + p.second;

        dfs( graph, dist_from_K, p.first, current_vertex, dist_from_K[p.first] );
    }
}

