#define INF 2e9
#define INF_LL 1LL<<60
#define ll long long
#define MAX_V 100005

struct edge {
    ll to;
    ll cost;
};

typedef pair<ll, ll> P;  // first: 最短距離, second: 頂点番号

ll V, d[MAX_V];
vector<edge> G[MAX_V]; // 隣接リスト表現

void dijkstra(ll s) {
    fill(d, d + V, INF_LL);
    d[s] = 0;  // 始点sへの最短距離は0

    priority_queue<P, vector<P>, greater<P>> que;  // 距離が小さい順に取り出せるようgreater<P>を指定
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;  // 更新した頂点の中で距離が最小の頂点v
        if (d[v] < p.first) {
