const int INF = 1e9;

using namespace std;

struct Edge {
  int to;
  ll cost;
  Edge(int to, ll cost) : to(to), cost(cost) {}
};

void dfs(int n, ll dist, vector<vector<Edge>> g, vector<ll>& d, vector<bool> checked) {
  vector<Edge> es = g.at(n);
  if(checked.at(n)) return;
  checked.at(n) = true;
  for(auto e : es) {
    if(checked.at(e.to)) continue;
    d.at(e.to) = dist + e.cost;
    dfs(e.to, d.at(e.to), g, d, checked);
  }
}

int main() {
  int N, Q, K;
  cin >> N;

  vector<int> a = vector<int>(N - 1);
  vector<int> b = vector<int>(N - 1);
  vector<int> c = vector<int>(N - 1);
  vector<vector<Edge>> g = vector<vector<Edge>>(N);
  REP(i, N - 1) {
    cin >> a.at(i) >> b.at(i) >> c.at(i);
    a.at(i)--;
    b.at(i)--;
    g.at(a.at(i)).push_back(Edge(b.at(i), c.at(i)));
    g.at(b.at(i)).push_back(Edge(a.at(i), c.at(i)));
  }

  cin >> Q >> K;
  K--;
  vector<bool> checked = vector<bool>(N, false);
  vector<ll> d = vector<ll>(N);
  dfs(K, 0, g, d, checked);

  vector<int> x = vector<int>(Q);
  vector<int> y = vector<int>(Q);
  REP(i, Q) {
    cin >> x.at(i) >> y.at(i);
    x.at(i)--;
    y.at(i)--;
    ll ans = d.at(x.at(i)) + d.at(y.at(i));
    cout << ans << endl;
  }
}

