// 深さ優先探索
vector<bool> seen;
vector<long long int> dist;
void dfs(const Graph &G, int v, long long Dist) {
    //cout << "dfs:" << v << '\n';
    seen[v] = true; // v を訪問済にする
    dist[v] = Dist;

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) { 
        if (seen[next_v.first]) continue; // next_v が探索済だったらスルー
        dfs(G, next_v.first, Dist + next_v.second); // 再帰的に探索
    }
}

int main() {
    long long int n, a, b, c;
    cin >> n;
    Graph G(n+1);
    for(int i = 0; i < n-1; ++i) {
        cin >> a >> b >> c;
        edge e = {b, c};
        G[a].push_back(e);
        e = {a, c};
        G[b].push_back(e);
    }
    long long int q, k, x, y;
    cin >> q >> k;
    seen.assign(n+1, false);
    dist.assign(n+1, 0);
    dfs(G, k, 0);
    for(int i = 0; i < q; ++i) {
        cin >> x >> y;
        cout << (dist[x] + dist[y]) << '\n';
    }

    return 0;
}

