std::vector<int> dijkstra(int s,int N,vector<vector<Edge>> Edges){
    vector<int> d;
    priority_queue<pair<int,int> ,vector<pair<int,int>>,greater<pair<int,int>> > que;
    REP(a,N+10){
        d.push_back(INF);
    }
    d[s]=0;
    que.push(make_pair(0,s));
    while(!que.empty()){
        pair<int,int> p = que.top();que.pop();
        int v = p.second;
        if(d[v]<p.first)continue;
        for(int  i = 0;i < Edges.at(v).size();i++){
            Edge e = Edges.at(v).at(i);
            if(d.at(e.to)>d.at(v)+e.value){
                d.at(e.to)=d.at(v)+e.value;
                que.push(make_pair(d.at(e.to),e.to));
            }
        }
    }
    return d;
}
