    void add_edge(ll v1,ll v2, ll w)
    {
        to[v1].push_back(Pint(v2, E));
        edges.push_back(Pint(v1, v2));
        weights.push_back(w);
        E++;
    }

    vector<ll> dist;
    void dijkstra(ll start)
    {
        dist = vector<ll>(V, dDefault);
        priority_queue<Plint, vector<Plint>, greater<Plint>> pq;
        pq.push(Plint(0, start));

        while (!pq.empty()) {
            Plint p = pq.top(); pq.pop();
            ll v = p.second;
            if (dist[v] >= 0 && dist[v] <= p.first) continue;
            dist[v] = p.first;
            for (auto vnxt : to[v]) {
                 ll dnxt = dist[v] + weights[vnxt.second];
                if (dnxt < dist[vnxt.first] || dist[vnxt.first] < 0) {
                    pq.push(Plint(dnxt, vnxt.first));
                }
            }
        }
    }
};

  ll i,n,q,k;cin>>n;ll a,b,c;
  UndirectedGraph graph(n);
  rep(i,n-1){cin>>a>>b>>c;a--;b--;graph.add_edge(a,b,c);graph.add_edge(b,a,c);}
  cin>>q>>k;ll x,y;k--;
  graph.dijkstra(k);
  rep(i,q){cin>>x>>y;x--;y--;cout<<graph.dist[x]+graph.dist[y]<<endl;}
  return 0;
}

