// 隣接リストで使う辺を表す型
struct Edge {
  int to, cost;  // 辺の接続先頂点, 辺の重み
  Edge(int to, int cost) : to(to), cost(cost) {}  // コンストラクタ
};

typedef vector<vector<Edge> > AdjList;  // 隣接リストの型
AdjList graph;  // グラフの辺を格納した構造体
                // graph[v][i]は頂点vから出るi番目の辺Edge

const ll INF = 100000000000;


// 戻り値がtrueなら負の閉路を含む
vector<ll> bellman_ford(int n, int s) { // nは頂点数、sは開始頂点
  vector<ll> dist; // 最短距離
  dist = vector<ll>(n, INF);
  dist[s] = 0; // 開始点の距離は0
  for (int i = 0; i < n; i++) {
    for (int v = 0; v < n; v++) {
      for (int k = 0; k < graph[v].size(); k++) {
        Edge e = graph[v][k];
        if (dist[v] != INF && dist[e.to] > dist[v] + e.cost) {
          dist[e.to] = dist[v] + e.cost;
        }
      }
    }
  }
  return dist;
}

void solve(long long N, std::vector<long long> a, std::vector<long long> b, std::vector<long long> c, long long Q, long long K, std::vector<long long> x, std::vector<long long> y){
  graph = AdjList(N+1);
  for (int i = 0; i < N; i++) {
    graph[a[i]].pb(Edge(b[i],c[i]));
    graph[b[i]].pb(Edge(a[i],c[i]));
  }
  for (int i = 0; i < Q; i++) {
    vector<ll> n = bellman_ford(N+1,x[i]);
    vector<ll> m = bellman_ford(N+1,K);
    cout << n[K] + m[y[i]] << endl;
  }
}

