#include <stack>

#define MAX_V 100001

using namespace std;

struct edge { int to; long long cost; };
struct set {int v, p; long long d; };
vector<edge> tree[MAX_V];
long long depth[MAX_V];

void dfs(int v, int p, long long d) {
    stack<set> St;
    St.push(set{v, p, d});

    while (!St.empty()) {
        set cur = St.top(); St.pop();
        depth[cur.v] = cur.d;
        for (int i = 0; i < tree[cur.v].size(); i++) {
            edge e = tree[cur.v][i];
            if (e.to == cur.p) { continue; }
            St.push(set{e.to, cur.v, cur.d + e.cost});
        }
    }
}

