                D[E[p][i]] = D[p] + C[p][i],
                P.push(make_pair(-D[E[p][i]], E[p][i]));
    }

    for (int q=0; q<Q; q++)
    {
        int x, y;
        cin>>x>>y;
        cout<<D[x-1]+D[y-1]<<endl;
