#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int maxn=100005;
const ll INF=1e18;
struct Edge{
	int from,to;
	ll dist;
	Edge(int u,int v,ll d):from(u),to(v),dist(d){};
};
struct HeapNode{
	ll d;
	int u;
	bool operator < (const HeapNode& rhs) const
	{
		return d>rhs.d;
	}
}; 
struct Dijk{
	int n,m,M;
	vector<Edge> edges;
	vector<int> G[maxn];
	bool done[maxn];
	ll d[maxn];
	int p[maxn];
	void init()
	{
		for(int i=1;i<=maxn;i++)
			G[i].clear();
		edges.clear();
	}
	void AddEdge(int from,int to,int dist)
	{
		edges.push_back(Edge(from,to,dist));
		M=edges.size();
		G[from].push_back(M-1);
	}
	void dijkstra(int s)
	{
		priority_queue<HeapNode> Q;
		for(int i=1;i<=n;i++)
			d[i]=INF;
		d[s]=0;
		memset(done,0,sizeof done);
		Q.push((HeapNode){0,s});
		while(!Q.empty())
		{
			HeapNode x=Q.top();
			Q.pop();
			int u=x.u;
			if(done[u])
				continue;
			done[u]=true;
			for(int i=0;i<(int)G[u].size();i++)
			{
				Edge& e=edges[G[u][i]];
				if(d[e.to]>d[u]+e.dist)
				{
					d[e.to]=d[u]+e.dist;
					p[e.to]=G[u][i];
					Q.push((HeapNode){d[e.to],e.to});
				}
			}
		}
	}
	void Domain()
	{
		int s,u,v,q,k;
		ll dis;
		scanf("%d",&n);
		init();
		for(int i=1;i<=n-1;i++)
		{
			scanf("%d%d%lld",&u,&v,&dis);
			AddEdge(u,v,dis);
			AddEdge(v,u,dis);
		}
		scanf("%d%d",&q,&k);
		dijkstra(k);
		for(int i=1;i<=q;i++) {
			scanf("%d%d",&u,&v);
			printf("%lld\n",d[u]+d[v]);
		}
	}
};
int main()
{
	Dijk a;
	a.Domain();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
int MAXIMUM=100000;
long INF = 1e12;
// W:未訪問
// G:訪問する候補
// B:訪問済み
int W=0,G=1,B=2;
vector<pair<int,int>> adj[100000];
long d[100000];
int dijkstra(int K){
  priority_queue<pair<int,int>> PQ;
  int u,minv;
  int color[MAXIMUM];
  // d[n]:Tに属する頂点と V - T に属する頂点をつなぐ辺の中で重みが最小の辺の重みを記録

  //初期化
  for(int i=0;i<n;i++){
    d[i]=INF;
    color[i]=W;
  }

  d[K]=0;
  PQ.push(make_pair(0,K));
  color[K] = G;

  while (!PQ.empty()) {
    pair<int,int> f = PQ.top();
    PQ.pop();
    u = f.second;
    // 頂点を訪問済に
    color[u] = B;
    //最小値を取り出し、それが最短でなければ無視
    if( d[u]<f.first*(-1)) continue;

    //訪問済みでないかつ辺がつながっている頂点の中でコストが最小の辺を選択
    for(int j=0;j<adj[u].size();j++){
      int v = adj[u][j].first;
      if(color[v]== B) continue;
      if(d[v]>d[u]+adj[u][j].second){
        d[v]=d[u]+adj[u][j].second;
        PQ.push(make_pair(d[v]*(-1),v));
        color[v]=G;
      }
    }
  }


}

int main(){
  cin>>n;
  for(int i=0;i<n-1;i++){
    int a,b,c;
    cin>>a>>b>>c;
      adj[a-1].push_back(make_pair(b-1,c));
      adj[b-1].push_back(make_pair(a-1,c));
    }

  int Q,K;
  cin>>Q>>K;
  dijkstra(K-1);
  for(int i=0;i<Q;i++){
      int x,y;
      cin>>x>>y;
      cout<<d[x-1]+d[y-1]<<endl;
  }

}

