vector<Int> dijkstra(vector<pair<Int, Int>> G[], Int n, Int s) {
    vector<Int> dist(n, INF);
    priority_queue<pair<Int, Int>, vector<pair<Int, Int>>, greater<pair<Int, Int>>> q;
    q.push({0, s});
    dist[s] = 0;
    while (not q.empty()) {
        pair<Int, Int> p = q.top();
