using namespace std;

static const long long  MAX = 105;
static const long long  INFTY = 17000000001;
static const long long  WHITE = 0;
static const long long  GRAY = 1;
static const long long  BLACK = 2;

long long  n, M[MAX][MAX];

long long  dijkstra(long long  start,long long  goal) {
    long long  u, minv;
    long long  d[MAX], p[MAX], color[MAX];

    for (long long  i = 0; i < n; i++) {
        d[i] = INFTY;
        p[i] = -1;
        color[i] = WHITE;
    }

    d[start] = 0;

    while (1) {
        minv = INFTY;
        u = -1;
        for (long long  i = 0; i < n; i++) {
            if (minv > d[i] && color[i] != BLACK) {
                u = i;
                minv = d[i];
            }
        }
        if (u == -1 || d[goal] != INFTY) {
            break;
        }
        color[u] = BLACK;
        for (long long  v = 0; v < n; v++) {
            if (color[v] != BLACK && M[u][v] != INFTY) {
                if (d[v] >  d[u] + M[u][v]) {
                    d[v] = d[u] + M[u][v];
                    color[v] = GRAY;
                }
            }
        }
    }

    return d[goal];
}
int  main() {
    cin >> n;

    for (long long  i = 0; i < n; i++) {
        for (long long  j = 0; j < n; j++) {
            M[i][j] = INFTY;
            M[j][i] = INFTY;
        }
    }

    long long  u, v, c;
    for (long long  i = 0; i < n - 1; i++) {
        cin >> u >> v >> c;
        u--;
        v--;
        M[u][v] = c;
        M[v][u] = c;
    }


    long long   x, y;
    long long  Q, K;
    cin >> Q >> K;
    K--;
    for (long long  i = 0; i < Q; i++) {
        cin >> x >> y;
        x--;
        y--;
        cout << dijkstra(x,K) + dijkstra(K,y)  << endl;
    }
    return 0;
}

