	while(!q.empty()) {
		pair<int, long long> a = q.top();
		q.pop();
		if(d[a.first] < a.second) continue;
		for(int i = 0; i < graph[a.first].size(); ++i) {
			pair<int, long long> e = graph[a.first][i];
			if(d[e.first] > d[a.first] + e.second) {
