const LL INF = (LL)1e18;
int n, q, k;
vector<vector<pair<int, LL> > > adj;
VL dijkstra(int start)
{
	VL dist(n, INF);
	priority_queue<pair<LL, int> > pq;

	dist[start] = 0;
	pq.push({0ll, start});
	while(pq.empty() == false)
	{
		LL cost = -pq.top().first; int here = pq.top().second;
		pq.pop();
		if(dist[here] < cost) continue;

		for(auto pr : adj[here])
		{
			int there = pr.first;
			LL nextDist = cost + pr.second;
			if(nextDist < dist[there])
			{
				dist[there] = nextDist;
				pq.push({-nextDist, there});
			}
		}
	}
	return dist;
}
