typedef long long ll;

struct edge{
  int to;
  ll cost;
};
typedef pair<int, int> P;
const ll INF = 1e15;
const int MAX_V = 1e5+1;

vector<edge> G[MAX_V];
ll d[MAX_V];
int V;

void dijkstra(int s){
  priority_queue<P, vector<P>, greater<P>> que;
  rep(i, V+1) d[i] = INF;
  d[s] = 0;
  que.push(P(0, s));
  while(!que.empty()){
    P p = que.top();
    que.pop();
    int v = p.second;
    if(d[v] < p.first) continue;
    rep(i, G[v].size()){
      edge e = G[v][i];
      if(d[e.to] > d[v] + e.cost){
        d[e.to] = d[v] + e.cost;
        que.push(P(d[e.to], e.to));
      }
    }
  }
}

int main(){
  cin >> V;
  rep(i, V-1){
    int a, b;
    ll c;
    cin >> a >> b >> c;
    edge e1, e2;
    e1.to = b, e1.cost = c, e2.to = a, e2.cost = c;
    G[a].push_back(e1), G[b].push_back(e2);
  }
  int k, q;
  cin >> q >> k;
  ll ans[q];
  dijkstra(k);
  rep(i, q){
    int x, y;
    cin >> x >> y;
    ans[i] = d[x] + d[y];
  }
  rep(i, q) cout << ans[i] << endl;
  return 0;
}

