template <typename T>
struct edge {
    ll src, to;
    T cost;

    edge(ll to, T cost) : src(-1), to(to), cost(cost) {}

    edge(ll src, ll to, T cost) : src(src), to(to), cost(cost) {}

    edge &operator=(const ll &x) {
        to = x;
        return *this;
    }

    operator ll() const { return to; }
};

template <typename T>
using Edges = vector<edge<T>>;
template <typename T>
using WeightedGraph = vector<Edges<T>>;
using UnWeightedGraph = vector<vector<ll>>;
template <typename T>
using Matrix = vector<vector<T>>;

template <typename T>
vector<T> dijkstra(WeightedGraph<T> &g, ll s) {
    const auto INF = numeric_limits<T>::max();
    vector<T> dist(g.size(), INF);

    using Pi = pair<T, ll>;
    priority_queue<Pi, vector<Pi>, greater<Pi>> que;
    dist[s] = 0;
    que.emplace(dist[s], s);
    while (!que.empty()) {
        T cost;
        ll idx;
        tie(cost, idx) = que.top();
        que.pop();
        if (dist[idx] < cost) continue;
        for (auto &e : g[idx]) {
            auto next_cost = cost + e.cost;
            if (dist[e.to] <= next_cost) continue;
            dist[e.to] = next_cost;
            que.emplace(dist[e.to], e.to);
        }
    }
    return dist;
}

int main() {
    ll N;
    cin >> N;
    WeightedGraph<ll> g(N);
    for (ll i = 1; i < N; i++) {
        ll a, b, c;
        cin >> a >> b >> c;
        g[a - 1].emplace_back(b - 1, c);
        g[b - 1].emplace_back(a - 1, c);
    }
    ll Q, K;
    cin >> Q >> K;
    vector<ll> ans;
    vector<ll> v = dijkstra(g, K - 1);
    for (ll i = 0; i < Q; i++) {
        ll x, y;
        cin >> x >> y;
        ans.push_back(v[x - 1] + v[y - 1]);
    }
    for (auto &i : ans) {
        cout << i << endl;
    }
}

