struct Edge {
  int t;
  ll cost;
};

int dp[20][200001];
ll cost[200001];
ll depth[200001];

void dfs(int v, int p, vector<vector<Edge>> &G, ll c, int d) {
  cost[v] = c;
  depth[v] = d;
  for(int i = 0; i < G[v].size(); i++) {
    if (G[v][i].t == p) continue;
    dp[0][G[v][i].t] = v;
    dfs(G[v][i].t, v, G, c + G[v][i].cost, d + 1);
  }
}

int lca(int a, int b) {
  if (depth[a] < depth[b]) {
    int diff = depth[b] - depth[a];
    for(int i = 0; i < 20; i++) {
      if (diff >> i & 1) {
        b = dp[i][b];
      }
    }
  }
  if (depth[b] < depth[a]) {
    int diff = depth[a] - depth[b];
    for(int i = 0; i < 20; i++) {
      if (diff >> i & 1) {
        a = dp[i][a];
      }
    }
  }
  if (a == b) return a;

  for(int i = 19; i >= 0; i--) {
    if (dp[i][a] != dp[i][b]) {
      a = dp[i][a];
      b = dp[i][b];
    }
  }
  return dp[0][a];
}

void solve() {
  int N;
  cin >> N;
  vector<vector<Edge>> G(N);
  for (int i = 0; i < N - 1; i++) {
    int a, b, c;
    cin >> a >> b >> c;
    a--, b--;
    G[a].push_back({b, c});
    G[b].push_back({a, c});
  }

  int Q, K;
  cin >> Q >> K;
  K--;

  dp[0][K] = K;
  dfs(K, -1, G, 0, 0);

  for(int i = 0; i < 19; i++) {
    for(int j = 0; j < N; j++) {
      dp[i + 1][j] = dp[i][dp[i][j]];
    }
  }

  for (int i = 0; i < Q; i++) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    // int c = lca(x, y);
    // cout << c << endl;
    cout << depth[x] + depth[y] << endl;
  }
}

int main() {
  std::cin.tie(0);
