long long init(long long root,long long dep){
	long long t=v[root];
	depth[root]=dep;
	while(e[t].to==fa[root]) t=e[t].next;
	while(t){
		if(e[t].to!=fa[root]){
			fa[e[t].to]=root;
			s[e[t].to]=s[root]+e[t].w;
			init(e[t].to,dep+1);	
		}
		t=e[t].next; 
	}
}
long long lca(long long a,long long b){
	long long p1=a,p2=b;
	long long j1,j2;
	if(depth[a]>depth[b]){
		j1=a;j2=b;
	}else j1=b,j2=a;

			//get to the same depth
			while(depth[j1]!=depth[j2]){
				j1=fa[j1];
			}
			while(j1!=j2){
				j1=fa[j1];
				j2=fa[j2];
			}
			long long lca=j1;
			return s[p1]-s[lca]+s[p2]-s[lca];
}
 
 
