    add_edge(g, b[i] - 1, a[i] - 1, c[i]);
  }
  auto dist = dijkstra(g, K - 1);
  REP(i,Q) {
    int s = x[i] - 1, t = y[i] - 1;
    cout << dist[s] + dist[t] << endl;
  }
}

