class DIJKSTRA {

  typedef long long ll;
  typedef std::pair<ll,ll> P;
  struct Edge { ll to; ll cost; };

  private:
    std::vector<std::vector<Edge>> G; // j-th Edge connected with vertex i : G[i][j]
    std::vector<ll> D;  // result
    std::vector<ll> C;  // # of paths
    bool directed;

  public:
    DIJKSTRA ( ll N , bool dir = false ) : directed (dir) {
      G.resize(N);
      D.assign(N, std::numeric_limits<ll>::max());
      C.assign(N, 0);
    }

    void Path ( ll i, ll j, ll x ) {
      G[i].push_back( {j,x} );
      if ( !directed ) G[j].push_back( {i,x} );
    }

    void Run (ll start) {
      std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
      pq.push( P(0, start) );
      D[start] = 0;
      C[start] = 1;
      while( !pq.empty() ) {
        auto cur = pq.top(); pq.pop();
        int d = cur.first;
        int v = cur.second;
        if ( D[v] < d ) continue;
        for(auto&& e : G[v]) {
          if ( D[e.to] > D[v] + e.cost ) {
            D[e.to] = D[v] + e.cost;
            pq.push( P(D[e.to], e.to) );
            C[e.to] = C[v];
          }
          else if ( D[e.to] == D[v] + e.cost ) C[e.to] += C[v];
        }
      }
      return;
    }

    ll Get ( ll i ){ return D[i]; }

    ll GetPaths ( ll i ) { return C[i]; }
};


int main (void) {
  std::cin.tie(0);  std::ios::sync_with_stdio(false);
  ll N; std::cin >> N;
  DIJKSTRA dij(N, false);
  rep(i,N-1) {
    ll a,b,c; std::cin >> a >> b >> c; a--,b--;
    dij.Path(a,b,c);
  }

  ll Q, K; std::cin >> Q >> K; K--;
  std::vector<ll> ans(Q);
  dij.Run(K);
  rep(i,Q) {
    ll x,y; std::cin >> x >> y; x--,y--;
    ans[i] = dij.Get(x) + dij.Get(y);
  }

  rep(i,Q) std::cout << ans[i] << std::endl;

  return 0;
}

