const ll INF = 1e15;
const int max_n = 1e6;

int n;
vector<edge> g[max_n];
ll d[max_n];

void dijkstra(ll s){
	fill(d, d + n, INF);
	d[s] = 0;

	priority_queue<P,vector<P>,greater<P> > que;
	que.push(P(0,s));

	while(!que.empty()){
		P p = que.top();
		que.pop();

		ll v = p.second;
		if(d[v] < p.first) continue; //後から最短パスが見つかった場合、先にqueに入っているものはここではじかれる

		for(ll i = 0; i < g[v].size(); i++){
			edge e= g[v][i];
			if(d[e.to] > d[v] + e.cost){
				d[e.to] = d[v] + e.cost;
				que.push(P(d[e.to], e.to));
			}
		}
	}
}

