using pii = pair<int, int>;

class Node{
  public:
    long cost;
    int from;
    int to;

    Node(int to, int from, long cost){
      this -> cost = cost;
      this -> from = from;
      this -> to = to;
    }
};

struct Comparator{
  bool operator()(const Node& a, const Node& b){
    return a.cost > b.cost;
  }
};

typedef pair<int, int> pii;
typedef vector<pii> ad;

long solve(int x, int y, ad *ads, int n, long *kresult){
  priority_queue<Node, vector<Node>, Comparator> pque;
  bool visited[n + 1];
  rep(i, n + 1){
    visited[i] = false;
  }
  visited[x] = true;

  long ends[n + 1];
  rep(i, n + 1) ends[i] = 0;

  while(true){
    for(pii edge: ads[x]){
      pque.push(Node(x, edge.first, edge.second));
    }

    Node target(0, 0, 0);
    while(not pque.empty()){
      target = pque.top();
      pque.pop();
      if(not visited[target.from]){
        goto WHILE_ELSE;
      }
    }

    return -1;
WHILE_ELSE:
    ends[target.from] += ends[target.to] + target.cost;
    x = target.from;

    if(x == y) {
      return ends[y];
    }
    visited[x] = true;
  }
}

