  long kresult[n + 1];
  FOR(i, 1, n + 1){
    kresult[i] = solve(k, i, ads, n, kresult);
  }
  rep(i, q){
    int x, y;
    cin >> x >> y;

    cout << kresult[x] + kresult[y] << endl;
  }
}

