using int64 = long long;
using pii = pair<int64, int64>;
using Graph = vector<vector<pii>>;
constexpr int64 INIT_VAL = 1e18;

vector<int64> dijkstra(Graph &G, int s)
{
    int N = G.size();
    vector<int64> d(N, INIT_VAL);
    d[s] = 0;

    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push(pii(0, s));

    while (!pq.empty()) {
        pii p = pq.top(); pq.pop();
        int v = p.second;

        if (d[v] < p.first) {
            continue;
        }

        for (pii np : G[v]) {
            int nv = np.first;
            if (d[v] + np.second < d[nv]) {
                d[nv] = d[v] + np.second;
                pq.push(pii(d[nv], nv));
            }           
        }
    }
    return d;
}

