    g[a].emplace_back(b, c);
    g[b].emplace_back(a, c);
  }
  ll Q, K;
  cin >> Q >> K;
  K--;
  vector<ll> dist = search(K, g);
  ll x, y;
  for (int i = 0; i < Q; i++) {
    cin >> x >> y;
