    while(a != b)
    {
        lli& x = to_root[a] > to_root[b] ? a : b;

        assert(x != root);

        lli p = tree[x];

        len += edges[{x, p}];

        if(p != root && g[p].size() == 1)
        {
            lli pp = tree[p];

            len += edges[{p, pp}];

            edges[{x, pp}] = edges[{x, p}] + edges[{p, pp}];

            tree[x] = pp;

            p = pp;
        }

        x = p;
    }

    if(same) len = len0;

    return {len, a};
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;

    g = vvvi(n + 1);

    for(int i = 0; i < n - 1; i++)
    {
        int a, b, c; cin >> a >> b >> c;

        g[a].push_back({b, c});
        g[b].push_back({a, c});

        edges[{a, b}] = c;
        edges[{b, a}] = c;
    }

    cin >> q >> root;

    tree = vi(n + 1);
    tree[root] = root;

    vid = vi(n + 1);
    to_root = vi(n + 1);

    vid[root] = ++id;

    hang(g, root);

    for(int i = 0; i < q; i++)
    {
        int a, b; cin >> a >> b;

        lli len, anc;

        auto pr = find_anc(a, b);

        len = pr.first;
        anc = pr.second;

        len += to_root[anc] * 2;

        cout << len << '\n';
    }

    return 0;
}

