void serch(long long int X,long long int Y,long long int Z,long long int U) {
	if (X == Y) {
		E = min(E, Z);
		return;
	}
	if (Z >= E)return;

	for (int i = 0; i < (int)G[X].size(); i++) {
		if (U == G[X][i].first)goto go;;
		serch(G[X][i].first, Y, Z + G[X][i].second,X);
	go:;
	}
	return;
}

