#define NMAX (100001)
#define INF (100000000000000)
vector<pair<ll, int> > G[NMAX];
ll cost[NMAX];
bool done[NMAX] = { false };
ll ans[NMAX] = { 0 };

void dijkstra(int root)
{
	priority_queue<pair<ll, int>, vector<pair<ll, int> >, greater<pair<ll, int> > > PQ;
	pair<ll, int> current;	/* first: cost, second: index */
	ll next_cost;
	int current_index, next_index;

	rep(i, NMAX) cost[i] = INF;

	cost[root] = 0;
	PQ.push(make_pair(0, root));

	while (!PQ.empty()) {
		current = PQ.top();
		PQ.pop();

		current_index = current.second;

		if (done[current_index]) continue;
		done[current_index] = true;

		rep(i, G[current_index].size()) {
			next_index = G[current_index][i].second;
			next_cost = G[current_index][i].first;

			if ((!done[next_index])
				&& (cost[next_index] > cost[current_index] + (ll)next_cost)) {
				cost[next_index] = cost[current_index] + (ll)next_cost;
				PQ.push(make_pair(cost[next_index], next_index));
			}
		}
	}
}

