    for(int i = 0; i < n - 1; ++i){
        int a, b, c;
        cin >> a >> b >> c;
        --a, --b;
        graph[a].emplace_back(b, c);
        graph[b].emplace_back(a, c);
    }
    CostLCA<ll> lca(graph);
    lca.build();
