using ll = long long;
using Edge = struct { ll to, cost; };
bool operator<(const Edge &e1, const Edge &e2) {
  return (e1.cost != e2.cost) ? e1.cost > e2.cost : e1.to < e2.to;
}
template<class E>
using Graph = vector<vector<E>>;

struct Dijkstra {
  vector<ll> d;
  const ll INF = 1e15;
  template<class E>
    Dijkstra(const Graph<E> &G, ll s) {
      int N = G.size();
      priority_queue<Edge> pq;
      d.assign(N, INF); d[s] = 0;
      pq.push({s, 0});
      while (!pq.empty()) {
        Edge e = pq.top(); pq.pop();
        ll u = e.to;
        if (d[u] < e.cost) continue;
        for (auto&& v : G[u]) {
          if (d[v.to] > d[u] + v.cost) {
            d[v.to] = d[u] + v.cost;
            pq.push({v.to, d[v.to]});
          }
        }
      }
    }
};

int main() {
  int N; cin >> N;
  Graph<Edge> G(N);
  for (int i = 0; i < N - 1; ++i) {
    ll a, b, c; cin >> a >> b >> c;
    --a; --b;
    G[a].push_back({b, c});
    G[b].push_back({a, c});
  }
  ll Q, K; cin >> Q >> K;
  --K;
  Dijkstra dijkstra(G, K);
  while (Q--) {
    ll x, y; cin >> x >> y;
    --x; --y;
    cout << dijkstra.d[x] + dijkstra.d[y] << endl;
  }
  return 0;
}

