    vector<vector<int64_t>> cost(N, vector<int64_t>(N, INF));
    for (int64_t i = 0, a, b, c; i < N - 1; i++) {
        cin >> a >> b >> c;
        cost[a - 1][b - 1] = cost[b - 1][a - 1] = c;
    }
    cin >> Q >> K;
    vector<bool> visited(N, false);
    vector<int64_t> dis(N, 0);
    queue<int64_t> q;
    visited[K - 1] = true;
