using Edge = pair<ll,ll>;  //　1つ目は結んでいるノード、2つ目はその辺の重みを指す
using Graph = vector<vector<Edge> >;  //隣接リスト

void dijkstra(const Graph &G, vl &dist, ll s){  // sを始点とする最短経路
  priority_queue<Pair, vector<Pair>, greater<Pair> > que; //secondが頂点、firstがその頂点への暫定最小コストを表す
  dist[s] = 0;  //sへの距離は0

  que.emplace(0, s);

  while(!que.empty()){
    Pair p = que.top(); //キューから辺を取り出す
    que.pop(); //取り出した辺は破棄
    ll v = p.second;  
    if(dist[v] < p.first) continue; //辺の行き先の距離が辺のコスト未満なら、そのまま
    for(auto e : G[v]){  //頂点vから出る各辺について
      if(dist[e.first] > dist[v] + e.second){  //辺Eを通るとコストが改善される場合
        dist[e.first] = dist[v] + e.second;  //更新
        que.emplace(Pair(dist[e.first], e.first));  //キューにその頂点を格納
      }
    }
  }
}

