const int M=100005;

ll mp[M/7][M/7],pre[M],dis[M];
bool vis[M];
void dijkstra(int n,int s)
{
    int min,i,j,k;
    // 初始化源点 
    for(i=1;i<=n;i++){
    	vis[i]=false;
    	if(i!=s) {
    		dis[i]=mp[s][i];
    		pre[i]=s;
		}
	}
    dis[s] = 0;
    vis[s] = true;
    for(i=1;i<=n-1;i++) {
		min=inf;
		k=0;
		for(j=1;j<=n;j++){
			if(!vis[j] && dis[j]<min) {
				min=dis[j];
				k=j;
			}
		}
		if(k==0)break;
		vis[k]=true;
		for(j=1;j<=n;j++) {
			if(!vis[j] && mp[k][j]!=inf && dis[j]>dis[k]+mp[k][j] ) {
				dis[j]=dis[k]+mp[k][j];
				pre[j]=k;
			}
		}
	}
}

void init(int N) {
	for(int i = 1; i <= N; ++i)
        for(int j = 1; j <= N; ++j)
            mp[i][j] = inf;
    memset(dis,inf,sizeof(dis));
    memset(pre,0,sizeof(pre));
}

