#define NCONS 100001

using namespace std;
int N, Q, K;
vector<ll> adj[NCONS];
vector<ll> cost[NCONS];
bool visited[NCONS];
ll dist[NCONS];
int indegree[NCONS];
int leaf_idx;

void set_leaf_idx()
{
	for (int i = 1; i <= N; i++)
		if (indegree[i] == 1)
		{
			leaf_idx = i;
			return;
		}
}

void set_dist(int cur, ll len)
{
	visited[cur] = true;
	dist[cur] = len;
	for (int i = 0; i < adj[cur].size(); i++)
	{
		auto next = adj[cur][i];
		auto next_cost = cost[cur][i];
		if (visited[next]) continue;
		set_dist(next, len + next_cost);
	}
}

ll get_dist(int x, int y)
{
	ll ret = dist[x] - dist[y];
	if (ret >= 0)
		return ret;
	else
		return -ret;
}

ll query(int x, int y)
{
	ll ret = 0;
	auto dxy = get_dist(x, y);
	auto dxk = get_dist(x, K);
	auto dky = get_dist(K, y);
	if (dxk + dky == dxy)
		ret = dxy;
	else
		ret = dxy + 2 * dxk;
	return ret;
}

int main(void)
{
	cin.tie(NULL); ios_base::sync_with_stdio(false);
	cin >> N;
	for (int i = 0; i < N - 1; i++)
	{
		ll a, b, c; cin >> a >> b >> c;
		adj[a].push_back(b);
		adj[b].push_back(a);
		cost[a].push_back(c);
		cost[b].push_back(c);
		indegree[a] += 1;
		indegree[b] += 1;
	}
	set_leaf_idx();
	set_dist(leaf_idx, 0);
	cin >> Q >> K;
	for (int i = 0; i < Q; i++)
	{
		int x, y; cin >> x >> y;
		cout << query(x, y) << endl;
	}
	return 0;
}

