#define p pair<ll, int>
using namespace std;
const int SIZE = 100005;
const ll INF = 1e18;

struct Edge {
    int to;
    ll cost;
};

ll dist[SIZE];
bool used[SIZE];
vector<Edge> g[SIZE];

void solve(int s) {
    for (int i = 0; i < SIZE; i++) {
        dist[i] = INF;
        used[i] = false;
    }
    dist[s] = 0;
    priority_queue<p, vector<p>, greater<p>> que;
    que.push(p(0, s));
    while (!que.empty()) {
        p cur = que.top();
        que.pop();
        int v = cur.second;
        used[v] = true;
        if (dist[v] < cur.first) continue;
        for (int i = 0; i < g[v].size(); i++) {
            Edge e = g[v][i];
            if (!used[e.to] && dist[e.to] > dist[v] + e.cost) {
                dist[e.to] = dist[v] + e.cost;
                que.push(p(dist[e.to], e.to));
            }
        }
    }
}
int main() {
    int n, q, k;
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        ll c;
        cin >> a >> b >> c;
        g[a - 1].push_back((Edge){b - 1, c});
        g[b - 1].push_back((Edge){a - 1, c});
    }
    cin >> q >> k;
    solve(k - 1);
    for (int i = 0; i < q; i++) {
        int x, y;
        cin >> x >> y;
        cout << dist[x - 1] + dist[y - 1] << endl;
    }
    return 0;
}

