int N,Q,K;
vector<vector<pair<int,int>>> G; // グラフ
vector<ll> Dis; // 頂点Kからの距離
vector<bool> seen;

void dfs(int v){
  seen.at(v) = true;
  for (auto p : G.at(v)){
    auto nv = p.first;
    auto distance = p.second;
    if (seen.at(nv)) continue; // 既に訪れていればスキップ
    Dis.at(nv) = Dis.at(v) + distance;
    dfs(nv);
  }
}

