    G.at(b).push_back(make_pair(a,c));
  }
  cin >>Q >>K;

  seen.assign(N, false);
  Dis.assign(N, -1);
  K--;
  Dis.at(K) = 0;
  dfs(K);

  rep(i, Q){
    int a,b; cin >>a >>b;
    a--; b--;
    cout <<Dis.at(a) + Dis.at(b) <<endl;
  }
