using namespace std;

const int maxn = 1e5 + 10;
const long long inf = 0x7fffffffffffffff;

struct Edge {
	int to;
	long long len;
	Edge(int to, long long len) : to(to), len(len) {}
	bool operator < (const Edge &r) const
	{
		return len > r.len;
	}
};

vector<Edge> edge[maxn];
int n;
long long dist[maxn];

void dij(int k)
{
	bool vis[maxn] = {};
	for (int i = 0; i <= n; i++)
		dist[i] = inf;
	priority_queue<Edge> que;

	dist[k] = 0;
	que.push(Edge(k, 0));

	while (!que.empty()) {
		Edge tmp = que.top();
		que.pop();
		int u = tmp.to;
		if (vis[u])
			continue;
		vis[u] = true;
		for (int i = 0; i < edge[u].size(); i++) {
			int to = edge[u][i].to;
			long long len = edge[u][i].len;
			if (!vis[to] && dist[to] > dist[u] + len) {
				dist[to] = dist[u] + len;
				que.push(Edge(to, dist[to]));
			}
		}
	}

}

