		edge[a].push_back(Edge(b, c));
		edge[b].push_back(Edge(a, c));
	}
	int q, k;
	scanf("%d %d", &q, &k);
	dij(k);
	for (int i = 0; i < q; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		printf("%lld\n", dist[a] + dist[b]);
	}
	return 0;
}

