    q.emplace(s);
    vector<ll> memo(N, 0);
    while (!q.empty()) {
        int i = q.front(); q.pop();
        if (i == g)return memo[i];
        for (auto&& x : G[i]) {
            if (memo[x.first] != 0)continue;
            memo[x.first] = memo[i] + x.second;
            q.emplace(x.first);
        }
    }
    return 0LL;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    cin >> N;
    G.resize(N);
    REP(i, N - 1) {
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        G[a].emplace_back(b, c);
        G[b].emplace_back(a, c);
    }

    int Q;
    cin >> Q >> K;
    K--;
    vector<ll> length(N);
    REP(i, N) {
        length[i] = bfs(i, K);
    }
    vector<pair<int, int>> query(Q);
    REP(i, Q) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        query[i] = { x,y };
    }

    REP(i, Q) {
        cout << length[query[i].first] + length[query[i].second] << endl;
    }

    return 0;
}

