//前向星+SPFA
/*
edeg[]: 邻接表
dis[]: 最短路数组
vis[]: 出入队标记数组
cnt[]: 入队次数统计
head[u]:表示起点为u的最后一条边的标号，如果是-1表示没有以u为起点的边
init::初始化边
add::(u起点, v终点, w权值)
spfa::(s起点，n点数)[-1存在负环，反之为到点n最短路权值]

*/
#include<cstdio>
#include<string.h>
#include<algorithm>
#include<iostream>
#include<vector>
#include<queue>
#include<cmath>
#define ll long long
#define maxn 11000
#define INF 9123372036854775807
using namespace std;
int N;
struct Edge
{
	int to;
	int next;//表示和该边有共同起点的上一条边的标号
	int val;
}edge[100010];
int tot;
int head[maxn];
ll dis[maxn][maxn];
int vis[maxn];
int cnt[maxn];
void init()
{
	tot=0;
	memset(head,-1,sizeof(head));
}
void add(int u,int v,int w)
{
	edge[tot].to=v;
	edge[tot].val=w;
	edge[tot].next=head[u];
	head[u]=tot++;
}
void spfa(int s)
{
	memset(cnt,0,sizeof(cnt));
	memset(vis,0,sizeof(vis));
	queue<int> q;
	for(int i=1;i<=N;i++)
	{
		vis[i]=0;
		cnt[i]=0;
		dis[s][i]=INF;
	}
	vis[s]=1;
	dis[s][s]=0;
	q.push(s);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		vis[u]=0;
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].val;
			if(dis[s][u]+w<dis[s][v])
			{
				dis[s][v]=dis[s][u]+w;
				if(!vis[v])
				{
					vis[v]=1;

					q.push(v);
				}
			}
		}
	}
	//默认返回最后一个点最短距离，可更改
}
int main()
{
	cin>>N;
	init();
	for(int i=1;i<N;i++)
	{
		int a,b,c;
		cin>>a>>b>>c;
		add(a,b,c);
		add(b,a,c);
	}


	int Q,K;

	cin>>Q>>K;
	spfa(K);
	for(int i=1;i<=Q;i++)
	{
		int x,y;
		cin>>x>>y;
		cout<<dis[K][y]+dis[K][x]<<endl; 
	}
	return 0;
}

