ll d[100010];
void dijkstra(int s) {
	priority_queue<P, vector<P>, greater<P>> que;
	fill(d, d + 100010, INF);
	d[s] = 0;
	que.push(P(0, s));
	while (!que.empty()) {
		P p = que.top(); que.pop();
		ll v = p.second;
		if (d[v] < p.first)continue;
		for (int i = 0; i < f[v].size(); i++) {
			edge e = f[v][i];
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(make_pair(d[e.to], e.to));
			}
		}
	}
}
