using namespace std;

struct road{
    int goal;
    long cost;
};

vector<vector<road>> roads;
vector<long> K_distance;

void find_distance(int now, long cost_all){
    if(K_distance[now] == -1){
        K_distance[now] = cost_all;
        for(int i = 0; i < roads[now].size(); i++){
            find_distance(roads[now][i].goal, cost_all + roads[now][i].cost);
        }
    }
}

int main(){
    int N;
    cin >> N;
    roads.resize(N);
    for(int i = 0; i < N - 1; i++){
        int start, goal;
        long cost;
        cin >> start >> goal >> cost;
        roads[start - 1].push_back({goal - 1, cost});
        roads[goal - 1].push_back({start - 1, cost});
    }
    int Q, K;
    cin >> Q >> K;
    K_distance.resize(N);
    fill(K_distance.begin(), K_distance.end(), -1);
    find_distance(K - 1, 0);
    for(int i = 0; i < Q; i++){
        int start, goal;
        cin >> start >> goal;
        cout << K_distance[start - 1] + K_distance[goal - 1] << endl;
    }
}

