// 現在位置 i から dest までの最短経路を深さ優先探索
long dfs( int i, int dest, int parent, long d, vector<edge>* V )
{
    if( i == dest ) return d;
    long ans = LONG_MAX;
    for( auto &e: V[i] ){
        if( e.to == parent ) continue;
        ans = min( ans, dfs( e.to, dest, i, d+e.length, V ) );
    }
    return ans;
}


