vector<ll> dijkstra ( int a, vector<vector<edge>> &g, int n ) {
    vector<ll> cost(n, 1e18);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
    cost[a] = 0;
    que.push({0, a});
    while(!que.empty()) {
        pair<ll, int> now = que.top(); que.pop();
        ll now_cost = now.first;
        int now_p = now.second;
        if ( now_cost > cost[now_p] ) continue;
        for ( auto tmp_num : g[now_p] ) {
            if ( cost[now_p] + tmp_num.cost < cost[tmp_num.to] ) {
                cost[tmp_num.to] = cost[now_p] + tmp_num.cost;
                que.push({cost[tmp_num.to], tmp_num.to});
            }
        }
    }
    return cost;
}   

