long solve(int x, int y, ad *ads, int n){
  int ox = x;
  int oy = y;
  priority_queue<Node, vector<Node>, Comparator> pque;
  bool visited[n + 1];
  rep(i, n + 1){
    visited[i] = false;
  }
  visited[x] = true;

  pii ends[n + 1];

  while(true){
    for(pii edge: ads[x]){
      pque.push(Node(x, edge.first, edge.second));
    }

    Node target(0, 0, 0);
    while(not pque.empty()){
      target = pque.top();
      pque.pop();
      if(not visited[target.from]){
        goto WHILE_ELSE;
      }
    }

    return -1;
WHILE_ELSE:
    ends[target.from] = make_pair(target.to, target.cost);
    x = target.from;
    if(x == oy) {
      long sum_cost = 0;
      for(pii e : ends){
      }
      while(y != ox){
        sum_cost += ends[y].second;
        y = ends[y].first;
      }
      return sum_cost;
    }
    visited[x] = true;
  }
}

