vector<ll> dijkstra(const Graph &g, int s) {
  vector<ll> d(g.size(), INF);
  d[s] = 0;
  priority_queue<PLL, vector<PLL>, greater<PLL>> que;
  que.push(PLL(0, s));
  while(!que.empty()) {
    ll dist = que.top().F;
    ll v= que.top().S;
    que.pop();
    if(d[v] < dist) continue;
    for(const auto &e : g[v]) {
      if(d[e.to] <= d[v] + e.cost) continue;
      d[e.to] = d[v] + e.cost;
      que.push(PLL(d[e.to], e.to));
    }
  }
  return d;
}


