void Init()
{
    for(int i=0; i<n; i++)
        G[i].clear();
    edges.clear();
}
struct Heap
{
    int d,u;
    Heap(int a,int b)
    {
        d=a,u=b;
    }
    bool operator<(Heap h)const
    {
        return d>h.d;
    }
};
void Dijkstra(int s)
{
    priority_queue<Heap> p;
    p.push(Heap(0,s));
    for(int i=0; i<=n; i++) dis[i]=INF;
    dis[s]=0;
    memset(vis,0,sizeof(vis));
    while(!p.empty())
    {
        Heap h=p.top();
        p.pop();
        int  u=h.u;
        if(vis[u]) continue;
        for(int i=0; i<G[u].size(); i++)
        {
            Edge &e=edges[G[u][i]];
            if(vis[e.to]) continue;
            if(dis[e.to]>dis[u]+e.cost)
            {
                dis[e.to]=dis[u]+e.cost;
                p.push(Heap(dis[e.to],e.to));
            }
        }
    }
}
