void dijkstra(ll s){
  priority_queue<pint,vector<pint>,greater<pint>> que;
  fill(dist,dist+n,INF);
  dist[s]=0;
  que.push(pint(0,s));
  while(!que.empty()){
    auto p=que.top();que.pop();
    ll v=p.second;
    if(dist[v]<p.first) continue;
    for(auto e:graph[v]){
      if(dist[e.to]>dist[v]+e.cost){
        dist[e.to]=dist[v]+e.cost;
        que.push(pint(dist[e.to],e.to));
      }
    }
  }
}
