typedef pair<int,int> P;
int V;
vector<edge> G[100005];
ll d[100005];

void di(int s){
    priority_queue<P, vector<P>, greater<P>> que;
    fill(d,d+V,linf);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()){
        P p = que.top();que.pop();
        int v = p.sd;
        if(d[v] < p.ft)continue;
        rep(i,0,sz(G[v])){
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost){
                 d[e.to]=d[v] + e.cost;
                 que.push(P(d[e.to],e.to));
            }
        }
    }
}
