void solve()
{
	int N = Ni();
	Graph G(N);
	REP(i, N - 1) {
		int a = Ni() - 1, b = Ni() - 1, c = Ni();
		G[a].emplace_back(a, b, c);
		G[b].emplace_back(b, a, c);
	}
	vl d(N, INF);
	int Q = Ni(), K = Ni() - 1;
	queue<pll> q;
	q.emplace(K, 0);
	while (!q.empty()) {
		auto p = q.front(); q.pop();
		d[p.first] = p.second;
		for (auto e : G[p.first]) if (d[e.to] == INF) {
			q.emplace(e.to, p.second + e.cost);
		}
	}
	REP(i, Q) {
		int x = Ni() - 1, y = Ni() - 1;
		O(d[x] + d[y]);
	}
}

