struct Graph {
    struct Edge {
        int from;
        int to;
        lint cost;
        int index;
        int color;
    };
    struct Node {
        int index;
        bool check;
        int color;
        lint dist;
        std::vector<Edge> edges;
        Node() {
            index = -1;
            check = false;
            color = -1;
            dist  = INF;
            std::vector<Edge>(0);
        }
    };

    int numNodes;
    int numColor;
    bool directed;
    std::vector<Node> nodes;
    std::vector<Edge> edges;

    Graph(int N) : numNodes(N), nodes(N) {
        for (int i = 0; i < N; i++)
            nodes[i].index = i;
        numColor = -1;
        directed = false;
    }
    Graph(int N, bool directed) : numNodes(N), nodes(N) {
        for (int i = 0; i < N; i++)
            nodes[i].index = i;
        numColor = -1;
        directed = true;
    }

    void addEdge(int from, int to, int cost) {
        nodes[from].edges.push_back(Edge({from, to, cost}));
        if (!directed) nodes[to].edges.push_back(Edge({to, from, cost}));
    }

    void addEdge(int from, int to) {
        nodes[from].edges.push_back(Edge({from, to}));
        if (!directed) nodes[to].edges.push_back(Edge({to, from}));
    }

    void bfs(int startIndex) {
        for (auto& node : nodes)
            node.dist = INF;
        nodes[startIndex].dist = 0;
        std::queue<int> que({startIndex});
        while (!que.empty()) {
            int currentIndex = que.front();
            que.pop();
            for (auto edge : nodes[currentIndex].edges) {
                if (nodes[edge.to].dist == INF) {
                    nodes[edge.to].dist = nodes[currentIndex].dist + edge.cost;
                    que.push(edge.to);
                }
            }
        }
    }

    void coloring() {
        int c = 0;
        for (auto& node : nodes) {
            if (node.color != -1) continue;
            node.color = c;
            std::queue<int> que({node.index});
            while (!que.empty()) {
                int currentIndex = que.front();
                for (auto edge : nodes[currentIndex].edges) {
                    if (nodes[edge.to].color != -1) continue;
                    nodes[edge.to].color = c;
                    que.push(nodes[edge.to].index);
                }
            }
            c++;
        }
        numColor = c;
    }
};
