const int maxn = 4e5+10;
struct edge{
	int to;
	long long weight;
	edge(int to,long long weight) : to(to),weight(weight){}
};
vector<edge>g[maxn];
int vs[maxn*2-1];//dfs访问顺序 
int depth[maxn*2-1];//节点深度 
int id[maxn];//各个顶点在vs中首次出现的下标 
long long dist[maxn];//节点到根结点的距离 
int bit[maxn*2-1][16];//RMQ的binaryindexdtree节点 
void rmq_init(int n)
{
	for(int i=0;i<n;i++)
	{
		bit[i][0] = i;
	}
	for(int j=1;(1<<j)<n;j++)
	{
		for(int i=0;i+(1<<j)-1<n;i++)
		{
			if(depth[bit[i][j-1]] <= depth[bit[i+(1<<(j-1))][j-1]])
			{
				bit[i][j] = bit[i][j-1];
			}
			else
			{
				bit[i][j] = bit[i+(1<<(j-1))][j-1];
			}
		}
	}
}
int query(int l,int r)
{
	int k = 0;
	while((1<<(k+1))<r-l+1)
		k++;
	if(depth[bit[l][k]] <= depth[bit[r-(1<<k)][k]])
	{
		return bit[l][k];
	}
	else
	{
		return bit[r-(1<<k)][k];
	}
}
void dfs(int v,int p,int d,int &k)
{
	id[v] = k;
	vs[k] = v;
	depth[k++] = d;
	for(int i=0;i<g[v].size();i++)
	{
		if(g[v][i].to != p)
		{
			dist[g[v][i].to] = dist[v] + g[v][i].weight;
			dfs(g[v][i].to,v,d+1,k);
			vs[k] = v;
			depth[k++] = d;
		}
	 } 
}
int init(int V)
{
	int k = 0,root = 0;
	dfs(root,-1,0,k);
	rmq_init(V*2-1);
}
int lca(int u,int v)
{
	return vs[query(min(id[u],id[v]),max(id[u],id[v])+1)];
}
void add_edge(int from,int to,int weight)
{
	g[from].push_back(edge(to,weight));
}
int main()
{

		int n,m;
		scanf("%d",&n);
		for(int i=1;i<n;i++)
		{
			int u,v;
			long long w;
			scanf("%d%d%lld",&u,&v,&w);
			--u,--v;
			add_edge(u,v,w);
			add_edge(v,u,w);
		}
		init(n);
		int q,k;
		scanf("%d%d",&q,&k);
		--k;
		for(int i=0;i<q;i++)
		{
			int u,v;
			scanf("%d%d",&u,&v);
			--u,--v;
			int f = lca(u,k);
			long long ans = dist[u]-dist[f]+dist[k]-dist[f];
			int ff = lca(k,v);
			long long ans2 = dist[k]-dist[ff]+dist[v]-dist[ff];
			cout<<ans+ans2<<endl;
		}

	return 0;
}

