typedef pair<int, ll> P;

class D {
	int n, q, k;
	vll d;
	vector<vector<P>> g;
	const int nul = INTMAX;
public:
	D()
	{
		cin >> n;
		d.resize(n + 1, nul);
		g.resize(n + 1);

		REP(i, n - 1)
		{
			int a, b;
			ll c;
			cin >> a >> b >> c;

			g[a].emplace_back(MP(b, c));
			g[b].emplace_back(MP(a, c));

		}

		cin >> q >> k;

	}

	void init()
	{
		d[k] = 0;

		deque<int> que;
		que.PB(k);

		while (!que.empty())
		{
			int cur = que.front(); que.pop_front();

			REP(i, SZ(g[cur]))
			{
				int nxt = g[cur][i].first;
				ll c = g[cur][i].second;

				if (d[nxt] == nul)
				{
					d[nxt] = d[cur] + c;
					que.PB(nxt);
				}
			}
		}

	}

	void solve()
	{

		init();
/*
		REP(i, n + 1)
			cout << d[i] << " ";
		cout << endl;
*/
		REP(i, q)
		{
			int x, y;
			cin >> x >> y;

			cout << d[x] + d[y] << endl;

		}

	}
};


int main()
{
	D solution;
	solution.solve();

	return 0;
}

