vector<edge> g[MAX_V];
vector<bool> check(MAX_V,false);
vector<ll> dis(MAX_V,INF);

//深さ優先探索を利用する
void dfs(int s){
    if(check[s])return;
    check[s] = true;
/*
現在iへの最小移動コスト
sへの最小移動コスト + s->iへの移動コストを比べる
*/
    rep(i,g[s].size()){
        if(dis[g[s][i].to] > g[s][i].c + dis[s]){
            dis[g[s][i].to] = g[s][i].c + dis[s];
            dfs(g[s][i].to);
        }
    }
}

