    dis[k] = 0;//初期値
    //dfsを使ってkから各頂点への距離を求めておく
    dfs(k);

    int x,y;
    rep(i,q){
        cin >> x >> y;
        x--;y--;
        cout << dis[x] + dis[y] << endl;
