typedef long long ll;
typedef std::pair<int, int> ipair;
const int MAX_V = 100010;
const int MAX_LOG_V = 17;
vector<ipair> G[MAX_V];
int parent[MAX_LOG_V][MAX_V];
int depth[MAX_V];
vector<int> eulerT;

class TREE {

   public:
      int k = 0;
      ll distance[MAX_V];
      int begin[MAX_V * 2];
      int end[MAX_V * 2];

      // vertex, parent, depth, distance
      void dfs(int v, int p, int d, ll l) {
         parent[0][v] = p;
         depth[v] = d;
         distance[v] = l;
         begin[v] = k;
         eulerT.push_back(v);
         k++;
         for (auto& g : G[v]) {
            if (g.first != p) {
               dfs(g.first, v, d + 1, l + g.second);
               eulerT.push_back(v);
               k++;
            }
         }
         end[v] = k;
      }

      void init(int V, int root) {
         dfs(root, -1, 0, 0);
         for (int k = 0; k + 1 < MAX_LOG_V; k++) {
            for (int v = 0; v < V; v++) {
               if (parent[k][v] < 0) parent[k + 1][v] = -1;
               else parent[k + 1][v] = parent[k][parent[k][v]];
            }
         }
      }

      int lca(int u, int v) {
         if (depth[u] > depth[v]) swap(u, v);
         for (int k = 0; k < MAX_LOG_V; k++) {
            // if k th digit of depth[v] - depth[u] is 1
            if ((depth[v] - depth[u]) >> k & 1) {
               v = parent[k][v];
            }
         }
         if (u == v) return u;
         for (int k = MAX_LOG_V - 1; k >= 0; k--) {
            if (parent[k][u] != parent[k][v]) {
               u = parent[k][u];
               v = parent[k][v];
            }
         }
         return parent[0][u];
      }
};

int main() {
   int N;
   cin >> N;
   int a, b, c;
   for (int i = 0; i < N - 1; i++) {
      cin >> a >> b >> c;
      a--;
      b--;
      G[a].push_back(ipair(b, c));
      G[b].push_back(ipair(a, c));
   }
   int Q, K;
   cin >> Q >> K;
   K--; 
   TREE tree;
   tree.init(N, K);

   int u, v;
   for (int q = 0; q < Q; q++) {
      cin >> u >> v;
      u--;
      v--;
      ll ans = 0;
      ans += tree.distance[u] + tree.distance[v];
      cout << ans << endl;
   }

   return 0;
}

