vector<pair<int,long long>> map[100001];


long long dist(int a, int b){
    queue<pair<int,pair<int,long long>>> q; //現在位置, {前位置, 距離}
    for(pair<int,long long> x : map[a]){
        q.push(make_pair(x.first,make_pair(a,x.second)));
        if(x.first==b) return x.second;
    }
    while(!q.empty()){
        pair<int,pair<int,long long>> t=q.front();
        q.pop();

        for(pair<int,long long> x : map[t.first]){
            if(x.first==t.second.first) continue;
            q.push(make_pair(x.first,make_pair(t.first,t.second.second+x.second)));
            if(x.first==b) return t.second.second+x.second;
        }
    }

    return -1;
}

