class Tree {
	using T = pair<ll, int>;
	int n;
	vector<vector<T>> edge;
	vector<ll> d;

public:
	Tree(int N) : n(N), edge(N), d(N, INT64_MAX) {}
	void add(int a, int b, ll c) {
		edge[a].emplace_back(c, b);
		edge[b].emplace_back(c, a);
	}
	void dijkstra(int k) {
		priority_queue<T, vector<T>, greater<T>> pq;
		pq.emplace(0, k);
		while (!pq.empty()) {
			ll c;
			int i;
			tie(c, i) = pq.top();
			pq.pop();
			if (c > d[i]) continue;
			d[i] = c;
			for (auto p : edge[i]) {
				ll x;
				int j;
				tie(x, j) = p;
				if (c + x < d[j]) {
					pq.emplace(c + x, j);
				}
			}
		}
	}
	ll distance(int i) {
		return d[i];
	}
};

