#define REP(i,n) FOR(i,0,n)

typedef long long ll;
typedef pair<ll, ll> P;

struct edge { ll to,cost; };

vector<ll> dijkstra(int V, int s, vector<vector<edge>> &G) {
  vector<ll> d(V,LLONG_MAX);d[s]=0;
  priority_queue<P,vector<P>,greater<P>> q;q.push({0,s});
  while (!q.empty()) {
    P p = q.top();q.pop();
    int v = p.second;
    if (d[v]<p.first) continue;
    for (edge e:G[v]) {
      if (d[e.to]>d[v]+e.cost) {
        d[e.to] = d[v]+e.cost;
        q.push({d[e.to],e.to});
      }
    }
  }
  return d;
}

int main() {
  int N;cin>>N;
  vector<vector<edge>> G(N);
  REP(i,N-1) {
    int a,b,c;cin>>a>>b>>c;
    a--;b--;
    G[a].push_back({b,c});
    G[b].push_back({a,c});
  }
  int Q,K;cin>>Q>>K;

  // ワーシャルフロイトは間に合わない（ON3）
  // なので単純にKからの距離を全部出して足し合わせる
  vector<ll> ds = dijkstra(N,K-1,G);
  REP(i,Q) {
    int x,y;cin>>x>>y;
    x--;y--;
    OUT(ds[x]+ds[y]);
  }

  return 0;
}

