int main() {
  int N;
  cin >> N;
  vector<vector<P>> G(N);
  rep(i,N-1) {
    int a, b; ll c;
    cin >> a >> b >> c;
    --a; --b;  // 0-indexed
    G[a].push_back(P(b,c));
    G[b].push_back(P(a,c));
  }

  int Q, K;
  cin >> Q >> K;
  --K;  // 0-indexed
  Graph query(Q, vector<int>(2));
  rep(i,Q) {
    int x, y;
    cin >> x >> y;
    --x; --y;  // 0-indexed
    query[i][0] = x; query[i][1] = y;
  }

  vector<ll> dist(N);  // distance from K
  queue<P> search;
  vector<bool> visited(N, false);
  dist[K] = 0;
  search.push(P(K,0));
  visited[K] = true;

  while(!search.empty()) {
    P v = search.front();
    search.pop();

    for (auto nv : G[v.first]) {
      if (visited[nv.first]) continue;  // obstruct backflow

      dist[nv.first] = dist[v.first] + nv.second;
      search.push(nv);
      visited[nv.first] = true;
    }
  }

  rep(i,Q) {
    int &x = query[i][0], &y = query[i][1];
    ll ans = dist[x] + dist[y];
    cout << ans << endl;
  }
  return 0;
}

