using namespace std;
typedef long long ll;
typedef pair<int, int> P;

const ll INF = 1LL << 60;

struct edge { ll cost, to; };
vector<edge> g[200100]; // 辺
ll dist[100100]; // 距離
vector<ll> prever; // どこから来たか
ll N; // 頂点の数

void dijkstra(ll s) {
    dist[s] = 0;
    prever = vector<ll>(N, -1);

    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        ll v = p.second;

        if (p.first > dist[v]) continue;
        // 次の頂点へ潜る
        for (int i = 0; i < g[v].size(); i++) {
            edge e = g[v][i];
            if (e.cost + dist[v] < dist[e.to]) {
                dist[e.to] = e.cost + dist[v];
                prever[e.to] = v;
                que.push(P(dist[e.to], e.to));
            }
        }
    }
}

int main() {
    cin >> N;

    rep(i, N - 1) {
        ll a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        g[a].push_back((edge){c, b});
        g[b].push_back((edge){c, a});

    }

    rep(i, N) dist[i] = INF;

    ll Q, K;
    cin >> Q >> K;
    K--;
    dijkstra(K);
    rep(i, Q) {
        ll x, y;
        cin >> x >> y;
        x--;
        y--;

        ll ans = 0;
        ans += dist[x];
        ans += dist[y];
        cout << ans << endl;
    }
}

