        edge[a].emplace(b, c);
        edge[b].emplace(a, c);
    }

    int problems, k;
    cin >> problems >> k;
    vector<long> kdistance(nodes + 1, MAXC);
    kdistance[k] = 0;

    for (auto&& itr : edge[k]) {
        finddist(itr.first, k, edge, kdistance);
    }

    for (int i = 0; i < problems; i++) {
        int x, y;
        cin >> x >> y;
        cout << kdistance[x] + kdistance[y] << endl;
    }
}

