template<typename T>
vector<T> dijkstra(const vector<vector<pair<int, T>>> &graph, int root) {
  using P = pair<T, int>;
  vector<T> dists(graph.size(), numeric_limits<T>::max());
  priority_queue<P, vector<P>, greater<P>> que;
  dists[root] = 0;
  que.emplace(dists[root], root);
  while (!que.empty()) {
    P x = que.top(); que.pop();
    if (dists[x.second] < x.first) continue;
    for (auto e : graph[x.second]) {
      if (dists[e.first] > dists[x.second] + e.second) {
        dists[e.first] = dists[x.second] + e.second;
        que.emplace(dists[e.first], e.first);
      }
    }
  }
  return dists;
}

