ll head[maxn];
ll d[maxn];

struct Edge {
	ll from, to, next;
   	ll dis;
} edge[maxn];

void add_edge(ll from, ll to, ll c){
	edge[++edge_num].next = head[from];
	edge[edge_num].from = from;
	edge[edge_num].to = to;
	edge[edge_num].dis = c;
	head[from] = edge_num;
}

bool vis[maxn];
void dfs(ll p){
	vis[p] = true;
	for (ll i = head[p]; i; i = edge[i].next){
		ll to = edge[i].to;
		if (vis[to]) continue;
		d[to] = d[p] + edge[i].dis;
		dfs(to);	
	}
}

