void spfa(int v0)
{
	int i;
	bool visited[maxnum];
	for(i = 1; i <= n; i++)
	{
		dist[i] = INF;
		visited[i] = false;
	/*	cout << dist[i] << endl;*/
	}
	queue<int>Q;
	Q.push(v0);
	visited[v0] = true;
	dist[v0] = 0;
	while(!Q.empty())
	{
		int u = Q.front();
		Q.pop();
		visited[u] = false;
		int k = first[u];
		while(k != -1)
		{
			int v = e[k].w;
