struct Tmp
{
public:
  int N, K;
  vector<vector<pair<int, int>>> tree;
  // vector<int> memo;
  vector<ll> distance;
  Tmp(int N)
  : N(N)
  , K()
  , tree(N)
  // , memo(N)
  , distance(N)
  {}

  void pre(int k) {
    K = k;
    rec(k, -1, 0);
  }

  void rec(int cur, int par, ll dis) {
    distance[cur] = dis;
    for (const auto& p : tree[cur]) {
      if (p.first != par) {
        rec(p.first, cur, dis + p.second);
      }
    }
  }

  ll operator() (int x, int y) {
    return distance[x] + distance[y];
  }
};

void solve(void)
{
  int N; cin >> N;
  Tmp t(N);
  for (int i = 0; i < N-1; ++i) {
    int a, b, c; cin >> a >> b >> c;
    --a; --b;
    t.tree[a].push_back({b, c});
    t.tree[b].push_back({a, c});
  }
  int Q, K; cin >> Q >> K;
  --K;
  t.pre(K);
  for (int _ = 0; _ < Q; ++_) {
    int x, y; cin >> x >> y;
    --x; --y;
    cout << t(x, y) << CRLF;
  }
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

