typedef pair<int , int> P;//<最短距離, 頂点番号>
#define MAX_V 100005
struct edge {int to; ll cost; };
ll V;//頂点数
vector<edge> G[MAX_V];
ll d[MAX_V];//頂点sからの最短距離

void dijkstra(int s) {
    //greater<P>を指定し.fsを小さい順に取り出す
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+V, INF);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.sc;
        if(d[v] < p.fs) continue;
        rep(i,G[v].size()) {
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    } 
}

int main() {
    cin >> V;
    rep(i, V - 1) {
        int a, b; ll c;
        cin >> a >> b >> c;
        a--; b--;
        edge e = {b, c};
        G[a].pub(e);
        edge f = {a, c};
        G[b].pub(f);
    }
    int Q, K; cin >> Q >> K; K--;

    dijkstra(K);

    rep(i,Q) {
        int x, y; cin >> x >> y; x--; y--;
        ll ans = d[x] + d[y];
        cout << ans << endl;
    }
    return 0;
}

#include <iostream>
