using namespace std;

typedef long long LL;

struct node {
  int id;
  LL cost;
  LL now_min;
};

int N, Q, K;
vector<node> all_nodes[100005];
LL min_to_vertex[100005];

void bfs(int s_vertex) {
  queue<node> search_queue;

  min_to_vertex[s_vertex] = 1;
  search_queue.push(node {s_vertex, 0, 1});

  while (!search_queue.empty()) {
    node now_node = search_queue.front();
    search_queue.pop();

    auto &neighbor = all_nodes[now_node.id];

    for(auto &n: neighbor) {
      if (!min_to_vertex[n.id]) {
	n.now_min = now_node.now_min + n.cost;
	min_to_vertex[n.id] = now_node.now_min + n.cost;
	search_queue.push(n);
      }
    }
  }
}

int main() {
  cin >> N;

  int a, b;
  LL c;
  for(int i = 0; i < N-1; i++) {
    cin >> a >> b >> c;

    all_nodes[a].push_back(node{b, c, 0});
    all_nodes[b].push_back(node{a, c, 0});
  }

  cin >> Q >> K;

  bfs(K);

  int x, y;
  for(int i = 0; i < Q; i++) {
    cin >> x >> y;

    cout << min_to_vertex[x] + min_to_vertex[y] - 2 << endl;
  }

  return 0;
}

