		lld s = e[p].size();
		for(int i = 0; i < s; i++)
		{
			if (dist[e[p][i].node] < 0)
			{
				dist[e[p][i].node] = dist[p] + e[p][i].cost;
				dfs(e[p][i].node);
			}
