    queue<int> que;

    // 初期条件 (頂点 K を初期ノードとする)
    dist[K] = 0;
    que.push(K); // K を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
