    else{
        int s3=lca(x,s);
        if(s3!=s){
            return dist(y,z)+2*dist(x,s);
        }
        else{
            if(s1!=s){
                return dist(y,z)+2*dist(x,s1);
            }
            else return dist(y,z)+2*dist(x,s2);
