class Ver{
public:
    map<ll, ll> children; // ver, distance
    ll idx;
    ll d;
    Ver(){};
    Ver(ll _idx){
        idx = _idx;
        children = map<ll, ll>();
        d = -1;
    }
    void addChildren(ll c, ll d){
        children.emplace(make_pair(c,d));
    }

    void calc(ll d_so_far, map<ll, Ver>& m){
        if(d > -1) return;
        this->d = d_so_far;
        FORMAP(it, this->children){
            m[it->ff].calc(this->d + children[it->ff], m);
        }
        return;
    }
};

map<ll, Ver> vex;

int main(){
    ll N; cin >> N;
    REP(i, N-1){
        ll a, b, c; cin >> a >> b >> c;
        if(vex.count(a) == 0){
            vex[a] = Ver(a);
        }
        if(vex.count(b) == 0)
        {
            vex[b] = Ver(b);
        }
        vex[a].addChildren(b, c);
        vex[b].addChildren(a, c);
    }
    ll Q, K; cin >> Q >> K;
    vex[K].calc(0, vex);

    REP(i, Q){
        ll x, y; cin >> x >> y;
        cout << vex[x].d + vex[y].d << endl;
    }
    return 0;
}

