static const int GRAY = 1;
static const int BLACK = 2;
int n;
static const int MAX = 100000;
vector<pair<ll, ll>> adj[MAX];

ll d[MAX];
ll p[MAX];
void dijkstra(int s) {
	priority_queue<pair<ll, ll>>PQ;
	int color[MAX];

	rep(i, n) {
		d[i] = INFTY;
		color[i] = WHITE;
		p[i] = 0;
	}

	d[s] = 0;
	p[s] = -1;
	PQ.push(make_pair(0, s)); // ?reverse?
	color[s] = GRAY;

	while (!PQ.empty()) {
		pair<ll, ll> f = PQ.top(); PQ.pop();
		ll u = f.second;

		color[u] = BLACK;

		if (d[u] < f.first * (-1)) continue;

		rep(j, adj[u].size()) {
			ll v = adj[u][j].first;
			if (color[v] == BLACK) continue;
			if (d[v] > d[u] + adj[u][j].second) {
				d[v] = d[u] + adj[u][j].second;
				PQ.push(make_pair(d[v] * (-1), v));
				p[v] = u;
				color[v] = GRAY;
			}
		}
	}
	//rep(i, n) cout << i << " " << (d[i] == INFTY ? -1 : d[i]) << endl;
	//rep(i, n) cout << i << " " << (p[i] == INFTY ? -1 : p[i]) << endl;
