void solve(Graph g, int v, int p, ll sum, vector<ll>&d){
  d[v] = sum;
  for(auto e : g[v]){
    if(e.first == p) continue;
    solve(g, e.first, v, sum + e.second, d);
  }
}


void rec(const Graph &G, int v, int p, long long sum, vector<long long> &dist) {
    dist[v] = sum;
    for (auto e : G[v]) {
        if (e.first == p) continue;
        rec(G, e.first, v, sum + e.second, dist);
    }
}

