vector<ll> dijkstra(ll N, ll K) {
    vector<ll> dist(N + 1, INF);
    dist[K] = 0;

    priority_queue<p> que;
    que.push(p(K, 0));

    while(!que.empty()) {
        auto token = que.top(); que.pop();
        auto node = token.first;
        auto cost = token.second;
        for (auto g : G[node]) {
            auto to = g.first;
            auto c = g.second;
            if (dist[to] > dist[node] + c) {
                dist[to] = dist[node] + c;
                que.push(p(to, dist[to]));
            }
        }
    }

    return dist;
}

