// 最大公約数
ll GreatestCommonDivisor(ll a, ll b) {
	if (a < b) {
		ll tmp = a;
		a = b;
		b = tmp;
	}

	ll r = a % b;
	while (r != 0) {
		a = b;
		b = r;
		r = a % b;
	}

	return b;
}

// 最小公倍数
ll LeastCommonMultiple(ll a, ll b) {
	ll gcd = GreatestCommonDivisor(a, b);

	ll tmp = a / gcd;
	return tmp * b;
}

