int main() {
	int N;
	cin >> N;

	vector< vector< pair<int,long long> > > adjList(N+1);
	int a,b;
	long long weight;
	for (int i = 0; i < N-1; ++i) {
		cin >> a >> b >> weight;
		adjList[a].push_back(make_pair(b,weight));
		adjList[b].push_back(make_pair(a,weight));
	} 

	int Q,K;
	cin >> Q >> K;

	vector<long long> dist(N+1,-1);
	priority_queue< pair<int,long long>, vector< pair<int, long long> >, greater< pair<int, long long> > > pq;
	dist[K] = 0;
	pq.push(make_pair(K,0));
	while (!pq.empty()) {
		pair<int, long long> cur = pq.top();
		pq.pop();
		int x = cur.first;
		long long d = cur.second;

		if (d > dist[x]) continue;
		for (vector< pair<int,long long> >::iterator it = adjList[x].begin(); it != adjList[x].end(); ++it) {
			int nx = it->first;
			long long nd = d + it->second;
			if (dist[nx] != -1 && dist[nx] <= nd) continue;
			dist[nx] = nd;
			pq.push(make_pair(nx,nd));
		}
	}

	int from,to;
	vector<long long> ans;
	for (int i = 0; i < Q; ++i) {
		cin >> from >> to;
		ans.push_back(dist[from] + dist[to]);
	}

	for (int i = 0; i < Q; ++i) {
		cout << ans[i] << endl;
	}
	return 0;
}

