void dijkstra(int s){//始点sからのダイクストラ
  priority_queue<pi,vector<pi>,greater<pi> > q;//pair(コスト、頂点)としてコストの小さい順に並ぶ
  for(int i=0;i<V;i++) d[i]=INF;//初期化
  d[s]=0;
  q.push(pi(0,s));
  while(!q.empty()){
    pi p = q.top();q.pop();
    int w=p.second;//最新の確定した頂点
    if(d[w]<p.first) continue;//取り出した頂点のコストが最短コストより長かったら破棄
    for(int i=0;i<g[w].size();i++){//取り出した頂点と隣接した頂点を調べる
      int t=g[w][i].to;
      ll c=g[w][i].cost;
      if(d[t]>d[w]+c){//頂点tまでの暫定最短距離よりwまでの最短距離+w→tのコストが小さければ更新
	d[t]=d[w]+c;
	q.push(pi(d[t],t));
      }
     }
  }
}
