void solve() {
    i64 N; RD(N);

    vector<vector<pair<i64,i64>>> G(N);
    REP(_, N-1) {
        i64 a,b; RD(a); RD(b); --a; --b;  // 0-based
        i64 c; RD(c);
        G[a].emplace_back(b,c);
        G[b].emplace_back(a,c);
    }

    i64 Q; RD(Q);
    i64 K; RD(K); --K;  // 0-based

    vector<i64> d;
    tie(d,ignore) = graph_dijkstra(G, K);

    REP(_, Q) {
        i64 x,y; RD(x); RD(y); --x; --y;  // 0-based

        i64 ans = d[x] + d[y];
        PRINTLN(ans);
    }
}

