int dep[MaxN + 10] , p[MaxN + 10][21] ;
bool vis[MaxN + 10];
LL cost[MaxN * 2] , dis[MaxN + 10];

void Build(int x , int y , LL c)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = c;
}

void dfs(int x , int father)
{
	dep[x] = dep[father] + 1;
	p[x][0] = father;
	if(x == K) vis[x] = 1;
	for(int i = 1 ; i <= 20 ; i++)
		p[x][i] = p[p[x][i - 1]][i - 1];
	int ed = last[x];
	while(ed != -1){
		int dr = other[ed];
		if(dr != father) {
			if(vis[x] == 1) vis[dr] = 1;
			dis[dr] = dis[x] + cost[ed];
			dfs(dr , x);
		}
		ed = pre[ed];
	}
}

void swap(int &x , int &y)
{
	int temp;temp = x ; x = y ; y = temp;
}

int Get_LCA(int x , int y)
{
	if(dep[x] < dep[y]) swap(x , y);
	int del = dep[x] - dep[y];
	for(int i = 0 ; i <= POW ; i++)
		if(del & (1 << i)) x = p[x][i];
	if(x != y){
		for(int i = POW ; i >= 0 ; i--){
			if(p[x][i] != p[y][i]){
				x = p[x][i];
				y = p[y][i];
			}
		}
		x = p[x][0];
		y = p[y][0];
	}
	return x;
}

void Init()
{
	all = -1;
	memset(last , -1 , sizeof(last));
	memset(dep , 0 , sizeof(dep));
	for(int i = 2 ; i <= n ; i++){
		int a , b ;LL c;
		scanf("%d %d %lld", &a , &b , &c);
		Build(a , b , c);
		Build(b , a , c);
	}
}

int Dis(int x , int y)//两点之间距离
{
	int lca = Get_LCA(x , y);
	return dep[x] + dep[y] - 2 * dep[lca];
}

