const ll INF = 1e10;
const int MAX = 100010;
const int WHITE = 1;
const int BLACK = 2;
const int GRAY = 3;

int N;
vector<pair<ll,ll> > list[MAX];

vector<ll> bfs(int K){
    vector<ll> d(N, INF);
    vector<int> color(N, WHITE);
    d[K] = 0;
    color[K] = GRAY;

    priority_queue<pair<ll,ll>, vector<pair<ll,ll> >, greater<pair<ll,ll> > >Q;
    Q.push({d[K],K});

    while(!Q.empty()){
        int u, cost_u;
        tie(cost_u, u) = Q.top(); Q.pop();
        color[u] = BLACK;

        if(d[u] < cost_u) continue;

        for(int j=0;j<list[u].size();j++){
            int v = list[u][j].first;
            if(color[v] == BLACK) continue;
            if(d[v] > d[u] + list[u][j].second){
                d[v] = d[u] + list[u][j].second;
                color[v] = GRAY;
                Q.push({d[v], v});
            }
        }
    }
    return d;
}

int main(){
