#include <bits/stdc++.h>

using namespace std;

using ll = long long;

template<typename T>
struct LowestCommonAncestor {
    struct Edge {
        int dst; T w;
        Edge(int _d, T _w) : dst(_d), w(_w) {}
    };

    const int root, UB;
    int n;
    std::vector<std::vector<Edge>> adj;
    std::vector<std::vector<int>> par;
    std::vector<int> dep;
    std::vector<T> dist;

    LowestCommonAncestor(int _n) : root(0), UB(log2(_n) + 1), n(_n), adj(n),
                                   par(UB, std::vector<int>(n)), dep(n), dist(n) {}

    void add_edge(int v1, int v2, T w) {
        adj[v1].emplace_back(Edge(v2, w));
        adj[v2].emplace_back(Edge(v1, w));
    }

    void Preprocessing() {
        Dfs(root, -1, 0, 0);
        for (int k = 0; k + 1 < UB; ++k)
            for (int v = 0; v < n; ++v)
                par[k + 1][v] = (par[k][v] < 0 ? -1 : par[k][par[k][v]]);
    }

    void Dfs(int cur, int p, int d, T len) {
        par[0][cur] = p;
        dep[cur] = d;
        dist[cur] = len;
        for (const auto &e : adj[cur])
            if (e.dst != p) Dfs(e.dst, cur, d + 1, len + e.w);
    }

    int get(int u, int v) {
        if (dep[u] > dep[v]) std::swap(u, v);
        for (int k = 0; k < UB; ++k)
            if ((dep[v] - dep[u]) >> k & 1) v = par[k][v];
        if (u == v) return u;
        for (int k = UB - 1; 0 <= k; --k)
            if (par[k][u] != par[k][v]) {
                u = par[k][u];
                v = par[k][v];
            }
        return par[0][u];
    }

    T distance(int u, int v) { return dist[u] + dist[v] - dist[get(u, v)]; }
};

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    int n;
    cin >> n;

    LowestCommonAncestor<ll> lca(n);
    for (int i = 0, a, b, c; i < n - 1; ++i) {
        cin >> a >> b >> c;
        lca.add_edge(a - 1, b - 1, c);
    }

    lca.Preprocessing();
    int q, k;
    cin >> q >> k;
    for (int i = 0, x, y; i < q; ++i) {
        cin >> x >> y;
        cout << lca.distance(x - 1, k - 1) + lca.distance(y - 1, k - 1) << endl;
    }

    return 0;
}

