#define REP(i, start, count) for(int i=(start); i<(int)(count); ++i)
#define rep(i, count) REP(i, 0, count)
#define ALLOF(c) (c).begin(), (c).end()

typedef long long ll;
typedef unsigned long long ull;

#define NIL -1
#define MAX 100000

struct Node {
    int parent = NIL;
    ll depth = 0; // 親との距離
    vector<int> children = vector<int>();
    int s = 0;
};

int main(void) {
    Node tree[MAX + 1];
    int N;
    cin >> N;

    rep(i, N - 1) {
        int a, b, c;
        cin >> a >> b >> c;
        tree[b].parent = a;
        tree[b].depth = c;
        tree[a].children.push_back(b);
    }

    int Q, K;
    cin >> Q >> K;

    // 木をK基点でDFSする
    stack<int> S;
    int searched[N + 1] = {}; 
    ll toK[N + 1] = {};

    S.push(K);
    searched[K] = 1;
    toK[K] = 0;

    while (!S.empty()) {
        int u = S.top();

        bool flag = false;
        for (int i = tree[u].s; i < tree[u].children.size(); ++i) {
            int child = tree[u].children[i];
            if (searched[child] == 0) {
                searched[child] = 1;

                ll parent_depth = tree[child].parent != NIL ? toK[tree[child].parent] : 0;
                toK[child] = parent_depth + tree[child].depth;
                S.push(child);
                flag = true;
                tree[u].s = i;
                break;
            }
        }

        if (!flag) {
            ll parent = tree[u].parent;
            if (parent != NIL && searched[parent] == 0) {
                searched[parent] = 1;

                toK[parent] = toK[u] + tree[u].depth;
                S.push(parent);
                flag = true;
            }
        }

        if (!flag) {
            searched[u] = 2;
            S.pop();
        }

    }

    // 距離を求める
    rep(i, Q) {
        int x, y;
        cin >> x >> y;
        cout << toK[x] + toK[y] << endl;
    }

    return 0;
}

