//{{{ void leastCommonAncestor(const Graph &g, int r, vector<Query> &qs) {
struct Query {
	int u, v, w;
	Query(int u, int v) : u(u), v(v), w(-1) { }
};
void visit(const Graph &g, int u, int w,
		unordered_map<int,unordered_map<int, int>> &qs, vector<int> &color,
		vector<int> &ancestor, UnionFind &uf) {
	ancestor[ uf.root(u) ] = u;
	FOR(e, g[u]) if (e->dst != w) {
		visit(g, e->dst, u, qs, color, ancestor, uf);
		uf.unionSet( e->src, e->dst );
		ancestor[ uf.root(u) ] = u;
	}
	color[u] = 1;
	for(auto &p:qs[u]) {
//		int w = (q->v == u ? q->u : q->u == u ? q->v : -1);
//		if (w >= 0 && color[w]) q->w = ancestor[ uf.root(w) ];
		int w = p.first;
		if(color[w]){
			p.second = ancestor[uf.root(w)];
		}
	}
}
void leastCommonAncestor(const Graph &g, int r, vector<Query> &qs) {
	unordered_map<int, unordered_map<int, int>> qm;
	for(auto &q:qs){
		qm[q.u][q.v] = -1;
		qm[q.v][q.u] = -1;
	}
	UnionFind uf(g.size());
	vector<int> color(g.size()), ancestor(g.size());
	visit(g, r, -1, qm, color, ancestor, uf);
	for(auto &q:qs){
		q.w = max(qm[q.u][q.v], qm[q.v][q.u]);
//		cerr<<"result: "<<q.u<<" "<<q.v<<" "<<qm[q.v][q.u]<<" "<<qm[q.u][q.v]<<endl;
	}
}
