void dijkstra(int s)
{
	priority_queue<P,vector<P>,greater<P> > que;
	for(int i = 0;i < n;i++) dist[i] = INF;
	dist[s] = 0;
	que.push(make_pair(0,s));
	while(!que.empty())
	{
		P p=que.top();
		que.pop();
		int v=p.second;
		if(dist[v]<p.first) 
		{
			continue;
		}
		for(int i=0;i<tree[v].size();i++)
		{
			edge e=tree[v][i];
			if(dist[e.to]>dist[v] + e.cost)
			{
				dist[e.to]=dist[v] + e.cost;
				que.push(make_pair(dist[e.to],e.to));
			}
		}
	}
}
