using namespace std;

struct Tree {
    vector<long long> distances;
    vector<vector<pair<int, int> > > edges;

    explicit Tree(int n) {
        distances.resize(n + 1, -1);
        edges.resize(n + 1);
    }

    void connect(int a, int b, int dist) {
        edges[a].emplace_back(b, dist);
        edges[b].emplace_back(a, dist);
    }

    void bfs(int root) {
        distances[root] = 0;
        queue<int> current;
        current.push(root);
        while (!current.empty()) {
            int a = current.front();
            for (int i = 0; i < edges[a].size(); ++i) {
                int b = edges[a][i].first, c = edges[a][i].second;
                if (distances[b] == -1) {
                    distances[b] = distances[a] + c;
                    current.push(b);
                }
            }
            current.pop();
        }
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int N;
