    vector<pair<int, int> > XY(Q);
    for (auto & xy : XY) cin >> xy.first >> xy.second;
    tree.bfs(K);
    for (auto & xy : XY) {
       printf("%lld\n", tree.distances[xy.first]+tree.distances[xy.second]);
    }
    return 0;
}

