typedef long long ll;

struct Edge {
  int to, cost;
};

int N, Q, K;
vector<Edge> d[100000];
ll v[100000];

void dfs(int idx, int par = -1) {
  for (auto &e : d[idx]) {
    if (e.to == par) continue;
    v[e.to] = v[idx] + e.cost;
    dfs(e.to, idx);
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N;
  for (int i = 1; i < N; i++) {
    int a, b, c;
    --a, --b;
    d[a].emplace_back((Edge) {b, c});
    d[b].emplace_back((Edge) {a, c});
  }
  cin >> Q >> K;
  dfs(--N);
  while (Q--) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    cout << v[x] + v[y] << endl;
  }

  return 0;
}

