int main() {
	ios::sync_with_stdio(false);
	cin >> N;
	vector<long long int>dis(N + 1, LLONG_MAX);
	list<pair<int, int>>edge[100001];
	for (int i = 1; i < N; i++) {
		cin >> L >> R >> K;
		edge[L].push_back({ R,K });
		edge[R].push_back({ L,K });
	}
	cin >> M >> K;
	dis[K] = 0;
	priority_queue<pair<long long int, int>, vector<pair<long long int, int>>, greater<pair<long long int, int>>>PQ;
	PQ.push({ 0,K });
	while (!PQ.empty()) {
		long long int c = PQ.top().first;
		long long int cn = PQ.top().second;
		PQ.pop();
		if (c > dis[cn])continue;
		for (auto i : edge[cn]) {
			if (dis[cn] + i.second < dis[i.first]) {
				dis[i.first] = dis[cn] + i.second;
				PQ.push({ dis[i.first],i.first });
			}
		}
	}
	for (int i = 0; i < M; i++) {
		cin >> L >> R;
		cout << dis[L] + dis[R] << endl;
	}
	return 0;
}

