vll bfs(ll n, vector<vector<vll>> &next, ll start) {
  vll ans(n, 0);

  queue<vll> task;
  task.push({0, start});

  vll seen(n, 0);
  seen[start] = 1;

  ll depth = 0;
  while (task.size() > 0) {
    for (ll j = 0; j < next[task.front()[1]].size(); j++) {
      if (seen[next[task.front()[1]][j][1]] == 0) {
        ans[next[task.front()[1]][j][1]] = ans[task.front()[1]] + next[task.front()[1]][j][0];

        task.push(next[task.front()[1]][j]);
        seen[next[task.front()[1]][j][1]] = 1;
      }
    }
    task.pop();
  }
  return ans;
}

