        n = _n;
        vertex_to.resize(_n);
    }
    void connect(int from, int to, W_T val = 0) {
        vertex_to[from].push_back(edges.size());
        vertex_to[to].push_back(edges.size());
        edges.emplace_back(from, to, val);
    }
    inline size_t degree(int v) {
        return vertex_to[v].size();
    }
};



