ll dp[100100];
int tin[100100], tout[100100], up[100100][20];
vector <pii> g[100100];

void dfs(int v, int p = 0) {
    tin[v] = ++timer;
    up[v][0] = p;

    for (int i = 1; i <= lg; ++i)
        up[v][i] = up[up[v][i - 1]][i - 1];

    for (int i = 0; i < (int)g[v].size(); ++i){
        int to = g[v][i].f;
        if (to != p) {
            dp[to] = dp[v] + g[v][i].s;
            dfs(to, v);
        }
    }
    tout[v] = ++timer;
}

bool upper(int a, int b) {
    return tin[a] <= tin[b] && tout[a] >= tout[b];
}

int lca (int a, int b) {
    if (upper(a, b)) return a;
    if (upper(b, a)) return b;
    for (int i = lg; i >= 0; --i)
        if (!upper(up[a][i], b))
            a = up[a][i];
    return up[a][0];
}

