void dijkstra(int s) {
  // cost(neg), node
  priority_queue<pair<ll, int>> pq;
  dist[s] = 0ll;
  pq.push(make_pair(0ll, s));
  while (!pq.empty()) {
    auto pu = pq.top(); pq.pop();
    ll cu = -pu.first;
    int u = pu.second;

    if (visited[u]) continue;
    visited[u] = true;

    for (auto pv: adj[u]) {
      ll cv = pv.first;
      int v = pv.second;
      if (visited[v]) continue;
      if (dist[v] > dist[u] + cv) {
        dist[v] = dist[u] + cv;
        pq.push(make_pair(dist[v]*-1ll, v));
      }
    }
  }
};

