constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

class Dijkstra{
  //Dijkstra algorithm
  //calculation time complexity: O(|W| log |V|)
  //useful without negative cost
  private:
    struct edge { ll to, cost; };
    typedef pair<ll, ll> P; //first is the shortest distance, second is the number of vertex

    ll V, E;
    vector<ll> d;
    vector<ll> prev;
    vector<vector<edge> > G;

  public:
    Dijkstra(ll V, vector<ll> From, vector<ll> To, vector<ll> Cost){
      //num of vertex
      this->V = V;
      d.resize(V, INFLL);
      prev.resize(V, -1);
      E = (ll)From.size();
      if(To.size() != E || Cost.size() != E){
        fprintf(stderr, "Sizes are different, %d %d %d\n", From.size(), To.size(), Cost.size());
        exit(0);
      }
      G.resize(V);
      for(ll i=0; i<E; ++i){
        edge tmp_forward = {To[i], Cost[i]};
        G[From[i]].push_back(tmp_forward);
      }
      return;
    };

    ~Dijkstra(void){
      return;
    };

    //calculate shortest path from s vertex to others
    void shortest_path(ll s){
      priority_queue<P, vector<P>, greater<P> > que;
      for(ll i=0; i<V; ++i) d[i] = INFLL;
      d[s] = 0;
      que.push(P(0, s));

      while(!que.empty()){
        P p = que.top(); que.pop();
        ll v = p.second;
        if(d[v] < p.first) continue;
        for(ll i=0; i<G[v].size(); i++){
          edge e = G[v][i];
          if(d[e.to] > d[v] + e.cost){
            d[e.to] = d[v] + e.cost;
            prev[e.to] = v;
            que.push(P(d[e.to], e.to));
          }
        }
      }
      return;
    };

    ll get_distance(ll vertex){
      return d[vertex];
    };

    //shortest path to vertex t
    vector<ll> get_path(ll t){
      vector<ll> path;
      for(; t!=-1; t=prev[t]){
        path.push_back(t);
      }
      reverse(path.begin(), path.end());
      return path;
    };
};

