        edge e;
        e.to = b;
        e.cost = c;
        G[a].push_back(e);

        edge e2;
        e2.to = a;
        e2.cost = c;
        G[b].push_back(e2);
    }
    long long q, k;
    cin >> q >> k;
    dijkstra(k - 1, G);
    REP(i, q)
    {
        long long x, y;
        cin >> x >> y;
        x--;
        y--;
        cout << d[x] + d[y] << endl;
    }
}

