        if(upper(x, k)){
            cout << res + 2 * (dp[k] - dp[x]) << endl;
            continue;
        }
        if(upper(y, k)){
            cout << res + 2 * (dp[k] - dp[y]) << endl;
            continue;
        }
        if(upper(k, x) || upper(k, y)){
            cout << res << endl;
            continue;
        }
        cout << 2 * (dp[k] - dp[pr]) + res << endl;
    }
}

