    Edge(int u, int v, int w) : from(u), to(v), dist(w) {}
};

vector <Edge> edge;
vector <int> G[maxn];
ll d[2][maxn];
bool done[maxn];

int N,M;

void Init() {
    rep(i,1,N+1) G[i].clear();
    edge.clear();

}

void AddEdge(int from, int to, int dist) {
    int e;
    edge.pb(Edge(from, to, dist));
    e = sz(edge);
    G[from].pb(e - 1);
}

void dij(int k,int s) {
    priority_queue <pii,vector<pii>,greater<pii> > Q;
    rep(i,1,N+1) {
        d[k][i] = INF;
    }
    d[k][s] = 0;
    memset(done,0,sizeof(done));
    Q.push(mp(0,s));
    while (!Q.empty()) {
        pii t = Q.top(); Q.pop();
        int u = t.se;
        if (done[u]) continue;
        done[u] = true;
        rep(i,0,sz(G[u])) {
            Edge e = edge[G[u][i]];
            if (d[k][e.to] > d[k][u] + e.dist) {
                d[k][e.to] = d[k][u] + e.dist;
                Q.push(mp(d[k][e.to],e.to));
            }
        }

    }
}

