vector<vector<pair<ll, ll>>> graph;
vector<ll> costs;

ll cost = 0;

void dfs(ll i, ll parent)
{
	costs[i] = cost;
	for(auto &neighbor : graph[i])
		if(neighbor.ff != parent)
		{
			cost += neighbor.ss;
			dfs(neighbor.ff, i);
			cost -= neighbor.ss;
		}
}

