vll dijkstra(ll n, vector<vector<vll>> &next, ll start) {
  vll ans(n, inf);
  ans[start] = 0;

  for (ll i = 0; i < n - 1; i++) {
    priority_queue<vll, vector<vll>, greater<vll>> pq;
    for (ll j = 0; j < n; j++) {
      if (ans[j] == inf) continue;
      for (ll k = 0; k < next[j].size(); k++) {
        if (ans[next[j][k][1]] == inf) {
          pq.push({ans[j] + next[j][k][0], next[j][k][1]});
        }
      }
    }
    vll v = pq.top();
    ans[v[1]] = v[0];
  }

  return ans;
}

int main() {
  ll n;
  cin >> n;

  vector<vector<vll>> next(n, vector<vll>(0));
  for (ll i = 0; i < n - 1; i++) {
    ll a, b, c;
    cin >> a >> b >> c;
    next[a - 1].push_back({c, b - 1});
    next[b - 1].push_back({c, a - 1});
  }

  ll q, k;
  cin >> q >> k;

  vll ans = dijkstra(n, next, k - 1);

  for (ll i = 0; i < q; i++) {
    ll x, y;
    cin >> x >> y;
    cout << ans[x - 1] + ans[y - 1] << endl;
  }
}

