typedef long long ll;
typedef vector<ll> vl;
typedef vector<vl> vvl;

const ll INF = (ll)1e18;
int N, Q, K;
vl d;
vvl cost;
vector<bool> used;

void dijkstra(int s) {
	d[s] = 0;
	while (true) {
		int v = -1;
		for (int u = 0; u < N; u++) {
			if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
		}
		if (v == -1) break;
		used[v] = true;
		for (int u = 0; u < N; u++) {
			d[u] = min(d[u], d[v] + cost[v][u]);
		}
	}
}

int main(void) {
	cin >> N;

	vl ini_vl(N, INF);
	cost.resize(N, ini_vl);

	for (int i = 1; i < N; ++i) {
		int a, b;
		ll c;
		cin >> a >> b >> c;
		cost[a - 1][b - 1] = c;
		cost[b - 1][a - 1] = c;
	}

	d.resize(N, INF);
	used.resize(N, false);

	cin >> Q >> K;
	dijkstra(K - 1);

	for (int i = 1; i <= Q; ++i) {
		int x, y;
		cin >> x >> y;
		ll ans = d[x - 1] + d[y - 1];
		cout << ans << '\n';
	}

	return 0;
}

