void init(int V){
	rep(i, V){
		rep(j, V){
			if(i == j) d[i][j] = 0;
			else d[i][j] = 10000000000;

		}
	}
}

void make(int E){
	rep(i, E){
		long u , v ,c;
		cin >> u >> v >> c;
		u--; v--;
		d[u][v] = c; d[v][u] = c;
	}
}
void wf(int V){
	rep(k, V){
		rep(i, V){
			rep(j, V){
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}



int main(void){
