typedef long long ll;
typedef pair<int, int> P;

const ll INF = 1e18;

//#####################
//Dijkstra
//#####################
struct edge
{
    int to, cost;
};

int n;
vector<edge> g[112345];
ll dis[112345];

void dijkstra(int s)
{
    priority_queue<P, vector<P>, greater<P>> que;
    fill(dis, dis + n + 1, INF);
    dis[s] = 0;
    que.push(P(0, s));

    while (!que.empty())
    {
        P p = que.top();
        que.pop();
        int n_ = p.second;
        if (dis[n_] < p.first)
            continue;
        for (int i = 0; i < g[n_].size(); i++)
        {
            edge e = g[n_][i];
            if (dis[e.to] > dis[n_] + e.cost)
            {
                dis[e.to] = dis[n_] + e.cost;
                que.push(P(dis[e.to], e.to));
            }
        }
    }
}

int main()
{
    int q, k;
    cin >> n;

    REP(i, n - 1)
    {
        int a, b, c;
        cin >> a >> b >> c;

        g[a].push_back({b, c});
        g[b].push_back({a, c});
    }

    cin >> q >> k;

    int x[112345];
    int y[112345];

    REP(i, q)
    {
        cin >> x[i] >> y[i];
    }

    dijkstra(k);

    REP(i, q)
    {
        cout << dis[x[i]] + dis[y[i]] << endl;
    }

    return 0;
}

