struct edge { int to; ll cost; };

int N, Q, K;
vector<edge> g[100010];
ll d[100010];


void dijk(int s){
    priority_queue<int> pq;
    pq.push(s);
    d[s] = 0;

    while(!pq.empty()){
        int u = pq.top(); pq.pop();
        for(edge v : g[u]){
            if(d[v.to] > d[u] + v.cost){
                d[v.to] = d[u] + v.cost;
                pq.push(v.to);
            }
        }
    }
}


