struct Edge{
    int to;
    ll cost;
    Edge(int to, ll cost) :to(to), cost(cost){};
};
const int n_max = 100050;
vector<vector<Edge>> root(n_max);

struct Data{
    int v;
    ll min;
    Data(int v, ll min): v(v), min(min){};
    //a < bとしたとき昇順データとなる
    bool operator<(const Data& other) const {
        return min > other.min;
    }
};
vector<ll> dp(n_max, 1e18);

void dijkstra(int k){
    priority_queue<Data> pq;
    auto push = [&](int v, ll c){
        if (dp[v] < c) return;
        dp[v] = c;
        pq.emplace(v, c);
    };
    push(k, 0);
    while(!pq.empty()){
        auto now = pq.top(); pq.pop();
        for(auto next: root[now.v]){
            push(next.to, dp[now.v] + next.cost);
        }
    }
}

