        root[b].emplace_back(a, c);
    } 

    int q, k;
    cin >> q >> k;
    k--;
    dijkstra(k);
    rep(i, q){
        int x, y; cin >> x >> y;
        x--; y--;
        cout << dp[x]+dp[y] << endl;
    }

}

