#include <functional>
using namespace std;

using int64 = long long;
const int64 kUnreached = 1e+16;

struct Edge {
  int64 to, dist;
};

void Dijkstra(const vector<vector<Edge>>& edges, const int64 k, vector<int64>& dists) {
  dists[k] = 0;
  queue<int64> q;
  q.push(k);
  while (!q.empty()) {
    int64 from = q.front();
    q.pop();
    for (auto& e : edges[from]) {
      int64 to = e.to;
      if (dists[to] < kUnreached)
        continue;
      dists[to] = dists[from] + e.dist;
      q.push(to);
    }
  }
}

int main() {
  int64 n;
  cin >> n;
  vector<vector<Edge>> edges(n);
  for (int64 i = 0; i < n - 1; ++i) {
    int64 a, b, c;
    cin >> a >> b >> c;
    --a;
    --b;
    edges[a].push_back({b, c});
    edges[b].push_back({a, c});
  }

  int64 q, k;
  cin >> q >> k;
  vector<int64> dists(n, kUnreached);
  Dijkstra(edges, k - 1, dists);
  for (int64 i = 0; i < q; ++i) {
    int64 x, y;
    cin >> x >> y;
    cout << (dists[x - 1] + dists[y - 1]) << "\n";
  }
  return 0;
}

