  while(!q.empty()) {
    ll c,v; tie(c, v) = q.top(); q.pop();
    for(auto &e:G[v]) {
      ll nc = c+e.cost;
      int nv = e.to;
      if(dist[nv] > nc) {
        dist[nv] = nc;
        q.push(state(nc, nv));
      }
    }
  }
  return;
}

