#include <bits/stdc++.h>
using namespace std;
using ll = long long;
constexpr const ll INF = LLONG_MAX / 2;

struct node {
    int to;
    ll cost;
};

vector<ll> dijkstra(vector<vector<node>> const &graph, int K) {
    int N = graph.size();
    vector<ll> cost(N, INF);
    cost[K] = 0;
    priority_queue<pair<ll,int>> que;
    unordered_set<int> used;

    que.push({0, K});
    while (!que.empty()) {
        auto p = que.top(); que.pop();
        auto u = p.second;
        if (used.count(u) || cost[u] != p.first)
            continue;
        used.insert(u);
        for (auto const &v: graph[u]) {
            cost[v.to] = min(cost[v.to], cost[u] + v.cost);
            que.push({cost[v.to], v.to});
        }
    }
    return cost;
}

int main() {
    int N;
    cin >> N;
    vector<vector<node>> graph(N);

    for (int i = 0; i < N - 1; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        graph[a].push_back({b, c});
        graph[b].push_back({a, c});
    }

    int Q, K;
    cin >> Q >> K;
    K--;

    auto cost = dijkstra(graph, K);

    for (int i = 0; i < Q; i++) {
        int x, y;
        cin >> x >> y;
        x--; y--;
        cout << cost[x] + cost[y] << endl;
    }
    return 0;
}

