typedef long long ll;
typedef pair<int,int> P;
constexpr ll INF = (1LL << 55);
struct LowestCommonAncestor {
  int n, h;
  vector<vector<int>> par;
  vector<vector<pair<int,int>>> g;
  vector<int> dep;
  vector<ll> weight;

  LowestCommonAncestor(int sz) {
    n = sz; h = 1;
    g.resize(n), dep.resize(n), weight.resize(n);
    while ((1 << h) <= n) h++;
    par.assign(h, vector<int>(n, -1));
  }

  void add_edge(int u, int v, int w = 0) {
    g[u].emplace_back(make_pair(v, w));
    g[v].emplace_back(make_pair(u, w));
  }

  void dfs(int u, int p, int depth) {
    par[0][u] = p;
    dep[u] = depth;
    if (p == -1) weight[u] = 0;
    for (auto v : g[u]) {
      if (v.first == p) continue;
      weight[v.first] = weight[u] + v.second;
      dfs(v.first, u, depth + 1);
    }
  }

  void build(int root = 0) {
    dfs(root, -1, 0);
    for (int i = 0; i + 1 < h; i++) {
      for (int j = 0; j < n; j++) {
        if (par[i][j] != -1) par[i+1][j] = par[i][par[i][j]];
        else par[i+1][j] = -1;
      }
    }
  }

  int query(int u, int v) {
    if (dep[u] > dep[v]) swap(u, v);
    for (int i = h-1; i >= 0; i--) {
      if ( ((dep[v] - dep[u]) >> i) & 1) v = par[i][v];
    }
    if (u == v) return u;
    for (int i = h-1; i >= 0; i--) {
      if (par[i][u] != par[i][v]) {
        u = par[i][u];
        v = par[i][v];
      }
    }
    return par[0][u];
  }

  int dist(int u, int v) {
    return dep[u] + dep[v] - 2 * dep[query(u, v)];
  }

  ll weightedsum(int u, int v) {
    return weight[u] + weight[v] - 2 * weight[query(u, v)];
  }
};
int main(){ 
  int n;
  cin >> n;
  LowestCommonAncestor lca(n);
  rep(i,n-1) {
    int u, v, c;
    cin >> u >> v >> c;
    u--; v--;
    lca.add_edge(u, v, c);
  }
  lca.build();
  int q, k;
  cin >> q >> k;
  k--;
  while (q--) {
    int x, y;
    cin >> x >> y;
    x--, y--;
    cout << lca.weightedsum(x, k) + lca.weightedsum(y, k) << endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long int ll;
#define MAXN	100000
struct edge
{
  int v,n;
  ll w;
  edge():v(0),w(0),n(0){}
  edge(int vv, ll ww, int nn):v(vv),w(ww),n(nn){}
};
edge E[MAXN<<1];
int nE;
int front[MAXN+1];
void add_edge(int u, int v, ll w)
{
  int ne = ++nE;
  E[ne] = edge(v,w,u[front]);
  u[front] = ne;
}
int solid[MAXN+1];
ll d[MAXN+1];
void dijstra(int s)
{
  set< pair<ll,int> > q;
  memset(d, -1, sizeof(d));
  d[s] = 0; solid[s] = 1;
  q.insert(make_pair(0,s));
  while(!q.empty())
  {
    auto p = q.begin();
    int u = p->second;
    solid[u] = 1;
    q.erase(p);
    for(int e=u[front];e;e = E[e].n)
    {
      int v = E[e].v; ll w = E[e].w;
      if((!solid[v]) && ((-1 == d[v]) || (d[u]+w < d[v])))
      {
        q.erase(make_pair(d[v],v));
        d[v] = d[u]+w;
        q.insert(make_pair(d[v],v));
      }
    }
  }
}
int main(void)
{
  int N = 0;
  int a = 0, b = 0;
  ll c = 0;
  scanf("%d", &N);
  while(N--)
  {
    scanf("%d %d %lld", &a, &b, &c);
    add_edge(a,b,c);
    add_edge(b,a,c);
  }
  int Q = 0, K = 0;
  int x = 0, y = 0;
  scanf("%d %d", &Q, &K);
  dijstra(K);
  while(Q--)
  {
    scanf("%d %d", &x, &y);
    printf("%lld\n", d[x]+d[y]);
  }
  return 0;
}

