using namespace std;

void dijkstra(const vector<vector<pair<int, int>>> &adj_lists,
              vector<long> &distances, int s) {
  priority_queue<pair<long, int>, vector<pair<long, int>>,
                 greater<pair<long, int>>>
      que;
  que.push(pair<long, int>(0, s));
  while (!que.empty()) {
    const pair<long, int> p = que.top();
    const long d = p.first;
    const int v = p.second;
    que.pop();
    if (distances[v] < 0) {
      distances[v] = d;
      for (int k = 0; k < adj_lists[v].size(); k++) {
        const int u = adj_lists[v][k].first, w = adj_lists[v][k].second;
        if (distances[u] < 0) {
          que.push(pair<long, int>(d + w, u));
        }
      }
    }
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, Q, K, as[MAX_N], bs[MAX_N], cs[MAX_N], xs[MAX_Q], ys[MAX_Q];
  scanf("%d", &N);
  for (int i = 0; i < N - 1; i++) {
    scanf("%d %d %d", &as[i], &bs[i], &cs[i]);
    as[i]--;  // NOTE : modified input
    bs[i]--;  // NOTE : modified input
  }
  scanf("%d %d", &Q, &K);
  K--;  // NOTE : modified input
  for (int k = 0; k < Q; k++) {
    scanf("%d %d", &xs[k], &ys[k]);
    xs[k]--;  // NOTE : modified input
    ys[k]--;  // NOTE : modified input
  }

  // create graph (tree)
  vector<vector<pair<int, int>>> adj_lists;
  for (int i = 0; i < N; i++) {
    adj_lists.push_back(vector<pair<int, int>>());
  }
  for (int i = 0; i < N - 1; i++) {
    const int a = as[i], b = bs[i], c = cs[i];
    adj_lists[a].push_back(pair<int, int>(b, c));
    adj_lists[b].push_back(pair<int, int>(a, c));
