void addEdge(int a, int b, int c)
{
  G[a].push_back((Edge){b, c});
  G[b].push_back((Edge){a, c});
}

void spfa(int s)
{
  queue<int> que;
  que.push(s);
  memset(d, 0x3f, sizeof d);
  memset(inque, 0, sizeof inque);
  inque[s] = true;
  d[s] = 0;
  while (!que.empty()) {
    int v = que.front(); que.pop();
    inque[v] = false;
    for (int i = 0; i < G[v].size(); ++i) {
      Edge &e = G[v][i];
      if (d[e.to] > d[v] + e.cost) {
        d[e.to] = d[v] + e.cost;
        if (!inque[e.to]) {
          inque[e.to] = true;
          que.push(e.to);
        }
      }
    }
  }
}

