ll XtoY(int K, int x, int y)
{
	vector<ll> D(N, 100000000000000000);
	vector<int> Xin(N, 0);

	bool xf = false, yf = false;

	D[K] = 0;

	while (!xf || !yf)
	{
		int u = -1;
		for (int v = 0; v < N; ++v)
		{
			if (Xin[v] == 0 && (u == -1 || D[v] < D[u]))u = v;
		}
		if (u == -1) { break; }

		Xin[u] = 1;

		for (int v = 0; v < N; ++v)
		{
			if (cost[v][u] == 0) { continue; }

			D[v] = min(D[v], D[u] + cost[u][v]);

			if (v == x) { xf = true; }
			if (v == y) { yf = true; }
		}

	}


	return D[y]+D[x];
}

