ll lca(ll u, ll v){
	if(depth[u]>depth[v]) swap(u,v);
	for(ll k=0; k<30; k++){
		if((depth[v]-depth[u])>>k&1){
			v=parent[k][v];
		}
	}
	if(u==v) return u;
	for(ll k=30-1; k>=0; k--){
		if(parent[k][u]!=parent[k][v]){
			u=parent[k][u];
			v=parent[k][v];
		}
	}
	return parent[0][u];
}

