const int N = 111111;
vector<pair<int, ll> > tree[N];
int depth[N];
int firstPos[N];
vector<int> tour;
pair<int, int> stree[4 * N];
ll dists[N];
int n, q, k;

pair<int, int> build(int left, int right, int pos) {
    if(left == right) {
        stree[pos] = make_pair(depth[tour[left]], left);
        return stree[pos];
    }
    int mid = left + right >> 1;
    pair<int, int> a = build(left, mid, pos * 2 + 1);
    pair<int, int> b = build(mid + 1, right, pos * 2 + 2);
    stree[pos] = min(a, b);
    return stree[pos];
}

pair<int, int> query(int left, int right, int curLeft, int curRight, int pos) {
    if(curLeft > right || curRight < left) {
        return make_pair(N, N);
    } else if(curLeft >= left && curRight <= right) {
        return stree[pos];
    }
    int mid = curLeft + curRight >> 1;
    pair<int, int> a = query(left, right, curLeft, mid, pos * 2 + 1);
    pair<int, int> b = query(left, right, mid + 1, curRight, pos * 2 + 2);
    return min(a, b);
}

int getLCA(int u, int v) {
    int pu = firstPos[u], pv = firstPos[v];
    if(pu > pv) {
        swap(pu, pv);
    }
    pair<int, int> res = query(pu, pv, 0, tour.size(), 0);
    return tour[res.second];
}

void dfs(int node, int p = 0) {
    if(p == 0) {
        depth[node] = 0;
    } else {
        depth[node] = depth[p] + 1;
    }
    for(nnode : tree[node]) {
        if(nnode.first != p) {
            if(!firstPos[node]) {
                firstPos[node] = tour.size();
            }
            tour.push_back(node);
            dists[nnode.first] = dists[node] + nnode.second;
            dfs(nnode.first, node);
        }
    }
    if(!firstPos[node]) {
        firstPos[node] = tour.size();
    }
    tour.push_back(node);
}

ll solve(int x, int y) {
    int lca = getLCA(x, y); //lol
    return dists[x] + dists[y];
}

