void dfs(const vector<vector<pair<int64_t, int64_t>>>& links,
         vector<int64_t>& dist, int64_t current, int64_t parent) {
  for (auto p : links[current]) {
    auto v = p.first;
    auto d = p.second;
    if (v == parent) {
      continue;
    }

    dist[v] = dist[current] + d;
    dfs(links, dist, v, current);
  }
}

main() {
  int64_t n;
  cin >> n;

  vector<vector<pair<int64_t, int64_t>>> links(n);
  for (auto _ : irange(0L, n - 1)) {
    int64_t a, b, c;
    cin >> a >> b >> c;
    --a;
    --b;
    links[a].emplace_back(b, c);
    links[b].emplace_back(a, c);
  }

  int64_t q, k;
  cin >> q >> k;
  --k;

  vector<int64_t> dist(n);
  dfs(links, dist, k, -1);

  for (auto _ : irange(0L, q)) {
    int64_t x, y;
    cin >> x >> y;
    --x;
    --y;

    cout << dist[y] + dist[x] << "\n";
  }
}

