		}
	}
}

void make(int E){
	rep(i, E){
		int u , v ,c;
		cin >> u >> v >> c;
		u--; v--;
		d[u][v] = c; d[v][u] = c;
	}
}
void wf(int V){
	rep(k, V){
		rep(i, V){
			rep(j, V){
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}



