	if (mini[m] < min.first) continue;

	FOR(i, 0, edge[m].size()) {
	  k = edge[m][i].first;
	  if (stt[k] != COMP) {
		if (edge[m][i].second + mini[m] < mini[k]) {
		  mini[k] = edge[m][i].second + mini[m];
		  stt[k] = VIS;
		  pq.push(make_pair(mini[k], k));
		}
	  }
	}
  }

}

