#include <bits/stdc++.h>
using namespace std;

class LCA {
public:
  struct edge{
    int to;
    long long cost;
    edge(int to,long long cost):to(to),cost(cost){}
  };
  int logn,n;
  bool isInit = false;
  vector<int> depth;
  vector<long long> distance;
  vector<vector<edge>> es;
  vector<vector<int>> parent;
  LCA(int n):n(n) {
    logn = log2(n) + 1;
    es = vector<vector<edge>>(n);
    parent = vector<vector<int>>(logn,vector<int>(n,-1));
    depth = vector<int>(n);
    distance = vector<long long>(n);
  }
  void add_edge(int u,int v,long long c=1) {
    es[u].emplace_back(v, c);
    es[v].emplace_back(u, c);
    isInit = false;
  }
  void dfs(int u,int prev=-1,int d=0,long long dist=0) {
    depth[u] = d;
    distance[u] = dist;
    parent[0][u] = prev;
    for(const edge& e: es[u]) {
      if( e.to == prev )continue;
      dfs( e.to, u, d+1, dist+e.cost );
    }
  }
  void init() {
    isInit = true;
    dfs(0);
    for(int i=0; i<logn-1; i++)for(int j=0; j<n; j++) {
        if( parent[i][j] == -1 )parent[i+1][j] = -1;
        else parent[i+1][j] = parent[i][parent[i][j]];
      }
  }
  int calc(int u,int v) {
    if(!isInit)init();
    if( depth[u] < depth[v] )swap(u,v);
    for(int i=0; i<depth[u]-depth[v]; i++) {
      if( ((depth[u]-depth[v]) >> i) & 1 )u = parent[i][u];
    }
    if( u == v )return u;
    for(int k=logn-1; k>=0; k--) {
      if( parent[k][u] != parent[k][v] ) {
        u = parent[k][u];   // 共通の親ではないので，そこより親にある(2^kより子ではない)
        v = parent[k][v];
      }
    }
    return parent[0][u];
  }
  long long getDistance(int u,int v) {
    int w = calc(u,v);
    return distance[u]+distance[v]-distance[w]*2;
  }
};

int main(void) {
  int N;
  cin >> N;
  LCA lca(N);
  for(int i=0;i<N-1;i++){
    int a,b,c;
    cin >> a >> b >> c;
    a--;b--;
    lca.add_edge(a,b,c);
  }

  int Q,K;
  cin >> Q >> K;
  K--;
  int x,y;
  for(int i=0;i<Q;i++){
    cin >> x >> y;x--;y--;
    cout << lca.getDistance(x,K) + lca.getDistance(y,K) << endl;
  }

  return 0;
}

