int V; // vertex count

void dijkstra(int s) {
    fill(d, d + V, infinite);
    fill(used, used + V, false);

    d[s] = 0;
    while(true) {
        int v = -1;
        // find minimum distance not used vertex
        for(int u = 0; u < V; u++) {
            if(!used[u] && (v == -1 || d[u] < d[v])) {
                v = u;
            }
        }

        if(v == -1) {
            break;
        }

        used[v] = true;
        for(int u = 0; u < V; u++) {
            d[u] = min(d[u], d[v] + cost[v][u]);
        }
    }
}


