ll query( int u, int v ) {
  ll r = 0;
  if( d[ u ] > d[ v ] ) {
    swap( u, v );
  }
  for( int j = LOG2-1; j >= 0; --j ) {
    if( dp[ v ][ j ] != -1 && d[ u ] <= d[ dp[ v ][ j ] ] ) {
      r += val[ v ][ j ];
      v = dp[ v ][ j ];
    }
  }
  if( u == v ) {
    return r;
  }
  for( int j = LOG2-1; j >= 0; --j ) {
    if( dp[ u ][ j ] != dp[ v ][ j ] ) {
      r += val[ u ][ j ];
      u = dp[ u ][ j ];
      r += val[ v ][ j ];
      v = dp[ v ][ j ];
    }
  }
  r += val[ u ][ 0 ];
  r += val[ v ][ 0 ];
  return r;
}

