//ダイクストラ法(蟻本p97)
struct edge {
  int to, cost;
};
typedef pair<int, int> P; // firstは最短距離、secondは頂点の番号

#define MAX_V 100001
#define INF (int64_t)pow(10, 18)
int V;
vector<edge> G[MAX_V];
int64_t d[MAX_V];

void dijkstra(int s) {
  // greater<P>を指定することでfirstが小さい順に取り出せるようにする
  priority_queue<P, vector<P>, greater<P>> que;
  fill(d, d + MAX_V, INF);
  d[s] = 0;
  que.push(P(0, s));

  while (!que.empty()) {
    P p = que.top();
    que.pop();
    int v = p.second;
    if (d[v] < p.first)
      continue;
