void dijkstra(int s)
{
	priority_queue<pair<long long int, int> > qu;
	qu.push(make_pair(0, s));
	while(!qu.empty()){
		long long int nowlen = -(qu.top()).first;
		int now = (qu.top()).second;
		qu.pop();
		if(pathlenfromk[now] >= 0) continue;
		pathlenfromk[now] = nowlen;
		for(int i = 0; i < tree[now].size(); i++){
			int next = tree[now][i].first;
			long long int c = tree[now][i].second;
			if(pathlenfromk[next] >= 0) continue;
			qu.push(make_pair(-(nowlen + c), next));
		}
	}
}

