//s番目の頂点から各頂点への最短距離を求める
void shortest_path(int s){
    rep(i, V)d[i] = INF;
    d[s] = 0;
    while(true){
        bool update = false;
        rep(i, E){
            edge e = es[i];
            if(d[e.from] != INF && d[e.to] > d[e.from] + e.cost){
                d[e.to] = d[e.from] + e.cost;
                update = true;
            }
        }
        if(!update) break;
    }
}


