				tree[a[i]].list[j] = tree[a[i]].child.size() - 1;
			}
		}
		tree[a[i]].list[b[i]] = tree[a[i]].child.size() - 1;
		for (int j = 0; j < N; j++){
			if (tree[j].list[a[i]] == -1) continue;

			for (int k = 0; k < N; k++){
				if (k == j || tree[j].list[k] != -1 || tree[a[i]].list[k] == -1) continue;

				tree[j].list[k] = tree[j].list[a[i]];
			}
		}

		tree[b[i]].child.push_back(a[i]);
		for (int j = 0; j < N; j++){
			if (j == b[i]) continue;

			if (tree[b[i]].list[j] == -1 && tree[a[i]].list[j] != -1){
				tree[b[i]].list[j] = tree[b[i]].child.size() - 1;
			}
		}
		tree[b[i]].list[a[i]] = tree[b[i]].child.size() - 1;
		for (int j = 0; j < N; j++){
			if (tree[j].list[b[i]] == -1) continue;

			for (int k = 0; k < N; k++){
				if (k == j || tree[j].list[k] != -1 || tree[b[i]].list[k] == -1) continue;

				tree[j].list[k] = tree[j].list[b[i]];
			}
		}

		cost[a[i]][b[i]] = c[i];
		cost[b[i]][a[i]] = c[i];
	}

	cin >> Q >> K;
	K--;
	x = vector<int>(Q);
	y = vector<int>(Q);
	for (int i = 0; i < Q; i++){
		cin >> x[i] >> y[i];
		x[i]--;
		y[i]--;
	}

	for (int i = 0; i < Q; i++){
		int start, end, now;
		long long int ans;

		start = x[i];
		end = y[i];
		now = start;

		ans = 0;
		while (now != K){
			int next = tree[now].child[tree[now].list[K]];
			ans += cost[now][next];
			now = next;
		}
		while (now != end){
			int next = tree[now].child[tree[now].list[end]];
			ans += cost[now][next];
			now = next;
		}

		cout << ans << endl;
	}

	return 0;
}

