template <typename F>
int lower_bound(int from, int until, const F& predicate) {
	while (from < until) {
		const auto mid = (from + until) / 2;
		if (predicate(mid)) until = mid;
		else from = mid + 1;
	}
	return until;
}
struct Edge {
	int to;
	long long int cost;
	Edge(const int t, const int c) :to{ t }, cost{ c }{};
};
int mlca(int a, int b, const std::vector<int>& depth, const std::vector<std::vector<int>>& parents) {
	while (a != b) {
		if (depth[a] == depth[b]) {
			auto first = lower_bound(0, parents[a].size(), [&parents, a, b](const int index) { return parents[a][index] == parents[b][index]; });
			if (first == 0) return parents[a].front();
			else {
				a = parents[a][first - 1];
				b = parents[b][first - 1];
			}
		}
		else if (depth[a] > depth[b]) {
			auto first = lower_bound(0, parents[a].size(), [&parents, &depth, a, b](const int index) {return depth[parents[a][index]] <= depth[b]; });
			if (first == 0) a = parents[a].front();
			else a = parents[a][first - 1];
		}
		else {
			auto first = lower_bound(0, parents[b].size(), [&parents, &depth, a, b](const int index) {return depth[parents[b][index]] <= depth[a]; });
			if (first == 0) b = parents[b].front();
			else b = parents[b][first - 1];
		}
	}
	return a;
}
int main() {
	std::cin.tie(0); std::ios::sync_with_stdio(false);
	int n; std::cin >> n;
	std::vector<std::vector<Edge>> nodes(n);
	for (auto i = 1; i < n; ++i) {
		int a, b, c; std::cin >> a >> b >> c;
		nodes[a - 1].emplace_back(b - 1, c);
		nodes[b - 1].emplace_back(a - 1, c);
	}
	std::vector<std::vector<int>> parents(n);
	std::queue<int> queue; queue.push(0);
	std::vector<int> depth(n, INT_MAX); depth[0] = 0;
	std::vector<long long int> length(n, 0);
	while (!queue.empty()) {
		auto current = queue.front(); queue.pop();
		for (const auto& e : nodes[current]) if (depth[e.to] > depth[current]) {
			parents[e.to].push_back(current);
			while (parents[e.to].size() <= parents[parents[e.to].back()].size()) {
				parents[e.to].push_back(parents[parents[e.to].back()][parents[e.to].size() - 1]);
			}
			depth[e.to] = depth[current] + 1;
			length[e.to] = length[current] + e.cost;
			queue.push(e.to);
		}
	}
	int q, k; std::cin >> q >> k; --k;
	for (auto i = 0; i < q; ++i) {
		int x, y; std::cin >> x >> y; --x; --y;
		auto ca = mlca(x, k, depth, parents);
		auto cb = mlca(y, k, depth, parents);
		std::cout << (length[x] + length[k] * 2 + length[y] - length[ca] * 2 - length[cb] * 2) << std::endl;
	}
}

