typedef long long lint;
const int  N=100010;
vector<pair<int,int> > adj[N];
int visit[N],parent[N],dist[N],depth[N];
lint ans;

void dfs(int n){
    int size=adj[n].size();
    for(int i=0;i<size;i++){
        int x=adj[n][i].first;
        int d=adj[n][i].second;
        if(!visit[x]){
            visit[x]=1;
            depth[x]=depth[n]+1;
            parent[x]=n;
            dist[x]=d;
            dfs(x);
        }
    }
}

void lca(int a,int b){
    while(a!=b){
        if(depth[a]<depth[b]){
            ans+=dist[b];
            b=parent[b];
        }else if(depth[a]>depth[b]){
            ans+=dist[a];
            a=parent[a];
        }else{
            ans+=dist[a];ans+=dist[b];
            a=parent[a];
            b=parent[b];
        }
    }
}

int main(void){
    int n;
    scanf("%d",&n);
    for(int i=1;i<n;i++){
        int a,b,c;
        scanf("%d %d %d",&a,&b,&c);
        adj[a].push_back(make_pair(b,c));
        adj[b].push_back(make_pair(a,c));
    }
    visit[1]=1;
    depth[1]=1;
    dfs(1);
    int q,k;
    scanf("%d %d",&q,&k);
    while(q--){
        int x,y;
        scanf("%d %d",&x,&y);
        ans=0;
        lca(x,k);
        lca(k,y);
        printf("%lld\n",ans);
    }
    return 0;
}

