class dijkstra{
  public:
    const int MAX_V = 1000000;
    vector<Edge> g[100000],rg[100000];
    bool visit[100000];

    int N;
    const ll INF = 1e15;
    dijkstra(){};
    dijkstra(int n):N(n){};
    vector<ll> shorter_path(int s){
      priority_queue<NODE> Q;
      Q.push({s,0});
      vector<ll> res(N,INF);
      while(Q.size()){
        NODE q= Q.top();Q.pop();
        if(res[q.pos] == INF){
          res[q.pos] = q.cost;
        }
        else{
          continue;
        }
        for(auto n : g[q.pos]){
          Q.push({n.to,q.cost+n.cost});
        }
      }
      return res;
    }
    void push(int p,int to,int c){
      g[p].push_back({to,c});
      rg[to].push_back({p,c});
    }
    deque<ll> Topological_sort(){
      deque<ll> res;
      rep(i,N){
        dfs(res,i);
      }
      return res;
    }
    void dfs(deque<ll> &res,int k){
      if(!visit[k]){
        visit[k] = true;
        for (auto&& nxt : g[k]) {
          dfs(res,nxt.to);
        }
        res.emplace_front(k);
      }
    }
    pll farthest_point(int n,int p){
      pll r = {0,n};
      for (auto&& k : g[n]) {
        if(k.to != p){
          pll res = farthest_point(k.to,n);
          res.fi += k.cost;
          if(r.fi < res.fi) r = res;
        }
      }
      return r;
    }
    ll diameter(){
      pll a = farthest_point(0,-1);
      pll b = farthest_point(a.se,-1);
      return b.fi;
    }
};

