vector<pair<int, int>> v(100001);
vector<long> a(100000), b(100000), c(100000);

void hoge(int pos, long dis) {
  int f = v.at(pos).first;
  if (a.at(f) == pos) {
    if (dist.at(b.at(f)) == LONG_MAX) {
      dist.at(b.at(f)) = dis + c.at(f);
      hoge(b.at(f), dist.at(b.at(f)));
    }
  } else {
    if (dist.at(a.at(f)) == LONG_MAX) {
      dist.at(a.at(f)) = dis + c.at(f);
      hoge(a.at(f), dist.at(a.at(f)));
    }
  }
  int s = v.at(pos).second;
  if (a.at(s) == pos) {
    if (dist.at(b.at(s)) == LONG_MAX) {
      dist.at(b.at(s)) = dis + c.at(s);
      hoge(b.at(s), dist.at(b.at(s)));
    }
  } else {
    if (dist.at(a.at(s)) == LONG_MAX) {
      dist.at(a.at(s)) = dis + c.at(s);
      hoge(a.at(s), dist.at(a.at(s)));
    }
  }
}

