  for (int i=0; i<N-1; i++) {
    cin >> a.at(i) >> b.at(i) >> c.at(i);
    if (v.at(a.at(i)).first == 0) {
      v.at(a.at(i)).first = i;
    } else {
      v.at(a.at(i)).second = i;
    }
    if (v.at(b.at(i)).first == 0) {
      v.at(b.at(i)).first = i;
    } else {
      v.at(b.at(i)).second = i;
    }
  }
  cin >> Q >> K;
  for (int i=1; i<=N; i++) {
    dist.at(i) = LONG_MAX;
  }
  dist.at(K) = 0;
  hoge(K, 0);

  for (int i=0; i<Q; i++) {
    int x, y;
    cin >> x >> y;
    cout << dist.at(x) + dist.at(y) << endl;
  }
}

