using namespace std;

vector < pair <int, int> > G[100005];

long long dis[100005];

int dep[100005];

int fa[100005][20];

void dfs(int u, int f) {
    fa[u][0] = f;
    for (int i = 1; i < 20; ++i)
        fa[u][i] = fa[fa[u][i - 1]][i - 1];
    for (auto &x : G[u]) {
        int v = x.first;
        if (v == f)
            continue;
        dep[v] = dep[u] + 1;
        dis[v] = dis[u] + x.second;
        dfs(v, u);
    }
}

int lca(int u, int v) {
    if (dep[u] < dep[v])
        swap(u, v);
    for (int i = 19; i >= 0; --i)
        if (dep[fa[u][i]] >= dep[v])
            u = fa[u][i];
    if (u == v)
        return u;
    for (int i = 19; i >= 0; --i)
        if (fa[u][i] ^ fa[v][i])
            u = fa[u][i], v = fa[v][i];
    return fa[u][0];
}

long long cal(int u, int v) {
    return dis[u] + dis[v] - 2 * dis[lca(u, v)];
}

int main() {
    int n;
    scanf("%d", &n);
    for (int i = 1; i < n; ++i) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        G[u].push_back( {v, w} );
        G[v].push_back( {u, w} );
    }
    dfs(1, 1);
    int q, k;
    scanf("%d%d", &q, &k);
    while (q--) {
        int u, v;
        scanf("%d%d", &u, &v);
        long long ans = cal(u, k) + cal(k, v);
        printf("%lld\n", ans);
    }
    return 0;
}

