using ll = long long;
const int N = 100500;

int n, q, root;
vector<pair<int, int>> go[N];
ll dist[N];

void dfs(int v, int p, ll d)
{
    dist[v] = d;
    for (auto e : go[v])
    {
        int to = e.first;
        int w = e.second;
        if (to == p)
            continue;
        dfs(to, v, d + w);
    }
}

void solve()
{
    scanf("%d", &n);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b, c;
        scanf("%d%d%d", &a, &b, &c);
        a--, b--;
        go[a].emplace_back(b, c);
        go[b].emplace_back(a, c);
    }
    scanf("%d%d", &q, &root);
    root--;
    dfs(root, -1, 0);
    for (int i = 0; i < q; i++)
    {
        int a, b;
        scanf("%d%d", &a, &b);
        a--, b--;
        printf("%lld\n", dist[a] + dist[b]);
    }
}

int main()
{
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
#endif

    solve();

    eprintf("\n\ntime = %.3lf\n", (double)clock() / CLOCKS_PER_SEC);
}

