        cin >> a >> b >> c;
        a--, b--;
        G[a].push_back({b, c});
        G[b].push_back({a, c});
    }

    ll Q, K;
    cin >> Q >> K;
    K--;
    dijkstra(K);
    rep(i, Q) {
        ll a, b;
        cin >> a >> b;
        a--, b--;
        cout << d[a] + d[b] << endl;
    }
}

#include<cstdio>
