using namespace std;
typedef long long weight;
weight const infty = 0x3fffffffffffff;
typedef pair<weight,int> edge;
class Graph{
    int numVertex;
    list<edge> *adj;
public:
    Graph(int v);
    void addEdge(int u,int v,weight w);
    void dijkstra(weight l[],int s);
};
//v頂点{0,1,...,v-1}0辺のグラフを作成
Graph::Graph(int v){
    this->numVertex=v;
    this->adj=new list<edge>[v];
}
//グラフに重さwの辺(u-v:無向グラフ)を追加
void Graph::addEdge(int u,int v,weight w){
    adj[u].push_back({w,v});
    adj[v].push_back({w,u});
}
//頂点sから点tへの最短経路l[t]を求める
void Graph::dijkstra(weight l[],int s){
    for(int i=0;i<numVertex;i++)l[i]=infty;
    l[s]=0;//l[始点]=0,l[それ以外]=無限大
    priority_queue<edge,vector<edge>,greater<edge>> pq;//firstを優先してソートするのでweightが先
    pq.push({0,s});//pq={(最短距離0,始点s)}
    while(!pq.empty()){
        int u=pq.top().second;//頂点を取得
        pq.pop();
        for(auto i=adj[u].begin();i!=adj[u].end();i++){
            int v=(*i).second;
            weight w=(*i).first;
            if(l[v]>l[u]+w){
                l[v]=l[u]+w;
                pq.push({l[v],v});
            }
        }
    }
}
