int main(){
    int n;
    scanf("%d",&n);
    Graph g(n+1);
    for(int i=1;i<n;i++){
        int a,b,c;
        scanf("%d%d%d",&a,&b,&c);
        g.addEdge(a,b,c);
    }
    int q,k;
