void dfs(const Graph &G, ll v, ll cost, bool _k, ll k) {
    seen[v] = true;
	costs[v] = cost;
	if(v == k) _k = true;
	th_k[v] = _k;
    for (auto next_v : G[v]) { 
        if (seen[next_v.to]) continue;
        dfs(G, next_v.to, cost + next_v.cost, _k, k);
    }
}
vector<pair<ll, ll>> dat;
vector<ll> vs;
vector<ll> depth;
vector<ll> id;


void update(ll k, ll a, ll n){
    k += n - 1;
    dat[k].first = a;
    dat[k].second = k - (n - 1);
    while(k > 0){
        k = (k - 1) / 2;
        if(dat[k * 2 + 1].first < dat[k * 2 + 2].first){
            dat[k].first = dat[k * 2 + 1].first;
            dat[k].second = dat[k * 2 + 1].second;
        }else{            
            dat[k].first = dat[k * 2 + 2].first;
            dat[k].second = dat[k * 2 + 2].second;
        }
    }
}

void rmq_init(vector<ll> a, ll n_){
    ll n = 1;
    while(n < n_) n *= 2;
    for(ll i = 0; i < 2 * n - 1; i++) dat[i] = make_pair(INF,-1);
    for(ll i = 0; i < a.size(); i++) update(i, a[i], n);
}

pair<ll, ll> query(ll a, ll b, ll k, ll l, ll r){
    if(r <= a || b <= l) return make_pair(INF, -1);
    if(a <= l && r <= b) return dat[k];
    else{
        pair<ll, ll> vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        pair<ll, ll> vr = query(a, b, k * 2 + 2, (l + r) / 2 + 1, r);
        if(vl.first < vr.first){
            return vl;
        }else{
            return vr;
        }
    }
}

void rmq_dfs(ll v, ll p, ll d, ll &k){
    id[v] = k;
    vs[k] = v;
    depth[k++] = d;
    for(ll i = 0; i < G[v].size(); i++){
        if(G[v][i].to != p){
            rmq_dfs(G[v][i].to, v, d + 1, k);
            vs[k] = v;
            depth[k++] = d;
        }
    }
}

vector<bool> lca_seen;
ll lca_dfs(ll v, ll count, ll g) {
    lca_seen[v] = true;
    count++;
    if (v == g) return count;

    for (auto next_v : G[v]) { 
        if (lca_seen[next_v.to]) continue;
        return lca_dfs(next_v.to, count, g);
    }
    return count;
}

void init(ll n, ll root){
    ll k = 0;
    rmq_dfs(root, -1, 0, k);
    rmq_init(depth, n * 2 - 1);
}

ll lca(ll u, ll v, ll n){
    return vs[query(min(id[u], id[v]), max(id[u], id[v]) + 1, 0, 0, 2 * n - 1).second];
}

int solve() {
    cin >> n;
