		Edge e2 = {a[i]-1, c[i]};
		G[b[i]-1].push_back(e2);
    }
    cin >> q >> k;
    x.resize(q);
    y.resize(q);
	dfs(G, 0, 0, false, k-1);
    REP(i, q){
        cin >> x[i] >> y[i];
		if((th_k[x[i]-1] && !th_k[y[i]-1]) || (!th_k[x[i]-1] && th_k[y[i]-1])){
			cout << lca_dfs(0,0,x[i]-1) + lca_dfs(0,0,y[i]-1) - 2*lca_dfs(0,0,lca(x[i]-1, y[i]-1, n)) << endl;
		}else if(!th_k[x[i]-1] && !th_k[y[i]-1]){
			cout << 2*costs[k-1] + costs[x[i]-1] + costs[y[i]-1] << endl;
		}else{
