vector<pll> G[100000];
ll cost[100000];
bool used[100000];

void dijkstra(int n) {
    used[n] = true;
    priority_queue<pll> que;
    for (auto e : G[n]) que.push(e);

    while (!que.empty()) {
        auto edge = que.top(); que.pop();
        if (used[edge.second]) continue;

        used[edge.second] = true;
        cost[edge.second] = edge.first;

        for (auto e : G[edge.second]) {
            if (used[e.second]) continue;
            que.push({e.first + edge.first, e.second});
        }
    }
}

