using namespace std;

#define REP(i, n) for (int i = 0; i < (int)(n); ++i)

const int
	MAXN = 100000,
	MAXLGN = 18;

int N, M;
long long dist[MAXN];
int level[MAXN];
int lca[MAXN][MAXLGN];
vector< pair<int, int> > G[MAXN];

int log2(int x)
{
	int lg = 1;
	while (1 << lg < x) lg++;
	return lg - 1;
}

int queryLCA(int u, int v)
{
	if (level[v] > level[u])
	      swap(u, v);

	for (int i = log2(level[u]); i >= 0; i--)
		if (level[u] - (1 << i) >= level[v])
		      u = lca[u][i];


	if (u == v) return u;

	for (int i = log2(level[u]); i >= 0; i--)
		if (lca[u][i] != lca[v][i])
		{
			u = lca[u][i];
			v = lca[v][i];
		}


	return lca[u][0];
}

int main()
{
	scanf( "%d", &N );
	REP(i, N - 1)
	{
		int u, v, w;
		scanf( "%d %d %d", &u, &v, &w );
        u --, v --;
		G[u].push_back(make_pair(v, w));
		G[v].push_back(make_pair(u, w));
	}

	queue< int > Q;
	for (Q.push(0), level[0] = 1; !Q.empty(); Q.pop())
	{
		int u = Q.front();
		REP(i, G[u].size())
		{
			int v = G[u][i].first;
			int w = G[u][i].second;
			if (level[v]) continue;

			Q.push(v);
			lca[v][0] = u;
			dist[v] = dist[u] + 1LL * w;
			level[v] = level[u] + 1;

			int lg = log2(level[v]);
			for (int i = 1; i <= lg; i++)
				lca[v][i] = lca[ lca[v][i - 1] ][i - 1];
		}
	}
	int k;
	cin >> M >> k;
	k --;
	while (M--)
	{
		int u, v;
		scanf( "%d %d", &u, &v );
		u --, v --;
		int z = queryLCA(u, k);
		long long res = dist[u] + dist[k] - 2 * dist[z];
		z = queryLCA(k, v);
		res += dist[k] + dist[v] - 2 * dist[z];
		cout << res << endl;
	}

	return 0;
}

