using namespace std;

typedef long long ll;

int N;
vector<int> T[100000];
vector<int> C[100000];

ll cost;

ll dfs(int n, int pre, int goal) {
	//printf("%d", n);
	if (n == goal)
		return cost;
	for (int i = 0; i < T[n].size(); ++i) {
		if (pre == T[n][i])
			continue;
		cost += C[n][i];
		int t;
		if ((t = dfs(T[n][i], n, goal)) > 0) {
			//printf("<=>%d\n",cost);
			return t;
		}
		else {
			//printf("\b");
			cost -= C[n][i];
		}
	}
	return -1;
}


int main() {
	cin >> N;
	for (int i = 0; i < N-1; ++i)
	{
		int a,b,c;
		cin >> a >> b >> c;
		T[a].push_back(b);
		T[b].push_back(a);
		C[a].push_back(c);
		C[b].push_back(c);
	}
	int Q, K;
	cin >> Q >> K;
	for (int j = 0; j < Q; ++j) {
		int s, g;
		cin >> s >> g;
		cost = 0;
		dfs(s, 0, K);
		cout << dfs(K, 0, g) << endl;
	}

}

