#define  pb push_back  
#define  mp make_pair  
#define  sz(x) ((int)(x).size())  
using namespace std;  
typedef long long int LL;
const int N = 1e5+24;  
const LL INF = 1e15;  
int n, q,st;
LL dis[N];  
bool vis[N];  
struct Node {  
    LL d;
	int e;  
    bool operator < (const Node x) const {  
        return x.d < d;  
    }  
    Node(LL d, int e):d(d), e(e){}  
};  
vector<pair<int, LL> > V[N];  

void dijkstra(int s) {  
    priority_queue<Node> q;  
    fill(dis + 1, dis + n + 1, INF);  
    fill(vis + 1, vis + n + 1, false);  
    q.push(Node(0, s));  
    dis[s] = 0;  
    while(!q.empty()) {  
        Node deq = q.top(); q.pop();  
        if(vis[deq.e])    
            continue;  
        vis[deq.e] = true;  
        for(int i = 0;i < sz(V[deq.e]);i++) {  
            int e = V[deq.e][i].first;  
            LL w = V[deq.e][i].second;  
            if(dis[deq.e] < dis[e] - w) {  
                dis[e] = dis[deq.e] + w;  
                q.push(Node(dis[e], e));      
            }  
        }  
    }     
}  

int main(){  
    while(~scanf("%d",&n)) {  
        for(int i = 1;i <= n;i++)  
            V[i].clear();  
        for(int i = 1;i < n;i++) {  
            int a, b; LL w;  
            scanf("%d%d%I64d", &a, &b, &w);  
            V[a].pb(mp(b, w));  
            V[b].pb(mp(a, w));    
        }  
		scanf("%d%d",&q,&st);
        dijkstra(st);
		for(int i=1;i<=q;i++){
			int a,b;
			scanf("%d%d",&a,&b);
			printf("%I64d\n", dis[a]+dis[b]);  
		}
    }  
    return 0;  
}

