const ll INF=1000000000000000000;

struct edge {
    ll to;
    ll cost;
};
// <最短距離, 頂点の番号>
using P = pair<ll, ll>;



void dijkstra(vector<edge> *G, ll V, ll s, ll *d) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d+V, INF);
    que.push(P(0, s));
    d[s]=0;

    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (d[v] < p.first) continue;

        for (ll i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

