    for (int i = 0; i <= n; ++i) {
        D[i] = INF;
    }

    priority_queue< Edge > pq;
    pq.push(Edge(k, 0));

    D[k] = 0;

    while (!pq.empty()) {
        Edge top = pq.top();
        pq.pop();

        if (visited[top.nod]) continue;

        visited[top.nod] = true;

        for (Edge edge: G[top.nod]) {
            if (D[top.nod] + edge.cost < D[edge.nod]) {
                D[edge.nod] = D[top.nod] + edge.cost;

                pq.push(Edge(edge.nod, -D[edge.nod]));
            }
        }
    }

    while (q--) {
        cin >> a >> b;

        cout << D[a] + D[b] << "\n";
    }

    return 0;
}

