template <typename T> class Graph {
public:
	struct edge {
		int from;
		int to;
		T cost;
	};

	int n;
	vector<edge> edges;
	vector<vector<int>> graph;	

	Graph(int _n) : n(_n) {
		graph.resize(n);
	}

	int add_edge(bool undirected, int from, int to, T cost = 1){
		assert(0 <= from && from < n && 0 <= to && to < n);
		const int id = (int) edges.size();
		graph[from].push_back(id);
		if(undirected) graph[to].push_back(id);
		edges.push_back({from, to, cost});
		return id;
	}

	void dfs(int v,int p, T d);
};

