void dfs(int n){
    int size=adj[n].size();
    for(int i=0;i<size;i++){
        int x=adj[n][i].first;
        int d=adj[n][i].second;
        if(!visit[x]){
            visit[x]=1;
            depth[x]=depth[n]+1;
            parent[x][0]=n;
            dist[x][0]=d;
            dfs(x);
        }
    }
}

void lca(int a,int b){
    if(depth[a]<depth[b])swap(a,b);
    int dif=depth[a]-depth[b];
    for(int i=0;dif;i++){
        if(dif%2){
            ans+=dist[a][i];
            a=parent[a][i];
        }
        dif/=2;
    }
    if(a!=b){
        for(int i=49;i>=0;i--)
            if(parent[a][i]!=-1&&parent[a][i]!=parent[b][i]){
                ans+=dist[a][i];ans+=dist[b][i];
                a=parent[a][i];
                b=parent[b][i];
            }
        ans+=dist[a][0];ans+=dist[b][0];
    }
}

