        while (!queue.empty()) {
            pair<ll, ll> p = queue.top();
            queue.pop();
            ll v = p.second;

            if (dis2[v] < p.first) {
                continue;
            }

            for (ll i = 0; i < ki[v].size(); i++) {
                if (dis2[ki[v][i].fi] > dis2[v] + ki[v][i].se) {
                    dis2[ki[v][i].fi] = dis2[v] + ki[v][i].se;
                    queue.push(mp(dis2[ki[v][i].fi], ki[v][i].fi));
                }
            }
        }
        ans += dis2[y];

//    dbg(dis2);

        cout << ans << endl;
    }
    return  0;

}

