const int MAXN=1e5+24;
struct ArcNode{
	int to;
	int weight;
	ArcNode *next;
};
queue<int> Q; 
int n;   
ArcNode* List[MAXN];  
int inq[MAXN];
LL dist[MAXN],path[MAXN];
void SPFA(int src){
	int i,u;   
	ArcNode* temp;
	for(i=1;i<=n;i++){
		dist[i]=INF;
		path[i]=src;
		inq[i]=0;
	}
	dist[src]=0; path[src]=src; inq[src]++;
	Q.push(src);  
	while(!Q.empty()) {
		u=Q.front();
		Q.pop();
		inq[u]--;
		temp=List[u];
		while(temp!=NULL){
			int v=temp->to;
			if(dist[v]>dist[u]+temp->weight){
				dist[v]=dist[u]+temp->weight;
				path[v]=u;
				if(!inq[v]){
					Q.push(v);
					inq[v]++;
				}
			}
			temp=temp->next;
		}
	}
}
