struct LCA{
  int ln;
  vector<vector<pair<int, ll> > > *G;
  vvi parent;
  vi depth;
  vl dd;
  void dfs(int pos, int pre, int d){
    depth[pos] = d;
    each(itr, (*G)[pos]){
      if(pre == itr->fi) continue;
      parent[0][itr->fi] = pos;
      dd[itr->fi] = dd[pos] + itr->se;
      dfs(itr->fi, pos, d+1);
    }
  }
  int root(int a, int b){
    if(depth[a] > depth[b]) swap(a, b);
    int d = depth[b] - depth[a];
    FOR(i, 0, ln) if((1<<i)&d) b = parent[i][b];
    if(a == b) return a;
    FORR(i, ln-1, 0) if(parent[i][a] != parent[i][b]) a = parent[i][a], b = parent[i][b];
    return parent[0][a];
  }
  void build(vector<vector<pair<int, ll> > > *G, int r){
    this->G = G;
    int n = sz(*G);
    for(ln = 0; (1<<ln) < n; ln++);
    parent = vvi(n);
    FOR(i, 0, ln) parent[i] = vi(n);
    depth = vi(n);
    dd = vl(n);
    dfs(r, -1, 0);
    FOR(i, 1, ln)FOR(j, 0, n) parent[i][j] = (parent[i-1][j] == -1 ? -1 : parent[i-1][parent[i-1][j]]);
  }
};

