// ダイクストラ法
struct Dijkstra {
    int n;
    vector<bool> used;
    vector<int64_t> d;
    vector<int> prev;
    vector<vector<int64_t>> dist;
    Dijkstra(int _n) {
        init(_n);
    }
    void init(int _n) {
        n = _n;
        d.clear();
        used.clear();
        prev.clear();
        dist.clear();
        d.resize(n, INFL);
        used.resize(n, false);
        prev.resize(n, -1);
        dist.resize(n, vector<int64_t>(n, INFL));
    }
    void dijkstra(int s) {
        fill(d.begin(), d.end(), INFL);
        fill(used.begin(), used.end(), false);
        fill(prev.begin(), prev.end(), -1);
        d[s] = 0;
        while (true) {
            int v = -1;
            for (int u = 0; u < n; u++) {
                if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
            }
            if (v == -1) break;
            used[v] = true;
            for (int u = 0; u < n; u++) {
                if (d[u] > d[v] + dist[v][u]) {
                    d[u] = d[v] + dist[v][u];
                    prev[u] = v;
                }
            }
        }
    }

};
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll N;
        in >> N;
        Dijkstra dk(N);
        vll a(N), b(N), c(N);
        rep(i, N - 1) {
            in >> a[i] >> b[i] >> c[i];
            dk.dist[a[i] - 1][b[i] - 1] = c[i];
            dk.dist[b[i] - 1][a[i] - 1] = c[i];
        }
        ll Q, K;
        in >> Q >> K;
        vll x(Q), y(Q);
        rep(i, Q) {
            in >> x[i] >> y[i];
            dk.dijkstra(K - 1);
            ll ans = dk.d[x[i] - 1] + dk.d[y[i] - 1];
            out << ans << endl;
        }
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
