const int INFTY = 1001001001;

class BFS
{
public:
    vector<vector<long long>> costs;
    vector<vector<int>> edges;
    vector<long long> dist;
    vector<int> state;
    int N, M;
    BFS()
    {
        cin >> N;
        M = N - 1;
        costs.resize(N, vector<long long>(N));
        edges.resize(N);
        dist.resize(N, INFTY);
        state.resize(N);
        int a, b, c;
        for (int i = 0; i < M; ++i)
        {
            cin >> a >> b >> c;
            --a;
            --b;
            edges[a].push_back(b);
            edges[b].push_back(a);
            costs[a][b] = costs[b][a] = c;
        }
    }

    void step(int root)
    {
        int node = root;
        queue<int> Q;
        Q.push(node);
        dist[node] = 0;
        while (!Q.empty())
        {
            node = Q.front();
            Q.pop();
            if (state[node] != 1)
            {
                for (int e : edges[node])
                {
                    if (state[e] != 1)
                    {
                        Q.push(e);
                        dist[e] = dist[node] + costs[node][e];
                    }
                }
                state[node] = 1;
            }
        }
    }
};


int main()
{
    BFS bfs;
    int Q, K;
    cin >> Q >> K;
    --K;
    bfs.step(K);
    int x, y;
    for (int i = 0; i < Q; ++i)
    {
        cin >> x >> y;
        --x;
        --y;
        cout << bfs.dist[x] + bfs.dist[y] << endl;
    }
}

