using namespace std;

const int MAX = 1e5 + 10;
int n;
int q, k;
vector<pair<int, long long>> G[MAX];
long long minDist[MAX];

int main() {
  scanf("%d", &n);
  for (int i = 0; i < n - 1; i++) {
    int a, b, c;;
    scanf("%d%d%d", &a, &b, &c);
    a--;b--;
    G[a].emplace_back(make_pair(b, c));
    G[b].emplace_back(make_pair(a, c));
  }
  scanf("%d%d", &q, &k);
  k--;
  fill(minDist, minDist + MAX, 1e9);
  priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
  pq.push({0, k});
  minDist[k] = 0;
  while (!pq.empty()) {
    auto now = pq.top(); pq.pop();
    for (auto nxt : G[now.second]) {
      const long long nxtCost = now.first + nxt.second;
      if (minDist[nxt.first] <= nxtCost) {
        continue;
      }
      minDist[nxt.first] = nxtCost;
      pq.push({nxtCost, nxt.first});
    }
  }
  for (int i = 0; i < q; i++) {
    cerr << "problem " << i + 1 << " solved" << endl;
    int x, y;
    scanf("%d%d", &x, &y);
    x--;y--;
    cout << minDist[x] + minDist[y] << endl;
  }

  return 0;
}

