void dk(int s) {
  fill(d, d + V, 10000000000);
  fill(used, used + V, false);
  d[s] = 0;

  while (true) {
    int v = -1;
    rep(u, V){
      if (!used[u] && (v == -1 || d[u] < d[v])) {
        v = u;
      }
    }
    if (v == -1) break;
    used[v] = true;
    rep(u, V){
      d[u] = min(d[u], d[v] + cost[v][u]);
    }
  }
}

