void dijkstra(vector<VP> &g, ll start, Vec &dist) {
    priority_queue<P, vector<P>, function<bool(P, P)>> q([](P a, P b)->ll {
        return a.second > b.second;
    });
    dist[start] = 0;
    q.push(mp(start, 0));
    while (!q.empty()) {
        P now = q.top();
        q.pop();
        Each(nxt, g[now.fi]) {
            if(chmin(dist[nxt.fi], now.se+nxt.se)) {
                q.push(mp(nxt.fi, dist[nxt.fi]));
            }
        }
    }
}


