void bfs(int k){
    dis[k]=-1;
    queue<P> que;
    que.push(P(k, 0));

    while(!que.empty()){
        P q=que.front(); que.pop();
        int now_v=q.first;
        ll now_cost=q.second;

        for(int i=0; i<tree[now_v].size(); i++){
            int next_v=tree[now_v][i].first;
            ll path_cost=tree[now_v][i].second;

            if(dis[next_v] == 0){
                dis[next_v]=now_cost+path_cost;
                que.push(P(next_v, dis[next_v]));
            }
        }
    }
}

