using namespace std;

typedef long long ll;

struct Edge {
  int to;
  ll cost;

  Edge(int to, ll cost) {
    this->to = to;
    this->cost = cost;
  }
};

int main() {
  int N;
  cin >> N;
  vector<vector<Edge>> edgesFor = vector<vector<Edge>>(N);
  rep(i, N - 1) {
    int a, b, c;
    cin >> a >> b >> c;
    a--;
    b--;
    Edge e1(b, c);
    edgesFor[a].push_back(e1);
    Edge e2(a, c);
    edgesFor[b].push_back(e2);
  }

  int Q, K;
  cin >> Q >> K;
  K--;

  vector<ll> ds(N); // Kからの最短距離
  fill(ds.begin(), ds.end(), INFL);
  deque<int> queue;
  queue.push_back(K);
  ds[K] = 0;
  unordered_set<int> checkedSet;
  checkedSet.insert(K);
  while (!queue.empty()) {
    int i = queue.front();
    queue.pop_front();

    ll d = ds[i];
    for (Edge e : edgesFor[i]) {
      if (checkedSet.count(e.to)) {
        continue;
      }

      ds[e.to] = min(d + e.cost, ds[e.to]);
      queue.push_back(e.to);
      checkedSet.insert(e.to);
    }
  }

  rep(i, Q) {
    int x, y;
    cin >> x >> y;
    x--;
    y--;

    cout << (ds[x] + ds[y]) << endl;
  }
}

