#define MAX_LOG 22
int lca(int a, int b){
		if (d[a] < d[b]){
			swap(a, b);
		}
		for (int i = 0; i < MAX_LOG; i++){
			if (((d[a] - d[b]) >> i) & 1){
				a = par[i][a];
			}
		}
		if (a == b){
			return a;
		}
		for (int i = MAX_LOG - 1; i >= 0; i--){
			if (par[i][a] != par[i][b]){
				a = par[i][a];
				b = par[i][b];
			}
		}
		return par[0][a];
	}
ll dist(int x,int y){
	return d[x]+d[y]-d[lca(x,y)]*2;
}
