// {{{
struct LowestCommonAncestor{
    int n,h;
    vector< vector<int> > G,par;
    vector<int> dep;
    LowestCommonAncestor(){}
    LowestCommonAncestor(int n):n(n),G(n),dep(n){
        h=1;
        while((1<<h)<=n) h++;
        par.assign(h,vector<int>(n,-1));
    }

    void add_edge(int u,int v){
        G[u].emplace_back(v);
        G[v].emplace_back(u);
    }

    void dfs(int v,int p,int d){
        par[0][v]=p;
        dep[v]=d;
        for(int u:G[v])
            if(u!=p) dfs(u,v,d+1);
    }

    void build(int r=0){
        dfs(r,-1,0);
        for(int k=0;k+1<h;k++)
            for(int v=0;v<n;v++)
                if(~par[k][v])
                    par[k+1][v]=par[k][par[k][v]];
    }

    int lca(int u,int v){
        if(dep[u]>dep[v]) swap(u,v);
        for(int k=0;k<h;k++)
            if((dep[v]-dep[u])>>k&1)
                v=par[k][v];

        if(u==v) return u;

        for(int k=h-1;k>=0;k--)
            if(par[k][u]!=par[k][v])
                u=par[k][u],v=par[k][v];

        return par[0][u];
    }

    int distance(int u,int v){
        return dep[u]+dep[v]-dep[lca(u,v)]*2;
    }
};
// }}}

void solver() {
    int n = input();

    struct edge {
        int to;
        i64 cost;
        edge() {}
        edge(int to, i64 cost) : to(to), cost(cost) {}
    };

    auto G = make_vector(n, 0, edge());
    LowestCommonAncestor lca(n);

    range(i, 0, n - 1) {
        int u = input() - 1, v = input() - 1, c = input();
        G[u].emplace_back(v, c);
        G[v].emplace_back(u, c);
        lca.add_edge(u, v);
    }

    lca.build();

    vector< i64 > dists(n, -1);
    dists[0] = 0;
    queue< int > que({0});
    while (!que.empty()) {
        int v = que.front();
        que.pop();

        for (auto &e: G[v]) {
            if (dists[e.to] != -1) continue;
            dists[e.to] = dists[v] + e.cost;
            que.emplace(e.to);
        }
    }

    auto get_distance = [&](int u, int v) {
        return dists[u] + dists[v] - 2 * dists[lca.lca(u, v)];
    };

    int q = input(), k = input() - 1;
    range(i, 0, q) {
        int x = input() - 1, y = input() - 1;
        cout << get_distance(x, k) + get_distance(k, y) << endl;
    }
}

signed main(int argc, char *argv[]) {
    solver();
}

