  Edge(int s, int t, Cost c) : from(s), to(t), cost(c) {}
};

template<typename Cost> using Graph = vector<vector<Edge<Cost>>>;

template <typename Cost>
void add_edge(Graph<Cost> &g, int from, int to, Cost cost) {
  g[from].emplace_back(from, to, cost);
}

template <typename Cost>
vector<Cost> dijkstra(const Graph<Cost> &g, int s, Cost zero = 0) {
  vector<Cost> d(g.size(), ll(1e18));
  d[s] = zero;
  using P = pair<Cost,int>;
  priority_queue<P, vector<P>, greater<P>> que;
  que.push(P(zero, s));
  while (!que.empty()) {
    Cost dist = que.top().first;
    int v = que.top().second;
    que.pop();
    if (d[v] < dist) continue;
    for (const auto &e: g[v]) {
      if (d[e.to] <= d[v] + e.cost) continue;
      d[e.to] = d[v] + e.cost;
      que.push(P(d[e.to], e.to));
    }
  }
  return d;
}

void solve(ll N, vector<ll> a, vector<ll> b, vector<ll> c, ll Q, ll K, vector<ll> x, vector<ll> y) {
  Graph<ll> g(N);
  REP(i,N-1) {
    add_edge(g, a[i] - 1, b[i] - 1, c[i]);
    add_edge(g, b[i] - 1, a[i] - 1, c[i]);
  }
  auto dist = dijkstra(g, K - 1);
  REP(i,Q) {
    int s = x[i] - 1, t = y[i] - 1;
    cout << dist[s] + dist[t] << endl;
  }
}

