typedef long long ll;
const int MAX_N = 100000;

int main() {
  int N, Q, K;

  std::cin >> N;
  std::vector<std::vector<std::pair<int, ll>>> e(N);
  for(int i = 0; i < N - 1; ++i) {
    int a, b;
    ll c;
    std::cin >> a >> b >> c;
    e[a - 1].push_back(std::make_pair(b, c));
    e[b - 1].push_back(std::make_pair(a, c));
  }

  std::cin >> Q >> K;
  ll d[MAX_N + 1] = {};

  std::stack<int> s;
  s.push(K);

  while(!s.empty()) {
    int x = s.top(); s.pop();
    for(auto p : e[x - 1]) {
      int y = p.first;
      if(y == K or d[y] > 0) continue;
      d[y] = d[x] + p.second;
      s.push(y);
    }
