  ll ans[MAX_N];
  for(int i = 0; i < Q; ++i) {
    int x, y;
    std::cin >> x >> y;
    ans[i] = d[x] + d[y];
  }

  for(int i = 0; i < Q; ++i) {
    std::cout << ans[i] << std::endl;
  }
}

