vec<ll> dijkstra(mat<pi> G,int K){
  vec<ll> res(G.size(),LLONG_MAX);
  rpq<pi> que;
  res[K]=0;
  que.emplace(res[K],K);
  while(!que.empty()){
    ll cost,now; tie(cost,now)=que.top(); que.pop();
    if(res[now]<cost) continue;
    for(auto &e:G[now]){
      ll ncost=cost+e.second;
      if(res[e.first]<=ncost) continue;
      res[e.first]=ncost;
      que.emplace(res[e.first],e.first);
    }
  }
  return res;
}

