    a--;
    b--;
    d.addEdge(a, b, c);
    d.addEdge(b, a, c);
  }
  ll q, k;
  cin >> q >> k;
  k--;
  d.exec(k);
  rep(i, q) {
    ll x, y;
    cin >> x >> y;
    x--;
    y--;
    cout << d.dist(x) + d.dist(y) << endl;
  }
  return 0;
}

