			dr = other[dt];
			if(dis[now] + cost[dt] < dis[dr]){
				dis[dr] = dis[now] + cost[dt];
				if(!Inque[dr]){
					Inque[dr] = 1; 
					seq[++tail] = dr;
				}
			}
			dt = pre[dt];
		}
		Inque[now] = 0;
		head++;
	}
}

