int d[MAX_N+1][MAX_N+1];
bool visit[MAX_N+1];

long long dfs(int x, int y, long long distance){
   if(x==y) return distance;
   if(visit[x]) return INF;
   visit[x] = true;

   long long min;
   bool first = true;
   for(int i=1; i<=N; ++i){
      if(d[x][i]>0){
	 if(first){
	    min = dfs(i,y,distance+d[x][i]);
	    first = false;
	 }else min = std::min(min,dfs(i,y,distance+d[x][i]));
      }
   }
   return min;
}

