	rep(i, n - 1) {
		ll a, b, c;
		cin >> a >> b >> c;
		adj[a - 1].push_back(make_pair(b - 1, c));
		adj[b - 1].push_back(make_pair(a - 1, c));
	}

	int Q, K;
	cin >> Q >> K;

	vector<ll> v;
	dijkstra(K - 1);
	rep(i, Q) {
		int x, y;
		cin >> x >> y;

		ll k_shortest = d[x - 1];
		ll  y_shortest = d[y - 1];

		v.push_back(k_shortest + y_shortest);
	}

	for (vector<ll>::iterator it = v.begin(); it != v.end(); it++) {
		cout << *it << endl;
	}
	return 0;
}

