void dfs(int node,int lv,int pa,int pa_edge){
    visited[node]=true;
    level[node]=lv;
    parent[node]=pa;
    parent_edge[node]=pa_edge;
    for(int i=0;i<adj[node].size();i++)if(!visited[adj[node][i].F])dfs(adj[node][i].F,lv+1,node,adj[node][i].S);
}
void compute(){
    int i,j,k;
    dfs(1,1,1,0);
    for(i=1;i<=n;i++){
        sparse[i][0]=parent[i];
        weight[i][0]=parent_edge[i];
    }
    for(j=1;j<=LN;j++)for(i=1;i<=n;i++){
        sparse[i][j]=sparse[sparse[i][j-1]][j-1];
        weight[i][j]=weight[i][j-1]+weight[sparse[i][j-1]][j-1];
    }
}
int lca(int a,int b){
    if(level[a]>level[b])swap(a,b);
    int temp=level[b]-level[a];
    for(int j=LN;j>=0;j--)if((temp>>j)&1)b=sparse[b][j];
    if(a==b)return a;
    for(int j=LN;j>=0;j--)if(sparse[a][j]!=sparse[b][j]){
        a=sparse[a][j];
        b=sparse[b][j];
    }
    return parent[a];
}
ll queryup(int a,int b){
    int temp=level[a]-level[b];
    ll ret=0;
    for(int j=LN;j>=0;j--)if((temp>>j)&1){
