	Bfs(b);
	for(int i = 1; i <= a; i++)
	{
		LL ans = 0;
		int x, y;
		scanf("%d %d", &x, &y);
		ans += dis[x];
		ans += dis[y];
		printf("%lld\n", ans);
	}
	return 0;
}

