      for(auto nn:ed[tp.second]){
        if(dist[nn.to]!=-1)continue;
        q.push({nn.cost+tp.first,nn.to});
      }
    }
    return dist[end];
  }
  ll getd(ll end){
    return dist[end];
  }
};
