void SE(int u, int v, int w){
	to[++ tot] = v; nex[tot] = head[u]; head[u] = tot; val[tot] = w;
}

void DFS(int x){
	siz[x] = 1;
	for(int i = head[x]; i; i = nex[i]){
		if(dep[to[i]]) continue;
		dep[to[i]] = dep[x] + 1;
		fa[to[i]] = x;
		dis[to[i]] = dis[x] + val[i];
		DFS(to[i]);
		if(siz[to[i]] > siz[son[x]]) son[x] = to[i];
		siz[x] += siz[to[i]];
	}
	return;
}

void RDFS(int x, int f){
	top[x] = f;
	if(!son[x]) return;
	RDFS(son[x], f);
	for(int i = head[x]; i; i = nex[i])
		if(to[i] != fa[x] && to[i] != son[x])
			RDFS(to[i], to[i]);
	return;
}

int LCA(int x, int y){
	for(int fx = top[x], fy = top[y]; fx != fy; x = fa[fx], fx = top[x])
		if(dep[fx] < dep[fy]) swap(fx, fy), swap(x, y);
	if(dep[x] > dep[y]) return y;
	return x;
}

