void shortest (int a, int b, vector <set <pair<int, int>>> & v, long long len, long long & res, set <int> made) {
  for (auto elem : v[a - 1]) {
  if (elem.first == b) res = min(res, len + elem.second);
  else {
    if (!made.count(elem.first)) {
    made.insert(elem.first);
    shortest(elem.first, b, v, len + elem.second, res, made);
    made.erase(made.lower_bound(elem.first));
    }
  }
  }

}

