//int cost[MAX_V][MAX_V];
ll d[MAX_V];
//bool used[MAX_V];
ll V;
struct edge {
	ll to, cost;
};
vector<edge> G[MAX_V];


// O(ElogV)
void dijkstra(ll s) {
	fill(d, d + V, INF);
	d[s] = 0;
	priority_queue<P, vector<P>, greater<P> > q;
	q.push(make_pair(0, s)); // distance, index)

	while(!q.empty()) {
		P p = q.top();
		q.pop();
		ll v = p.second;
		if(d[v] < p.first) continue;
		rep(i, 0, G[v].size()) {
			edge e = G[v][i];
			if(d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				q.push(P(d[e.to], e.to));
			}
		}
	}
}

