int depth[114514];
int dist[114514];
int n;
void lcadfs(int v,int p,int d){
	par[0][v] = p;
	depth[v] = d;
	for(int i=0;i<nex[v].size();i++){
		if( nex[v][i].to != p ) lcadfs( nex[v][i].to, v, d+1 );
	}
}
int lca(int u,int v){
	if(depth[u] > depth[v]) swap(u,v);
	for(int k=0;k<=17;k++){
		if( ( (depth[v] - depth[u] ) >> k ) & 1 ){
			v = par[k][v];
		}
	}
	if( u == v )return u;
	for(int k=17;k>=0;k--){
		if( par[k][u] != par[k][v] ){
			u = par[k][u];
			v = par[k][v];
		}
	}
	return par[0][u];
}
void init(int n){
	lcadfs(1,0,0);
	for(int k=0;k<=17;k++){
		for(int v=1;v<=n;v++){
			if( par[k][v] <= 0 )par[k+1][v]=0;
			par[k+1][v] = par[k][par[k][v]];
		}
	}
}
