		nex[b].pb( (edge){ a, c} );
	}
	init(n);
	queue< pair<int,int> > que;
	que.push(mp(1,-1));
	while( !que.empty() ){
		int cur = que.front().first;
		int par = que.front().second; 
		que.pop();
		for(int i=0;i<nex[cur].size();i++){
			int nx = nex[cur][i].to;
			if( nx != par ){
				dist[nx] = dist[cur] + nex[cur][i].cost;
				que.push( mp( nx, cur ) );
			}
		}
	}
	int q,k;
	cin>>q>>k;
	vector<int> ans;
	for(int i=0;i<q;i++){
		int x,y;
		cin>>x>>y;
		int d1 = dist[x] + dist[k] - 2 * dist[lca(x,k)];
		int d2 = dist[y] + dist[k] - 2 * dist[lca(y,k)];
		ans.pb(d1+d2);
	}
	for(int i=0;i<q;i++){
		cout<<ans[i]<<endl;
	}
	return 0;
}

