	llong cost;

	data(){};
	data(llong place, llong cost) :
		place(place),
		cost(cost)
	{}

	bool operator<(const data &ri) const{
		return cost < ri.cost;
	}
	bool operator>(const data &ri) const{
		return cost > ri.cost;
	}
};

vector<vector<P> > edges;
vector<llong> dis;
llong Dijkstra(int start){
	priority_queue<data, vector<data>, greater<data> > q;
	dis[start] = 0;

	q.push(data(start, 0));
	while(q.size()){
		data now = q.top(); q.pop();
		if(dis[now.place] < now.cost) continue;

		for(int i = 0; i < edges[now.place].size(); i++){
			P edge = edges[now.place][i];
			data next(edge.first, now.cost + edge.second);
			if(dis[next.place] <= next.cost) continue;
			dis[next.place] = next.cost;
			q.push(next);
		}
	}

	return -1;
}

