void bfs(int k) {

    queue<int> q;
    q.push(k);
    ll u;
    cost[k] = 0;
    while (!q.empty()) {
        u = q.front(); q.pop();
        for (int v = 0; v < G[u].size(); v++) {
            P p = G[u][v];
