long long dfs(int v, const Graph &G, vector<bool> seen){
    if(v == dest) return 0;;
    seen[v] = true;
    long long res = 1e12;
    for(auto next : G[v]) {
        if(seen[next.to]) continue;
        res = min(res, dfs(next.to, G, seen) + next.weight);
    }
    seen[v] = false;
    return res;
}

