vector<bool> seen;
vector<ll> kyo;
void dfs(const Graph& G, int v) {
    seen[v] = true; // v を訪問済にする

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) {
        if (seen[next_v.first]) continue; // next_v が探索済だったらスルー
        kyo[next_v.first] = kyo[v] + next_v.second;
        dfs(G, next_v.first); // 再帰的に探索
    }
}



