typedef long long ll;
const int maxn= 100005;
const int mod = 475;
const ll INF = 0x3f3f3f3f;
const double eps = 1e-6;


int n;
int cnt;
int vis[maxn];
int pre[maxn];
int head1[maxn],head2[maxn];
ll dis[maxn];

struct node
{
    int s,t,w,lca,next;
}e1[maxn*2],e2[maxn*4];

void init()
{
    mst(vis,0);
    mst(dis,0);
    mst(head1,-1);
    mst(head2,-1);
    for(int i=1;i<=n;i++)
        pre[i]=i;
}

int find(int x)
{
    int t,r=x;
    while(x!=pre[x])
    {
        x=pre[x];
    }
    while(r!=x)
    {
        t=pre[r];
        pre[r]=x;
        r=t;
    }
    return x;
}

void join(int a,int b)
{
    int A,B;
    A=find(a);
    B=find(b);
    if(A!=B)
        pre[B]=A;
}
void add1(int s,int t,int w)
{
    e1[cnt].s=s;
    e1[cnt].t=t;
    e1[cnt].w=w;
    e1[cnt].next=head1[s];
    head1[s]=cnt++;
}

void add2(int s,int t)
{
    e2[cnt].s=s;
    e2[cnt].t=t;
    e2[cnt].lca=-1;
    e2[cnt].next=head2[s];
    head2[s]=cnt++;
}

void Tarjan(int now)
{
    vis[now]=1;
    for(int i=head1[now];i!=-1;i=e1[i].next)
    {
        int t=e1[i].t;
        if(vis[t]==0)
        {
            int w=e1[i].w;
            dis[t]=dis[now]+w;
            Tarjan(t);
            join(now,t);
        }
    }
    for(int i=head2[now];i!=-1;i=e2[i].next)
    {
        int t=e2[i].t;
        if(vis[t]==1)
        {
            e2[i].lca=find(t);
            e2[i^1].lca=e2[i].lca;
        }
    }
}

int main()
{
    int x,y,w;
    int q,k;
    while(~scanf("%d",&n))
    {
        init();
        cnt=0;
        for(int i=0;i<n-1;i++)
        {
            scanf("%d%d%d",&x,&y,&w);
            add1(x,y,w);
            add1(y,x,w);
        }
        cnt=0;
        scanf("%d%d",&q,&k);
        for(int i=0;i<q;i++)
        {
            scanf("%d%d",&x,&y);
            add2(x,k);
            add2(k,x);
            add2(k,y);
            add2(y,k);
        }
        Tarjan(1);
        for(int i=0;i<q;i++)
        {
            int now=i*4;
            int u=e2[now].s;
            int v=e2[now].t;
            int lca=e2[now].lca;
            ll ans=dis[u]+dis[v]-2*dis[lca];
            now=i*4+2;
            u=e2[now].s;
            v=e2[now].t;
            lca=e2[now].lca;
            ans=ans+dis[u]+dis[v]-2*dis[lca];
            printf("%lld\n",ans);
        }
    }
    return 0;
}

