const long long INF = 100000000000;

struct Edge{
    int to;
    int cost;

    Edge(int t, int c){
        to = t;
        cost = c;
    }
};

int main(){
    int n;
    cin >> n;
    vector<vector<Edge>> graph(n);

    for (auto i = 0; i < n-1; i++)
    {
        int a, b, c;
        cin >> a >> b >> c;
        a -= 1;
        b -= 1;
        Edge e1(a, c);
        Edge e2(b, c);
        graph[a].push_back(e2);
        graph[b].push_back(e1);
    }

    int q, k;
    cin >> q >> k;
    k -= 1;

    // dijkstra
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> qu;
    vector<long long> d(n, INF);
    d[k] = 0;
    qu.push(pair<long long, int>(0, k));

    while(!qu.empty()){
        auto p = qu.top();
        qu.pop();
        int v = p.second;
        if(d[v] < p.first){
            continue;
        }

        for (auto i = 0; i < graph[v].size(); i++)
        {
            Edge e = graph[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;
                qu.push(pair<long long, int>(d[e.to], e.to));
            }
        }
    }
    vector<int> x(q);
    vector<int> y(q);

    for (auto i = 0; i < q; i++)
    {
        int x_i, y_i;
        cin >> x_i >> y_i;
        x[i] = x_i - 1;
        y[i] = y_i - 1;        
    }

    for (auto i = 0; i < q; i++)
    {
        cout << d[x[i]] + d[y[i]] << endl;
    }

}

