ll XtoY(int x, int y)
{
	vector<ll> D(N, 100000000000000000);
	vector<int> Xin(N, 0);

	D[x] = 0;

	while (true)
	{
		int u = -1;
		for (int v = 0; v < N; ++v)
		{
			if (Xin[v] == 0 && (u == -1 || D[v] < D[u]))u = v;
		}
		if (u == -1) { break; }

		Xin[u] = 1;

		for (int v = 0; v < N; ++v)
		{
			if (cost[v][u] == 0) { continue; }

			D[v] = min(D[v], D[u] + cost[u][v]);
		}

	}


	return D[y];
}

