		int start, end;
		for(int i = 0; i < m; i++){
			long long ans = 0;
			scanf("%d %d", &start, &end);
			if(key < start) Dijkstra(start,key), ans += dist[start];
			else Dijkstra(key,start), ans += dist[key];

			//printf("%lld\n",dis[key]);
			if(key > end) Dijkstra(key,end), ans += dist[key];
			else Dijkstra(end,key), ans += dist[end];

			//printf("%lld\n",dis[end]);

			printf("%lld\n",ans);
		}
	}
	return 0;
}

