void dfs(vector<vector<Edge>> &g, vector<ll> &costs,ll v,ll p){

	for(Edge nextv:g[v]){
		if(nextv.to==p)continue;
		costs[nextv.to]=costs[v]+nextv.cost;
		dfs(g,costs,nextv.to,v);
	}

}

