void bfs(std::vector<std::vector<Edge> >& g, long long d[], int k) {
  std::fill(d, d + 100000, (long long)(1e15));

  d[k] = 0;

  std::priority_queue<std::pair<long long, int> > que; // cost, vertex
  que.push({0, k});

  while (!que.empty()) {
    auto p = que.top();
    que.pop();

    for (auto nextv : g[p.second]) {
      if (d[nextv.to] <= p.first + nextv.cost) {
	continue;
      }

      d[nextv.to] = p.first + nextv.cost;
      que.push({d[nextv.to], nextv.to}); 
    }
  }

}

