#include <bits/stdc++.h>
using namespace std;

const long long int INF = 1e18;

struct edge{
    int to;
    long long int cost;
};

int V,E;// number of (vertices, edges)
vector<vector<edge>> graph;
vector<long long int> d;// shortest distances
vector<int> previous_node;

void Dijkstra(int s){// s = starting point
    priority_queue<
        pair<int, int>// temporarily keeping (shortest distance, vertex)
        , vector<pair<int, int>>, greater<pair<int, int>>// shorter ones first
    > pq;

    // initialize (INF)
    for(int i=0; i<V; i++){
        d[i] = INF;
    }
    d[s] = 0;
    pq.push({0,s});

    // search
    pair<int, int> current;// (shortest-distance confirmed, vertex)
    while(!pq.empty()){
        current = pq.top();
        pq.pop();

        int v = current.second;
        if(d[v] < current.first){
            continue;// no need to update d[v]
        }
        // else
        for(int i=0; i<graph[v].size(); i++){
            edge e = graph[v][i];
            if(d[e.to] > d[v] + e.cost){
                d[e.to] = d[v] + e.cost;// update minimum cost
                pq.push({d[e.to], e.to});
                previous_node[e.to] = v;// path : (v) --> (e.to)
            }
        }
    }
}

int main(){
    int s;// starting point

    int n;
    cin >> n;
    V = n;
    E = n-1;
    graph.resize(V);
    d.resize(V);
    previous_node.assign(V, -1);

    for(int i=0; i<E; i++){
        int u, v, w;
        cin >> u >> v >> w;
        u -= 1;
        v -= 1;
        graph[u].push_back({v, w});
        graph[v].push_back({u, w});
    }

    int q, k;
    cin >> q >> k;
    s = k - 1;
    Dijkstra(s);// starting from s

    vector<int> x(q), y(q);
    for(int i=0; i<q; i++){
        cin >> x[i] >> y[i];
    }
    for(int i=0; i<q; i++){
        cout << d[x[i]-1] + d[y[i]-1] << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using edge = pair<long long, long long>;
using Graph = vector<vector<edge>>;

vector<long long> dijkstra(const Graph &G, long long s){
    using Pi = pair<long long, long long>;
    const long long inf = 1e12;
    vector<long long> dist(G.size(), inf); 
    priority_queue<Pi, vector<Pi>, greater<Pi>> que;
    dist[s] = 0; que.emplace(dist[s], s);
    while (!que.empty()) {
        long long sum_dist; int node;
        tie(sum_dist, node) = que.top(); que.pop();
        if (dist[node] < sum_dist) continue;
        for (auto &e : G[node]) {
            long long next_node; long long dis; tie(next_node, dis) = e;
            if (dist[next_node] > dist[node] + dis) {
                dist[next_node] = dist[node] + dis;
                que.emplace(dist[next_node], next_node);
            }
        }
    }
    return dist;
}

int main(){
    long long N, Q, K;
    cin >> N;
    Graph G(N, vector<edge>());
    for (int i = 1; i < N; i++) {
        long long a, b, c;
        cin >> a >> b >> c; a--; b--;
        G[a].emplace_back(b, c);
        G[b].emplace_back(a, c);
    }
    cin >> Q >> K; K--;
    vector<long long> dist = dijkstra(G, K);
    for (int i = 0; i < Q; i++) {
        int a, b; cin >> a >> b; a--; b--;
        long long ans = dist[a] + dist[b];
        cout << ans << endl;
    }
    return 0;
}

