    dirs[start] = 0;
    vis[start] = 1;
    Q.push(start);
    while(!Q.empty())
    {
        LL top = Q.front(); //边的起点
        Q.pop();
        vis[top] = 0;
        for(LL j=pre[top];j!=-1;j=edge[j].next)
        {
            LL e = edge[j].v; //边的终点
            if(dirs[e] > edge[j].w + dirs[top])
            {
                dirs[e] = edge[j].w + dirs[top];
                if(!vis[e])
