    for (int i = 1; i < 20; i++)
        for (int j = 1; j <= n; j++)
            lca[i][j] = lca[i - 1][lca[i - 1][j]];
    int q;
    scanf("%d%d", &q, &k);
    unordered_map<int, int> l;
    l.reserve(512);
    l.max_load_factor(0.25f);
    ios::sync_with_stdio(false);
    for (int i = 0, x, y; i < q; i++) {
        scanf("%d%d", &x, &y);
        if (!l.count(x)) l[x] = getLca(x, k);
        if (!l.count(y)) l[y] = getLca(y, k);
        cout << getDis(x, l[x]) + 2 * getDis(k, l[x]) + getDis(y, l[y]) << '\n';
    }
}

