int leaf_idx;

void set_leaf_idx()
{
	for (int i = 1; i <= N; i++)
		if (indegree[i] == 1)
		{
			leaf_idx = i;
			return;
		}
}

void set_dist(int cur, ll len)
{
	visited[cur] = true;
	dist[cur] = len;
	for (int i = 0; i < adj[cur].size(); i++)
	{
		auto next = adj[cur][i];
		auto next_cost = cost[cur][i];
		if (visited[next]) continue;
		set_dist(next, len + next_cost);
	}
}

ll get_dist(int x, int y)
{
	ll ret = dist[x] - dist[y];
	if (ret >= 0)
		return ret;
	else
		return -ret;
}

ll query(int x, int y)
{
	ll ret = 0;
	auto dxy = get_dist(x, y);
	auto dxk = get_dist(x, K);
	auto dky = get_dist(K, y);

	ret = dxk + dky;

	return ret;
}

