    ll ans1 = (dist[x] - dist[lca_xk]) + (dist[k] - dist[lca_xk]);
    // k to y
    int lca_ky = lca(k,y);
    ll ans2 = (dist[k] - dist[lca_ky]) + (dist[y] - dist[lca_ky]);
    printf("%lld\n",ans1+ans2);
  }
  return 0;
}

