using ll = long long;
using namespace std;

// dijkstra法
const int MAX_V = 100000;
struct edge { int to, cost; };
int V;
vector<edge> G[MAX_V];
ll d[MAX_V];

void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P>> pq;
    fill(d, d + V, LLINF);
    d[s] = 0;
    pq.push(P(0, s));

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        for (edge e : G[v])
        {
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                pq.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    V = N;
    for (int i = 0; i < N-1; i++)
    {
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        G[a].push_back(edge{b,c});
        G[b].push_back(edge{a,c});
    }
    int Q, K;
    cin >> Q >> K;
    K--;
    dijkstra(K);
    vector<ll> ans(Q);
    for (int i = 0; i < Q; i++)
    {
        int x, y;
        cin >> x >> y;
        x--; y--;
        ans[i] = d[x] + d[y];
    }
