using EDGE = vector<vector<pair<ll, ll>>>;

void dfs(ll node, ll pnode, ll dist, vector<ll>& dist_from_root, const EDGE& edges)
{
    dist_from_root[node] = dist;
    for (auto&& e : edges[node]) {
        if (e.first != pnode) {
            dfs(e.first, node, dist + e.second, dist_from_root, edges);
        }
    }
}

