vector<ll> dijkstra(ll s,ll n,Graph g){
    typedef pair<ll,ll> P;
    vector<ll> d(n,INF);
    priority_queue<P, vector<P>, greater<P>> que;
    d[s] = 0ll;
    que.push(P(0ll, s));
    while(!que.empty()){
        P p = que.top();
        que.pop();
        int v = p.second;
        if(d[v]<p.first) continue;
        for(ll i = 0; i<g[v].size(); i++){
            Edge e = g[v][i];
            if(d[e.to]>d[v]+e.weight){
                d[e.to] = d[v] + e.weight;
                que.push(P(d[e.to],e.to));
            }
        }
    }
    return d;
}

