vector<ll> dijkstra(int s,vector<edge> g[]){
    vector<ll> d(MAX,LINF);
    priority_queue<P,vector<P>,greater<P>> q;
    d[s]=0;
    q.push(P(0,s));
    while(!q.empty()){
