#include<set>

using namespace std;
#define int long long
#define repeat(i,n) for(int i=0;i<(n);i++)

struct Edge{
   int to, c;
   Edge(int _to, int _c):to(_to), c(_c){}
};

vector<Edge> g[100005];
vector<int> d(100005, -1);
vector<int> sb(100005, 0);

int par[17][100005];
int dep[100005];

void init(int N){
  repeat(i, 16){
    repeat(j, N){
      if(par[i][j]==-1){
        par[i+1][j]=-1;
      }else{
        par[i+1][j]=par[i][par[i][j]];
      }
    }
  }
}

int lca(int s, int t){
  if(dep[s]<dep[t]) swap(s, t);
  repeat(i,17)if((dep[s]-dep[t])>>i&1) s=par[i][s];
  if(s==t) return s;
  for(int i=16; i>=0; i--){
    if(par[i][s]!=par[i][t]) s=par[i][s], t=par[i][t];
  }
  return par[0][s];
}


void f(int i, int p, int k){
   par[0][i]=p;
   if(i==k) sb[i]=1;
   for(auto e: g[i])if(e.to!=p){
      assert(d[i]>=0);
      d[e.to]=d[i]+e.c;
      sb[e.to]|=sb[i];
      dep[e.to]=dep[i]+1;
      f(e.to, i, k);
   }
}


signed main(){

   int N; cin>> N;
   repeat(i, N-1){
      int a, b, c;
      cin>> a>> b>> c;
      a--; b--;
      g[a].push_back(Edge{b, c});
      g[b].push_back(Edge{a, c});
   }

   int Q, K;
   cin>> Q>> K; K--;

   d[0]=0;
   f(0, -1, K);
   init(N);

   while(Q--){
      int x, y;
      cin>> x>> y;
      x--; y--;
      int dd=0;
      if(sb[x]==0 and sb[y]==0){
         // dd=2*d[K]+d[x]+d[y];
         dd=d[x]+d[K]-2*d[lca(x, K)];
         assert(dd>=0);
         dd+=d[y]+d[K]-2*d[lca(y, K)];
         assert(dd>=0);
      }else if(sb[x]==1 and sb[y]==1){
         dd=d[x]+d[y]-2*d[K];
         assert(dd>=0);
      }else{
         dd=d[x]+d[y]-2*d[lca(x, y)];
      }
      cout<< dd<< endl;
   }


