const ll INF = 1e18;
const ll MOD = 1e9 + 7;

void dijkstra(vector<vector<pair<int, ll>>> &G, Vll &dis, auto s)
{
  /*
  ダイクストラ法。任意の始点から各点への最短距離を求める。計算量は O((V+E)logV)。
  引数のグラフは 0-indexed の隣接リストを想定。要素は、PII(to, weight)。
  始点から各点までの距離を格納する配列を用意し、参照渡しする。すべての要素をINFで初期化しておく。
  */
  dis[s] = 0;
  priority_queue< pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>> > q; // 値の小さい要素を優先
  q.push(pair<ll, int>(dis[s], s));
  while(!q.empty())
  {
    pair<ll, int> node = q.top();
    q.pop();
    int u = node.second;
    ll c = node.first;
    REPx(x, G[u])
    {
      int v = x.first;
      ll w = x.second;
      if (c + w < dis[v])
      {
        dis[v] = c + w;
        q.push(pair<ll, int>(dis[v], v));
      }
    }
  }
}

int main()
{
  ll N;
  cin >> N;
  vector<vector<pair<int, ll>>> tree(N, vector<pair<int, ll>>());
  REP(i, N-1)
  {
    int a, b;
    ll c;
    cin >> a >> b >> c;
    a--; b--;
    tree[a].push_back(pair<int, ll>(b, c));
    tree[b].push_back(pair<int, ll>(a, c));
  }
  int Q, K;
  cin >> Q >> K; K--;
  Vll dis(N, INF);
  dijkstra(tree, dis, K);
  REP(i, Q)
  {
    int x, y;
    cin >> x >> y;
    x--; y--;
    ll res = dis[x] + dis[y];
    cout << res << endl;
  }

  return 0;
}

