        list[a].push_back(make_pair(b,c));
        list[b].push_back(make_pair(a,c));
    }
    cin >> Q >> K;
    K--;
    dijkstra(K);
    for(int i=0;i<Q;i++){
        int x,y;
        cin >> x >> y;
        x--; y--;
        cout << dist[x] + dist[y] << endl;
    }
