	for(int i=0;i<N-1;i++){
		int a,b;
		long long c;
		scanf("%d %d %lld",&a,&b,&c);
		a--;b--;
		struct edge t;
		t.to = b;
		t.cost = c;
		G[a].push_back(t);
		struct edge e;
		e.to = a;
		e.cost = c;
		G[b].push_back(e);
	}

	scanf("%d %d",&Q,&K);
	K--;
	dijktsra(K);

	for(int i=0;i<Q;i++){
		int x,y;
		scanf("%d %d",&x,&y);
		x--;y--;
		printf("%lld\n",d[x]+d[y]);
	}

	return 0;
}

