using namespace std;
const long long INF = 18e10;
typedef pair<int, int> P;
int N;
struct edge {
    int to;
    long long cost;
};
vector<edge> G[100000 + 10];
long long d[100000 + 10];

void add_edge(int u, int v, long long cost) {
    G[u].push_back(edge{v, cost});
    G[v].push_back(edge{u, cost});
}

void dij(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d + N + 1, INF);
    d[s] = 0;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        for (int i = 0; i < G[v].size(); i++) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
}

int main() {
    while (~scanf("%d", &N)) {
        for (int i = 1; i <= N + 1; i++)
            G[i].clear();
        int a, b;
        long long c;
        for (int i = 0; i < N - 1; i++) {
            scanf("%d %d %I64d", &a, &b, &c);
            add_edge(a, b, c);
        }
        int q, k;
        scanf("%d %d", &q, &k);
        dij(k);
        int x, y;
        for (int i = 0; i < q; i++) {
            scanf("%d %d", &x, &y);
            printf("%I64d\n", d[x] + d[y]);
        }
    }
    return 0;
}

