Node tree[100000];

long long calc_distance(long long);

int main()
{
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n - 1; i++)
    {
        int a, b, c;
        scanf("%d%d%d", &a, &b, &c);
        a--; b--;
        if (a > b) std::swap(a, b);
        tree[b].parent = a;
        tree[b].cost = c;
    }
    int q, k;
    scanf("%d%d", &q, &k);
    k--;
    tree[k].k_distance = 0;
    int tmp_k{k};
    while (tmp_k)
    {
        int next = tree[tmp_k].parent;
        tree[next].k_distance = tree[tmp_k].k_distance + tree[tmp_k].cost;
        tmp_k = next;
    }

    for (int i = 0; i < q; i++)
    {
        int x, y;
        scanf("%d%d", &x, &y);
        x--; y--;
        printf("%lld\n", calc_distance(x) + calc_distance(y));
    }

    return 0;
}

long long calc_distance(long long a)
{
    if (tree[a].k_distance != -1) return tree[a].k_distance;

    tree[a].k_distance = calc_distance(tree[a].parent) + tree[a].cost;
    return tree[a].k_distance;
}

