typedef struct str_node node_t;
typedef struct str_node{
    int64_t id;
    vector<node_t*> next;
    vector<int64_t> distance;
}node_t;

int64_t test(vector<node_t> &node, int64_t from, int64_t cur, int64_t target, int64_t distance);

int64_t N;
int64_t Q,K;

int main(void) {
    int64_t a,b,c;
    cin >> N;

    vector<node_t> node(N);
    node[0].id = 0;
    for(int i=1;i<N;i++) {
        cin >> a >> b >> c;
        node[i].id = i;
        node[a-1].next.push_back(&node[b-1]);
        node[a-1].distance.push_back(c);
        node[b-1].next.push_back(&node[a-1]);
        node[b-1].distance.push_back(c);
    }

    cin >> Q >> K;
    vector<pair<int64_t,int64_t>> xy(Q);
    for(int i=0;i<Q;i++) {
        cin >> xy[i].first >> xy[i].second;
    }

    vector<int64_t> total_distance(N);

    for(int i=0;i<N;i++) {
        if((K - 1) == i) {
            total_distance[i] = 0;
            continue;
        }
        total_distance[i] = test(node, -1, K -1, i, 0);
//printf("i:%d/%ld total:%ld\n", i, N, total_distance[i]);
    }

    for(int i=0;i<Q;i++) {
        cout << total_distance[xy[i].first-1] + total_distance[xy[i].second-1] << "\n";
    }

    return 0;
}

int64_t test(vector<node_t> &node, int64_t from, int64_t cur, int64_t target, int64_t distance) {
    int64_t total = 0;
    for(int i=0;i<node[cur].next.size();i++) {
        if(node[cur].next[i]->id == target) {
//printf("debug target:%ld from:%ld i:%d cur:%ld distance:%ld node[%ld].distance[%d]:%ld\n"
//        ,target,from,i,cur,distance,cur,i,node[cur].distance[i]);
            return distance  + node[cur].distance[i];
        }
    }

    for(int i=0;i<node[cur].next.size();i++) {
//printf("debug %d/%ld => %ld\n", i, node[cur].next.size(), node[cur].next[i]->id);
        if(node[cur].next[i]->id == from) continue;
        total += test(node, cur, node[cur].next[i]->id, target, distance + node[cur].distance[i]);
        if(total) break;
    }

//printf("debug target:%ld from:%ld i:- cur:%ld distance:%ld total:%ld\n"
//        ,target,from,cur,distance,total);
    return total;
}

