// https://www.youtube.com/watch?v=8uowVvQ_-Mo&feature=youtu.be&t=1619
struct combination{
    vector<mint> fact, ifact;
    combination(int n) : fact(n + 1), ifact(n + 1)
    {
        assert(n < mod);
        fact[0] = 1;
        for (int i = 1; i <= n; ++i)
            fact[i] = fact[i - 1] * i;
        ifact[n] = fact[n].inv();
        for (int i = n; i >= 1; --i)
            ifact[i - 1] = ifact[i] * i;
    }
    mint operator()(int n, int k)
    {
        if (k < 0 || k > n)
            return 0;
        return fact[n] * ifact[k] * ifact[n - k];
    }
};

//分割数のmodの表生成(tof=falseで重複あり)d[i][j]=jのi分割
struct divNum{
    vector<vector<mint>> d;
    int N, M;
    divNum(int n, int m, bool tof=true) : d(n + 1, vector<mint>(m + 1, 0))
    {
        N = n;
        M = m;
        if (tof)
        {
            rep(j, n + 1)
            {
                d[j][0] = 1;
            }
            rep(j, m)
            {
                d[0][j + 1] = 0;
            }
            for (int j = 1; j <= n; j++)
            {
                for (int k = 1; k <= m; k++)
                {
                    if (j > k)
                        d[j][k] = d[j - 1][k];
                    else
                        d[j][k] = d[j - 1][k] + d[j][k - j];
                }
            }
        }
        else
        {
            d[0][0] = 1;
            rep(i, n)
            {
                rep(j, m + 1)
                {
                    rep(k, m - j + 1)
                    {
                        d[i + 1][j + k] = d[i + 1][j + k] + d[i][j];
                    }
                }
            }
        }
    }
    mint operator()(int n, int m)
    {
        if (n < 0 || m < 0 || n > N || m > M)
            return 0;
        else
        {
            return d[n][m];
        }
    }
};
