vector<bool> seen;
void dfs(ll &v, const ll &K ,const vector<vector<ll>> &G, vector<vector<ll>> &Z) {
  seen[v] = true; // v を訪問済にする
  // v から行ける各頂点 next について
  for (auto next : G[v]) {
    if (seen[next]) continue; // next_v が探索済だったらスルー
    Z[K][next]=Z[K][v]+Z[v][next];
    dfs(next, K, G, Z); // 再帰的に探索
  }
}

