typedef unsigned long long ll;

int N;
vector<int> T[100000];
vector<int> C[100000];

ll cost;

bool dfs(int n, int pre, int goal,ll c) {
	printf("%2d", n);
	if (n == goal) {
		cost = c;
		return true;
	}
	for (int i = 0; i < T[n].size(); ++i) {
		if (pre == T[n][i])
			continue;
		if (dfs(T[n][i], n, goal, c + C[n][i]))
			return true;
	}
	return false;
}


int main() {
	cin >> N;
	for (int i = 0; i < N-1; ++i)
	{
		int a,b,c;
