void DFS(int root) 
{ 
    memset(vis, false, sizeof(vis)); 
    top = -1; 
    int level = 1, order = 1;
    ll dist = 0,  pre_w = 0; 
    stack[++top] = root, vis[root] = true, H[root] = order , d[root] = dist; 
    while(top >= 0) 
    { 
        int now = stack[top]; 
        bool back = true; 
        E[order] = now, L[order++] = level; 
        for(pnode p = adjlist[now]; p; p = p->next) 
        { 
            if(!vis[p->v]) 
            { 
                stack[++top] = p->v; 
                d[p->v] = (dist += (pre_w = p->w)), H[p->v] = order , level++; 
                vis[p->v] = true, back = false; 
                break; 
            } 
        } 
        if(back)dist -= pre_w, level--, top--; 
    } 
} 

int Min[N<<1][30], idx[N<<1]; 
void RMQ(int len) 
{ 
    idx[0] = -1; 
    for(int i = 1; i <= len ; i ++) 
        idx[i] = (i & (i - 1)) ? idx[i-1] : idx[i-1] + 1, Min[i][0] = i; 
    for(int j = 1; j <= idx[len] ; j ++) 
        for(int i = 1, limit = len + 1 - (1 << j); i <= limit ; i ++) 
            Min[i][j] = Min[i+(L[Min[i][j-1]] > L[Min[i+(1<<j>>1)][j-1]] ? (1 << j>>1) : 0)][j-1]; 
} 

int LCA(int u, int v) 
{ 
    int a = H[u], b = H[v]; 
    if(a > b) swap(a, b); 
    int t = idx[b-a+1]; 
    b -= (1 << t) - 1; 
    return E[Min[L[Min[a][t]] > L[Min[b][t]] ? b : a][t]]; 
} 
