typedef struct Node {
    long id;
    vector<pair<long, ll> > connects;
} Node;

void solve(const vector<Node> &nodes, const long &k, map<long, ll> &table) {
    queue<pair<long, ll> > q;
    Node n = nodes[k];
    ll cost;

    long i, len = n.connects.size();

    for (i = 0; i < len; i++) {
        table[n.connects[i].first] = n.connects[i].second;

        q.push(make_pair(n.connects[i].first, n.connects[i].second));
    }

    table[k] = -1;

    while (!q.empty()) {
        n = nodes[q.front().first];
        cost = q.front().second;

        q.pop();

        len = n.connects.size();
        for (i = 0; i < len; i++) {
            if (table[n.connects[i].first] == 0) {
                table[n.connects[i].first] = n.connects[i].second + cost;

                q.push(make_pair(n.connects[i].first, n.connects[i].second + cost));
            }
        }
    }

    table[k] = 0;
}

