      adj[b-1].push_back(make_pair(a-1,c));
    }

  int Q,K;
  cin>>Q>>K;
  dijkstra(K-1);
  for(int i=0;i<Q;i++){
      int x,y;
      cin>>x>>y;
      cout<<d[x-1]+d[y-1]<<endl;
  }

}

