	rep(i, 0, Q) {
		scanf("%d %d", &a, &b);
		a--, b--;
		ans.push_back(depth[a] + depth[K] - depth[lca(a, K)] * 2
			+ depth[b] + depth[K] - depth[lca(b, K)] * 2);
	}
	rep(i, 0, Q)printf("%lld\n", ans[i]);
	return 0;
}

