using namespace std;
#define MAX 100000
typedef long long ll;

struct edge{
  ll to,cost;
  edge(ll to,ll cost):to(to),cost(cost) {}
};

int N;
vector< edge > G[MAX];
ll dist[MAX];
int depth[MAX];
int parent[MAX];
int dp[30][MAX];

int lca(int a,int b){
  if(depth[a]>depth[b])swap(a,b);
  int x=depth[b]-depth[a];
  for(int i=0;i<30;i++)
    if(x>>i&1)b=dp[i][b];
  if(a==b)return a;
  for(int i=29;i>=0;i--){
    if(dp[i][a]!=dp[i][b]){
      a=dp[i][a];
      b=dp[i][b];
    }
  }
  return parent[a];
}

ll solve(int a,int b){
  int c=lca(a,b);
  return dist[a]+dist[b]-dist[c]*2LL;
}

void dfs(int pos,int prev,int d){
  depth[pos]=d;
  parent[pos]=prev;
  for(edge e:G[pos]){
    if(e.to==prev)continue;
    dist[e.to]=dist[pos]+e.cost;
    dfs(e.to,pos,d+1);
  }
}

