ll d[100001];

void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<>> que;
    for (int i = 0; i < 100001; i++) d[i] = INF;
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (auto to : V[v]) {
            ll cost = G[C(v, to)];

            if (d[to] > d[v] + cost) {
                d[to] = d[v] + cost;
                que.push(P(d[to], to));
            }
        }
    }
}

