struct Tree
{
	Tree(int numVertices)
	{
		al.resize(numVertices);
		w.resize(numVertices);
	}

	void addEdge(int a, int b, long long weight) {
		al[a].push_back(b);
		al[b].push_back(a);

		w[a].push_back(weight);
		w[b].push_back(weight);
	}

	void calcShortestPaths(int from);
	long long getShortestPath(int u, int v) const { return shp[u] + shp[v]; }

private :
	void dfs(int u, int p);

	std::vector<std::vector<int>> al;
	std::vector<std::vector<long long>> w;

	std::vector<long long> shp;
};

void Tree::calcShortestPaths(int from)
{
	shp.resize(al.size(), 0);
	dfs(from, -1);
}

void Tree::dfs(int u, int p)
{
	for (size_t i = 0; i != al[u].size(); ++i) {
		int nu = al[u][i];
		long long wnu = w[u][i];
		if (nu != p) {
			shp[nu] = shp[u] + wnu;
			dfs(nu, u);
		}
	}
}

