void dfs(int now, long long costs){
    seen[now] = true;
    depth[now] = costs;
    for(int i = 0; i < G[now].size(); i++){
        edge e = G[now][i];
        if(!seen[e.to]){
            dfs(e.to, costs + e.cost);
        }
    }
}

