class Edge{
public:
	int from, to;
    ll cost;
	Edge(int from = 0, int to = 0, ll cost = 0) :
			from(from), to(to), cost(cost){}

	bool operator < (const Edge &e) const{
		return cost < e.cost;
	}
	bool operator >(const Edge &e) const{
		return cost > e.cost;
	}

};

class Node{
public:
	vector<Edge> edges;
	ll dist;
	Node(){
		dist = -1;
	}
};

class Graph{
public:
	vector<Node> nodes;
	Graph(int n) {
		rep(i, n) { Node n;  nodes.push_back(n); }
	}
	Node& operator[](int i){
		return nodes[i];
	}
};


class Data{

public:
	ll dist;
	Edge *edge;
	Data(ll dist, Edge *edge) {
		this->dist = dist;
		this->edge = edge;
	}

	bool operator < (const Data &d) const{
		return dist < d.dist;
	}
	bool operator >(const Data &d) const{
		return dist > d.dist;
	}
};

int N, Q, K;
Graph G(0);
ll dist[100000];

void process(int K){
	queue<Data> q;
	Edge e0 =  Edge(-1, K, 0);
	q.push(Data(0, &e0));

	while(!q.empty()){
		Data d = q.front(); q.pop();
        Edge &e = *(d.edge);
        Node &n = G[e.to];
		if(n.dist != -1) continue;

		n.dist = d.dist;

		for(auto &ee: n.edges){
			q.push(Data(n.dist + ee.cost, &ee));
		}
	}

    rep(i, N){
        fprintf(stderr, "%d %lld\n", i, G[i].dist);
    }
}

ll query(int x, int y){
	return G[x].dist + G[y].dist;
}

int main() {
	cin >> N;
	G = Graph(N);

	rep(i, N-1){
		int a, b; ll c;
		cin >> a >> b >> c; a--; b--;
		G[a].edges.push_back(Edge(a, b, c));
		G[b].edges.push_back(Edge(b, a, c));
	}

	cin >> Q >> K;
    K--;
	process(K);

	rep(i, Q){
		int x, y;
		cin >> x >> y; x--; y--;
		cout << query(x, y) << endl;
	}

}

