void dfs(vector<vector<Edge>> &g, vector<ll> &costs,ll v,ll p){

	for(Edge nextv:g[v]){
		if(nextv.to==p)continue;
		costs[nextv.to]=costs[v]+nextv.cost;
		dfs(g,costs,nextv.to,v);
	}

}

signed main() {
	//ABC014D

	//cinから受付
	//N:ノードの数、0〜(node_size-1)がノード番号として定義される
	//M:与えられるEdgeの数
	ll N,M;
	cin >> N;
	M=N-1;
	vector<vector<ll>> g(N);
	vector<vector<Edge>> eg(N);
	for (ll i=0; i<M; i++) {
		ll from,to,cost;
		cin >> from >> to >> cost;
		from--;to--;
		g[from].push_back(to);
		g[to].push_back(from);
		Edge e1(from,to,cost);
		Edge e2(to,from,cost);
		eg[from].push_back(e1);
		eg[to].push_back(e2);
	}

	ll Q,K;
	cin>>Q>>K;
	K--;

	DoublingLowestCommonAncestor< vector<vector<ll>> > lca(g);
	lca.build();

	vector<ll> costs(N,0);
	dfs(eg,costs,K,-1);

	vector<ll> anslist(Q,0);
	rep(i,Q){
		ll x,y;
		cin>>x>>y;
		x--;y--;
		ll lcaxy=lca.query(x, y);
		ll lcakx=lca.query(K, x);
		ll lcaky=lca.query(K, y);
		ll ans=0;
		if(lcaxy==K){//1
			ans=costs[x]+costs[y]-2*costs[K];
		}else if(lcakx==K || lcaky==K){//2
			if(lcakx==x || lcaky==y){//2A
				ans=abs(costs[x]-costs[y]);
			}else{//2B
				ans=costs[x]+costs[y]-2*costs[K];
			}
		}else if(lcakx==lcaky){//3
			ans=costs[x]+costs[y]+2*costs[K]-4*costs[lcakx];
		}else if(lcaxy==lcakx){//4A
			ans=costs[K]+costs[y]-2*costs[lcaky]  +costs[K]-costs[lcaxy]  +costs[x]-costs[lcaxy];
		}else if(lcaxy==lcaky){//4B
			ans=costs[K]+costs[x]-2*costs[lcakx]  +costs[K]-costs[lcaxy]  +costs[y]-costs[lcaxy];
		}
		anslist[i]=ans;
	}

	rep(i,Q)p(anslist[i]);
	return 0;
}

