using namespace std;
#define MAX_V 100010
#define INFA (long long)1000000000000000000
#define rep(i,q) for(int i = 0; (q) > i; i++)
struct edge { int to, cost; };
typedef pair<int,int> P;

int V;
vector<edge> G[MAX_V];
long long d[MAX_V];

void dijkstra(int s){
  priority_queue<P,vector<P>, greater<P> > que;
  fill(d,d+V+1,INFA);
  d[s]=0;
  que.push(P(0, s));

  while(!que.empty()){
    P p = que.top(); que.pop();
    int v =  p.second;
    if(d[v] < p.first)continue;
    for(int i = 0; i < G[v].size(); i++){
      edge e = G[v][i];
      if(d[e.to] > d[v] + e.cost){
        d[e.to] = d[v]+e.cost;
        que.push(P(d[e.to],e.to));
      }
    }
  }
}
int main(){
  cin>>V;
  for(int i = 0; V-1 > i; i++){
    int a,b,c;
    scanf("%d %d %d", &a,&b,&c);
    G[a].push_back({b,c});
    G[b].push_back({a,c});
  }

  int q,k;cin>>q>>k;
  dijkstra(k);
  for(int i = 0; q > i; i++){
    long long x,y;
    cin>>x>>y;
    cout << d[x]+d[y] << endl;
  }
}

