const ll LINF = 1001002003004005006ll;
const int INF = 1001001001;
const int MOD = 1000000007;

vl d;
vl* dijkstra(vv(PL) &G,int V,int s) {
// G[f][i] = P(t,c) means that from `f` to `t` 's cost is `c` 
  d = vl(V,LINF);
  priority_queue<PL,vp, greater<PL>> que;
  d[s] = 0;
  que.push(PL(0,s));
  while(!que.empty()) {
    PL p = que.top();
    que.pop();
    ll  tar = p.second;
    if(d[tar] < p.first) continue;
    rep(i,sz(G[tar])) {
      PL e = G[tar][i];
      if(d[e.first] > d[tar] + e.second) {
        d[e.first] = d[tar] + e.second;
        que.push(PL(d[e.first],e.first));
      }
    }
  }
  return &d;
}

int main() {
  int N;
  cin >> N;
  vv(PL) G(N);
  rep(i,N-1) {
    int a,b,c;
    cin >> a >> b >> c;
    a--;
    b--;
    G[a].push_back(PL(b,c));
    G[b].push_back(PL(a,c));
  }
  int q,k;
  cin >> q >> k;
  k--;

  vl* res = dijkstra(G,N,k);
  vl ans(q);
  rep(i,q) {
    int x,y;
    cin >> x >> y;
    x--;
    y--;
    ans[i] = (*res)[x] + (*res)[y];
  }
  rep(i,q) {
    cout << ans[i] << endl;
  }
  return 0;
}

