template <class T> struct SparseTable {
  vector<vector<T>> table;

  SparseTable() {}
  SparseTable(const vector<T> &A) {
    init(A);
  }

  void init(const vector<T> &A) {
    int n = (int) A.size();
    int height = 32 - __builtin_clz(n - 1);
    int width = 1 << height;
    table.resize(height, vector<T>(width));
    for (int i = 0; i < width; i++) table[0][i] = A[i];
    for (int i = 1; i < height; i++) for (int j = 0; j < width; j++) {
      const int b = ((j >> i) | 1) << i;
      table[i][j] = (j >> i) & 1 ? query(b, j) : query(j, b-1);
    }
  }

  T query(int l, int r) {
    if (l == r) return table[0][l];
    const int d = 31 - __builtin_clz(l ^ r);
    return min(table[d][l], table[d][r]);
  }
};
template <class RMQ> struct _LCA {
  size_t n;
  vector<int> D, P, L, R;
  vector<pair<int, int>> ET;
  vector<long long> WD;
  RMQ rmq;

  _LCA(const Graph &G, int root = 0) : n(G.size()), D(n), P(n), L(n), R(n), WD(n) {
    dfs(G, root);
    rmq.init(ET);
  }

  void dfs(const Graph &G, int root = 0) {
    vector<int> count(n);
    stack<int> S; S.push(root);
    while (!S.empty()) {
      int v = S.top(); S.pop();
      if (count[v] == 1) {
        count[v] = 2;
        R[v] = ET.size() - 1;
        if (P[v] >= 0) ET.emplace_back(D[P[v]], P[v]);
      }
      else if (count[v] == 0) {
        S.push(v);
        count[v] = 1;
        L[v] = ET.size();
        ET.emplace_back(D[v], v);
        for (auto &edg : G[v]) if (!count[edg.dst]) {
          D[edg.dst] = D[v] + 1;
          WD[edg.dst] = WD[v] +  edg.weight;
          P[edg.dst] = v;
          S.push(edg.dst);
        }
      }
    }
  }

  int query(int u, int v) {
    u = L[u]; v = L[v];
    if (u > v) swap(u, v);
    return rmq.query(u, v).second;
  }

  long long dist(int u, int v) {
    return WD[u] + WD[v] - 2 * WD[query(u, v)];
  }
};
using LCA = _LCA<SparseTable<pair<int, int>>>;

void Main() {
  int n = ri();
  Graph G(n);
  rep(i, n-1) {
    int u = ri() - 1;
    int v = ri() - 1;
    int64_t w = ri();
    G[u].emplace_back(v, w);
    G[v].emplace_back(u, w);
  }

  int q = ri();
  int k = ri() - 1;

  LCA lca(G, k);


  while (q--) {
    int u = ri()-1;
    int v = ri()-1;

    int l = lca.query(u, v);

    ll dist = lca.dist(u, v);
    if (l == k) {
      cout << dist << endl;
    }
    else {
      ll d2 = lca.dist(l, k);
      cout << (dist + d2 * 2) << endl;
    }
  }
}

