//sから各頂点への最短ルートを計算する
void dijkstra(int s, int V, vector<ll> &d){
    // greater<P>を指定することでfirstが小さい順に取り出せるようにする
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d.begin(),d.end(), INF);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()){
        P p = que.top(); que.pop();
        int v = p.second;
        if(d[v] < p.first) continue;
        for(int i = 0; i < graph[v].size(); i++){
            edge e = graph[v][i];
            //cout << "d[e.t]:" << d[e.t] << ", d[v]+e.c:" << d[v]+e.c << endl;
            if(d[e.t] > d[v] + e.c){
                d[e.t] = d[v] + e.c;
                que.push(P(d[e.t],e.t));
            }
        }
    }
}

