    for (int i=0; i<=MAXV; i++) edges.push_back(NULL);
  }

  void insert_edge(int x, int y, long long int w,bool dir){
    edge *p = (edge*)malloc(sizeof(edge));

    p->weight = w;
    p->y = y;
    p->type = -1;
    p->next = edges[x];

    edges[x] = p;
    deg[x] ++;

    if (dir == false)
      insert_edge(y,x,w,true);
    else
      ne ++;
  }


  ///varibles for BFS
  vector<bool> processed,discovered;
  vector<int> parent,depth,entry_time,exit_time;
  vector<long long int> way;
