  }
  //-----------------------------------------------------------
  void process_edge(int x, int y){
  }



  bool unsearched = true;
  void initialize_search(){
    t = 0;
    for (int i=0; i<=nv; i++) {
      if(unsearched){
        processed.push_back(false);
        discovered.push_back(false);
        parent.push_back(-1);
        depth.push_back(-1);
        entry_time.push_back(-1);
        exit_time.push_back(-1);
        way.push_back(0);
      }else{
        processed[i] = discovered[i] = false;
        parent[i] = depth[i] = entry_time[i] = exit_time[i] = -1;
        way[i] = 0;
      }
    }
    unsearched = false;
  }


  void dfs(int v){
    edge *p;      /* temporary pointer */
    int y;        /* successor vertex */

    t = t+1;
    entry_time[v] = t;
    discovered[v] = true;
//    process_vertex_early(v);

