void dijkstra(int s, T inf) {
    fill_n(dist, SIZE, inf);
    fill_n(used, SIZE, false);
    priority_queue<P, vector<P>, greater<P>> q;
    q.push(P(0, s));
    while (q.size()) {
        int t;
        long long d;
        tie(d, t) = q.top(), q.pop();
        if (used[t]) continue;
        used[t] = true;
        dist[t] = d;
        for (auto e : G[t]) {
