	while(q--){
		int a,b;
        scanf("%d%d",&a,&b);
        int lcaab=LCA(a,b);
        int lcaak=LCA(lcaab,k);
        //cout<<lcaab<<" "<<lcaak<<endl;
        LL dis1=getdis(k,a);
        LL dis2=getdis(k,b);
        LL dis3=getdis(k,lcaab);
        if(getdis(k,lcaab)+getdis(a,k)==getdis(a,lcaab)||getdis(k,lcaab)+getdis(b,k)==getdis(b,lcaab))printf("%lld\n",getdis(a,b));
        else printf("%lld\n",getdis(a,b)+2*min(dis1,min(dis2,dis3)));
		//printf("%d\n",ans);
	}
}

