void bellman(int s) {
   rep (i, 0, N) dist[i] = INF;
   dist[s] = 0;
   while (true) {
      bool update = false;
      for (int i = 0; i < N; i++) {
         for (edge e : G[i]) {
            if (dist[i] != INF && dist[e.to] > dist[i] + e.cost) {
               dist[e.to] = dist[i] + e.cost;
               update = true;
            }
         }
      }
      if (!update) break;
   }
}


