using namespace std;static const long long INFL = 0x3F3F3F3F3F3F3F3FLL;
typedef int64_t ll;
typedef pair<ll, ll> pll;
// ダイクストラ法（プライオリティキュー）
struct DijkstraPQ {
    struct edge { int64_t to, cost; };
    int V;
    vector<vector<edge>> G;
    vector<int64_t> d;

    DijkstraPQ(int _n) {
        init(_n);
    }
    void init(int _n) {
        V = _n;
        G.clear();
        d.clear();
        G.resize(V, vector<edge>());
        d.resize(V, INFL);
    }
    void dijkstra(int64_t s) {
        // greaterを指定することでfirstが小さい順に取り出せるようにする
        priority_queue<pll, vector<pll>, greater<pll>> pq;
        fill(d.begin(), d.end(), INFL);
        d[s] = 0;
        pq.push(pll(0, s));
        while (!pq.empty()) {
            pll p = pq.top();
            pq.pop();
            ll v = p.second; // secondは頂点の番号
            if (d[v] < p.first) continue; // firstは最短距離
            for (int i = 0; i < G[v].size(); i++) {
                edge e = G[v][i];
                if (d[e.to] > d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    pq.push(pll(d[e.to], e.to));
                }
            }
        }
    }
};
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll N;
        in >> N;
        DijkstraPQ dk(N);
        ll a, b, c;
        rep(i, N - 1) {
            in >> a >> b >> c;
            a--; b--;
            dk.G[a].pb({b, c});
            dk.G[b].pb({a, c});
        }
        ll Q, K;
        in >> Q >> K;
        K--;
        ll x, y;
        rep(i, Q) {
            in >> x >> y;
            x--; y--;
            dk.dijkstra(K);
            ll ans = dk.d[x] + dk.d[y];
            out << ans << endl;
        }
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
