class Solution {
public:
    long long n;
    std::vector<std::vector<std::array<long long, 2>>> v;
    std::vector<long long> dist;
    std::vector<bool> visited;
    void dfs (long long cur, long long cur_dist)
    {
      dist[cur] = cur_dist;
      visited[cur] = true;
      for (auto &p : v[cur])
        {
          if (visited[p[0]])
            continue;

          dfs (p[0], cur_dist + p[1]);
        }
    }

    void solve(std::istream& in, std::ostream& out) {
      in >> n;
      v.resize (n);
      for (long long i = 0; i < n - 1; ++i)
        {
          long long a, b, c;
          in >> a >> b >> c;
          --a; --b;
          v[a].push_back ({b, c});
          v[b].push_back ({a, c});
        }
      long long q, k;
      in >> q >> k;
      --k;
      dist.resize (n);
      visited.resize (n);
      dfs (k, 0);
      for (long long i = 0; i < q; ++i)
      {
        long long a, b;
        in >> a >> b;
        --a; --b;
        out << dist[a] + dist[b] << '\n';
      }
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}

