    // 頂点数と辺数
    ll N, M;
    cin >> N;
    M=N-1;

    // グラフ入力受取 (ここでは無向グラフを想定)
    Graph G(N);
    for (int i = 0; i < M; ++i) {
        int a, b,c;
        cin >> a >> b>>c;
        a--;
        b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    ll Q,K;
    cin>>Q>>K;
    K--;

    // BFS のためのデータ構造
    vector<int> dist(N, -1); // 全頂点を「未訪問」に初期化
    queue<int> que;

    // 初期条件 (頂点 K を初期ノードとする)
    dist[K] = 0;
    que.push(K); // K を橙色頂点にする

    // BFS 開始 (キューが空になるまで探索を行う)
    while (!que.empty()) {
        int v = que.front(); // キューから先頭頂点を取り出す
        que.pop();

        // v から辿れる頂点をすべて調べる
        for (int nv : G[v]) {
            if (dist[nv] != -1) continue; // すでに発見済みの頂点は探索しない

            // 新たな白色頂点 nv について距離情報を更新してキューに追加する
            dist[nv] = dist[v] + 1;
            que.push(nv);
        }
    }

    // 結果出力 (各頂点の頂点 0 からの距離を見る)
    //for (int v = 0; v < N; ++v) cout << v << ": " << dist[v] << endl;

    FOR(i,0,Q-1){
      ll x,y;
      cin>>x>>y;
      x--;y--;
      cout<<dist[x]+dist[y]<<endl;
    }

}

