// getAround(count) -> around
// getCost(from, to) -> cost
ints Dijkstra(int N, int a, function<ints(int)> getAround, function<int(int, int)> getCost) {
	struct Node {
		int point;
		int totalCost;

		bool operator < (Node const& n) const {
			return totalCost > n.totalCost;
		}
	};

	ints minCosts(N, INT64_MAX);
	priority_queue<Node> que;

	minCosts(a) = 0;
	que.push(Node{ a, 0 });

	while (!que.empty()) {
		Node node = que.top();
		que.pop();

		for (int next : getAround(node.point)) {
			int cost = getCost(node.point, next);
			if (cost < 0) {
				continue;
			}

			Node newNode;
			newNode.point = next;
			newNode.totalCost = node.totalCost + cost;

			if (newNode.totalCost < minCosts[newNode.point]) {
				minCosts[newNode.point] = newNode.totalCost;
				que.push(newNode);
			}
		}
	}

	return minCosts;
}

struct MyMain {
	void Run() {
		int N = in;
		arr<dic<int, int>> g(N);
		REP(i, N - 1) {
			int a = in(-1);
			int b = in(-1);
			int c = in;
			g[a][b] = c;
			g[b][a] = c;
		}
		int Q = in;
		int K = in(-1);

		function<ints(int)> getAround = [&](int index) -> ints {
			ints around;
			around.reserve(g[index].size());
			for (auto const& a : g[index]) {
				around.pb(a.first);
			}
			return around;
		};
		function<int(int, int)> getCost = [&](int from, int to) -> int {
			return g[from][to];
		};

		ints minCosts = Dijkstra(N, K, getAround, getCost);

		REP(i, Q) {
			int x = in(-1);
			int y = in(-1);

			int ans = minCosts[x] + minCosts[y];
			out << ans;
		}
	}
};

