			p[u][i] = p[p[u][i-1]][i-1];
			tofa[u][i] = tofa[u][i-1]+tofa[p[u][i-1]][i-1];
		}
	}
	for (int i = first[u]; i; i = edge[i].next) {
		int v = edge[i].to;
		if (!vis[v]) {
			d[v] = d[u]+1;
			p[v][0] = u;
			tofa[v][0] = edge[i].c;
			DFS(v);
		}
	}
}
ll LCA(int a, int b) {
	int i, j; ll ret = 0;
	if (d[a] < d[b])	swap(a, b);
	for (i = 0; (1<<i) <= d[a]; i++) {}
	i--;
	for (j = i; j >= 0; j--) {
		if (d[a]-(1<<j) >= d[b]) {
			ret += tofa[a][j];
			a = p[a][j];
		}
	}
	if (a == b) {
		return ret;
	}
	for (j = i; j >= 0; j--) {
		if (p[a][j] != p[b][j]) {
			ret += (tofa[a][j]+tofa[b][j]);
			a = p[a][j];
			b = p[b][j];
		}
	}
	return ret+tofa[a][0]+tofa[b][0];
}
