  for (int i = 0; i < N; i++) {
    graph[a[i]].pb(Edge(b[i],c[i]));
    graph[b[i]].pb(Edge(a[i],c[i]));
  }
  vector<ll> n = bellman_ford(N+1,K);
  for (int i = 0; i < Q; i++) {
    cout << n[x[i]] + n[y[i]] << endl;
  }
}

