// combination
const int MAX = 510000;
const int MOD = 1000000007;

ll fac[MAX], finv[MAX], inv[MAX];

class REP;

void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

long long COM(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

// gcd, lcm
ll gcd(ll a, ll b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

ll lcm(ll a, ll b) {
    return a / gcd(a, b) * b;
}

void rec(map<ll, ll> &distance, vector<ll> &previous, vector<vector<ll>> &graph) {
    bool isChanged = false;
    vector<ll> newPrevious;
    for (ll node : previous) {
        REP(i, graph.size()) {
            if (graph[node][i] > 0 && distance.find(i) == distance.end()) {
                newPrevious.push_back(i);
                distance.insert(make_pair(i, distance.at(node) + graph[node][i]));
                isChanged = true;
            }
        }
    }
    if (isChanged) {
        rec(distance, newPrevious, graph);
    }
}

int main() {
    ll N, Q, K;
    vector<vector<ll>> graph;
    cin >> N;
    graph = vector<vector<ll>>(N, vector<ll>(N, 0));
    REP(i, N - 1) {
        ll a, b, c;
        cin >> a >> b >> c;
        graph[a - 1][b - 1] = c;
        graph[b - 1][a - 1] = c;
    }
    cin >> Q >> K;
    K--;
    map<ll, ll> distance;
    distance.insert(make_pair(K, 0));
    vector<ll> previous;
    previous.push_back(K);
    rec(distance, previous, graph);
    REP(i, Q) {
        ll x, y;
        cin >> x >> y;
        cout << (distance.at(x - 1) + distance.at(y - 1)) << endl;
    }
    return 0;
}

