int  N, Q, K;
long d[MAX_V];
long cost[MAX_V][MAX_V];
bool used[MAX_V];

void dijkstra(int s) {
    std::fill(d, d+N, INF);
    std::fill(used, used+N, false);
    d[s] = 0;
    while (true) {
        int v = -1;
        for (int u=0; u<N; ++u) {
            if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
        }
        if (v == -1) break;
        used[v] = true;
        for (int u=0; u<N; ++u) {
            d[u] = std::min(d[u], d[v] + cost[v][u]);
        }
    }
    /*
    std::cout << "\nDebug : ";
    for (int i=0; i<N; ++i) std::cout << d[i] << ' ';
    std::cout << std::endl;
    */
}

long solve(int x, int y) {
    return d[x] + d[y];
}

