        pq.push({0, start});
        vector<char> visited(nodes.size());
        while(pq.size()){
            auto e = pq.top(); pq.pop();
            if(visited[e.dest]){ continue; }
            visited[e.dest] = true;
            if(e.dest == goal){
                return e.cost;
            }
            for(auto& edge : nodes[e.dest].edges){
                pq.push({e.cost + edge.cost, edge.dest});
            }
        }
        return -1;
    }
};

