typedef long long ll;
const ll NV = 100000 + 5;
const ll NE = 5e5 + 5;

ll n, m;

struct Dijkstra
{
    ll n, size;
    ll dis[NV], head[NV];
    ll mark[NV];

    struct node
    {
        ll v, dis;
        node() {}
        node(ll V, ll DIS): v(V), dis(DIS){}
        friend bool operator < (const node a, const node b)
        {
            return a.dis > b.dis;   // 结构体中，dis小的优先级高
        }
    };

    struct edge
    {
        ll v, w, next;
        edge() {}
        edge(ll V, ll W, ll NEXT): v(V), w(W), next(NEXT) {}
    }E[NE];

    inline void init(ll vx)
    {
        n = vx, size = 0;
        memset(head, -1, sizeof(ll)*(vx+1));
    }

    inline void insert(ll u, ll v, ll w)
    {
        E[size] = edge(v, w, head[u]);  // E[size]. v = u, E[size].w = v, E[size].next = head[u]
        head[u] = size++;
    }


    ll dijkstra(ll src, ll des)   // src: 0  des: n-1
    {
        node first, next;
        priority_queue<node> Q;
        for (ll i = 0; i <= n; i++)
        {
            dis[i] = 99999999999999;
            mark[i] = false;
        }
        dis[src] = 0;
        Q.push(node(src, 0));   // 把起始点入队

        while (!Q.empty())
        {
            first = Q.top();
            Q.pop();
            mark[first.v] = true;

            for (ll i = head[first.v]; i != -1; i = E[i].next)
            {
                if (!mark[E[i].v])
                {
                    next = node(E[i].v, first.dis + E[i].w);
                    if (next.dis < dis[next.v])
                    {
                        dis[next.v] = next.dis;
                        Q.push(next);
                    }
                }
            }      // end for
        }     // end while
        return dis[des];
    }     // end dijkstra
}G;

