    {
        G.init(n);
        n--;
        while (n--)
        {
            int u, v, w;
            cin>>u>>v>>w;
            G.insert(u-1, v-1, w);
            G.insert(v-1, u-1, w);
        }
  ll m,k;
  cin>>m>>k;
  for(ll i=0;i<m;i++)
  {
      ll a,b;
      cin>>a>>b;
     cout<<G.dijkstra(a-1, k-1)+G.dijkstra(b-1, k-1)<<endl;
  }

    }
