struct qnode
{
	int v;
	long long c;
	qnode(int _v = 0, long long _c = 0) :v(_v),c(_c){}
	bool operator < (const qnode &r) const
	{
		return c > r.c;
	}
};

struct Edge
{
	int v;
	long long cost;
	Edge(int _v = 0,long long _cost = 0):v(_v),cost(_cost){}
};

vector <Edge> E[MAX];
