void dfs(int n){
    int size=adj[n].size();
    for(int i=0;i<size;i++){
        int x=adj[n][i].first;
        int d=adj[n][i].second;
        if(!visit[x]){
            visit[x]=1;
            depth[x]=depth[n]+1;
            parent[x]=n;
            dist[x]=d;
            dfs(x);
        }
    }
}

int lca(int a,int b){
    while(a!=b){
        if(depth[a]<depth[b])
            ans+=(2*dist[b]),b=parent[b];
        else if(depth[a]>depth[b])
            ans+=dist[a],a=parent[a];
        else{
            ans+=dist[a],a=parent[a];
            ans+=(2*dist[b]),b=parent[b];
        }
    }
    return a;
}

void Lca(int a,int b){
    while(a!=b){
        if(depth[a]<depth[b])
            ans+=(dist[b]),b=parent[b];
        else if(depth[a]>depth[b])
            ans+=dist[a],a=parent[a];
        else{
            ans+=dist[a],a=parent[a];
            ans+=(dist[b]),b=parent[b];
        }
    }
}

