// make the adjacent list from the edge list
vector<vector<P> > makeAdj(int k, int n, const vector<Edge>& e) {
	// n:the number of vertex
	// k=0:undirected, k=1:directed
	vector<vector<P> > ret(n, vector<P>(0));
	for(int i=0; i<e.size(); ++i) {
		ret[e[i].from].push_back(P(e[i].to, e[i].cost));
		if(k==0) ret[e[i].to].push_back(P(e[i].from, e[i].cost));
	}
	return ret;
}
// Do dijkstra
vector<ll> dijkstra(int s, const vector<vector<P> >& adj) {
	int n=(int)adj.size();
	vector<ll> dis(n, INF*INF);
	priority_queue<P, vector<P>, greater<P> > q;
	dis[s]=0;
	q.push(P(0, s));
	while(!q.empty()) {
		P buf=q.top();
		q.pop();
		ll d=buf.first;
		ll p=buf.second;
		if(dis[p]<d) continue;
		for(int i=0; i<adj[p].size(); ++i) {
			ll nd=adj[p][i].second;
			ll np=adj[p][i].first;
			if(dis[np]>dis[p]+nd) {
				dis[np]=dis[p]+nd;
				q.push(P(dis[np], np));
			}
		}
	}
	return dis;
