#include <vector>

using namespace std;

#define MAX 100001
const long long INF = 1e18;

vector<pair<int, int> > graph[MAX];
long long dist[MAX];

struct option
{
	bool operator() (const pair<int, long long> &a, pair<int, long long> &b) const {
		return a.second > b.second;
	}
};

void Dijkstra(int s)
{
	priority_queue<pair<int, long long>, vector<pair<int, long long> >, option> pq;
	pq.push(make_pair(s, 0));

	dist[s] = 0;

	while(!pq.empty())
	{
		pair<int, long long> top = pq.top();
		pq.pop();

		int u = top.first;
		long long w = top.second;

		for(int i = 0; i < graph[u].size(); i++)
		{
			pair<int, int> v = graph[u][i];

			if(w + v.second < dist[v.first])
			{
				dist[v.first] = w + v.second;
				pq.push(pair<int, long long>(v.first, dist[v.first]));
			}
		}
	}
}

int main()
{
	int N;
	cin >> N;

	for(int i = 0; i < N-1; i++)
	{
		int u, v, w;
		cin >> u >> v >> w;

		graph[v].push_back(pair<int, int>(u, w));
		graph[u].push_back(pair<int, int>(v, w));
	}

	int Q, K;
	cin >> Q >> K;

	for(int i = 1; i <= N; i++)
	{
		dist[i] = INF;
	}

	Dijkstra(K);

	for(int i = 0; i < Q; i++)
	{
		int x, y;
		cin >> x >> y;

		long long first = dist[x];

		long long second = dist[y];

		// cout << "first is " << first << " and second is " << second << endl;
		long long ans = first + second;
		cout << ans << endl;
	}

	return 0;
}

