{
	int to;
	int next;//表示和该边有共同起点的上一条边的标号
	ll val;
}edge[maxn];
ll tot;
int head[maxn];
ll dis[maxn];
int vis[maxn];
int cnt[maxn];
void init()
{
	tot=0;
	memset(head,-1,sizeof(head));
}
void add(int u,int v,int w)
{
	edge[tot].to=v;
	edge[tot].val=w;
	edge[tot].next=head[u];
	head[u]=tot++;
}
void spfa(int s)
{
	memset(cnt,0,sizeof(cnt));
	memset(vis,0,sizeof(vis));
	queue<int> q;
	for(int i=1;i<=N;i++)
	{
		vis[i]=0;
		dis[i]=INF;
	}
	vis[s]=1;
	dis[s]=0;
	q.push(s);
	while(!q.empty())
	{
		int u=q.front();
		q.pop();
		vis[u]=0;
		for(int i=head[u];i!=-1;i=edge[i].next)
		{
			int v=edge[i].to;
			int w=edge[i].val;
			if(dis[u]+w<dis[v])
			{
				dis[v]=dis[u]+w;
				if(!vis[v])
				{
					vis[v]=1;

					q.push(v);
				}
			}
		}
	}
	//默认返回最后一个点最短距离，可更改
}
