using namespace std;
typedef long long ll;

struct edge {
    ll to;
    ll cost;
};

using P = pair<ll, ll>;	// <最短距離, 頂点の番号>
void dijkstra(vector<vector<edge>> &g, vector<ll> &dist, ll s) {
    priority_queue<P, vector<P>, greater<P> > que;
    dist.assign(dist.size(), 1LL<<60);
    dist[s] = 0;
    que.push(P(0, s));
    while (!que.empty()) {
        P p = que.top();
        que.pop();
        ll v = p.second;
        if (dist[v] < p.first) continue;
        for (ll i=0; i<g[v].size(); ++i) {
            edge e = g[v][i];
            if (dist[e.to] > dist[v] + e.cost) {
                dist[e.to] = dist[v] + e.cost;
                que.push(P(dist[e.to], e.to));
            }
        }
    }
}

