vector<long long> shortest(const vector<vector<pair<int, long long>>> &g, int s)
{
	const int N = g.size();
	const long long inf = 1LL << 59;
	vector<long long> ans(N, inf);

	vector<bool> visited(N, false);
	stack<int> waiting;
	auto visit = [&](int x, long long cost) {
		if (!visited[x]) {
			visited[x] = true;
			ans[x] = cost;
			waiting.push(x);
		}
	};
	visit(s, 0);
	while (!waiting.empty()) {
		auto x = waiting.top();
		waiting.pop();
		for (auto &e : g[x]) {
			visit(e.first, ans[x] + e.second);
		}
	}
	return ans;
}

