void di(int x)
{
    S.insert(mp(0, x));
    D[x] = 0;
    while (S.size())
    {
        ll curr = S.begin()->second;
        S.erase(S.begin());
        for (auto it : V[curr])
        {
            ll vertex = it.first;
            ll weight = it.second;
            if (D[vertex] > D[curr] + weight)
            {
                if (D[vertex] != INF)
                    S.erase(S.find(mp(D[vertex], vertex)));
                D[vertex] = D[curr] + weight;
                S.insert(mp(D[vertex], vertex));
            }
        }
    }
}

