        add(b,a,c);
        add(a,b,c);
    }
    int k,q;
    scanf("%d%d",&k,&q);
    dijk(n,q);
    for(int i=1;i<=k;i++){
        scanf("%d%d",&a,&b);
        printf("%lld\n",dist[a]+dist[b]);
    }
    return 0;
}

