using namespace std;
using ll = long long;
const ll INFTY = 1e12;

struct edge{
    int to;
    ll cost;
};

int main(){
    int N;
    cin >> N;
    vector<edge> list[N];
    for(int i=0;i<N-1;i++){
        int a,b;
        ll c;
        cin >> a >> b >> c;
        a--;b--;
        list[a].push_back({b,c});
        list[b].push_back({a,c});
    }

    int q,k;
    cin >> q >> k; k--;
    ll dist[N];
    for(int i=0;i<N;i++) dist[i] = INFTY;
    queue<int> Q;
    Q.push(k);
    dist[k] = 0;
    while(!Q.empty()){
        int u = Q.front(); Q.pop();
        for(auto e : list[u]){
            if(dist[e.to] == INFTY){
                dist[e.to] = dist[u] + e.cost;
                Q.push(e.to);
            }
        }
    }

    for(int i=0;i<q;i++){
        int x,y;
        cin >> x >> y;
        x--;y--;
        cout << dist[x] + dist[y] << endl;
    }
    return 0;
}

