	LL i, j, k, n, m;
	cin >> n;

	vector<VVILL_TYPE> edge(n);

	for (i = 0; i < n - 1; i++) {
		auto temp = MYCP::ReadInts(3);
		temp[0]--;
		temp[1]--;

		VILL_TYPE a;
		a.push_back(ILL_TYPE(temp[1]));
		a.push_back(ILL_TYPE(temp[2]));

		edge[temp[0]].push_back(a);

		swap(temp[0], temp[1]);
		VILL_TYPE reset;
		a = reset;
		a.push_back(ILL_TYPE(temp[1]));
