    while(ch>='0'&&ch<='9'){x=x*10+(ch-'0');ch=getchar();}
    return x*f;
}

struct LCA{
    LL eg;
    LL deep[maxn], head[maxn], fa[maxn][20], vis[maxn], dis[maxn];
    struct A{LL u, v, w, next;}star[maxn*2];
    void init(){
        memset(vis, 0, sizeof vis);
        memset(head, -1, sizeof head);
        memset(dis, 0, sizeof dis);
        eg = 0;
    }
    void ins(LL u,LL v,LL w){
        ++eg, star[eg] = (A){u, v, w, head[u]}, head[u] = eg;
    }
    void insert(LL u,LL v,LL w){
        ins(u,v,w);ins(v,u,w);
    }
    void dfs(LL u){
        vis[u]=1;
        for(LL i=1; i<=18; i++){
            if(deep[u] < (1<<i))break;
            fa[u][i] = fa[fa[u][i-1]][i-1];
        }
        for(LL i=head[u]; ~i; i=star[i].next){
            LL v = star[i].v;
            if(vis[v]) continue;
            deep[v] = deep[u]+1;
            fa[v][0] = u;
            dis[v] = dis[u] + star[i].w;
            dfs(v);
        }
    }
    LL lca(LL u, LL v){
        if(deep[u] < deep[v]) swap(u, v);
        LL d=deep[u]-deep[v];
        for(LL i=0;i<=18;i++)
            if((1<<i)&d) u = fa[u][i];
        for(LL i=18;i>=0;i--)
            if(fa[u][i]!=fa[v][i]){
                u=fa[u][i];v=fa[v][i];
            }
        if(u == v)return u;
        return fa[u][0];
    }
    void solve(LL n){
        init();
        for(LL i=1; i<n; i++){
            LL u, v, w;
            scanf("%lld%lld%lld", &u, &v, &w);
            insert(u, v, w);
        }
        LL m, k;
        scanf("%lld%lld", &m, &k);
        dfs(1);
        for(LL i=1; i<=m; i++){
            LL u, v, w;
            scanf("%lld%lld", &u, &v);
            printf("%lld\n", dis[u] + dis[k] - 2*dis[lca(u, k)] + dis[v] + dis[k] - 2*dis[lca(v, k)]);
        }
    }
}solver;


int main(){
    LL n;
    while(~scanf("%lld", &n)){
        solver.solve(n);
    }
    return 0;
}

