const int MaxN = 1000;
typedef long long LL;

LL n, all, m;

int pre[MaxN + 5], last[MaxN + 5], other[MaxN + 5];int seq[MaxN + 5];
LL dis[MaxN + 5], cost[MaxN + 5];
bool Inque[MaxN + 5];


void Build(int x, int y, LL w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int s)
{
	int head = 1, tail = 1, now, ed, dr;
	seq[tail] = s;
	for(int i = 1; i <= n; i++)
	{
		if(i == s) dis[i] = 0;
		else dis[i] = 10000000000;
	}
	Inque[s] = 1;
	while(head <= tail)
	{
		now = seq[head];
		ed = last[now];
		while(ed != -1)
		{
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr])
			{
				dis[dr] = dis[now] + cost[ed];
				if(!Inque[dr])
				{
					Inque[dr] = 1;
					seq[++tail] = dr;
				}
			}
			ed = pre[ed];
		}
		Inque[now] = 0;
		head++;
	}
}


int main()
{
	all = -1;
	memset(last, -1, sizeof(last));
	scanf("%d", &n);
	for(int i = 1; i <= n - 1; i++)
	{
		int a, b;
		LL w;
		scanf("%d %d %lld", &a, &b, &w);
		Build(a, b, w);
		Build(b, a, w);
	}
	memset(seq, 0, sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	int a, b;
	scanf("%d %d", &a, &b);
	Bfs(b);
	for(int i = 1; i <= a; i++)
	{
		LL ans = 0;
		int x, y;
		scanf("%d %d", &x, &y);
		ans += dis[x];
		ans += dis[y];
		printf("%lld\n", ans);
	}
	return 0;
}

