struct option
{
	bool operator() (const pair<int, long long> &a, pair<int, long long> &b) const {
		return a.second > b.second;
	}
};

void Dijkstra(int s)
{
	priority_queue<pair<int, long long>, vector<pair<int, long long> >, option> pq;
	pq.push(make_pair(s, 0));

	dist[s] = 0;

	while(!pq.empty())
	{
		pair<int, long long> top = pq.top();
		pq.pop();

		int u = top.first;
		long long w = top.second;

		for(int i = 0; i < graph[u].size(); i++)
		{
			pair<int, int> v = graph[u][i];

			if(w + v.second < dist[v.first])
			{
				dist[v.first] = w + v.second;
				pq.push(pair<int, long long>(v.first, dist[v.first]));
			}
		}
	}
}

