#define INF (1ULL << 60)

struct Node {
    unsigned long long adj_cost;
    int next_node;

    Node(unsigned long long adj_cost, int next_node) {
        this->adj_cost = adj_cost;
        this->next_node = next_node;
    }
};

void depth_first_search(int current_node, int prev_node, unsigned long long total_cost, 
                        vector<vector<Node>> &nodes, vector<unsigned long long> &dist) {
    dist[current_node] = total_cost;
    for (auto n: nodes[current_node]) {
        if (n.next_node == prev_node) {
            continue;
        }
        depth_first_search(n.next_node, current_node, n.adj_cost + total_cost, nodes, dist);
    }
}

int main() {
    int N;
    cin >> N;

    vector<vector<Node>> nodes(N, vector<Node>(0, {INF, -1}));
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        unsigned long long c;
        cin >> a >> b >> c;
        a--;
        b--;
        nodes[a].emplace_back(c, b);
        nodes[b].emplace_back(c, a);
    }

    int Q, K;
    cin >> Q >> K;
    K--;

    vector<unsigned long long> dist_to_K(N, INF);
    depth_first_search(K, -1, 0, nodes, dist_to_K);

    for (int i = 0; i < Q; i++) {
        int x, y;
        cin >> x >> y;
        x--;
        y--;
        cout << dist_to_K[x] + dist_to_K[y] << endl;
    }
    return 0;
}

