{
	e[++cnt].to=v; e[cnt].next=head[u]; head[u]=cnt; e[cnt].w=w;
}

void dfs(int u,int fas)
{
	dep[u]=dep[fas]+1;
	for(int i=head[u];i;i=e[i].next)
	{
		int v=e[i].to; 
		if(v==fas) continue;
		fa[v][0][0]=u; fa[v][0][1]=e[i].w;
		dfs(v,u);
	}
}

int lca(int x,int y)
{
	if(dep[x]<dep[y]) swap(x,y);
	for(int i=17;i>=0;i--)
		if(dep[y]<=dep[fa[x][i][0]]) x=fa[x][i][0];
	if(x==y) return x;
	for(int i=17;i>=0;i--)
		if(fa[x][i][0]!=fa[y][i][0]) 
		{
			x=fa[x][i][0]; 
			y=fa[y][i][0];
		}
	return fa[x][0][0];
}


LL lca1(int x,int y)
{
	LL res=0;
	if(dep[x]<dep[y]) swap(x,y);
	for(int i=17;i>=0;i--)
		if(dep[y]<=dep[fa[x][i][0]]) res+=fa[x][i][1],x=fa[x][i][0];
	if(x==y) return res;
	//printf("hhh %d %d\n",x,y);
	for(int i=17;i>=0;i--)
		if(fa[x][i][0]!=fa[y][i][0]) 
		{
			res+=fa[x][i][1]; res+=fa[y][i][1];
			x=fa[x][i][0]; 
			y=fa[y][i][0];
		}
	res+=fa[x][0][1]+fa[y][0][1];
	return res;
}
