    Graph.at(a).push_back(make_pair(b, c));
    Graph.at(b).push_back(make_pair(a, c));
  }
  cin >> Q >> K;
  vector<pair<int64_t, int64_t>> vp(Q);
  for (int i = 0; i < Q; i++)
  {
    cin >> x >> y;
    vp.at(i) = make_pair(x, y);
  }
  dijkstra();
  for (auto p : vp)
  {
    tie(x, y) = p;
    cout << D.at(x) + D.at(y) << endl;
  }
}

