bool bo[100001]={false};
ll dfs(int x,int y,vector<ll>a,vector<ll>b,vector<ll>c){
  queue<int> s;
  queue<int> q;
  bo[x]=true;
  ll sum=0;;
  for(int i=0;i<a.size();i++){
    if(a[i]==x){
      s.push(b[i]);
      q.push(c[i]);
    }
    if(b[i]==x){
      s.push(a[i]);
      q.push(c[i]);
    }
  }
  if(s.size()==0){
    bo[x]=false;
    return -1000000000000000;
  }
  while(s.size()>0){
    int fi=s.front();
    s.pop();
    int dis=q.front();
    q.pop();
    if(s==y) sum+=dis;
    else if(bo[s]==true) sum=-1000000000000000;
    else{
      sum+=dis;
      sum+=dfs(s,y,a,b,c);
    }
    if(sum>0){
      bo[x]=false;
      return sum;
    }
  }
  return 0;
}

