long long dist[100005];

void dij(int s){
	priority_queue<pli,vector<pli>,greater<pli> > pq;
	dist[s]=0;
	pq.push(pli(0,s));
	while(!pq.empty()){
		pli v=pq.top();
		pq.pop();
		long long dis=v.first;
		int pos=v.second;
		for(int i=0;i<adj[pos].size();i++){
			pil u=adj[pos][i];
			int npos=u.first;
			long long len=u.second;
			if(dis+len<dist[npos]){
				dist[npos]=dis+len;
				pq.push(pli(dist[npos],npos));
			}
		}
	}
}

