int main()
{
    cin >> N;
    ll* a = new ll[N];
    ll* b = new ll[N];
    ll* c = new ll[N];
    connection = new ll*[N];
    for(ll i = 0; i < N; i ++){
        connection[i] = new ll[N];
        for(ll n = 0; n < N; n ++){
            connection[i][n] = LLONG_MAX;
        }
    }
    for(ll i = 0; i < N - 1; i ++){
        cin >> a[i] >> b[i] >> c[i];
        a[i] --;
        b[i] --;
        connection[a[i]][b[i]] = c[i];
        connection[b[i]][a[i]] = c[i];
    }

    //ダイクストラ
    priority_queue<pair<ll,ll> >pq;
    // weight[v]に始点sからvまでの最短コストを保存する
    ll weight[N];
    // 訪問状態を記録
    bool searched[N];
    for(ll i = 0; i < N; i ++){
        searched[i] = false;
        weight[i] = LLONG_MAX;
    }

    ll Q, K;
    ll* x;
    ll* y;
    cin >> Q >> K;
    K --;
    x = new ll[Q];
    y = new ll[Q];
    for(ll i = 0; i < Q; i ++){
        cin >> x[i] >> y[i];
        x[i] --; 
        y[i] --;
    }

    pq.push(make_pair(0, K));

    // priority_queue dicstra
    while(!pq.empty()){
        pair<ll,ll> first = pq.top();
        pq.pop();
        ll node = first.second;
        ll u = -first.first;
        //cout << node << "/" << u << endl;
        searched[node] = true;

        for(ll i = 0; i < N; i ++){
            if(searched[i]) continue;
            if(connection[i][node] == LLONG_MAX) continue;
            if(connection[i][node] + u < weight[i]){
                //cout << i << "/" << node << ":" << connection[i][node] << "," << u << endl;
                weight[i] = connection[i][node] + u;
                pair<ll,ll> newPair = make_pair(weight[i] * -1, i);
                pq.push(newPair);
            }
        }
    }

    for(ll i = 0; i < Q; i ++){
        cout << (weight[x[i]] + weight[y[i]]) << endl;
    }


    return 0;
}

