int lca(int u, int v) {
	if (d[u] > d[v])swap(u, v);
	rep(i, 20) {
		if ((d[v] - d[u]) >> i & 1)v = par[i][v];
	}
	if (u == v)return u;
	for (int i = 19; i >= 0; i--) {
		if (par[i][u] != par[i][v]) {
			u = par[i][u]; v = par[i][v];
		}
	}
	return par[0][u];
}
ll dist(int x,int y){
	return d[x]+d[y]-d[lca(x,y)]*2;
}
