const long long sss=1e14+5;
typedef struct node
{
    int adj;
    long long data;//adj为邻接点，data为边的权值
    struct node *next;
} node;

node *g[100005];
long long dis[100005];
int flag[100005],q[100005];//dis记录最短路径值，flag做出入队标记，q为队列
int n;
void spfa(int st)
{
    long long i,k,front,rear;
    node *p;
    for(i=1; i<=n; i++)
        dis[i]=sss;//初始化路径为长整型最大数
    memset(flag,0,sizeof(flag));//入队标记初始化为0
    front=0;
    rear=1;
    //将起始点入队
    dis[st]=0;//到自己距离为0
    q[rear]=st;//入队
    flag[st]=1;//置入队标记
    while(front!=rear)//当队列不为空时
    {
        front=(front+1)%100005;//出队，注意使用循环队列
        k=q[front];//记下出队点号
        flag[k]=0;//置出队标记
        p=g[k];//找到以出队点为头的邻接链表，考察由出队点中转至各邻接点路径是否更短
        while(p)
        {
            if(dis[k]+p->data<dis[p->adj])
            {
                dis[p->adj]=dis[k]+p->data;//路径更短，更新路径值
                if(!flag[p->adj])//若其邻接点未入队
                {
                    rear=(rear+1)%100005;//入队
                    q[rear]=p->adj;
                    flag[p->adj]=1;//*置入队标记
                }
            }
            p=p->next;/*记得改变循环变量，考察下一个邻接点*/
            //cout<<dis[k]<<endl;
        }
    }
}
int main()
{
    int i,x,y,q,k;
    long long z;
    node *p,*ss;
    scanf("%d",&n);//读入点数，边数
    memset(g,0,sizeof(g));//初始化图
    for(i=1; i<=n-1; i++) //读入边的信息，左点、右点、权值
    {
        scanf("%d%d%lld",&x,&y,&z);
        p=(node*)malloc(sizeof(node));//创建链表
        p->data=z;
        p->adj=y;
        p->next=g[x];//尾插法
        g[x]=p;
        ss=(node*)malloc(sizeof(node));//创建链表
        ss->data=z;
        ss->adj=x;
        ss->next=g[y];//尾插法
        g[y]=ss;
    }
    scanf("%d%d",&q,&k);
    spfa(k);//计算由起始点到各点的最短路径
    for(i=0;i<q;i++)
    {
        scanf("%d%d",&x,&y);
        //printf("%d %d\n",dis[x],dis[y]);
        printf("%lld\n",dis[x]+dis[y]);
    }
    return 0;
}

