using namespace std;

using P = pair<int, int>;
using ll = long long;

const int MAX_V = 100000;
const int MAX_LOG_V = 17;

vector<P> G[MAX_V];
int root = 0;

int parent[MAX_LOG_V][MAX_V];
int depth[MAX_V];
ll dist[MAX_V];

void dfs(int v, int p, int d) {
	parent[0][v] = p;
	depth[v] = d;
	for (int i = 0; i < G[v].size(); i++) {
		if (G[v][i].first != p) {
			dist[G[v][i].first] = dist[v] + G[v][i].second;
			dfs(G[v][i].first, v, d + 1);
		}
	}
}

void init(int V) {
	dfs(root, -1, 0);
	for (int k = 0; k + 1 < MAX_LOG_V; k++) {
		for (int v = 0; v < V; v++) {
			if (parent[k][v] < 0) parent[k + 1][v] = -1;
			else parent[k + 1][v] = parent[k][parent[k][v]];
		}
	}
}

int lca(int u, int v) {
	if (depth[u] > depth[v]) swap(u, v);
	for (int k = 0; k < MAX_LOG_V; k++) {
		if ((depth[v] - depth[u]) >> k & 1) {
			v = parent[k][v];
		}
	}
	if (u == v) return u;
	for (int k = MAX_LOG_V - 1; k >= 0; k--) {
		if (parent[k][u] != parent[k][v]) {
			u = parent[k][u];
			v = parent[k][v];
		}
	}
	return parent[0][u];
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	for (int i = 1; i < n; i++) {
		int a, b, c;
		cin >> a >> b >> c;
		a--;
		b--;
		G[a].emplace_back(b, c);
		G[b].emplace_back(a, c);
	}

	init(n);
	int q, k;
	cin >> q >> k;
	k--;
	for (int i = 0; i < q; i++) {
		int x, y;
		cin >> x >> y;
		x--;
		y--;
		int u = lca(x, k);
		int v = lca(y, k);
		ll ans = dist[x] + dist[k] - dist[u] * 2;
		ans += dist[y] + dist[k] - dist[v] * 2;
		cout << ans << endl;
	}
	return 0;
}

