int main(){

  ll N = il();

  //使い方
  Graph graph(N); //頂点数を入れて宣言しないとバグる
  rep(i, N-1){
    ll fromidx = il() - 1;
    ll toidx = il() - 1; // 0-indexed
    ll weight = il();
    graph.addUEdge(fromidx, toidx, weight); //無向辺の場合はこれ。有向辺ならaddEdge
  }

  ll Q = il();
