  // グラフとスタート地点のidxを渡すと、vectorを返す
  // vector[t] = 頂点tへの累計最小重み。vector[s] = 0となる
  vector<ll> result = dijkstra(graph, K);

  rep(i, Q){
    ll x = il() - 1;
    ll y = il() - 1;
    cout << result[x] + result[y] << endl;
  }

}

