#include <bits/stdc++.h>
#define ll long long
using namespace std;

const int LOGMAX = 19;

int n;
vector<vector<pair<int, int>>> g;
vector< vector<ll> > cost;
vector< vector<int> > dp;

vector< pair<int, int> > p;
vector< bool > used;

int t = 0;

vector<int> tin, tout;

void hang(int v) {
    used[v] = true;
    tin[v] = t++;
    for (pair<int, int> par : g[v]) {
        int u = par.first;
        int c = par.second;
        if (!used[u]) {
            p[u] = {v, c};
            hang(u);
        }
    }
    tout[v] = t++;
}

bool is_parent(int a, int b) { // is a parent of b
    return (tin[a] <= tin[b]) && (tout[a] >= tout[b]);
}

int LCA(int a, int b) {
    //cout << "LCA(" << a << "," << b << ") is ";
    if (is_parent(a, b)){
        //cout << a << "\n";
        return a;
    }
    if (is_parent(b, a)) {
        //cout << b << "\n";
        return b;
    }
    for (int i = LOGMAX - 1; i >= 0; --i) {
        int next_a = dp[a][i];
        if (!is_parent(next_a, b)) a = next_a;
    }
    //cout << dp[a][0] << "\n";
    return dp[a][0];
}

ll get_price(int a, int b) {
    int c = LCA(a, b);
    ll res = 0;
    for (int level = LOGMAX - 1; level >= 0; --level) {
        int a_next = dp[a][level], b_next = dp[b][level];
        if (is_parent(c, a_next)) {
            res += cost[a][level];
            a = a_next;
        }
        if (is_parent(c, b_next)) {
            res += cost[b][level];
            b = b_next;
        }
    }
    if (dp[a][0] == c) {
        res += cost[a][0];
    }
    if (dp[b][0] == c) {
        res += cost[b][0];
    }
    return res;
}

ll get_ans(int a, int b, int k) {
    return get_price(a, k) + get_price(k, b);
}

int main()
{
    cin.tie(0);
    ios_base::sync_with_stdio(false);

    cin >> n;
    g.resize(n);
    cost.resize(n);
    dp.resize(n);
    p.resize(n);
    tin.resize(n);
    tout.resize(n);
    for (int i = 0; i < n; ++i) {
        cost[i].resize(LOGMAX);
        dp[i].resize(LOGMAX);
    }

    used.resize(n, false);

    for (int i = 0; i < n - 1; ++i) {
        int a, b, c;
        cin >> a >> b >> c;
        --a;
        --b;
        g[a].push_back({b, c});
        g[b].push_back({a, c});
    }
    p[0] = {0, 0};
    hang(0);

    for (int i = 0; i < n; ++i) {
        cost[i][0] = p[i].second;
        dp[i][0] = p[i].first;
    }
    for (int level = 1; level < LOGMAX; ++level) {
        for (int i = 0; i < n; ++i) {
            cost[i][level] = cost[i][level - 1] + cost[dp[i][level - 1]][level - 1];
            dp[i][level] = dp[dp[i][level - 1]][level - 1];
        }
    }
    int q, k;
    cin >> q >> k;
    --k;
    for (int i = 0; i < q; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        cout << get_ans(a, b, k) << "\n";
    }
}

