class dijkstra{
private:
	typedef pair<ll,int> pa; //first:最短距離 second:頂点番号
	int V,E;//頂点数,辺数
	vector<vector<edge>> G;
	vector<ll> d;
public:
	dijkstra(int v, int e){
		V = v;
		E = e;
		G.resize(V+5);
		d.resize(V+5);
	}
	void run(int s){//O(|E|log|V|)
    	rp_queue(pa) que;
    	fill(d.begin(),d.end(),linf);
    	d[s] = 0;
    	que.push(pa(0,s));
    	while(!que.empty()){
        	pa p = que.top();que.pop();
        	int v = p.sd;
        	if(d[v] < p.ft)continue;
        	rep(i,0,sz(G[v])){
            	edge e = G[v][i];
            	if(d[e.to] > d[v] + e.cost){
                	 d[e.to]=d[v] + e.cost;
                 	que.push(pa(d[e.to],e.to));
            	}
        	}
    	}
	}

	void addpath(int a,int b,int c){
		edge e;
    	e.to = b;
    	e.cost = c;
    	G[a].pb(e);
	}

	ll cost(int v){
		return d[v];
	}
};

