typedef long long LL;

const int MaxN = 1e5;
int n, m;
LL all;
int pre[2*MaxN + 5], last[2*MaxN + 5], other[2*MaxN + 5];
LL cost[2*MaxN + 5];
LL	dis[MaxN + 5];
int seq[MaxN + 5];
bool Inque[MaxN + 5];


void Build(int x, int y, LL w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int s)
{
	LL head = 1, tail = 1, now, ed, dr;
	seq[tail] = s;
	for(int i = 1; i <= n; i++)
	{
		if(i == s) dis[i] = 0;
		else dis[i] = 1ll << 60;
	}
	Inque[s] = 1;
	while(head <= tail)
	{
		now = seq[head];
		ed = last[now];
		while(ed != -1)
		{
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr])
			{
				dis[dr] = dis[now] + cost[ed];
				if(!Inque[dr])
				{
					Inque[dr] = 1;
					seq[++tail] = dr;
				}
			}
			ed = pre[ed];
		}
		Inque[now] = 0;
		head++;
	}
}

int main()
{
	all = -1;
	memset(last, -1, sizeof(last));
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int a,b;
		LL w;
		scanf("%d %d %lld", &a, &b, &w);
		Build(a, b, w); Build(b, a, w);
	}
	int q,k,u,v;
	scanf("%d %d",&q,&k);
	memset(seq, 0, sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	Bfs(k);
	while(q--){
			scanf("%d %d",&u,&v);
		printf("%lld\n", dis[u]+dis[v]);
	}
	return 0;
}

