#include<bits/stdc++.h>
using namespace std;

const int maxn=1e6+5;

vector<pair<int,int> >e[maxn];//二维数组，第一维是点的序号，第二维是该点所连接的点的数量
//first是该点连接的点的序号，second是该点到所连接点的权值

int n,m,dis[maxn];

void init()
{
    for(int i=0;i<maxn;i++)e[i].clear();
    for(int i=0;i<maxn;i++)dis[i]=1e9;
}

void dij(int s)
{
    priority_queue<pair<int,int> >q;
    dis[s]=0;
    q.push(make_pair(-dis[s],s));
    while(!q.empty())
    {
        int now=q.top().second;//当前离起点最近的点（最短路已经确定的点）
        q.pop();
        for(int i=0;i<e[now].size();i++)
        {
            int v=e[now][i].first;//更新该点所连接的所有点
            if(dis[v]>dis[now]+e[now][i].second)
            {
                dis[v]=dis[now]+e[now][i].second;
                q.push(make_pair(-dis[v],v));//更新成功则入队
            }
        }
    }
}

int main()
{
    ios_base::sync_with_stdio(0),cin.tie(0);
    while(cin>>n)
    {
        int q;
        init();
        for(int i=0;i<n-1;i++)
        {
            int x,y,z;
            cin>>x>>y>>z;
            e[x].push_back(make_pair(y,z));
            e[y].push_back(make_pair(x,z));
        }
        int s,t;
        cin>>q>>s;
        dij(s);
        while(q--)
        {
            int a,b;
            cin>>a>>b;
            cout<<dis[a]+dis[b]<<endl;
        }
    }
    return 0;
}

