using namespace std;
typedef pair<int, int> P;
struct Edge
{
	int to;
	int cost;
};
vector<Edge> V[100001];

void solve()
{
	int N;
	cin >> N;
	vector<long long int> D(N);
	for (int i = 0; i < N; ++i)
	{
		D[i] = 1LL << 62;
	}

	for (int i = 0; i < N - 1; ++i)
	{
		int a, b, c;
		cin >> a >> b >> c;
		--a;
		--b;
		Edge e;
		e.to = b;
		e.cost = c;
		V[a].push_back(e);
		e.to = a;
		V[b].push_back(e);
	}
	int Q, K;
	cin >> Q >> K;
	D[K - 1] = 0;
	priority_queue<P, vector<P>, greater<P> > que;
	que.push(P(0, K - 1));
	while (!que.empty())
	{
		P p = que.top();
		que.pop();
		int v = p.second;
		if (D[v] < p.first)
		{
			continue;
		}
		for (int i = 0; i < V[v].size(); ++i)
		{
			Edge e = V[v][i];
			if (D[e.to] > D[v] + e.cost)
			{
				D[e.to] = D[v] + e.cost;
				que.push(P(D[e.to], e.to));
			}
		}
	}
	for (int i = 0; i < Q; ++i)
	{
		int x, y;
		cin >> x >> y;
		cout << D[x - 1] + D[y - 1] << endl;
	}
}

int main()
{
	solve();
	return(0);
}

