#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int INF = 1000000000;

int main()
{
  int N; scanf("%d", &N);
  vector<vector<pair<int, ll>>> adj(N + 5, vector<pair<int, ll>>());
  for (int i = 0; i < N - 1; ++i) {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);
    adj[a].push_back(make_pair(b, c));
    adj[b].push_back(make_pair(a, c));
  }

  int Q, K;
  scanf("%d %d", &Q, &K);
  vector<ll> dist(N + 5, numeric_limits<ll>::max());
  dist[K] = 0;
  priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> que;
  que.push(make_pair(0, K));
  while (not que.empty()) {
    pair<ll, int> p = que.top(); que.pop();
    ll d = p.first;
    int u = p.second;
    if (d > dist[u]) { continue; }
    for (pair<ll, int> p : adj[u]) {
      int v = p.first;
      ll cost = p.second;
      if (d + cost < dist[v]) {
        dist[v] = d + cost;
        que.push(make_pair(dist[v], v));
      }
    }
  }
  for (int i = 0; i < Q; ++i) {
    int x, y;
    scanf("%d %d", &x, &y);
    printf("%lld\n", dist[x] + dist[y]);
  }
  return 0;
}

