#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<ll, ll>;
const ll INF = (ll)1e18;

struct edge {
  ll to, cost;

  edge(ll f, ll t, ll c) {
    to = t;
    cost = c;
  }
};

struct graph {
  ll V;
  vector<vector<edge>> G;
  vector<ll> d;

  graph(ll n) { init(n); }

  void init(ll n) {
    V = n;
    G.resize(V);
    d.resize(V);
  }

  void add_edge(ll s, ll t, ll cost) { G[s].push_back(edge(s, t, cost)); }

  void Dijkstra(ll s) {
    for (int i = 0; i < V; i++) {
      d[i] = INF;
    }
    d[s] = 0;

    priority_queue<P, vector<P>, greater<P>> que;
    que.push(P(0, s));

    while (!que.empty()) {
      P p = que.top();
      que.pop();
      ll v = p.second;

      if (d[v] < p.first) {
        continue;
      }

      for (auto e : G[v]) {
        if (d[e.to] > d[v] + e.cost) {
          d[e.to] = d[v] + e.cost;
          que.push(P(d[e.to], e.to));
        }
      }
    }
  }
};

ll N, Q, K;
vector<ll> x, y;
graph G = graph(N);

