using namespace std;

struct tree
{
	vector<int> con;
	vector<long long> dis;
	vector<int> child;
	long long from_root;
	bool end;
};

tree node[100005];

void preorder(int id)
{
	node[id-1].from_root=0;
	node[id-1].end=true;
	for(int i=1;i<=node[id-1].con.size();i++)
	{
		int ad=node[id-1].con[i-1];
		if(node[ad-1].end==true)
			node[id-1].from_root+=node[ad-1].from_root+node[id-1].dis[i-1];
		else
			node[id-1].child.push_back(node[id-1].con[i-1]);
	}
	for(int i=1;i<=node[id-1].child.size();i++)
	{
		preorder(node[id-1].child[i-1]);
	}
}

int main(void)
{
	int n;
	cin >> n;
	for(int i=1;i<=n-1;i++)
	{
		int a,b,c;
		cin >> a >> b >> c;
		node[a-1].con.push_back(b);
		node[a-1].dis.push_back(c);
		node[b-1].con.push_back(a);
		node[b-1].dis.push_back(c);
	}
	for(int i=1;i<=n;i++)node[i-1].end=false;

	int q,k;
	cin >> q >> k;
	preorder(k);

	for(int i=1;i<=q;i++)
	{
		int x,y;
		cin >> x >> y;
		cout << node[x-1].from_root+node[y-1].from_root << endl;
	}
}

