		scanf("%d %d %lld", &a, &b, &w);
		Build(a, b, w); Build(b, a, w);
	}
	int q,k,u,v;
	scanf("%d %d",&q,&k);
	memset(seq, 0, sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	Bfs(k);
	while(q--){
			scanf("%d %d",&u,&v);
		printf("%d\n", dis[u]+dis[v]);
	}
	return 0;
}

