ll XtoY(int K, int x, int y)
{
	vector<ll> D(N);
	vector<int> Xin(N, 0);

	bool xf = false, yf = false;

	Xin[K] = 1; D[K] = 0;

	queue<int> qu;

	qu.push(K);

	while (!xf || !yf)
	{
		int u = qu.front();
		qu.pop();

		for (int v = 0; v < N; ++v)
		{
			if (cost[u][v] == 0) { continue; }

			D[v] = D[u] + cost[u][v];

			if (v == x) { xf = true; }
			if (v == y) { yf = true; }

			qu.push(v);
		}
	}

	return D[x] + D[y];

}

