	vector<ll> x(Q), y(Q);
	for (ll i = 0; i < Q; i++) {
		cin >> x[i] >> y[i];
		x[i]--; y[i]--;
	}

	dijkstra(K);

	for (ll i = 0; i < Q; i++) {
		cout << d[x[i]]+d[y[i]] << endl;
	}

}

