		ll d = p.first;
		int v = p.second;
		if (dist[v] < d) continue;
		rep (i, (int)G[v].size()){
			ll cost = G[v][i].first;
			int to  = G[v][i].second;
			if (dist[to] > dist[v] + cost){
				dist[to] = dist[v] + cost;
				que.push(LI(dist[to], to));
			} // end if
		} // end rep
	} // end while
}

