using namespace std;
class class_Dijkstra{
public:
	class_Dijkstra(){};
	virtual ~class_Dijkstra(){};
	void Init(int N);
	void Set_Line(int a,int b , int64_t distance);
	bool Search(int startPoint, int targetPoint,int maxStep , int64_t maxDistance , int64_t &rtn_Distance);
	void DispPath(int startPoint , int targetPoint);
	vector< multimap<int64_t,int> > Connect; // 相手の点番号と距離
	vector<double> Distance; // 始点から この点までの最短距離
//	vector<int> StepCnt; // 始点からの中継点数
//	vector<int> BeforePointNb; // 最短経路での 一つ前の点
	vector<int> Color;	// 0:白 , 1:グレー , 2:黒
	multimap<int64_t,int> Que; // 距離 と 相手点番号
	int PointMax=0;
};

void class_Dijkstra::Init(int N){
	PointMax = N;
	Connect.clear();
	Connect.resize(N);

	Distance.clear();
	Distance.resize(N);
	for(int i=0;i<N;i++){
		Distance[i] = LLONG_MAX;
	}

	Color.clear();
	Color.resize(N);

	Que.clear();
}

void class_Dijkstra::Set_Line(int a, int b , int64_t distance){
	Connect[a].insert(make_pair(distance,b));
	Connect[b].insert(make_pair(distance,a));
}

void class_Dijkstra::DispPath(int startPoint , int targetPoint){
	assert(Color[startPoint]==2);
	assert(Color[targetPoint]==2);
	int num = targetPoint;
	printf("(%d)",num);

/*	while(1){
		printf("<= %1.1f =(%d)",Distance[num]-Distance[BeforePointNb[num]] , BeforePointNb[num] );
		num = BeforePointNb[num];
		if (num == startPoint){break;}
	}
*/	printf("\n");
}


bool class_Dijkstra::Search(int startPoint , int targetPoint,int maxStep , int64_t maxDistance , int64_t &rtn_Distance){

	// 作業vector 初期値設定
	for(int i=0;i<PointMax;i++){
		Distance[i] = LLONG_MAX;
//		StepCnt[i] = 0;
//		BeforePointNb[i] = 0;
		Color[i] = 0;
	}
	Que.clear();
	rtn_Distance = 0.0;

	// スタート地点
	Distance[startPoint] = 0.0;
	Color[startPoint] = 1;
	Que.insert( make_pair(0.0,startPoint) ); // スタートをQueに登録

	while(1){
		if (Que.empty() ){return false;}// 経路を探索し尽くした

		// Que内の 先頭(最短距離) 点を取得
		auto top = Que.begin();
		int current_Point = top->second;
		double current_Distance = top->first;
		Que.erase(top); // Que から先頭要素を取り出す

//		if ( maxStep <= StepCnt[current_Point] ) {return false;} // 中継点数が上限を超えた
		if ( maxDistance <= current_Distance ) {return false;} // 距離 が 上限を超えた
		if ( current_Point == targetPoint) {// 目標点に到達した
			Color[current_Point] = 2;
			rtn_Distance = current_Distance;
			return true;
		}
		for(auto nextPoint : Connect[current_Point])
		{
//fprintf(stderr,"Current_Point %d , nextPoint %d , dist %2.2lf \n",current_Point,nextPoint.second,nextPoint.first);
			if (Color[nextPoint.second] == 2) {continue;}

			// 現点までの最短距離 + 次点までの距離 < 次点-始点 間の最短距離(候補)
			if ( Distance[current_Point] + nextPoint.first < Distance[nextPoint.second]) {
				// 次点-始点 間の最短距離 の更新

				if (Color[nextPoint.second] == 1) {
					// 現項目を Que から 一旦削除
					auto P = Que.equal_range( Distance[nextPoint.second] );
					for (auto it = P.first; it != P.second; ++it) {
						if (it->second == nextPoint.second){
							Que.erase(it);
							break;
						}
					}
				}

				Distance[nextPoint.second] = Distance[current_Point] + nextPoint.first;
//				StepCnt[nextPoint.second] = StepCnt[current_Point] + 1;
//				BeforePointNb[nextPoint.second] = current_Point;

				// Que への新規追加
				Que.insert( make_pair(Distance[nextPoint.second],nextPoint.second) );
				Color[nextPoint.second] =1 ;
			}
		}
		Color[current_Point] = 2; // カレント点からの探索終了
	}
}


