		temp[0]--;
		temp[1]--;

		VILL_TYPE a;
		a.push_back(ILL_TYPE(temp[1]));
		a.push_back(ILL_TYPE(temp[2]));

		edge[temp[0]].push_back(a);

		swap(temp[0], temp[1]);
		VILL_TYPE reset;
		a = reset;
		a.push_back(ILL_TYPE(temp[1]));
		a.push_back(ILL_TYPE(temp[2]));

		edge[temp[0]].push_back(a);
	}

	LL q;
