		cin >> x[i] >> y[i];
		x[i]--;
		y[i]--;
	}

	VILL_TYPE d(n, ILL_TYPE::plus_inf());
	d[k] = 0;

	stack<LL> ls;
	ls.push(k);

	LL count = 0;

	while (!ls.empty())
	{
		count++;

		auto itr = ls.top();

		for (i = 0; i < edge[itr].size(); i++) {
			auto a = edge[itr][i][0].getN();
			auto b = edge[itr][i][1];

			if (d[itr] + b < d[a]) {
				d[a] = d[itr] + b;

				ls.push(a);
			}
		}

		ls.pop();
	}

