vector<ll> dijkstra(int s) {
    vector<ll> dist(N, 1e18);
    priority_queue<pli, vector<pli>, greater<pli>> que;
    dist[s] = 0;
    que.push({0, s});
    while (!que.empty()) {
        pli v = que.top();
        que.pop();
        if (v.first > dist[v.second])
            continue;
        for (auto nv : G[v.second]) {
            if (dist[nv.second] > nv.first + dist[v.second]) {
                dist[nv.second] = nv.first + dist[v.second];
                que.push({dist[nv.second], nv.second});
            }
        }
    }
    return dist;
}

