vector<ll> dist;
void dfs(const vector<vector<pair<int,ll>>> &G, int v) {

    // v から行ける各頂点 next_v について
    for (auto next_v : G[v]) {
        if (dist[next_v.F]>=0) continue; // next_v が探索済だったらスルー
        dist[next_v.F] = dist[v] + next_v.S;
        dfs(G, next_v.F); // 再帰的に探索
    }
}

