typedef long long ll;
typedef pair<int,ll> P;


void dist(int i,vector<vector<P>> V,vector<ll> d){
	d[i]=0;
	priority_queue<P,vector<P>,greater<>> que;
	que.push(P(i,0));

	while(!que.empty()){
		P p=que.top();que.pop();
		int u=p.first;
		if(d[u]<p.second) continue;
		for(int k=0;k<V[u].size();k++){
			int v=V[u][k].first;
			ll length=V[u][k].second;
			ll alt=d[u]+length;
			if(d[v]>alt){
				d[v]=alt;
				que.push(P(v,alt));
				//cout<<v<<"="<<alt<<endl;
			}
		}
	}
	return;
}

