int dfs(long long s, long long cost){
  map<long long, long long> mp_dist = lpath[s];
  for (auto it = mp_dist.begin();it != mp_dist.end();it++) {
    if (!visited[it->first]) {
      dist[it->first] = cost + it->second;
      visited[it->first] = 1;
      dfs(it->first, dist[it->first]);
    }
  }
  return(0);
}

