int getLeave(){
    for(int i=0; i<N; ++i){
        if(to[i].size() == 1){
            return i;
        }
    }
    return -1;
}

void dig(int i, int p, long long int s){
    if(p >= 0){
        length[i] = s;
    }else{
        length[i] = 0;
    }

    for(auto x : to[i]){
        if(x.first != p){
            dig(x.first, i, s+x.second);
        }
    }
}

