void dijkstra(const vector<vector<pair<ll, ll>>>&edge, vector<ll>&cost, ll start = 0)
{
	fill(ALL(cost), INFLL); cost[start] = 0;
	priority_queue<pair<ll, ll>, vector<pair<ll, ll>>, greater<pair<ll, ll>>> node_queue; node_queue.push(make_pair(0, start));
	while (!node_queue.empty()) {
		ll tpn_cost = node_queue.top().first, tpn_index = node_queue.top().second; node_queue.pop();
		for (auto i : edge[tpn_index]) {
			ll dst_index = i.first, dst_cost = i.second;
			if (tpn_cost + dst_cost < cost[dst_index]) {
				cost[dst_index] = tpn_cost + dst_cost;
				node_queue.push(make_pair(cost[dst_index], dst_index));
			}
		}
	}
	return;
}
