template <typename Edge, typename T>
void Dijkstra(const vector<vector<Edge>> &edge, int s, vector<T> &d, T inf) {
    using P = pair<T, int>;
    priority_queue<P, vector<P>, greater<P>> q;
    for(int i = 0; i < edge.size(); i++) {
        d.push_back(inf);
    }
    d[s] = 0;
    q.push({0, s});
    while (q.size()) {
        T dist;
        int v;
        tie(dist, v) = q.top();
        q.pop();
        if (d[v] < dist) continue;
        for (auto &&e : edge[v]) {
            if (0 > d[e.to] || d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                q.push({d[e.to], e.to});
            }
        }
    }
}
