using namespace std;

long d[100000][100000];


void init(int V){
	rep(i, V){
		rep(j, V){
				if(i == j) d[i][j] = 0;
				else d[i][j] = 1000000;
		}
	}
}

void make(int E){
	rep(i, E){
		long u , v ,c;
		cin >> u >> v >> c;
		u--; v--;
		d[u][v] = c; d[v][u] = c;
	}
}
void wf(int V){
	rep(k, V){
		rep(i, V){
			rep(j, V){
				d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
			}
		}
	}
}



int main(void){
	long n;
	cin >> n;
	init(n);
	make(n - 1);
	wf(n);
	long q, k;
	cin >> q >> k;
	for(long i = 0;i < q;i++){
		long s, e;
		long total;
		cin >> s >> e;
		total = d[s-1][k-1] + d[k-1][e-1];
		cout << total << endl;
	}
	return 0;
}

