void dfs(int cur, long long cost, std::vector<bool> &isVisited, std::vector<long long> &costList, const std::vector<std::vector<tree>> tList){
	costList[cur]= cost;
	isVisited[cur]= true;

	for(int i=0; i< tList[cur].size(); i++){
		tree next= tList[cur][i];

		if(!isVisited[next.dst])
			dfs(next.dst, cost+ next.cost, isVisited, costList, tList);
	}

}

