using namespace std;
using ll = long long;
using pii = pair<ll,ll>;

const int MAX = 100010;
const int WHITE = 1;
const int BLACK = 2;
const int GRAY = 3;
const ll INFTY = 1e11;

vector<pii> list[MAX];
ll dist[MAX];
int color[MAX];
int N;

void dijkstra(int K){
    priority_queue<pii, vector<pii>, greater<pii> > Q;
    for(int i=0;i<N;i++){
        dist[i] = INFTY;
        color[i] = WHITE;
    }

    dist[K] = 0;
    Q.push(make_pair(dist[K],K));
    color[K] = GRAY;

    while(!Q.empty()){
        auto f = Q.top(); Q.pop();
        ll u = f.second;
        ll cost_u = f.first;
        color[u] = BLACK;
        if(dist[u] < cost_u) continue;

        for(int j=0;j<list[u].size();j++){
            int v = list[u][j].first;
            if(color[v] == BLACK) continue;
            if(dist[v] > dist[u] + list[u][j].second){
                dist[v] = dist[u] + list[u][j].second;
                Q.push(make_pair(dist[v],v));
                color[v] = GRAY;
            }
        }
    }
}

int main(){
    ll K,Q;
    cin >> N;
    for(int i=0;i<N-1;i++){
        ll a,b,c;
        cin >> a >> b >> c;
        a--;b--;
        list[a].push_back(make_pair(b,c));
        list[b].push_back(make_pair(a,c));
    }
    cin >> Q >> K;
    K--;
    dijkstra(K);
    for(int i=0;i<Q;i++){
        int x,y;
        cin >> x >> y;
        x--; y--;
        cout << dist[x] + dist[y] << endl;
    }
    return 0;
}

