using Edge = pair<int,ll>;
using Graph = vector<vector<Edge>>;

void rec(const Graph &G, int v, int p, ll sum, vector<ll> &dist){
  //現在地にコストを格納
  dist[v] = sum;
  for(auto e: G[v]){
    if(e.first == p) continue;//来た場所に戻らないようにする。
    //G=グラフ,e.first = 行き先, v=元々いた所(次のp), sum+e.second=コスト, dist=コストを格納する配列 
    rec(G, e.first, v, sum+e.second, dist);
  }
}

int main(){
  int N; cin >> N;
  Graph G(N);
  rep(i,N-1){
    int a,b; ll c; cin >> a >> b >> c;
    a--;b--;
    G[a].push_back({b,c});
    G[b].push_back({a,c});
  }
  int Q, K; cin >> Q >> K; K--;
  vector<ll> dist(N,0);
  //Kは行き先、-1は元々いた場所、0はコスト
  rec(G,K,-1,0,dist);

  rep(q,Q){
    int x,y; cin >> x >> y; x--; y--;
    cout << dist[x]+dist[y] << endl;
  }

  return 0;
}

