#define mx 100005
ll dist[mx];
vector<int> adj[mx];
vector<int> cost[mx];
struct str
{
    int node;
    ll c;
    str(int a, ll b)
    {
        node = a;
        c = b;
    }
    bool operator<(const str &ob)const
    {
        return ob.c>c;
    }
};
priority_queue<str> pq;
void dij(int s)
{
    dist[s] = 0;
    pq.push(str(s,0));
    while(!pq.empty()){
        str ob = pq.top();
        pq.pop();
        for(int i=0; i<(int)adj[ob.node].size(); i++){
            int x = adj[ob.node][i];
            ll nd=0;
            nd = nd + ob.c + cost[ob.node][i];
            if(nd<dist[x]){
                dist[x] = nd;
                pq.push(str(x, nd));
            }
        }
    }
}
int main()
{
    memset(dist, 63, sizeof dist);
    int n,a,b,c,q,k;
    scanf("%d",&n);
