        scanf("%d%d%d",&a,&b,&c);
        adj[a].pb(b);
        cost[a].pb(c);
        adj[b].pb(a);
        cost[b].pb(c);
    }
    scanf("%d%d",&q,&k);
    dij(k);
    while(q--){
