using namespace std;
typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
const ll INF = 1ll<<50;
const int maxN = 100010;
const int maxK = 17;
const int MOD = 1000000007;

vector<pii> w[maxN];     //原来的图 
int deep[maxN];
ll dis[maxN];        //每个点到 根节点的值 
int pre[maxN][maxK];
void build(int x,int p)           //新树 
{
	for(int i=0;i<w[x].size();i++)
	{
		int y = w[x][i].first;
		int len = w[x][i].second;
		if(y == p) continue;
		deep[y] = deep[x] + 1;              //记录层次 
		dis[y] = dis[x] + len;
		pre[y][0] = x;
		build(y,x);
	}
}
int getLCA(int x,int y)        //新树 
{
	if(deep[x] < deep[y]) swap(x,y);
	for(int i=maxK-1;i>=0;i--)
	{
		if(deep[x] - deep[y] >= 1<<i)
		{
			x = pre[x][i];
		}
	}
	if(x == y)
		return x;
	for(int i=maxK-1;i>=0;i--)
	{
		if(pre[x][i] != pre[y][i])
		{
			x = pre[x][i];
			y = pre[y][i];
		}	
	}
	return pre[x][0];	
}
int main()
{
	int n;
	scanf("%d",&n);
	for(int i=1;i<n;i++)
	{
		int a,b,c;
		scanf("%d%d%d",&a,&b,&c);
		w[a].push_back(pii(b,c));
		w[b].push_back(pii(a,c));
	}
	build(1,0);
	deep[1] = 1;
	for(int k=1;k<=maxK-1;k++)
	{
		for(int i=1;i<=n;i++)
		{
			pre[i][k] = pre[pre[i][k-1]][k-1];
		}
	}
	int Q,K;
	scanf("%d%d",&Q,&K);
	for(int i=1;i<=Q;i++)
	{
		int x,y;
		scanf("%d%d",&x,&y);
		int u = getLCA(x,K);
		ll len1 = dis[x]+dis[K] - 2*dis[u];
		int v = getLCA(K,y);
		ll len2 = dis[K] + dis[y] - 2*dis[v];
		ll ans = len1 + len2;
		printf("%lld\n",ans);	
	}
	return 0;
}

