    {
        this->to = to;
        this->cost = cost;
    }
};

typedef pair<int, int> P;

vll dijkstra(int s, vector<vector<Edge>> &G)
{
    vll d(G.size(), INF);

    priority_queue<P, vector<P>, greater<P>> q;

    d[s] = 0;
    q.emplace(0, s);

    while(!q.empty())
    {
        auto p = q.top(); q.pop();
        int v = p.second;
        if (d[v] < p.first) continue;

        for (auto e : G[v])
        {
            if (d[e.to] > d[v] + e.cost)
            {
                d[e.to] = d[v] + e.cost;
                q.emplace(d[e.to], e.to);
            }
        }
    }

    return d;
}


