	int head=0,tail=1;
	for (int i=1;i<=n;i++)
	  d[i]=inf;
	memset(f,0,sizeof(f));
	h[1]=st;
	d[st]=0;
	f[st]=1;
	while (head<tail)
	{
	  head++;
	  int fa=h[head];
	  int p=now[fa];
	  while (p>0)
	  {
	  	int s=son[p];
	  	if (d[s]>d[fa]+v[p])
	  	{
		  d[s]=d[fa]+v[p];
		  if (!f[s])
		  {
		  	tail++;
		  	f[s]=1;
			h[tail]=s;
		  }
		}
		p=pre[p];
	  }
	  f[fa]=0;
	}
}



