void dijkstra(int s, int n){
    for(int i =0;i<=n;++i){d[i]=INF;p[i]=-1;}
    priority_queue <dist_node, vector<dist_node>, greater<dist_node> > q;
    d[s]=0;
    q.push(dist_node(0,s));
