template<class T>
vector<T> Dijkstra(W_Graph<T> &G, int s) {
    const auto inf = numeric_limits<T>::max();
    vector<T> min_dist(G.size(), inf);

    using P = pair<T, int>; //pair<dist_from_starting_point, index_of_node>
    priority_queue<P, vector<P>, greater<P>> que;
    min_dist[s] = 0;
    que.emplace(min_dist[s], s);  //starting_point 

    while(!que.empty()) {
        T dist;
        int index;
        tie(dist, index) = que.top();
        que.pop();
        if(dist > min_dist[index]) continue;

        for(auto &edge : G[index]) {
            auto new_dist = dist + edge.cost;
            //compare the length of each route and chenge min_dist[edge.to]
            if(new_dist >= min_dist[edge.to]) continue;
            min_dist[edge.to] = new_dist;
            que.emplace(min_dist[edge.to], edge.to);
        }
    }
    return min_dist;
}

