void dfs(int p,int bef,ll len,int d){
  dist[p] = len;
  for(pii P : g[p]){
    int to = P.first;
    ll nlen = len + P.second;
    if(to==bef)continue;
    dfs(to,p,nlen,d+1);
  }
  // prepare for doubling LCA
  dep[p] = d;
  par[p][0] = bef;
  REP(i,DEG){
    if(par[p][i]==-1){
      par[p][i+1] = -1;
    }else{
      int nxt = par[p][i];
      par[p][i+1] = par[nxt][i];
    }
  }
}

int lca(int a,int b){
  int da = dep[a];
  int db = dep[b];
  if(da>db){
    swap(a,b);
    swap(da,db);
  }
  REP(i,DEG+1){
    if(((db-da)>>i)&1){
      b = par[b][i];
      db = dep[b];
    }
  }
  if(a==b)return a;
  FORR(i,0,DEG+1){
    if(par[a][i] != par[b][i]){
      a = par[a][i];
      b = par[b][i];
    }
  }
  return par[a][0];
}

