using namespace std;
typedef long long int ll;
#define MAXN	100000
struct edge
{
  int v,n;
  ll w;
  edge():v(0),w(0),n(0){}
  edge(int vv, ll ww, int nn):v(vv),w(ww),n(nn){}
};
edge E[MAXN<<1];
int nE;
int front[MAXN+1];
void add_edge(int u, int v, ll w)
{
  int ne = ++nE;
  E[ne] = edge(v,w,u[front]);
  u[front] = ne;
}
int solid[MAXN+1];
ll d[MAXN+1];
void dijstra(int s)
{
  set< pair<ll,int> > q;
  memset(solid,0,sizeof(solid));
  memset(d, -1, sizeof(d));
  d[s] = 0; solid[s] = 1;
  q.insert(make_pair(0ll,s));
  while(!q.empty())
  {
    auto p = q.begin();
    int u = p->second;
    solid[u] = 1;
    q.erase(p);
    for(int e=u[front];e;e = E[e].n)
    {
      int v = E[e].v; ll w = E[e].w;
      if((!solid[v]) && ((-1 == d[v]) || (d[u]+w < d[v])))
      {
        q.erase(make_pair(d[v],v));
        d[v] = d[u]+w;
        q.insert(make_pair(d[v],v));
      }
    }
  }
}
int main(void)
{
  int N = 0;
  int a = 0, b = 0;
  ll c = 0;
  scanf("%d", &N);
  while(--N)
  {
    scanf("%d %d %lld", &a, &b, &c);
    add_edge(a,b,c);
    add_edge(b,a,c);
  }
  int Q = 0, K = 0;
  int x = 0, y = 0;
  scanf("%d %d", &Q, &K);
  dijstra(K);
  while(Q--)
  {
    scanf("%d %d", &x, &y);
    printf("%lld\n", d[x]+d[y]);
  }
  return 0;
}

