        graph[b].push_back({a,c});
    }
    cin >> Q >> K;
    K--;
    dijkstra(K);
    ll ans[Q];
    REP(i,Q){
        cin >> x >> y;
        x--; y--;
        ans[i] = dist[x] + dist[y];
    }
    REP(i,Q){
        cout << ans[i] << endl;
    }
    return 0;
}

