typedef long long ll;
typedef pair<ll, ll> P;
const ll INF = 10000000000000;
const ll LINF = 10000000000000000;
const int MOD = 1000000007;
const int dx[9] = { 0, 1,  0, -1, 1,  1, -1, -1, 0};
const int dy[9] = { 1, 0, -1,  0, 1, -1, -1,  1, 0};
//--------------------------------------//
int N;
vector<P> G[100000];
int Q, K;

ll d[100000];
void solve(){
	rep(i, N)
		d[i] = INF;
	K--;
	d[K] = 0;
	priority_queue<P, vector<P>, greater<P> > q;
	q.push(P(0, K));
	while(!q.empty()){
		P p = q.top(); q.pop();
		int n = p.second;
		int cost = p.first;
		if(d[n] < cost) continue;
		rep(i, G[n].size()){
			int to = G[n][i].first;
			int co = G[n][i].second;
			if(d[to] > d[n] + co){
				d[to] = d[n] + co;
				q.push(P(d[to], to));
			}
		}
	}
	rep(i, Q){
		int x, y;
		cin >> x >> y;
		x--; y--; 
		cout << d[x] + d[y] << endl;
	}
}

