	cin >> N;
	rep(i, N - 1){
		int a, b, c;
		cin >> a >> b >> c;
		a--; b--;
		G[a].pub(P(b, c));
		G[b].pub(P(a, c));
	}
	cin >> Q >> K;
		solve();
	return 0;
}

