int main(int argc, char* argv[]) {
    if (argc >= 1) freopen(argv[1], "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);

    int N;
    cin >> N;

    vector<vector<pair<int, ll>>> adj(N);
    vector<ll> dist(N);

    FOR(i,0,N-1) {
        int a, b, c;
        cin >> a >> b >> c;
        adj[a-1].emplace_back(b-1, c);
        adj[b-1].emplace_back(a-1,c);
    }

    int Q, K;
    cin >> Q >> K;
    K--;

    function<void(int,int,ll)> dfs = [&](int u, int p, ll w) {
        dist[u] = w;
        for (auto v : adj[u]) if (v.X != p) {
                dfs(v.first, u, w + v.second);
        }
    };
    dfs(K, -1, 0);

    while (Q--) {
        int x, y;
        cin >> x >> y;
        cout << dist[x-1] + dist[y-1] << '\n';
    }

}

