const  int maxx=1e5+100;
const int INF=99999999;
const int MOD=1e9+7;
typedef long long ll;
int n;
struct node
{
    int r,nextt;
    ll dis;
}s[maxx*2];
ll d[maxx];
int h[maxx];
int cnt;
void add(int a,int b,ll c)
{
    s[cnt].r=b;
    s[cnt].dis=c;
    s[cnt].nextt=h[a];
    h[a]=cnt;
    cnt++;
}
void dfs(int k,int dd)
{
    for(int i=h[k]; i!=-1; i=s[i].nextt){
        int v=s[i].r;
        //if(v==dd)  continue;
        d[v]=d[k]+s[i].dis;
        dfs(v,k);
    }
}
int main()
{
    scanf("%d",&n);
    int a,b;
    ll c;
    cnt=0;
    memset(h,-1,sizeof(h));
    memset(d,0,sizeof(d));
    for(int i=0; i<n-1; i++){
        scanf("%d%d%lld",&a,&b,&c);
        add(a,b,c);
        add(b,a,c);
    }
    int m,k;
    scanf("%d%d",&m,&k);
    dfs(k,-1);
    while(m--){
        scanf("%d%d",&a,&b);
        cout<<d[a]+d[b]<<endl;
    }
    return 0;
}

