    for (int i = 1; i <= Q; i++){
        queue<graph> q;
        vector<int64_t> KY(N + 1, 0);
        q.push({x.at(i), 0});
        while (!q.empty()){
            int st = q.front().ob;
            q.pop();
            if (st == K){
                ans_1.at(i) = KY.at(st);
                break;
            }
            else{
                for(int i = 0; i < d.at(st).size(); i++){
                    int st_1 = d.at(st).at(i).ob;
                    int ky_1 = d.at(st).at(i).di;
                    q.push(d.at(st).at(i));
                    KY.at(st_1) = KY.at(st) + ky_1;
                }
            }
        }
    }
    for (int i = 1; i <= Q; i++){
        queue<graph> q;
        vector<int64_t> KY(N + 1, 0);
        q.push({K, 0});
        while (!q.empty()){
            int st = q.front().ob;
