                    int ky_1 = d.at(st).at(i).di;
                    q.push(d.at(st).at(i));
                    KY.at(st_1) = KY.at(st) + ky_1;
                }
            }
        }
    }
    for (int i = 1; i <= Q; i++){
        cout << ans_1.at(i) + ans_2.at(i) << endl;
    }    
}

