inline void dfs(int x)
{
	route[x].push_back(x);
	for(int i=0;i<G[x].size();i++)
	{
		route[G[x][i].first]=route[x];
		layer[G[x][i].first]=layer[x]+G[x][i].second;
		dfs(G[x][i].first);
	}
	return ;
}
inline long long extra(int pa,int pb)
{
	int i=0,MIN=min(route[pa].size(),route[pb].size());
	for(;i<MIN&&route[pa][i]==route[pb][i];i++);
	i--;
	int xp=route[pa][i];
	return min(abs(layer[xp]-layer[pa]),abs(layer[xp]-layer[pb]))*2;
}
