void dijkstra(int s) {
    std::priority_queue< P, std::vector<P>, std::greater<P> > que;
    std::fill(d, d+N, INF);
    d[s] = 0;
    que.push( P(0, s) );
    while ( !que.empty() ) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        for (int i=0; i<G[v].size(); ++i) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push( P(d[e.to], e.to) );
            }
        }
    }
}

