int up[18][100007];
ll path[100007];
int tin[100007], tout[100007];

int tt = 0;
void dfs(int v, int pred, ll len){
	tin[v] = tt++;
	path[v] = len;
	up[0][v] = pred;
	for (int i = 1; i < 18; i++) up[i][v] = up[i - 1][up[i - 1][v]];
	for (auto to : g[v]) if (to.x != pred) dfs(to.x, v, len + to.y);
	tout[v] = tt++;
}

bool isPred(int a, int b){
	return tin[a] <= tin[b] && tout[b] <= tout[a];
}

int getLca(int a, int b){
	if (isPred(a, b)) return a;
	if (isPred(b, a)) return b;
	for (int i = 17; i >= 0; i--) if (!isPred(up[i][a], b)) a = up[i][a];
	return up[0][a]; 
}

ll getPathLen(int a, int b){
	int c = getLca(a, b);
	return path[a] + path[b] - 2 * path[c];
}

