long long bfs(Graph& G, int s, int x, int y){
    vector<long long> d(G.size(), LONG_MAX);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    vector<bool> visited(G.size(), false);

    while(!q.empty()){
        const int current_v = q.front(); q.pop();
        visited[current_v] = true;

        for(auto& e : G[current_v]){
            if(visited[e.to]) continue;
            q.push(e.to);
            d[e.to] = d[current_v] + e.cost;
        }

        if(visited[x] && visited[y])
            break;
    }

    return d[x] + d[y];
}


