    cin >> N;
    array<IA, L> M;
    array<int, L> D;
    array<int, L> ksign;
    for (int i = 0; i < L; ++i) { ksign[i] = 1;}
    for (int i = 0; i < N-1; ++i) {
        cin >> a >> b >> c;
