    }
    cin >> Q >> K;
    int64_t sumk = 0;
    unordered_map<int, int64_t> kmemo;
    while (M[K].a > 0) {
        a = M[K].i;
        K = M[K].a;
        ksign[a] = -1;
        kmemo[a] = sumk;
        sumk += D[a];
    }
    unordered_map<int, int64_t> memo;
    for (int i = N; i < N+Q; ++i) {
        int64_t x, y, tx, ty, xsum, ysum, ti, ta, tti, p;
