            xsum = 0;
            t = M[tx];
            while (t.a > 0) {
                if (ksign[t.i] < 0) {
                    p = t.i;
                    break;
                }
                xsum += D[t.i];
                t = M[t.a];
            }
            if (kmemo.find(p) != kmemo.end()) {
                xsum += kmemo[p];
            } else {
                xsum += sumk;
            }
            memo[x] = xsum;
        }
