                ysum += D[t.i];
                t = M[t.a];
            }
            if (kmemo.find(p) != kmemo.end()) {
                ysum += kmemo[p];
            } else {
                ysum += sumk;
            }
            memo[y] = ysum;
        }
        cout << memo[x] + memo[y] << endl;
    }
