using namespace std;
typedef long long LL;

const int MaxN = 1e5;
int n, m;
LL all;
int pre[2*MaxN + 5], last[2*MaxN + 5], other[2*MaxN + 5];
LL cost[2*MaxN + 5];
LL	dis[MaxN + 5];
int seq[MaxN + 5];
bool Inque[MaxN + 5];


void Build(int x, int y, LL w)
{
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
	cost[all] = w;
}

void Bfs(int s)
{
	LL head = 1, tail = 1, now, ed, dr;
	seq[tail] = s;
	for(int i = 1; i <= n; i++)
	{
		if(i == s) dis[i] = 0;
		else dis[i] = 1 << 30;
	}
	Inque[s] = 1;
	while(head <= tail)
	{
		now = seq[head];
		ed = last[now];
		while(ed != -1)
		{
			dr = other[ed];
			if(dis[now] + cost[ed] < dis[dr])
			{
				dis[dr] = dis[now] + cost[ed];
				if(!Inque[dr])
				{
					Inque[dr] = 1;
					seq[++tail] = dr;
				}
			}
			ed = pre[ed];
		}
		Inque[now] = 0;
		head++;
	}
}

int main()
{
	all = -1;
	memset(last, -1, sizeof(last));
	scanf("%d", &n);
	for(int i = 1; i < n; i++)
	{
		int a,b;
		LL w;
		scanf("%d %d %lld", &a, &b, &w);
		Build(a, b, w); Build(b, a, w);
	}
	int q,k,u,v;
	scanf("%d %d",&q,&k);
	memset(seq, 0, sizeof(seq));
	memset(Inque, 0, sizeof(Inque));
	Bfs(k);
	while(q--){
			scanf("%d %d",&u,&v);
		printf("%lld\n", dis[u]+dis[v]);
	}
	return 0;
}

#include<bits/stdc++.h>
#define int long long
using namespace std;
const int INF = 1e10;

struct edge{
    int to,cost;
};
typedef pair<int,int> P; //firstは最短距離、secondは頂点の番号

int V; //頂点数
vector<edge> G[100010];
int d[100010]; //頂点sからの最短距離

void dijkstra(int s) {
    //greater<P>を指定することでfirstが小さい順に取り出せる
    priority_queue<P,vector<P>,greater<P>> que;
    fill(d,d + V,INF);
    d[s] = 0;
    que.push(P(0,s));

    while(!que.empty()) {
        P p = que.top();
        que.pop();
        int v = p.second;
        if(d[v] < p.first) {
            continue;
        }
        for(int i = 0;i < G[v].size();i++) {
            edge e = G[v][i];
            if(d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to],e.to));
            }
        }
    }
}

signed main() {
    cin >> V;
    for(int i = 0;i < V - 1;i++) {
        int A,B,C;
        cin >> A >> B >> C;
        G[A - 1].push_back(edge{B - 1,C});
      	G[B - 1].push_back(edge{A - 1,C});
    }
    int Q,K;
    cin >> Q >> K;
    dijkstra(K - 1);
    for(int i = 0;i < Q;i++) {
        int A,B;
        cin >> A >> B;
        cout << d[A - 1] + d[B - 1] << endl;
    }
}

