void dfs(int N,int s,vector<int> G[],function<void(int,int,int)> F){
	stack<pair<int,int>> sp;
	sp.push({s,-1});
	while(!sp.empty()){
		int v = sp.top().first;
		int f = sp.top().second;
		sp.pop();
		for(int i=0;i<G[v].size();i++){
			int t = G[v][i];
			if(t != f){
