using namespace std;


using pi=pair<int,int>;
const long long INF=99999999999999;
struct edge{
	int to,cost;
};

vector<int> djikstra(vector<vector<edge>> &G,int start){
	vector<int> dist(G.size(), INF);
	priority_queue<pi,vector<pi>,greater<pi>> que;
	dist[start]=0;
	// pair(その時点での最短経路,頂点の番号)
	que.push(make_pair(dist[start],start));
	while(!que.empty()){
		int cost=que.top().first;
		int idx=que.top().second;
		que.pop();

		if(dist[idx]<cost)continue;
		for(edge e:G[idx]){
			if(dist[e.to]<=cost+e.cost) continue;
			dist[e.to]=cost+e.cost;
			que.push(make_pair(dist[e.to],e.to));
		}
	}
	return dist;
}

