void dfs(int v, int p, int d, int w)
{
    dep[v] = d, depw[v] = depw[p]+w, par[v][0] = p;
    for(int i = 0 ; i < T[v].size() ; i++ )
        if( T[v][i] != p ) dfs(T[v][i], v, d+1, W[v][i]);
}
INT lca(int v, int w)
{
    if( dep[v] < dep[w] ) swap(v, w);
    int diff = dep[v] - dep[w];
    for(int i = 0 ; diff ; i++, diff>>=1 ) if(diff&1) v = par[v][i];
    if( v == w ) return v;
    for(int i = 20 ; i >= 0 ; i-- )
        if( par[v][i] and par[w][i] and par[v][i] != par[w][i] )
            v = par[v][i], w = par[w][i];
    return par[v][0];
}
