#include<bits/stdc++.h>
using namespace std;
#define MAX 100005
typedef long long ll;

struct edge{
  ll to,cost;
  edge(ll to,ll cost):to(to),cost(cost) {}
};

ll n;
vector< edge > G[MAX];
ll size[MAX];
ll par[MAX];
ll dep[MAX];
ll depth[MAX];
ll dist[MAX];
ll parent[MAX];

void idfs(int pos,int prev=-1){
  int m=-1;
  parent[pos]=prev;

  for(edge e:G[pos]){
    if(e.to==prev)continue;

    depth[e.to]=depth[pos]+1;
    dist[e.to]=dist[pos]+e.cost;

    idfs(e.to,pos);
    size[pos]+=size[e.to];
    if(m==-1||size[m]<size[e.to])m=e.to;
  }

  if(m!=-1)par[m]=pos;
}

int calc(int x){
  if(par[x]==x)return x;
  return par[x]=calc(par[x]);
}

void init(){
  for(int i=0;i<MAX;i++){
    parent[i]=-1;
    depth[i]=0;
    dist[i]=0;
    size[i]=1;
    par[i]=i;
    dep[i]=0;
  }

  for(int i=0;i<n-1;i++){
    ll a,b,c;
    cin>>a>>b>>c;
    a--,b--;
    G[a].push_back( edge(b,c) );
    G[b].push_back( edge(a,c) );
  }

  idfs(0,-1);

  for(int i=0;i<n;i++){
    int p=calc(i);
    dep[i]=0;
    while(p){
      p=par[parent[p]];
      dep[i]++;
    }
  }
}

int lca(int a,int b){
  while(par[a]!=par[b]){
    if(depth[ par[a] ]>depth[ par[b] ])swap(a,b);
    b=parent[ par[b] ];
  }
  if(depth[a]<depth[b])return a;
  return b;
}

ll Cal(int a,int b){
  int c=lca(a,b);
  return dist[a]+dist[b]-dist[c]*2LL;
}

int main(){
  cin>>n;
  init();
  ll q,K;
  cin>>q>>K;
  K--;
  while(q--){
    ll a,b;
    cin>>a>>b;
    a--,b--;
    cout<< Cal(a,K) + Cal(K,b) <<endl;
  }
  return 0;
}

