void dfs(int now, int parent, long long distance, vector<vector<int>> &children, vector<vector<long long>> &c) {
    d.at(now) = distance;
    for(int child : children.at(now)) {
        if(child == parent) continue;
        dfs(child, now, distance+c.at(now).at(child) ,children, c);
    }
}

