class UnionFind {
public:
	vector <ll> par; // 各元の親を表す配列
	vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

	// Constructor
	UnionFind(ll sz_) : par(sz_), siz(sz_, 1) {
		for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}
	void init(ll sz_) {
		par.resize(sz_);
		siz.resize(sz_, 1);
		for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
	}

	// Member Function
	// Find
	ll root(ll x) { // 根の検索
		while (par[x] != x) {
			x = par[x] = par[par[x]]; // x の親の親を x の親とする
		}
		return x;
	}

	// Union(Unite, Merge)
	bool merge(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		// merge technique（データ構造をマージするテク．小を大にくっつける）
		if (siz[x] < siz[y]) swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
		return true;
	}

	bool issame(ll x, ll y) { // 連結判定
		return root(x) == root(y);
	}

	ll size(ll x) { // 素集合のサイズ
		return siz[root(x)];
	}
};
struct combination {
	vector<mint> fact, ifact;
	combination(int n) :fact(n + 1), ifact(n + 1) {
		//assert(n < mod);
		fact[0] = 1;
		for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;
		ifact[n] = fact[n].inv();
		for (int i = n; i >= 1; --i) ifact[i - 1] = ifact[i] * i;
	}
	mint operator()(int n, int k) {
		if (k < 0 || k > n) return 0;
		return fact[n] * ifact[k] * ifact[n - k];
	}
};
int nowdist[100010];
map<P, int>mp;
void now(const Graph2 &G, int v, int p, int d = 0) {
	nowdist[v] = d;
	for (auto nv : G[v]) {
		if (nv == p)continue;
		now(G, nv, v, d + mp[{v, nv}]);
	}
}
struct LCA {
	vector<VE> parent;
	VE dist;
	LCA(const Graph &G, int root = 0) { init(G, root); }
	void init(const Graph &G, int root = 0) {
		int V = G.size();
		int K = 1;
		while ((1 << K) < V) K++;
		parent.assign(K, vector<int>(V, -1));
		dist.assign(V + 1, -1);
		dfs(G, root, -1, 0);
		for (int k = 0; k + 1 < K; k++) {
			for (int v = 0; v < V; v++) {
				if (parent[k][v] < 0) {
					parent[k + 1][v] = -1;
				}
				else {
					parent[k + 1][v] = parent[k][parent[k][v]];
				}
			}
		}
	}
	void dfs(const Graph &G, int v, int p, int d) {
		parent[0][v] = p;
		dist[v] = d;
		for (auto e : G[v]) {
			//cout << v << endl;
			if (e.to != p) dfs(G, e.to, v, d + 1);
		}
	}

	int query(int u, int v) {
		if (dist[u] < dist[v]) swap(u, v);
		int K = parent.size();
		for (int k = 0; k < K; k++) {
			if ((dist[u] - dist[v]) >> k & 1) {
				u = parent[k][u];
			}
		}
		if (u == v) return u;
		for (int k = K - 1; k >= 0; k--) {
			if (parent[k][u] != parent[k][v]) {
				u = parent[k][u];
				v = parent[k][v];
			}
		}
		return parent[0][u];
	}
	int get_dist(int u, int v) {
		return nowdist[u] + nowdist[v] - 2 * nowdist[query(u, v)];
	}
};
