int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};

class LCA {
private:
  const int n = 0;
  const int log2_n = 0;
  VVI par;
  vector<vector<PII>> g;
  VI depth, d;

  // parとdを構築する
  void dfs(int v, int p, int dist, int n_depth) {
    par[0][v] = p; d[v] = dist; depth[v] = n_depth;
    for (auto e : g[v]) {
      if (e.first != p) dfs(e.first, v, dist + e.second, n_depth+1);
    }
  }

public:
  LCA(int n_=1e5) :
    n(n_), log2_n(log2(n)+1), par(log2_n, VI(n)), g(n, vector<PII>()), depth(n), d(n) {}
  // u-vに重みcostの辺を張る
  void add_edge(int u, int v, int cost) { g[u].PB({v, cost}); g[v].PB({u, cost}); }
  // rootを根としてparとdを構築
  void build(int root = 0) {
    dfs(root, -1, 0, 0);
    REP(k, log2_n-1) {
      REP(v, n) {
        if(par[k][v] < 0) par[k+1][v] = -1;
        else par[k+1][v] = par[k][par[k][v]];
      }
    }
  }
  // uとvのlcaを返す
  int get(int u, int v) {
    if (depth[u] > depth[v]) std::swap(u, v);
    for (int k = 0; k < log2_n; k++) {
      if ((depth[v] - depth[u]) >> k & 1) {
        v = par[k][v];
      }
    }
    if (u == v) return u;
    for (int k = log2_n - 1; k >= 0; k--) {
      if (par[k][u] != par[k][v]) {
        u = par[k][u];
        v = par[k][v];
      }
    }
    return par[0][u];
  }
  // uとvの距離を返す
  int length(int u, int v) {
    int lca = get(u, v);
    return d[u] + d[v] - 2*lca;
  }
  void debug() {
    cout << depth << endl << d << endl;
  }
};

