int dfs(int cur,int prev,int lev)
{
	level[cur]=lev;
	par[cur][0]=prev;
	int i;
	rep(i,adj[cur].size())
	{
		if(adj[cur][i]!=prev)
		{
			d[adj[cur][i]]=d[cur]+wet[cur][i];
			dfs(adj[cur][i],cur,lev+1);
		}
	}
	return 0;
