int lca(int p,int q){
	int i;
	if(level[p]<level[q]){
		//cout<<"Hi'<"<<endl;
		swap(p,q);
	}
	fd(i,LOG-1,0){
		if(level[p]-(1<<i)>=level[q]){
			//cout<<p<<" "<<i<<endl;
			p=par[p][i];
		}
	}
	//cout<<p<<endl;
	if(p==q){
		return p;
	}
	fd(i,LOG-1,0){
		if(par[p][i]!=par[q][i]){
			p=par[p][i];
			q=par[q][i];
		}
	}
	return par[p][0];

}
