void adde(int u,int v,int w) {e[++cnt].to=v,e[cnt].v=w,e[cnt].nex=last[u],last[u]=cnt;}
void dfs(int x,int fath)
{
	fa[x][0]=fath,deep[x]=deep[fath]+1;
	for(int k=last[x];k;k=e[k].nex)
		if(e[k].to^fath) Sum[e[k].to][0]=e[k].v,dfs(e[k].to,x);
}
ll solve(int x,int y)
{
	ll res=0;
	if(deep[x]<deep[y]) swap(x,y);
	for(int j=17;~j;j--) if(deep[x]+(1<<j)<=deep[y]) res+=Sum[x][j],x=fa[x][j];
	if(x^y)
	{
		for(int j=17;~j;j--) if(fa[x][j]^fa[y][j])
			res+=Sum[x][j]+Sum[y][j],x=fa[x][j],y=fa[y][j];
		res+=Sum[x][0]+Sum[y][0],x=fa[x][0],y=fa[y][0];
	}
	return res;
}
