            }
        }else if(flag && x[i] == before){
            seq++;
            if(i == x.size()-1){
                s.first.push_back(seq);
                s.second.push_back(x[i]);
            }
        }else if(flag && x[i] != before){
            s.first.push_back(seq);
            s.second.push_back(x[(i-1)*(i!=0)]);
            seq=1;
            flag = 0; 
            //debug(i)
            if(i == x.size()-1){
                s.first.push_back(seq);
                s.second.push_back(x[i]);
            }
        }else{
