typedef long long ll;
typedef struct {
	ll cost;
	int to;
} Edge;

ll n;
ll q, k;
ll min_cost[100005];
int visited[100005];
Edge *graph[100005];
int edge_num[100005];
int capacity[100005];

int st[100005];
int sp;

void dfs(ll k);

int main()
{
	scanf("%lld", &n);

	for (ll i = 1; i < n; i++) {
		ll a, b, c;

		scanf("%lld %lld %lld", &a, &b, &c);


		if (capacity[a] == edge_num[a]) {
			graph[a] = realloc(graph[a], sizeof(Edge) * (capacity[a] + 1) * 2);
			capacity[a] = 2 * (capacity[a] + 1) - 1;
		}

		if (capacity[b] == edge_num[b]) {
			graph[b] = realloc(graph[b], sizeof(Edge) * (edge_num[b] + 1) * 2);
			capacity[b] = 2 * (capacity[b] + 1) - 1;
		}

		graph[a][edge_num[a]] = (Edge){.cost = c, .to = b};
		graph[b][edge_num[b]] = (Edge){.cost = c, .to = a};

		edge_num[a]++;
		edge_num[b]++;
	}

	scanf("%lld %lld", &q, &k);

	dfs(k);

	for (ll i = 0; i < q; i++) {
		ll x, y;

		scanf("%lld %lld", &x, &y);

		printf("%lld\n", min_cost[x] + min_cost[y]);
	}


	return 0;
}

void dfs(ll k)
{
	visited[k] = 1;
	st[0] = k;
	sp = 0;

	while(sp >= 0) {
		ll pos = st[sp]; sp--;

		for (ll i = 0; i < edge_num[pos]; i++) {
			ll npos = graph[pos][i].to;
			ll ncos = graph[pos][i].cost + min_cost[pos];

			if (visited[npos] == 0) {
				visited[npos] = 1;
				min_cost[npos] = ncos;

				sp++;
				st[sp] = npos;
			}
		}
	}

	return;
}

