typedef struct{
	int front;
	int rear;
	int size;
	int *data;
} Queue;
void init_queue(Queue* q,int s){
	q->data=calloc(s,sizeof(int));
	q->front=q->rear=0;
	q->size=s;
	return;
}
void end(Queue* q){
	free(q->data);
	return;
}
void push(Queue* q,int a){
	q->data[q->rear]=a;
	q->rear=(q->rear+1)%q->size;
	return;
}
int pop(Queue* q){
	int res=q->data[q->front];
	q->front=(q->front+1)%q->size;
	return res;
}
int isempty(Queue *q){
	return q->front==q->rear;
}
typedef struct LIST{
	int to,cost;
	struct LIST *next;
}Edge;
Edge** init(int v){
	Edge **edge=(Edge**)calloc(v,sizeof(Edge*));
	return edge;
}
void add_edge(Edge **edge,int s,int t,int c){
	Edge *tmp=(Edge*)malloc(sizeof(Edge));
	tmp->to=t,tmp->cost=c;
	tmp->next=edge[s];
	edge[s]=tmp;
	return;
}
void delete_edge(Edge **edge,int v){
	int i;
	Edge *e,*tmp;
	FOR(i,0,v){
		e=edge[i];
		while(e!=NULL){
			tmp=e->next;
			free(e);
			e=tmp;
		}
	}
	return;
}
