int find (int x){
    if (par[x]==x){
        return x;
    } else {
        int p=find(par[x]);
        dis[x]=dis[par[x]]+dis[x];
        p=find(par[x]);
        return p ;
    }
}

void unite (int x, int y, long long d){
    int px=find(x);
    int py=find(y);
    if (x!=y){
        if (px==k){
            par[py]=k;
            dis[py]=dis[x]+d-dis[py];
        } else if (py==k){
            par[px]=k;
            dis[px]=dis[y]+d+dis[px];
        } else {
            par[px]=py;
            dis[px]=dis[y]+d+dis[px];
        }
    }
}


