long long int Change(int x,int K,long long int **C,int N){
	long long int ans=inf;
	long long int new_ans; 
	int i;
	if (C[x-1][K-1]!=inf){
		long long int ans=C[x-1][K-1];
		return ans;
	}
	else {
		for (i=0;i<N;i++){
			new_ans=C[x-1][i]+Change(i,K,C,N);
			if (new_ans<ans){
				ans=new_ans;
			}
			return ans;
		}
	}
}

