    int v=stack[--top];
    int p;
    for(p=start[v];p!=-1;p=next[p]){
      int u=vertex[p];
      if(dp[u]==-1){
	dp[u]=dp[v]+cost[p];
	stack[top++]=u;
      }
    }
  }
  return;
}

