int n,par[100020],a[100020],b[100020],q,k;
long long dis[100020],c[100020];

int find (int x){
    if (par[x]==x){
        return x;
    } else {
        int p=find(par[x]);
        dis[x]=dis[par[x]]+dis[x];
        par[x]=p;
        return par[x];
    }
}

void unite (int x, int y, long long d){
    int px=find(x);
    int py=find(y);
    if (x!=y){
        if (px==k){
            par[py]=k;
            dis[py]=dis[x]+d-dis[y];
        } else if (py==k){
            par[px]=k;
            dis[px]=dis[y]+d+dis[x];
        } else {
            par[px]=py;
            dis[px]=dis[y]+d+dis[x];
        }
    }
}


int main(void){
    scanf("%d",&n);
    for (int i=0; i<n; i++){
        par[i]=i;
    }
    for (int i=0; i<n-1; i++){
        scanf("%d%d%lld",&a[i],&b[i],&c[i]);
        a[i]--;
        b[i]--;
    }
    scanf("%d%d",&q,&k);
    k--;
    for (int i=0; i<n-1; i++){
        unite(a[i],b[i],c[i]);
    }
    for (int i=0; i<q; i++){
        int x,y;
        scanf("%d%d",&x,&y);
        printf("%lld\n",dis[x-1]+dis[y-1]);
    }
	return 0 ;
}

