	for (i=0;i<N;i++){
		C[i]=malloc(N*sizeof(long long int));
		for (j=0;j<N;j++){
			C[i][j]=inf;
		}
	}
	for (i=0;i<N-1;i++){
		scanf("%d %d",&a,&b);
		scanf("%lld",&c);
		C[a-1][b-1]=C[b-1][a-1]=c;
	}
	for (i=0;i<N;i++){
		for (j=0;j<N;j++){
			for (k=0;k<N;k++){
				if (C[i][j]>C[i][k]+C[k][j]){
					C[i][j]=C[i][k]+C[k][j];
				}
			}
		}
	}

	int Q,K;
	int x,y;
	scanf("%d %d",&Q,&K);

	for (i=0;i<Q;i++){
		scanf("%d %d",&x,&y);
		if (C[x-1][K-1]==inf){
			C[x-1][K-1]=C[K-1][x-1]=Change(x,K,C,N);
		}
		if (C[y-1][K-1]==inf){
