int esort(const void *a, const void *b){
  E *x, *y;
  x = (E *)a; y = (E *)b;
  if(x->s < y->s) return -1;
  if(x->s > y->s) return  1;
  if(x->g < y->g) return -1;
  return 1;
}

void MakeGraph(G *g, int n, int m){
  g->vcnt = n; g->ecnt = 2 * m;
  int a, b; ll c;
  rep(i, g->ecnt / 2){
    scanf("%d %d %lld", &a, &b, &c);
    a--; b--;
    g->e[2 * i].s = a;
    g->e[2 * i].g = b;
    g->e[2 * i].d = c;
    g->e[2 * i + 1].s = b;
    g->e[2 * i + 1].g = a;
    g->e[2 * i + 1].d = c;
  }

  qsort(g->e, g->ecnt, sizeof(E), esort);

  int p = 0;
  rep(i, g->vcnt){
    while(p < g->ecnt && g->e[p].s < i) p++;
    g->id[i] = p;
  }
  g->id[g->vcnt] = g->ecnt;
 }




void dfs(G *g, int i, int *visited, ll *distance){
  visited[i] = 1;
  for(int j = g->id[i]; j < g->id[i + 1]; j++){
    int p = g->e[j].g;
    if(visited[p] == 0){
      distance[p] = g->e[j].d + distance[i];
      dfs(g, p, visited, distance);
    }
  }
  return;
}

