void addEdge(int32_t* pEdgeCount, struct edge_t** pEdges, int32_t to, int64_t cost) {
	struct edge_t* asumikana = realloc(*pEdges, sizeof(**pEdges) * (*pEdgeCount + 1));
	if (asumikana == NULL) exit(2);
