//// 優先度付きキュー（ダイクストラ法用）
#define MAX 1000000
typedef struct { ll t; int n; } QUE;
QUE que[MAX]; int qsize;

#define PARENT(i) ((i)>>1)
#define LEFT(i)   ((i)<<1)
#define RIGHT(i)  (((i)<<1)+1)

void min_heapify(int i)
{
	int l, r, min;
	QUE qt;

	l = LEFT(i), r = RIGHT(i);
	if (l < qsize && que[l].t < que[i].t) min = l; else min = i;
	if (r < qsize && que[r].t < que[min].t) min = r;
	if (min != i) {
		qt = que[i]; que[i] = que[min]; que[min] = qt;
		min_heapify(min);
	}
}

void deq()
{
	que[0] = que[--qsize];
	min_heapify(0);
}

void enq(int n, ll t)
{
	int i, min;
	QUE qt;

	i = qsize++;
	que[i].t = t, que[i].n = n;
	while (i > 0 && que[min = PARENT(i)].t > que[i].t) {
		qt = que[i]; que[i] = que[min]; que[min] = qt;
		i = min;
	}
}

//// 本問題関連
#define MAXV 100005
int N; // グラフの頂点数
int M; // 枝数
int hi[MAXV], *to[MAXV], *cost[MAXV]; // 頂点から本数、次のノード、次のノードまでのコスト
ll dis[MAXV];

void dijkstra(int start) {
	int i, u, v;
	ll t;

	memset(dis, 0x55, sizeof(dis));
	enq(start, 0);
	while (qsize) {
		u = que[0].n, t = que[0].t, deq();
		if (dis[u] <= t) continue;
		dis[u] = t;
		for (i = 0; i < hi[u]; i++) {
			v = to[u][i];
			if (dis[v] > t) enq(v, t + cost[u][i]);
		}
	}
}

void getGraph(void) {
	int i, k, a, b, c;
	int *memo, sz;

// 入力　N、M
// a1, b1, c1
// a2, b2, c2
// ...
// aM, bM, cM
	N = in(), M = N-1; // 頂点数、枝数の入力
	memo = malloc(M*3*sizeof(int));
	sz = 0; for (i = 0; i < M; ++i) {
		a = in(), b = in(), c = in();
		hi[a]++, hi[b]++;
		memo[sz++] = a, memo[sz++] = b, memo[sz++] = c;
	}
	for (i = 1; i <= N; ++i) if (hi[i]) {
		to[i] = malloc(hi[i]*sizeof(int)), cost[i] = malloc(hi[i]*sizeof(int));
	}
	memset(hi, 0, sizeof(hi));

	i = 0; while (i < sz) {
		a = memo[i++], b = memo[i++], c = memo[i++];
		k = hi[a]++, to[a][k] = b, cost[a][k] = c; // 有向グラフのみ
		k = hi[b]++, to[b][k] = a, cost[b][k] = c; // 無向グラフ
	}
	free(memo);
}

int main()
{
	int K, Q;

	getGraph();
	Q = in(), K = in();
	dijkstra(K);
	while (Q--) {
		int x = in(), y = in();
		out(dis[x] + dis[y]);
	}
	return 0;
}

