fun solve(){
    val n = nextInt()
    val nodes: Array<Node> = Array(n) { Node(it) }
    repeat(n - 1){
        val (a, b, c) =nextIntList()
        nodes[a - 1].edges.add(Edge(a - 1, b - 1, c.toLong()))
        nodes[b - 1].edges.add(Edge(b - 1, a - 1, c.toLong()))
    }

    val (q, k) = nextIntList()
    val dist = dijkstra(nodes, k - 1)
    val ans = Array(q) { 0L }
    repeat(q) { 
        val (x, y) = nextIntList()
        ans[it] = dist[x - 1] + dist[y - 1]
    }

    for (i in ans) {
        println(i)
    }

}

fun dijkstra(nodes: Array<Node>, start: Int) : Array<Long> {
    val queue = PriorityQueue<Edge>(16) { e1: Edge, e2: Edge ->
        if(e1.cost < e2.cost){
            return@PriorityQueue -1
        } else if (e2.cost > e1.cost) {
            return@PriorityQueue 1
        } else {
            return@PriorityQueue 0
        }
    }
    queue.add(Edge(start, start, 0))
    val dist: Array<Long> = Array(nodes.size) { LINF / 2 }
    dist[start] = 0
    while(queue.isNotEmpty()){
        val now = queue.poll()
        if(dist[now.to] < now.cost) continue;
        for (edge in nodes[now.to].edges) {
            if(dist[edge.to] <= dist[edge.from] + edge.cost) continue
            dist[edge.to] = dist[edge.from] + edge.cost
            queue.add(Edge(edge.from, edge.to, dist[edge.to]))
            nodes[edge.to].past = edge.from
        }
    }
    return dist
}

