class Graph(v: Int) {
    private val vec = Array(v + 1) { mutableListOf<E>() }

    fun addEdge(a: Int, b: Int, c: Int) = addEdge(a, b, c.toLong())
    fun addEdge(a: Int, b: Int, c: Long = 0L) {
        vec[a].add(E(b, c))
    }

    fun dijkstra(start: Int): LongArray {
        val que = PriorityQueue<E>(11, Comparator { o1, o2 -> (o1.c - o2.c).toInt() })
        que.add(E(start, 0))
        val d = LongArray(vec.size) { -1 }
        d[start] = 0
        while (que.isNotEmpty()) {
            val cur = que.poll()
            if (d[cur.v] < cur.c) continue
            for (next in vec[cur.v]) {
                if (d[next.v] < 0 || d[next.v] > d[cur.v] + next.c) {
                    d[next.v] = d[cur.v] + next.c
                    que.add(next)
                }
            }
        }
        return d
    }

    data class E(val v: Int, val c: Long)
}

