fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val adj = Array(n) { mutableSetOf<Pair<Int, Int>>() }
    for (i in 0 until n - 1) {
        val u = sc.nextInt() - 1
        val v = sc.nextInt() - 1
        val c = sc.nextInt()
        adj[u].add(v to c)
        adj[v].add(u to c)
    }
    val q = sc.nextInt()
    val k = sc.nextInt() - 1
    val dist = Array(n) { 0L }
    val que: Queue<Pair<Int, Long>> = ArrayDeque()
    que.add(k to 0)
    val visited = Array(n) { false }
    visited[k] = true
    while (que.count() > 0) {
        val (v, d) = que.poll()
        dist[v] = d
        for ((w, c) in adj[v]) {
            if (!visited[w]) {
                visited[w] = true
                que.add(w to d + c)
            }
        }
    }
    for (i in 0 until q) {
        val x = sc.nextInt() - 1
        val y = sc.nextInt() - 1
        println(dist[x] + dist[y])
    }
}

