fun abc070d() {
    val n = readLine()!!.toInt()
    val abcList = (1 until n)
        .map { readLine()!!.split(' ').map { it.toInt() }.let { Edge(it[0] - 1, it[1] - 1, it[2].toLong()) } }
    val (q, k) = readLine()!!.split(' ').map { it.toInt() }
    val queries = (1..q)
        .map { readLine()!!.split(' ').map { it.toInt() }.let { it[0] - 1 to it[1] - 1 } }

    // [from] = to, cost
    val graph = Array(n) { mutableListOf<Pair<Int, Long>>() }
    abcList.forEach {
        val (from, to, cost) = it
        graph[from].add(to to cost)
        graph[to].add(from to cost)
    }

    // cost from K
    val costs = LongArray(n) { -1 }

    fun dfs(beforeCost: Long, currIndex: Int, currCost: Long) {
        costs[currIndex] = beforeCost + currCost

        graph[currIndex].filter { costs[it.first] == -1L }.forEach {
            val (nextIndex, nextCost) = it
            dfs(costs[currIndex], nextIndex, nextCost)
        }
    }

    dfs(0, k - 1, 0)

    val answer = queries.map { costs[it.first] + costs[it.second] }.joinToString(System.lineSeparator())

    println(answer)
}

