// returns distance array
fun dijkstra(graph: List<List<Edge>>, source: Int) : List<Long> {
    val queue = PriorityQueue<Pair<Long, Int>>({ o1, o2 ->  (o1.first - o2.first).toInt() })
    val d = LongArray(graph.size)

    d.fill(Long.MAX_VALUE);
    d[source] = 0
    queue.add(Pair(0, source))

    while(!queue.isEmpty()) {
        val p = queue.poll()!!
        val v = p.second
        if (d[v] < p.first) {
            continue
        }

        for (i in 0 until graph[v].size) {
            val e = graph[v][i]
            if (d[e.to] > d[v] + e.distance) {
                d[e.to] = d[v] + e.distance
                queue.add(Pair(d[e.to], e.to))
            }
        }
    }


    return d.toList()
}

fun main(arg: Array<String>) {
    val INF = 1L.shl(40)
    val N = nextInt()
    val G = Array(N) { mutableListOf<Pair<Int, Long>>() }
    repeat(N - 1) {
        val (a, b, c) = listOfInt(-1, -1, 0)
        val C = c.toLong()
        G[a].add(b to C); G[b].add(a to C)
    }
    fun get(x: Int, y: Int): Long {
        val V = BooleanArray(N)
        fun dfs(s: Int, c: Long, L: Int): Long {
            if (s == y) return c
            if (V[s]) return INF
            V[s] = true
            var cc = INF
            for (d in G[s]) {
                cc = Math.min(cc, dfs(d.first, c + d.second, L + 1))
            }
            return cc
        }
        val rtn = dfs(x, 0, 0)
        return rtn
    }
    val (Q, K) = listOfInt(0, -1)
    val ans = LongArray(Q)
    repeat(Q) { q ->
        val (x, y) = listOfInt(-1, -1)
        ans[q] = get(x, K) + get(K, y)
    }
    println(ans.joinToString("\n"))
}
