	static Main edge[];

	public Main(List<Integer> next, List<Long> c, int count) {
		this.next = next;
		this.c = c;
	}

	public static void dfs(int v, int p, long d) {
		depth[v] = d;
		int n = edge[v].next.size();
		for (int i = 0; i < n; ++i) {
			int next = edge[v].next.get(i);
			if (next == 0)
				break;
			if (next == p)
				continue;
			long cost = edge[v].c.get(i);
			dfs(next, v, d + cost);
		}
	}

	public static void main(String[] args) {
