	private void solve() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		Map<Integer, List<Edge>> map = new HashMap<>();
		for (int i = 1; i < N; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			long c = sc.nextLong();
			if (!map.containsKey(a)) {
				map.put(a, new ArrayList<>());
			}
			if (!map.containsKey(b)) {
				map.put(b, new ArrayList<>());
			}
			map.get(a).add(new Edge(b, c));
			map.get(b).add(new Edge(a, c));
		}
		int Q = sc.nextInt();
		int K = sc.nextInt();
		Set<Integer> parents = new HashSet<>();
		Set<Integer> currents = new HashSet<>();
		currents.add(K);
		long[] dists = new long[N + 1];
		dists[K] = 0L;
		while (!currents.isEmpty()) {
			Set<Integer> nexts = new HashSet<>();
			for (int id : currents) {
				parents.add(id);
				for (Edge e : map.get(id)) {
					if (!parents.contains(e.to)) {
						dists[e.to] = dists[id] + e.cost;
						nexts.add(e.to);
					}
				}
			}
			currents = nexts;
		}
		for (int i = 0; i < Q; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			System.out.println(dists[x] + dists[y]);
		}
	}

