    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        Node nodes[]=new Node[n];
        int a,b;
        long c;
        for(int i=0;i<n;i++) nodes[i]= new Node(i);
