        int a;
        long b;

        public Path(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Path path = (Path) o;
            return a == path.a &&
                    b == path.b;
        }

        @Override
        public int hashCode() {
            return Objects.hash(a, b);
        }
    }
}

