public void solve() {
	int numNode = ni();
	int numEdge = numNode - 1;
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = nl();
		edges[i] = new Edge(a, b, c);
	}
	Graph g = new Graph(numNode, numEdge, edges, false);

	int q = ni();
	int kk = ni() - 1;
	long dist[] = bfs(g.nodes, 0);
	LCA lca = new LCA(numNode);
	lca.init(0, g.nodes);
	for(int i = 0; i < q; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		int root1 = lca.apply(a, kk);
		int root2 = lca.apply(kk, b);
		prtln(dist[a] + dist[b] + dist[kk] * 2 - dist[root1] * 2 - dist[root2] * 2);
	}
	errprtln(dist);
}

long[] bfs(Node nodes[], int start) {
	long dist[] = new long[nodes.length];
	Arrays.fill(dist, INF);

	Deque<Integer> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start] = 0;
	while(!s.isEmpty()) {
		int crt = s.removeFirst();
		for(Edge e : nodes[crt].edges) {
			if(isINF(dist[e.target])) {
				dist[e.target] = dist[e.source] + e.cost;
				s.addLast(e.target);
			}
		}
	}

	return dist;
}

class LCA {
	int numNode;
	int log;
	int[][] parent;
	int[] depth;

	public LCA(int numNode) {
		this.numNode = numNode;
		this.log = Integer.numberOfTrailingZeros(Integer.highestOneBit(numNode - 1)) + 1;
		this.parent = new int[log][numNode];
		this.depth = new int[numNode];
	}

	void init(int root, Node nodes[]) { // O(VlogV)
		bfs(nodes, root);
		parent[0][root] = -1;

		for(int k = 0; k + 1 < log; k ++) {
			for(int v = 0; v < numNode; v ++) {
				if(parent[k][v] < 0) {
					parent[k + 1][v] = -1;
				}else {
					parent[k + 1][v] = parent[k][parent[k][v]];
				}
			}
		}
	}

	void bfs(Node nodes[], int start) {
		Arrays.fill(depth, -1);
		depth[start] = 0;

		Deque<Integer> s = new ArrayDeque<>();
		s.addLast(start);
		depth[start] = 0;
		while(!s.isEmpty()) {
			int crt = s.removeFirst();
			for(Edge e : nodes[crt].edges) {
				if(depth[e.target] < 0) {
					depth[e.target] = depth[e.source] + 1;
					parent[0][e.target] = e.source;
					s.addLast(e.target);
				}
			}
		}
	}

	int apply(int u, int v) { // O(logV)
		if(depth[u] > depth[v]) {
			int t = u;
			u = v;
			v = t;
		}

		for(int k = 0; k < log; k ++) {
			if(isFlagged(depth[v] - depth[u],k)) {
				v = parent[k][v];
			}
		}
		if(u == v) { return u; }

		for (int k = log - 1; k >= 0; k --) {
			if(parent[k][u] != parent[k][v]) {
				u = parent[k][u];
				v = parent[k][v];
			}
		}
		return parent[0][u];
	}
}

	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    private static int N;
    private static Edge[] E;
    private static int K;
    private static Query[] Q;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        E = new Edge[N-1];
        for (int i = 0; i < N-1; i++) {
            E[i] = new Edge(sc.nextInt(), sc.nextInt(), sc.nextInt());
        }
        int q = sc.nextInt();
        K = sc.nextInt();
        Q = new Query[q];
        for (int i = 0; i < q; i++) {
            Q[i] = new Query(sc.nextInt(), sc.nextInt());
        }

        for (long ans : solve()) {
            System.out.println( ans );
        }
    }

    private static long[] solve() {
        List[] nodeEdges = new List[N+1];
        for (int i = 0; i < N+1; i++) {
            nodeEdges[i] = new ArrayList();
        }

        for (Edge edge : E) {
            nodeEdges[edge.a].add( edge );
            nodeEdges[edge.b].add( edge );
        }

        long[] fromK = caclFromK(nodeEdges);

        long[] ans = new long[Q.length];
        for (int i = 0; i < Q.length; i++) {
            Query q = Q[i];
            ans[i] = fromK[q.x] + fromK[q.y];
        }
        return ans;
    }

    private static long[] caclFromK(List[] nodeEdges) {
        long[] fromK = new long[N+1];
        boolean[] done = new boolean[N+1];
        dfs(K, 0, fromK, done, nodeEdges);
        return fromK;
    }

    private static void dfs(int node, long cost, long[] fromK, boolean[] done, List[] nodeEdges) {
        fromK[node] = cost;
        done[node] = true;
        for (Object o : nodeEdges[node]) {
            Edge edge = (Edge) o;
            int next = edge.next(node);
            if( !done[next] ) {
                dfs(next, cost + edge.c, fromK, done, nodeEdges);
            }
        }
    }

    private static class Edge {
        private final int a;
        private final int b;
        private final int c;

        public Edge(int a, int b, int c) {
            this.a = a;
            this.b = b;
            this.c = c;
        }

        public int next(int from) {
            if(from == a ) return b;
            else if( from == b ) return a;
            else throw new IllegalArgumentException("wtf");
        }
    }

    private static class Query {
        private final int x;
        private final int y;

        public Query(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

