	static class TaskX {

		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			List<P>[] g = new ArrayList[n];
			g = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);
			for (int i = 0; i < n-1; i++) {
				int a = in.nextInt()-1, b = in.nextInt()-1, c = in.nextInt();
				g[a].add(new P(b, c));
				g[b].add(new P(a, c));
			}

			int q = in.nextInt(), k = in.nextInt()-1;
			long[] cost = dijkstra(k, g);
			while (q-- > 0) {
				int x = in.nextInt()-1, y = in.nextInt()-1;
				out.println(cost[x] + cost[y]);
			}

		}


		long[] dijkstra(int from, List<P>[] g) {
			int n = g.length;
			PriorityQueue<P> q = new PriorityQueue<>();
			long[] cost = new long[n];
			Arrays.fill(cost, LINF);
			cost[from] = 0;
			q.add(new P(from, cost[from]));

			while (!q.isEmpty()) {

				P pp = q.remove();

				if (pp.second != cost[pp.first]) continue;
				for (P p : g[pp.first]) {
					if (cost[pp.first] + p.second < cost[p.first]) {
						cost[p.first] = cost[pp.first] + p.second;
						q.add(new P(p.first, cost[p.first]));
					}
				}

			}

			return cost;
		}

		class P implements Comparable<P> {
			int first;
			long second;

			public P(int first, long second) {
				super();
				this.first = first;
				this.second = second;
			}

			@Override
			public String toString() {
				return "P [first=" + first + ", second=" + second + "]";
			}

			@Override
			public int compareTo(P o) {
				return Long.compare(this.second, o.second);
			}
		}
	}

