		int v;
		long dist;
		P(int v, long dist){
			this.v=v;
			this.dist=dist;
		}
		@Override
		public int compareTo(P arg0) {
			return Long.compare(this.dist, arg0.dist);
		}
	}

	long d[];
	long INF = 1001001001001001L;
	ArrayList<ArrayList<Edge>> g = new ArrayList<>();
	public void run() {
