public class Main {
	static ArrayList<HashMap<Integer, Long>> list = new ArrayList<HashMap<Integer, Long>>();
	static long maze_cnt[];
	public static void main(String args[]) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int a[] = new int[N];
		int b[] = new int[N];
		long c[] = new long[N];

		for(int i = 0; i < N; i++) {
			HashMap<Integer, Long> map = new HashMap<Integer, Long>();
			list.add(map);
		}

		for(int i = 0; i < N - 1; i++) {
			a[i] = sc.nextInt() - 1;
			b[i] = sc.nextInt() - 1;
			c[i] = (long)sc.nextInt();
			list.get(a[i]).put(b[i], c[i]);
			list.get(b[i]).put(a[i], c[i]);
		}

		int Q = sc.nextInt();
		int K = sc.nextInt() - 1;
		int x[] = new int[Q];
		int y[] = new int[Q];
		for(int i = 0; i < Q; i++) {
			x[i] = sc.nextInt() - 1;
			y[i] = sc.nextInt() - 1;
		}

		DFS(list, K);

		for(int i = 0; i < Q; i++) {
			System.out.println(maze_cnt[x[i]] + maze_cnt[y[i]]);
		}
	}

public static void DFS(ArrayList<HashMap<Integer, Long>> list, int now) {

		Queue<Integer> queue = new ArrayDeque<Integer>();
		queue.add(now);

		maze_cnt = new long[list.size()];
		boolean flag[] = new boolean[list.size()];

		for(int i = 0; i < list.size(); i++) {
			maze_cnt[i] = Integer.MAX_VALUE;
			flag[i] = false;
		}

		maze_cnt[now] = 0;

		while(queue.size() != 0) {
			now = queue.poll();
			for(int key : list.get(now).keySet()) {
				if(maze_cnt[key] > maze_cnt[now] + list.get(now).get(key) && !flag[key]) {
					queue.add(key);
					maze_cnt[key] = maze_cnt[now] + list.get(now).get(key);
					flag[key] = true;
				}
			}
		}
	}
}

import java.util.*;

public class Main {

	class State implements Comparable<State>{
		int now;
		long cost;
		public State(int now, long cost) {
			this.now = now;
			this.cost = cost;
		}
		public int compareTo(State o) {
			if(this.cost > o.cost) return 1;
			if(this.cost < o.cost) return -1;
			return 0;
		}
	}

	private void doit(){
		Scanner sc = new Scanner(System.in);
		while(sc.hasNext()){
			int n = sc.nextInt();
			long [][] pass = new long[n][n];
			for(int i = 0; i < n;i++){
				Arrays.fill(pass[i], Long.MAX_VALUE);
			}

			for(int i =0; i < n-1; i++){
				int a = sc.nextInt() - 1;
				int b = sc.nextInt() - 1; 
				int c = sc.nextInt();
				pass[a][b] = c;
				pass[b][a] = c;
			}
			int q = sc.nextInt();
			int start = sc.nextInt() -1;

			PriorityQueue<State> open = new PriorityQueue<>();
			open.add(new State(start, 0));
			long [] close = new long[n];
			Arrays.fill(close, Long.MAX_VALUE);

			while(!open.isEmpty()){
				State current = open.poll();

				for(int i = 0; i < n;i++){
					if(current.now == i)continue;
					if(pass[current.now][i] == Long.MAX_VALUE ) continue;
					long nextcost = current.cost + pass[current.now][i];
					if(close[i] < nextcost) continue;
					close[i] = nextcost;
					open.add(new State(i, nextcost));
				}
			}

			StringBuilder sb = new StringBuilder();
			for(int i = 0; i < q; i++){
				int x = sc.nextInt() - 1;
				int y = sc.nextInt() - 1;
				long res = close[x] + close[y];
				sb.append(res+"\n");
			}
			System.out.print(sb.toString());
		}

	}


	private void debug(Object... o) {
		System.out.println("debug = " + Arrays.deepToString(o));
	}

	public static void main(String[] args) {
		new Main().doit();
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.Objects;
import java.util.PriorityQueue;
import java.util.StringTokenizer;
import java.util.stream.Collectors;

public class Main {

	public static void main(String args[]) {
		ConsoleScanner cin = new ConsoleScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	static long now() {
		return System.currentTimeMillis();
	}

	static void trace(Object... objects) {
		assert null != System.out.format("trace:%s\n", Arrays.deepToString(objects));
	}

	private static void solve(ConsoleScanner cin, PrintWriter cout) {
		// assert solve(1) == 1;
		int n = cin.nextInt();
		int[][] abcs = new int[n - 1][];
		for (int i = 0; i < abcs.length; i++)
			abcs[i] = new int[] { cin.nextInt(), cin.nextInt(), cin.nextInt() };
		int q = cin.nextInt();
		int k = cin.nextInt();
		int[][] xys = new int[q][];
		for (int i = 0; i < xys.length; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt() };

		long start = now();

		long[] ans = solve(n, abcs, q, k, xys);
		String ansstr = Arrays.stream(ans).mapToObj(Objects::toString)
				.collect(Collectors.joining(System.lineSeparator()));

		cout.println(ansstr);
		trace("elapsed", now() - start);
	}

	private static long[] solve(int n, int[][] abcs, int q, int k, int[][] xys) {
		int[] elen = new int[n + 1];
		for (int[] abc : abcs) {
			elen[abc[0]] += 1;
			elen[abc[1]] += 1;
		}
		int[][][] edges = new int[n + 1][][];
		for (int i = 1; i <= n; i++)
			edges[i] = new int[elen[i]][];
		for (int[] abc : abcs) {
			edges[abc[0]][--elen[abc[0]]] = new int[] { abc[1], abc[2] };
			edges[abc[1]][--elen[abc[1]]] = new int[] { abc[0], abc[2] };
		}

		// 始点Kからの最短経路
		// ダイクストラ法
		long[] dist = new long[n + 1];
		Arrays.fill(dist, -1L);
		PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(vals -> vals[1]));
		pq.add(new long[] { k, 0 });
		while (!pq.isEmpty()) {
			long[] arg = pq.poll();
			int v = (int) arg[0];
			long c = arg[1];
			if (dist[v] != -1)
				continue;
			dist[v] = c;
			for (int[] e : edges[v]) {
				int to = e[0];
				if (dist[to] != -1)
					continue;
				pq.add(new long[] { to, c + e[1] });
			}
		}

		long[] ans = Arrays.stream(xys).mapToLong(xy -> dist[xy[0]] + dist[xy[1]]).toArray();
		return ans;
	}

	static class ConsoleScanner {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		String next() {
			try {
				while (!st.hasMoreElements())
					st = new StringTokenizer(br.readLine());
				return st.nextToken();
			} catch (IOException e) {
				throw new AssertionError(e);
			}
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

