public class Main{
	static ArrayList<ArrayList<Edge>> tree;
	static long[] depth;
	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		int n = sc.nextInt();
		tree = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			tree.add(new ArrayList<>());
		}
		for (int i = 0; i < n - 1; i++) {
			int a = sc.nextInt() - 1;
			int b = sc.nextInt() - 1;
			long c = sc.nextLong();
			tree.get(a).add(new Edge(b, c));
			tree.get(b).add(new Edge(a, c));
		}
		int q = sc.nextInt();
		int k = sc.nextInt() - 1;
		int[] x = new int[q];
		int[] y = new int[q];
		for (int i = 0; i < q; i++) {
			x[i] = sc.nextInt() - 1;
			y[i] = sc.nextInt() - 1;
		}
		depth = new long[n];
		for (int i = 0; i < n; i++) {
			depth[i] = -1;
		}
		depth[k] = 0;
		dfs(k);
		for (int i = 0; i < q; i++) {
			System.out.println(depth[x[i]] + depth[y[i]]);
		}
	}
	static void dfs(int n) {
		for (Edge edge :
				tree.get(n)) {
			if (depth[edge.to] == -1) {
				depth[edge.to] = depth[n] + edge.distance;
				dfs(edge.to);
			}
		}
	}
}

