public class Main{
	static IntStream REPS(int v){return IntStream.range(0,v);}
	static IntStream REPS(int l,int r){return IntStream.rangeClosed(l,r);}
	static IntStream INS(int n) {return REPS(n).map(i->getInt());}
	static Scanner s=new Scanner(System.in);
	static int getInt(){return Integer.parseInt(s.next());}
	public static void main(String[]$){
		int n=getInt();

		ArrayList<ArrayList<Edge>>edges=new ArrayList<>();
		for(int i=0;i<n;++i)edges.add(new ArrayList<>());
		for(int i=0;i<n-1;++i){
			int a=getInt()-1,b=getInt()-1,c=getInt();
			edges.get(a).add(new Edge(a,b,c));
			edges.get(b).add(new Edge(b,a,c));
		}
		int q=getInt(),k=getInt()-1;
		long[]dist=new long[n];
		{
			PriorityQueue<Edge>p=new PriorityQueue<>(edges.get(k));
			Arrays.fill(dist,Integer.MAX_VALUE);
			dist[k]=0;

			int filled=1;
			while(filled!=n){
				Edge poll=p.poll();
				if(dist[poll.t]==Integer.MAX_VALUE) {
					dist[poll.t]=dist[poll.f]+poll.c;
					p.addAll(edges.get(poll.t));
					++filled;
				}
			}
		}
		for(int i=0;i<q;++i)
			System.out.println(dist[getInt()-1]+dist[getInt()-1]);
	}
	static class Edge implements Comparable<Edge>{
		int f,t;long c;
		public Edge(int from,int to,int cost){f=from;t=to;c=cost;}
		@Override
		public String toString(){return "("+f+","+t+")="+c;}
		@Override
		public int compareTo(Edge o){
			long v=c-o.c;
			return v==0?0:v>0?1:-1;
		}
		@Override
		public int hashCode(){
			final int prime=31;
			int result=prime+(int)(c^(c>>>32));
			result=prime*result+f;
			result=prime*result+t;
			return result;
		}
		@Override
		public boolean equals(Object obj){
			if(this==obj) return true;
			if(obj==null||getClass()!=obj.getClass()) return false;
			Edge other=(Edge)obj;
			if(c!=other.c||f!=other.f||t!=other.t) return false;
			return true;
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

    private static class Edge {
        int from;
        int to;
        long cost;

        private Edge(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
    }

    public static long dijkstra(Map<Integer, List<Edge>> allEdges, int start, int end, int nodeNum) {
        long[] d = new long[nodeNum + 1];
        Arrays.fill(d, -1);
        PriorityQueue<Edge> heap = new PriorityQueue<>(Comparator.comparingLong(a -> d[a.from] + a.cost));
        d[start] = 0;
        List<Edge> edges = allEdges.get(start);
        heap.addAll(edges);
        while (d[end] < 0) {
            Edge nearest = heap.poll();
            if (d[nearest.to] >= 0) {
                continue;
            }
            d[nearest.to] = d[nearest.from] + nearest.cost;
            if (!allEdges.containsKey(nearest.to)) {
                continue;
            }
            edges = allEdges.get(nearest.to);
            for (int i = 0; i < edges.size(); i++) {
                Edge edge = edges.get(i);
                if (d[edge.to] < 0) {
                    heap.add(edge);
                }
            }
        }
        return d[end];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n - 1];
        int[] b = new int[n - 1];
        long[] c = new long[n - 1];
        Map<Integer, List<Edge>> map = new HashMap<>();
        for (int i = 1; i <= n; i++) {
            map.put(i, new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            a[i] = sc.nextInt();
            b[i] = sc.nextInt();
            c[i] = sc.nextLong();
            List<Edge> l1 = map.get(a[i]);
            l1.add(new Edge(a[i], b[i], c[i]));
            map.put(a[i], l1);
            List<Edge> l2 = map.get(b[i]);
            l2.add(new Edge(b[i], a[i], c[i]));
            map.put(b[i], l2);
        }
        int q = sc.nextInt();
        int k = sc.nextInt();
        int[] x = new int[q];
        int[] y = new int[q];
        for (int i = 0; i < q; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }
        long[] d = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            d[i] = dijkstra(map, k, i, n);
        }
        for (int i = 0; i < q; i++) {
            System.out.println(d[x[i]] + d[y[i]]);
        }
    }

}

