    SegTree(int N){
        this.dat = new int[N * 4];
        this.size = N;
    }

    // [a, b]の最小値を返す
    // l,rにはノードkに対応する区間を与える
    int query(int a, int b, int k, int l, int r){
        if(r < a || b < l) return Integer.MAX_VALUE;
        if(a <= l && r <= b) return dat[k];
        int vl = query(a, b, k << 1, l, (l + r) / 2);
        int vr = query(a, b, (k << 1) + 1, (l + r) / 2 + 1, r);
        return Math.min(vl, vr);
    }

    // インデックスiの値をxに更新
    void update(int i, int x){
        i += this.size - 1;
        dat[i] = x;
        while(i > 0){
            i = i >> 1;     // 1ビットぶん右シフト
            dat[i] = Math.min(dat[i << 1], dat[(i << 1) + 1]);
        }
    }

    public String toString(){
        StringBuilder sb = new StringBuilder("[");
        for(int i = size; i < 2 * size; i++){
            sb.append(dat[i]).append(",");
        }
        sb.delete(sb.length() - 1, sb.length());
        String output = sb.append("]").toString();
        return output;
    }
}

// Range Sum Queryを実現するBinary Indexed Tree
class BIT{
    int[] tree;

    BIT(int N){
        this.tree = new int[N + 1];
    }

    int sum(int i){
        int sum = 0;
        while(i > 0){
            sum += this.tree[i];
            i -= i & -i;
        }
        return sum;
    }

    void add(int i, int x){
        while(i <= tree.length){
            this.tree[i] += x;
            i += i & -i;
        }
    }

    public String toString(){
        StringBuilder sb = new StringBuilder("[");
        for(int i = 0; i < tree.length; i++){
            sb.append(tree[i] + ",");
        }
        sb.append("]");
        String output = sb.toString();
        return output;
    }

}

// 標準のScannerより高速に標準入力する
class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.HashMap;
import java.util.LinkedList;
import java.util.Scanner;

public class Main {
	private Scanner sc;

	private int n;

	private long[] node;

	private HashMap<Integer, LinkedList<Integer>> hm;
	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		sc = new Scanner(System.in);

		n = sc.nextInt();


		hm = new HashMap<Integer, LinkedList<Integer>>();
		for (int i = 0; i < (n - 1); i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();
			int val = sc.nextInt();

			LinkedList<Integer> ll = new LinkedList<Integer>();
			if (hm.containsKey(from) == true) ll = hm.get(from);
			ll.push(to);
			ll.push(val);
			hm.put(from, ll);

			ll = new LinkedList<Integer>();
			if (hm.containsKey(to) == true) ll = hm.get(to);
			ll.push(from);
			ll.push(val);
			hm.put(to, ll);
		}

		int q = sc.nextInt();
		int k = sc.nextInt();

		node = new long[n + 1];
		for (int i = 0; i < node.length; i++) {
			node[i] = -1;
		}
		node[k] = 0;
		calc(k);

		for (int i = 0; i < q; i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();

			System.out.println(node[from] + node[to]);
		}
	}

	private void calc(int from) {
		if (hm.containsKey(from) == false) return;

		LinkedList<Integer> ll = hm.get(from);

		for (int i = 0; i < (ll.size() / 2); i++) {
			int index = ll.get(i * 2 + 1);
			if (node[index] != -1) continue;

			node[index] = node[from] + ll.get(i * 2);
			calc(index);
		}
	}
}

