import java.util.StringTokenizer;
import java.util.stream.Collectors;

public class Main {

	public static void main(String args[]) {
		ConsoleScanner cin = new ConsoleScanner();
		PrintWriter cout = new PrintWriter(System.out);
		solve(cin, cout);
		cout.flush();
	}

	static long now() {
		return System.currentTimeMillis();
	}

	static void trace(Object... objects) {
		assert null != System.out.format("trace:%s\n", Arrays.deepToString(objects));
	}

	private static void solve(ConsoleScanner cin, PrintWriter cout) {
		// assert solve(1) == 1;
		int n = cin.nextInt();
		int[][] abcs = new int[n - 1][];
		for (int i = 0; i < abcs.length; i++)
			abcs[i] = new int[] { cin.nextInt(), cin.nextInt(), cin.nextInt() };
		int q = cin.nextInt();
		int k = cin.nextInt();
		int[][] xys = new int[q][];
		for (int i = 0; i < xys.length; i++)
			xys[i] = new int[] { cin.nextInt(), cin.nextInt() };

		long start = now();

		long[] ans = solve(n, abcs, q, k, xys);
		String ansstr = Arrays.stream(ans).mapToObj(Objects::toString)
				.collect(Collectors.joining(System.lineSeparator()));

		cout.println(ansstr);
		trace("elapsed", now() - start);
	}

	private static long[] solve(int n, int[][] abcs, int q, int k, int[][] xys) {
		ArrayList<int[]> edges = new ArrayList<>();
		for (int[] abc : abcs) {
			edges.add(abc);
			edges.add(new int[] { abc[1], abc[0], abc[2] });
		}
		Collections.sort(edges, Comparator.comparingInt(abc -> abc[0]));
		int[] soe = new int[n + 2];
		for (int i = edges.size() - 1; i >= 0; i--) {
			int[] e = edges.get(i);
			soe[e[0]] = i;
		}
		soe[n + 1] = edges.size();

		// 始点Kからの最短経路
		// ダイクストラ法
		long[] dist = new long[n + 1];
		Arrays.fill(dist, -1L);
		PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(vals -> vals[1]));
		pq.add(new long[] { k, 0 });
		while (!pq.isEmpty()) {
			long[] arg = pq.poll();
			int v = (int) arg[0];
			long c = arg[1];
			if (dist[v] != -1)
				continue;
			dist[v] = c;
			for (int i = soe[v]; i < soe[v + 1]; i++) {
				int[] e = edges.get(i);
				int to = e[1];
				if (dist[to] != -1)
					continue;
				pq.add(new long[] { to, c + e[2] });
			}
		}

		long[] ans = Arrays.stream(xys).mapToLong(xy -> dist[xy[0]] + dist[xy[1]]).toArray();
		return ans;
	}

	static class ConsoleScanner {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer("");

		String next() {
			try {
				while (!st.hasMoreElements())
					st = new StringTokenizer(br.readLine());
				return st.nextToken();
			} catch (IOException e) {
				throw new AssertionError(e);
			}
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}
	}

}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(final String[] args) {
        final Scanner scanner = new Scanner(System.in);
        final int n = scanner.nextInt();

        final Map<Integer, List<Node>> tree = new HashMap<>();
        for (int i = 0; i < n - 1; i++) {
            final int a = scanner.nextInt();
            final int b = scanner.nextInt();
            final int c = scanner.nextInt();
            tree.computeIfAbsent(a, v -> new ArrayList<>()).add(new Node(b, c));
            tree.computeIfAbsent(b, v -> new ArrayList<>()).add(new Node(a, c));
        }

        final int q = scanner.nextInt();
        final int k = scanner.nextInt();

        final long[] distances = new long[n + 1];
        distances[k] = Long.MAX_VALUE;
        recursive(distances, tree, k, 0);

        for (int i = 0; i < q; i++) {
            final int x = scanner.nextInt();
            final int y = scanner.nextInt();
            System.out.println(distances[x] + distances[y]);
        }
    }

    private static void recursive(final long[] distances, final Map<Integer, List<Node>> tree, final int currentNode, final long sumDistance) {
        final List<Node> destinations = tree.get(currentNode);
        for (final Node destination : destinations) {
            if (distances[destination.label] != 0) {
                continue;
            }

            distances[destination.label] = sumDistance + destination.distance;
            recursive(distances, tree, destination.label, sumDistance + destination.distance);
        }
    }

    static class Node {
        int label;
        long distance;

        Node(final int label, final int distance) {
            this.label = label;
            this.distance = distance;
        }
    }
}

