  static ArrayList[] edge;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    edge = new ArrayList[n];
    for(int i = 0; i < n; i++) {
      edge[i] = new ArrayList<Edge>();
    }
    for(int i = 0; i < n - 1; i++) {
      int a = sc.nextInt() - 1;
      int b = sc.nextInt() - 1;
      long c = sc.nextLong();
      Edge e1 = new Edge(b, c);
      Edge e2 = new Edge(a, c);
      edge[a].add(e1);
      edge[b].add(e2); 
    }
    int Q = sc.nextInt();
    int K = sc.nextInt() - 1;
    dfs(K, -1, 0);
    for(int i = 0; i < Q; i++) {
      int x = sc.nextInt() - 1;
      int y = sc.nextInt() - 1;
      System.out.println(depth[x] + depth[y]);
    }
  }

  public static void dfs(int v, int parent, long depth) {
    depth[v] = depth;
    ArrayList<Edge> elist = edge[v];
    for(int i = 0; i < elist.size(); i++) {
      Edge e = elist.get(i);
      if(e.to != parent) dfs(e.to, v, e.cost + depth[v]); 
    } 
  }
}

class Edge {
  int to;
  long cost;
  Edge(int to, long cost) {
    this.to = to;
    this.cost = cost;
  }
}

import java.util.ArrayList;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    static long[] distance;
    static ArrayList<TreeMap<Integer, Long>> edges;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        distance = new long[n];
        edges = new ArrayList<>();
        for (int i = 0 ; i < n ; i++) {
            edges.add(new TreeMap<Integer, Long>());
        }
        for (int i = 0 ; i < n - 1 ; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            long d = sc.nextLong();
            edges.get(a).put(b, d);
            edges.get(b).put(a, d);
        }
        int q = sc.nextInt();
        dfs(-1, sc.nextInt() - 1, 0);
        for (int i = 0 ; i < q ; i++) {
            System.out.println(distance[sc.nextInt() - 1] + distance[sc.nextInt() ^ 1]);
        }


    }

    static void dfs(int from, int to, long d) {
        distance[to] = d;
        TreeMap<Integer, Long> m = edges.get(to);
        m.remove(from);
        m.forEach((k, v) -> dfs(to, k, d+v));
    }

}

import java.util.Scanner;

public class Main {
	private Scanner sc;

	private int n;
	private long[][] map;

	boolean[] flag;
	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		sc = new Scanner(System.in);

		n = sc.nextInt();

		map = new long[n + 1][n + 1];
		for (int i = 0; i < map.length; i++) {
			for (int j = 0; j < map.length; j++) {
				map[i][j] = 0;
			}
		}
		for (int i = 0; i < (n - 1); i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();
			int val = sc.nextInt();
			map[from][to] = val;
			map[to][from] = val;
		}

		int q = sc.nextInt();
		int k = sc.nextInt();

		flag = new boolean[n + 1];
		for (int i = 0; i < flag.length; i++) {
			flag[i] = false;
		}

		for (int i = 0; i < map.length; i++) {
			for (int j = (i + 1); j < map.length; j++) {
				calc(i, j);
			}
		}

		for (int i = 0; i < q; i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();

			System.out.println(map[from][k] + map[k][to]);
		}
	}

	private long calc(int from, int to) {
		flag[from] = true;

		if (map[from][to] != 0) {
			flag[from] = false;
			return map[from][to];
		}

		long tmp = 0;
		long min = 0;
		for (int i = 1; i < n; i++) {
			if ((flag[i] == true) || (map[from][i] == 0)) continue;

			tmp = map[from][i] + calc(i, to);
			if (((min == 0) || (min > tmp)) && (tmp != map[from][i])) min = tmp;
		}

		flag[from] = false;
		map[from][to] = min;
		map[to][from] = min;
		return min;
	}
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] a = new int[N - 1];
		int[] b = new int[N - 1];
		long[] c = new long[N - 1];
		for(int i = 0; i < N - 1; i++) {
			a[i] = sc.nextInt() - 1;
			b[i] = sc.nextInt() - 1;
			c[i] = sc.nextLong();
		}
		int Q = sc.nextInt();
		int K = sc.nextInt() - 1;
		int[] x = new int[Q];
		int[] y = new int[Q];
		for(int i = 0; i < Q; i++) {
			x[i] = sc.nextInt() - 1;
			y[i] = sc.nextInt() - 1;
		}
		sc.close();
		long[] d = dijkstra(N, K, a, b, c, true);
		StringBuilder sb = new StringBuilder();
		for(int i = 0; i < Q; i++) {
			long ans = d[x[i]] + d[y[i]];
			sb.append(ans).append("\n");
		}
		System.out.print(sb.toString());
	}
	/**
	 * ダイクストラ法 (優先度付きキュー)
	 * @param N 頂点数 (0 ~ N-1)
	 * @param t 始点
	 * @param from, to 辺
	 * @param cost 辺のコスト
	 * @param flag true なら無向辺、 false なら有向辺
	 * @return d t から各頂点への最短距離
	 */
	public static long[] dijkstra(int N, int t, int[] from, int[] to, long[] cost, boolean flag) {
		final int WHITE = 0;
	    final int GRAY = 1;
	    final int BLACK = 2;
	    final long INF = 100000000000000l;
		long[] d = new long[N];
		int[] color = new int[N];
		@SuppressWarnings("unchecked")
		ArrayList<Node>[] adj = new ArrayList[N];
		for(int i = 0; i < N; i++) {
			d[i] = INF;
			color[i] = WHITE;
			adj[i] = new ArrayList<Node>();
		}
		int E = from.length;
		for(int i = 0; i < E; i++) {
			adj[from[i]].add(new Node(to[i], cost[i]));
			if(flag)adj[to[i]].add(new Node(from[i], cost[i]));

		}
		Queue<Node> pq = new PriorityQueue<Node>(new MyComparator());
		d[t] = 0;
		pq.add(new Node(t, 0l));
		while(!pq.isEmpty()) {
			Node f = pq.poll();
			int u = f.id;
			color[u] = BLACK;
			if(d[u] < f.cost) continue;
			for(int j = 0; j < adj[u].size(); j++) {
				int v = adj[u].get(j).id;
				if(color[v] == BLACK) continue;
				if(d[v] > d[u] + adj[u].get(j).cost) {
					d[v] = d[u] + adj[u].get(j).cost;
					pq.add(new Node(v, d[v]));
					color[v] = GRAY;
				}
			}
		}
		return d;
	}
	static class Node{
		int id;
		long cost;
		public Node(int id, long cost) {
			this.id = id;
			this.cost = cost;
		}
	}
	static class MyComparator implements Comparator<Node>{
		@Override
        public int compare(Node v1, Node v2) {
			if(v1.cost < v2.cost) {
				return -1;
			}else if(v1.cost == v2.cost) {
				return 0;
			}else {
				return 1;
			}
		}
	}
}

import java.io.*;
import java.util.*;

class Main {


	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int[] a = new int[N - 1];
		int[] b = new int[N - 1];
		long[] c = new long[N - 1];
		for (int i = 0; i < N - 1; i++) {
			a[i] = sc.nextInt() - 1;
			b[i] = sc.nextInt() - 1;
			c[i] = sc.nextLong();
		}

		int Q = sc.nextInt();
		int K = sc.nextInt() - 1;

		long[] dk = new long[N];
		Arrays.fill(dk, Long.MAX_VALUE);
		dk[K] = 0;
		int t = 0;
		while (t++ <= N + 1) {
			boolean updated = false;
			for (int i = 0; i < N - 1; i++) {
				if (dk[a[i]] != Long.MAX_VALUE) {
					if (dk[a[i]] + c[i] < dk[b[i]]) {
						dk[b[i]] = dk[a[i]] + c[i];
						updated = true;
					}
				}
				if (dk[b[i]] != Long.MAX_VALUE) {
					if (dk[b[i]] + c[i] < dk[a[i]]) {
						dk[a[i]] = dk[b[i]] + c[i];
						updated = true;
					}
				}
			}
			if (!updated) break;
		}

		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < Q; i++) {
			int x = sc.nextInt() - 1;
			int y = sc.nextInt() - 1;
			sb.append(dk[x] + dk[y]).append("\n");
		}

		System.out.print(sb.toString());
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		List<List<Hen>> list = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			list.add(new ArrayList<>());
		}
		for (int i = 0; i < n - 1; i++) {
			sa = br.readLine().split(" ");
			int a = Integer.parseInt(sa[0]) - 1;
			int b = Integer.parseInt(sa[1]) - 1;
			int c = Integer.parseInt(sa[2]);
			list.get(a).add(new Hen(b, c));
			list.get(b).add(new Hen(a, c));
		}

		sa = br.readLine().split(" ");
		int q = Integer.parseInt(sa[0]);
		int k = Integer.parseInt(sa[1]) - 1;
		int[] x = new int[q];
		int[] y = new int[q];
		for (int i = 0; i < q; i++) {
			sa = br.readLine().split(" ");
			x[i] = Integer.parseInt(sa[0]) - 1;
			y[i] = Integer.parseInt(sa[1]) - 1;
		}
		br.close();

		long[] d = new long[n];
		Arrays.fill(d, Long.MAX_VALUE);
		Queue<Integer> que = new ArrayDeque<>();
		que.add(k);
		d[k] = 0;
		while (!que.isEmpty()) {
			int cur = que.poll();
			for (Hen h : list.get(cur)) {
				if (d[h.v] == Long.MAX_VALUE) {
					que.add(h.v);
					d[h.v] = d[cur] + h.c;
				}
			}
		}

		PrintWriter pw = new PrintWriter(System.out);
		for (int i = 0; i < q; i++) {
			pw.println(d[x[i]] + d[y[i]]);
		}
		pw.flush();
	}

	static class Hen {
		int v, c;

		public Hen(int v, int c) {
			this.v = v;
			this.c = c;
		}
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			int[][] map = new int[n][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					map[i][j] = (i == j) ? 0 : -1;
				}
			}

			for (int i = 0; i < n - 1; i++) {
				int a = sc.nextInt() - 1;
				int b = sc.nextInt() - 1;
				int c = sc.nextInt();
				map[a][b] = c;
				map[b][a] = c;
			}

			int q = sc.nextInt();
			int k = sc.nextInt() - 1;

			for (int i = 0; i < q; i++) {
				int x = sc.nextInt() - 1;
				int y = sc.nextInt() - 1;

				long[] distance = new long[n];
				dijkstra(map, k, distance);
				System.out.println(distance[x] + distance[y]);
			}
		}
	}

	public static void dijkstra(int[][] map, int src, long[] distance) {
		int nTown = distance.length;
		boolean[] fixed = new boolean[nTown];
		for (int i = 0; i < nTown; i++) {
			distance[i] = Long.MAX_VALUE;
			fixed[i] = false;
		}
		distance[src] = 0;
		while (true) {
			int marked = minIndex(distance, fixed);
			if (marked < 0)
				return;
			if (distance[marked] == Integer.MAX_VALUE)
				return;
			fixed[marked] = true;
			for (int j = 0; j < nTown; j++) {
				if (map[marked][j] > 0 && !fixed[j]) {
					long newDistance = distance[marked] + map[marked][j];
					if (newDistance < distance[j])
						distance[j] = newDistance;
				}
			}
		}
	}

	static int minIndex(long[] distance, boolean[] fixed) {
		int idx = 0;
		for (; idx < fixed.length; idx++)
			if (!fixed[idx])
				break;
		if (idx == fixed.length)
			return -1;
		for (int i = idx + 1; i < fixed.length; i++)
			if (!fixed[i] && distance[i] < distance[idx])
				idx = i;
		return idx;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.List;
import java.util.ArrayList;
import java.util.Queue;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        Main m = new Main();
        m.solve();
    }
    private void solve() throws Exception {
        FastScan scan = new FastScan(System.in);
        int N = scan.scanInt();
        List<List<Path>> graph = new ArrayList(N);
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < N - 1; i++) {
            int a = scan.scanInt()-1;
            int b = scan.scanInt()-1;
            int c = scan.scanInt();
            graph.get(a).add(new Path(b, c));
            graph.get(b).add(new Path(a, c));
        }
        int Q = scan.scanInt();
        int K = scan.scanInt()-1;
        Queue<Integer> queue = new ArrayDeque<>();
        long[] distances = new long[N];
        boolean[] visited = new boolean[N];
        queue.add(K);
        while(!queue.isEmpty()) {
            int current = queue.poll();
            visited[current] = true;
            for (Path p : graph.get(current)) {
                if (visited[p.to]) {
                    continue;
                }
                distances[p.to] = distances[current] + p.cost;
                queue.add(p.to);
            }
        }
        for (int i = 0; i < Q; i++) {
            int from = scan.scanInt() - 1;
            int to = scan.scanInt() - 1;
            System.out.println(distances[from] + distances[to]);
        }
    }

    class Path {
        int to;
        int cost;
        Path(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }
    class FastScan {
        BufferedReader br;
        StringTokenizer st;
        FastScan(InputStream is) {
            InputStreamReader isr = new InputStreamReader(is);
            this.br = new BufferedReader(isr);
        }
        String next() throws IOException {
            while (this.st == null || !this.st.hasMoreTokens()) {
                this.st = new StringTokenizer(br.readLine().trim());
            }
            return st.nextToken();
        }
        long scanLong() throws IOException {
            return Long.parseLong(this.next());
        }
        int scanInt() throws IOException {
            return Integer.parseInt(this.next());
        }
        double scanDouble() throws IOException {
            return Double.parseDouble(this.next());
        }
        char scanCharacter() throws IOException {
            return this.next().charAt(0);
        }
        String nextLine() throws IOException {
            return br.readLine().trim();
        }
    }
}

import java.io.IOException;
