public class Main {
    static class Element {
        long t, c;

        Element(long t, long c) {
            this.t = t;
            this.c = c;
        }
    }

    static int NN = 100007;
    static ArrayList<Long>[] G;
    static long z[];

    static void dfs(int v, long u, int p) {
        z[v] = u;
        for (int i = 0; i < G[v].size(); i++) {
            long qaq = G[v].get(i);
            int w = (int) (qaq >>> 32);
            if (w == p) continue;
            dfs(w, u + (int) qaq, v);
        }
    }

