        arrived[now] = true;
        dist[now] = d;
        for(Map.Entry<Integer,Long> e : root.get(now).entrySet()){
            int k = e.getKey();
            long v = e.getValue();
            if(!arrived[k]){
                dfs(k,d+v);
            }
        }
        return;
    }
