    	PriorityQueue<long[]> q;

    	// 頂点の数を引数に初期化
    	public DijkstraMatrix(int n) {
    		a = new int[n + 1][n + 1];
    		b = new boolean[n + 1];
    		q = new PriorityQueue<long[]>(n + 1, new Comparator<long[]>() {
    			@Override
    			public int compare(long[] o1, long[] o2) {
    				if(o1[1] == o2[1])		return 0;
    				else if(o1[1] > o2[1])	return 1;
    				else					return -1;
    			}
    		});
    	}
    	// 辺の登録
    	public void set(int i, int j, int cost) {
    		a[i][j] = cost;
    		a[j][i] = cost;
    	}
    	// コスト計算
    	public long getCost(int s, int e) {
    		Arrays.fill(b, false);
    		q.clear();
    		b[s] = true;
    		for (int i = 1; i < a.length; ++i)
    			if (a[s][i] > 0)
    				q.add(new long[] { i, a[s][i] });
    		long c = 0;
    		while (!q.isEmpty()) {
    			long[] t = q.poll();
    			if (t[0] == e) {
    				c = t[1];
    				break;
    			}
    			b[(int)t[0]] = true;
    			for (int i = 1; i < a.length; ++i)
    				if (!b[i] && a[(int)t[0]][i] > 0)
    					q.add(new long[] { i, t[1] + a[(int)t[0]][i] });
    		}
    		return c;
    	}
    }

    static class Solver {
    	public void solve(int testNumber, MyInput in, PrintWriter out) {
    		int N = in.nextInt();
