import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    int N;
    Scanner scanner = new Scanner(System.in);
    Node[] nodes;

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        N = scanner.nextInt();
        nodes = new Node[N];
        for (int i = 0; i < N; i++) {
            nodes[i] = new Node();
        }
        for (int i = 0; i < N - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            long c = scanner.nextLong();
            nodes[a - 1].add(nodes[b - 1], c);
            nodes[b - 1].add(nodes[a - 1], c);
        }
        int Q = scanner.nextInt();
        int K = scanner.nextInt();

        long[] costs = new long[N];
        for (int i = 0; i < N; i++) {
            costs[i] = cost(nodes[i], nodes[K - 1], null);
        }

        for (int i = 0; i < Q; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            System.out.println(costs[x - 1] + costs[y - 1]);
        }

    }

    long cost(Node x, Node y, Node prev) {
        if (x == y) {
            return 0;
        }
        for (int i = 0; i < x.nexts.size(); i++) {
            Node next = x.nexts.get(i);
            if (prev == next) {
                continue;
            }
            long nextCost = cost(next, y, x);
            if (nextCost != -1) {
                return nextCost + x.distances.get(i);
            }
        }
        return -1;
    }

    class Node {

        List<Node> nexts = new ArrayList<>();
        List<Long> distances = new ArrayList<>();

        void add(Node next, long distance) {
            nexts.add(next);
            distances.add(distance);
        }
    }
}

import java.util.*;
import java.util.function.Consumer;

public class Main {
    private static final Scanner scanner = new Scanner(System.in);
    private static final Consumer<List<String>> consumer = solve();

    public static void main(String[] args) {
        consumer.accept(readInput());
    }

    private static List<String> readInput() {
        final List<String> lineList = new ArrayList<>();
        while (scanner.hasNextLine()) {
            lineList.add(scanner.nextLine());
        }
        return lineList;
    }

    static Consumer<List<String>> solve() {
        return args -> {
            int N = Integer.parseInt(args.get(0));
            List<List<Edge>> edges = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                edges.add(new ArrayList<>());
            }
            for (int i = 0; i < N - 1; i++) {
                int[] e = Arrays.stream(args.get(1 + i).split(" ")).mapToInt(Integer::parseInt).toArray();
                edges.get(e[0] - 1).add(new Edge(e[0] - 1, e[1] - 1, e[2]));
                edges.get(e[1] - 1).add(new Edge(e[1] - 1, e[0] - 1, e[2]));
            }
            int via = Integer.parseInt(args.get(N).split(" ")[1]) - 1;
            for (int i = N + 1; i < args.size(); i++) {
                int[] q = Arrays.stream(args.get(i).split(" ")).mapToInt(Integer::parseInt).toArray();
                int from = q[0] - 1;
                int to = q[1] - 1;
                long first = getDist(from, via, edges, new HashSet<>());
                long second = getDist(via, to, edges, new HashSet<>());
                System.out.println(first + second);
            }
            System.out.println();
        };
    }

    static long getDist(int s, int d, List<List<Edge>> es, Set<Integer> used) {
        used.add(s);
        if (s == d) {
            return 0;
        }
        long min = Long.MAX_VALUE / 2;
        for (Edge next : es.get(s)) {
            if (!used.contains(next.to)) {
                min = Math.min(min, getDist(next.to, d, es, used) + next.cost);
            }
        }
        return min;
    }

    static class Edge {
        int from;
        int to;
        long cost;

        public Edge(int from, int to, long cost) {
            this.from = from;
            this.to = to;
            this.cost = cost;
        }
    }

}

