class Tree {
	int n;
	Edges[] es;
	long[] dsts;

	Tree(int n) {
		this.n = n;
		es = new Edges[n];
		for (int i = 0; i < n; i++) {
			es[i] = new Edges();
		}
		dsts = new long[n];
	}

	void addEdge(int a, int b, long c) {
		es[a].e.add(new Edge(b, c));
		es[b].e.add(new Edge(a, c));
	}

	void dfs(int st) {
		for (int i = 0; i < n; i++) {
			dsts[i] = -1;
		}
		dsts[st] = 0;
		dfs2(st);
	}

	private void dfs2(int a) {
		for (Edge e : es[a].e) {
			int to = e.to;
			long cc = dsts[a] + e.c;
			if (dsts[to] == -1 || cc < dsts[to]) {
				dsts[to] = cc;
				dfs2(to);
			}
		}
	}
}

