import java.rmi.server.ExportException;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Main m = new Main();
        m.solve();
    }
    private void solve() throws Exception {
        FastScan scan = new FastScan(System.in);
        int N = scan.scanInt();
        List<Path>[] graph = new List[N];
        for (int i = 0; i < N; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int i = 0; i < N - 1; i++) {
            int a = scan.scanInt()-1;
            int b = scan.scanInt()-1;
            long c = scan.scanLong();
            Path p1 = new Path(b, c);
            graph[a].add(p1);
            Path p2 = new Path(a, c);
            graph[b].add(p2);
        }
        int Q = scan.scanInt();
        int K = scan.scanInt()-1;
        Queue<Integer> queue = new ArrayDeque<>();
        long[] distances = new long[N];
        boolean[] visited = new boolean[N];
        Arrays.fill(distances, Long.MAX_VALUE);
        distances[K] = 0;
        queue.add(K);
        while(!queue.isEmpty()) {
            int current = queue.poll();
            visited[current] = true;
            List<Path> neighbors = graph[current];
            for (Path p : neighbors) {
                if (visited[p.to]) {
                    continue;
                }
                distances[p.to] = distances[current] + p.cost;
                queue.add(p.to);
            }
        }
        for (int i = 0; i < Q; i++) {
            int from = scan.scanInt() - 1;
            int to = scan.scanInt() - 1;
            System.out.println(distances[from] + distances[to]);
        }
    }

    class Path {
        int to;
        long cost;
        Path(int to, long cost) {
            this.to = to;
            this.cost = cost;
        }
    }
    class FastScan {
        BufferedReader br;
        StringTokenizer st;
        FastScan(InputStream is) {
            InputStreamReader isr = new InputStreamReader(is);
            this.br = new BufferedReader(isr);
        }
        String next() throws IOException {
            while (this.st == null || !this.st.hasMoreTokens()) {
                this.st = new StringTokenizer(br.readLine().trim());
            }
            return st.nextToken();
        }
        long scanLong() throws IOException {
            return Long.parseLong(this.next());
        }
        int scanInt() throws IOException {
            return Integer.parseInt(this.next());
        }
        double scanDouble() throws IOException {
            return Double.parseDouble(this.next());
        }
        char scanCharacter() throws IOException {
            return this.next().charAt(0);
        }
        String nextLine() throws IOException {
            return br.readLine().trim();
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Scanner;

class Main{
	static	ArrayList<HashMap<Integer, Integer>> graph ;
	static long ans = 100000000000L;
	static long first = 100000000000L;
	static long second = 100000000000L;
	static boolean[] used;



	public static void main(String[] args) {


		Scanner sc = new Scanner(System.in);			//文字の入力
		int n = sc.nextInt();

		used = new boolean[n+1];
		graph =new ArrayList<HashMap<Integer,Integer>>();				//arraylistの番号は始点



		for(int i = 0; i <= n;i++){

			HashMap<Integer, Integer> zero = new HashMap<Integer,Integer>();
			zero.put(0, 0);

			graph.add(i, zero);					//getで始点を指定、putで<隣接点、距離>を入れていく
		}

		for(int i = 0;i < n-1;i++){
			int a = sc.nextInt();			
			int b = sc.nextInt();
			int c = sc.nextInt();

			//getで始点を指定、putで<隣接点、距離>を入れていく

			graph.get(a).put(b, c);					//getで始点を指定、putで<隣接点、距離>を入れていく
			graph.get(b).put(a, c);					//getで始点を指定、putで<隣接点、距離>を入れていく


		}







		int q = sc.nextInt();				//問題数
		int k = sc.nextInt();				//通らなきゃいけない場所

		for(int i = 0;i <q;i++){
			ans = 100000000000L;


			int x = sc.nextInt();			//始点
			int y = sc.nextInt();			//終点
			used[x] = true;
			used[0] = true;
			dfs(x,k,0);
			first = ans;

			Arrays.fill(used, false);    	 	//リセット

			ans = 100000000000L;
			used[k] = true;
			used[0] = true;

			dfs(k,y,0);
			first +=  ans;

			Arrays.fill(used, false);    	 	//リセット
			System.out.println(first);
		}



	}

	static void dfs(int p,int g,long sum){



		if(p == g){
			ans = Math.min(ans, sum);

			return ;
		}

		for(int i:graph.get(p).keySet()){
			if(!(used[i])){
				used[i] = true;
				dfs(i, g , sum + graph.get(p).get(i));
			}
		}

		return ;


	}


}

