		for(Edge i:list[now]){
			if(i.to!=front){
				dfs(i.to,i.cost+cost,now);
			}
		}
	}

	static class Edge{
		int to;
		long cost;
		public Edge(int to,long cost){
			this.to=to;
			this.cost=cost;
		}
	}
}

