		if (costs[idx] == -1) {
			costs[idx] = total;
			for (Route r : lists[idx]) {
				setCost(total + r.cost, r.point);
			}
		}
	}

	static class Route {
		public int point;
		public long cost;

		public Route(int point, long cost) {
			this.point = point;
			this.cost = cost;
		}
	}

}

