    private static String solve(Scanner scanner) {
        int N = Integer.parseInt(scanner.nextLine());
        Map<Integer, Map<Integer, Integer>> tree = new HashMap<>();

        for (int i = 0; i < N - 1; i ++) {
            String[] split = scanner.nextLine().split(" ");
            int a = Integer.parseInt(split[0]);
            int b = Integer.parseInt(split[1]);
            int c = Integer.parseInt(split[2]);

            put(tree, a, b, c);
            put(tree, b, a, c);
        }

        String[] split = scanner.nextLine().split(" ");
        int Q = Integer.parseInt(split[0]);
        int K = Integer.parseInt(split[1]);

        tree.get(K).put(K, 0);

        Map<Integer, Long> distance = new HashMap<>();
        fillDistance(0, K, tree, distance);

        List<String> answers = new LinkedList<>();
        for (int i = 0; i < Q; i ++) {
            split = scanner.nextLine().split(" ");

            int x = Integer.parseInt(split[0]);
            int y = Integer.parseInt(split[1]);

            long answer = distance.get(x) + distance.get(y);
            answers.add(String.valueOf(answer));
        }

        return String.join("\n", answers);
    }

    private static void fillDistance(long currentDistance,
                                     int node,
                                     Map<Integer, Map<Integer, Integer>> tree,
                                     Map<Integer, Long> distance) {
        if (distance.keySet().contains(node)) return;

        distance.put(node, currentDistance);

        Map<Integer, Integer> innerMap = tree.get(node);
        for (Integer nextNode: innerMap.keySet()) {
            fillDistance(currentDistance + (long) innerMap.get(nextNode), nextNode, tree, distance);
        }
    }

    private static void put(Map<Integer, Map<Integer, Integer>> map, int a, int b, int c) {
        Map<Integer, Integer> innerMap = map.getOrDefault(a, new HashMap<>());
        innerMap.put(b, c);
        map.put(a, innerMap);
    }
}

