public void solve() {
	int numNode = ni();
	int numEdge = numNode - 1;
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = nl();
		edges[i] = new Edge(a, b, c);
	}
	Graph g = new Graph(numNode, numEdge, edges, false);

	int q = ni();
	int kk = ni() - 1;
	long dist[] = bfs(g.nodes, 0);
	LCA lca = new LCA(numNode);
	lca.init(0, g.nodes);
	for(int i = 0; i < q; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		int root1 = lca.apply(a, kk);
		int root2 = lca.apply(kk, b);
		prtln(dist[a] + dist[b] + dist[kk] * 2 - dist[root1] - dist[root2]);
	}
	errprtln(dist);
}

long[] bfs(Node nodes[], int start) {
	long dist[] = new long[nodes.length];
	Arrays.fill(dist, INF);

	Deque<Integer> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start] = 0;
	while(!s.isEmpty()) {
		int crt = s.removeFirst();
		for(Edge e : nodes[crt].edges) {
			if(isINF(dist[e.target])) {
				dist[e.target] = dist[e.source] + e.cost;
				s.addLast(e.target);
			}
		}
	}

	return dist;
}

class LCA {
	int numNode;
	int log;
	int[][] parent;
	int[] depth;

	public LCA(int numNode) {
		this.numNode = numNode;
		this.log = Integer.numberOfTrailingZeros(Integer.highestOneBit(numNode - 1)) + 1;
		this.parent = new int[log][numNode];
		this.depth = new int[numNode];
	}

	void init(int root, Node nodes[]) { // O(VlogV)
		bfs(nodes, root);
		parent[0][root] = -1;

		for(int k = 0; k + 1 < log; k ++) {
			for(int v = 0; v < numNode; v ++) {
				if(parent[k][v] < 0) {
					parent[k + 1][v] = -1;
				}else {
					parent[k + 1][v] = parent[k][parent[k][v]];
				}
			}
		}
	}

	void bfs(Node nodes[], int start) {
		Arrays.fill(depth, -1);
		depth[start] = 0;

		Deque<Integer> s = new ArrayDeque<>();
		s.addLast(start);
		depth[start] = 0;
		while(!s.isEmpty()) {
			int crt = s.removeFirst();
			for(Edge e : nodes[crt].edges) {
				if(depth[e.target] < 0) {
					depth[e.target] = depth[e.source] + 1;
					parent[0][e.target] = e.source;
					s.addLast(e.target);
				}
			}
		}
	}

	int apply(int u, int v) { // O(logV)
		if(depth[u] > depth[v]) {
			int t = u;
			u = v;
			v = t;
		}

		for(int k = 0; k < log; k ++) {
			if(isFlagged(depth[v] - depth[u],k)) {
				v = parent[k][v];
			}
		}
		if(u == v) { return u; }

		for (int k = log - 1; k >= 0; k --) {
			if(parent[k][u] != parent[k][v]) {
				u = parent[k][u];
				v = parent[k][v];
			}
		}
		return parent[0][u];
	}
}

	}
}

import java.util.*;

public class Main {
    @lombok.ToString
    private class Edge {
        int to;
        long cost;

        public Edge(int to, long cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    @lombok.ToString
    private class Node {
        long minCost = Long.MAX_VALUE;
        List<Edge> childs = new ArrayList<>();
        boolean isFix = false;

        public void addEdge(Edge e) {
            childs.add(e);
        }

        public void fixed() {
            isFix = true;
        }
    }

    public void main(Scanner sc) {
        int n = sc.nextInt();
        Node nodes[] = new Node[n + 1];
        for (int i = 1; i <= n; i++) {
            nodes[i] = new Node();
        }
        for (int i = 0; i < n - 1; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            long c = sc.nextLong();
            nodes[a].addEdge(new Edge(b, c));
            nodes[b].addEdge(new Edge(a, c));
        }

        int q = sc.nextInt();
        int k = sc.nextInt();
        dijkstra(k, n, nodes);

        for (int i = 0; i < q; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            System.out.println(nodes[x].minCost + nodes[y].minCost);
        }
    }

    public void dijkstra(int start, int n, Node nodes[]) {
        nodes[start].minCost = 0;

        Queue<Node> queue = new PriorityQueue<>((n1, n2) -> Long.compare(n1.minCost, n2.minCost));
        queue.add(nodes[start]);
        while (!queue.isEmpty()) {
            Node src = queue.poll();
            src.fixed();
            for (Edge e : src.childs) {
                Node dst = nodes[e.to];
                if (!dst.isFix) {
                    dst.minCost = Math.min(dst.minCost, src.minCost + e.cost);
                    queue.add(dst);
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        new Main().main(sc);
        sc.close();
    }
}

