            int b = Integer.parseInt(str[1]) - 1;
            long c = Long.parseLong(str[2]);

            edge ed = new edge(b, c);
            edges[a].add(ed);
            ed = new edge(a, c);
            edges[b].add(ed);
        }

        String[] str = br.readLine().split(" ");
        int q = Integer.parseInt(str[0]);
        int k = Integer.parseInt(str[1]) - 1;
