	private void calc(int from) {
		for (int i = 0; i < nodes[from].size(); i++) {
			int index = nodes[from].getTo(i);
			if (costs[index] != -1) continue;

			costs[index] = costs[from] + nodes[from].getValue(i);
			calc(index);
		}
	}
