public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        LightScanner in = new LightScanner(inputStream);
        LightWriter out = new LightWriter(outputStream);
        DTransitTreePath solver = new DTransitTreePath();
        solver.solve(1, in, out);
        out.close();
    }

    static class DTransitTreePath {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            // out.setBoolLabel(LightWriter.BoolLabel.YES_NO_FIRST_UP);
            int n = in.ints();
            DTransitTreePath.Node[] nodes = new DTransitTreePath.Node[n];
            for (int i = 0; i < n; i++) {
                nodes[i] = new DTransitTreePath.Node();
            }
            for (int i = 1; i < n; i++) {
                int a = in.ints() - 1, b = in.ints() - 1;
                long c = in.longs();
                nodes[a].neg.add(nodes[b]);
                nodes[a].dis.add(c);
                nodes[b].neg.add(nodes[a]);
                nodes[b].dis.add(c);
            }
            int q = in.ints(), k = in.ints() - 1;
            nodes[k].dfs(null, 0);
            for (int i = 0; i < q; i++) {
                int x = in.ints() - 1, y = in.ints() - 1;
                out.ans(nodes[x].depth + nodes[y].depth).ln();
            }
        }

        private static class Node {
            private ArrayList<DTransitTreePath.Node> neg = new ArrayList<>();
            private ArrayList<Long> dis = new ArrayList<>();
            DTransitTreePath.Node parent;
            long depth;

            private void dfs(DTransitTreePath.Node parent, long depth) {
                this.parent = parent;
                this.depth = depth;
                for (int i = 0; i < neg.size(); i++) {
                    if (neg.get(i) != parent) {
                        neg.get(i).dfs(this, depth + dis.get(i));
                    }
                }
            }

        }

    }

    static class LightScanner {
        private BufferedReader reader = null;
        private StringTokenizer tokenizer = null;

        public LightScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        public String string() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int ints() {
            return Integer.parseInt(string());
        }

        public long longs() {
            return Long.parseLong(string());
        }

    }

    static class LightWriter implements AutoCloseable {
        private final Writer out;
        private boolean autoflush = false;
        private boolean breaked = true;

        public LightWriter(Writer out) {
            this.out = out;
        }

        public LightWriter(OutputStream out) {
            this(new BufferedWriter(new OutputStreamWriter(out, Charset.defaultCharset())));
        }

        public LightWriter print(char c) {
            try {
                out.write(c);
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter print(String s) {
            try {
                out.write(s, 0, s.length());
                breaked = false;
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return this;
        }

        public LightWriter ans(String s) {
            if (!breaked) {
                print(' ');
            }
            return print(s);
        }

        public LightWriter ans(long l) {
            return ans(Long.toString(l));
        }

        public LightWriter ln() {
            print(System.lineSeparator());
            breaked = true;
            if (autoflush) {
                try {
                    out.flush();
                } catch (IOException ex) {
                    throw new UncheckedIOException(ex);
                }
            }
            return this;
        }

        public void close() {
            try {
                out.close();
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
        }

    }
}

import java.util.*;

public class Main {

	class State implements Comparable<State>{
		int now;
		long cost;
		public State(int now, long cost) {
			this.now = now;
			this.cost = cost;
		}
		public int compareTo(State o) {
			if(this.cost > o.cost) return 1;
			if(this.cost < o.cost) return -1;
			return 0;
		}
	}

	private void doit(){
		Scanner sc = new Scanner(System.in);
		while(sc.hasNext()){
			int n = sc.nextInt();
			long [][] pass = new long[n][n];
			for(int i = 0; i < n;i++){
				Arrays.fill(pass[i], Long.MAX_VALUE);
			}

			for(int i =0; i < n-1; i++){
				int a = sc.nextInt() - 1;
				int b = sc.nextInt() - 1; 
				int c = sc.nextInt();
				pass[a][b] = c;
				pass[b][a] = c;
			}
			int q = sc.nextInt();
			int start = sc.nextInt() -1;

			PriorityQueue<State> open = new PriorityQueue<>();
			open.add(new State(start, 0));
			long [] close = new long[n];
			Arrays.fill(close, Long.MAX_VALUE);

			boolean [] used = new boolean[n];
			used[start] = true;
			int count = 1;

			while(!open.isEmpty()){
				State current = open.poll();
				if(!used[current.now]){
					used[current.now] = true;
					count++;
					if(count == n){
						break;
					}
				}

				for(int i = 0; i < n;i++){
					if(current.now == i)continue;
					if(pass[current.now][i] == Long.MAX_VALUE ) continue;
					long nextcost = current.cost + pass[current.now][i];
					if(close[i] < nextcost) continue;
					close[i] = nextcost;
					open.add(new State(i, nextcost));
				}
			}

			StringBuilder sb = new StringBuilder();
			for(int i = 0; i < q; i++){
				int x = sc.nextInt() - 1;
				int y = sc.nextInt() - 1;
				long res = close[x] + close[y];
				sb.append(res+"\n");
			}
			System.out.print(sb.toString());
		}

	}


	private void debug(Object... o) {
		System.out.println("debug = " + Arrays.deepToString(o));
	}

	public static void main(String[] args) {
		new Main().doit();
	}

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    int N;
    Scanner scanner = new Scanner(System.in);
    Node[] nodes;

    public static void main(String[] args) {
        new Main().compute();
    }

    void compute() {
        N = scanner.nextInt();
        nodes = new Node[N];
        for (int i = 0; i < N; i++) {
            nodes[i] = new Node();
        }
        for (int i = 0; i < N - 1; i++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            long c = scanner.nextLong();
            nodes[a - 1].add(nodes[b - 1], c);
            nodes[b - 1].add(nodes[a - 1], c);
        }
        int Q = scanner.nextInt();
        int K = scanner.nextInt();
        for (int i = 0; i < Q; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            System.out.println(cost(nodes[x - 1], nodes[K - 1], null) + cost(nodes[K - 1], nodes[y - 1], null));
        }

    }

    long cost(Node x, Node y, Node prev) {
        if (x == y) {
            return 0;
        }
        for (int i = 0; i < x.nexts.size(); i++) {
            Node next = x.nexts.get(i);
            if (prev == next) {
                continue;
            }
            long nextCost = cost(next, y, x);
            if (nextCost != -1) {
                return nextCost + x.distances.get(i);
            }
        }
        return -1;
    }

    class Node {

        List<Node> nexts = new ArrayList<>();
        List<Long> distances = new ArrayList<>();

        void add(Node next, long distance) {
            nexts.add(next);
            distances.add(distance);
        }
    }
}

