		}
		pw.close();
	}

	List<No>[] node;
	long[] d;
	void func(int pre, int now) {
		for (No t : node[now]) {
			if (pre == t.f) continue;
			d[t.f] = d[now] + t.g;
			func(now, t.f);
		}
	}

	class No {
		int f;
		int g;
		No(int a, int b) {
			f = a;
			g = b;
		}
