public class Main {
	private Scanner sc;

	private int n;
	private int[][] map;

	private long[] node;

	public static void main(String[] args) {
		new Main();
	}

	public Main() {
		sc = new Scanner(System.in);

		n = sc.nextInt();

		map = new int[n + 1][n + 1];
		for (int i = 0; i < map.length; i++) {
			for (int j = 0; j < map.length; j++) {
				map[i][j] = 0;
			}
		}

		for (int i = 0; i < (n - 1); i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();
			int val = sc.nextInt();
			map[from][to] = val;
			map[to][from] = val;
		}

		int q = sc.nextInt();
		int k = sc.nextInt();

		node = new long[n + 1];
		for (int i = 0; i < node.length; i++) {
			node[i] = -1;
		}
		node[k] = 0;
		calc(k);

		for (int i = 0; i < q; i++) {
			int from = sc.nextInt();
			int to = sc.nextInt();

			System.out.println(node[from] + node[to]);
		}
	}

	private void calc(int from) {
		for (int i = 1; i < (n + 1); i++) {
			if ((map[from][i] == 0) || node[i] != -1) continue;

			node[i] = node[from] + map[from][i];
			calc(i);
		}
	}
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main main = new Main();
		main.run();
	}

	class Edge{
		int to;
		long cost;
		Edge(int to, long cost){
			this.to=to;
			this.cost=cost;
		}
	}
	public void run() {
		Scanner sc = new Scanner(System.in);
		ArrayList<ArrayList<Edge>> g = new ArrayList<ArrayList<Edge>>();
		int n = sc.nextInt();
		for(int i=0; i<n; i++) {
			g.add(new ArrayList<Edge>());
		}
		for(int i=0; i<n-1; i++) {
			int a=sc.nextInt(); a--;
			int b=sc.nextInt(); b--;
			long c=sc.nextLong();
			g.get(a).add(new Edge(b, c));
			g.get(b).add(new Edge(a, c));
		}

		long d[] = new long[n];
		boolean used[] = new boolean[n];
		int q = sc.nextInt();
		int k = sc.nextInt(); k--;

		ArrayDeque<Integer> stack = new ArrayDeque<Integer>();
		stack.push(k);
		used[k]=true;
		d[k]=0;
		while(!stack.isEmpty()) {
			int u = stack.pop();
			for(Edge e : g.get(u)) {
				if(used[e.to]) continue;
				d[e.to]=d[u] + e.cost;
				used[e.to]=true;
				stack.push(e.to);
			}
		}

		for(int i=0; i<q; i++) {
			int x = sc.nextInt();x--;
			int y = sc.nextInt();y--;
			System.out.println(d[x]+d[y]);
		}
		sc.close();
	}

}

