//        String[] str = br.readLine().split(" ");

        ArrayList<edge>[] es  = new ArrayList[n];
        for(int i=0; i<n; i++) es[i] = (new ArrayList<>());

        for (int i=0; i<n-1; i++) {
            String[] str = br.readLine().split(" ");
            edge ed_f = new edge();
            int a = Integer.parseInt(str[0]) - 1;
