        depth = new long[n];
        v = new ArrayList[n];
        visited = new boolean[n];
        for (int i = 0; i < n; i++) v[i] = new ArrayList<>();
        for (int i = 0; i < n - 1; i++) {
            int x = in.nextInt() - 1;
            int y = in.nextInt() - 1;
