            v[x].add(new Pair(y, w));
            v[y].add(new Pair(x, w));
        }
        int q = in.nextInt();
        int k = in.nextInt() - 1;
        dfs(k, -1, 0);
        for (int i = 0; i < q; i++) {
            int x = in.nextInt() - 1;
            int y = in.nextInt() - 1;
            out.println(depth[x] + depth[y]);
        }
        out.close();
    }

    private static void dfs(int source, int parent, long d) {
        visited[source] = true;
        depth[source] = d;
        for (Pair a : v[source]) {
            if (!visited[a.to]) {
                dfs(a.to, source, d + a.w);
            }
        }
    }

