        Map<Cost,Cost> cmap = new HashMap<>();
        PathMap pmap = new PathMap();

        for(int i = 0; i < N-1; i++){
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            long c = scanner.nextInt();
            Cost cost = new Cost(a,b,c);
            cmap.put(cost,cost);
            pmap.put(cost);
        }
        int Q = scanner.nextInt();
