    void step(int curr ,long[] distance, HashMap<Integer,HashMap<Integer,Integer>> cost, int prev){
        for(Integer to : cost.get(curr).keySet()){
            if(to == prev) continue;
            distance[to] = distance[curr] + cost.get(curr).get(to);
            step(to, distance, cost, curr);
        }
    }

