class Sieve {
    private int n;
    private int[] f;
    public ArrayList<Integer> primes = new ArrayList<>();
    public Sieve(int N){
        n = N;
        f = new int[n+1];
        f[0] = -1; // 0 is not prime
        f[1] = -1; // 1 is not prime
        for(int i = 2; i <= N; i++){
            if(f[i]!=0) continue;
            primes.add(i);
            f[i] = i;
            for(int j = i+i; j<=n; j+=i){
                if(f[j]==0) f[j] = i;
            }
        }
    }
    public boolean isPrime(int i){
        return (f[i]==i);
    } 
    public ArrayList<Integer> factorList(int i){
        ArrayList<Integer> res = new ArrayList<>();
        while(i != 1){
            res.add(f[i]);
            i /= f[i];
        }
        return res;
    }
    public HashMap<Integer, Integer> factorCount(int i){
        HashMap<Integer, Integer> res = new HashMap<>();
        while(i != 1){
            res.putIfAbsent(f[i], 0);
            res.put(f[i], res.get(f[i]) + 1);
            i /= f[i];
        }
        return res;
    }
}


class Node{
    int id;             
    int past;           
    List<Edge> edges;   

    Node(int id, int past){
        this.id = id;
        this.past = past;
        this.edges = new ArrayList<>();
    }
    void addEdge(Edge edge){
        edges.add(edge);
    }

    public boolean equals(Object obj){
        if(obj instanceof Node){
            Node node = (Node)obj;
            return this.id == node.id;
        } 
        return false;
    }
    public int hashCode(){
        return id;
    }
    public String toString(){
        return "[id:" + id + " past: " + past + "]";
    }
}


class Edge implements Comparable<Edge>{
    int from;       
    int to;        
    long cost;       

    Edge(int from, int to, long cost){
        this.from = from;
        this.to = to;
        this.cost = cost;
    }
    public int compareTo(Edge edge){
        return Long.compare(this.cost, edge.cost);
    }

    public String toString(){
        return "[" + from + " to " + to + " cost:" + cost + "]";
    }
}

class EdgeComparator implements Comparator<Edge>{
    @Override
    public int compare(Edge e1, Edge e2){
        long cost1 = e1.cost;
        long cost2 = e2.cost;
        if(cost1 < cost2){
            return -1;
        } else if(cost1 > cost2){
            return 1;
        } else {
            return 0;
        }
    }
}
// Union-Find
class UnionFind{
    private int[] d;
    public UnionFind(int num){
        d = new int[num];
        for(int i=0; i<num; i++){
            d[i] = -1;
        }
    }
    public void union(int a, int b){
        a = find(a);
        b = find(b);
        if(a == b){
            return;
        }
        if(-d[a] < -d[b]){
            int tmp = a;
            a = b;
            b = tmp;
        }
        d[a] += d[b];
        d[b] = a;
    }
    public int find(int a){
        if(d[a] < 0){
            return a;
        }else{
            d[a] = find(d[a]);
            return d[a];
        }
    }
    public int size(int a){
        return -d[find(a)];
    }
}


class Permutation {
