            to[(int)p].add(new long[]{q, dis});
            to[(int)q].add(new long[]{p, dis});
        }

        // 点kから各点までの距離を計算
        int query = sc.nextInt();
        int k = sc.nextInt() - 1;
        long[] distK = calcDist(k);

        // p→k→qの最短距離を出力
        while (query-- > 0) {
