	static void dfs(int s, long add) {
		dist[s] = add;

		for (int i = 0; i < edge.get(s).size(); i++) {
			if (!used[edge.get(s).get(i).to]) {
				used[edge.get(s).get(i).to] = true;
				dfs(edge.get(s).get(i).to, add + edge.get(s).get(i).cost);
				used[edge.get(s).get(i).to] = false;
			}
		}
