public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TransitTreePath solver = new TransitTreePath();
        solver.solve(1, in, out);
        out.close();
    }

    static class TransitTreePath {
        private ArrayList<ArrayList<Edge>> tree = new ArrayList<>();
        private long[] dist;
        private boolean[] seen;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            dist = new long[n + 1];
            seen = new boolean[n + 1];
            for (int i = 0; i <= n; i++) {
                tree.add(new ArrayList<>());
            }
            for (int i = 0; i < n - 1; i++) {
                int a = in.nextInt();
                int b = in.nextInt();
                int c = in.nextInt();
                tree.get(a).add(new Edge() {
                    {
                        to = b;
                        length = c;
                    }
                });
                tree.get(b).add(new Edge() {
                    {
                        to = a;
                        length = c;
                    }
                });
            }
            int q = in.nextInt();
            int k = in.nextInt();
            dfs(k, 0);
            for (int i = 0; i < q; i++) {
                int x = in.nextInt();
                int y = in.nextInt();
                out.println(dist[x] + dist[y]);
            }
        }

        private void dfs(int start, long d) {
            if (seen[start])
                return;
            dist[start] = d;
            seen[start] = true;
            for (int i = 0; i < tree.get(start).size(); i++) {
                Edge e = tree.get(start).get(i);
                dfs(e.to, d + e.length);
            }
        }

        class Edge {
            int to;
            int length;

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
import java.util.*;
public class Main{
	public static void main(String[] args)throws Throwable {
		MyScanner sc=new MyScanner();
		PrintWriter pw=new PrintWriter(System.out);

		n=sc.nextInt();
		adj=new ArrayList [n];
		for(int i=0;i<n;i++)
			adj[i]=new ArrayList<Integer>();
		int [] x=new int [n-1];
		int [] y=new int [n-1];
		int [] z=new int [n-1];
		for(int i=0;i<n-1;i++){
			x[i]=sc.nextInt()-1;
			y[i]=sc.nextInt()-1;
			z[i]=sc.nextInt();
			adj[x[i]].add(y[i]);
			adj[y[i]].add(x[i]);
		}
		preProcessing();
		for(int i=0;i<n-1;i++)
			if(level[x[i]]>level[y[i]])
				cost[x[i]]=z[i];
			else
				cost[y[i]]=z[i];
		dfs2(0);
		int q=sc.nextInt();
		k=sc.nextInt()-1;
		while(q-->0){
			int u=sc.nextInt()-1;
			int v=sc.nextInt()-1;
			pw.println(min_dis(u, v));
		}

		pw.flush();
		pw.close();
	}

	static long min_dis(int u,int v){
		int l=query(u, v);
		int uk=query(u, k);
		int vk=query(v, k);
		int lk=query(l, k);
		if(lk==l && (uk==k || vk==k))
			return path_len(u, v, l);
		else
			return path_len(u, k, uk)+path_len(v, k, vk);
	}

	static long path_len(int u,int v,int l){
		return cost[u]+cost[v]-2*cost[l];
	}

	static int n,k;
	static int [][] ansector;
	static int [] parent,level;
	static long [] cost;
	static ArrayList<Integer> [] adj;

	static void preProcessing(){
		parent=new int [n];
		level=new int [n];
		cost=new long [n];
		parent[0]=-1;
		dfs(0, 0);
		int log=(int)Math.ceil(Math.log(n)/Math.log(2));
		ansector=new int [n][log];
		for(int [] x : ansector)
			Arrays.fill(x, -1);
		for(int i=0;i<n;i++)
			ansector[i][0]=parent[i];				
		for(int j=1;(1<<j)<n;j++)
			for(int i=0;i<n;i++)
				if(ansector[i][j-1]!=-1)
					ansector[i][j]=ansector[ansector[i][j-1]][j-1];
	}

	public static void dfs(int u,int h){
		level[u]=h;
		for(int v : adj[u])
			if(v!=parent[u]){
				parent[v]=u;
				dfs(v, h+1);
			}
	}

	static void dfs2(int u){
		for(int v : adj[u])
			if(v!=parent[u]){
				cost[v]+=cost[u];
				dfs2(v);
			}
	}

	public static int query(int u,int v){
		if(level[u]<level[v]){
			int tmp=u;
			u=v;
			v=tmp;
		}
		int log=1;
		for(log=1;(1<<log)<=level[u];log++);
		log--;

		for(int i=log;i>=0;i--)
			if(level[u]-(1<<i)>=level[v])
				u=ansector[u][i];

		if(u==v)
			return u;

		for(int i=log;i>=0;i--)
			if(ansector[u][i]!=-1 && ansector[u][i]!=ansector[v][i]){
				u=ansector[u][i];
				v=ansector[v][i];
			}
		return parent[u];
	}

	static class MyScanner {
		BufferedReader br;
		StringTokenizer st;
		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}
		String next() {while (st == null || !st.hasMoreElements()) {
			try {st = new StringTokenizer(br.readLine());}
			catch (IOException e) {e.printStackTrace();}}
		return st.nextToken();}
		int nextInt() {return Integer.parseInt(next());}
		long nextLong() {return Long.parseLong(next());}
		double nextDouble() {return Double.parseDouble(next());}
		String nextLine(){String str = "";
		try {str = br.readLine();}
		catch (IOException e) {e.printStackTrace();}
		return str;}
	}
}

import java.util.ArrayList;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main main = new Main();
		main.run();
	}

	class Edge{
		int to;
		long cost;
		Edge(int to, long cost){
			this.to=to;
			this.cost=cost;
		}
	}
	public void run() {
		Scanner sc = new Scanner(System.in);
		ArrayList<ArrayList<Edge>> g = new ArrayList<ArrayList<Edge>>();
		int n = sc.nextInt();
		long INF = 10000000000L;
		for(int i=0; i<n; i++) {
			g.add(new ArrayList<Edge>());
		}
		for(int i=0; i<n-1; i++) {
			int a=sc.nextInt(); a--;
			int b=sc.nextInt(); b--;
			long c=sc.nextLong();
			g.get(a).add(new Edge(b, c));
			g.get(b).add(new Edge(a, c));
		}

		long d[] = new long[n];
		boolean used[] = new boolean[n];
		int q = sc.nextInt();
		int k = sc.nextInt(); k--;
		for(int i=0; i<n; i++) {
			d[i]=INF;
		}
		d[k]=0;


		while(true){
			long minv = INF;
			int u = -1;
			for(int i=0; i<n; i++) {
				if(used[i]) continue;
				if(d[i] == INF) continue;
				if(d[i] < minv) {
					minv = d[i];
					u = i;
				}
			}
			if(u == -1) break;
			used[u]=true;
			for(Edge e : g.get(u)) {
				if(used[e.to]) continue;
				if(d[e.to] > d[u] + e.cost) {
					d[e.to] = d[u] + e.cost;
				}
			}
		}

		for(int i=0; i<q; i++) {
			int x = sc.nextInt(); x--;
			int y = sc.nextInt(); y--;
			System.out.println(d[x] + d[y]);
		}
		sc.close();
	}

}

