    public static long[] solve(Node nodes[], long dist[], long stCost, int st, int from){
        dist[st]=stCost;
        for(Edge e:nodes[st].edges){
            if(e.id!=from){
                dist[e.id]=dist[st]+e.cost;
                dist=solve(nodes, dist, dist[e.id], e.id, st);
            }
        }
        return dist;
    }

    static class Node{
        int id;
        ArrayList<Edge> edges;
        public Node(int id){
