        for(int i = 0; i < n; i++){
            for(int j = 0; j < n; j++){
                if(i==j) a[i][j] = 0;
                else a[i][j] = Long.MAX_VALUE/10;
            }
        }
        for(int i = 0; i < n-1; i++){
            int f = ni()-1;
            int t = ni()-1;
            long c = nl();
            a[f][t] = c;
            a[t][f] = c;
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
