public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		Dijkstra dj = new Dijkstra(n);

		for (int k = 0; k < n - 1; k++) {
			int i, j;
			i = sc.nextInt();
			j = sc.nextInt();

			dj.setE(i, j, sc.nextInt());
		}

		int q = sc.nextInt();
		int k = sc.nextInt();

		dj.dijkstra(k);
		long D[] = new long[n+1];
		for (int i = 0; i <= n; i++) {
			D[i] = dj.D[i];
		}

		for (int i = 0; i < q; i++) {
			System.out.println(dj.D[sc.nextInt()] + D[sc.nextInt()]);
		}

	}

	static class Dijkstra {
		DijList[] e;
		boolean[] S;
		long D[];
		int n;
		int s;

		Dijkstra(int n) {
			this.n = n;
			e = new DijList[n+1];
			S = new boolean[n+1];
			D = new long[n+1];
			for (int i = 0; i <= n; i++) {
				e[i] = new DijList(i, 0);
			}
		}

		void setE(int i, int j, int e) {
			this.e[i].setNext(new DijList(j, e));
			this.e[j].setNext(new DijList(i, e));
		}

		void dijkstra (int s) {
			this.s = s;
			for (int i = 1; i <= n; i++) {
				D[i] = Long.MAX_VALUE;
				S[i] = false;
			}
			D[s] = 0;
			for (int i = 1; i <= n; i++) {
				long min = Long.MAX_VALUE;
				int k = 0;
				for (int j = 1; j <= n; j++) {
					if (!S[j] && D[j] < min) {
						min = D[j];
						k = j;
					}
				}
				S[k] = true;
				DijList conec = e[k];
				DijList jud;
				for (int j = 1; j <= n; j++) {
					jud = conec.get(j);
					if (jud == null) continue;
					conec = jud;
					long temp = conec.w;
					if (temp != -1 && !S[j]) {
						long temp2 = D[k] + temp;
						D[j] = D[j] < temp2 ? D[j] : temp2;
					}
				}
			}
		}
	}

	static class DijList {
		DijList next;
		DijList back;
		int n;
		long w;

		public DijList(int n, long w) {
			this.n = n;
			this.w = w;
		}

		public void setNext(DijList next) {
			if (this.next == null) {
			       	this.next = next;
				next.back = this;
			} else {
				if (next.n > this.n) {
					this.next.setNext(next);
				} else {
					this.back.next = next;
					next.back = this.back;
					next.next = this;
					this.back = next;
				}	
			}
		}

		public DijList get(int n) {
			if (this.n == n) return this;
			if (this.next == null) return null;
			return this.next.get(n);
		}
	}
}

import java.util.*;
import java.util.function.Consumer;

public class Main {
    private static final Scanner scanner = new Scanner(System.in);
    private static final Consumer<List<String>> consumer = solve();

    public static void main(String[] args) {
        consumer.accept(readInput());
    }

    private static List<String> readInput() {
        final List<String> lineList = new ArrayList<>();
        while (scanner.hasNextLine()) {
            lineList.add(scanner.nextLine());
        }
        return lineList;
    }

    static Consumer<List<String>> solve() {
        return args -> {
            int N = Integer.parseInt(args.get(0));
            List<List<Edge>> edges = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                edges.add(new ArrayList<>());
            }
            for (int i = 0; i < N - 1; i++) {
                int[] e = Arrays.stream(args.get(1 + i).split(" ")).mapToInt(Integer::parseInt).toArray();
                edges.get(e[0] - 1).add(new Edge(e[1] - 1, e[2]));
                edges.get(e[1] - 1).add(new Edge(e[0] - 1, e[2]));
            }
            int via = Integer.parseInt(args.get(N).split(" ")[1]) - 1;
            dist = new long[N];
            getDist(via, 0, edges, new HashSet<>());
            for (int i = N + 1; i < args.size(); i++) {
                int[] q = Arrays.stream(args.get(i).split(" ")).mapToInt(Integer::parseInt).toArray();
                int from = q[0] - 1;
                int to = q[1] - 1;
                System.out.println(dist[from] + dist[to]);
            }
        };
    }

    static long[] dist;
    static void getDist(int s, long cost, List<List<Edge>> es, Set<Integer> used) {
        used.add(s);
        dist[s] = cost;
        for (Edge next : es.get(s)) {
            if (!used.contains(next.to)) {
                getDist(next.to, cost + (long) next.cost, es, used);
            }
        }
    }

    static class Edge {
        int to;
        int cost;

        public Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] a = new int[N - 1];
        int[] b = new int[N - 1];
        int[] c = new int[N - 1];
        for (int i = 0; i < N - 1; ++i) {
            a[i] = sc.nextInt() - 1;
            b[i] = sc.nextInt() - 1;
            c[i] = sc.nextInt();
        }
        int Q = sc.nextInt();
        int K = sc.nextInt() - 1;
        int[] x = new int[Q];
        int[] y = new int[Q];
        for (int i = 0; i < Q; ++i) {
            x[i] = sc.nextInt() - 1;
            y[i] = sc.nextInt() - 1;
        }

        System.out.println(solve(a, b, c, x, y, K));

        sc.close();
    }

    static String solve(int[] a, int[] b, int[] c, int[] x, int[] y, int K) {
        int N = a.length + 1;

        @SuppressWarnings("unchecked")
        List<Integer>[] edgeLists = new List[N];
        for (int i = 0; i < edgeLists.length; ++i) {
            edgeLists[i] = new ArrayList<>();
        }

        for (int i = 0; i < a.length; ++i) {
            edgeLists[a[i]].add(i);
            edgeLists[b[i]].add(i);
        }

        long[] distances = new long[N];
        Arrays.fill(distances, -1);
        search(distances, edgeLists, a, b, c, K, 0);

        return IntStream.range(0, x.length).mapToObj(i -> String.valueOf(distances[x[i]] + distances[y[i]]))
                .collect(Collectors.joining("\n"));
    }

    static void search(long[] distances, List<Integer>[] edgeLists, int[] a, int[] b, int[] c, int v, long distance) {
        distances[v] = distance;

        for (int edge : edgeLists[v]) {
            int adj = (a[edge] == v) ? b[edge] : a[edge];
            if (distances[adj] == -1) {
                search(distances, edgeLists, a, b, c, adj, distance + c[edge]);
            }
        }
    }
}

