  static class DTransitTreePath {

    public void solve(int testNumber, Scanner in, PrintWriter out) {
    /*
    無向グラフなのでx->k->yはk->x + k->yで出来るのでただの
    Dijkstra法貼るだけの問題
     */

      int vertexNum = in.nextInt();
      Graph g = new Graph(vertexNum);
      for (int i = 0; i < vertexNum - 1; i++) {
        int f = in.nextInt();
        int t = in.nextInt();
        int c = in.nextInt();
        g.addUndirectedEdge(--f, --t, c);
      }
      int q = in.nextInt();
      int k = in.nextInt();
      long[] costFromK = g.dijkstra(--k);
      for (int i = 0; i < q; i++) {
        int x = in.nextInt();
        int y = in.nextInt();
        out.println(costFromK[--x] + costFromK[--y]);
      }
    }

  }

  static class Vertex {

    private List<Edge> adj;

    public Vertex() {
      this.adj = new ArrayList<>();
    }

    public void addEdge(Edge e) {
      adj.add(e);
    }

    public List<Edge> getAdj() {
      return adj;
    }

    public int getSize() {
      return adj.size();
    }

  }

  static class Edge {

    int to;
    int cost = 1;

    public Edge(int to) {
      this.to = to;
    }

    public Edge(int to, int cost) {
      this.to = to;
      this.cost = cost;
    }

    public String toString() {
      return "to :" + to + ", cost :" + cost;
    }

  }

  static class Graph {

    private Vertex[] v;
    private int size;

    public Graph(int size) {
      this.size = size;
      v = new Vertex[this.size];
      for (int i = 0; i < this.size; i++) {
        v[i] = new Vertex();
      }
    }

    public void addUndirectedEdge(int from, int to, int cost) {
      v[from].addEdge(new Edge(to, cost));
      v[to].addEdge(new Edge(from, cost));
    }

    public long[] dijkstra(int from) {
      PriorityQueue<Pair<Long, Integer>> pq =
          new PriorityQueue<>(Comparator.comparing(x -> x.getX()));
      long[] d = new long[size];
      Arrays.fill(d, (long) 1e20);
      d[from] = 0;
      pq.add(new Pair<>((long) 0, from));
      while (!pq.isEmpty()) {
        Pair ip = pq.peek();
        pq.poll();
        long c = (long) ip.getX();
        int now = (int) ip.getY();
        if (d[now] < c) {
          continue;
        }
        for (int i = 0; i < v[now].getSize(); i++) {
          Edge e = v[now].getAdj().get(i);
          // System.out.println(e.toString());
          if (d[e.to] > d[now] + e.cost) {
            d[e.to] = d[now] + e.cost;
            Pair<Long, Integer> p = new Pair<>(d[e.to], e.to);
            pq.add(p);
            // System.out.println("d[" + e.to + "] update");
          }
        }
      }
      return d;
    }

  }

  static class Pair<T, U> {

    private T x;
    private U y;

    public Pair(T t, U u) {
      this.x = t;
      this.y = u;
    }

    public T getX() {
      return x;
    }

    public U getY() {
      return y;
    }

    public String toString() {
      return this.x.toString() + " " + this.y.toString();
    }

    public int hashCode() {
      return super.hashCode();
    }

  }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		try (Scanner sc = new Scanner(System.in)) {
			int n = sc.nextInt();
			int[][] map = new int[n][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < n; j++) {
					map[i][j] = (i == j) ? 0 : -1;
				}
			}

			for (int i = 0; i < n - 1; i++) {
				int a = sc.nextInt() - 1;
				int b = sc.nextInt() - 1;
				int c = sc.nextInt();
				map[a][b] = c;
				map[b][a] = c;
			}

			int q = sc.nextInt();
			int k = sc.nextInt() - 1;

			for (int i = 0; i < q; i++) {
				int x = sc.nextInt() - 1;
				int y = sc.nextInt() - 1;

				long[] distanceX = new long[n];
				long[] distanceY = new long[n];
				dijkstra(map, x, distanceX);
				dijkstra(map, y, distanceY);
				System.out.println(distanceX[k] + distanceY[k]);
			}
		}
	}

	public static void dijkstra(int[][] map, int src, long[] distance) {
		int nTown = distance.length;
		boolean[] fixed = new boolean[nTown];
		for (int i = 0; i < nTown; i++) {
			distance[i] = Long.MAX_VALUE;
			fixed[i] = false;
		}
		distance[src] = 0;
		while (true) {
			int marked = minIndex(distance, fixed);
			if (marked < 0)
				return;
			if (distance[marked] == Integer.MAX_VALUE)
				return;
			fixed[marked] = true;
			for (int j = 0; j < nTown; j++) {
				if (map[marked][j] > 0 && !fixed[j]) {
					long newDistance = distance[marked] + map[marked][j];
					if (newDistance < distance[j])
						distance[j] = newDistance;
				}
			}
		}
	}

	static int minIndex(long[] distance, boolean[] fixed) {
		int idx = 0;
		for (; idx < fixed.length; idx++)
			if (!fixed[idx])
				break;
		if (idx == fixed.length)
			return -1;
		for (int i = idx + 1; i < fixed.length; i++)
			if (!fixed[i] && distance[i] < distance[idx])
				idx = i;
		return idx;
	}
}

