                graph[a].Add(Tuple.Create(b, c));
                graph[b].Add(Tuple.Create(a, c));
            }
            dst = new long[N];
            var QK = Sarray();
            var Q = QK[0];
            var K = QK[1] - 1;
            dsf(K, -1);
            for (var i = 0; i < Q; ++i)
            {
                var xy = Sarray();
                var x = xy[0] - 1;
                var y = xy[1] - 1;
                WriteLine(dst[x] + dst[y]);
            }
            Out.Flush();
        }
        static void dsf(long r, long p)
        {
            foreach(var g in graph[r])
            {
                var nr = g.Item1;
                if (nr == p) continue;
                dst[nr] = dst[r] + g.Item2;
                dsf(nr, r);
            }
        }
    }
}

