public class Pair<T1, T2> : IComparable<Pair<T1, T2>>
{
    public T1 v1 { get; set; }
    public T2 v2 { get; set; }
    public Pair() { v1 = Input.Next<T1>();v2 = Input.Next<T2>(); }
    public Pair(T1 v1, T2 v2)
    { this.v1 = v1;this.v2 = v2; }

    public int CompareTo(Pair<T1, T2> p)
    {
        var c = Comparer<T1>.Default.Compare(v1, p.v1);
        if (c == 0)
            c = Comparer<T2>.Default.Compare(v2, p.v2);
        return c;
    }
    public override string ToString()
        => $"{v1.ToString()} {v2.ToString()}";
    public override bool Equals(object obj)
        => this == (Pair<T1, T2>)obj;
    public override int GetHashCode()
        => base.GetHashCode();
    public static bool operator ==(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) == 0;
    public static bool operator !=(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) != 0;
    public static bool operator >(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) == 1;
    public static bool operator >=(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) != -1;
    public static bool operator <(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) == -1;
    public static bool operator <=(Pair<T1, T2> p1, Pair<T1, T2> p2)
        => p1.CompareTo(p2) != 1;
}

using System;
using System.Collections.Generic;
using System.Text;

public class Program
{
    private int N;
    private List<E>[] Edges;
    private int Q, K;

    private long[] Cost;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        Edges = new List<E>[N];
        for (int i = 0; i < N; i++)
        {
            Edges[i] = new List<E>();
        }

        for (int i = 0; i < N - 1; i++)
        {
            int a = sc.NextInt() - 1;
            int b = sc.NextInt() - 1;
            long c = sc.NextLong();
            Edges[a].Add(new E(a, b, c));
            Edges[b].Add(new E(b, a, c));
        }
Cost = new long[N];
        Q = sc.NextInt();
        K = sc.NextInt() - 1;
        Search(K, -1, 0);
        var sb = new StringBuilder();
        for (int i = 0; i < Q; i++)
        {
            int x = sc.NextInt() - 1;
            int y = sc.NextInt() - 1;
            sb.AppendLine($"{Cost[x] + Cost[y]}");
        }

        Console.Write(sb.ToString());
    }

    private void Search(int i, int parent, long dist)
    {
        Cost[i] = dist;
        foreach (E e in Edges[i])
        {
            if (e.B == parent) continue;
            Search(e.B, i, dist + e.C);
        }
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

