namespace ABC070D
{
    class Program
    {
        static void Solve(Input input)
        {
            var n = input.NextInt();
            var dj = new Dijkstra(n);

            for (int i = 0; i < n - 1; i++)
            {
                var a = input.NextInt() - 1;
                var b = input.NextInt() - 1;
                var c = input.NextInt();

                dj.AddPath(a, b, c);
                dj.AddPath(b, a, c);
            }

            var q = input.NextInt();
            var k = input.NextInt() - 1;

            var sp = dj.ShortestPath(k);
            for (int i = 0; i < q; i++)
            {
                var x = input.NextInt() - 1;
                var y = input.NextInt() - 1;

                Console.WriteLine(sp[x] + sp[y]);
            }
        }

        /// <summary>
        /// 重み付き・有向グラフの単一始点最短経路
        /// 辺の重みは非負数だけ
        /// </summary>
        class Dijkstra
        {
            class PriorityQueue<T> where T : IComparable<T>
            {
                List<T> Heap;
                Func<T, T, bool> compare;

                public PriorityQueue(int capacity, bool isMinHeap = true)
                {
                    this.Heap = new List<T>(capacity);

                    if (isMinHeap)
                    {
                        compare = (x, y) => x.CompareTo(y) < 0;
                    }
                    else
                    {
                        compare = (x, y) => x.CompareTo(y) > 0;
                    }
                }

                public PriorityQueue() : this(0) { }

                static void pushHeap(List<T> heap, Func<T, T, bool> compare, T item)
                {
                    var n = heap.Count();
                    heap.Add(item);

                    while (n != 0)
                    {
                        var parent = (n - 1) / 2;

                        if (compare(heap[n], heap[parent]))
                        {
                            var temp = heap[n];
                            heap[n] = heap[parent];
                            heap[parent] = temp;
                        }

                        n = parent;
                    }
                }

                static T popHeap(List<T> heap, Func<T, T, bool> compare)
                {
                    if (!heap.Any())
                    {
                        throw new Exception();
                    }
                    var item = heap[0];

                    var n = heap.Count() - 1;
                    heap[0] = heap.Last();
                    heap.RemoveAt(n);

                    var parent = 0;
                    var child = 2 * parent + 1;
                    while (child < n)
                    {
                        if ((child != n - 1) && compare(heap[child + 1], heap[child]))
                        {
                            child++;
                        }

                        if (compare(heap[child], heap[parent]))
                        {
                            var temp = heap[parent];
                            heap[parent] = heap[child];
                            heap[child] = temp;
                        }

                        parent = child;
                        child = 2 * parent + 1;
                    }

                    return item;
                }

                /// <summary>
                /// 要素追加
                /// </summary>
                /// <param name="item"></param>
                public void Push(T item)
                {
                    pushHeap(this.Heap, this.compare, item);
                }

                /// <summary>
                /// 先頭の値取得し削除する
                /// </summary>
                /// <returns></returns>
                public T Pop()
                {
                    return popHeap(this.Heap, this.compare);
                }

                /// <summary>
                /// 先頭の値取得（削除はしない）
                /// </summary>
                /// <returns></returns>
                public T Peek()
                {
                    if (!this.Heap.Any())
                    {
                        throw new Exception();
                    }

                    return this.Heap[0];
                }

                /// <summary>
                /// ヒープに格納されているアイテム数
                /// </summary>
                /// <returns></returns>
                public int Count() => this.Heap.Count();

                /// <summary>
                /// 一つでの値が格納されているか
                /// </summary>
                /// <returns></returns>
                public bool Any() => this.Heap.Any();
            }

            struct Edge : IComparable<Edge>
            {
                public int To;
                public long Cost;

                public Edge(int to, long cost)
                {
                    this.To = to;
                    this.Cost = cost;
                }

                public int CompareTo(Edge other)
                {
                    return this.Cost.CompareTo(other.Cost);
                }
            }

            static readonly long INF = long.MaxValue / 5;

            // 接続情報
            List<List<Edge>> es;
            // ノード数
            int V;
            // 経路復元用情報
            int[] Prev;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="v">ノード数</param>
            public Dijkstra(int v)
            {
                es = Enumerable.Repeat(0, v)
                    .Select(_ => new List<Edge>())
                    .ToList();
                V = v;
            }

            /// <summary>
            /// 経路追加
            /// </summary>
            /// <param name="from"></param>
            /// <param name="to"></param>
            /// <param name="cost"></param>
            public void AddPath(int from, int to, int cost)
                => es[from].Add(new Edge(to, cost));

            /// <summary>
            /// 各ノードへの最短経路
            /// </summary>
            /// <param name="s"></param>
            /// <returns>nullなら負経路がある</returns>
            public long[] ShortestPath(int s)
            {
                var d = Enumerable.Repeat<long>(INF, V).ToArray();
                var pq = new PriorityQueue<Edge>();
                Prev = Enumerable.Repeat(-1, V).ToArray();

                d[s] = 0;
                pq.Push(new Edge(s, 0));

                while (pq.Any())
                {
                    var p = pq.Pop();
                    var v = p.To;

                    // 他の経路の方がコストが低い
                    if (d[v] < p.Cost) continue;

                    foreach (var e in es[v])
                    {
                        if (d[e.To] > d[v] + e.Cost)
                        {
                            // こっちの経路の方が効率的
                            d[e.To] = d[v] + e.Cost;
                            Prev[e.To] = v;
                            pq.Push(new Edge(e.To, d[e.To]));
                        }
                    }
                }

                return d;
            }

            /// <summary>
            /// 最後に探索した経路を復元する
            /// </summary>
            /// <param name="t">目的ノード</param>
            /// <returns>探索したことがないときはnull</returns>
            public int[] Path(int t)
            {
                if (this.Prev == null) return null;

                var stack = new Stack<int>();
                while (t >= 0)
                {
                    stack.Push(t);
                    t = Prev[t];
                }

                return stack.ToArray();
            }
        }

