namespace AtCoder.ABC070
{
    class Program
    {
        static int n;
        static Dictionary<int, long>[] link;
        static bool[] isFinal;
        static long[] d;
        static void Main()
        {
            n = int.Parse(Console.ReadLine());
            link = Enumerable.Range(0, n).Select(elem => new Dictionary<int, long>()).ToArray();
            isFinal = new bool[n];
            d = Enumerable.Repeat(long.MaxValue, n).ToArray();
            for (int i = 0; i < n - 1; i++)
            {
                int[] inputs = Console.ReadLine().Split(' ')
                            .Select(int.Parse)
                            .ToArray();
                link[inputs[0] - 1].Add(inputs[1] - 1, inputs[2]);
                link[inputs[1] - 1].Add(inputs[0] - 1, inputs[2]);
            }
            int[] qk = Console.ReadLine().Split(' ')
                        .Select(int.Parse)
                        .ToArray();
            int q = qk[0];
            int k = qk[1] - 1;
            var x = new int[q];
            var y = new int[q];
            Dijkstra(k);
            for (int i = 0; i < q; i++)
            {
                int[] xy = Console.ReadLine().Split(' ')
                            .Select(elem => int.Parse(elem) - 1)
                            .ToArray();
                Console.WriteLine(d[xy[0]] + d[xy[1]]);
            }
        }

        static void Dijkstra(int root)
        {
            d[root] = 0;
            int u = -1;
            while (true)
            {
                long mincost = long.MaxValue;
                for (int i = 0; i < n; i++)
                {
                    if (!isFinal[i] && d[i] < mincost)
                    {
                        mincost = d[i];
                        u = i;
                    }
                }
                if (mincost == long.MaxValue) break;
                isFinal[u] = true;

                foreach (var item in link[u])
                {
                    var v = item.Key;
                    if (isFinal[v]) continue;
                    if (d[u] + link[u][v] < d[v])
                    {
                        d[v] = d[u] + link[u][v];
                    }
                }
            }
        }
    }
}

