class Graph
{
    protected List<Edge>[] graph;
    protected int size;

    // [0, maxv)
    public Graph(int maxv)
    {
        graph = new List<Edge>[maxv];
        for (var i = 0; i < maxv; i++) graph[i] = new List<Edge>();
        size = maxv;
    }

    public void AddPath(int source, int target, int cost)
        => graph[source].Add(new Edge(target, cost));
}

class Dijkstra : Graph
{
    int source;
    long[] d;
    const long inf = long.MaxValue;

    public Dijkstra(int maxv) : base(maxv)
    {
        d = new long[maxv];
    }

    public void Calc(int source)
    {
        this.source = source;
        for (var i = 0; i < size; i++) d[i] = inf;
        d[source] = 0;
        var pq = new PriorityQueue<Pair<long, int>>();
        pq.Enqueue(Pair.Create(0L, source));

        while (pq.Any())
        {
            var p = pq.Dequeue();
            var v = p.Second;
            if (d[v] < p.First) continue;
            for (var i = 0; i < graph[v].Count; i++)
            {
                var e = graph[v][i];
                if (d[e.To] > d[v] + e.Cost)
                {
                    d[e.To] = d[v] + e.Cost;
                    pq.Enqueue(Pair.Create(d[e.To], e.To));
                }
            }
        }
    }

    public long GetMinCost(int source, int target)
    {
        if (source != this.source) throw new InvalidOperationException();
        return d[target];
    }
}

class PriorityQueue<T>
{
    List<T> heap;
    int size;
    Comparison<T> compare;

    public PriorityQueue()
        : this(Enumerable.Empty<T>(), Comparer<T>.Default.Compare) { }

    public PriorityQueue(IEnumerable<T> collection)
        : this(collection, Comparer<T>.Default.Compare) { }

    public PriorityQueue(Comparison<T> comparsion)
        : this(Enumerable.Empty<T>(), comparsion) { }

    public PriorityQueue(IEnumerable<T> collection, Comparison<T> comparsion)
    {
        var array = collection.ToArray();
        Array.Sort(array, comparsion);
        heap = new List<T>(array);
        size = array.Length;
        compare = comparsion;
    }

    public int Count => size;

    public bool Any() => size > 0;

    public void Clear() => size = 0;

    public void Enqueue(T item)
    {
        var i = size++;
        while (i > 0)
        {
            var p = (i - 1) >> 1;
            if (compare(heap[p], item) <= 0) break;
            if (i == heap.Count) heap.Add(heap[p]);
            else heap[i] = heap[p];
            i = p;
        }
        if (i == heap.Count) heap.Add(item);
        else heap[i] = item;
    }

    public T Dequeue()
    {
        if (size == 0) throw new InvalidOperationException();
        var r = heap[0];
        var x = heap[--size];
        var i = 0;
        while ((i << 1) + 1 < size)
        {
            var a = (i << 1) + 1;
            var b = (i << 1) + 2;
            if (b < size && compare(heap[b], heap[a]) < 0) a = b;
            if (compare(heap[a], x) >= 0) break;
            heap[i] = heap[a];
            i = a;
        }
        heap[i] = x;
        return r;
    }

    public T Peek()
    {
        if (size == 0) throw new InvalidOperationException();
        return heap[0];
    }
}

