            var a2 = long.Parse(line[1]) - 1;
            var a3 = long.Parse(line[2]);
            a[a1].Add(new Edge { to = a2, d = a3 });
            a[a2].Add(new Edge { to = a1, d = a3 });
        }
        string[] line2 = Console.ReadLine().Trim().Split(' ');
        var q = long.Parse(line2[0]);
        var k = long.Parse(line2[1]) - 1;
        var mind = new long[n];
        for (long i = 0; i < n; i++) mind[i] = INF;
        goDijk(a, k, n, mind);
        for (long i = 0; i < q; i++)
        {
            line2 = Console.ReadLine().Trim().Split(' ');
            var x = long.Parse(line2[0]) - 1;
            var y = long.Parse(line2[1]) - 1;
            Console.WriteLine(mind[x] + mind[y]);
        }
    }
    public static void goDijk(List<Edge>[] aa, long r, long n, long[] mind)
    {
        var pq = new PriorityQueue<Node>((int)n + 10000, 0);
        pq.Push(new Node { id =(int) r, d = 0 });
        while (pq.Count() > 0)
        {
            var targ = pq.Pop();
            var nowd = targ.d;
            var nowid = targ.id;
            if (mind[nowid] < nowd) continue;
            mind[nowid] = nowd;
            foreach (var x in aa[nowid])
                if (nowd + x.d < mind[x.to])
                    pq.Push(new Node { id =(int) x.to, d = nowd + x.d });
        }
    }
}

