namespace Algorithm
{
    class Program
    {
        static List<Edge>[] graph;
        static long[] depth;
        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            depth = new long[100010];
            graph = Enumerable.Repeat(0, n).Select(_ => new List<Edge>()).ToArray();

            for (var i = 0; i < n - 1; i++) {
               var t = Console.ReadLine().Split().Select(int.Parse).ToArray();
               t[0]--;
               t[1]--;

               graph[t[0]].Add(new Edge(){To=t[1],Cost=t[2]});
               graph[t[1]].Add(new Edge(){To=t[0],Cost=t[2]});
            }

            var m = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int Q = m[0], K = m[1];
            Dfs(--K, -1, 0);

            for (var i = 0; i < Q; i++) {
               var q = Console.ReadLine().Split().Select(int.Parse).ToArray();
               //Console.WriteLine($"{K} {q[0]} {q[1]}");
               var ans = depth[--q[0]]+depth[--q[1]];
               Console.WriteLine(ans);
            }
        }

        static void Dfs(int node, int parent, long cost)
        {
            depth[node] = cost;
            for (var i = 0; i < graph[node].Count; i++) {
                if (parent == graph[node][i].To) continue;
                Dfs(graph[node][i].To, node, cost+graph[node][i].Cost);
            }
        }
    }

