	class Program {
        static void Main(string[] args) {
			new Calc().Solve();
			return;
        }

		private class Calc {
			private List<List<Tuple<int, int>>> Graph = new List<List<Tuple<int, int>>>();
			public void Solve() {
				int N = ReadInt();
				REP(N, x => { Graph.Add(new List<Tuple<int, int>>()); });
				REP(N-1, x => {
					int a, b, c;
					ReadTriple(out a, out b, out c);
					a--;b--;
					Graph[a].Add(new Tuple<int, int>(b, c));
					Graph[b].Add(new Tuple<int, int>(a, c));
				});
				int Q, K;
				ReadMulti(out Q, out K);
				REP(100007, x => { Distance[x] = long.MaxValue; });
				K--;
				Distance[K] = 0;
				DFS(K, -1);
				REP(Q, x => {
					int a, b;
					ReadMulti(out a, out b);
					a--;b--;
					(Distance[a] + Distance[b]).WL();
				});
				return;
			}
			private long[] Distance = new long[100007];
			private void DFS(int cr,int pr) {
				foreach (var item in Graph[cr]) {
					if (item.Item1 == cr) continue;
					if (Distance[item.Item1] != long.MaxValue) continue;
					Distance[item.Item1] = Distance[cr] + item.Item2;
					DFS(item.Item1, cr);
				}
			}
		}
    }



