using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Text;

namespace AtCoder
{
    class ABC070D
    {
        class TreeEdge
        {
            public long idx;
            public long cost;
            public TreeEdge() {
                idx = 0;
                cost = 0;
            }
            public TreeEdge(long _idx,long _cost)
            {
                idx = _idx;
                cost = _cost;
            }
        }
        class Query
        {
            public long start;
            public long end;
            public Query() { start = end = 0; }
            public Query(long s, long e)
            {
                start = s;
                end = e;
            }
        }
        static List<Query> qList = null;


        static long N = 0;
        static long Q = 0;
        static long K = 0;

        static long[] DistanceFromPointK = null;
        static List<List<TreeEdge>> TreeNode = null;//TreeNode[A] : 木の節Aの辺情報を格納

        static void Main(string[] args)
        {
            preprocess();
            // 頂点数
            N = long.Parse(Console.ReadLine());
            DistanceFromPointK = new long[(int)N];
            TreeNode = new List<List<TreeEdge>>((int)N);//頂点数分確保
            for (int i = 0; i < N; ++i)
            {
                DistanceFromPointK[i] = long.MaxValue;
                TreeNode.Add(new List<TreeEdge>());
            }
            for (int i = 0; i < N-1; ++i){//edgeの数だけ
                long[] inputLongArray = Console.ReadLine().Split(' ').Select(_inputStr => long.Parse(_inputStr)).ToArray();
                long pA = inputLongArray[0];
                long pB = inputLongArray[1];
                long dist = inputLongArray[2];
                //配列のindexにするため0基準に
                pA--;
                pB--;
                //index A番目に、点Aから点Bへの辺情報を代入
                TreeNode[(int)pA].Add(new TreeEdge(pB, dist));
                //index B番目に、点Bから点Aへの辺情報を代入
                TreeNode[(int)pB].Add(new TreeEdge(pA, dist));
            }
            {
                long[] inputLongArray = Console.ReadLine().Split(' ').Select(_inputStr => long.Parse(_inputStr)).ToArray();
                Q = inputLongArray[0];
                K = inputLongArray[1]-1;//頂点indexなので1引く
            }
            qList = new List<Query>((int)Q);
            for (int i = 0; i < Q; ++i)
            {
                long[] inputLongArray = Console.ReadLine().Split(' ').Select(_inputStr => long.Parse(_inputStr)).ToArray();
                qList.Add(new Query(inputLongArray[0]-1, inputLongArray[1]-1) );//頂点indexなので1引く
            }

            //事前計算
            DFS(K, -1, 0);

            var ans = new List<long>((int)Q);
            for(int i = 0; i < Q; ++i)
            {
                long startIdx = qList[i].start;
                long endIdx = qList[i].end;
                long Cost_startToK = DistanceFromPointK[startIdx];
                long Cost_KToEnd = DistanceFromPointK[endIdx];
                ans.Add(Cost_startToK + Cost_KToEnd);
            }

            foreach (var l in ans)
            {
                Console.WriteLine(l.ToString());
            }
            Console.Out.Flush();
        }


        //深さ優先探索
        //今の点、親の点
        public static void DFS(long currentVertex,long parentVertex, long cost)
        {
            //KからcurrentVertexまでの距離を保存
            DistanceFromPointK[currentVertex] = cost;

            //次に見る点を探す
            foreach(var edge in TreeNode[(int)currentVertex])
            {
                //次に見る点が親だったら探索しなくてもいい
                if(edge.idx == parentVertex) { continue; }
                DFS(edge.idx, currentVertex, cost + edge.cost);
            }
        }


        //---------------------------------------------------------------------------------
        /// <summary>
        /// 
        /// </summary>
        public static void preprocess()
        {
            //出力高速化
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);
        }


        /// <summary>
        /// 与えられた数が素数かどうかを計算する
        /// </summary>
        /// <param name="num">対象数</param>
        /// <returns>true:素数, false:素数ではない(合成数)</returns>
        public static bool isPrime(int num)
        {
            if (num < 2) return false;
            else if (num == 2) return true;
            else if (num % 2 == 0) return false;

            double sqrtNum = Math.Sqrt(num);
            for (int i = 3; i <= sqrtNum; i += 2)
            {
                if (num % i == 0)
                {
                    return false;
                }
            }
            return true;
        }

        /// <summary>
        /// 順列mPnを計算する
        /// </summary>
        /// <param name="m"></param>
        /// <param name="n"></param>
        /// <returns></returns>
        public static long Permutation(long m, long n)
        {
            long ret = 1;
            for(var i = 0; i < n; ++i)
            {
                ret *= m - i;
            }
            return ret;
        }
        /// <summary>
        /// 組み合わせmCnを計算する
        /// </summary>
        /// <param name="m"></param>
        /// <param name="n"></param>
        /// <returns></returns>
        public static long Combination(long m, long n)
        {
            if(m == n || n == 0)
            {
                return 1;
            }
            long ans = 1;
            for(var i = 0; i <= n; ++i)
            {
                ans *= (m - i + 1) / i;
            }
            return ans;
        }
    }
}

