    class Graph
    {
      public static HashSet<int> ConnectedComponent(Dictionary<int, HashSet<int>> adj, int idx)
      {
        HashSet<int> comp = new HashSet<int>();
        comp.Add(idx);
        List<int> target = new List<int>();
        target.Add(idx);
        while (target.Count > 0)
        {
          List<int> next = new List<int>();
          foreach (var p in target)
          {
            foreach (var f in adj[p])
            {
              if (!comp.Contains(f))
              {
                next.Add(f);
                comp.Add(f);
              }
            }
          }
          target = next;
        }
        return comp;
      }
      public static int[] CalcDistance_OnTree(Dictionary<int, HashSet<int>> adj, int N, int start)
      {
        var dist = Enumerable.Range(0, N + 1).Select(i => -1).ToArray();
        dist[start] = 0;
        Queue<int> queue = new Queue<int>();
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
          var v = queue.Dequeue();
          foreach (var w in adj[v])
          {
            if (dist[w] < 0)
            {
              dist[w] = dist[v] + 1;
              queue.Enqueue(w);
            }
          }
        }
        return dist;
      }
      public static long[] CalcDistance_OnTree(Dictionary<int, Dictionary<int, long>> adj, int N, int start)
      {
        var dist = Enumerable.Range(0, N + 1).Select(i => -1L).ToArray();
        dist[start] = 0;
        Queue<int> queue = new Queue<int>();
        queue.Enqueue(start);
        while (queue.Count > 0)
        {
          var v = queue.Dequeue();
          foreach (var t in adj[v])
          {
            var w = t.Key;
            var c = t.Value;
            if (dist[w] < 0)
            {
              dist[w] = dist[v] + c;
              queue.Enqueue(w);
            }
          }
        }
        return dist;
      }
    }

