	for (int i = 0; i < n-1; i++)
	{
	    tmp = ReadIntArray();
	    int a = tmp[0] - 1, b = tmp[1] - 1, c = tmp[2];
	    d[a,b] = d[b,a] = c;
	}
	tmp = ReadIntArray();
	int q = tmp[0], k = tmp[1] - 1;

	for (int i = 0; i < n; i++)
	    for (int j = 0; j < n; j++)
		d[k,i] = Math.Min(d[k, i], d[k, j] + d[j, i]);

	for (int i = 0; i < q; i++)
	{
	    tmp = ReadIntArray();
	    int x = tmp[0] - 1, y = tmp[1] - 1;
	    long ans = d[k,x] + d[k,y];
	    WriteLine(ans);
	}
    }
