    void solve()
    {
        string[] str;
        int N = int.Parse(Console.ReadLine());

        //        int[,] dist = new int[N + 1, N + 1];
        long[] distK = new long[N + 1];
        int[] a = new int[N];
        int[] b = new int[N];
        int[] c = new int[N];

        for (int i = 0; i < N - 1; ++i)
        {
            str = Console.ReadLine().Split(' ');
            a[i] = int.Parse(str[0]);
            b[i] = int.Parse(str[1]);
            c[i] = int.Parse(str[2]);
            //dist[a, b] = c;
            //dist[b, a] = c;
        }

        str = Console.ReadLine().Split(' ');
        int Q = int.Parse(str[0]);
        int K = int.Parse(str[1]);

        Queue<int> que = new Queue<int>();
        que.Enqueue(K);

        while (que.Count > 0)
        {
            int t = que.Dequeue();
            for (int i = 0; i < N - 1; ++i)
            {
                if (a[i] == t)
                {
                    if (distK[b[i]] == 0)
                    {
                        que.Enqueue(b[i]);
                        distK[b[i]] = distK[t] + c[i];
                    }
                }
                if (b[i] == t)
                {
                    if (distK[a[i]] == 0)
                    {
                        que.Enqueue(a[i]);
                        distK[a[i]] = distK[t] + c[i];
                    }
                }
            }
        }

        for (int i = 0; i < Q; ++i)
        {
            str = Console.ReadLine().Split(' ');
            int x = int.Parse(str[0]);
            int y = int.Parse(str[1]);

            Console.WriteLine(distK[x] + distK[y]);
        }
