    {
        //入力を受け取る
        var N = long.Parse(Console.ReadLine());

        Path = new List<long>[N+1];
        Step = new long[N+1,N+1];
        for(long i = 0; i< N ;i++){
          Path[i+1] = new List<long>();
        }

        for(long i = 1; i< N ;i++){
           var ABC = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
           var A = ABC[0];
           var B = ABC[1];
           var C = ABC[2];
           Path[A].Add(B);
           Path[B].Add(A);
           Step[A,B] = C;
           Step[B,A] = C;
        }

        var QK = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
        var Q = QK[0];
        var K = QK[1];
        ans = new long[N+1];
        for(long i = 0;i <= N ;i++){
          ans[i] = -1;
        }
        //幅優先探索でKからの最短経路を求める
        //WFS(K);
        //XからKとYからKのそれぞれの最短経路を足し合わせたものを答えにする
        for(long i = 0; i < Q ;i++){
          var XY = Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToArray();
          var X = XY[0];
          var Y = XY[1];
          Console.WriteLine(ans[X]+ans[Y]);
        }

    }
    static void WFS(long num)
    {
        var queue = new MyQueue();
        queue.Enque(num);
        ans[num] = 0;
        while (!(queue.isEmpty()))
        {
            var top = queue.Deque();
                foreach (long item in Path[top])
                {
                  //Console.WriteLine(item);
                    //探索済みか
                    if (ans[item] == -1)
                    {
                        ans[item] = ans[top] + Step[top,item];
                        queue.Enque(item);
                    }
                }
        }
    }
}

