        }

    }
    static void WFS(long num)
    {
        var queue = new MyQueue();
        queue.Enque(num);
        ans[num] = 0;
        while (!(queue.isEmpty()))
        {
            var top = queue.Deque();
                foreach(KeyValuePair<long,long> item in Path[top].adj) {
                    //探索済みか
                    if (ans[item.Key] == -1)
                    {
                        ans[item.Key] = ans[top] + item.Value;
                        queue.Enque(item.Key);
                    }
                }
        }
    }
}

class MyQueue
{
    public long[] datas = new long[100000];
    public long enpoint = -1;
    public long depoint = -1;
    public void Enque(long data)
    {
        this.enpoint++;
        datas[this.enpoint] = data;
    }
    public long Deque()
    {
        this.depoint++;
        return datas[this.depoint];
    }

    public bool isEmpty()
    {
        return (this.depoint == this.enpoint);
    }
}

