        const long SINF = 9223372036854775807;

        static int N, Q, K;

        static List<List<Edge>> G = new List<List<Edge>>();
        static bool[] seen;
        static long[] dis;

        static int[] x, y;

        public static void Input()
        {
            var cin = new Scanner();
            N = int.Parse(Console.ReadLine());
            seen = new bool[N];
            dis = new long[N];
            for(var i = 0; i < N; i++)
            {
                G.Add(new List<Edge>());
            }
            for(var i = 0; i < N - 1; i++)
            {
                var input = cin.SplitReader();
                G[input[0] - 1].Add(new Edge(input[1] - 1, input[2]));
                G[input[1] - 1].Add(new Edge(input[0] - 1, input[2]));
            }
            var p = cin.SplitReader();
            Q = p[0];
            K = p[1] - 1;
            x = new int[Q];
            y = new int[Q];
            for(var i = 0; i < Q; i++)
            {
                var input = cin.SplitReader();
                x[i] = input[0] - 1;
                y[i] = input[1] - 1;
            }

        }

        static void Main(string[] args)
        {
            Input();
            var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
            Console.SetOut(sw);

            Dfs(K, 0);
            for(var i = 0; i < Q; i++)
            {
                Console.WriteLine(dis[x[i]] + dis[y[i]]);
            }

            Console.Out.Flush();
        }

        struct Edge
        {
            public int _to;
            public long _distance;

            public Edge(int t,long d)
            {
                _to = t;
                _distance = d;
            }
        }

        public static void Dfs(int v, long D)
        {
            seen[v] = true;
            dis[v] = D;
            foreach(var next in G[v])
            {
                if (seen[next._to]) { continue; }
                Dfs(next._to, D + next._distance);
            }
        }

    }




