namespace AtCoder.ABC070
{
    class Program
    {
        static int n;
        static long[,] M;
        static bool[] isFinal;
        static long[] d;
        static void Main()
        {
            n = int.Parse(Console.ReadLine());
            M = new long[n, n];
            isFinal = new bool[n];
            d = Enumerable.Repeat(long.MaxValue, n).ToArray();
            for (int i = 0; i < n - 1; i++)
            {
                string[] inputs = Console.ReadLine().Split(' ');
                M[int.Parse(inputs[0]) - 1, int.Parse(inputs[1]) - 1] = long.Parse(inputs[2]);
                M[int.Parse(inputs[1]) - 1, int.Parse(inputs[0]) - 1] = long.Parse(inputs[2]);
            }
            int[] qk = Console.ReadLine().Split(' ')
                        .Select(int.Parse)
                        .ToArray();
            int q = qk[0];
            int k = qk[1] - 1;
            var x = new int[q];
            var y = new int[q];
            for (int i = 0; i < q; i++)
            {
                int[] xy = Console.ReadLine().Split(' ')
                            .Select(elem => int.Parse(elem) - 1)
                            .ToArray();
                x[i] = xy[0];
                y[i] = xy[1];
            }

            Dijkstra(k);
            for (int i = 0; i < q; i++)
            {
                Console.WriteLine(d[x[i]] + d[y[i]]);
            }
        }

        static void Dijkstra(int root)
        {
            d[root] = 0;
            int u = -1;
            while (true)
            {
                long mincost = long.MaxValue;
                for (int i = 0; i < n; i++)
                {
                    if (!isFinal[i] && d[i] < mincost)
                    {
                        mincost = d[i];
                        u = i;
                    }
                }
                if (mincost == long.MaxValue || u == -1) break;
                isFinal[u] = true;

                for (int v = 0; v < n; v++)
                {
                    if (!isFinal[v] && M[u, v] != 0)
                    {
                        if (d[u] + M[u, v] < d[v])
                        {
                            d[v] = d[u] + M[u, v];
                        }
                    }
                }
            }
        }
    }
}

