        var qk = Input.ar;
        ps[qk[1] - 1].Weight = 0;
        pq.Enqueue(ps[qk[1] - 1]);
        while (!pq.isEmpty)
        {
            var p = pq.Dequeue();
            foreach (var ad in p.adj)
                if (ps[ad].Weight > p.Weight + p.dist[ad])
                {
                    ps[ad].Weight = p.Weight + p.dist[ad];
                    pq.Enqueue(ps[ad]);
                }
        }
        var res = new long[qk[0]];
        for(var j = 0; j < qk[0]; j++)
        {
            var xy = Input.ar;
            res[j] = ps[xy[0] - 1].Weight + ps[xy[1] - 1].Weight;
        }
        WriteLine(string.Join("\n", res));
    }
}

