        for (int i = 0; i < n + 1; i++)
        {
            from[i] = new List<Tuple<long, long>>();
        }
        for (int i = 0; i < n - 1; i++)
        {
            long a = sc.NextLong();
            long b = sc.NextLong();
            long c = sc.NextLong();
            from[a].Add(Tuple.Create(b, c));
            from[b].Add(Tuple.Create(a, c));
        }

        long q = sc.NextLong();
        long k = sc.NextLong();

        long[] dists = new long[n + 1];
        for (int i = 0; i < n + 1; i++)
        {
            dists[i] = long.MinValue;
        }

        Queue<Tuple<long, long>> que = new Queue<Tuple<long, long>>();
        que.Enqueue(Tuple.Create(k, (long)0));
        while (que.Count > 0)
        {
            var item = que.Dequeue();
            var point = item.Item1;
            var cost = item.Item2;
            if (dists[point] != long.MinValue)
            {
                continue;
            }
            dists[point] = cost;
            foreach (var target in from[point])
            {
                que.Enqueue(Tuple.Create(target.Item1, cost + target.Item2));
            }
        }

        for (int i = 0; i < q; i++)
        {
            long x = sc.NextLong();
            long y = sc.NextLong();

