    }

    class Branch
    {
        public readonly int From;
        public readonly int To;
        public readonly int Distance;

        public Branch(int from, int to, int distance)
        {
            From = from;
            To = to;
            Distance = distance;
        }

        public int other(int current)
        {
            if (current == From)
            {
                return To;
            }

            if (current == To)
            {
                return From;
            }

            throw new Exception();
        }
    }
