class MyQueue
{
    public long[] datas = new long[100000];
    public long enpoint = -1;
    public long depoint = -1;
    public void Enque(long data)
    {
        this.enpoint++;
        datas[this.enpoint] = data;
    }
    public long Deque()
    {
        this.depoint++;
        return datas[this.depoint];
    }

    public bool isEmpty()
    {
        return (this.depoint == this.enpoint);
    }
}

