        if(node1 == node2) {
            Route tmp = new Route();
            tmp.CommonParent = TreeNodeList[node1];
            tmp.ThuruPoint = node1 == this.MustThuruPoint;
            return tmp;
        }

        Route ans = new Route();
        if(TreeNodeList[node1].Depth > TreeNodeList[node2].Depth) {
            ans = GetAnsSub(node2, node1);
        } else {
			ans = GetAnsSub(node1, node2);
		}
        if(ans.ThuruPoint) {
            return ans;
        }
        Route ret = GetAnsSub(MustThuruPoint, ans.CommonParent.Id);
        ans.Length += ret.Length * 2;
