            return GetAnsSub(node2, node1);
        }
        Route ans = GetAnsSub(node1, TreeNodeList[node2].Parent.Id);
        ans.Length += TreeNodeList[node2].Length;
        if(node2 == MustThuruPoint) {
            ans.ThuruPoint = true;
        }
        pathDic[node1][node2] = ans;
        return ans;
	}

