    struct Edge : IComparable<Edge>
    {
        public int to; public long cost;
        public Edge(int to, long cost)
        {
            this.to = to;
            this.cost = cost;
        }
        public int CompareTo(Edge e)
        {
            return cost.CompareTo(e.cost);
        }
    }
    List<Edge>[] G;
    //G = Enumerable.Range(0, N).Select(i => new List<Edge>()).ToArray();
    long[] D;
    const long inf = long.MaxValue / 3;
    void dijkstra(int s)
    {
        int n = G.Length;
        D = Enumerable.Repeat(inf, n).ToArray();
        var Q = new PriorityQueue<Edge>() { rev = true };//小さい順に取り出す
        D[s] = 0;
        Q.Enqueue(new Edge(s, D[s]));
        while (Q.Any())
        {
            var e = Q.Dequeue();
            var v = e.to;
            if (D[v] < e.cost) continue;
            foreach (var gv in G[v])
            {
                if (D[gv.to] > D[v] + gv.cost)
                {
                    D[gv.to] = D[v] + gv.cost;
                    Q.Enqueue(new Edge(gv.to, D[gv.to]));
                }
            }

        }
    }
    class PriorityQueue<T> where T : IComparable<T>
    {
        List<T> buf;
        public bool rev = false;
        public PriorityQueue() { buf = new List<T>(); }
        int cmp(int i, int j) { return buf[i].CompareTo(buf[j]) * (rev ? -1 : 1); }
        void swap(int i, int j) { var t = buf[i]; buf[i] = buf[j]; buf[j] = t; }
        public void Enqueue(T elem)
        {
            int n = buf.Count;
            buf.Add(elem);
            while (n > 0)
            {
                int i = (n - 1) >> 1;
                if (cmp(n, i) > 0) swap(i, n);
                n = i;
            }
        }
        public T Dequeue()
        {
            T ret = buf[0];
            int n = buf.Count - 1;
            buf[0] = buf[n];
            buf.RemoveAt(n);
            for (int i = 0, j; (j = (i << 1) + 1) < n; i = j)
            {
                if (j != n - 1 && cmp(j, j + 1) < 0) ++j;
                if (cmp(i, j) < 0) swap(i, j);
            }
            return ret;
        }
        public int Count { get { return buf.Count; } }
        public bool Any() { return Count > 0; }
        public T Peek() { return buf[0]; }
    }

}

