            var distance = new long[N + 1, N + 1];
            for (int i = 0; i < N - 1; i++)
            {
                var read1 = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                distance[read1[0], read1[1]] = read1[2];
                distance[read1[1], read1[0]] = read1[2];
            }

            var read2 = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            var Q = read2[0];
            var K = read2[1];
            var fromK = new long[N + 1];
            for (int i = 0; i < N + 1; i++) fromK[i] = -1;
            fromK[K] = 0;
            var nodes = new Queue<int>();
            nodes.Enqueue(K);

            while (nodes.Count != 0)
            {
                var searchNode = nodes.Dequeue();
                for (int i = 1; i < N + 1; i++)
                {
                    if (distance[searchNode, i] != 0 && fromK[i] == -1)
                    {
                        nodes.Enqueue(i);
                        fromK[i] = fromK[searchNode] + distance[searchNode, i];
                    }
                }
            }

            for (int i = 0; i < Q; i++)
            {
                var xy = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                Console.WriteLine(fromK[xy[0]] + fromK[xy[1]]);
            }
        }
    }
}

using System;
