class Procon
{
  public Procon() {}
  static void Main(string[] agrs)
  {
    new Procon().Do();
  }

  Scanner cin;

  public void Do()
  {
    cin = new Scanner();
    int N = cin.nextInt();
    int[,] dist = new int[N-1, 3];
    for (int i=0; i<N-1; i++) {
      dist[i,0] = cin.nextInt()-1;
      dist[i,1] = cin.nextInt()-1;
      dist[i,2] = cin.nextInt();
    }
    int Q = cin.nextInt();
    int K = cin.nextInt() - 1;
    long[] d = new long[N];
    for (int i=0; i<N; i++) {
      d[i] = -1;
    }
    d[K] = 0;

    for (int i=0; i<N; i++) { 
      for (int j=0; j<N-1; j++) {
        if (d[dist[j,0]] >= 0 && d[dist[j,1]] < 0) {
          d[dist[j,1]] = d[dist[j,0]] + dist[j, 2];
        } else if (d[dist[j,1]] >= 0 && d[dist[j,0]] < 0) {
          d[dist[j,0]] = d[dist[j,1]] + dist[j, 2];
        }
      }
    }

    for (int i=0; i<Q; i++) {
      int x = cin.nextInt();
      int y = cin.nextInt();
      Console.WriteLine((long)d[x-1] + (long)d[y-1]);
    }
  }
}


