using System;
using System.Collections.Generic;
using System.Text;

namespace AtTest.D_Challenge
{
    class ABC_070
    {
        static Node[] nodes;
        static long[] distances;
        static bool[] isMin;

        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            nodes = new Node[n];
            distances = new long[n];
            isMin = new bool[n];
            for (int i = 0; i < n; i++)
            {
                nodes[i] = new Node(n);
                distances[i] = -1;
                isMin[i] = false;
            }
            for (int i = 0; i < n-1; i++)
            {
                int[] abc = ReadInts();
                nodes[abc[0] - 1].edges.Add(new Edge(abc[1] - 1, abc[2]));
                nodes[abc[1] - 1].edges.Add(new Edge(abc[0] - 1, abc[2]));
            }
            int[] qk = ReadInts();
            distances[qk[1] - 1] = 0;
            isMin[qk[1] - 1] = true;
            Dijkstra(qk[1] - 1);

            var res = new long[qk[0]];
            for (int i = 0; i < qk[0]; i++)
            {
                int[] xy = ReadInts();
                res[i] = distances[xy[0] - 1]
                    + distances[xy[1] - 1];
            }
            for(int i = 0; i < qk[0]; i++)
            {
                Console.WriteLine(res[i]);
            }
        }

        //最大距離を帰す
        static void Dijkstra(int start)
        {
            Node startNode = nodes[start];
            int cnt = 1;
            int nowIndex = start;

            while (cnt < nodes.Length)
            {
                for (int i = 0; i < nodes[nowIndex].edges.Count; i++)
                {
                    int destIndex = nodes[nowIndex].edges[i].toIndex;
                    if (isMin[destIndex]) continue;//確定ノードは無視

                    long distance = distances[nowIndex]
                        + nodes[nowIndex].edges[i].distance;
                    if (distance < distances[destIndex]
                        || distances[destIndex] == -1)
                    {
                        distances[destIndex] = distance;
                    }
                }

                int settleIndex = -1;
                for (int i = 0; i < distances.Length; i++)
                {
                    if (isMin[i] || distances[i] == -1) continue;

                    if (settleIndex == -1
                        || distances[i] < distances[settleIndex])
                    {
                        settleIndex = i;
                    }
                }
                if (settleIndex == -1) break;
                isMin[settleIndex] = true;
                nowIndex = settleIndex;
                cnt++;
            }
        }

        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        class Node
        {
            public List<Edge> edges;
            public Node(int length)
            {
                distances = new long[length];
                isMin = new bool[length];
                for (int i = 0; i < length; i++)
                {
                    distances[i] = -1;
                }
                edges = new List<Edge>();
            }
        }

        class Edge
        {
            public int toIndex;
            public int distance;

            public Edge(int toIndex, int distance)
            {
                this.toIndex = toIndex;
                this.distance = distance;
            }
        }
    }
}

