using System;
using System.Collections.Generic;

namespace Abc070d
{
    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            int[][] branches = new int[n - 1][];
            for (int i = 0; i < n - 1; i++)
            {
                string[] input = Console.ReadLine().Split(' ');
                int[] branch =
                {
                    int.Parse(input[0]),
                    int.Parse(input[1]),
                    int.Parse(input[2])
                };
                branches[i] = branch;
            }

            string[] query = Console.ReadLine().Split(' ');
            int q_num = int.Parse(query[0]);
            int k = int.Parse(query[1]);

            long[] dp = new long[n + 1];
            dp[k] = 0;
            List<int> queue = new List<int>();
            int current;
            queue.Add(k);
            while (queue.Count > 0)
            {
                current = queue[0];
                queue.RemoveAt(0);
                foreach (int[] branch in branches)
                {
                    if (branch[1] != k && dp[branch[1]] == 0 && branch[0] == current)
                    {
                        dp[branch[1]] = dp[current] + branch[2];
                        queue.Add(branch[1]);
                    }

                    if (branch[0] != k && dp[branch[0]] == 0 && branch[1] == current)
                    {
                        dp[branch[0]] = dp[current] + branch[2];
                        queue.Add(branch[0]);
                    }
                }
            }

            for (int i = 0; i < q_num; i++)
            {
                string[] q = Console.ReadLine().Split(' ');
                int x = int.Parse(q[0]);
                int y = int.Parse(q[1]);

                Console.WriteLine(dp[x] + dp[y]);
            }
        }
    }
}

using System;
