using System.Runtime.InteropServices;

class Program
{
    const string Yes = "Yes";
    const string No = "No";
    const long Mod = 1000000007;
    const char White = '.';
    const char Black = '#';

    static void Main(string[] args) {
#if DEBUG
        MyDebugger.Test(process, "../TextFile1.txt");
#else
        object ret = process(new StreamReader(Console.OpenStandardInput()));
        Console.WriteLine(ret);
#endif
    }

    static object process(TextReader input) {
        var n = int.Parse(input.ReadLine());
        var ab = new Dictionary<int, List<int>>();
        var cc = new Dictionary<int, int>[n];

        for (int i = 0; i < n; i++) {
            ab[i] = new List<int>();
            cc[i] = new Dictionary<int, int>();
        }

        for (int i = 0; i < n - 1; i++) {
            var spl = input.ReadLine().Split(' ');
            var a = int.Parse(spl[0]) - 1;
            var b = int.Parse(spl[1]) - 1;
            var c = int.Parse(spl[2]);

            ab[a].Add(b);
            ab[b].Add(a);

            cc[Math.Min(a, b)][Math.Max(a, b)] = c;
        }

        var splx = input.ReadLine().Split(' ');
        var q = int.Parse(splx[0]);
        var k = int.Parse(splx[1]) - 1;

        var box = new long[n];
        Search(n, ab, cc, k, -1, box);

        var sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            var spl = input.ReadLine().Split(' ');
            var x = int.Parse(spl[0]) - 1;
            var y = int.Parse(spl[1]) - 1;

            sb.AppendLine((box[x] + box[y]).ToString());
        }

        return sb;
    }

    static void Search(int n, Dictionary<int, List<int>> ab, Dictionary<int, int>[] cc, int p, int from, long[] box) {
        //Debug.WriteLine(x);

        if (from != -1) {
            box[p] = box[from] + cc[Math.Min(from, p)][Math.Max(from,p)];
        }

        //次の再帰
        foreach (var to in ab[p]) {
            if (to == from) continue;
            Search(n, ab, cc, to, p, box);
        }
    }

    static int[] ToIntArray(string strs, int n) {
        var ret = new int[n];
        var spl = strs.Split(' ');
        for (int i = 0; i < n; i++)
            ret[i] = int.Parse(spl[i]);
        return ret;
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;

namespace AtCoder.D
{
    public class Program
    {
        public static void Main() { var r = GetResult(); Debug.WriteLine(r); Console.Write(r); }

        private static object GetResult()
        {
            var N = ReadLong();
            var dists = Enumerable.Range(0, (int)N)
                .ToDictionary(x => x, y => new List<Path>());
            for (var i = 0; i < N - 1; i++)
            {
                var (a, b, c) = Read3Longs();
                a--; b--; // インデックス変換

                dists[(int)a].Add(new Path { From = a, To = b, Dist = c });
                dists[(int)b].Add(new Path { From = b, To = a, Dist = c });
            }

            var (Q, K) = Read2Longs();
            K--;//インデックス変換
            var distK = new long[N];
            distK[K] = 0;
            var q = new Queue<Path>();

            var distsOfK = dists[(int)K];
            foreach (var item in distsOfK)
            {
                distK[item.To] = item.Dist;

                foreach (var d in dists[(int)item.To])
                {
                    if (d.To == K) continue;
                    q.Enqueue(d);
                }
            }

            while (q.Count > 0)
            {
                var dq = q.Dequeue();
                distK[dq.To] = distK[dq.From] + dq.Dist;

                var removes = new List<int>();
                var distsOfTo = dists[(int)dq.To];
                foreach (var item in distsOfTo)
                {
                    if (distK[item.To] != 0)
                    {
                        removes.Add(distsOfTo.IndexOf(item));
                        continue;
                    }
                    q.Enqueue(item);
                }

                foreach (var remove in removes.OrderByDescending(x => x))
                {
                    distsOfTo.RemoveAt(remove);
                }
            }

            var sb = new StringBuilder();
            for (var i = 0; i < Q; i++)
            {
                var (x, y) = Read2Longs();
                x--; y--;//インデックス変換
                var d = distK[x] + distK[y];
                sb.AppendLine(d.ToString());
            }

            return sb.ToString().Trim();
        }

        private class Path
        {
            public long From { get; set; }
            public long To { get; set; }
            public long Dist { get; set; }
        }

        #region Console.Read

        public static string ReadText() { return Console.ReadLine(); }
        public static List<string> ReadTexts() { return Console.ReadLine().Split(' ').ToList(); }
        public static long ReadLong() { return long.Parse(Console.ReadLine()); }
        public static (long, long) Read2Longs() { var ls = ReadLongs(); return (ls[0], ls[1]); }
        public static (long, long, long) Read3Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2]); }
        public static (long, long, long, long) Read4Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3]); }
        public static (long, long, long, long, long) Read5Longs() { var ls = ReadLongs(); return (ls[0], ls[1], ls[2], ls[3], ls[4]); }
        public static List<long> ReadLongs() { return Console.ReadLine().Split(' ').Select(x => long.Parse(x)).ToList(); }

        #endregion
    }
}

