namespace abc070_d
{
    class Program
    {
        static long[,] cost;
        static long[] d;
        static bool[] used;
        static int V;
        const long inf = 1000000000000000000;
        static void dijkstra(int start)
        {
            for (int i = 0; i < V; i++) { d[i] = inf; used[i] = false; }
            d[start] = 0;

            while (true)
            {
                int v = -1;
                for (int u = 0; u < V; u++)
                {
                    if (!used[u] && (v == -1 || d[u] < d[v])) v = u;
                }

                if (v == -1) break;
                used[v] = true;

                for (int u = 0; u < V; u++)
                {
                    d[u] = Math.Min(d[u], d[v] + cost[v, u]);
                }
            }

        }
        static void Main(string[] args)
        {
            V = int.Parse(Console.ReadLine());
            cost = new long[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++) cost[i, j] = inf;
            }
            d = new long[V];
            used = new bool[V];
            for (int i = 0; i < V - 1; i++)
            {
                int[] x = Console.ReadLine().Split().Select(int.Parse).ToArray();
                x[0]--; x[1]--;
                cost[x[0], x[1]] = x[2]; cost[x[1], x[0]] = x[2];
            }
            int[] a = Console.ReadLine().Split().Select(int.Parse).ToArray();
            dijkstra(a[1] - 1);
            for (int i = 0; i < a[0]; i++)
            {
                int[] x = Console.ReadLine().Split().Select(int.Parse).ToArray();
                x[0]--; x[1]--;
                Console.WriteLine(d[x[0]] + d[x[1]]);
            }
        }
    }
}

