    List<long>[] C;
    long[] cost;
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        G = new List<int>[N];
        C = new List<long>[N];
        for(int i=0;i<N;i++){
            G[i] = new List<int>();
            C[i] = new List<long>();
        }
        string[] str;
        for(int i=0;i<N-1;i++){
            str = Console.ReadLine().Split(' ');
            int a = int.Parse(str[0])-1;
            int b = int.Parse(str[1])-1;
            long c = int.Parse(str[2]);
            G[a].Add(b);
            G[b].Add(a);
            C[a].Add(c);
            C[b].Add(c);
        }
        str = Console.ReadLine().Split(' ');
        int Q = int.Parse(str[0]);
        int K = int.Parse(str[1]) - 1;
        cost = new long[N];
        dfs(K,-1,0);
        for(int i=0;i<Q;i++){
            str = Console.ReadLine().Split(' ');
            long count = cost[int.Parse(str[0])-1] + cost[int.Parse(str[1])-1];
            sb.Append(count+"\n");
        }
    }
    void dfs(int v,int f,long c){
        cost[v] = c;
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if(t != f){
                dfs(t,v,c+C[v][i]);
            }
        }
    }
}

