            isMin[qk[1] - 1] = true;
            Dijkstra(qk[1] - 1);

            var res = new long[qk[0]];
            for (int i = 0; i < qk[0]; i++)
            {
                int[] xy = ReadInts();
                res[i] = distances[xy[0] - 1]
                    + distances[xy[1] - 1];
            }
            for(int i = 0; i < qk[0]; i++)
            {
                Console.WriteLine(res[i]);
            }
        }

        //最大距離を帰す
        static void Dijkstra(int start)
        {
            int cnt = 1;
            int nowIndex = start;
            var checkDict = new Dictionary<int, bool>();

            while (cnt < nodes.Length)
            {
                for (int i = 0; i < nodes[nowIndex].edges.Count; i++)
                {
                    int destIndex = nodes[nowIndex].edges[i].toIndex;
                    if (isMin[destIndex]) continue;//確定ノードは無視

                    long distance = distances[nowIndex]
                        + nodes[nowIndex].edges[i].distance;
                    if (checkDict.ContainsKey(destIndex))
                    {
                        distances[destIndex]
                            = Math.Min(distances[destIndex], distance);
                    }
                    else
                    {
                        distances[destIndex] = distance;
                        checkDict.Add(destIndex, true);
                    }
                }

                int settleIndex = -1;
                foreach(int index in checkDict.Keys) {
                    if (isMin[index]) continue;

                    if (settleIndex == -1
                        || distances[index] < distances[settleIndex])
                    {
                        settleIndex = index;
                    }
                }
                if (settleIndex == -1) break;
                isMin[settleIndex] = true;
                nowIndex = settleIndex;
                cnt++;
                checkDict.Remove(settleIndex);
            }
        }

