public class Hello
{
    public const long INF = 999999999999999999;
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine().Trim());
        var a = new List<Edge>[n];
        for (int i = 0; i < n; i++) a[i] = new List<Edge>();
        for (int i = 0; i < n - 1; i++)
        {
            string[] line = Console.ReadLine().Trim().Split(' ');
            var a1 = int.Parse(line[0]) - 1;
            var a2 = int.Parse(line[1]) - 1;
            var a3 = int.Parse(line[2]);
            a[a1].Add(new Edge { to = a2, d = a3 });
            a[a2].Add(new Edge { to = a1, d = a3 });
        }
        string[] line2 = Console.ReadLine().Trim().Split(' ');
        var q = int.Parse(line2[0]);
        var k = int.Parse(line2[1]) - 1;
        var mind = new long[n];
        for (int i = 0; i < n; i++) mind[i] = INF;
        goDijk(a, k, n, mind);
        for (int i = 0; i < q; i++)
        {
            line2 = Console.ReadLine().Trim().Split(' ');
            var x = int.Parse(line2[0]) - 1;
            var y = int.Parse(line2[1]) - 1;
            Console.WriteLine(mind[x] + mind[y]);
        }
    }
    public static void goDijk(List<Edge>[] aa, int r, int n, long[] mind)
    {
        var pq = new PriorityQueue<Node>(n + 10000, 0);
        pq.Push(new Node { id = r, d = 0 });
        while (pq.Count() > 0)
        {
            var targ = pq.Pop();
            var nowd = targ.d;
            var nowid = targ.id;
            if (mind[nowid] < nowd) continue;
            mind[nowid] = nowd;
            foreach (var x in aa[nowid])
                if (nowd + x.d < mind[x.to])
                    pq.Push(new Node { id = x.to, d = nowd + x.d });
        }
    }
}

