class Program {
    static int ReadInt() { return int.Parse(Console.ReadLine()); }
    static int[] ReadInts() { return Console.ReadLine().Split().Select(int.Parse).ToArray(); }
    static string[] ReadStrings() { return Console.ReadLine().Split(); }

    struct E {
        public int node;
        public int cost;
    }

    static long[] Calc(int k, int n, List<E>[] adj) {
        var used = new bool[n + 1];
        var cost = new long[n + 1];

        var q = new PriorityQueue<D>();
        q.Enqueue(new D { node = k, cost = 0 });
        while (q.Count > 0) {
            var d = q.Dequeue();
            if (used[d.node]) continue;
            used[d.node] = true;

            cost[d.node] = d.cost;

            foreach (var e in adj[d.node]) {
                q.Enqueue(new D { node = e.node, cost = d.cost + e.cost });
            }
        }

        return cost;
    }

    static void Main() {
        int n = ReadInt();

        var adj = new List<E>[n + 1];
        for (int i = 0; i < adj.Length; i++)
            adj[i] = new List<E>();
        for (int i = 0; i < n - 1; i++) {
            var abc = ReadInts();
            int a = abc[0], b = abc[1], c = abc[2];
            adj[a].Add(new E { node = b, cost = c });
            adj[b].Add(new E { node = a, cost = c });
        }

        var qk = ReadInts();
        int q = qk[0], k = qk[1];

        var cost = Calc(k, n, adj);
        for (int i = 0; i < q; i++) {
            var xy = ReadInts();
            int x = xy[0], y = xy[1];

            var ans = cost[x] + cost[y];
            Console.WriteLine(ans);

        }
    }
}

