	static class Program
	{
		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var (a, b, c) = cin.ReadValueArray<int, int, long>(n - 1);
			var (q, k) = cin.ReadValue<int, int>();
			var (x, y) = cin.ReadValueArray<int, int>(q);

			var seen = new bool[n];
			var connected = new List<List<Pair<int, long>>>();
			var length = new long[n];

			k--;
			for (int i = 0; i < n; i++)
			{
				seen[i] = false;
				connected.Add(new List<Pair<int, long>>());
				length[i] = 0;
			}
			for (int i = 0; i < q; i++)
			{
				x[i]--;
				y[i]--;
			}

			for (int i = 0; i < n - 1; i++)
			{
				a[i]--;
				b[i]--;
				connected[a[i]].Add(new Pair<int, long>(b[i], c[i]));
				connected[b[i]].Add(new Pair<int, long>(a[i], c[i]));
			}

			seen[k] = true;
			var que = new Queue<int>();
			que.Enqueue(k);
			while (que.Count > 0)
			{
				var now = que.Dequeue();
				long len = length[now];
				foreach (var e in connected[now])
				{
					if (seen[e.First]) continue;
					length[e.First] = len + e.Second;
					que.Enqueue(e.First);
					seen[e.First] = true;
				}
			}
			for (int i = 0; i < q; i++)
			{
				Console.WriteLine(length[x[i]] + length[y[i]]);
			}
		}

		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);
			var cin = new Scanner();
			Solve(cin);
			Console.Out.Flush();
		}

