namespace kyoupuro {

    class Data {
        public long b;
        public long diff;
        public Data(long b, long d) {
            this.b = b;
            this.diff = d;
        }
    }

    class MainClass {

        public static void Main() {
            var N = Input.NextLong();
            var matrix = new List<Data>[N];

            for (int i = 0; i < N; i++) {
                matrix[i] = new List<Data>();
            }

            // 入力
            for (int i = 0; i < N - 1; i++) {
                var a = Input.NextLong() - 1;
                var b = Input.NextLong() - 1;
                var c = Input.NextLong();
                matrix[a].Add(new Data(b, c));
                matrix[b].Add(new Data(a, c));
            }

            var Q = Input.NextLong();
            var K = Input.NextLong() - 1;

            // 距離計算
            var diffence = Enumerable.Repeat(long.MaxValue, (int)N).ToArray();
            diffence[K] = 0;
            var queue = new Queue<long>();
            queue.Enqueue(K);
            while (queue.Any()) {
                var tmp = queue.Dequeue();

                // add + 距離
                foreach(var data in matrix[tmp].Where(x => diffence[x.b] > diffence[tmp])) {
                    diffence[data.b] = data.diff + diffence[tmp];
                    queue.Enqueue(data.b);
                }
            }

            // クエリ
            for (int i = 0; i < Q; i++) {
                var x = Input.NextInt() - 1;
                var y = Input.NextInt() - 1;
                Console.WriteLine(diffence[x] + diffence[y]);
            }
        }
    }

    class Input {
        static IEnumerator<string> enumerator = new string[] { }.AsEnumerable().GetEnumerator();

        public static string Line() {
            return Console.ReadLine();
        }

        public static int NextInt() {
            while (!enumerator.MoveNext()) {
                enumerator = StrArr().AsEnumerable().GetEnumerator();
            }
            return int.Parse(enumerator.Current);
        }

        public static long NextLong() {
            while (!enumerator.MoveNext()) {
                enumerator = StrArr().AsEnumerable().GetEnumerator();
            }
            return long.Parse(enumerator.Current);
        }

        public static string[] StrArr() {
            return Line().Split(' ');
        }

        public static List<int> IntList() {
            return StrArr().Select(int.Parse).ToList();
        }

        public static List<long> LongList() {
            return StrArr().Select(long.Parse).ToList();
        }

        public static void Skip(int line = 1) {
            enumerator.Reset();
            for (int i = 0; i < line; i++) Console.ReadLine();
        }

        public static void Reset() {
            enumerator.Reset();
        }
    }
}

