using static CS_Contest.Utils;

namespace CS_Contest {
	using Li = List<int>;
	using LLi = List<List<int>>;
	class Program {
        static void Main(string[] args) {
			new Calc().Solve();
			return;
        }

		private class Calc {
			long[,] Cost;
			public void Solve() {
				int N = ReadInt();
				Cost = new long[N, N];
				REP(N, x => REP(N, y => { Cost[x, y] = INF; }));
				REP(N-1, x => {
					int a, b, c;
					ReadTriple(out a, out b, out c);
					a--;b--;
					Cost[a, b] = c;
					Cost[b, a] = c;
				});
				int Q, K;
				ReadMulti(out Q, out K);
				var toK = new List<long>();
				REP(N, x => {
					toK.Add(Dijkstra(x, N, K - 1));
				});
				REP(Q, _ => {
					int x, y;
					ReadMulti(out x, out y);
					x--;y--;
					 (toK[x] + Dijkstra(K-1, N, y)).WL();
				});
				return;
			}
			private long Dijkstra(int s,int N,int g) {
				Li prev = new Li();
				var dist = new List<long>();
				PriorityQueue<Tuple<long, int>> Q = new PriorityQueue<Tuple<long, int>>((x, y) => {
					if (x.Item1 == y.Item1) return 0;
					else if (x.Item1 < y.Item1) return -1;
					else return 1;
				});
				Q.Enqueue(new Tuple<long, int>(0,s));
				REP(N, x => {
					if (x == s) dist.Add(0);
					else dist.Add(INF);
					prev.Add(-1);
				});
				while (Q.Count!=0) {
					var src = Q.Dequeue();
					if (dist[src.Item2] < src.Item1) {
						continue;
					}

					for (int dest = 0; dest < N; dest++) {
						var cost = Cost[src.Item2, dest];
						if(cost!=INF&& dist[dest] > dist[src.Item2] + cost) {
							dist[dest] = dist[src.Item2] + cost;
							Q.Enqueue(new Tuple<long, int>(dist[dest], dest));
							prev[dest] = src.Item2;
						}
					}
				}
				return dist[g];
			}
		}
    }



    public static class Utils {
		public static int ModValue = (int)(1e9+7);
		public static long INF = long.MaxValue;
		public static long Mod(long x) => x % ModValue;
		public static long ModPow(long x,long n) { long tmp = 1; while (n != 0) { if (n % 2 == 1) { tmp = Mod(tmp * x); }x = Mod(x * x);n /= 2; }return tmp; }
		public static long DivMod(long x, long y) => Mod(x * ModPow(y, (long)(1e9 + 5)));
        public static void WL(this object obj) => WriteLine(obj);
        public static void WL(this string obj) => WriteLine(obj);
