namespace AtCoder.ABC070
{
    class Program
    {
        static int n;
        static int[,] M;
        static bool[] isFinal;
        static long[] d;
        static int[] parent;
        static void Main()
        {
            n = int.Parse(Console.ReadLine());
            M = new int[n, n];
            isFinal = new bool[n];
            d = Enumerable.Repeat(long.MaxValue, n).ToArray();
            parent = new int[n];
            for (int i = 0; i < n - 1; i++)
            {
                int[] inputs = Console.ReadLine().Split(' ')
                            .Select(int.Parse)
                            .ToArray();
                M[inputs[0] - 1, inputs[1] - 1] = inputs[2];
                M[inputs[1] - 1, inputs[0] - 1] = inputs[2];
            }
            int[] qk = Console.ReadLine().Split(' ')
                        .Select(int.Parse)
                        .ToArray();
            int q = qk[0];
            int k = qk[1] - 1;
            var x = new int[q];
            var y = new int[q];
            for (int i = 0; i < q; i++)
            {
                int[] xy = Console.ReadLine().Split(' ')
                            .Select(elem => int.Parse(elem) - 1)
                            .ToArray();
                x[i] = xy[0];
                y[i] = xy[1];
            }

            Dijkstra(k);
            for (int i = 0; i < q; i++)
            {
                Console.WriteLine(d[x[i]] + d[y[i]]);
            }
        }

        static void Dijkstra(int root)
        {
            d[root] = 0;
            parent[root] = -1;
            int u = -1;
            while (true)
            {
                long mincost = long.MaxValue;
                for (int i = 0; i < n; i++)
                {
                    if (!isFinal[i] && d[i] < mincost)
                    {
                        mincost = d[i];
                        u = i;
                    }
                }
                if (mincost == long.MaxValue || u == -1) break;
                isFinal[u] = true;

                for (int v = 0; v < n; v++)
                {
                    if (!isFinal[v] && M[u, v] != 0)
                    {
                        if (d[u] + M[u, v] < d[v])
                        {
                            d[v] = d[u] + M[u, v];
                            parent[v] = u;
                        }
                    }
                }
            }
        }
    }
}

