        static void Dfs(int v,long tmp)
        {
            for (int i = 0; i < vs.Count(); i++)
            {
                if (graph[v,i] > 0 && vs[i] == false)
                {
                    vs[i] = true;
                    ans[i] = graph[v, i] + tmp;
                    Dfs(i, ans[i]);
                    vs[i] = false;
                }
            }
            return;
        }
