using System;
using System.Collections.Generic;
using System.Text;
using System.Linq;

class Program
{
    void solve()
    {
        string[] str;
        int N = int.Parse(Console.ReadLine());

        long[,] dist = new long[N + 1, N + 1];
        long[] distK = new long[N + 1];

        for (int i = 0; i < N - 1; ++i)
        {
            str = Console.ReadLine().Split(' ');
            int a = int.Parse(str[0]);
            int b = int.Parse(str[1]);
            long c = long.Parse(str[2]);
            dist[a, b] = c;
            dist[b, a] = c;
        }

        str = Console.ReadLine().Split(' ');
        int Q = int.Parse(str[0]);
        int K = int.Parse(str[1]);

        Queue<int> que = new Queue<int>();
        que.Enqueue(K);

        while (que.Count > 0)
        {
            int t = que.Dequeue();
            for (int i = 1; i < N + 1; ++i)
            {
                if (i == t) continue;

                if (dist[i, t] != 0)
                {
                    if (distK[i] == 0) {
                        que.Enqueue(i);
                        distK[i] = distK[t] + dist[i, t];
                    }
                }
            }
        }

        for (int i = 0; i < Q; ++i)
        {
            str = Console.ReadLine().Split(' ');
            int x = int.Parse(str[0]);
            int y = int.Parse(str[1]);

            Console.WriteLine(distK[x] + distK[y]);
        }
    }

    public static int Main()
    {
        bool loop = false;
#if ES_DEBUG
        loop = true;
#endif
        do
        {
            new Program().solve();
        } while (loop);
        return 0;
    }
}

