                graph[b].Add(new Tuple<int, long>(a, c));
            }

            var QK = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
            var Q = QK[0];
            var K = QK[1];

            var dict = new Dictionary<int, long[]>();
            dict[K - 1] = Bfs(graph, K - 1);

            var query = new Tuple<int, int>[Q];
            for (var i = 0; i < Q; i++)
            {
                var xy = Console.ReadLine().Trim().Split(' ').Select(int.Parse).ToArray();
                query[i] = new Tuple<int, int>(xy[0] - 1, xy[1] - 1);
            }

            for (var i = 0; i < Q; i++)
            {
                var x = query[i].Item1;
                var y = query[i].Item2;

                if (!dict.ContainsKey(x)) dict[x] = Bfs(graph, x);
                Console.WriteLine(dict[x][K - 1] + dict[K - 1][y]);
            }
        }

        static long[] Bfs(List<Tuple<int, long>>[] graph, int x)
        {
            var n = graph.Count();
            var queue = new Queue<int>();
            queue.Enqueue(x);
            var depths = Enumerable.Repeat(-1, n).ToArray();
            depths[x] = 0;
            var costs = Enumerable.Repeat((long)1e18 + 1, n).ToArray();
            costs[x] = 0;
            while (queue.Any())
            {
                var current = queue.Dequeue();
                foreach (var next in graph[current])
                {
                    if (costs[next.Item1] <= costs[current] + next.Item2) continue;
                    depths[next.Item1] = depths[current] + 1;
                    costs[next.Item1] = costs[current] + next.Item2;
                    queue.Enqueue(next.Item1);
                }
            }

            return costs;
        }
    }
}

