{
    public class Program
    {
        public static void Main() { var r = GetResult(); Debug.WriteLine(r); Console.Write(r); }

        private static object GetResult()
        {
            var N = ReadLong();
            var dist = Enumerable.Range(0, (int)N)
                .ToDictionary(x => x, y => new List<Path>());
            for (var i = 0; i < N - 1; i++)
            {
                var (a, b, c) = Read3Longs();
                a--; b--; // インデックス変換

                dist[(int)a].Add(new Path { From = a, To = b, Dist = c });
                dist[(int)b].Add(new Path { From = b, To = a, Dist = c });
            }

            var (Q, K) = Read2Longs();
            K--;//インデックス変換
            var distK = new long[N];
            distK[K] = 0;
            var q = new Queue<Path>();
            var removeIndexes = new List<int>();
            foreach (var item in dist[(int)K])
            {
                q.Enqueue(item);
                removeIndexes.Add(dist[(int)K].IndexOf(item));
            }

            foreach (var remove in removeIndexes.OrderByDescending(x => x))
            {
                dist[(int)K].RemoveAt(remove);
            }

            while (q.Count > 0)
            {
                var dq = q.Dequeue();

                distK[dq.To] = distK[dq.From] + dq.Dist;
                var removes = new List<int>();
                foreach (var item in dist[(int)dq.To])
                {
                    if (distK[item.To] != 0)
                    {
                        removes.Add(dist[(int)dq.To].IndexOf(item));
                        continue;
                    }
                    q.Enqueue(item);
                }

                foreach (var remove in removes.OrderByDescending(x => x))
                {
                    dist[(int)dq.To].RemoveAt(remove);
                }
            }

            var sb = new StringBuilder();
            for (var i = 0; i < Q; i++)
            {
                var (x, y) = Read2Longs();
                x--; y--;//インデックス変換
                var d = distK[x] + distK[y];
                sb.AppendLine(d.ToString());
            }

            return sb.ToString().Trim();
        }

        private class Path
        {
            public long From { get; set; }
            public long To { get; set; }
            public long Dist { get; set; }
        }

