            }
            for (int i = 0; i < N - 1; i++) {
                Key = getKeys();
                Linked[Key[0] - 1].Add(new KeyValuePair<int, long>(Key[1] - 1, Key[2]));
                Linked[Key[1] - 1].Add(new KeyValuePair<int, long>(Key[0] - 1, Key[2]));
