        static ulong gcd(ulong p, ulong q)
        {
            if (p < q)
            {
                ulong temp = p;
                p = q;
                q = temp;
            }

            ulong r = 1;

            while (r != 0)
            {
                r = p % q;
                p = q;
                q = r;
            }

            return p;
        }
