public static class Graph
{
  public static long[] dijkstra(List<Tuple<long, int>>[] edge, int from, long INF = Math2.INFL)
  {
    long[] ret = Enumerable.Range(0, edge.Length).Select(_ => INF).ToArray();
    var pq = new PriorityQueue<Tuple<long, int>>((a, b) => (int)(a.Item1 - b.Item1));
    ret[from] = 0;
    pq.Enqueue(new Tuple<long, int>(0, from));
    while (pq.Count > 0)
    {
      var p = pq.Dequeue();
      var v = p.Item2;
      if (ret[v] < p.Item1) continue;
      foreach (var e in edge[v])
      {
        if (ret[e.Item2] > ret[v] + e.Item1)
        {
          ret[e.Item2] = ret[v] + e.Item1;
          pq.Enqueue(new Tuple<long, int>(ret[e.Item2], e.Item2));
        }

      }
    }
    return ret;
  }
}


public class PriorityQueue<T>
{
  List<T> _item;
  public int Count { get { return _item.Count; } }
  bool _isascend { get; set; }
  public T Peek { get { return _item[0]; } }
  Comparison<T> Comp;
  public PriorityQueue(bool IsAscend = true, IEnumerable<T> list = null) : this(Comparer<T>.Default.Compare, IsAscend, list) { }
  public PriorityQueue(Comparison<T> cmp, bool IsAscend = true, IEnumerable<T> list = null)
  {
    _item = new List<T>();
    _isascend = IsAscend;
    this.Comp = cmp;
    if (list != null)
    {
      _item.AddRange(list);
      Build();
    }
  }

  private int Compare(int i, int j) => (_isascend ? -1 : 1) * Comp(_item[i], _item[j]);
  private void Swap(int i, int j) { var t = _item[i]; _item[i] = _item[j]; _item[j] = t; }
  private int Parent(int i)
      => (i - 1) >> 1;
  private int Left(int i)
      => (i << 1) + 1;
  public T Enqueue(T val)
  {
    int i = _item.Count;
    _item.Add(val);
    while (i > 0)
    {
      int p = Parent(i);
      if (Compare(i, p) > 0)
        Swap(i, p);
      i = p;
    }
    return val;
  }
  private void Heapify(int index)
  {
    for (int i = index, j; (j = Left(i)) < _item.Count; i = j)
    {
      if (j != _item.Count - 1 && Compare(j, j + 1) < 0) j++;
      if (Compare(i, j) < 0)
        Swap(i, j);
    }
  }
  public T Dequeue()
  {
    T val = _item[0];
    _item[0] = _item[_item.Count - 1];
    _item.RemoveAt(_item.Count - 1);
    Heapify(0);
    return val;
  }
  private void Build()
  {
    for (var i = (_item.Count >> 1) - 1; i >= 0; i--)
      Heapify(i);
  }
}



public static class Math2
{
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power(long a, long b, long MOD = 1000000007)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2(long a, long b)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD(long a, long b)
  {
    while (b > 0)
    {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM(long a, long b) => (b / GCD(a, b)) * a;
  public static long Comb(long n, long r, int MOD = 1000000007)
  {
    long ret = 1;
    long x = 1;
    for (long i = n; i >= n - r + 1; --i)
    {
      ret = ret / x * i;
      ret %= MOD;
      x++;
    }
    return ret;
  }
  public static long Comb2(long n, long r)
  {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i)
    {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
}
