        static long[] getDistanceFromEntry(List<List<KeyValuePair<int, long>>> Linked) {
            long[] distance = new long[N];
            foreach (var item in Linked[EntryNode]) {
                distance[item.Key] = item.Value;
            }
            var Visited = new bool[N];
            Queue<int> nodes = new Queue<int>();
            nodes.Enqueue(EntryNode);
            while (nodes.Count > 0 && Visited.Any(t => t == false)) {
                var n = nodes.Dequeue();
                foreach (var item in Linked[n].Where(pair => !Visited[pair.Key])) {
                    distance[item.Key] = distance[n] + item.Value;
                    nodes.Enqueue(item.Key);
                    Visited[item.Key] = true;
                }
            }
            return distance;
        }
