    static void Solve()
    {
        var num = Input.num;
        var ps = P.Make(num, num - 1);
        var qk = Input.ar;
        ps[qk[1] - 1].Weight = 0;
        var que = new Queue<P>();
        que.Enqueue(ps[qk[1]-1]);
        while (que.Count != 0)
        {
            var p = que.Dequeue();
            foreach (var ad in p.adj)
            {
                if (ps[ad].Weight != Input.Inf || ad == qk[1] - 1) continue;
                ps[ad].Weight = p.Weight + p.dist[ad];
                que.Enqueue(ps[ad]);
            }
        }
        var res = new long[qk[0]];
        for(var i = 0; i < qk[0]; i++)
        {
            var xy = Input.ar;
            res[i] = ps[xy[0] - 1].Weight + ps[xy[1] - 1].Weight;
        }
