                    Enumerable.Repeat(0, d1).Select(_ =>
                    Enumerable.Repeat(0, d2).Select(__ =>
                     Enumerable.Repeat(v, d3).ToArray()).ToArray()).ToArray();
            }
        }
        #endregion
    }
}

using System;
using System.Collections.Generic;

class ABC070D
{
	static public void Main(string[] args)
	{
		int N = int.Parse(Console.ReadLine());
		List<int>[] dest = new List<int>[N+1];
		for(int i=1; i<=N; i++)
		{
			dest[i] = new List<int>();
		}
		List<long>[] cost = new List<long>[N+1];
		for(int i=1; i <= N; i++)
		{
			cost[i] = new List<long>();
		}

		int a, b;
		long c;
		string[] vals;
		for(int i=1; i <= N-1; i++)
		{
			vals = Console.ReadLine().Split(' ');
			a = int.Parse(vals[0]);
			b = int.Parse(vals[1]);
			c = long.Parse(vals[2]);
			dest[a].Add(b);
			cost[a].Add(c);
			dest[b].Add(a);
			cost[b].Add(c);
		}
		int Q,K;
		vals = Console.ReadLine().Split(' ');
		Q = int.Parse(vals[0]);
		K = int.Parse(vals[1]);
		long[] distance = new long[N+1];
		distance[K] = 0;
		Queue<int> q = new Queue<int>();
		q.Enqueue(K);
		int t;
		while(q.Count > 0)
		{
			t = q.Dequeue();
			for(int i=0; i < dest[t].Count; i++)
			{
				if(distance[dest[t][i]] > 0)
					continue;
				distance[dest[t][i]] = distance[t] + cost[t][i];
				q.Enqueue(dest[t][i]);
			}
		}
		int[,] query = new int[Q, 2];
		for(int i=0; i < Q; i++)
		{
			vals = Console.ReadLine().Split(' ');
			query[i,0] = int.Parse(vals[0]);
			query[i,1] = int.Parse(vals[1]);
		}
		for(int i=0; i < Q; i++)
		{
			Console.WriteLine(distance[query[i,0]] + distance[query[i,1]]);
		}
	}
}

