    class Program
    {
        private const int MODULO = 1000000007;
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        class Solver
        {
            private long[][] costs;
            public Solver(int N, int[][] paths)
            {
                costs = new long[N][];
                for (int i = 0; i < N; ++i)
                {
                    var q = new Queue<int>();
                    costs[i] = Enumerable.Repeat(long.MaxValue, N).ToArray();
                    costs[i][i] = 0;
                    q.Enqueue(i);
                    while (q.Count > 0)
                    {
                        int j = q.Dequeue();
                        for (int k = 0; k < N; ++k)
                        {
                            if (paths[j][k] < int.MaxValue && costs[i][k] > costs[i][j] + paths[j][k])
                            {
                                costs[i][k] = costs[i][j] + paths[j][k];
                                q.Enqueue(k);
                            }
                        }
                    }
                }
            }
            public IEnumerable<long> Solve(int Q, Tuple<int, int>[] queries, int K)
            {
                var answers = new long[Q];
                for (int i = 0; i < Q; ++i)
                {
                    int x = queries[i].Item1;
                    int y = queries[i].Item2;
                    answers[i] = costs[x][K] + costs[K][y];
                }
                return answers;
            }
        }
        static void Main(string[] args)
        {
            int N = ReadInt();
            var paths = new int[N][];
            for (int i = 0; i < N; ++i) { paths[i] = Enumerable.Repeat(int.MaxValue, N).ToArray(); }
            for (int i = 0; i < N - 1; ++i)
            {
                int[] v2 = ReadInts();
                int a = v2[0] - 1;
                int b = v2[1] - 1;
                int c = v2[2];
                paths[a][b] = c;
                paths[b][a] = c;
            }
            int[] v1 = ReadInts();
            int Q = v1[0];
            int K = v1[1] - 1;
            var queries = new Tuple<int, int>[Q];
            for (int i = 0; i < Q; ++i)
            {
                int[] v2 = ReadInts();
                queries[i] = new Tuple<int, int>(v2[0] - 1, v2[1] - 1);
            }
            foreach (var ans in new Solver(N, paths).Solve(Q, queries, K))
            {
                Console.WriteLine(ans);
            }
        }
    }
}

