        static T[,] getUniform<T>(int row,int col, T value) {
            T[,] Ts = new T[row, col];
            for (int i = 0; i < row; i++) {
                for (int j = 0; j < col; j++) {
                    Ts[j, i] = value;
                }
            }
            return Ts;
        }
        static void setUniform<T>(T[,] ts, T value) {
            int N = ts.GetLength(0);
            int M = ts.GetLength(1);
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < N; j++) {
                    ts[j, i] = value;
                }
            }
        }

        static int N, EntryNode;
        static long[,] distance;
        static void Main() {
            var Key = getKeys();
            N = Key[0];
            distance = getUniform(N, N, -1L);
            for (int i = 0; i < N - 1; i++) {
                Key = getKeys();
                distance[i, i] = 0;
                distance[Key[0] - 1, Key[1] - 1] = Key[2];
                distance[Key[1] - 1, Key[0] - 1] = Key[2];
            }
            distance[N - 1, N - 1] = 0;
            Key = getKeys();
            int Q = Key[0];
            EntryNode = Key[1] - 1;
            getDistanceFrom();
            for (int i = 0; i < Q; i++) {
                Key = getKeys();
                Console.WriteLine(distance[EntryNode,Key[0] - 1] + distance[EntryNode, Key[1] - 1]);
            }
        }


        static void getDistanceFrom() {
            var visited = new bool[N];
            visited[EntryNode] = true;
            int next = EntryNode;
            while (visited.Any(t => t == false)) {
                update(next);
                visited[next] = true;
                next = getMinNode(next,visited);
            }
        }

        static void update(int from) {
            for (int i = 0; i < N; i++) {
                if (distance[from, i] > 0) {
                    distance[EntryNode, i] = Math.Min((distance[EntryNode,i]==-1)?long.MaxValue:distance[EntryNode, i], distance[EntryNode, from] + distance[from, i]);
//                    Console.WriteLine("distance[" + EntryNode + ", " + i + "] =" + "Math.Min(" + distance[EntryNode, i] + ", " + distance[EntryNode, from] + "+" + distance[from, i]);
                }
            }
        }
        static int getMinNode(int from,bool[] visited) {
            long min = long.MaxValue;
            int index = 0;
            for (int i = 0; i < N; i++) {
                if (!visited[i] && distance[from, i] > 0 && min > distance[from, i]) {
                    min = distance[from, i];
                    index = i;
                }
            }
            return index;
        }
    }
