function myconv(i,no){try{switch(no){case 1:return parseInt(i);case 2:return i.split(" ");case 4:return i.split(" ").map((a)=>Number(a));case 6:return i.split("");case 7:return i.split("").map((a)=>Number(a));case 8:return i.join(" ");case 9:return i.join("\n");case 0:return i.join("");default:return i;}}catch(e){return i;}}
function Main(){
  var N = nextInt();
	var list = new Array(N);
	for(var i = 0; i < N; i++){
		list[i] = {
			accessed : false,
			children : {},
			kyori : 0
		};
	}
	for(var i = 0; i < N - 1; i++){
		var tmp = nextIntArray();
		list[tmp[0] - 1]["children"][tmp[1] - 1] = tmp[2];
		list[tmp[1] - 1]["children"][tmp[0] - 1] = tmp[2];
	}
	var two = nextIntArray();
	var Q = two[0];
	var K = two[1] - 1;
	list[K]["accessed"] = true;
	var queue = [K];
	while(queue.length > 0){
		var tmp = queue.shift();
		var keys = Object.keys(list[tmp]["children"]);
		for(var i = 0; i < keys.length; i++){
			if(list[keys[i]]["accessed"]){continue;}
			list[keys[i]]["accessed"] = true;
			list[keys[i]]["kyori"] += list[tmp]["children"][keys[i]] + list[tmp]["kyori"];
			queue.push(keys[i]);
		}
	}
	var output = new Array(Q);
	for(var i = 0; i < Q; i++){
		var tmp = nextIntArray();
		tmp[0]--;
		tmp[1]--;
		output[i] = list[tmp[0]]["kyori"] + list[tmp[1]]["kyori"];
	}
	myout(myconv(output,9));
}

