Path = Struct.new(:node, :distance)

def calc_distances(from, distance)
  @neighbors[from].each do |n|
    next if @from_k[n.node] > -1
    d = distance + n.distance
    @from_k[n.node] = d
    calc_distances(n.node, d)
  end
end

def calc_distances_non_recursive(from)
  stack = [Path.new(from, 0)]

  until stack.empty?
    n = stack.pop
    @neighbors[n.node].each do |m|
      next if @from_k[m.node] != -1
      d = n.distance + m.distance
      @from_k[m.node] = d
      stack.push(Path.new(m.node, d))
    end
  end
end

