func dfs(before, start int, a [][]int, cost []int) {
	for i := 0; i < len(a[start]); i = i + 2 {
		next, c := a[start][i], a[start][i+1]
		if before != next {
			cost[next] = cost[start] + c
			dfs(start, next, a, cost)
		}
	}
}

