type Graph struct {
	n        int
	edges    map[int]map[int]int
	distance []int
}

func NewGraph(n int) *Graph {
	g := &Graph{
		n:        n,
		edges:    make(map[int]map[int]int, n),
		distance: make([]int, n),
	}
	for i := 0; i < n; i++ {
		g.edges[i] = make(map[int]int)
	}
	return g
}

func (g *Graph) AddEdge(u, v, d int) {
	g.edges[v][u] = d
	g.edges[u][v] = d
}

func dfs(c int, edges [][]int, visited map[int]struct{}) {
	visited[c] = struct{}{}

	for _, v := range edges[c] {
		_, flag := visited[v]
		if flag {
			continue
		}
		dfs(v, edges, visited)
	}
}

func bfs(c int, graph *Graph) {
	next := make([]int, 0)
	next = append(next, c)
	visited := make(map[int]struct{})

	for ; len(next) != 0; {
		u := next[0]
		next = next[1:]
		visited[u] = struct{}{}

		for v, d := range graph.edges[u] {
			_, flag := visited[v]
			if flag {
				continue
			}

			graph.distance[v] = graph.distance[u] + d

			next = append(next, v)
		}
	}
}

