func solve() {
	n := ri()
	type e struct{ t, c int }
	g := make([][]e, n)
	for i := 0; i < n-1; i++ {
		a, b, c := ri()-1, ri()-1, ri()
		g[a] = append(g[a], e{b, c})
		g[b] = append(g[b], e{a, c})
