var dist []int

const inf = 100100100100000

func dijkstra(s, N int) {
	dist = make([]int, N)
	for i := 0; i < N; i++ {
		dist[i] = inf
	}
	pq := priorityQueue{}
	heap.Push(&pq, pqi{s})
	dist[s] = 0
	for len(pq) > 0 {
		n := heap.Pop(&pq).(pqi).a
		for _, e := range node[n] {
			if dist[e.to] > dist[n]+e.cost {
				dist[e.to] = dist[n] + e.cost
				heap.Push(&pq, pqi{e.to})
			}
		}
	}
}

