	to   int
	cost uint
}

func dfs(graph [][]edge, costs []uint, node int, prev int, totalCost uint) {
	paths := graph[node]
	for _, p := range paths {
		if p.to != prev {
			cost := totalCost + p.cost
			costs[p.to] = cost
			dfs(graph, costs, p.to, node, cost)
		}
	}
}

