type edge struct {
	to, weight int
}

type node struct {
	dist     int
	visited  bool
	edgeList []edge
}

type graph []node

func DFS(G *graph, K int) {
	(*G)[K].visited = true
	for _, ed := range (*G)[K].edgeList {
		if !(*G)[ed.to].visited {
			(*G)[ed.to].dist = (*G)[K].dist + ed.weight
			DFS(G, ed.to)
		}
	}
}

func main() {
