	for i := 0; i < n-1; i++ {
		a := nextInt() - 1
		b := nextInt() - 1
		c := nextInt()
		es[a] = append(es[a], Edge{b, c})
		es[b] = append(es[b], Edge{a, c})
	}

	q := nextInt()
	k := nextInt() - 1

	ds := make([]int, n)
	for i := 0; i < n; i++ {
		ds[i] = -1
	}
	ds[k] = 0

	var dfs func(v int)
	dfs = func(v int) {
		for _, e := range es[v] {
			if ds[e.to] != -1 {
				continue
			}
			ds[e.to] = ds[v] + e.cost
			dfs(e.to)
		}
	}
	dfs(k)

	for i := 0; i < q; i++ {
		x := nextInt() - 1
		y := nextInt() - 1
		fmt.Println(ds[x] + ds[y])
	}
}

