func solve() {
	n := ri()
	type edge struct{ t, c int }
	g := make([][]edge, n)
	for i := 0; i < n-1; i++ {
		a, b, c := ri()-1, ri()-1, ri()
		g[a] = append(g[a], edge{t: b, c: c})
		g[b] = append(g[b], edge{t: a, c: c})
	}
	q, k := ri(), ri()-1
	a := make([]int, n)
	var dfs func(int, int, int)
	dfs = func(v, p, d int) {
		a[v] = d
		for _, nv := range g[v] {
			if nv.t == p {
				continue
			}
			dfs(nv.t, v, d+nv.c)
		}
	}
	dfs(k, -1, 0)
	for i := 0; i < q; i++ {
		x, y := ri()-1, ri()-1
		pln(a[x] + a[y])
	}
}

