package main

import (
	"bufio"
	"fmt"
	"os"
)

type graph [][]int

var sc = bufio.NewScanner(os.Stdin)

func nextLine() string {
	sc.Scan()
	return sc.Text()
}

func bfs(n int, g graph) []int {
	lengths := make([]int, len(g))
	visited := make([]bool, len(g))

	queue := make([]int, 0)
	queue = append(queue, n)
	lengths[n] = 0
	visited[n] = true

	for len(queue) > 0 {
		q := queue[0]
		queue = queue[1:]
		for i := range g[q] {
			if g[q][i] > 0 && !visited[i] {
				queue = append(queue, i)
				lengths[i] = g[q][i] + lengths[q]
				visited[i] = true
			}
		}
	}

	return lengths
}

func main() {
	var N, Q, K int
	fmt.Sscan(nextLine(), &N)

	g := make(graph, N)
	for i := range g {
		g[i] = make([]int, N)
	}

	for i := 0; i < N-1; i++ {
		var a, b, c int
		fmt.Sscan(nextLine(), &a, &b, &c)
		g[a-1][b-1] = c
		g[b-1][a-1] = c
	}

	fmt.Sscan(nextLine(), &Q, &K)

	lengths := bfs(K-1, g)

	for i := 0; i < Q; i++ {
		var x, y int
		fmt.Sscan(nextLine(), &x, &y)
		fmt.Println(lengths[x-1] + lengths[y-1])
	}
}

