}

func dijkstra(G [][]Edge, D []int, k int) {
	pq := &PQ{}
	heap.Init(pq)
	done := make([]bool, len(D))
	heap.Push(pq, Element{k, 0})
	for pq.Len() > 0 {
		cur := heap.Pop(pq).(Element).id
		if done[cur] {
			continue
		}
		done[cur] = true
		for i := 0; i < len(G[cur]); i++ {
			next, cost := G[cur][i].to, G[cur][i].cost
			if done[next] {
				continue
			}
			if D[cur]+cost < D[next] {
				D[next] = D[cur] + cost
				heap.Push(pq, Element{next, D[next]})
			}
		}
	}
}

