func main() {
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, initialBufSize), maxBufSize)
	defer wt.Flush()

	n := nextInt()

	d := NewDijkstra(n)
	for i := 0; i < n-1; i++ {
		a, b, c := nextInt()-1, nextInt()-1, nextInt()
		d.AddEdge(a, b, c)
	}

	q, k := nextInt(), nextInt()-1
	d.Search(k)
	for i := 0; i < q; i++ {
		x, y := nextInt()-1, nextInt()-1
		puts(d.Cost[x] + d.Cost[y])
	}
}

