func NextLine() string {
  var line,buffer []byte
  var isPrefix bool = true
  var err error
  for ;isPrefix; {
    line,isPrefix,err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
  }
  return string(buffer)
}
func NextInt() int {
  var x int
  x,_ = strconv.Atoi(NextLine())
  return x
}
func Next2Ints() (int,int) {
  var x,y int
  var s []string = strings.Split(NextLine()," ")
  x,_ = strconv.Atoi(s[0])
  y,_ = strconv.Atoi(s[1])
  return x,y
}
func Next3Ints() (int,int,int) {
  var x,y,z int
  var s []string = strings.Split(NextLine()," ")
  x,_ = strconv.Atoi(s[0])
  y,_ = strconv.Atoi(s[1])
  z,_ = strconv.Atoi(s[2])
  return x,y,z
}

func main() {
  const infty int64 = 9223372036854775800
  var n int = NextInt()
  var edge [][]int = make([][]int,n)
  var cost [][]int64 = make([][]int64,n)
  for i:=0;i<n;i++ {
    edge[i] = []int{}
    cost[i] = []int64{}
  }
  var a,b,c int
  for i:=0;i<n-1;i++ {
    a,b,c = Next3Ints()
    a,b = a-1,b-1
    edge[a] = append(edge[a],b)
    cost[a] = append(cost[a],int64(c))
    edge[b] = append(edge[b],a)
    cost[b] = append(cost[b],int64(c))
  }
  var q,k int = Next2Ints()
  k--
  var w []int64 = make([]int64,n)
  set := make(map[int]struct{})
  for j:=0;j<n;j++ {
    w[j] = infty
    set[j] = struct{}{}
  }
  w[k] = 0
  var min int64 = 0
  for len(set) > 0 {
    for u,_ := range set {
      if w[u] != min { continue }
      for j:=0;j<len(edge[u]);j++ {
        if w[edge[u][j]] > min + cost[u][j] {
          w[edge[u][j]] = min + cost[u][j]
        }
      }
      delete(set,u)
    }
    var tmin int64 = infty
    for j:=0;j<n;j++ {
      if tmin > w[j] && w[j] > min { tmin = w[j] }
    }
    min = tmin
  }
  for i:=0;i<q;i++ {
    var x,y int = Next2Ints()
    x,y = x-1,y-1
    fmt.Println(w[x]+w[y])
  }
}

