	for i := 0; i < n-1; i++ {
		fmt.Fscan(r, &a)
		fmt.Fscan(r, &b)
		fmt.Fscan(r, &c)
		a--
		b--
		tree[a] = append(tree[a], edge{to: b, cost: c})
		tree[b] = append(tree[b], edge{to: a, cost: c})
	}

	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()

	var q, k int
	fmt.Fscan(r, &q)
	fmt.Fscan(r, &k)
	k--
	dfs(k, -1, 0)

	var x, y int
	for i := 0; i < q; i++ {
		fmt.Fscan(r, &x)
		fmt.Fscan(r, &y)
		x--
		y--

		fmt.Fprintln(w, depth[x]+depth[y])
	}
}

