	for i := 0; i < q; i++ {
		a := scanInt(sc)
		b := scanInt(sc)
		cost := costs[a] + costs[b]
		fmt.Println(cost)
	}
}

func scanInt(sc *bufio.Scanner) int {
	sc.Scan()
	v, _ := strconv.Atoi(sc.Text())
	return v
}

func calcCosts(graph graph, costs []int, from int, prev int, totalCost int) {
	paths := graph[from]
	for _, p := range paths {
		if p.node != prev {
			cost := totalCost + p.cost
			costs[p.node] = cost
			calcCosts(graph, costs, p.node, from, cost)
		}
	}
}

