const INF = 100000000000


/*********** PriorityQueue ***********/
type PriorityQueue struct {
    arr []interface{}
    comp CompFunc
}

type CompFunc func(p, q interface{}) bool

func NewPriorityQueue() *PriorityQueue {
    return new(PriorityQueue)
}

func (pq PriorityQueue) Len() int {
    return len(pq.arr)
}

func (pq PriorityQueue) Swap(i, j int) {
    pq.arr[i], pq.arr[j] = pq.arr[j], pq.arr[i]
}

func (pq PriorityQueue) Less(i, j int) bool{
    return pq.comp(pq.arr[i], pq.arr[j])
}

func (pq *PriorityQueue) Push(x interface{}) {
    pq.arr = append(pq.arr, x)
}

func (pq *PriorityQueue) Pop() interface{} {
    n := pq.Len()
    item := pq.arr[n - 1]
    pq.arr = pq.arr[:n - 1]
    return item
}

func (pq *PriorityQueue) IsEmpty() bool {
    return pq.Len() == 0
}

/* type for edge */
type Edge struct {
    to int
    cost int
}

/* type for dijkstra */
type State struct {
    time int
    node int
}

/* dijkstra */

func dijkstra(start int, edges [][]Edge, n int, comp CompFunc) []int {
    var dist []int
    for i := 0; i < n; i++ {
        dist = append(dist, INF)
    }
    dist[start] = 0
    que := new(PriorityQueue)
    que.comp = comp
    heap.Push(que, State{time: 0, node:start})
    for !que.IsEmpty() {
        state := heap.Pop(que).(State)
        for _, edge := range edges[state.node] {
            newTime := state.time + edge.cost
            if dist[edge.to] > newTime {
                dist[edge.to] = newTime
                heap.Push(que, State{time: newTime, node: edge.to})
            }
        }
    }
    return dist
}
/* input */
var sc = bufio.NewScanner(os.Stdin)

