    n := readInt()
    var edges [][]Edge
    for i := 0; i < n; i++ {
        edges = append(edges, make([]Edge, 0))
    }
    for i := 0; i < n - 1; i++ {
        a, b, c := readInt() - 1, readInt() - 1, readInt()
        edges[a] = append(edges[a], Edge{to: b, cost: c})
        edges[b] = append(edges[b], Edge{to: a, cost: c})
    }

    var comp CompFunc
    comp = func(p, q interface{}) bool {
        return p.(State).time < q.(State).time
    }

    q, k := readInt(), readInt() - 1
    dist := dijkstra(k, edges, n, comp)
    for i := 0; i < q; i++ {
        x, y := readInt() - 1, readInt() - 1
        fmt.Println(dist[x] + dist[y])
    }
}

