	dist := make(map[int64]int64)
	for i := 1; i < n; i++ {
		xs := getInts()
		a, b, c := xs[0], xs[1], int64(xs[2])
		tree[a] = append(tree[a], b)
		tree[b] = append(tree[b], a)
		dist[int64(a)*1e11+int64(b)] = c
		dist[int64(b)*1e11+int64(a)] = c
	}
	ys := getInts()
	q, k := ys[0], ys[1]
	flags := make([]bool, n+1)
	dists := make([]int64, n+1)
	flags[k] = true
	temp1 := []int{k}
	for len(temp1) > 0 {
		sz := len(temp1) - 1
		v := temp1[sz]
		temp1 = temp1[:sz]
		d := dists[v]
		for _, w := range tree[v] {
			if flags[w] {
				continue
			}
			flags[w] = true
			dists[w] = d + dist[int64(v)*1e11+int64(w)]
			temp1 = append(temp1, w)
		}
	}
	for i := 0; i < q; i++ {
		xs := getInts()
		x, y := xs[0], xs[1]
		fmt.Println(dists[x] + dists[y])
	}
}

