func main() {
	var n, a, b, c int
	fmt.Scan(&n)
	g := NewGraph(n)
	for i := 0; i < n-1; i++ {
		fmt.Scan(&a, &b, &c)
		a--
		b--
		g.AddEdge(a, b, c)
		g.AddEdge(b, a, c)
	}

	var q, k, x, y int
	fmt.Scan(&q, &k)
	g.DijkstraSearch(k - 1)

	ans := make([]int, q)
	for i := 0; i < q; i++ {
		fmt.Scan(&x, &y)
		ans[i] = g.Cost[x-1] + g.Cost[y-1]
	}

	for i := 0; i < q; i++ {
		fmt.Println(ans[i])
	}
}

