var sc = NewScanner(os.Stdin, 1000000)

var (
	n, q, k    int
	lenMap     [][]int
	refMap     [][]int
	visitedMap []bool
)

func initVisitedMap() {
	visitedMap = make([]bool, n+1)
}

func search(curr, goal int, dist uint64) uint64 {
	if curr == goal {
		return dist
	}
	result := uint64(0)
	for _, next := range refMap[curr] {
		if visitedMap[next] == true {
			return uint64(0)
		}
		visitedMap[next] = true
		s := search(next, goal, dist+uint64(lenMap[curr][next]))
		result += s
	}
	return result
}

func main() {
	n = sc.ReadInt()

	lenMap = make([][]int, n+1)
	for i := 0; i < n+1; i++ {
		lenMap[i] = make([]int, n+1)
	}

	refMap = make([][]int, n+1)

	var a, b, c int
	for i := 0; i < n-1; i++ {
		a, b, c = sc.ReadInt(), sc.ReadInt(), sc.ReadInt()
		lenMap[a][b] = c
		lenMap[b][a] = c
		refMap[a] = append(refMap[a], b)
		refMap[b] = append(refMap[b], a)
	}

