type route struct {
	to, weight int
}

type graph [][]route

var sc = bufio.NewScanner(os.Stdin)

func nextLine() string {
	sc.Scan()
	return sc.Text()
}

var depths []int

func dfs(n int, g graph, weight int) {
	depths[n] = weight
	for i := range g[n] {
		to, w := g[n][i].to, g[n][i].weight
		if depths[to] == -1 && w > 0 {
			dfs(to, g, weight+w)
		}
	}
}

func main() {
	var N, Q, K int
	fmt.Sscan(nextLine(), &N)

	g := make(graph, N)

	for i := 0; i < N-1; i++ {
		var a, b, c int
		fmt.Sscan(nextLine(), &a, &b, &c)
		g[a-1] = append(g[a-1], route{to: b - 1, weight: c})
		g[b-1] = append(g[b-1], route{to: a - 1, weight: c})
	}

	fmt.Sscan(nextLine(), &Q, &K)

	depths = make([]int, len(g))
	for i := range depths {
		depths[i] = -1
	}
	dfs(K-1, g, 0)

	for i := 0; i < Q; i++ {
		var x, y int
		fmt.Sscan(nextLine(), &x, &y)
		fmt.Println(depths[x-1] + depths[y-1])
	}
}

module MakeBinaryHeap (M : sig type t val compare : t -> t -> int end) = struct

  type t = { node : M.t array; mutable size : int }

  let make n (init : M.t) = { node = Array.make n init; size = 0 }

  let empty_p t = if t.size = 0 then true else false

  let pop t =
    if t.size <= 0 then failwith "out of size" else
    let rec max_heapify i =
      let l = 2*i in
      let r = 2*i + 1 in
      let m = if l <= t.size && M.compare t.node.(l) t.node.(i) > 0 then l else i in
      let m = if r <= t.size && M.compare t.node.(r) t.node.(m) > 0 then r else m in
      if m = i then ()
      else begin
        let tmp = t.node.(i) in
        t.node.(i) <- t.node.(m);
        t.node.(m) <- tmp;
        max_heapify m
      end in
    let ret = t.node.(1) in
    t.node.(1) <- t.node.(t.size);
    t.size <- t.size - 1;
    max_heapify 1;
    ret

  let push x t =
    let parent i = int_of_float (floor (float_of_int i) /. 2.) in
    let rec doit i =
      let p = parent i in
      if i <= 1 || M.compare t.node.(p) t.node.(i) >= 0 then ()
      else begin
        let tmp = t.node.(i) in
        t.node.(i) <- t.node.(p);
        t.node.(p) <- tmp;
        doit p
      end in
    t.size <- t.size + 1;
    t.node.(t.size) <- x;
    doit t.size

end

