class Iku {
  int dist;
  long cost;
}

alias His = Tuple!(int, "now", int, "from", long, "cost");

long search(int x, int k, int n, Iku[][] adj, long[] memo)
{
  RedBlackTree!(His, (a, b) => a.cost < b.cost) queue;
  queue = new typeof(queue);
  His atom = His(x, -1, 0);
  queue.insert = atom;
  His[] hist = new His[](n + 1);
  hist[] = His(-1, -1, -1);
  while (queue.length) {
    His node = queue.front;
    queue.removeFront;
    if (hist[node.now].now != -1) {
      continue;
    }
    hist[node.now] = node;
    if (memo[node.now] != -1) {
      long cost = node.cost;
      int ite = node.from;
      while (ite != -1) {
        memo[ite] = cost - hist[ite].cost + memo[node.now];
        ite = hist[ite].from;
      }
      break;
    }
    if (node.now == k) {
      long cost = node.cost;
      int ite = node.from;
      while (ite != -1) {
        memo[ite] = cost - hist[ite].cost;
        ite = hist[ite].from;
      }
      break;
    }
    foreach (Iku iku; adj[node.now]) {
      His next = His(iku.dist, node.now, node.cost + iku.cost);
      queue.insert = next;
    }
  }
  return memo[x];
}

