    adj[l[0]] ~= left;
    Iku right = new Iku();
    right.dist = l[0];
    right.cost = l[2];
    adj[l[1]] ~= right;
  }
  long[] memo = new long[n + 1];
  memo[] = -1;
  auto l = readln.chomp.split.map!(to!int).array;
  int q = l[0];
