auto parse( Range )( Range input )
if( isInputRange!Range && is( ElementType!Range == string ) )
{
	auto n = input.front.to!( long );
	auto abcs = new long[ 3 ][ n - 1 ];
	foreach( ref abc; abcs )
	{
		input.popFront;
		abc = input.front.split.to!( long[] );
	}
	input.popFront;
	auto qk = input.front.split.to!( long[] );
	auto xys = new long[ 2 ][ qk[ 0 ] ];
	foreach( ref xy; xys )
	{
		input.popFront;
		xy = input.front.split.to!( long[] );
	}
	return tuple( n, abcs, qk[ 1 ], xys );
}

auto solve( long n, long[ 3 ][] abcs, long k, long[ 2 ][] xys )
{
	auto ds = dijkstra( n + 1, abcs, k );
	auto anss = new long[ xys.length ];
	foreach( ref ans, xy; lockstep( anss, xys ) )
	{
		ans = ds[ xy[ 0 ] ] + ds[ xy[ 1 ] ];
	}
	return anss.to!( string[] ).join( "\n" );
}

auto dijkstra( bool directed = false )( long n, long[ 3 ][] es, long s )
{
	import std.container.binaryheap;

	auto tss = new Tuple!( long, long )[][ n ];
	foreach( e; es )
	{
		tss[ e[ 0 ] ] ~= tuple( e[ 1 ], e[ 2 ] );
		static if( !directed ) tss[ e[ 1 ] ] ~= tuple( e[ 0 ], e[ 2 ] );
	}

	auto ds = new long[ n ];
	ds[] = long.max;
	ds[ s ] = 0;
	auto dc = n;
	auto queue = heapify!( ( a, b ) => b[ 1 ] < a[ 1 ] )( new Tuple!( long, long )[ es.length ], 0 );
	queue.insert( tuple( s, 0L ) );
	while( !queue.empty )
	{
		auto fi = queue.front[ 0 ];
		auto fd = queue.front[ 1 ];
		queue.popFront();
		if( ds[ fi ] < fd ) continue;
		dc--;
		if( dc == 0 ) break;
		foreach( t; tss[ fi ] )
		{
			auto td = fd + t[ 1 ];
			if( ds[ t[ 0 ] ] < td ) continue;
			ds[ t[ 0 ] ] = td;
			queue.insert( tuple( t[ 0 ], td ) );
		}
	}
	return ds;
}

