struct S {
    int node;
    long cost;
}

long[] bfs(int k, int n, S[][int] adj) {
    auto cost = new long[n + 1];
    auto used = new bool[n + 1];

    S[] q = [S(k, 0)];
    while (q.length > 0) {
        auto d = q[0];
        q = q[1 .. $];

        if (used[d.node])
            continue;
        used[d.node] = true;
        cost[d.node] = d.cost;

        if (d.node !in adj)
            continue;
        foreach (s; adj[d.node]) {
            q ~= S(s.node, d.cost + s.cost);
        }
    }
    return cost;
}

