        adj[a] ~= S(b, c);
        adj[b] ~= S(a, c);
    }

    auto qk = readints();
    int q = qk[0], k = qk[1];

    auto cost = bfs(k, n, adj);
    for (int i = 0; i < q; i++) {
        auto xy = readints();
        int x = xy[0], y = xy[1];

        auto ans = cost[x] + cost[y];
