struct UnionFind
{
	void init(long n) { par = new long[](n); foreach (i; 0..n) par[i] = i; }
	long root(long i) { return par[i] == i ? i : (par[i] = root(par[i])); }
	bool same(long i, long j) { return root(i) == root(j); }
	void unite(long i, long j) { i = root(i); j = root(j); if (i == j) return; par[i] = j; }
	long[] par;
}

long[] dijkstra(long from, long to, long[][] edges)
{
	long[] path;
	auto cost = new long[](edges.length); fill(cost, long.max); cost[from] = 0;
	long[][] open = [[from]];
	while (!open.empty)
	{
		auto n = open.front; open.popFront;
		auto p = n[0];
		foreach (i; 0..edges.length)
		{
			if (edges[p][i] == -1) continue;
			auto c = cost[p] + edges[p][i];
			if (c < cost[to] && c < cost[i]) { cost[i] = c; if (i == to) path = i ~ n; else open ~= i ~ n; }
		}
	}
	return cost[to] ~ path;
}

void main()
{
	auto N = RD!long;
	auto v = new long[2][][](N);
	foreach (i; 0..N-1)
	{
		auto a = RD!long - 1;
		auto b = RD!long - 1;
		auto c = RD!long;
		v[a] ~= [b, c];
		v[b] ~= [a, c];
	}

	auto Q = RD!long;
	auto K = RD!long - 1;
	auto par = new long[2][](N);
	par[K] = [K, 0];
	long[] open = [K];
	while (!open.empty)
	{
		//stderr.writeln(open);
		auto n = open.front; open.popFront;
		foreach (chi; v[n])
		{
			if (chi[0] == par[n][0]) continue;
			par[chi[0]] = [n, chi[1]];
			open ~= chi[0];
		}
	}

	foreach (i; 0..Q)
	{
		auto x = RD!long - 1;
		auto y = RD!long - 1;
		long ans;
		while (x != K)
		{
			ans += par[x][1];
			x = par[x][0];
		}
		while (y != K)
		{
			ans += par[y][1];
			y = par[y][0];
		}
		writeln(ans);
	}

	stdout.flush();
}

