def bfs(s, g, N, G):
    if s == g:
        return 0
    q = []
    q.append(s)
    memo = [0 for _ in range(N)]
    while q != []:
        i = q.pop()
        if i == g:
            return memo[i]
        for n in G[i]:
            if memo[n[0]] != 0:
                continue
            memo[n[0]] = memo[i] + n[1]
            q.append(n[0])
    return 0


