#多分重みつきunionfind木を実装すれば楽
class WeightedUnionFind():

    def __init__(self, n):
        self.par = [i for i in range(n+1)]
        self.rank = [0] * (n+1)
        # 親への重みを管理
        self.weight = [0] * (n+1)
    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            y = self.find(self.par[x])
            # 親への重みを追加しながら根まで走査
            self.weight[x] += self.weight[self.par[x]]
            self.par[x] = y
            return y
    def union(self, x, y, w):
        rx = self.find(x)
        ry = self.find(y)
        # xの木の高さ < yの木の高さ
        if self.rank[rx] < self.rank[ry]:
            self.par[rx] = ry
            self.weight[rx] = w - self.weight[x] + self.weight[y]
        # xの木の高さ ≧ yの木の高さ
        else:
            self.par[ry] = rx
            self.weight[ry] = -w - self.weight[y] + self.weight[x]
            # 木の高さが同じだった場合の処理
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1            
    def same(self, x, y):
        return self.find(x) == self.find(y)
    def diff(self, x, y):
        return abs(self.weight[x] - self.weight[y])

def main():
    N = int(input())
    tree = WeightedUnionFind(N)
    for _ in range(N-1):
        a,b,c = map(int,input().split())
        tree.union(a,b,c)
    Q,K = map(int,input().split())
    Ans = []
    for _ in range(Q):
        x,y = map(int,input().split())
        p = tree.find(x)
        ans = tree.diff(x,p)+2*tree.diff(p,K)+tree.diff(p,y)
        Ans.append(ans)
    for ans in Ans:
        print(ans)


