import copy
def dfs(L,start,end):
    stack = [start]

    visited = []

    path =[ 0 for i in range((len(L)+1))]

    while stack:
        node = stack.pop()
        if node == end:
            return path[end]
        for n in L[node]:
            if n[0] not in visited:

                path[n[0]] = path[node]  + n[1]

                stack.append(n[0])
                visited.append(n[0])


def bfs(L,start,end):
    que = queue.Queue()
    que.put(start)

    visited = [start]
    while not que.empty():
        q = que.get()
        if q == end:
            return visited

        for v in L[q]:
            if v[0] not in visited:
                visited.append(v[0])
                que.put(v[0])



