def BFS(N, graph, start):
    Q = []
    V = []
    prev = {}
    d = {}
    for i in range(N):
        prev[i] = None
        d[i] = float("inf")
    Q.append(start)
    d[start] = 0
    while len(V) < N:
        a = Q.pop(0)
        V.append(a)
        for b, c in graph[a].items():
            if not b in V:
                Q.append(b)
                prev[b] = a
                d[b] = d[a] + c
    return d

