def connected(ros, f):
    ls = []
    for r in ros:
        if r[0] == f:
            ls.append((r[1], r))
        elif r[1] == f:
            ls.append((r[0], r))
    return ls

def solve(ros, f, t):
    costs = {}
    routes = {}
    queue = deque([f])
    added = set()
    while True:
        p = queue.popleft()
        if p == t:
            break
        for ne in connected(ros, p):
            if ne[0] not in added:
                queue.append(ne[0])
                added.add(ne[0])
                costs[ne[0]] = ne[1][2]
                routes[ne[0]] = p
    ans = 0
    pointer = t
    while True:
        ans += costs[pointer]
        pointer = routes[pointer]
        if pointer == f:
            return ans


