    if cache.get((start,end),None) != None:
        return cache[(start,end)]
    stack = [(start, [start], 0)]
    while stack:
        (v, path, length) = stack.pop()
        for next,l in g[v]:
            if next in path: continue
            if next == end:
                cache[(start,end)] = length + 1
                return cache[(start,end)]
            else:
                stack.append((next, path + [next], length + l))

