def solve(n_query, q_query, k):
    for a, b, c in n_query:
        unite(a, b, c)
        if a == k:
            is_via_root[b] = 0
        if b == k:
            is_via_root[a] = 0

    ans = []
    for x, y in q_query:
        if x == k:
            x_to_k = 0
        # x-root-k
        elif is_via_root[x]:
            x_to_k = weight(x) + weight(k)
        # x-k-root
        else:
            x_to_k = abs(diff(x, k))
        if y == k:
            k_to_y = 0
        # y-root-k
        elif is_via_root[y]:
            k_to_y = weight(k) + weight(y)
        # y-k-root
        else:
            k_to_y = abs(diff(k, y))

        ans.append(x_to_k + k_to_y)
#        print("{0}->{1}: {2} |{3}->{4}: {5}".format(x, k, x_to_k, k, y, k_to_y))

    return ans


def unite(x, y, w):
    w += diff_weight[x]-diff_weight[y]
    rt_x = find(x)
    rt_y = find(y)
#    print("rt_x: {0} | rt_y: {1} | par[rt_x]: {2} | par[rt_y]: {3} | w: {4}".format(
#        rt_x, rt_y, par[rt_x], par[rt_y], w))

    if rt_x == rt_y:
        return
    if rank[rt_x] >= rank[rt_y]:
        par[rt_y] = rt_x
        diff_weight[rt_y] = w
        if rank[rt_x] == rank[rt_y]:
            rank[rt_x] += 1
    else:
        par[rt_x] = rt_y
        diff_weight[rt_x] = -w


def find(x):
    if par[x] < 0:
        return x
    else:
        px = find(par[x])
        diff_weight[x] += diff_weight[par[x]]
        par[x] = px
        return px


def weight(x):
    find(x)
    return diff_weight[x]


def is_same(x, y):
    return find(x) == find(y)


def diff(x, y):
    return weight(y)-weight(x)


