def connect(N,a,b,c,v):
    vs = []
    indices = []
    ws = []
    n = a.count(v)
    for i in range(n):
        if i == 0:
            indices.append(a.index(v))
        else:
            indices.append(a.index(v,indices[i-1]+1))
        ws.append(c[indices[i]])
        vs.append(b[indices[i]])
    m = b.count(v)
    for i in range(m):
        if i == 0:
            indices.append(b.index(v))
        else:
            indices.append(b.index(v,indices[i-1]+1))
        ws.append(c[indices[i]])
        vs.append(a[indices[i]])
    return (vs,indices,ws)

def minpath(N,a,b,c,k,cheat_pre,vertex,ind,w,univk):
  cheat_pre[vertex-1] = cheat_pre[k-1]+w
  vs,inds,ws = connect(N,a,b,c,vertex)
  for i in range(len(vs)):
      if cheat_pre[vs[i]-1] == 0 and vs[i] != univk:
        cheat_pre = minpath(N,a,b,c,vertex,cheat_pre,vs[i],inds[i],ws[i],univk)
  return cheat_pre

