from collections import defaultdict


def warshall_floyd(graph: dict, N: int):
    """ graph:
    {node:{node:cost,node:cost,...},
     node:{node:cost,node:cost,...},...}
    """
    INF = float("inf")
    dp = [[INF] * N for _ in range(N)]
    for i in range(N):
        dp[i][i] = 0

    # Step 1: fill dp
    for v1, edges in graph.items():
        for v2, cost in edges.items():
            dp[v1][v2] = cost

    # search
    for k in range(N):  # 中継点
        for i in range(N):  # 始点
            for j in range(N):  # 終点
                dp[i][j] = min(dp[i][k] + dp[k][j], dp[i][j])

    return dp


