from collections import deque

def dfs(graph, start, n):
    stack = deque()
    push, pop = stack.append, stack.pop
    inf = float('INF')
    costs = [inf for i in range(n)]
    visited = [False] * n
    push((start, 0))
    visited[start] = True
    costs[start] = 0

    while stack:
        a,c = pop()
        for b,cc in graph[a].items():
            if visited[b]:
                continue
            if cc + c < costs[b]:
                push((b, cc+c))
                visited[b] = True
                costs[b] = cc + c
    return costs

