    for i in range(N):
        conn[i][i] = 0
    for j in range(N - 1):
        a = A[j] - 1
        b = B[j] - 1
        conn[a][b] = min(conn[a][b], C[j])
        conn[b][a] = min(conn[b][a], C[j])
    d = warshall_floyd(conn)
