struct P {
    to: usize,
    c: u64,
}

fn walk(i: usize, p: usize, l: u64, t: &Vec<Vec<P>>, mut ll: &mut Vec<u64>) {
    ll[i] = l;
    for j in t[i].iter() {
        if j.to != p {
            walk(j.to, i, l+j.c, t, ll);
        }
    }
}

