        Q: usize,
        K: usize1,
        query: [(usize1, usize1); Q],
    }
    let mut edges_list = vec![Vec::<(usize, usize)>::new(); N];
    for &(a, b, c) in edges.iter() {
        edges_list[a].push((b, c));
        edges_list[b].push((a, c));
    }
    for &(qx, qy) in query.iter() {
        let mut cost = 0;
        // qx to K
        dfs(qx, qx, &edges_list, 0, &mut cost, K);
        // K to qy,
        let mut cost2 = 0;
        dfs(K, K, &edges_list, cost, &mut cost2, qy); 
        println!("{}", cost2);
    }
}

fn dfs(now: usize, parent: usize, edges: &Vec<Vec<(usize, usize)>>, cost: usize, ans: &mut usize, dist: usize) {
    if dist == now { 
        *ans = cost;
        return; 
    }
    for &(to, d) in edges[now].iter() {
        if to == parent { continue; }
        if *ans > 0 { break; }
        dfs(to, now, edges, cost+d, ans, dist);
    }
}

