            .spawn(solve)
            .unwrap()
            .join()
            .unwrap();
    } else {
        solve();
    }
}

fn solve() {
    let n = get!(usize);
    let abc = get!(usize, usize, usize; n-1);
    let (q,k) = get!(usize, usize);
    let xy = get!(usize,usize; q);

    let mut nodes = vec![Vec::new(); n+1];
    for (a,b,c) in abc {
        nodes[a].push((b,c));
        nodes[b].push((a,c));
    }
    let mut costs = vec![0; n+1];
    let mut queue = VecDeque::new();
    let mut visited = BTreeSet::new();

    queue.push_back((k, 0));
    visited.insert(k);
    costs[k] = 0;
    while let Some((node, cost)) = queue.pop_front() {
        costs[node] = cost;
        for &(next, ncost) in &nodes[node] {
            if visited.contains(&next) {
                continue;
            }
            queue.push_back((next, cost + ncost));
            visited.insert(next);
        }
    }

    for (x,y) in xy {
        println!("{}", costs[x]+costs[y]);
    }
}

use std::io::*;
fn dijkstra(start: usize, graph: &Vec<Vec<(usize, i64)>>) -> Vec<i64> {
    let mut dist = vec![std::i64::MAX; graph.len()];
    dist[start] = 0;
    let mut bh = std::collections::BinaryHeap::new();
    bh.push((0i64, start));
    while let Some((cost, v)) = bh.pop() {
        if dist[v] < -cost {
            continue;
        }
        for e in graph[v].iter() {
            let nv = e.0;
            let nc = e.1;
            if dist[nv] > -cost + nc {
                dist[nv] = -cost + nc;
                bh.push((-dist[nv], nv));
            }
        }
    }
    dist
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let mut g: Vec<Vec<(usize, i64)>> = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let a: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = itr.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: i64 = itr.next().unwrap().parse().unwrap();

        g[a].push((b, c));
        g[b].push((a, c));
    }
    let q: usize = itr.next().unwrap().parse().unwrap();
    let k: usize = itr.next().unwrap().parse().unwrap();
    let d = dijkstra(k - 1, &g);
    let mut out = Vec::new();
    for _ in 0..q {
        let x: usize = itr.next().unwrap().parse().unwrap();
        let y: usize = itr.next().unwrap().parse().unwrap();
        writeln!(out, "{}", d[x - 1] + d[y - 1]).ok();
    }
    stdout().write_all(&out).unwrap();
}

