fn bfs(src: usize, adj: &[Vec<(usize, u64)>]) -> Vec<u64> {
    let mut dists = vec![0; adj.len()];
    let mut queue = VecDeque::new();
    let mut used = vec![false; adj.len()];
    queue.push_front((src, 0));
    while queue.len() > 0 {
        let (crt, cost) = queue.pop_back().unwrap();
        used[crt] = true;
        dists[crt] = cost;
        for &(nxt, c) in adj[crt].iter() {
            if used[nxt] {
                continue;
            }
            queue.push_front((nxt, cost + c));
        }
    }
    dists
}

