fn exec() {
    let mut sc = Scanner::new(io::stdin());
    let n: usize = sc.ne();
    let mut g = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let (u, v, c): (usize, usize, i64) = (sc.ne(), sc.ne(), sc.ne());
        let (u, v) = (u - 1, v - 1);
        g[u].push((v, c));
        g[v].push((u, c));
    }
    let (q, k): (usize, usize) = (sc.ne(), sc.ne());
    let k = k - 1;
    let inf = 1e18 as i64;
    let mut dist = vec![inf as i64; n];
    let mut que = std::collections::BinaryHeap::new();
    que.push((0, k));
    dist[k] = 0;
    while let Some((d, cur)) = que.pop() {
        if dist[cur] < d {
            continue;
        }
        for &e in &g[cur] {
            if dist[e.0] > dist[cur] + e.1 {
                dist[e.0] = dist[cur] + e.1;
                que.push((dist[e.0], e.0));
            }
        }
    }
    for _ in 0..q {
        let (x, y): (usize, usize) = (sc.ne(), sc.ne());
        println!("{}", dist[x - 1] + dist[y - 1]);
    }
