fn bfs_dist_weighted_tree(N:usize,E:&Vec<HashMap<usize,isize>>,start:usize) -> Vec<isize>{
    //BFSで重み付き木グラフのstartからの距離を測る。
    let mut d = vec![-1;N];
    let mut q = VecDeque::new();
    q.push_back(start);
    d[start] = 0;
    while let Some(i) = q.pop_front(){
        for (&j,&c) in E[i].iter(){
            if d[j]!= -1{continue;}
            d[j] = d[i]+c;
            q.push_back(j);
        }
    }
    d
}

