pub fn main() {
    use std::io::Read;
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut iter = buf.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut graph: Vec<Vec<(usize, u64)>> = vec![vec![];n];
    for _ in 0..n-1 {
        let a: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let b: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let c: u64 = iter.next().unwrap().parse().unwrap();
        graph[a].push((b, c));
        graph[b].push((a, c));
    }

    let q: usize = iter.next().unwrap().parse().unwrap();
    let k: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;


    // k -> i
    let mut costs: Vec<Option<u64>> = vec![None;n];
    costs[k] = Some(0);

    for _ in 0..q {
        let x: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let y: usize = iter.next().unwrap().parse::<usize>().unwrap() - 1;
        let s = len(&graph, &mut costs, k, x, std::usize::MAX);
        let t = len(&graph, &mut costs, k, y, std::usize::MAX);
        println!("{}", s.unwrap() + t.unwrap());
    }
}

fn len(graph: &[Vec<(usize,u64)>], costs: &mut [Option<u64>], k: usize, cur: usize, pre: usize) -> Option<u64> {
    if let Some(v) = costs[cur] {
      return Some(v);
    }

    let mut ret: Option<u64> = None;
    for &(v, cost) in &graph[cur] {
        if pre == v {continue;}
        if let Some(rest) = len(graph,costs,k,v,cur) {
            if let Some(rr) = ret {
                ret = Some(std::cmp::min(rr, cost + rest));
            } else {
                ret = Some(cost + rest);
            }
        }
    }
    costs[cur] = ret;
    ret
}

use std::io::{BufRead, Write};
use std::io;
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::usize;

#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: usize,
    position: usize,
}

// The priority queue depends on `Ord`.
// Explicitly implement the trait so the queue becomes a min-heap
// instead of a max-heap.
impl Ord for State {
    fn cmp(&self, other: &State) -> Ordering {
        // Notice that the we flip the ordering on costs.
        // In case of a tie we compare positions - this step is necessary
        // to make implementations of `PartialEq` and `Ord` consistent.
        other
            .cost
            .cmp(&self.cost)
            .then_with(|| self.position.cmp(&other.position))
    }
}

// `PartialOrd` needs to be implemented as well.
impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

// Each node is represented as an `usize`, for a shorter implementation.
#[derive(Clone, Debug)]
struct Edge {
    node: usize,
    cost: usize,
}

// Dijkstra's shortest path algorithm.

// Start at `start` and use `dist` to track the current shortest distance
// to each node. This implementation isn't memory-efficient as it may leave duplicate
// nodes in the queue. It also uses `usize::MAX` as a sentinel value,
// for a simpler implementation.
fn shortest_path(adj_list: &Vec<Vec<Edge>>, start: usize, goal: usize) -> Option<usize> {
    // dist[node] = current shortest distance from `start` to `node`
    let mut dist: Vec<_> = (0..adj_list.len()).map(|_| usize::MAX).collect();

    let mut heap = BinaryHeap::new();

    // We're at `start`, with a zero cost
    dist[start] = 0;
    heap.push(State {
        cost: 0,
        position: start,
    });

    // Examine the frontier with lower cost nodes first (min-heap)
    while let Some(State { cost, position }) = heap.pop() {
        // Alternatively we could have continued to find all shortest paths
        if position == goal {
            return Some(cost);
        }

        // Important as we may have already found a better way
        if cost > dist[position] {
            continue;
        }

        // For each node we can reach, see if we can find a way with
        // a lower cost going through this node
        for edge in &adj_list[position] {
            let next = State {
                cost: cost + edge.cost,
                position: edge.node,
            };

            // If so, add it to the frontier and continue
            if next.cost < dist[next.position] {
                heap.push(next);
                // Relaxation, we have now found a better way
                dist[next.position] = next.cost;
            }
        }
    }

    // Goal not reachable
    None
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().unwrap();
    let mut adjacency = vec![Vec::<Edge>::new(); n];
    for _ in 0..n - 1 {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (a, b, c): (usize, usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            let c = split.next().unwrap().parse().unwrap();
            (a, b, c)
        };
        adjacency[b - 1].push(Edge {
            node: a - 1,
            cost: c,
        });
        adjacency[a - 1].push(Edge {
            node: b - 1,
            cost: c,
        });
    }
    s.clear();
    input.read_line(&mut s).unwrap();
    let (q, k): (usize, usize) = {
        let mut split = s.split_whitespace();
        let a = split.next().unwrap().parse().unwrap();
        let b = split.next().unwrap().parse().unwrap();
        (a, b)
    };
    for _ in 0..q {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (x, y): (usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            (a, b)
        };
        writeln!(
            output,
            "{}",
            shortest_path(&adjacency, x - 1, k - 1).unwrap() +
                shortest_path(&adjacency, k - 1, y - 1).unwrap()
        ).unwrap();
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

