    for (a,b,c) in es {
        edges[a].push((b,c));
        edges[b].push((a,c));
    }
    let inf = std::usize::MAX;
    let mut d = vec![inf; n];
    let mut heap = BinaryHeap::new();
    d[k] = 0;
    heap.push(Reverse((0, k)));
    while  !heap.is_empty() {
        let (dist, i) = heap.pop().unwrap().0;
        if d[i] < dist {
            continue;
        } else {
        for &(j, w) in &edges[i] {
            if d[j] > d[i] + w {
                d[j] = d[i] + w;
