use std::error::Error;
use std::io;
use std::collections::{HashMap, HashSet};
use std::collections::hash_map::Entry;

fn main() {
    if let Err(e) = run() {
        println!("{}", e);
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut n = String::new();
    io::stdin().read_line(&mut n)?;
    let n: usize = n.trim().parse()?;
    let mut adjs: HashMap<usize, Vec<(usize, usize)>> = HashMap::new();
    for _ in 0..n-1 {
        let mut abc = String::new();
        io::stdin().read_line(&mut abc)?;
        let abc: Vec<usize> = abc.trim().split(" ").map(|x| x.parse().expect("")).collect();
        match adjs.entry(abc[0]) {
            Entry::Occupied(o) => {o.into_mut().push((abc[1], abc[2]));},
            Entry::Vacant(v) => {v.insert(vec![(abc[1], abc[2])]);},
        };
        match adjs.entry(abc[1]) {
            Entry::Occupied(o) => {o.into_mut().push((abc[0], abc[2]));},
            Entry::Vacant(v) => {v.insert(vec![(abc[0], abc[2])]);},
        };
    }
    let mut qk = String::new();
    io::stdin().read_line(&mut qk)?;
    let qk: Vec<usize> = qk.trim().split(" ").map(|x| x.parse().expect("")).collect();
    let q = qk[0];
    let k = qk[1];
    let mut m: HashMap<usize, usize> = HashMap::new();
    let mut set: HashSet<usize> = HashSet::new();
    let mut v = Vec::new();
    for t in adjs.get(&k).unwrap() {
        v.push((t.0, t.1));
        set.insert(t.0);
    }
    while v.len() > 0 {
        let t = v.pop().unwrap();
        m.insert(t.0, t.1);
        for t2 in adjs.get(&t.0).unwrap() {
            if set.contains(&t2.0) {
                continue;
            }
            v.push((t2.0, t2.1 + t.1));
            set.insert(t2.0);
        }
    }
    for _ in 0..q {
        let mut xy = String::new();
        io::stdin().read_line(&mut xy)?;
        let xy: Vec<usize> = xy.trim().split(" ").map(|x| x.parse().expect(" ")).collect();
        let x = xy[0];
        let y = xy[1];
        println!("{}", m.get(&x).unwrap() + m.get(&y).unwrap());
    }
    Ok(())
}

