// Define custom type to implement a min-heap
#[derive(Debug, Copy, Clone, Eq, PartialEq)]
struct Cost(usize);

impl Ord for Cost {
    fn cmp(&self, other: &Cost) -> Ordering {
        other.0.cmp(&self.0)
    }
}

impl PartialOrd for Cost {
    fn partial_cmp(&self, other: &Cost) -> Option<Ordering> {
        Some(other.0.cmp(&self.0))
    }
}

fn main() {
    input!{
      n: usize,
      abcs: [(usize, usize, usize); n-1],
      qq: usize,
      k: usize,
      xys: [(usize, usize); qq],
    }
    let k = k-1;
    let mut g = vec![vec![]; n];
    for &(a, b, c) in &abcs {
        g[a-1].push((b-1, c));
        g[b-1].push((a-1, c));
    }

    const INF: usize = 1 << 60;
    let mut ds = vec![INF; n];
    ds[k] = 0;

    let mut q = BinaryHeap::new();
    q.push((Cost(0),k));

    while q.len() > 0 {
        let (ttl_cost, v) = q.pop().unwrap();
        if ds[v] < ttl_cost.0 {
            continue;
        }

        for &(n, nc) in &g[v] {
            if ds[v] + nc < ds[n] {
                ds[n] = ds[v] + nc;
                q.push((Cost(ds[v] + nc), n));
            }
        }
    }

    for i in 0..qq {
        let x = xys[i].0 - 1;
        let y = xys[i].1 - 1;
        println!("{}", ds[x] + ds[y]);
    }
}

