#[derive(Clone)]
struct Edge {
    node: usize,
    cost: usize,
}

fn search_cost(
    graph: &Vec<Vec<Edge>>,
    graph_shortest: &mut Vec<usize>,
    to: usize,
    from: usize,
    cost: usize,
) {
    for e in &graph[to] {
        if from == e.node {
            continue;
        }
        let cost_buf = cost + e.cost;
        graph_shortest[e.node] = cost_buf;
        search_cost(graph, graph_shortest, e.node, to, cost_buf);
    }
}

