use std::collections::HashSet;

// Each node is represented as an `usize`, for a shorter implementation.
#[derive(Copy, Clone, Debug)]
struct Edge {
    node: usize,
    cost: usize,
}

fn shortest_path(adjacency: &Vec<Vec<Edge>>, top: usize) -> Vec<usize> {
    let mut visited: HashSet<usize> = HashSet::new();
    let mut queue: Vec<usize> = vec![top];
    let mut result: Vec<usize> = vec![0; adjacency.len()];
    visited.insert(top);
    while let Some(x) = queue.pop() {
        for y in &adjacency[x] {
            if visited.insert(y.node) {
                result[y.node] = result[x] + y.cost;
                queue.push(y.node);
            }
        }
    }
    result
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().unwrap();
    let mut adjacency = vec![Vec::<Edge>::new(); n];
    for _ in 0..n - 1 {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (a, b, c): (usize, usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            let c = split.next().unwrap().parse().unwrap();
            (a, b, c)
        };
        adjacency[b - 1].push(Edge {
            node: a - 1,
            cost: c,
        });
        adjacency[a - 1].push(Edge {
            node: b - 1,
            cost: c,
        });
    }
    s.clear();
    input.read_line(&mut s).unwrap();
    let (q, k): (usize, usize) = {
        let mut split = s.split_whitespace();
        let a = split.next().unwrap().parse().unwrap();
        let b = split.next().unwrap().parse().unwrap();
        (a, b)
    };
    let cost = shortest_path(&adjacency, k - 1);
    for _ in 0..q {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (x, y): (usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            (a, b)
        };
        writeln!(output, "{}", cost[x - 1] + cost[y - 1]).unwrap();
    }
}

