fn main() {
    input! {
        n:usize,
        abc:[(usize,usize,i64);n-1],
        q:usize,
        k:usize,
        xy:[(usize,usize);q],
    }
    let mut g = Graph::new(n);
    for e in abc {
        g.add_undirectional_edge(e.0 - 1, e.1 - 1, e.2);
    }
    let dist = bfs(&g, k - 1);
    let xy = xy.iter().map(|&(x, y)| (x - 1, y - 1)).collect::<Vec<_>>();
    for (x, y) in xy {
        let ans = dist[x] + dist[y];
        println!("{}", ans);
    }
}

fn bfs(g: &Graph, k: usize) -> Vec<i64> {
    let mut res = vec![std::i64::MAX; g.len()];
    res[k] = 0;
    let mut b = VecDeque::new();
    b.push_back(k);
    while let Some(now) = b.pop_front() {
        for next in g[now].iter() {
            if res[next.to] != std::i64::MAX {
                continue;
            }
            res[next.to] = res[now] + next.cost;
            b.push_back(next.to);
        }
    }
    return res;
}

#[derive(Debug, Copy, Clone)]
pub struct Edge {
    pub to: usize,
    pub cost: i64,
}
impl Edge {
    pub fn new(to: usize, cost: i64) -> Edge {
        Edge { to: to, cost: cost }
    }
}
pub struct Graph {
    adjacency: Vec<Vec<Edge>>,
}
impl Graph {
    pub fn new(size: usize) -> Self {
        Graph {
            adjacency: vec![vec![]; size],
        }
    }
    pub fn len(&self) -> usize {
        self.adjacency.len()
    }
    pub fn add_directional_edge(&mut self, from: usize, to: usize, cost: i64) {
        self.adjacency[from].push(Edge::new(to, cost));
    }
    pub fn add_undirectional_edge(&mut self, from: usize, to: usize, cost: i64) {
        self.add_directional_edge(from, to, cost);
        self.add_directional_edge(to, from, cost);
    }
}
impl std::ops::Index<usize> for Graph {
    type Output = Vec<Edge>;
    fn index(&self, vertex: usize) -> &Self::Output {
        &self.adjacency[vertex]
    }
}

macro_rules! get {
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    get!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    get!($($t),*)
