#[derive(Clone)]
struct Node {
    nb: Vec<usize>,
    dist: Vec<usize>,
}

fn shortest(arena: &Vec<Node>, start: usize, goal: usize, from: usize) -> Option<usize> {
    if start == goal {
        return Some(0);
    }
    let mut min = None;
    for (i, nb) in arena[start].nb.iter().enumerate() {
        if *nb == from {
            continue;
        }

        let dist = arena[start].dist[i];
        if let Some(min_val) = min {
            if let Some(distsum) = shortest(arena, *nb, goal, start) {
                if min_val > distsum + dist {
                    min = Some(distsum + dist);
                }
            }
        } else {
            if let Some(distsum) = shortest(arena, *nb, goal, start) {
                min = Some(distsum + dist);
            }
        }
    }
    return min;
}

fn main() {
    let N = get!(usize);
    let abcs = get!(usize, usize, usize; N-1);
    let (Q, K) = get!(usize, usize);
    let xys = get!(usize, usize; Q);

    let mut arena = vec![Node{nb: Vec::new(), dist: Vec::new()}; N+1];

    for abc in abcs.iter() {
        arena[abc.0].nb.push(abc.1);
        arena[abc.1].nb.push(abc.0);
        arena[abc.0].dist.push(abc.2);
        arena[abc.1].dist.push(abc.2);
    }

    for xy in xys.iter() {
        println!("{}", shortest(&arena, K, xy.0, K).unwrap() + shortest(&arena, K, xy.1, K).unwrap());
    }
}

