    #[derive(Clone, Copy)]
    struct Edge {
        to: usize,
        cost: i64,
    }

    fn dijkstra_heap(g: &[Vec<Edge>], s: usize, inf: i64) -> Vec<i64> {
        let n = g.len();
        let mut queue = std::collections::BinaryHeap::new(); // max-heap
        let mut d = vec![inf; n];

        d[s] = 0;
        queue.push((0, s));

        while let Some((cost, v)) = queue.pop() {
            let cost = -cost;

            if d[v] < cost {
                continue;
            }
            for e in &g[v] {
                let new_cost = cost + e.cost;
                if d[e.to] > new_cost {
                    d[e.to] = new_cost;
                    queue.push((-new_cost, e.to));
                }
            }
        }

        d
    }

use std::io;
use std::io::BufRead;
use std::collections::{HashMap, HashSet};

const BIG: u64 = 0x4000_0000_0000_0000;

fn main() {
    let stdin = io::stdin();
    let mut stdin = stdin.lock();
    let mut s = String::new();
    stdin.read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().unwrap();
    let mut v: HashMap<(usize, usize), u64> = HashMap::with_capacity(n);
    for _ in 0..(n-1) {
        let mut s = String::new();
        stdin.read_line(&mut s).unwrap();
        let t: Vec<u64> = s.trim()
                           .split_whitespace()
                           .map(|x| x.parse().unwrap())
                           .collect();
        v.insert((t[0] as usize, t[1] as usize), t[2]);
        v.insert((t[1] as usize, t[0] as usize), t[2]);
    }
    let (q, k) = {
        let mut s = String::new();
        stdin.read_line(&mut s).unwrap();
        let t: Vec<u64> = s.trim()
                           .split_whitespace()
                           .map(|x| x.parse().unwrap())
                           .collect();
        (t[0], t[1] as usize)
    };
    let mut notdone = HashSet::with_capacity(n);
    for i in 1..(n+1) {
        notdone.insert(i as usize);
    }
    let mut dist = vec![BIG; n + 1];
    notdone.remove(&k);
    dist[k] = 0;
    let mut lastdone = k;
    loop {
        let mut nextdone = 0;
        let mut cost = BIG;
        for &node in notdone.iter() {
            match v.get(&(lastdone, node)) {
                Some(c) => {
                    if dist[lastdone] + c < dist[node] {
                        dist[node] = dist[lastdone] + c;
                    }
                },
                None => {}
            }
            if dist[node] < cost {
                nextdone = node;
                cost = dist[node];
            }
        }
        if nextdone == 0 { break; }
        notdone.remove(&lastdone);
        lastdone = nextdone;
    }
    for _ in 0..q {
        let (x, y) = {
            let mut s = String::new();
            stdin.read_line(&mut s).unwrap();
            let t: Vec<usize> = s.trim()
                               .split_whitespace()
                               .map(|x| x.parse().unwrap())
                               .collect();
            (t[0], t[1])
        };
        println!("{}", dist[x] + dist[y]);
    }
}

use petgraph::algo::dijkstra;
use petgraph::graph::{NodeIndex, UnGraph};
use proconio::input;

fn main() {
    input! {
        n: usize,
        edges: [(usize, usize, usize); n-1],
        q: usize,
        k: usize,
        pairs: [(usize, usize); q],
    }

    //グラフを作る。
    let g = UnGraph::<usize, usize, usize>::from_edges(&edges);

    //ダイクストラ法で頂点kから他の頂点の最短距離を計算
    let res = dijkstra(&g, k.into(), None, |e| *e.weight());


    for (start, end) in &pairs {
        //頂点x_jと頂点kの最短距離 + 頂点kと頂点y_jの最短距離を計算
        let distance =
            res.get(&NodeIndex::new(*start)).unwrap() + res.get(&NodeIndex::new(*end)).unwrap();
        println!("{}", distance);
    }
}

