use std::collections::HashMap;

fn dfs(table: &HashMap<usize, Vec<(usize, usize)>>, dists: &mut Vec<usize>, p: usize, d: usize) {
    dists[p] = d;

    if !table.contains_key(&p) { return }

    for &(b, c) in table.get(&p).unwrap().iter() {
        if dists[b] < std::usize::MAX { continue }

        dfs(table, dists, b, d+c);
    }
}

fn solve(abc: Vec<(usize, usize, usize)>, k:usize, xy: Vec<(usize, usize)>) -> Vec<usize> {

    let mut table = HashMap::new();

    for (a,b,c) in abc {
        {
            let x = table.entry(a).or_insert(vec![]);
            x.push((b, c));
        }

        {
            let x = table.entry(b).or_insert(vec![]);
            x.push((a, c));
        }

    }

    let mut dists = vec![std::usize::MAX; 100001];

    dfs(&table, &mut dists, k, 0);

    xy.iter().map(|&(x, y)| dists[x] + dists[y]).collect()
}

fn main() {
    let n = parse_line!(usize);
    let abc = (0..n).map(|_| parse_line!(usize, usize, usize)).collect();

    let (q, k) = parse_line!(usize, usize);
    let xy = (0..q).map(|_| parse_line!(usize, usize)).collect();

    for i in solve(abc, k, xy).iter() {
        println!("{}", i);
    }
}

