    let inf = std::u64::MAX;

    let n = readln();

    let mut es = vec![vec![]; n];

    for _ in 0..(n - 1) {
        let abc: Vec<usize> = reads();
        es[abc[0] - 1].push((abc[1] - 1, abc[2] as u64));
