type Cost = i64;

struct Edge {
    to: usize,
    cost: Cost,
}

impl std::clone::Clone for Edge {
    fn clone(&self) -> Edge { Edge{to: self.to, cost: self.cost} }
}

impl Ord for Edge {
    fn cmp(&self, other: &Edge) -> Ordering {
        (-self.cost).cmp(&(-other.cost))
    }
}

impl PartialOrd for Edge {
    fn partial_cmp(&self, other: &Edge) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Eq for Edge {}

impl PartialEq for Edge {
    fn eq(&self, other: &Edge) -> bool {
        self.cost == other.cost
    }
}

struct Graph {
    adj: Vec<Vec<Edge>>,
}

impl Index<usize> for Graph {
    type Output = Vec<Edge>;

    fn index(&self, i: usize) -> &Vec<Edge> {
        &self.adj[i]
    }
}

impl IndexMut<usize> for Graph {
    fn index_mut<'a>(&'a mut self, i: usize) -> &'a mut Vec<Edge> {
        &mut self.adj[i]
    }
}

impl Graph {

    fn new(n: usize) -> Graph{
        Graph {
            adj: vec![vec![]; n],
        }
    }

    fn size(&self) -> usize{
        self.adj.capacity()
    }

    fn add_edge(&mut self, from: usize, to_: usize, cost_: Cost) {
        self.adj[from].push(Edge{to: to_, cost: cost_});
    }

    fn add_uedge(&mut self, from: usize, to_: usize, cost_: Cost) {
        self.add_edge(from, to_, cost_);
        self.add_edge(to_, from, cost_);
    }

    fn get_shortest_path(&self, from: usize) -> (Vec<Cost>, Vec<usize>) {
        let n = self.size();

        let mut dist = vec![std::i64::MAX; n];
        let mut pre = vec![n as usize; n];
        let mut heap = BinaryHeap::new();
        heap.push(Edge{to: from, cost: 0});
        dist[from] = 0;
        println!();
        while !heap.is_empty() {
            match heap.pop() {
                None => {
                    assert!(true);
                }
                Some(p) => {
                    for e in &(*self)[p.to] {
                        if p.cost+e.cost >= dist[e.to] {
                            continue;
                        }
                        heap.push(Edge{to: e.to, cost: p.cost+e.cost});
                        dist[e.to] = p.cost+e.cost;
                        pre[e.to] = p.to;
                    }
                }
            }
        }

        (dist, pre)
    }
}

