fn main() {
  let n: usize = read();
  let mut g: Vec<Vec<(usize, u64)>> = vec![vec![]; n];
  for _ in 0..n-1 {
    let v: Vec<usize> = read_vec();
    g[v[0] - 1].push((v[1] - 1, v[2] as u64));
    g[v[1] - 1].push((v[0] - 1, v[2] as u64));
  }

  let (q, k) = {
    let v: Vec<usize> = read_vec();
    (v[0], v[1] - 1)
  };

  let mut tasks = Vec::new();
  for _ in 0..q {
    let v: Vec<usize> = read_vec();
    tasks.push((v[0] - 1, v[1] - 1));
  }

  //dijkstra法による単一始点からの最短経路長を探索
  let dist = dijkstra(n, &g, k);

  for (x, y) in tasks {
    println!("{}", dist[x] + dist[y]);
  }
}


fn dijkstra(n: usize, adj_list: &Vec<Vec<(usize, u64)>>, start: usize) -> Vec<u64> {
  let mut dist = vec![std::u64::MAX; n];
  let mut p_queue: BinaryHeap<(i64, usize)> = BinaryHeap::new();

  //init
  dist[start] = 0;
  p_queue.push((0, start));

  while !p_queue.is_empty() {
    // 起点となるノード
    let (cost, now)
      = match p_queue.pop() {
        None => break,
        Some(e) => (-e.0 as u64, e.1),
      };

    // 繋がっているノードを探索
    for &edge in &adj_list[now] {
      let next = edge.0;
      let weight = edge.1;

      if dist[next] > weight + cost {
        p_queue.push((-((weight + cost) as i64), next));
        dist[next] = weight + cost;
      }
    }

  }

  dist
}

