fn dfs2(n: usize, p: usize, e: &Vec<Vec<(usize, isize)>>, d: &mut Vec<isize>){
    for i in &e[p]{
        if d[i.0] > d[p] + i.1 {
            d[i.0] = d[p] + i.1;
            dfs2(n, i.0, e, d);
        }
    }
}

fn dfs(n: usize, k: usize, e: &Vec<Vec<(usize, isize)>>)->Vec<isize>{
    let mut d = vec![1 << 30; n];
    d[k] = 0;
    dfs2(n, k, &e, &mut d);
    return d
}

