fn main() {
    input! {
        n: usize,
        es: [(Usize1, Usize1, i64); n-1],
        q: usize, k: Usize1,
        qs: [(Usize1, Usize1); q]
    };
    let mut edges: Vec<Vec<(usize, i64)>> = vec![Vec::new(); n];
    for (a,b,c) in es {
        edges[a].push((b,c));
        edges[b].push((a,c));
    }
    let inf = i64::MAX;
    let mut d = vec![inf; n];
    let mut heap = BinaryHeap::new();
    d[k] = 0;
    heap.push(((0, k)));
    while  !heap.is_empty() {
        let (dist, i) = heap.pop().unwrap();
        if d[i] < -dist {
            continue;
        } else {
        for &(j, w) in &edges[i] {
            if d[j] > d[i] + w {
                d[j] = d[i] + w;
                heap.push(((-d[j], j)));
            } else {}
        }}
    }
    for (x,y) in qs {
        println!("{}", d[x]+d[y]);
    }
}

