    fn cmp(&self, other: &MinInt) -> Ordering {
        other.value.cmp(&self.value)
    }
}

fn make_pair(x: i64, y: usize) -> (MinInt, usize) {
    (MinInt { value: x }, y)
}

#[derive(Debug, Clone)]
struct Edge {
    to: usize,
    cost: i64,
}

fn solve(edges: &Vec<Vec<Edge>>, start_idx: usize, num_apexes: usize) -> Vec<i64> {
    let mut d = vec![INF; num_apexes];
    d[start_idx] = 0;
    let mut que = BinaryHeap::new();
    que.push(make_pair(0, start_idx));

    while let Some((u, v)) = que.pop() {
        if d[v] < u.value {
            continue;
        }
        for e in &edges[v] {
            if d[e.to] > d[v] + e.cost {
                d[e.to] = d[v] + e.cost;
                que.push(make_pair(d[e.to], e.to));
            }
        }
    }
    // println!("{:?}", d);
    d
}

fn main() {
    let n = read::<usize>();
    let mut edges: Vec<Vec<Edge>> = vec![Vec::new(); n];
    for i in 0..n - 1 {
        let v = read_vec::<usize>();
        let (a, b, c) = (v[0] - 1, v[1] - 1, v[2] as i64);
        edges[a].push(Edge { to: b, cost: c });
        edges[b].push(Edge { to: a, cost: c });
    }
    let v = read_vec::<usize>();
    let (q, k) = (v[0], v[1] - 1);

    let d = solve(&edges, k, n);
    for i in 0..q {
        let v = read_vec::<usize>();
        let (x, y) = (v[0] - 1, v[1] - 1);
        println!("{}", d[x] + d[y]);
    }
}

use std::io::*;
use std::str::FromStr;
use std::collections::BinaryHeap;

struct Graph {
    node: usize,
    directed: bool,
    graph: Vec<Vec<(usize, i64)>>,
}

impl Graph {
    fn new(n: usize, flag: bool) -> Graph {
        Graph { node: n, directed: flag, graph: vec![vec![]; n] }
    }

    fn add_edge(&mut self, start_node: usize, end_node: usize, cost: i64) -> () {
        self.graph[start_node].push((end_node, cost));
        if !self.directed { self.graph[end_node].push((start_node, cost)); }
    }
    fn dijkstra(&self, start_node: usize) -> Vec<i64> {
        let mut dist = vec![std::i64::MAX; self.node];
        dist[start_node] = 0;

        let mut queue: BinaryHeap<(i64, usize)> = BinaryHeap::new();
        queue.push((0, start_node));

        while !queue.is_empty() {
            let (min_dist, idx) = queue.pop().unwrap();
            if dist[idx] < -min_dist {
                continue;
            }
            for &(to, weight) in &self.graph[idx] {
                let cost_cand = dist[idx] + weight;
                if dist[to] > cost_cand {
                    dist[to] = cost_cand;
                    queue.push((-cost_cand, to));
                }
            }
        }
        dist
    }
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char) 
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();

    let mut g = Graph::new(n+1, false);
    for _ in 0..n-1 {
        let a: usize = read();
        let b: usize = read();
        let c: i64 = read();
        g.add_edge(a, b, c);
    }

    let q: usize = read();
    let k: usize = read();

    let v = g.dijkstra(k);
    for _ in 0..q {
        let x: usize = read();
        let y: usize = read();
        let ans = v[x] + v[y];
        println!("{}", ans);
    }
}

