}

fn dfs(tree:&Vec<Vec<Edge>>,depth:&mut Vec<u64>,v:usize,p:usize,d:u64){
    depth[v]=d;
    for e in &tree[v]{
        if e.to==p {
            continue;
        }else{
            dfs(tree,depth,e.to,v,d+e.cost);
        }
    }
}
