    input! {
        n:usize,
        nodes:[(usize,usize,u64);n-1],
        q:usize,
        k:usize1,
        query:[(usize,usize);q],
    };
    let mut tree:Vec<Vec<Edge>>=(0..n).map(|_|Vec::new()).collect();
    let mut depth=vec![0;n];
    for (s,t,c) in nodes.into_iter(){
        tree[s-1].push(Edge{to:t-1,cost:c});
        tree[t-1].push(Edge{to:s-1,cost:c});
    }
    dfs(&tree,&mut depth,k,std::usize::MAX,0);

    for (x,y) in query.into_iter(){
        println!("{}",depth[x-1]+depth[y-1]);
    }

}

