fn main() {
    let n = readln();

    let mut ts = vec![vec![None; n]; n];


    for _ in 0..(n - 1) {
        let abc: Vec<usize> = reads();

        ts[abc[0] - 1][abc[1] - 1] = Some(abc[2]);
        ts[abc[1] - 1][abc[0] - 1] = Some(abc[2]);
    }

    for i in 0..n {
        for j in 0..n {
            for k in 0..n {
                let r = add(ts[i][k], ts[k][j]);
                if cmp(ts[i][j], r) {
                    ts[i][j] = r;
                }
            }
        }
    }

    let qk = reads();

    for _ in 0..qk[0] {
        let xy: Vec<usize> = reads();

        println!("{}", add(ts[xy[0] - 1][qk[1] - 1], ts[qk[1] - 1][xy[1] - 1]).unwrap());
    }
}

fn cmp(lhs: Option<usize>, rhs: Option<usize>) -> bool {
    match (lhs, rhs) {
        (Some(lv), Some(rv)) => lv > rv,
        (None, Some(_)) => true,
        _ => false,
    }
}

fn add(lhs: Option<usize>, rhs: Option<usize>) -> Option<usize> {
    match (lhs, rhs) {
        (Some(lv), Some(rv)) => Some(lv + rv),
        _ => None,
    }
}

