// ref https://atcoder.jp/contests/abc126/submissions/5458290
struct Tree {
    n: usize,
    edges: Vec<Vec<(usize, i64)>>,
}
impl Tree {
    fn new(n: usize) -> Tree {
        Tree {
            n: n,
            edges: vec![vec![]; n],
        }
    }
    fn add_edge(&mut self, s: usize, t: usize, w: i64) {
        self.edges[s].push((t, w));
        self.edges[t].push((s, w));
    }
    fn dists(&self, i: usize) -> Vec<i64> {
        let mut res = vec![0; self.n];
        self.dists_sub(i, self.n, &mut res);
        res
    }
    fn dists_sub(&self, i: usize, prev: usize, res: &mut Vec<i64>) {
        for &(v, w) in &self.edges[i] {
            if v == prev {
                continue;
            }
            res[v] = res[i] + w;
            self.dists_sub(v, i, res);
        }
    }
}
fn main() {
    input!{
