    let mut tree = Tree::new(n);
    for &(a,b,c) in &abc {
        tree.add_edge(a,b,c);
    }
    // println!("{:?}", tree.dists(k));
    let dis = tree.dists(k);
    for &(x,y) in &xy {
        println!("{}", dis[x] + dis[y]);
    }
}

