fn main() {
    let stdin = std::io::stdin();
    let mut sc = Scanner::new(stdin.lock());

    let n: usize = sc.read();

    let mut g = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let a: usize = sc.read();
        let b: usize = sc.read();
        let c: u64 = sc.read();
        g[a - 1].push((b - 1, c));
        g[b - 1].push((a - 1, c));
    }

    // println!("{:?}", g);

    let q: usize = sc.read();
    let k: usize = sc.read();

    // d[i] = k -> i の距離
    let mut d = vec![1u64 << 60; n];
    {
        d[k - 1] = 0;

        let mut h = BinaryHeap::new();
        h.push(Rev((0, k - 1)));

        while let Some(Rev((c, v))) = h.pop() {
            if d[v] < c {
                continue;
            }

            for &(i, ci) in g[v].iter() {
                if d[i] > ci + d[v] {
                    d[i] = ci + d[v];
                    h.push(Rev((d[i], i)));
                }
            }
        }
    }

    // println!("{:?}", d);

    for _ in 0..q {
        let x: usize = sc.read();
        let y: usize = sc.read();
        println!("{}", d[x - 1] + d[y - 1]);
    }
}

