fn calc_dicstance(graph: &Vec<Vec<(usize, usize)>>, distances: &mut Vec<usize>, cur_v: usize){
    for next in &graph[cur_v]{
        let (next_v, cost) = (next.0, next.1);
        if distances[next_v] != std::usize::MAX{
            continue;
        }
        distances[next_v] = cost + distances[cur_v];
        calc_dicstance(graph, distances, next_v);
    }
}

