fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let mut nbr = vec![Vec::new(); n];
    for _ in 0..n - 1 {
        let a: usize = sc.read();
        let b: usize = sc.read();
        let c: usize = sc.read();
        nbr[a - 1].push((b - 1, c));
        nbr[b - 1].push((a - 1, c));
    }
    let q: usize = sc.read();
    let k: usize = sc.read();
    let sdf = shortest_dists_from(k - 1, &nbr);

    let mut ret = String::new();
    use std::fmt::Write;
    for _ in 0..q {
        let x: usize = sc.read();
        let y: usize = sc.read();
        writeln!(&mut ret, "{}", sdf[x - 1] + sdf[y - 1]).unwrap();
    }
    ret
}

#[derive(PartialEq, Eq, Debug)]
struct Rev<T>(T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<std::cmp::Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> std::cmp::Ordering {
        other.0.cmp(&self.0)
    }
}
fn shortest_dists_from(start: usize, neighbor: &[Vec<(usize, usize)>]) -> Vec<usize> {
    use std::collections::BinaryHeap;
    use std::iter::FromIterator;
    let n = neighbor.len();
    let mut dist = vec![usize::max_value() / 2; n];
    dist[start] = 0;
    let mut que: BinaryHeap<_> = FromIterator::from_iter(dist.iter().map(|&d| Rev(d)).zip(0..n));
    while let Some((Rev(d), u)) = que.pop() {
        for &(v, l) in &neighbor[u] {
            let alt = d + l;
            if dist[v] > alt {
                dist[v] = alt;
                que.push((Rev(alt), v));
            }
        }
    }
    dist
}

