}

fn dfs(tree: &[Node], dists: &mut [i64], parent: usize) {
    for (n, c) in tree[parent].children.iter() {
        if dists[*n] == 1 << 60 {
            dists[*n] = dists[parent] + c;
            dfs(tree, dists, *n);
        }
    }
}

fn dists(tree: Vec<Node>, root: usize) -> Vec<i64> {
    let mut dists = vec![1 << 60; tree.len()];
    dists[root] = 0;
    dfs(&tree, &mut dists, root);

    dists
}
