        tree[a - 1].children.push((b - 1, c));
        tree[b - 1].children.push((a - 1, c));
    }
    let (q, k) = scan!(i64, usize);
    let dists = dists(tree, k - 1);
    for _ in 0..q {
        let (x, y) = scan!(usize, usize);
        println!("{}", dists[x - 1] + dists[y - 1])
    }
}

