use std::cmp;
use std::collections::{HashSet, BinaryHeap};
use std::io::{Write, BufWriter, stdout};
use std::iter::FromIterator;
fn main() {
    input! {
        N: usize,
        edges: [(usize1, usize1, usize); N-1],
        Q: usize,
        K: usize1,
        query: [(usize1, usize1); Q],
    }
    let mut edges_list = vec![Vec::<(usize, usize)>::new(); N];
    for &(a, b, c) in edges.iter() {
        edges_list[a].push((b, c));
        edges_list[b].push((a, c));
    }

    let mut d = vec![std::usize::MAX; N];
    d[K] = 0;
    let mut q = HashSet::<usize>::from_iter(0..N);
    let mut costs = BinaryHeap::<EdgeCost>::with_capacity(N);
    costs.push(EdgeCost(K, 0));
    while q.len() > 0 {
        let EdgeCost(prev, cc) = costs.pop().unwrap();
        if !q.remove(&prev) {
            continue;
        }
        for &(qq, cc) in edges_list[prev].iter() {
            if q.contains(&qq) {
                d[qq] = cmp::min(d[qq], d[prev] + cc);
                costs.push(EdgeCost(qq, d[qq]));
            }
        }
    }

    for &(qx, qy) in query.iter() {
        println!("{}", d[qx] + d[qy]);
    }
}

