use std::io::prelude::*;

fn input<T>() -> T
where
    T: std::str::FromStr,
{
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let abc: Vec<(usize, usize, i64)> = (1..n)
        .map(|_| {
            let a = input();
            let b = input();
            let c = input();
            (a, b, c)
        })
        .collect();
    let q: usize = input();
    let k: usize = input();
    let xy: Vec<(usize, usize)> = (0..q)
        .map(|_| {
            let x = input();
            let y = input();
            (x, y)
        })
        .collect();

    let mut t = vec![vec![]; n + 1];
    for (a, b, c) in abc {
        t[a].push((b, c));
        t[b].push((a, c));
    }

    let mut d = vec![-1; n + 1];
    dfs(k, 0, &t, &mut d);

    for (x, y) in xy {
        println!("{}", d[x] + d[y]);
    }
}

fn dfs(cur: usize, dist: i64, t: &Vec<Vec<(usize, i64)>>, d: &mut Vec<i64>) {
    d[cur] = dist;
    for &(next, cost) in &t[cur] {
        if d[next] >= 0 {
            continue;
        }
        dfs(next, dist + cost, t, d);
    }
}

