fn dfs(tree: &HashMap<usize,Vec<Edge>>, dist: &mut Vec<usize>, v: usize, p: Option<usize>, cost: usize) {
    dist[v] = cost;
    if let Some(edges) = tree.get(&v) {
        for edge in edges.iter() {
            if let Some(p) = p {
                if edge.to == p {
                    continue;
                }
            }
            dfs(tree, dist, edge.to, Some(v), cost + edge.cost);
        }
    }
}

