fn main() {

    let n = read_t_in_line::<i64>()[0];
    let mut g = vec![vec![] ; n as usize];

    for _ in 0..n-1 {
        let l = read_t_in_line::<i64>();
        let (mut a, mut b, c) = (l[0], l[1], l[2]);
        a -= 1;
        b -= 1;
        g[a as usize].push((b, c));
        g[b as usize].push((a, c));
    }

    let l = read_t_in_line::<i64>();
    let (q, mut k) = (l[0], l[1]);
    k -= 1;

    let qs : Vec<_> =
        (0..q).
        map(|_| read_t_in_line::<i64>()).
        map(|l| (l[0] - 1, l[1] - 1)).collect();

