// Each node is represented as an `usize`, for a shorter implementation.
#[derive(Copy, Clone, Debug)]
struct Edge {
    node: usize,
    cost: usize,
}

fn shortest_path(adjacency: &Vec<Vec<Edge>>, start: usize, goal: usize) -> Option<usize> {
    let mut visited: HashSet<usize> = HashSet::new();
    let mut path: HashMap<usize, (usize, usize)> = HashMap::new();
    let mut queue: Vec<usize> = vec![start];
    visited.insert(start);
    while let Some(x) = queue.pop() {
        if x == goal {
            let mut sum = 0;
            let mut current = x;
            while let Some(&(next, c)) = path.get(&current) {
                sum += c;
                current = next;
            }
            return Some(sum);
        }
        for y in &adjacency[x] {
            if visited.insert(y.node) {
                path.insert(y.node, (x, y.cost));
                queue.push(y.node);
            }
        }
    }
    None
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().unwrap();
    let mut adjacency = vec![Vec::<Edge>::new(); n];
    for _ in 0..n - 1 {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (a, b, c): (usize, usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            let c = split.next().unwrap().parse().unwrap();
            (a, b, c)
        };
        adjacency[b - 1].push(Edge {
            node: a - 1,
            cost: c,
        });
        adjacency[a - 1].push(Edge {
            node: b - 1,
            cost: c,
        });
    }
    s.clear();
    input.read_line(&mut s).unwrap();
    let (q, k): (usize, usize) = {
        let mut split = s.split_whitespace();
        let a = split.next().unwrap().parse().unwrap();
        let b = split.next().unwrap().parse().unwrap();
        (a, b)
    };
    for _ in 0..q {
        s.clear();
        input.read_line(&mut s).unwrap();
        let (x, y): (usize, usize) = {
            let mut split = s.split_whitespace();
            let a = split.next().unwrap().parse().unwrap();
            let b = split.next().unwrap().parse().unwrap();
            (a, b)
        };
        writeln!(
            output,
            "{}",
            shortest_path(&adjacency, x - 1, k - 1).unwrap() +
                shortest_path(&adjacency, k - 1, y - 1).unwrap()
        ).unwrap();
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

