const BIG: u64 = 0x4000_0000_0000_0000;

fn main() {
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    let n: usize = s.trim().parse().unwrap();
    let mut v: Vec<Vec<u64>> = Vec::with_capacity(n + 1);
    v.push(vec![]);
    for _ in 0..(n+1) {
        v.push(vec![BIG; n + 1]);
    }
    for _ in 0..(n-1) {
        let mut s = String::new();
        io::stdin().read_line(&mut s).unwrap();
        let t: Vec<u64> = s.trim()
                           .split_whitespace()
                           .map(|x| x.parse().unwrap())
                           .collect();
        v[t[0] as usize][t[1] as usize] = t[2];
        v[t[1] as usize][t[0] as usize] = t[2];
    }
    let (q, k) = {
        let mut s = String::new();
        io::stdin().read_line(&mut s).unwrap();
        let t: Vec<u64> = s.trim()
                           .split_whitespace()
                           .map(|x| x.parse().unwrap())
                           .collect();
        (t[0], t[1] as usize)
    };
    let mut done = vec![false; n + 1];
    let mut dist = vec![BIG; n + 1];
    done[k] = true;
    dist[k] = 0;
    let mut lastdone = k;
    loop {
        let mut nextdone = 0;
        let mut cost = BIG;
        for node in 1..(n+1) {
            if done[node] { continue; }
            if dist[lastdone] + v[lastdone][node] < dist[node] {
                dist[node] = dist[lastdone] + v[lastdone][node];
            }
            if dist[node] < cost {
                nextdone = node;
                cost = dist[node];
            }
        }
        if nextdone == 0 { break; }
        done[nextdone] = true;
        lastdone = nextdone;
    }
    for _ in 0..q {
        let (x, y) = {
            let mut s = String::new();
            io::stdin().read_line(&mut s).unwrap();
            let t: Vec<usize> = s.trim()
                               .split_whitespace()
                               .map(|x| x.parse().unwrap())
                               .collect();
            (t[0], t[1])
        };
        println!("{}", dist[x] + dist[y]);
    }
}

