#[derive(PartialEq, Eq, PartialOrd, Ord, Clone, Copy, Debug)]
enum Hyper<X> { NegInf, Real(X), Inf }
use Hyper::{Real, NegInf, Inf};
impl<X> Hyper<X> {
    fn unwrap(self) -> X { if let Hyper::Real(x) = self { x } else { panic!() } }
}
impl<X: Ring> std::ops::Add for Hyper<X> {
    type Output = Self;
    fn add(self, rhs: Hyper<X>) -> Hyper<X> {
        match (self, rhs) {
            (Real(x), Real(y)) => Real(x + y),
            (Inf, _) => Inf,
            (_, Inf) => Inf,
            _ => NegInf,
        }
    }
}
impl<X: Ring> std::ops::Sub for Hyper<X> {
    type Output = Self;
    fn sub(self, rhs: Hyper<X>) -> Hyper<X> { self + (-rhs) }
}
impl<X: Ring> std::ops::Neg for Hyper<X> {
    type Output = Self;
    fn neg(self) -> Hyper<X> {
        match self {
            Inf => NegInf,
            NegInf => Inf,
            Real(x) => Real(-x),
        }
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let mut g = vec![vec![]; n];
    for _ in 1..n {
        let a = sc.cin::<usize>() - 1;
        let b = sc.cin::<usize>() - 1;
        let c: i64 = sc.cin();
        g[a].push((b, c));
        g[b].push((a, c));
    }
    let q: usize = sc.cin();

    let k = sc.cin::<usize>() - 1;
    let mut memo = vec![Inf; n];
    memo[k] = Real(0);
    {
        let mut stack = vec![k];
        while let Some(u) = stack.pop() {
            for &(v, c) in g[u].iter() {
                if memo[v] >= memo[u] + Real(c) {
                    memo[v] = memo[u] + Real(c);
                    stack.push(v);
                }
            }
        }
    }

    for _ in 0..q {
        let a = sc.cin::<usize>() - 1;
        let b = sc.cin::<usize>() - 1;
        put!((memo[a] + memo[b]).unwrap());
    }
