fn main() {
   input! {
      n: usize,
      abc: [(usize, usize, usize); n-1],
      q: usize,
      k: usize,
      xy: [(usize, usize); q]
   }
   let mut to = vec![vec![]; n];
   for (a, b, c) in abc {
      to[a - 1].push((b - 1, c));
      to[b - 1].push((a - 1, c));
   }
   let mut d = vec![0; n];
   {
      let mut q = std::collections::VecDeque::new();
      q.push_back((k - 1, k - 1));
      while let Some((v, p)) = q.pop_front() {
         for &(u, c) in to[v].iter() {
            if u == p {
               continue;
            }
            d[u] = d[v] + c;
            q.push_back((u, v));
         }
      }
   }
   for (x, y) in xy {
      println!("{}", d[x - 1] + d[y - 1]);
   }
}

