#[derive(Eq, PartialEq, Clone, Debug)]
struct Rev<T>(pub T);

impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn main() {
    let n = get!(usize);
    let abc = get!(usize, usize, u64; n-1);
    let (q, k) = get!(usize, usize);
    let xy = get!(usize, usize; q);

    let g = {
        let mut g = vec![Vec::new(); n];
        for &(a, b, c) in &abc {
            g[a - 1].push((b - 1, c));
            g[b - 1].push((a - 1, c));
        }
        g
    };

    let mut costs_from_k = vec![u64::max_value() / 2; n];
    let mut que = Vec::new();
    que.push(Rev((0, k - 1)));
    while let Some(Rev((cost, p))) = que.pop() {
        costs_from_k[p] = cost;
        for &(to, c) in &g[p] {
            if costs_from_k[to] > cost + c {
                que.push(Rev((cost + c, to)));
            }
        }
    }

    for &(x, y) in &xy {
        println!("{}", costs_from_k[x - 1] + costs_from_k[y - 1]);
    }

}

struct Dikstra {
    dist: Vec<usize>,
    start: usize,
}
impl Dikstra {
    fn new(graph: &Vec<Vec<(usize, usize)>>, start: usize) -> Self {
        let mut d = Dikstra {
            dist: (0..graph.len()).map(|_|std::usize::MAX).collect(),
            start: start,
        };
        d.calc(graph);
        d
    }

    fn calc(&mut self, graph: &Vec<Vec<(usize, usize)>>) {
        //現在のnodeからの探索候補のヒープ
        let mut heap = std::collections::BinaryHeap::new();
        //初期化
        self.dist[self.start] = 0;
        heap.push((0, self.start));

        //未探索のnodeがなくなるまで隣接nodeへの最短距離を計算
        while let Some((cost, node)) = heap.pop() {

            if cost > self.dist[node] {
                continue;
            }
            //各辺について隣接先の重みを計算して更新
            for edge in &graph[node] {
                let next_cost = cost + edge.0;
                let next_node = edge.1;
                if next_cost < self.dist[next_node] {
                    heap.push((next_cost, next_node));
                    self.dist[next_node] = next_cost;
                }
            }
        }
    }

    fn distance(&self, i: usize) -> usize {
        self.dist[i]
    }
}

fn main() {
    input! {
        n:usize,
        nodes:[(usize,usize,usize);n-1],
        q:usize,
        k:usize1,
        query:[(usize,usize);q],
    };
    let mut graph = vec![vec![]; n];
    for node in nodes.into_iter() {
        let (x, y, c) = node;
        graph[x - 1].push((c as usize, y - 1));
        graph[y - 1].push((c as usize, x - 1));
    }
    let d = Dikstra::new(&graph, k);
    for (x, y) in query.into_iter() {
        println!("{}", d.distance(x - 1) + d.distance(y - 1));
    }
}

//input macros
#[macro_export]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}
#[macro_export]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};
    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}
#[macro_export]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };
    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };
    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };
    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };
    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

use proconio::input;
use proconio::marker::Usize1;
use std::collections::BinaryHeap;
fn main() {
    input! {
        n: usize,
        es: [(Usize1, Usize1, i64); n-1],
        q: usize, k: Usize1,
        qs: [(Usize1, Usize1); q]
    };
    let mut edges: Vec<Vec<(usize, i64)>> = vec![Vec::new(); n];
    for (a,b,c) in es {
        edges[a].push((b,c));
        edges[b].push((a,c));
    }
    let inf = std::i64::MAX;
    let mut d = vec![inf; n];
    let mut heap = BinaryHeap::new();
    d[k] = 0;
    heap.push(((0, k)));
    while  !heap.is_empty() {
        let (dist, i) = heap.pop().unwrap();
        if d[i] < -dist {
            continue;
        } else {
        for &(j, w) in &edges[i] {
            if d[j] > d[i] + w {
                d[j] = d[i] + w;
                heap.push(((-d[j], j)));
            } else {}
        }}
    }
    for (x,y) in qs {
        println!("{}", d[x]+d[y]);
    }
}

