fn solve(
    n: usize,
    abc: Vec<(usize, usize, usize)>,
    xy: Vec<(usize, usize)>,
    k: usize,
) -> Vec<usize> {
    let mut branches = vec![vec![]; n];
    for (a, b, c) in abc.into_iter() {
        branches[a - 1].push((b - 1, c));
        branches[b - 1].push((a - 1, c));
    }

    fn calc_dist_from_k(branches: Vec<Vec<(usize, usize)>>, k: usize, n: usize) -> Vec<usize> {
        let mut dist_from_k = vec![None; n];
        dist_from_k[k] = Some(0);
        let mut ps = vec![k];
        loop {
            let mut next_ps = vec![];
            for &p in &ps {
                let current_dist = dist_from_k[p].expect("A");
                for &(next_p, dist) in &branches[p] {
                    if dist_from_k[next_p].is_none() {
                        next_ps.push(next_p);
                        dist_from_k[next_p] = Some(current_dist + dist);
                    }
                }
            }
            if next_ps.is_empty() {
                break;
            }
            ps = next_ps;
        }
        let somes = dist_from_k.iter().filter(|&o| o.is_some()).count();
        eprintln!("{}/{}", somes, n);
        dist_from_k
            .into_iter()
            .map(|o| o.expect("not all"))
            .collect()
    }

    let dist_from_k = calc_dist_from_k(branches, k - 1, n);
    xy.into_iter()
        .map(|(x, y)| dist_from_k[x - 1] + dist_from_k[y - 1])
        .collect()
}


