/// predecessor subgraph by DFS
fn depth_first_tree(g: &Graph, source: usize) -> Graph {
    let mut visited = vec![false; g.order()];
    let mut stack = vec![];
    let mut tree = Graph::new(g.order());
    visited[source] = true;
    stack.push(source);
    while let Some(u) = stack.pop() {
        for e in &g[u] {
            let v = e.dst;
            if !visited[v] {
                visited[v] = true;
                stack.push(v);
                tree.add_directed_edge(u, v, e.weight);
            }
        }
    }
    tree
}

