use std::collections::VecDeque;

fn dijkstra(sn: usize, map: &Vec<Vec<(usize, i64)>>, dist: &mut Vec<i64>) {
    // cn, pn
    let mut q: VecDeque<(usize, usize)> = VecDeque::new();
    q.push_back((sn, 0));
    while !q.is_empty() {
        let cn = q.pop_front().unwrap();
        // println!("cn: {:?}", cn);
        for i in 0..map[cn.0].len() {
            let mi = map[cn.0][i];
            if mi.0 == cn.1 {
                continue;
            }
            if mi.1 + dist[cn.0] < dist[mi.0] {
                dist[mi.0] = mi.1 + dist[cn.0];
            }
            q.push_back((mi.0, cn.0));
        }
    }
}

fn main() {
    let n: usize = read();
    let mut map: Vec<Vec<(usize, i64)>> = vec![vec![]; n + 1];

    for _ in 0..n - 1 {
        let a: usize = read();
        let b: usize = read();
        let c: i64 = read();
        map[a].push((b, c));
        map[b].push((a, c));
    }
    let q: usize = read();
    let k: usize = read();
    let mut set: Vec<(usize, usize)> = vec![];
    for _ in 0..q {
        let x: usize = read();
        let y: usize = read();
        set.push((x, y));
    }
    let mut dist: Vec<i64> = vec![std::i64::MAX; n + 1];
    dist[k] = 0;
    dist[0] = 0;
    dijkstra(k, &map, &mut dist);
    // println!("{:?}", dist);
    for i in 0..q {
        let si = set[i];
        println!("{}", dist[si.0] + dist[si.1]);
    }
}

use std::io::*;
use std::str::FromStr;
use std::collections::BinaryHeap;

struct Graph {
    node: usize,
    directed: bool,
    graph: Vec<Vec<(usize, i64)>>,
}

impl Graph {
    fn new(n: usize, flag: bool) -> Graph {
        Graph { node: n, directed: flag, graph: vec![vec![]; n] }
    }

    fn add_edge(&mut self, start_node: usize, end_node: usize, cost: i64) -> () {
        self.graph[start_node].push((end_node, cost));
        if !self.directed { self.graph[end_node].push((start_node, cost)); }
    }
    fn dijkstra(&self, start_node: usize) -> Vec<i64> {
        let mut dist = vec![std::i64::MAX; self.node];
        dist[start_node] = 0;

        let mut queue: BinaryHeap<(i64, usize)> = BinaryHeap::new();
        queue.push((0, start_node));

        while !queue.is_empty() {
            let (min_dist, idx) = queue.pop().unwrap();
            if dist[idx] < -min_dist {
                continue;
            }
            for &(to, weight) in &self.graph[idx] {
                let cost_cand = dist[idx] + weight;
                if dist[to] > cost_cand {
                    dist[to] = cost_cand;
                    queue.push((-cost_cand, to));
                }
            }
        }
        dist
    }
    fn dijkstra_max(&self, start_node: usize) -> Vec<i64> {
        let mut dist = vec![0; self.node];
        dist[start_node] = 0;

        let mut queue: BinaryHeap<(i64, usize)> = BinaryHeap::new();
        queue.push((0, start_node));

        while !queue.is_empty() {
            let (max_dist, idx) = queue.pop().unwrap();
            if dist[idx] < -max_dist {
                continue;
            }
            for &(to, weight) in &self.graph[idx] {
                let cost_cand = dist[idx] + weight;
                if dist[to] < cost_cand {
                    dist[to] = cost_cand;
                    queue.push((-cost_cand, to));
                }
            }
        }
        dist
    }
}

