fn main() {
    let n: usize = read();

    let mut g = Graph::new(n+1, false);
    for _ in 0..n-1 {
        let a: usize = read();
        let b: usize = read();
        let c: i64 = read();
        g.add_edge(a, b, c);
    }

    let q: usize = read();
    let k: usize = read();

    for _ in 0..q {
        let x: usize = read();
        let y: usize = read();
        let v1 = g.dijkstra(x);
        let v2 = g.dijkstra(y);

        let ans = v1[k] + v2[k];
        println!("{}", ans);
    }
}

